window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["okuyan"]=[[{"n":1,"t":"Rahmân, Rahîm olan Allah’ın adıyla."},{"n":"2-4","t":"Hamd (övgü); Rahmân, Rahîm, hesap gününün sahibi, âlemlerin de Rabbi olan Allah içindir."},{"n":5,"t":"(Rabbimiz)! Yalnız sana kulluk ederiz ve yalnız senden yardım dileriz."},{"n":"6-7","t":"Bizi doğru yola, nimet verdiklerinin yoluna ulaştır; gazaba uğratılmışların ve sapkınların yoluna değil."}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":2,"t":"O kitap (Kur’an); onda asla şüphe yoktur. Muttakîler (duyarlı olanlar) için bir yol göstericidir."},{"n":3,"t":"Onlar gayba (bilinemeyenlere) inanır; namaz kılar ve kendilerine rızık olarak verdiklerimizden infak ederler (verirler)."},{"n":4,"t":"Sana indirilene ve senden önce indirilen(ler)e iman eder, ahiret gününe de kesin bir şekilde inanırlar."},{"n":5,"t":"İşte onlar Rableri tarafından doğru yol üzerindedir ve onlar kurtulanların ta kendileridir."},{"n":6,"t":"Şüphesiz ki kâfir olanları uyarsan da uyarmasan da onlar için birdir, iman etmezler."},{"n":7,"t":"(Bu nedenle) Allah onların kalplerini ve işitme (duyu)larını mühürlemiştir. Gözlerinde de (manevi) perde vardır; onlar için büyük bir azap vardır."},{"n":8,"t":"İnsanlardan öylesi vardır ki asla inanmadıkları hâlde “Allah’a ve ahiret gününe inandık.” derler."},{"n":9,"t":"Onlar Allah’ı ve müminleri (güya) aldatırlar. (Oysa) onlar kendilerinden başkasını aldatamazlar ve (bunun) farkına da varmazlar."},{"n":10,"t":"Kalplerinde bir hastalık vardır. Allah da (bu nedenlerle) onların hastalığını artırmıştır. Yalanlamaları sebebiyle onlar için elem verici bir azap vardır."},{"n":11,"t":"Onlara “Yeryüzünde bozgunculuk çıkarmayın!” dendiği zaman, “Biz ancak ıslah edicileriz.” derler."},{"n":12,"t":"Dikkat edin! Onlar bozguncuların ta kendileridir fakat farkına varmazlar."},{"n":13,"t":"Onlara “(Şu) insanların iman ettiği gibi siz de iman edin.” dendiği zaman “Biz hiç (o) beyinsizlerin iman ettiği gibi iman eder miyiz!” derler. Dikkat edin! Beyinsizler sadece kendileridir fakat (bunu bile) bilmezler."},{"n":14,"t":"(Bu münafıklar) müminlerle karşılaştıklarında “(Biz de) iman ettik.” derler. Şeytanları (kafadarları) ile baş başa kaldıklarındaysa “Biz sizinle beraberiz; biz onlarla (müminlerle) sadece alay ediyoruz.” derler."},{"n":15,"t":"(Oysa) Allah onlarla alay eder; (fakat) onlara fırsat vermektedir. Azgınlıkları içinde bocalayıp durmaktadırlar."},{"n":16,"t":"İşte onlar hidayet karşılığında sapkınlığı satın alanlardır. Onların (bu) ticareti kazançlı olmamış ve kendileri de doğru yola girmemiştir."},{"n":17,"t":"Onların (münafıkların) durumu, (karanlıkta) ateş tutuşturan kişi gibidir. (Ateş), etrafını aydınlattığında Allah onların aydınlığını hemen giderir ve onları karanlıklar içinde bırakır; (hiçbir şey) göremezler."},{"n":18,"t":"(Bu gibiler) sağırdır, dilsizdir, kördürler; onlar (gerçeğe) dönmezler."},{"n":19,"t":"Veya (onların durumu) gökten boşanan, içinde karanlıklar, gök gürültüsü ve şimşek bulunan sağanağa (tutulmuş kişilerin durumu) gibidir. Onlar (münafıklar), yıldırımlardan kaynaklanan ölüm korkusuyla parmaklarını kulaklarına tıkarlar. Allah kâfirleri çepeçevre kuşatandır."},{"n":20,"t":"(O esnada) şimşek, neredeyse gözlerini alacakmış (gibi çakar). (Şimşek) onlar için (etrafı) aydınlatınca orada (birazcık) yürürler; üzerlerine karanlık çökünce de oldukları yerde kala kalırlar. Allah dileseydi elbette onların işitme (duyu)larını ve gözlerini giderirdi. Şüphesiz ki Allah her şeye gücü yetendir."},{"n":21,"t":"Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize kulluk ediniz! Umulur ki böylece takvâlı (duyarlı) olursunuz."},{"n":22,"t":"O (Allah) ki yeri sizin için bir döşek, göğü de bir bina (güçlü bir tavan) yapmıştır. Gökten su indirip onunla size rızık olarak (çeşitli) meyveler çıkarmıştır. Artık (bu gerçeği) bilerek Allah’a ortaklar koşmayın!"},{"n":23,"t":"Kulumuza indirdiklerimizden şüphe içindeyseniz, onun (Kur’an’ın) benzeri herhangi bir sure getirin! Doğruysanız Allah’tan başka şahitlerinizi (yardımcılarınızı) da çağırın!"},{"n":24,"t":"(Bunu) yapamazsanız -ki asla yapamayacaksınız-, yakıtı insanlar ve taş olan, kâfirler için hazırlanmış (olacak) ateşten korunun!"},{"n":25,"t":"İman edip iyi işler yapanlara, altlarından ırmaklar akan cennetler olduğunu müjdele! Oradan (cennetlerdeki) herhangi bir meyveden kendilerine her ne zaman rızık verilirse, “Bu, bize daha önce verilmişti.” demiş (olacaklar)dır. Bu (rızık)lar onlara (dünyadakine) benzer olarak verilecektir. Onlar için orada (cennetlerde) tertemiz eşler de vardır ve onlar orada ebedî kalıcıdır."},{"n":26,"t":"Şüphesiz ki Allah (gerçeği açıklamak için) sivrisinek ve onun da ötesinde herhangi bir varlığı örnek vermekten çekinmez. İman edenler bunun (örneklerin) Rablerinden (gelen) bir gerçek olduğunu bilirler. Kâfir olanlar ise “Allah böyle örnek vermekle ne kastetmiştir ki?” derler. (Allah) onunla birçoğunu saptırır; birçoğunu da doğru yola ulaştırır. (Allah) bununla (verdiği örneklerle zaten) yoldan çıkmış olanlardan başkasını saptırmaz."},{"n":27,"t":"Allah’a verdikleri sözü sözleştikten sonra bozanlar, Allah’ın birleştirilmesini (gözetilmesini) emrettiği şeyleri kesenler (terk edenler) ve yeryüzünde bozgunculuk çıkaranlar var ya, işte onlar kaybedenlerin ta kendileridir."},{"n":28,"t":"Siz ölü (cansız)ken size hayat veren Allah’ı nasıl oluyor da inkâr ediyorsunuz! Sonra sizi öldürecek, sonra sizi (tekrar) diriltecek ve sonunda yalnızca O’na döndürüleceksiniz."},{"n":29,"t":"O, yerde ne varsa hepsini sizin için yaratmıştır. Sonra göğe yönelmiş, onu yedi kat olarak (yaratıp) düzenlemiştir. O her şeyi bilendir."},{"n":30,"t":"Hani Rabbin meleklere “Ben yeryüzünde bir halife (sorumlu) görevlendireceğim” demişti. Onlar “Biz seni hamdinle (övgüyle) tesbih ediyor (yüceltiyor) ve kutsallıkla anıyorken, yeryüzünde bozgunculuk çıkarmakta ve kan dökmekte olanı (insanı) mı halife görevlendiriyorsun?” demişlerdi. (Allah da onlara): “Şüphesiz ki sizin bilemeyeceğiniz şeyleri ben bilirim.” demişti."},{"n":31,"t":"(Allah) Âdem’e bütün isimleri öğretmiş, sonra onları meleklere yöneltip “Doğruysanız şunların isimlerini bana bildirin.” demişti."},{"n":32,"t":"(Melekler): “Sen yücesin; bize öğrettiklerinden başka bilgimiz yoktur. Yalnızca sen bilensin; doğru hüküm verensin.” demişlerdi."},{"n":33,"t":"(Allah:) “Ey Âdem! Onların (eşyanın) isimlerini onlara (meleklere) bildir.” demiş, (Âdem) isimlerini kendilerine bildirince “Ben size, şüphesiz ki göklerin ve yerin gaybını (bilinemeyenini) bilirim; açıkladıklarınızı da gizlemiş olduklarınızı da bilirim’ dememiş miydim?” demişti."},{"n":34,"t":"Hani meleklere “Âdem için (Allah’a) secde edin.” demiştik; onlar da hemen secde etmişti. İblis hariç. Yüz çevirmiş, kibirlenmiş, kâfirlerden olmuştu."},{"n":35,"t":"Şöyle demiştik: “Ey Âdem! Sen ve eşin şu bahçeye yerleşip, dilediğiniz yerden bolca yiyin! Şu ağaca yaklaşmayın; yoksa kaybedenlerden olursunuz.”"},{"n":36,"t":"(Ağaçtan yiyince) Şeytan onları(n ayaklarını) kaydırıp bulundukları yerden onları çıkarmıştı (çıkarılmalarına sebep olmuştu). (Bunun üzerine) “Bir kısmınız diğerine düşman olarak inin! Sizin için yeryüzünde (bahçe dışında) belirli bir süre kalma ve geçim imkânları vardır.” demiştik."},{"n":37,"t":"Âdem, Rabbinden birtakım (öğretici) sözler almıştı ve (Rabbi de) tevbesini kabul etmişti. Şüphesiz ki yalnızca O, tevbeleri çok kabul edendir, çok merhametlidir."},{"n":38,"t":"(Onlara) şöyle demiştik: “Hepiniz oradan (o bahçeden) inin! Benden size bir hidayet gelir de kim hidayetime uyarsa onlar için herhangi bir korku yoktur ve onlar üzülmeyecek de."},{"n":39,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar ateş halkıdır; onlar orada ebedî kalıcıdır.”"},{"n":40,"t":"Ey İsrailoğulları! Size vermiş olduğum nimet(ler)imi hatırlayın! Bana verdiğiniz sözü yerine getirin ki ben de size vadettiklerimi vereyim. Yalnızca benden korkun!"},{"n":41,"t":"Elinizdekini (Tevrat’ın aslını) doğrulayıcı olarak indirdiğime (Kur’an’a) iman edin! Sakın onu inkâr eden(ler)in öncüsü olmayın! Ayetlerimi az bir değer karşılığında satmayın! Yalnız bana karşı takvâlı (duyarlı) olun!"},{"n":42,"t":"Bilerek gerçeği batılla karıştırmayın, gerçeği gizlemeyin!"},{"n":43,"t":"Namazı kılın, zekâtı verin; boyun eğenlerle birlikte boyun eğin!"},{"n":44,"t":"(Ey İsrailoğulları)! Kitab’ı (Tevrat’ı) tilavet ettiğiniz (okuyup aktardığınız) hâlde kendinizi unutup iyiliği (başka) insanlara mı emrediyorsunuz! Akıl etmiyor musunuz?"},{"n":45,"t":"Sabır ve salât (fedakârlık) ile (Allah’tan) yardım isteyin! Şüphesiz ki o (sabır ve fedakârlık), saygı duyanlar dışındakilere ağır gelir."},{"n":46,"t":"Onlar, Rablerine kavuşacaklarına ve O’na döneceklerine kesin olarak iman eden kişilerdir."},{"n":47,"t":"Ey İsrailoğulları! Size vermiş olduğum nimet(ler)imi ve sizi (bir zamanlar) âlemlere (inançsızlara) üstün kıldığımı hatırlayın!"},{"n":48,"t":"Öyle bir güne karşı takvâlı (duyarlı) olun ki (o gün) kimse, kimseden hiçbir şey gideremez; onlardan şefaat kabul edilmez; kendilerinden fidye alınmaz; onlara yardım da edilmez."},{"n":49,"t":"Hani sizi işkencenin en kötüsüne süren ve oğullarınızı kestirip, kadınlarınızı sağ bırakmakta olan Firavun ailesinden kurtarmıştık. İşte bunda (size anlatılanlarda), Rabbinizden büyük bir imtihan vardır."},{"n":50,"t":"Hani biz sizin için denizi yarmıştık; sizi kurtarmış, Firavun’un ailesini (destekçilerini) de siz bakıyorken (denizde) boğmuştuk."},{"n":51,"t":"Hani (kendisine vahyetmek üzere) Musa ile kırk gece için sözleşmiştik. Sonra onun ardından, zalimler olarak buzağıyı (ilah) edinmiştiniz."},{"n":52,"t":"Sonra onun ardından şükredersiniz diye sizi affetmiştik."},{"n":53,"t":"Hani doğru yolu bulasınız diye Musa’ya Kitabı ve furkânı (doğruyu yanlıştan ayırma yeteneği) vermiştik."},{"n":54,"t":"Hani Musa kavmine şöyle demişti: “Ey kavmim! Şüphesiz ki siz, buzağıyı (ilah) edinmekle kendinize haksızlık ettiniz. Onun için, Yaratıcınıza tevbe edin de nefsinizi (kötü duygularınızı) öldürün! Böyle yapmanız Yaratıcınız katında sizin için hayırlı olandır. Böylece Allah tevbenizi kabul etmiş olur. Şüphesiz ki yalnızca O, tevbeleri çok kabul edendir, çok merhametlidir.”"},{"n":55,"t":"Hani “Ey Musa! Biz Allah’ı açıkça görünceye kadar sana asla inanmayız.” demiştiniz de bakıyorken sizi yıldırım yakalamıştı (çarpmıştı)."},{"n":56,"t":"Sonra (manevi) ölümünüzün ardından, şükredesiniz diye sizi (Vahiy ile) diriltmiştik."},{"n":57,"t":"Sizi bulutla gölgelendirmiş, size kudret helvası ile bıldırcın eti indirmiş (vermiş), “Size rızık olarak verdiğimiz temiz şeylerden yiyin!” (demiştik). (Emirlerimizi dinlememekle) onlar bize zulmetmemişlerdi; ancak kendilerine yazık etmişlerdi."},{"n":58,"t":"Hani (İsrailoğulları’na) şöyle demiştik: “Şu şehre girip (yerleşin); onun (nimetlerinden) dilediğiniz gibi bolca yiyip (yararlanın)! Kapıdan eğilerek (saygıyla) girin ve “Hıttah! (Bizi bağışla!)” deyin ki sizin için hatalarınızı bağışlayalım. Güzel davrananların (ödülünü) ileride daha da artıracağız.”"},{"n":59,"t":"(İçlerinden bazı) zalimler, kendilerinden (söylemeleri) istenen sözü başka bir sözle değiştirmişlerdi. Biz de yoldan çıkmaları nedeniyle üzerlerine gökten bir azap göndermiştik."},{"n":60,"t":"Hani Musa, kavmi için su isteyince (ona) “Asanla taşa vur!” demiştik. Hemen ondan on iki pınar fışkırmıştı. Her kabile de elbette içeceği yeri bilmişti. (Onlara şöyle demiştik:) “Allah’ın (yarattığı) rızkından yiyin, için! Yeryüzünde bozguncular olarak karışıklık çıkarmayın!”"},{"n":61,"t":"Hani siz (verilen nimetlere karşılık) şöyle demiştiniz: “Ey Musa! Tek (çeşit) yemeğe sabredemeyiz. Bizim için Rabbine dua et de yerin yetiştirdiği şeylerden; sebzesinden, salatalığından (acurundan), sarımsağından, mercimeğinden ve soğanından bize çıkarsın (lütfetsin)!” (Musa ise) “Daha iyiyi daha düşük ile değiştirmek mi istiyorsunuz? Şehre inin; şüphesiz ki istedikleriniz sizin için (orada) var!” demişti. (Bundan sonra) üzerlerine alçaklık ve çaresizlik damgası vurulmuş ve Allah’ın gazabına uğramışlardı. Bunun sebebi, Allah’ın ayetlerini inkâr etmeleri ve haksız olarak peygamberleri öldürmeleriydi. Bütün bunlar, isyana devam etmeleri ve haddi aşmış olmaları sebebiyledir."},{"n":62,"t":"Şüphesiz ki iman edenler, yahudi olanlar, sabiiler ve hristiyanlar(dan) kim Allah’a ve ahiret gününe iman edip iyi işler yaparsa, onlar için Rableri katında ödül(ler)i vardır. Onlara herhangi bir korku yoktur; onlar üzülmeyecek de."},{"n":63,"t":"Hani sizden sağlam bir söz almış, üzerinize (Sînâ) Dağı(nı âdeta) kaldırmıştık. (Onlara) “Size verdiğimizi (Kitabı) kuvvetle alın (ona sıkıca tutunun) ve içinde olanı hatırlayın ki takvâlı olabilesiniz.” (demiştik)."},{"n":64,"t":"Ondan sonra sözünüzden dönmüştünüz. Allah’ın iyiliği ve merhameti sizin üzerinize olmasaydı, şüphesiz ki zarara uğrayanlardan olurdunuz."},{"n":65,"t":"İçinizden cumartesi günü (avlanma yasağını) çiğneyenleri ve bu yüzden kendilerine “Aşağılık maymunlar (gibi) olun!” dediğimizi elbette bilmektesiniz."},{"n":66,"t":"Bunu öndekilere (onları görenlere) ve arkalarındakilere (ibretlik) bir ceza, muttakîler (duyarlı olanlar) için de bir öğüt kılmıştık."},{"n":67,"t":"Hani Musa, kavmine “Şüphesiz ki Allah herhangi bir inek kesmenizi emrediyor.” demişti. (Onlar) “Bizimle alay mı ediyorsun?” deyince, o da “Cahillerden olmaktan Allah’a sığınırım.” demişti."},{"n":68,"t":"(Onlar) “Bizim adımıza Rabbine dua et de onun (özelliklerinin) ne olduğunu bize açıklasın.” (Musa da) “Allah diyor ki o, ne yaşlı ne de körpe, ikisi arasında bir inektir. Size emredileni hemen yapın.” demişti."},{"n":69,"t":"(Onlar) “Bizim adımıza Rabbine dua et; bize onun renginin nasıl olduğunu açıklasın.” demişlerdi. (Musa da) “Allah diyor ki o, bakanlara huzur veren parlak sarı renkli bir inektir.” demişti."},{"n":70,"t":"(Onlar) “Bizim adımıza Rabbine dua et de onun (özelliklerinin) ne olduğunu bize açıklasın; (nasıl) bir inek (keseceğimizi iyice) karıştırdık. inşallah biz emredileni yapma yolunu buluruz.” demişlerdi."},{"n":71,"t":"(Musa da) “Allah diyor ki o, henüz boyunduruk altına alınmayan, toprak sürmeyen, ekin sulamayan, serbest dolaşan, renginde hiç alacası bulunmayan bir inektir.” demişti. (Bunun üzerine onlar) “İşte şimdi gerçeği getirdin (tam olarak açıkladın)!” cevabını vermişler ve hemen (onu bulup) kesmişlerdi ama neredeyse yapamayacaklardı."},{"n":72,"t":"Hani siz bir kişiyi öldürmüştünüz de onun hakkında birbirinizle atışmıştınız. (Oysa) Allah gizlemekte olduğunuzu (ortaya) çıkarıcıdır."},{"n":73,"t":"“Şimdi ona (öldürülen kişiye, kesilen ineğin) bir parçasıyla vurun.” demiştik. Böylece Allah ölüleri diriltir ve akıl edesiniz diye size delillerini gösterir."},{"n":74,"t":"Bunlardan sonra kalpleriniz (yine) katılaşmıştı. Artık onlar (kalpleriniz) taş gibi hatta daha da katıdır. Çünkü taşlardan öylesi var ki içinden ırmaklar fışkırır. Öylesi de var ki yarılır da ondan su çıkar. Bir kısmı da Allah’a saygı nedeniyle (yukardan aşağı) iner. Allah yapmakta olduklarınızdan asla habersiz değildir."},{"n":75,"t":"Onların (kitap ehlinin) size inanacaklarını mı umuyorsunuz! Oysa onlardan bir grup, Allah’ın kelamını duyarlar da iyice anladıktan sonra bilerek onu tahrif ederler(di)."},{"n":76,"t":"(Bunlar) müminlerle karşılaştıkları zaman “(Biz de) iman ettik.” derler. Birbirleriyle baş başa kaldıklarında “Allah’ın size açtıklarını (Tevrat’taki bilgileri), Rabbiniz katında aleyhinize delil getirmeleri için mi onlara anlatıyorsunuz? (Bunları) akıl etmiyor musunuz?” derler."},{"n":77,"t":"Bilmezler mi ki Allah şüphesiz ki onların gizlediklerini de açıkladıklarını da bilmektedir."},{"n":78,"t":"İçlerinde birtakım ümmiler vardır ki kuruntular dışında Kitab’ı (Tevrat’ı) bilmezler. Onlar zandan başka bir şeyde bulunmuyorlar."},{"n":79,"t":"Kitab'ı (Tevrat’ı) kendi elleriyle yazıp sonra onu az bir bedel karşılığında satmak için “Bu, Allah katındandır.” diyenlere yazıklar olsun! Elleriyle yazdıkları nedeniyle onların vay hâllerine! Kazandıkları nedeniyle onların vay hâllerine!"},{"n":80,"t":"(Kitap ehlinden bazıları) “Sayılı birkaç gün hariç, bize ateş dokunmayacaktır.” demişlerdi. (Onlara) de ki: “Siz Allah katından bir söz mü aldınız –ki Allah asla sözünden caymaz– yoksa Allah hakkında bilmediğiniz şeyleri mi söylüyorsunuz?”"},{"n":81,"t":"Hayır! Kim bir kötülük işler de kötülüğü kendisini çepeçevre kuşatırsa, işte o kişiler ateş halkıdır. Onlar orada ebedî kalacaklardır."},{"n":82,"t":"İman edip iyi işler yapanlara gelince onlar cennet halkıdır. Onlar da orada ebedî kalacaklardır."},{"n":83,"t":"Hani biz, İsrailoğulları’ndan “Allah’tan başkasına kulluk etmeyeceksiniz; ana babaya güzel davranacaksınız; yakınlara, yetimlere ve yoksullara (iyilik yapacaksınız)” diye söz almıştık. İnsanlara güzel söz söyleyin; namazı kılın ve zekâtı verin! Sonunda azınız hariç, yüz çevirerek dönüp gitmiştiniz."},{"n":84,"t":"Hani birbirinizin kanlarını dökmeyeceğinize, birbirinizi yurtlarınızdan çıkarmayacağınıza dair sizden söz almıştık. Sonunda siz de şahit olarak (bunları) kabul etmiştiniz."},{"n":85,"t":"Ardından siz öyle kimselersiniz ki birbirinizi öldürüyor, aranızdan bir grubu yurtlarından çıkarıyor, günahta ve düşmanlıkta onlara karşı birbirinize arka çıkıyorsunuz. Onları yurtlarından çıkarmak size haram olduğu hâlde (hem çıkarıyor hem de) size esirler olarak geldiklerinde fidye veri(p onları kurtarı)yorsunuz. Yoksa siz Kitab'ın (Tevrat’ın) bir kısmına inanıp bir kısmını inkâr mı ediyorsunuz? Böyle davrananlarınızın cezası, dünya hayatında rezillikten başka nedir ki! Kıyamet gününde ise en şiddetli azaba çarptırılacaklardır. Allah yapmakta olduklarınızdan asla habersiz değildir."},{"n":86,"t":"İşte onlar, ahirete karşılık dünya hayatını satın alanlardır. (Bu yüzden) azapları hafifletilmeyecek ve kendilerine yardım edilmeyecektir."},{"n":87,"t":"Yemin olsun ki biz Musa’ya Kitabı vermiştik. Ondan sonra birbiri ardınca elçiler göndermiştik. Meryem oğlu İsa’ya da apaçık deliller vermiş, onu Kutsal Ruh (Cebrail) ile desteklemiştik. Nefislerinizin arzulamadığı şeyleri söyleyen bir elçi size her geldiğinde ona karşı kibirlenmiştiniz. (Elçilerden) bir kısmını yalanlıyor; bir kısmını öldürüyordunuz."},{"n":88,"t":"(Yahudiler) “Kalplerimiz perdelidir.” demişlerdi. Hayır! Küfür ve inkârları sebebiyle Allah onlara lanet etmiştir. Ne kadar da azı inanır!"},{"n":89,"t":"Daha önce kâfirlere karşı zafer isterlerken, kendilerine Allah katından ellerindeki (Tevrat’ı) doğrulayan bir kitap (Kur’an) ulaşıp da (Tevrat’tan) bildikleri gerçekler kendilerine gelince onu inkâr etmişlerdi. (İşte) Allah’ın laneti böylesi kâfirlerin (üzerine)dir."},{"n":90,"t":"Allah’ın, kullarından dilediğine (peygamberlik) vermesini kıskandıkları için Allah’ın indirdiğini (Kur’an’ı) inkâr ederek kendilerini (alçak bir şeye) satmaları ne kötü bir şeydir! Böylece onlar, gazap üstüne gazaba uğramışlardı. Ayrıca o kâfirler için küçük düşürücü bir azap vardır."},{"n":91,"t":"Kendilerine “Allah’ın indirdiğine iman edin!” denince, “Biz sadece bize indirilene (Tevrat’a) inanırız.” derler ve ondan başkasını inkâr ederler. (Oysa) o (Kur’an), kendilerinde bulunanı (Tevrat’ın aslını) doğrulayıcı gerçektir. (Onlara) de ki: “Siz inanıyor idiyseniz daha önce Allah’ın peygamberlerini neden öldürüyordunuz?”"},{"n":92,"t":"Yemin olsun ki Musa, size apaçık deliller getirmişti. Sonra onun ardından, zalimler olarak buzağıyı (ilah) edinmiştiniz."},{"n":93,"t":"Hani sizden sağlam bir söz almış, üzerinize (Sînâ) Dağı(nı âdeta) kaldırmıştık. (Onlara) “Size verdiğimizi kuvvetle alın (ona sıkıca tutunun); (ondaki gerçekleri) dinleyin!” (demiştik). Onlar ise “İşittik ve isyan ettik.” demişlerdi. İnkârları sebebiyle kalplerine buzağı(ya tapma sevgisi) içirilmişti (doldurulmuştu). De ki: “(Böyle) inanıyorsanız, inancınız size ne kötü şeyler emrediyor!”"},{"n":94,"t":"(Onlara) de ki: “Ahiret yurdu Allah katında diğer insanlara değil de yalnızca size aitse (ve bu konuda) doğruysanız ölümü isteyin (bakalım)!”"},{"n":95,"t":"Onlar, kendi elleriyle önceden yaptıkları işler (günahlar) sebebiyle ölümü asla istemeyecektir. Allah zalimleri iyi bilendir."},{"n":96,"t":"Şüphesiz ki sen onları insanların (dünya) hayatına en düşkünü olarak bulursun; hatta şirk koşanlardan bile. Her biri bin sene yaşatılmak ister. Oysa (o kadar) yaşatılması (kimseyi) azaptan asla uzaklaştırmaz. Allah yapmakta olduklarını görendir."},{"n":97,"t":"De ki: “Kim Cebrail’e düşmansa (şunu iyi bilsin ki), Allah’ın izniyle onu (Kur’an’ı) senin kalbine, kendisinden önce gelen (kitapların aslını) doğrulayıcı, bir rehber ve müminler için bir müjde olarak o indirmiştir."},{"n":98,"t":"Kim Allah’a, meleklerine, elçilerine, Cebrail’e ve Mikail’e düşman olursa, (bilsin ki) Allah da kâfirlerin düşmanıdır.”"},{"n":99,"t":"Yemin olsun ki sana apaçık ayetler indirdik. Onları yoldan çıkanlardan başkası inkâr etmez."},{"n":100,"t":"Ne zaman onlar (Allah’a) bir söz vermişlerse, içlerinden bir grup onu bozmadı mı? Gerçekte onların çoğu iman etmez."},{"n":101,"t":"Allah tarafından kendilerine, beraberlerindekini doğrulayıcı bir elçi gelince, kitap ehlinden bir grup, sanki Allah’ın kitabını bilmiyormuş gibi onu arkalarına attılar."},{"n":102,"t":"Onlar, Süleyman’ın hükümdarlığı hakkında şeytanların (uydurup) söylediklerine uymuşlardı. (Oysa) Süleyman, (büyü yapıp) kâfir olmamıştı. Ancak şeytan (ruhlu insan)lar kâfir olmuşlardı. (Çünkü) onlar, insanlara büyü ve Babil’de Harut ile Marut isimli iki hükümdara indirileni öğretiyorlardı. (O iki hükümdar): “Biz sadece bir imtihanız; sakın kâfir olmayın!” demeden kimseye (bir şey) öğretmezlerdi. Onlar, o ikisinden (Harut ile Marut’tan), kişi ile eşinin arasını açacak şeyleri öğreniyorlardı. Oysa onlar (büyücüler), Allah’ın izni olmadan kimseye zarar veremezler(di). Onlar ise, kendilerine zarar veren ve yarar sağlamayan şeyleri öğreniyorlardı. Yemin olsun ki (büyüyü) satın alanların ahiretten payı olmadığını çok iyi bilmektelerdi. Karşılığında kendilerini sattıkları şey ne kötüdür! Keşke bunu bilselerdi!"},{"n":103,"t":"İman edip takvâlı (duyarlı) olsalardı, şüphesiz ki Allah tarafından verilecek ödül hayırlı olacaktı. Keşke bunu bilselerdi!"},{"n":104,"t":"Ey iman edenler! ‘Râ‘inâ!’ (bize çobanlık et) demeyin, ‘Unzurnâ!’ (bizi gözet) deyin ve (söylenenleri) dinleyin! kâfirler için elem verici bir azap vardır."},{"n":105,"t":"Kitap ehlinden ve müşriklerden nankörlük yapanlar, Rabbinizden size herhangi bir iyilik indirilmesini istemezler. Allah rahmetini dilediğine (layık olana) verir. Allah büyük lütuf sahibidir."},{"n":106,"t":"Biz bir ayetten her neyi nesh eder veya unutturursak daha iyisini veya benzerini getiririz. Bilmez misin ki Allah her şeye gücü yetendir."},{"n":107,"t":"Göklerin ve yerin otoritesinin yalnızca Allah’a ait olduğunu bilmez misin? Sizin için Allah’a rağmen dost da yardımcı da yoktur."},{"n":108,"t":"Yoksa siz de daha önce Musa’ya sorulduğu gibi elçinize sorular mı sormak istiyorsunuz? Kim küfrü imana değişirse, elbette doğru yoldan sapmış olur."},{"n":109,"t":"Kitap ehlinden çoğu, gerçek kendilerine apaçık belli olduktan sonra, içlerindeki kıskançlıktan ötürü, sizi imanınızdan vazgeçirip küfre döndürmek istediler. (Yine de) siz Allah onlar hakkındaki emrini getirinceye kadar (onları) affedin; hoşgörün! Şüphesiz ki Allah her şeye gücü yetendir."},{"n":110,"t":"Namazı kılın, zekâtı verin! Kendiniz için (önceden) ne tür bir iyilik sunarsanız, Allah katında onu bulacaksınız. Şüphesiz ki Allah yapmakta olduklarınızı görendir."},{"n":111,"t":"(Kitap ehli:) “Yahudi olanlar veya hristiyanlar hariç kimse asla cennete giremeyecek.” demişlerdi. İşte şu (iddiaları), kendi kuruntularıdır. De ki: “Doğruysanız delilinizi getirin!”"},{"n":112,"t":"Aksine kim güzel davranarak yüzünü (benliğini) Allah’a teslim ederse, onun ödülü Rabbinin katındadır. Onlara herhangi bir korku yoktur; onlar üzülmeyecek de."},{"n":113,"t":"Kitabı (Tevrat ve İncil’i) tilavet etmekte (okuyup aktarmakta) oldukları hâlde, yahudiler “Hristiyanlar, herhangi bir şey üzerinde (doğru yolda) değildir.” demişlerdi. Hristiyanlar da “Yahudiler, herhangi bir şey üzerinde (doğru yolda) değildir.” demişlerdi. (Kitabı) bilmeyenler de (birbirleri hakkında) tıpkı onların dediklerini söylemişlerdi. Allah, onların anlaşmazlığa düştükleri şey hakkında kıyamet günü aralarında hüküm verecektir."},{"n":114,"t":"Allah’ın mescitlerinde O’nun adının anılmasına engel olan ve onların (mescitlerin) harap olması için çalışandan daha zalim kim olabilir ki! Onların oralara ancak korkarak girebilmeleri gerekir. Onlar için dünyada rezillik vardır; onlar için ahirette de büyük bir azap vardır."},{"n":115,"t":"Doğu da Batı da yalnızca Allah’a aittir. Nereye dönerseniz Allah’ın yüzü (rızası) oradadır. Şüphesiz ki Allah (imkânları) geniş olandır, bilendir."},{"n":116,"t":"Onlar “Allah çocuk edindi.” dediler. (Haşa)! O yücedir. Aksine göklerde ve yerde olanların hepsi, yalnızca O’na (Allah’a) aittir; hepsi yalnızca O’na boyun eğenlerdir."},{"n":117,"t":"(O), göklerin ve yerin yoktan yaratıcısıdır. Bir işe hükmettiği zaman ona sadece “Ol!” der; o da hemen olmaya başlar."},{"n":118,"t":"(Gerçekleri) bilmeyenler şöyle demişlerdi: “Allah bizimle konuşmalı veya bize bir delil gelmeli değil miydi?” Öncekiler de tıpkı onların dediklerini demişlerdi. Kalpleri (akılları nasıl da) birbirine benzedi! Kesin bir şekilde inananlara ayetleri elbette apaçık ortaya koyduk."},{"n":119,"t":"Şüphesiz ki biz seni bir amaç ile müjdeleyici ve uyarıcı olarak gönderdik. Sen cehennem halkından sorumlu tutulmayacaksın."},{"n":120,"t":"Milletlerine (dinlerine) uyuncaya kadar yahudiler de hristiyanlar da senden asla razı olmayacaklardır. De ki: “Şüphesiz ki Allah’ın rehberliği, gerçek rehberliktir.” Sana gelen bilgiden sonra onların arzularına uyarsan, Allah’tan (gelecek azaba karşı) senin için herhangi bir dost ve yardımcı olmayacaktır."},{"n":121,"t":"Kendilerine kitap verdiklerimiz(den bazısı) onu, tam olarak (hakkını gözeterek) tilavet ederler (okuyup aktarırlar). (Çünkü) onlar, ona iman ederler. Onu inkâr edenlere gelince, işte asıl kaybedenler onlardır."},{"n":122,"t":"Ey İsrailoğulları! Size verdiğim nimet(ler)imi ve sizi (bir zamanlar) âlemlere (inançsızlara) üstün kıldığımı hatırlayın!"},{"n":123,"t":"Öyle bir güne karşı takvâlı (duyarlı) olun ki (o gün) kimse kimseden hiçbir şey gideremez; kimseden fidye kabul edilmez; kimseye şefaat yarar sağlamaz; onlara yardım da edilmez."},{"n":124,"t":"Hani Rabbi, İbrahim’i birtakım sözlerle sınamıştı; o da onları tam olarak yerine getirmişti. (Allah): “Ben seni insanlara önder yapacağım.” demişti. (İbrahim) “Soyumdan da (önderler yap, ya Rabbi)!” deyince, (Allah) “Sözüm zalimlere ermez (onlar için söz vermem).” demişti."},{"n":125,"t":"Hani Evi (Kâbe’yi) insanlara toplanma yeri ve güven (mekânı) kılmıştık. Siz de İbrahim’in makamından bir namaz yeri edinin! İbrahim’e ve İsmail’e “Tavaf edenler, ibadete kapananlar, rükû ve secde edenler için Evimi temiz tutun!” diye emretmiştik."},{"n":126,"t":"Hani İbrahim de demişti ki: “Rabbim! Burayı güvenli bir şehir yap; halkından Allah’a ve ahiret gününe inananları çeşitli meyvelerle rızıklandır!” (Allah da) şöyle demişti: “Kim inkâr ederse onu az bir süre yararlandırır, sonra onu cehennem azabına sürüklerim. Ne kötü varış yeridir (orası)!”"},{"n":127,"t":"Hani İbrahim ve İsmail, o Ev’in (Kâbe’nin) temellerini yükseltiyor (ve şöyle dua ediyorlardı:) “Rabbimiz! Bunu bizden kabul et! Şüphesiz ki yalnızca sen duyansın; bilensin."},{"n":128,"t":"Rabbimiz! Bizi sana boyun eğenler(den) kıl; neslimizden de boyun eğen bir ümmet (kıl)! Bize ibadet usullerimizi göster; tevbemizi kabul et! Şüphesiz ki yalnızca sen tevbeleri çok kabul edensin; çok merhametlisin."},{"n":129,"t":"Rabbimiz! Onlara, içlerinden senin ayetlerini kendilerine tilavet edecek (okuyup aktaracak), onlara Kitap ve hikmeti (doğru hüküm verme yeteneğini) öğretecek, onları arındıracak bir elçi gönder! Şüphesiz ki yalnızca sen güçlü olansın; doğru hüküm verensin.”"},{"n":130,"t":"Kendini bilmezlerden başka kim İbrahim’in dininden yüz çevirir ki! Yemin olsun ki biz onu dünyada (elçi) seçmiştik; şüphesiz ki o, ahirette de iyilerden (olacak)tır."},{"n":131,"t":"Hani Rabbi ona “Teslim ol!” demişti; o da “Âlemlerin Rabbine teslim oldum.” cevabını vermişti."},{"n":132,"t":"İbrahim bunu kendi oğullarına da vasiyet etmişti. Yakup da “Ey yavrularım! Allah sizin için bu dini (İslam’ı) seçti. Sadece müslümanlar olarak ölün!” (demişti)."},{"n":133,"t":"Yakup’a ölüm geldiği zaman siz orada mıydınız yoksa! O zaman (Yakup), oğullarına “Benden sonra neye (kime) kulluk edeceksiniz?” demişti. Onlar da: “Senin ve ataların İbrahim, İsmail ve İshak’ın ilahı olan tek Allah’a kulluk edeceğiz; biz yalnızca O’na teslim olmuşuzdur.” demişlerdi."},{"n":134,"t":"Onlar bir ümmetti, elbette gelip geçti(ler). Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorguya çekilmezsiniz."},{"n":135,"t":"(Kitap ehli olanlar:) “Yahudi veya hristiyan olun ki doğru yolu bulasınız.” demişlerdi. De ki: “Hayır! (Biz), hanîf (Allah’ı birleyen) olarak İbrahim’in milletine (dinine uyarız). O, müşriklerden değildi.”"},{"n":136,"t":"(Onlara) şöyle deyin: “Biz Allah’a, bize indirilene; İbrahim’e, İsmail’e, İshak’a, Yakup’a ve (onların) torunlar(ın)a indirilene; Rableri tarafından Musa’ya ve İsa’ya verilenlere, (ayrıca) diğer peygamberlere verilenlere inandık. Onlardan hiçbiri arasında fark gözetmeyiz. Biz yalnızca O’na (Allah’a) teslim olanlarız.”"},{"n":137,"t":"Onlar da sizin inandığınız gibi inanırlarsa doğru yolu bulmuş olurlar. Dönerlerse, yalnızca anlaşmazlık içine düşmüş olurlar. Onlara karşı Allah sana yeter. O, duyandır, bilendir."},{"n":138,"t":"Allah’ın boyası (ile boyanın)! Allah’ın boyasından daha güzel boyası olan kimmiş! Biz yalnızca O’na kulluk edicileriz."},{"n":139,"t":"De ki: “O, bizim de Rabbimiz, sizin de Rabbiniz olduğu hâlde Allah hakkında bizimle tartışıyor musunuz? Bizim yaptıklarımız bize, sizin yaptıklarınız da size aittir. Biz yalnızca O’na gönülden bağlananlarız.”"},{"n":140,"t":"Yoksa siz İbrahim, İsmail, İshak, Yakup ve (onların) torunlar(ın)ın yahudi veya hristiyan olduklarını mı söylüyorsunuz! De ki: “Siz mi daha iyi bilirsiniz, yoksa Allah mı?” Allah tarafından kendisine (bildirilmiş) bir şahitliği gizleyenden daha zalim kim olabilir ki! Allah yaptıklarınızdan asla habersiz değildir."},{"n":141,"t":"Onlar bir ümmetti, elbette gelip geçti(ler). Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorguya çekilmezsiniz."},{"n":142,"t":"İnsanlardan bazı beyinsizler “Yönelmekte oldukları kıblelerinden onları (Müslümanları) çeviren nedir?” diyecekler. De ki: “Doğu da Batı da yalnızca Allah’a aittir. Dileyeni (layık gördüğünü) doğru yola ulaştırır.”"},{"n":143,"t":"İşte böylece sizin insanlığa şahitler olmanız, Elçinin de size şahit olması için sizi dengeli bir ümmet kıldık. Senin üzerinde bulunduğun (kıble edindiğin Kâbe’yi) biz ancak Elçi'ye uyanı, topukları üzerinde geri dönenden bil(dir)memiz (ortaya çıkarmamız) için kıble yaptık. Bu, Allah’ın doğru yola ulaştırdıklarından başkasına elbette ağır gelir. Allah sizin imanınızı asla boşa çıkaracak değildir. Şüphesiz ki Allah insanlara karşı çok şefkatlidir, çok merhametlidir."},{"n":144,"t":"Yüzünü göğe çevirişini (haber beklediğini) elbette görüyoruz. Elbette seni memnun olacağın bir kıbleye döndürüyoruz. Yüzünü Mescid-i Haram tarafına çevir! Siz de nerede olursanız olun, (namazda) yüzlerinizi onun tarafına çevirin! Şüphesiz ki kendilerine kitap verilmiş olanlar, onun Rablerinden (gelen) gerçek olduğunu bilirler. Allah onların yaptıklarından habersiz değildir."},{"n":145,"t":"Şüphesiz ki kendilerine kitap verilmiş olanlara her türlü delili getirsen de onlar kıblene dönmezler. Sen onların kıblesine asla uyacak değilsin. Onlar da birbirlerinin kıblesine uymazlar. Sana gelen bilgiden sonra onların arzularına uyacak olursan, işte o zaman zalimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz onu (kıbleyi) kendi çocuklarını tanıdıkları gibi tanırlar. Şüphesiz ki onlardan bir grup, bilerek hakikati gizlemektedir."},{"n":147,"t":"Gerçek olan, Rabbinden (gelen)dir. Sakın şüphelenenlerden olma!"},{"n":148,"t":"Herkesin O’nun (Allah’ın yönlendirmesiyle) yöneldiği bir yönü vardır. Siz iyiliklerde yarışın! Nerede olursanız olun, Allah hepinizi bir araya getirecektir. Şüphesiz ki Allah her şeye gücü yetendir."},{"n":149,"t":"Nereden (yola) çıkarsan çık, (namazda) yüzünü Mescid-i Haram tarafına çevir! Şüphesiz ki bu (emir), Rabbinden (sana gelen bir gerçek)tir. Allah yapmakta olduklarınızdan asla habersiz değildir."},{"n":150,"t":"Nereden (yola) çıkarsan çık, (namazda) yüzünü Mescid-i Haram tarafına çevir! Siz de nerede olursanız olun, (namazda) yüzlerinizi onun tarafına çevirin ki aralarından haksızlık edenler (inatçılar) hariç, insanların aleyhinizde (kullanabilecekleri) bir delili bulunmasın! Sakın onlardan korkmayın! Yalnız bana saygı duyun! Böylece size olan nimetimi tamamlayayım da doğru yolu bulasınız."},{"n":151,"t":"Nitekim size kendi içinizden, ayetlerimizi tilavet eden (okuyup aktaran), sizi (kötülüklerden) arındıran, size Kitabı ve hikmeti (doğru hüküm verme yeteneğini) bildiren, bilmediklerinizi size öğreten bir elçi gönderdik."},{"n":152,"t":"Siz beni (ibadetle) hatırlayın ki ben de sizi (bağışlama ile) anayım. Benim için şükredin; bana nankörlük etmeyin!"},{"n":153,"t":"Ey iman edenler! Sabır ve salât (fedakârlık) ile (Allah’tan) yardım isteyin! Şüphesiz ki Allah sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenlere ‘ölüler’ demeyin! Aslında onlar diridir ancak siz anlayamazsınız."},{"n":155,"t":"Şüphesiz ki sizi biraz korku ve açlık; (ayrıca) mallardan, canlardan ve ürünlerden azaltma (fakirlik) ile imtihan edeceğiz. Sabredenleri müjdele!"},{"n":156,"t":"Onlar (sabredenler), kendilerine bir musibet geldiği zaman “Biz Allah’a aidiz ve biz elbette yalnızca O’na döneceğiz” derler."},{"n":157,"t":"İşte Rablerinden salavat (destekler) ve merhamet hep onların üzerinedir; doğru yolu bulanlar da onlardır."},{"n":158,"t":"Şüphesiz ki Safa ile Merve Allah’ın sembollerindendir. Kim Ev’i (Kâbe’yi) hacceder veya umre yaparsa, o ikisini (Safa ve Merve’yi) tavaf etmesinde kendisine herhangi bir vebal yoktur. Kim gönüllü olarak bir iyilik yaparsa, şüphesiz ki Allah şükre çok karşılık verendir, bilendir."},{"n":159,"t":"Kitapta insanlara açıkça gösterdikten sonra indirdiğimiz apaçık delilleri ve hidayeti gizleyenlere hem Allah hem de bütün lanet ediciler lanet eder."},{"n":160,"t":"Ancak tevbe edip kendilerini düzeltenler ve (gerçeği) açıkça ortaya koyanlar başkadır. Ben onların tevbelerini kabul ederim. Ben tevbeleri çok kabul edenim; çok merhametli olanım."},{"n":161,"t":"Şüphesiz ki kâfir olanlar ve kâfir olarak ölenlere gelince, işte Allah’ın, meleklerin ve bütün insanların laneti onların üzerinedir."},{"n":162,"t":"Onlar orada (lanet içinde) ebedî kalıcıdır. Azapları hafifletilmez ve onlara bakılmaz."},{"n":163,"t":"İlahınız tek bir ilahtır. O’ndan başka ilah yoktur. Merhametin kaynağıdır, merhametlidir."},{"n":164,"t":"Şüphesiz ki göklerin ve yerin yaratılmasında, gecenin ve gündüzün değişmesinde (birbiri peşine gelişinde), insanlara yarar sağlayan şeylerle (yüklü olarak) denizde yüzüp giden gemilerde, Allah’ın gökten indirip de kendisi sebebiyle ölümünden sonra toprağı canlandırdığı ve orada (yeryüzünde) her çeşit canlıyı yaydığı suda, rüzgârları ve gökle yer arasında emre hazır bulutları yönlendirmesinde akıl eden bir toplum için dersler vardır."},{"n":165,"t":"İnsanlardan bazıları, Allah’ın peşi sıra ortaklar edinir de onları Allah’ı sever gibi severler. İman edenlerin Allah’a olan sevgileri ise (onlarınkinden) çok daha fazladır. Keşke zalimler azabı gördükleri zaman (anlayacakları gibi) bütün kudretin yalnızca Allah’a ait olduğunu ve Allah’ın azabının çok şiddetli olduğunu (önceden) gör(üp anlayabil)selerdi!"},{"n":166,"t":"İşte o zaman (görecekler ki) kendilerine uyulanlar, (onlara) uyanlardan uzaklaşmıştır ve (her iki taraf da) azabı görmüş, sonunda aralarındaki bağlar kopmuştur."},{"n":167,"t":"(Kötülere) uyanlar şöyle demiş (olacaklar)dır: “Keşke bir kez daha (dünyaya dönmemiz) mümkün olsaydı da şimdi onların bizden uzaklaştıkları gibi biz de onlardan uzaklaşsaydık!” Böylece Allah pişmanlık duydukları işleri kendilerine gösterecektir. Onlar asla ateşten çıkamazlar."},{"n":168,"t":"Ey insanlar! Yeryüzünde bulunanların temiz (ve) helal olanlarından yiyin! Şeytanın adımlarını izlemeyin! Şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":169,"t":"O, size ancak kötülüğü, çirkinliği ve Allah hakkında bilmediğiniz şeyleri söylemenizi emreder."},{"n":170,"t":"Onlara (müşriklere) “Allah’ın indirdiğine uyun!” dendiği zaman, onlar “Hayır! Biz atalarımızı üzerinde bulduğumuz (yol)a uyarız.” dediler. Ataları hiçbir şey akıl etmemiş, doğruyu bulamamış olsalar da mı?"},{"n":171,"t":"Kâfir olanların durumu, (çobanın) bağırıp çağırmasından başka bir şey duymayanın durumuna benzer. Onlar (gerçeğe karşı) sağırdır, dilsizdir, kördür; onlar akıl da etmezler."},{"n":172,"t":"Ey iman edenler! Size verdiğimiz rızıkların temiz olanlarından yiyin! Yalnız O’na ibadet ediyorsanız Allah’a şükredin!"},{"n":173,"t":"Şüphesiz ki (Allah) size leşi, kanı, domuz etini ve Allah’tan başkası adına kesilen (hayvan)ı haram kılmıştır. (Ancak) azgınlık yapmayacak ve sınırı aşmayacak şekilde kim (bunlardan yemek) zorunda kalırsa, (bilsin ki) ona herhangi bir vebal yoktur. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":174,"t":"Allah’ın indirdiği kitaptakileri gizleyip onu az bir değer karşılığında satanlar (var ya), işte onlar karınlarında ateşten başka bir şey yemeyenlerdir. Kıyamet günü Allah onlara konuşmayacak ve onları temize çıkarmayacaktır. Onlar için elem verici bir azap vardır."},{"n":175,"t":"Onlar hidayet karşılığında sapkınlığı, bağışlanma karşılığında da azabı satın alanlardır. Ateşe karşı ne kadar dayanıklıdırlar!"},{"n":176,"t":"Onun (azabın) sebebi, Allah’ın, kitabı bir amaç ile indirmiş olmasıdır. (Buna rağmen) kitap hakkında ayrılığa düşenler, elbette derin bir anlaşmazlığın içindedir."},{"n":177,"t":"(Gerçek) iyilik, yüzlerinizi doğu ve(ya) batı tarafına çevirmeniz değildir. Gerçek iyilik, kişinin Allah’a, ahiret gününe, meleklere, Kitaba ve peygamberlere inanmasıdır. (Allah’ın rızasını gözeterek) yakınlara, yetimlere, yoksullara, yolda kalmışa, (yardım) isteyenlere ve kölelere sevdiği maldan harcamasıdır. (Ayrıca) namazı kılması, zekâtı vermesidir. (Bunlar) antlaşma yaptığı zaman sözlerini yerine getirenlerdir. (Dahası), sıkıntı, hastalık ve savaş zamanlarında sabredenlerdir. Doğru olanlar işte bunlardır! Muttakîler (duyarlı olanlar) da işte bunlardır!"},{"n":178,"t":"Ey iman edenler! Öldürülenler hakkında kısas size farz kılındı: Hür kişiye karşılık bizzat o hür kişi, köleye karşılık bizzat o köle, kadına karşılık da bizzat o kadın. Kimin cezası, kardeşi (öldürülenin velisi) tarafından bir şey (karşılığı) bağışlanırsa, artık (taraflar) hakkaniyete uymalı ve (öldüren kişi gereken diyeti) ona (öldürdüğünün yakınlarına) güzellikle ödemelidir. Bu (söylenenler), Rabbinizden bir hafifletme ve merhamettir. Kim bundan sonra haddi aşarsa onun için elem verici bir azap vardır."},{"n":179,"t":"Ey öz akıl sahipleri! kısasta sizin için hayat vardır. Umulur ki takvâlı (duyarlı) olursunuz."},{"n":180,"t":"Birinize ölüm geldiği zaman, bir hayır (mal) bırakacaksa ana babaya ve yakınlara uygun bir biçimde vasiyet etmek, muttakîler (duyarlı olanlar) üzerinde bir borç olarak farz kılınmıştır."},{"n":181,"t":"Kim duyduktan sonra onu (vasiyeti) değiştirirse, günahı sadece onu değiştirenedir. Şüphesiz ki Allah duyandır, bilendir."},{"n":182,"t":"Kim vasiyet edenin haksızlığa veya günaha yönelmesinden endişe eder de (ilgililerin) arasını bulursa kendisine herhangi bir günah yoktur. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":183,"t":"Ey iman edenler! Oruç, sizden öncekilere farz kılındığı gibi takvâya (duyarlılığa) ulaşasınız diye size de farz kılındı."},{"n":184,"t":"(Oruç size) sayılı günlerde olmak üzere (farz kılındı). İçinizden kim hasta veya yolcu olursa, (tutamadığı gün sayısı kadar) diğer günlerden o sayı(yı tamamlasın). Oruç tutmaya zar zor güçleri yetenlerin ise bir fakiri doyuracak kadar fidye (vermesi) gerekir. Kim gönüllü olarak iyilik yaparsa, bu kendisi için daha hayırlıdır. Bilirseniz (zorluğa rağmen) oruç tutmanız sizin için daha hayırlıdır."},{"n":185,"t":"Ramazan ayı, insanlara yol gösterici, bir rehber ve doğruyu yanlıştan ayırmanın apaçık delilleri olarak Kur’an’ın indirildiği aydır. Sizden o bir aylık süreye ulaşanlar onu (o ayı) oruç tutsun! (İçinizden) kim hasta veya yolcu olursa, (tutamadığı gün sayısı kadar) diğer günlerden o sayı(yı tamamlasın). Allah sizin için kolaylık ister; zorluk istemez. (Bütün bunlar), sayıyı tamamlamanız ve size doğru yolu göstermesine karşılık Allah’ı yüceltmeniz ve şükretmeniz içindir."},{"n":186,"t":"Kullarım sana, beni sorduğunda (de ki): “Ben (kendilerine) çok yakınım. Bana dua ettiği zaman, dua edenin çağrısına cevap veririm. (Kullarım) benim davetime uysunlar ve bana inansınlar ki doğru yolu bulabilsinler!”"},{"n":187,"t":"Oruç gecesinde kadınlarınıza yaklaşmak size helal kılındı. Onlar sizin için elbise (örtü), siz de onlar için elbisesiniz (örtüsünüz). Allah sizin kendinize kötülük ettiğinizi bilmektedir; (bu nedenledir ki) tevbenizi kabul edip sizi bağışladı. Artık onlara (hanımlarınıza) yaklaşın ve Allah’ın sizin için yazdıklarını (neslinizi) isteyin! Tan yerinin beyaz ipliği (aydınlığı), (gecenin) siyah ipliğinden (karanlığından) size göre (tamamen) ayırt edilinceye kadar yiyin, için; sonra da geceye kadar orucu tamamlayın! Mescitlerde itikâftayken onlara (hanımlara cinsel olarak) yaklaşmayın! İşte şu(nlar), Allah’ın (koyduğu) sınırlarıdır; sakın bunlara yaklaşmayın! Allah takvâya (duyarlılığa) ulaşsınlar diye ayetlerini insanlara işte böyle açıklıyor."},{"n":188,"t":"Mallarınızı aranızda batıl sebep(ler)le yemeyin! Bilerek insanların mallarından bir kısmını haram yollardan yemeniz için onları (malları) hakimlere (rüşvet olarak) vermeyin!"},{"n":189,"t":"Sana, hilallerden (ayın hâllerinden) soruyorlar. De ki: “Onlar, insanlar ve (özellikle) hac için vakit ölçüleridir. İyilik, asla evlere arkalarından gel(ip gir)meniz değildir. Ancak iyilik, takvâlı (duyarlı) olan kişi(nin davranışı)dır. Evlere kapılarından giriniz! Allah’a karşı takvâlı (duyarlı) olun! Umulur ki kurtulursunuz.”"},{"n":190,"t":"Size karşı savaşanlarla siz de Allah yolunda savaşın! Sakın aşırı(ya) gitmeyin (saldırmayın)! Şüphesiz ki Allah aşırıları (saldıranları) sevmez."},{"n":191,"t":"Onları (size karşı savaşmakta olanları) yakaladığınız yerde öldürün! Sizi çıkardıkları yerden siz de onları çıkarın! Fitne (zulüm ve işkence), (insan) öldürmekten daha şiddetli (bir kötülük)tür. Mescid-i Haram’da onlar sizinle savaşıncaya kadar siz de onlarla savaşmayın! Onlar size karşı savaş açarlarsa siz de onları öldürün! İşte kâfirlerin cezası böyledir."},{"n":192,"t":"Onlar (savaştan ve inkârdan) vazgeçerlerse, şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":193,"t":"Fitne (zulüm ve işkence) kalmayıncaya ve kulluk da yalnızca Allah’a oluncaya kadar onlarla (saldıranlarla) savaşın! Vazgeçerlerse zalimlerden başkasına düşmanlık yoktur."},{"n":194,"t":"Haram ay(lar) haram ay(lar)a karşılıktır. Dokunulmazlıklar da karşılıklıdır. Kim size saldırırsa siz de onun size saldırması gibi (ona misilleme olacak kadar) saldırın! Allah’a karşı takvâlı (duyarlı) olun! Bilin ki Allah muttakîlerle (duyarlı olanlarla) beraberdir."},{"n":195,"t":"Allah yolunda infak edin (verin)! (Bunu yapmayarak) kendi ellerinizle kendinizi tehlikeye atmayın! Her türlü iyiliği yapın! Şüphesiz ki Allah güzel davrananları sever."},{"n":196,"t":"Allah için haccı ve umreyi tam yapın! (Bunlardan) alıkonulursanız kolayınıza gelen kurbanı (gönderip kestirin)! Kurban, yerine varıncaya kadar başlarınızı (saçınızı) tıraş etmeyin! Sizden kim hasta olursa veya başından bir rahatsızlığı varsa, oruç veya sadaka veya kurban olmak üzere fidye (vermesi) gerekir. Güvende olduğunuz zaman kim hacca (hac günlerine) kadar umre ile yararlanmak isterse, kolayına gelen bir kurban (kesmesi gerekir). (Kurban kesmeye) imkân bulamayan kişi, hac günlerinde üç gün, (memleketine) döndüğü zaman yedi (gün) olmak üzere oruç tutar ki hepsi tam on (gün)dür. İşte şu (hüküm), ailesi Mescid-i Haram civarında oturmayanlar içindir. Allah’a karşı takvâlı (duyarlı) olun! Bilin ki Allah, cezası şiddetli olandır."},{"n":197,"t":"Hac, bilinen aylar(da)dır. Kim o aylarda haccederse (ihrama girerse), hac esnasında kadına yaklaşmak, günah sayılan davranışlara yönelmek ve kavga etmek yoktur. Ne iyilik yaparsanız Allah onu bilir. Azık edinin! Şüphesiz ki azığın en hayırlısı, takvâ (duyarlılık)tır. Ey öz akıl sahipleri! Bana karşı duyarlı olun!"},{"n":198,"t":"(Hac mevsiminde ticaret yaparak) Rabbinizden gelecek bir kazancı aramanızda size herhangi bir vebal yoktur. Arafat’tan (sel gibi) aktığınızda Meş‘ar-i Haram’da (Müzdelife’de) Allah’ı hatırlayın ve O’nu size ilettiği şekilde hatırlayın! Şüphesiz ki siz daha önce sapkınlardandınız."},{"n":199,"t":"Sonra, insanların (sel gibi) aktığı yerden siz de akın! Allah’tan bağışlanma dileyin! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":200,"t":"Hac ibadetlerinizi bitirince, babalarınızı andığınız gibi, hatta ondan daha da güçlü bir şekilde Allah’ı hatırlayın! İnsanlardan öylesi var ki “Rabbimiz! Bize (vereceğini) dünyada ver.” der. Böylesinin ahirette hiçbir payı yoktur."},{"n":201,"t":"Onlardan bir kısmı da “Rabbimiz! Bize dünyada da iyilik ver; ahirette de iyilik ver! Bizi cehennem azabından koru!” diye dua eder."},{"n":202,"t":"İşte onlar için kazandıklarından bir pay vardır. Allah, hesabı hızlı olandır."},{"n":203,"t":"Sayılı günlerde Allah’ı hatırlayın! Takvâlı (duyarlı) olmak isteyenler için kim iki gün içinde acele edip (Mina’dan Mekke’ye) dönmek isterse ona herhangi bir günah yoktur. (Dönüşü) geciktirenler için de herhangi bir günah yoktur. Allah’a karşı takvâlı (duyarlı) olun ve bilin ki hepiniz yalnızca O’nun huzurunda toplanacaksınız."},{"n":204,"t":"İnsanlardan öylesi vardır ki dünya hayatı hakkında söyledikleri hoşuna gider; kalbinde olana da Allah’ı şahit tutar. O hasımların en yamanıdır."},{"n":205,"t":"O dönüp gittiğinde (veya bir yetki sahibi olduğunda) yeryüzünde bozgunculuk çıkarmak, ekinleri ve nesli yok etmek (bozmak) için çalışır. Allah bozgunculuğu sevmez."},{"n":206,"t":"Böylesine “Allah’a karşı takvâlı (duyarlı) ol!” denince, gurur(u) kendisini günaha sevk eder. (Ceza olarak) ona cehennem yeter. O ne kötü bir yataktır!"},{"n":207,"t":"İnsanlardan öylesi de var ki Allah’ın rızasını kazanmak için kendini (servetini) satar (feda eder). Allah kullara çok şefkatlidir."},{"n":208,"t":"Ey iman edenler! Hep birden barışa girin! Şeytanın adımlarını izlemeyin! Şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":209,"t":"Size (hakikate dair) apaçık deliller geldikten sonra (barıştan) sapar, (şeytanın adımlarını izler)seniz, iyi bilin ki Allah güçlüdür, doğru hüküm verendir."},{"n":210,"t":"Onlar, buluttan gölgeler içinde Allah’ın (azap kararının) ve meleklerinin gelmesi ile (hükmün verilip) işin bitirilmesinden başka bir şey mi bekliyorlar! Bütün işler yalnızca Allah’a döndürülecektir."},{"n":211,"t":"İsrailoğulları’na sor ki kendilerine apaçık nice ayet (mucize) vermiştik. Kim kendisine (deliller) geldikten sonra Allah’ın nimetini (ayetlerini) değiştirirse, şüphesiz ki Allah’ın azabı şiddetlidir."},{"n":212,"t":"Kâfir olanlar için dünya hayatı cazip kılındı. Onlar, bazı müminlerle alay ederlerdi. (İman edip) takvâlı (duyarlı) olanlar, kıyamet gününde onların üzerinde (olacak)tır. Allah dilediğine (layık olana) hesapsız rızık verir."},{"n":213,"t":"İnsanlar tek bir ümmetti. Allah müjdeleyiciler ve uyarıcılar olarak peygamberleri göndermiştir. Anlaşmazlığa düştükleri konularda insanlar arasında hükmü vermesi için Kitabı bir amaç doğrultusunda indirmiştir. Ancak (kitap) verilenler, kendilerine apaçık deliller geldikten sonra aralarındaki kıskançlık nedeniyle (dinde) anlaşmazlığa düşmüşlerdi. (Bunun üzerine) Allah iman edenlere, üzerinde çelişkiye düştükleri gerçeği, buyruğuyla göstermiştir. Allah dileyeni (layık gördüğünü) doğru yola ulaştırır."},{"n":214,"t":"Yoksa siz, sizden önce gelip geçenlerin başına gelenlerin benzeri size de gelmeden cennete gireceğinizi mi sandınız! Yoksulluk ve sıkıntı onlara öylesine dokunmuş ve (öylesine) sarsılmışlardı ki sonunda (her) elçi ve beraberindeki müminler, “Allah’ın yardımı ne zaman?” demişlerdi. Dikkat edin! Allah’ın yardımı yakındır."},{"n":215,"t":"Sana nereye (kime) infak edeceklerini soruyorlar. De ki: “infak edeceğiniz her bir şey, ana baba, yakınlar, yetimler, yoksullar ve yolcular için olmalıdır. Her ne iyilik yaparsanız şüphesiz ki Allah onu bilendir.”"},{"n":216,"t":"Sizin için hoş olmasa da (size saldıran kâfirlere karşı) savaş size farz kılındı. Sizin için daha hayırlı olduğu hâlde bir şeyi sevmemeniz mümkündür. Sizin için daha kötü olduğu hâlde bir şeyi sevmeniz de mümkündür. Allah bilir, siz bilmezsiniz."},{"n":217,"t":"Sana haram ay(lar)ı, yani onda savaşmayı soruyorlar. De ki: “Onda savaşmak büyük (bir günah)tır. (İnsanları) Allah yolundan çevirmek, O’nu ve Mescid-i Haram’ın (saygınlığını) inkâr etmek ve (Mekke’nin müslüman) halkını oradan çıkarmak ise Allah katında daha büyük (günah)tır. Fitne (zulüm ve işkence), öldürmekten daha şiddetli (bir kötülük)tür. Güçleri yeterse onlar, dininizden döndürünceye kadar size karşı savaşa devam ederler. Sizden kim dininden döner ve kâfir olarak ölürse, onların işleri dünyada da ahirette de silinir (boşa gider). Onlar ateş halkıdır ve orada ebedî kalıcıdır.”"},{"n":218,"t":"Şüphesiz ki iman edenler, hicret edenler ve Allah yolunda cihad edenler (fedakârlık yapanlar) var ya, işte bunlar Allah’ın merhametini umabilirler. Allah çok bağışlayandır, çok merhametlidir."},{"n":219,"t":"Sana içki ve kumardan soruyorlar. De ki: “Her ikisinde de büyük bir günah (haram) ve insanlar için birtakım çıkarlar vardır. Her ikisinin (de) günahı çıkarından daha büyüktür.” Sana neyi infak edeceklerini soruyorlar. De ki: “Vazgeçilebileni.” Allah düşünesiniz diye ayetleri size işte böyle açıklıyor."},{"n":220,"t":"(Bu açıklamalar) dünya ve ahiret hakkındadır. Sana yetimler hakkında soruyorlar. De ki: “Onları(n durumunu) düzeltmek, (yüzüstü bırakmaktan) hayırlıdır. Onlarla birlikte yaşıyorsanız, (unutmayın ki) onlar, sizin kardeşlerinizdir. Allah işleri bozanı düzeltenden (ayırmayı) bilir. Allah dileseydi sizi de sıkıntıya sokardı. Şüphesiz ki Allah güçlüdür, doğru hüküm verendir.”"},{"n":221,"t":"Müşrik kadınlarla, (onlar) iman edinceye kadar evlenmeyin! İmanlı bir cariye, -hoşunuza gitse de- müşrik bir kadından elbette daha hayırlıdır. İman edinceye kadar müşrik erkekleri de (kızlarınızla) evlendirmeyin! İnanmış bir köle, -hoşunuza gitse de- müşrik bir (kişi)den elbette daha hayırlıdır. Onlar (müşrikler), ateşe çağırır. Allah ise buyruğu ile cennete ve bağışlanmaya çağırır. (Allah gerçeği) hatırlasınlar diye ayetlerini insanlara açıklıyor."},{"n":222,"t":"Sana kadınların âdet hâlini soruyorlar. De ki: “O, bir sıkıntıdır. (Bu sebeple) adet hâlinde kadınlardan (cinsel olarak) uzak durun! Temizleninceye kadar onlara (cinsel olarak) yaklaşmayın! Temizlendiklerinde (kan akışı durunca) Allah’ın size emrettiği yerden onlara varın (yaklaşın)! Şüphesiz ki Allah tevbe edenleri de temizlenenleri de sever.”"},{"n":223,"t":"Kadınlarınız sizin için bir tarladır. Tarlanıza nasıl dilerseniz öyle varın! Kendiniz için (ileriye) hazırlık yapın! Allah’a karşı takvâlı (duyarlı) olun! Bilin ki şüphesiz siz O’na kavuşacaksınız. Müminleri (büyük ödülle) müjdele!"},{"n":224,"t":"Yeminlerinizden dolayı iyilik etmenize, O’na karşı takvâlı (duyarlı) olmanıza ve insanların arasını düzeltmenize Allah’ı engel kılmayın! Allah duyandır, bilendir."},{"n":225,"t":"Allah yeminlerinizdeki boş sözlerle ilgili (kasıtsız yeminlerinizden) sizi sorumlu tutmaz. Ancak kalplerinizin kazandıklarıyla (kasıtlı yeminlerinizden) sorumlu tutar. Allah çok bağışlayandır, hoşgörülüdür."},{"n":226,"t":"Kadınlarına îlâ’da bulunanların dört ay beklemesi gerekir. (Bu sürede hanımlarına) dönerlerse, şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":227,"t":"(Bu süre sonunda hanımlarını) boşamaya karar verirlerse (ayrılırlar). Şüphesiz ki Allah duyandır, bilendir."},{"n":228,"t":"Boşanmış kadınlar, kendi kendilerine (evlenmeden) üç âdet hâli beklerler. Onlar Allah’a ve ahiret gününe inanmışlarsa, rahimlerinde Allah’ın yarattığını gizlemeleri kendilerine helal olmaz. (Kocaları) barışmak isterlerse, bu durumda onları (boşanma sürecindeki eşlerini) geri almaya daha fazla hak sahibidir. (Erkeklerin) kadınlar üzerindeki (hakları gibi), kadınların da (erkekler üzerinde) belirli (hakları) vardır. O (boşanma sürecindeki) erkeklerin, onlara (boşanma sürecindeki kadınlara) bir derece (önceliği) vardır. Allah güçlüdür, doğru hüküm verendir."},{"n":229,"t":"Boşama iki kezdir. (Bundan sonrası) ya iyilikle tutmak ya da güzellikle bırakmaktır. Kadınlara verdiklerinizden (boşanmada) bir şey almanız size helal olmaz. Ancak (eşler) Allah’ın sınırlarında kalıp evlilik haklarını tam uygulayamamaktan korkarlarsa bu durum istisnadır. Siz de onların (eşlerin), Allah’ın sınırlarını koruyamayacaklarından korkarsanız, kadının (erkeğe) fidye vermesinde her iki taraf için de vebal yoktur. Bunlar, Allah’ın sınırlarıdır; onları aşmayın! Kim Allah’ın sınırlarını aşarsa işte onlar, zalimlerin ta kendileridir."},{"n":230,"t":"(Erkek) onu (eşini üçüncü kez) boşarsa, ondan sonra (kadın) bir başka eşle evleninceye kadar onu alması kendisine helal olmaz. Bu kişi (ikinci eş) de onu boşarsa, (her iki taraf da) Allah’ın sınırlarını koruyacaklarına inandıkları takdirde, yeniden evlenmelerinde herhangi bir vebal yoktur. İşte şu (hüküm)ler, (gerçeği) bilmek (isteyen) bir topluluk için Allah’ın açıkladığı sınırlarıdır."},{"n":231,"t":"Kadınları boşadığınız ve onlar da (üç aylık bekleme) süresinin sonuna geldiklerinde onları iyilikle tutun veya iyilikle bırakın! Haksızlık ederek ve (kendilerine) zarar vermek için onları (zorla) tutmayın! Kim bunu yaparsa elbette (öncelikle) kendine kötülük etmiş olur. Allah’ın ayetlerini eğlence edinmeyin! Allah’ın sizin üzerinizdeki nimetini (size verdiği hidayeti), size öğüt vermek üzere indirdiği Kitabı ve hikmeti (doğru hüküm verme yeteneğini) hatırlayın! Allah’a karşı takvâlı (duyarlı) olun! Bilin ki şüphesiz Allah her şeyi bilendir."},{"n":232,"t":"Kadınları boşadığınız ve onlar da (üç aylık bekleme) süresinin sonuna geldiklerinde, aralarında iyilikle anlaştıkları takdirde, onların (eski veya aday) eşleriyle evlenmelerine engel olmayın! İşte bununla içinizden Allah’a ve ahiret gününe inananlara öğüt verilmektedir. Bu (öğüdü tutmanız), kendiniz için en iyisi ve en temizidir. Allah bilir, siz bilmezsiniz."},{"n":233,"t":"Emzirmeyi tamamlatmak isteyen (babalar) için (kendilerinden boşanmış) anneler çocuklarını iki tam yıl emzirirler. Onların uygun bir şekilde beslenmesi ve giyimi, babaya aittir. Hiçbir can (insan), gücünün dışında (bir şeyle) sorumlu tutulmaz. Hiçbir anne, çocuğu sebebiyle, hiçbir baba da çocuğu sebebiyle zarara uğratılmamalıdır. (Baba ölürse) onun benzeri (nafaka temini) mirasçı üzerine yükümlülüktür. Onlar (anne ve baba) karşılıklı anlaşarak ve birbirleriyle görüşerek (çocuğu iki yıldan önce sütten) ayırmak isterlerse kendilerine herhangi bir vebal yoktur. Çocuklarınızı (süt anneye) emzirtmek istediğiniz takdirde, süt anneye vermekte olduğunuzu (ücreti) uygun bir şekilde teslim etmenizde size vebal yoktur. Allah’a karşı takvâlı (duyarlı) olun! Bilin ki Allah yapmakta olduklarınızı şüphesiz ki görendir."},{"n":234,"t":"İçinizden ölenlerin (geride bıraktıkları) eşleri, kendi başlarına (evlenmeden) dört ay on gün beklerler. (Bekleme) süresinin sonuna geldiklerinde, kendileri hakkında yaptıkları uygun (işlerde) size herhangi bir vebal yoktur. Allah, yapmakta olduklarınızdan haberdardır."},{"n":235,"t":"(Beklemekte olan) kadınlarla evlenme hakkındaki düşüncelerinizi sunmanızda veya onu içinizde tutmanızda size herhangi bir vebal yoktur. Allah sizin onları anacağınızı bilir. Uygun sözler söylemeniz hariç, sakın onlara gizlice buluşma sözü vermeyin! Kitap, (bekleme) süresini dolduruncaya kadar nikâh düğümünü pekiştirmeyin (nikâh kıymaya kalkışmayın)! Bilin ki Allah nefislerinizdekileri (kalplerinizdekini) bilir. Bu sebeple (yanlış yaparsanız) O’ndan (Allah’tan) sakının! Bilin ki Allah çok bağışlayandır, hoşgörülüdür."},{"n":236,"t":"(Nikâhtan sonra) henüz dokunmadan (cinsel ilişkiye girmeden) veya onlar için belirli bir mehir belirlemeden kadınları boşarsanız size herhangi bir vebal yoktur. (Bu durumda) onlara ödemede bulunun: Güzel davrananlar üzerine bir borç olarak, zengin olan durumuna göre, fakir olan da durumuna göre uygun (bir ödemede bulunmalıdır)."},{"n":237,"t":"Kendilerine mehir belirleyerek evlendiğiniz kadınları, onlara dokunmadan (cinsel ilişkiye girmeden) boşarsanız, kadınların vazgeçmesi veya nikâh bağı elinde bulunanın (kocanın) vazgeçmesi durumu dışında, belirlediğiniz mehrin yarısı (onların hakkı)dır. Affetmeniz (mehirden vazgeçmeniz) takvâya (duyarlılığa) daha uygundur. Aranızda iyiliği unutmayın! Şüphesiz ki Allah, yapmakta olduklarınızı görendir"},{"n":238,"t":"Salavat’a (namazlara) ve orta (ideal) salât’a (namaza) devam edin! Allah’a saygı içinde (bunu) yerine getirin!"},{"n":239,"t":"(Bir tehlikeden) korkarsanız (namazlarınızı) yürüyerek veya binmiş olarak (binek üzerinde kılın)! Güvende olduğunuzda, siz bilmiyorken Allah’ın size öğrettiği şekilde O’nu hatırlayın (namaz kılın)!"},{"n":240,"t":"İçinizden vefat ettiğinde (dul) eşler bırakacak olanlar, (bu) eşlerinin (bıraktıkları maldan) bir yıla kadar (evlerinden) çıkarılmadan yararlanmaları hakkında (sağlıklarında) vasiyet (etsinler)! Onlar (eşi ölen kadınlar) giderlerse, kendileri hakkında yaptıkları uygun (işlerde) size bir vebal yoktur. Allah güçlüdür, doğru hüküm verendir."},{"n":241,"t":"Muttakîler (duyarlı olanlar) üzerine bir borç olarak, boşanmış kadınların uygun bir şekilde (kocalarından) menfaat sağlaması (onların hakkıdır)."},{"n":242,"t":"Allah akıl edesiniz diye ayetlerini size işte böyle açıklıyor."},{"n":243,"t":"Binlerce (kişi) oldukları hâlde, ölüm korkusuyla yurtlarından çıkıp gidenleri görmedin mi? Allah onlara “(manevi olarak) ölün!” demişti; sonra da onları (manevi olarak) diriltmişti. Şüphesiz ki Allah insanlara karşı lütufkârdır. Fakat insanların çoğu şükretmez."},{"n":244,"t":"Allah yolunda savaşın! Bilin ki Allah duyandır, bilendir."},{"n":245,"t":"Kim Allah’a güzel bir borç verirse, (Allah) da ona (bunun) pek çok katını verir. Allah dar olarak da verir; bol olarak da verir. Yalnızca O’na döndürüleceksiniz."},{"n":246,"t":"Musa’dan sonra, İsrailoğulları’nın yöneticilerini görmedin mi? Peygamberlerine, “Bize bir hükümdar gönder (görevlendir) ki (onun komutasında) Allah yolunda savaşalım.” demişlerdi. (O peygamber) “Ya size savaş yazılır (farz kılınır) da savaşmazsanız?” deyince, onlar da “Yurtlarımızdan çıkarılmış, çocuklarımızdan (uzaklaştırılmış olduğumuz) hâlde Allah yolunda neden savaşmayalım ki?” demişlerdi. Kendilerine savaş yazılınca (farz kılınınca), içlerinden azı hariç yüz çevirmişler (kaçmışlar)dı. Allah zalimleri bilendir."},{"n":247,"t":"Peygamberleri onlara “Elbette Allah, Talut’u size hükümdar olarak gönderdi (görevlendirdi)” deyince, onlar “Biz hükümdarlığa daha layık olduğumuz hâlde, kendisine servet ve zenginlik yönünden geniş imkânlar verilmemişken, nasıl o bize hükümdar olur?” demişlerdi. (O peygamber) şöyle demişti: “Allah onu sizin üzerinize seçti, ilimde ve bedende ona üstünlük verdi. Allah, hükümdarlığı dilediğine (layık olana) verir. Allah, (imkânları) geniş olandır, bilendir.”"},{"n":248,"t":"Peygamberleri onlara şöyle demişti: “Onun hükümdarlığının işareti, meleklerin taşıdığı, içinde Rabbinizden bir ferahlık ve sükûnet, Musa’nın ailesinin ve Harun’un ailesinin bıraktıklarından bir kalıntı bulunan Tâbût’un size gelmesidir. İnananlarsanız şüphesiz ki bunda sizin için bir delil vardır.””"},{"n":249,"t":"Talut askerlerle birlikte (savaş için) ayrılınca şöyle demişti: “Allah sizi bir ırmakla imtihan edecek. Ondan içen benden değildir, onu tatmayan bendendir; eliyle (sadece) bir avuç alan hariç.” İçlerinden azı hariç hepsi ırmaktan içmişlerdi. O (Talut) ve onunla birlikte iman edenler birlikte ırmağı geçince “Bugün bizim Calut’a ve askerlerine karşı koyacak gücümüz yoktur.” demişlerdi. Allah’(ın huzurun)a varacaklarına inananlar, “Sayıca az nice birlik(ler), Allah’ın izniyle sayıca çok birlik(ler)i yenmiştir. Allah sabredenlerle beraberdir.” demişlerdi."},{"n":250,"t":"Calut ve askerleriyle savaşa tutuştuklarında, (Talut’un askerleri) “Rabbimiz! Üzerimize sabır yağdır! Ayaklarımızı sabit tut! kâfirler topluluğuna karşı bize yardım et.” diye dua etmişlerdi."},{"n":251,"t":"Allah’ın izniyle onları yenmişler, Davud da Calut’u öldürmüştü. Allah ona (Davud’a) hükümdarlık ve hikmet (doğru hüküm verme yeteneği) vermiş, dilediği ilimlerden öğretmişti. Allah’ın insanlardan bir kısmını(n kötülüğünü) diğerleriyle savması olmasaydı, elbette yeryüzü bozguna uğrardı. Fakat Allah bütün insanlığa karşı iyilik sahibidir."},{"n":252,"t":"İşte şu(nlar), Allah’ın sana bir amaç ile tilavet etmekte (okuyup aktarmakta) olduğumuz ayetleridir. Şüphesiz ki sen elçilerdensin."},{"n":253,"t":"İşte şu elçilerin bir kısmını bir kısmına (farklı oldukları noktalarda) üstün kılmıştık. Allah onlardan bir kısmına konuşmuş, bazılarını da derecelerini yükseltmiştir. (Nitekim) Meryem oğlu İsa’ya da apaçık deliller vermiş ve onu Kutsal Ruh (Cebrail) ile desteklemiştik. Allah dileseydi (Allah’ın dileğine uysalardı) onlardan sonra gelen milletler, kendilerine apaçık deliller geldikten sonra birbirleriyle savaşmazlardı. Fakat onlar ayrılığa düştüler; içlerinden kimi iman etti, kimi de inkâr etti. Allah dileseydi (Allah’ın dileğine uysalardı) onlar savaşmazlardı fakat (her şekilde) Allah dilediğini yapar."},{"n":254,"t":"Ey iman edenler! Kendisinde artık alışveriş, dostluk ve şefaat bulunmayan gün (kıyamet) gelmeden önce, size verdiğimiz rızıktan infak edin (verin)! kâfirler elbette zalimlerdir."},{"n":255,"t":"Allah (ki) O’ndan başka ilah yoktur. Diridir, hayatı elinde tutandır. Kendisini ne uyuklama tutar ne de uyku. Göklerde ve yerdekilerin hepsi yalnızca O’na aittir. İzni olmadan O’nun katında kim şefaat edebilir ki! Onların önlerindekini de arkalarındakini de bilir. (Bildirmeyi) dilediklerinin dışında (kimse) O’nun bilgisinden hiçbir şeyi kuşatamaz. O’nun egemenliği gökleri ve yeri kapsamıştır. Onları koruyup gözetmek kendisine zor gelmez. O yücedir, büyüktür."},{"n":256,"t":"Dinde zorlama yoktur. Elbette doğru yanlıştan ayrılmıştır. Kim tağut’u (azgınlık edeni) reddedip Allah’a inanırsa, kopmayan en sağlam kulba yapışmış demektir. Allah duyandır, bilendir."},{"n":257,"t":"Allah iman etmiş olanların dostudur; onları karanlıklardan aydınlığa çıkarır. kâfir olanlara gelince, onların dostları Tağut’tur (azgınlık edendir); onları aydınlıktan karanlıklara çıkarırlar (gömerler). İşte bunlar ateş halkıdır. Onlar orada ebedî kalıcıdır."},{"n":258,"t":"Allah kendisine hükümdarlık verdiği için Rabbi hakkında İbrahim ile tartışmaya gireni (Nemrut’u) görmedin mi? Hani İbrahim “Rabbim yaşatan ve öldürendir.” demişti. O da “Ben de yaşatır ve öldürürüm.” demişti. İbrahim, “Allah güneşi doğudan getirmektedir; sen de onu batıdan getir.” demişti de o kâfir şaşakalmıştı. Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":259,"t":"Veya (görmediniz mi) o kişiyi ki evlerinin duvarları çatıları üzerine yığılmış (alt üst olmuş) bir şehre uğramıştı. (Bu kişi), “(Şehrin) ölümünden sonra Allah burayı nasıl diriltir acaba?” demişti. Bunun üzerine Allah onu yüz yıl öldürmüş (ölü gibi bırakmış), sonra tekrar diriltmişti. (Allah) “Ne kadar kaldın?” diye sorunca “Bir gün veya günün bir kısmı kadar.” demişti. (Allah) ona şöyle demişti: “Hayır! Yüz yıl kaldın. Yiyeceğine ve içeceğine bak, henüz bozulmamıştır. Eşeğine de bak! Seni insanlara bir ibret kılalım diye (böyle yaptık). Şimdi kemiklere bak, onları nasıl düzenliyor, sonra nasıl onlara et giydiriyoruz!” (Durum) kendisi için apaçık bir hâl alınca, “Biliyorum ki Allah her şeye gücü yetendir.” demişti."},{"n":260,"t":"Hani İbrahim “Rabbim! Ölüyü nasıl diriltmekte olduğunu bana göster.” demişti. (Rabbi ona) “İnanmadın mı?” diye sorunca (İbrahim) “Hayır (elbette inandım) fakat kalbimin tatmin olması için (görmek istedim)” demişti. Bunun üzerine (Allah) şöyle demişti: “Dört tane kuş alıp onları kendine alıştır; sonra her dağa onlardan birer parça koy! Ardından onları çağır; koşarak (uçarak) sana gelirler. Bil ki Allah güçlüdür, doğru hüküm verendir.”"},{"n":261,"t":"Mallarını Allah yolunda infak edenlerin (verenlerin) örneği, yedi başak bitiren bir tohum tanesi gibidir ki her başakta yüz tane (ürün) vardır. Allah dilediğine (layık olana) kat kat (fazlasını) verir. Allah (imkânları) geniş olandır, bilendir."},{"n":262,"t":"Mallarını Allah yolunda infak edip (verip) arkasından başa kakmayan, (fakirleri) incitmeyenler var ya onlar için Rableri katında ödül(ler)i vardır. Onlara herhangi bir korku yoktur; onlar üzülmeyecek de."},{"n":263,"t":"Güzel bir söz ve bağışlama, arkasından incitme gelen sadakadan hayırlıdır. Allah zengindir, hoşgörülüdür."},{"n":264,"t":"Ey iman edenler! Allah’a ve ahiret gününe inanmadığı hâlde malını insanlara gösteriş için infak eden (veren) kişi gibi, sadakalarınızı başa kakarak ve inciterek iptal etmeyin! Böylesinin durumu, üzerinde biraz toprak bulunan kayaya benzer ki ona sağanak yağmur isabet etmiş de onu çıplak (topraksız) hâle getirmiştir. Bunlar, kazandıklarından hiçbir şeyi elde edemezler. Allah o kâfirler topluluğunu doğru yola ulaştırmaz."},{"n":265,"t":"Allah’ın rızasını kazanmak ve nefislerini güçlendirmek için mallarını infak edenlerin (verenlerin) durumu, bir tepedeki bahçeye benzer ki üzerine sağanak yağmur yağmış da iki kat ürün vermiştir. Sağanak yağmur yağmasa bile bir çise (ile de ürün verir). Allah yaptıklarınızı görendir."},{"n":266,"t":"Herhangi biriniz ister mi ki hurma ve üzümlere (ağaçlara) sahip, arasından sular akan ve kendisi için orada her çeşit meyveden bulunan bir bahçesi olsun (ama) bakıma muhtaç çocukları varken kendisine yaşlılık gelip çatsın; içinde ateş bulunan bir kasırga ona (bahçeye) isabet ederek yakıp kül etsin! Allah düşünesiniz diye ayetleri size işte böyle açıklıyor."},{"n":267,"t":"Ey iman edenler! Kazandıklarınızın değerli olanlarından ve yerden (topraktan) size rızık olarak çıkardıklarımızdan infak edin (verin)! (Size verilse), gözünüzü yummadan alamayacağınız kötü malı infaka (vermeye) kalkışmayın! Bilin ki şüphesiz Allah zengindir, övgüye layıktır."},{"n":268,"t":"Şeytan size fakirlik vadeder (sizi fakirlikle korkutur) ve size cimriliği emreder (teşvik eder). Allah ise katından size bir bağışlanma ve bir lütuf vadeder. Allah (imkânları) geniş olandır, bilendir."},{"n":269,"t":"(Allah) hikmeti (doğru hüküm verme yeteneğini) dileyene (layık gördüğüne) verir. Kime hikmet (doğru hüküm verme yeteneği) verilirse, elbette ona pek çok iyilik verilmiş demektir. Öz akıl sahiplerinden başkası (gerçeği) hatırlamaz."},{"n":270,"t":"Şüphesiz ki Allah yaptığınız her infakı (harcamayı) ve adadığınız her adağı bilir. Zalimler için hiçbir yardımcı yoktur."},{"n":271,"t":"Sadakaları açıktan verirseniz bu ne güzeldir! Onları gizler de fakirlere öyle verirseniz, işte bu sizin için daha hayırlıdır. O (Allah) da sizin günahlarınızın bir kısmını örter. Allah yapmakta olduklarınızdan haberdardır."},{"n":272,"t":"Onların hidayeti senin üzerine (bir görev) değildir. Zira Allah dileyeni (layık gördüğünü) doğru yola ulaştırır. Her ne iyilik infak ederseniz kendiniz içindir. Yalnızca Allah rızası için infak edeceksiniz. Her ne iyilik infak ederseniz, size (karşılığı) tastamam verilecektir ve haksızlığa uğratılmayacaksınız."},{"n":273,"t":"(Yapacağınız yardımlar), kendilerini Allah yoluna adamış (oldukları için) yeryüzünde (kazanç amacıyla) dolaşamayan fakirler için (olsun)! Bilmeyenler, onurlarından dolayı onları zengin sanır. Sen onları yüzlerinden tanırsın. Onlar, yüzsüzlük ederek (bir şey) istemezler. Şüphesiz ki Allah yaptığınız her iyiliği bilendir."},{"n":274,"t":"Mallarını gece gündüz, gizli-açık (Allah yolunda) infak edenler var ya onlar için Rableri katında ödül(ler)i vardır. Onlara herhangi bir korku yoktur; onlar üzülmeyecek de."},{"n":275,"t":"Faiz yiyenler, şeytan çarpmış kişilerin kalktıkları gibi kalkarlar. Bu, onların “alışveriş tıpkı faiz gibidir.” demeleri yüzündendir. (Oysa) Allah alışverişi helal, faizi haram kılmıştır. (Artık) kime Rabbinden bir öğüt gelir de (faizden) vazgeçerse, geçmişte olan (kazançları) kendisinindir. Onun işi Allah’a (kalmış)tır. Kim de (tekrar faize) dönerse, işte onlar ateş halkıdır; orada ebedî kalıcıdır."},{"n":276,"t":"Allah faizi siler (malın ve servetin bereketini giderir); sadakaları ise artırır. Allah küfre dalanları, günahta ısrar edenleri sevmez."},{"n":277,"t":"İman edip iyi işler yapan, namaz kılan ve zekât verenler var ya, Rableri katında onlar için ödül(ler)i vardır. Onlara herhangi bir korku yoktur; onlar üzülmeyecek de."},{"n":278,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun! İnanıyorsanız, faizden (elinizde) kalan kısmı terkedin!"},{"n":279,"t":"(Böyle) yapmazsanız, Allah ve Elçisi tarafından (faizcilere açılan) savaştan haberiniz olsun! tevbe ederseniz, malınızın aslı (anaparanız) sizindir. (Böylece) ne haksızlık etmiş ne de haksızlığa uğramış olursunuz."},{"n":280,"t":"(Borçlu) dardaysa eli genişleyinceye kadar ona zaman vermek (gerekir). Bilirseniz (alacağınızı) bağışlamanız sizin için hayırlı olandır."},{"n":281,"t":"Allah’a döndürüleceğiniz, sonra da herkese kazandığının (karşılığının) eksiksiz verileceği ve onların haksızlığa uğratılmayacağı bir güne karşı duyarlı olun!"},{"n":282,"t":"Ey iman edenler! Belirlenmiş bir süreye kadar birbirinize borçlandığınız zaman onu yazın! Bir kâtip onu aranızda adaletle yazsın! Hiçbir kâtip, Allah’ın kendisine öğrettiği gibi yazmaktan kaçınmasın; (olduğu şekilde) yazsın! Üzerinde hak olan (borçlu) kişi de yazdırsın; Rabbine karşı takvâlı (duyarlı) olsun ve borcundan hiçbir şey eksiltmesin (eksik yazdırmasın)! Üzerinde hak olan (borçlu) kişi, aklı kıt veya zayıf ya da yazdırmaya gücü yetmiyorsa, velisi (onu) adaletle yazdırsın! Erkeklerinizden iki şahit de bulundurun! İki erkek bulunamazsa, razı olacağınız bir erkek ile biri yanılırsa (şaşırırsa) diğerinin ona hatırlatması için iki hanım şahit (olsun)! Şahitler, çağrıldıkları zaman (şahitlik etmekten) kaçınmasınlar! Küçük veya büyük hiçbir şeyi süresiyle birlikte yazmaya sakın üşenmeyin! Böyle yapmanız, Allah katında daha adil, şahitlik için daha sağlam, şüpheye düşmemeniz için daha uygundur. (Ancak) aranızda gerçekleştirdiğiniz ticaret peşin olursa bu hariç; bu durumda onu yazmamanızda sizin için hiçbir vebal yoktur. Karşılıklı (yüz yüze) alışveriş yaptığınızda (da) şahit tutun! Yazan da şahitlik eden de zarara uğratılmasın! (Bunu) yaparsanız şüphesiz ki bu, yoldan çıkmanız demektir. Allah’a karşı takvâlı (duyarlı) olun! Allah size öğretiyor. Allah her şeyi bilendir."},{"n":283,"t":"Yolculuktayken kâtip bulamazsanız (borca karşılık) alınmış bir rehin (kapora yeterlidir). Birbirinize güvenirseniz, kendisine güvenilen kişi, emaneti (sahibine) versin ve Rabbi olan Allah’a karşı takvâlı (duyarlı) olsun! Şahitliği (bildiklerinizi) gizlemeyin! Kim onu gizlerse onun kalbi günahkârdır. Allah yaptıklarınızı bilendir."},{"n":284,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. İçinizdekileri açığa vursanız da gizleseniz de Allah sizi onunla hesaba çekecektir. (Allah) dileyeni (layık gördüğünü) bağışlar; dileyene (layık gördüğüne) de azap eder. Allah her şeye gücü yetendir."},{"n":285,"t":"O elçi, Rabbinden kendisine indirilene iman etti, müminler de. Hepsi Allah’a, meleklerine, kitaplarına, elçilerine iman ettiler. (Müminler) “O’nun (Allah’ın) elçilerinden hiçbiri arasında fark gözetmeyiz.” (derler). “İşittik, itaat ettik. Rabbimiz, affına (sığındık)! Dönüş yalnızca sanadır.” derler."},{"n":286,"t":"Allah hiçbir canı gücünün yetmeyeceği şeyle sorumlu tutmaz. (Herkesin) kazandığı (iyilik) kendi lehine, kazandığı (kötülük) de kendi aleyhinedir. “Rabbimiz! Unutur veya hataya düşersek bizi sorumlu tutma! Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yük yükleme! Rabbimiz! Bize gücümüzün yetmediği şeyler yükleme! Bizi affet! Bizi bağışla! Bize merhamet et! Sen bizim mevlamızsın (efendimizsin)! kâfirler topluluğuna karşı bize yardım et!”"}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":2,"t":"Allah (ki) O’ndan başka ilah yoktur. Diridir, hayatı elinde tutandır."},{"n":3,"t":"3-4 O, sana Kitab'ı önceki kitapları(n aslını) doğrulayıcı olarak bir amaç ile indirmiştir. Daha önce insanlara doğru yolu göstermek için Tevrat’ı ve İncil’i de indirmişti. Furkân’ı (doğruyu yanlıştan ayıran Kur’an’ı) da O indirmiştir. Şüphesiz ki Allah’ın ayetlerini inkâr edenler için şiddetli bir azap vardır. Allah güçlüdür, intikam sahibidir."},{"n":4,"t":"3-4 O, sana Kitab'ı önceki kitapları(n aslını) doğrulayıcı olarak bir amaç ile indirmiştir. Daha önce insanlara doğru yolu göstermek için Tevrat’ı ve İncil’i de indirmişti. Furkân’ı (doğruyu yanlıştan ayıran Kur’an’ı) da O indirmiştir. Şüphesiz ki Allah’ın ayetlerini inkâr edenler için şiddetli bir azap vardır. Allah güçlüdür, intikam sahibidir."},{"n":5,"t":"Şüphesiz ki yerde de gökte de hiçbir şey Allah’a gizli kalmaz."},{"n":6,"t":"Rahimlerde sizi dilediği gibi şekillendiren O’dur. O’ndan başka ilah yoktur. Güçlüdür, doğru hüküm verendir."},{"n":7,"t":"Sana Kitabı indiren O’dur. Onun bazı ayetleri muhkem (açık anlamlı)dır ki bunlar Kitabın anasıdır (esasıdır). Diğerleri de müteşabih (benzeşen anlamlı)lardır. Kalplerinde eğrilik olanlar, Fitne çıkarmak ve onu (arzularına göre) yorumlamak için ondaki müteşabih ayetlerin peşine düşerler. (Oysa) onun (asıl) yorumunu Allah’tan başkası bilemez. İlimde derinlik sahibi olanlar ise “Ona inandık; hepsi Rabbimizin katındandır.” derler. Öz akıl sahiplerinden başkası (gerçeği) hatırlamaz."},{"n":8,"t":"(Şöyle dua ederler:) “Rabbimiz! Bizi doğru yola ulaştırdıktan sonra kalplerimizi eğriltme! Bize katından merhamet ver! Şüphesiz ki bolca veren yalnızca sensin."},{"n":9,"t":"Rabbimiz! Gelmesinde şüphe olmayan bir günde, insanları mutlaka toplayacak olan sensin.” Şüphesiz ki Allah sözünden dönmez."},{"n":10,"t":"Şüphesiz ki kâfir olanların malları da çocukları da Allah’a karşı onlara hiçbir şeyde asla yarar sağlamayacaktır. İşte onlar -evet onlar- cehennemin yakıtıdır."},{"n":11,"t":"(Bunların durumu) tıpkı Firavun’un ailesi (destekçileri) ve onlardan öncekilerin durumu gibidir. (Onlar) ayetlerimizi yalanlamışlardı; Allah da günahları sebebiyle onları yakalamıştı. Allah, azabı şiddetli olandır."},{"n":12,"t":"Kâfir olanlara de ki: “Yakında (dünyada) yenileceksiniz ve (ahirette) cehenneme sürüleceksiniz. Ne kötü bir yataktır (orası)!”"},{"n":13,"t":"(Bedir’de) karşı karşıya gelen (şu) iki grupta sizin için elbette bir ibret vardır: (Biri) Allah yolunda savaşan bir grup, diğeri ise onları apaçık bir şekilde kendilerinin iki katı gören kâfir (bir grup). Allah dilediğini (layık olanı) yardımı ile destekler. Şüphesiz ki görenler için bunda ibret vardır."},{"n":14,"t":"Kadınlara, çocuklara, yığınla altın ve gümüşe, nişanlı atlara, (sağılabilen) hayvanlara ve ekinlere karşı aşırı düşkünlük o insanlara çekici görünür. Bu(nlar), dünya hayatının geçimlikleridir. (Oysa) varılacak güzel yer, yalnızca Allah’ın katındadır."},{"n":15,"t":"De ki: “Bunlardan hayırlısını size bildireyim mi? Takvâlı (duyarlı) olanlar için Rablerinin katında, altlarından ırmaklar akan, içlerinde ebedî kalacakları cennetler, tertemiz eşler ve Allah’ın rızası vardır. Allah kulları görendir.”"},{"n":16,"t":"Onlar (duyarlı olanlar) “Rabbimiz! Şüphesiz ki biz iman ettik; bizim için günahlarımızı bağışla, bizi ateş azabından koru!” derler."},{"n":17,"t":"(Onlar) sabredenler, dürüst olanlar, (Allah’a) boyun eğenler, infak edenler (verenler) ve seher vakitlerinde bağışlanma dileyenler(dir)."},{"n":18,"t":"Allah, melekleri ve adaleti gözeten ilim sahipleri şahittir ki O’ndan başka ilah yoktur. (Evet) O’ndan başka ilah yoktur. Güçlüdür, doğru hüküm verendir."},{"n":19,"t":"Şüphesiz ki Allah katında din İslam’dır. Kitap verilenler ancak kendilerine bilgi geldikten sonra aralarındaki kıskançlık yüzünden ayrılığa düşmüşlerdi. Kim Allah’ın ayetlerini inkâr ederse (bilsin ki) şüphesiz ki Allah hesabı hızlı olandır."},{"n":20,"t":"Seninle tartışırlarsa de ki: “Ben kendimi bana uyanlarla birlikte Allah’a teslim ettim.” Kitap ehline ve ümmilere de ki: “Siz de Allah’a teslim oldunuz mu?” Teslim olurlarsa doğru yolu bulmuş olurlar. Yüz çevirirlerse sana düşen, sadece (mesajı) ulaştırmaktır. Allah kulları görendir."},{"n":21,"t":"Şüphesiz ki Allah’ın ayetlerini inkâr edenler, haksız yere peygamberleri öldürenler ve adaleti emredenleri öldürenler (var ya), onlara elem verici bir azabı müjdele!"},{"n":22,"t":"İşte onlar, dünyada da ahirette de işleri boşa gidenlerdir. Onların hiçbir yardımcısı da yoktur."},{"n":23,"t":"Kitaptan kendilerine bir pay verilenleri (kitap ehlini) görmedin mi? Aralarında hükmetmesi için Allah’ın Kitabına çağrılıyorlar da sonra içlerinden bir grup dönüp yüz çeviriyor."},{"n":24,"t":"(Gerekçeleri ise), onların “Sadece sayılı günlerde bize ateş dokunacaktır.” demeleriydi. Uydurdukları şeyler, dinleri hakkında kendilerini aldatmıştı."},{"n":25,"t":"Kazandıkları şeylerin haksızlığa uğratılmadan herkese tastamam ödenmiş (olacağı), kendisinde şüphe olmayan bir gün için onları topladığımız zaman (hâlleri) nasıl (olacak)!"},{"n":26,"t":"De ki: “Ey mülkün (otoritenin) gerçek sahibi (olan) Allah’ım! Sen dilediğine Mülk (otorite) verirsin ve dilediğinden mülkü (otoriteyi) geri alırsın. Dilediğini yükseltir; dilediğini de alçaltırsın. (Bütün) iyilik yalnızca senin elindedir. Şüphesiz ki sen her şeye gücü yetensin."},{"n":27,"t":"Geceyi gündüzün içine koyuyorsun; gündüzü de gecenin içine koyuyorsun. Ölüden diriyi çıkarıyorsun; diriden de ölüyü çıkarıyorsun. Dilediğine de hesapsız rızık verirsin.”"},{"n":28,"t":"Müminler, müminleri bırakıp da kâfirleri dost edinmesin! Kim bunu yaparsa, artık Allah ile bir şeyi (ilgisi) kalmaz. Ancak onlardan (kâfirlerden gelebilecek bir tehlikeden) korunmanız başkadır. Allah kendisine karşı (gelmekten) sizi sakındırıyor. Dönüş, yalnızca Allah’adır."},{"n":29,"t":"De ki: “Göğsünüzdekileri (kalplerinizdekileri) gizleseniz de açığa vursanız da Allah onu bilir. Göklerde ve yerde olanları da bilir. Allah her şeye gücü yetendir.”"},{"n":30,"t":"Herkesin, iyilik olarak yaptıklarını da kötülük olarak yaptıklarını da karşısında hazır bulacağı (o) günde (insan), işlediği kötülükleri ile kendisi arasında uzun bir mesafe bulunmasını içtenlikle dileyecek. Allah kendisine karşı (gelmekten) sizi sakındırıyor. Allah kullara çok şefkatlidir."},{"n":31,"t":"De ki: “Allah’ı seviyorsanız bana uyun ki Allah da sizi sevsin ve sizin için günahlarınızı bağışlasın. Allah çok bağışlayandır, çok merhametlidir.”"},{"n":32,"t":"De ki: “Allah’a ve Elçi'ye itaat edin! Yüz çevirirseniz (bilin ki) Allah kâfirleri sevmez.”"},{"n":33,"t":"Şüphesiz ki Allah; Âdem’i, Nuh’u, İbrahim Ailesi ile İmran Ailesini âlemlere (diğer insanlara) seç(ip üstün kıl)mıştır."},{"n":34,"t":"(Bunlar) birbirinden gelme nesillerdir. Allah duyandır, bilendir."},{"n":35,"t":"İmran’ın hanımı şöyle demişti: “Rabbim! Karnımdakini özgür olarak sana adadım. (Bunu) benden kabul et! Şüphesiz ki yalnızca sen duyansın; bilensin.”"},{"n":36,"t":"Onu doğurunca -Allah onun ne doğurduğunu çok iyi bilirken- şöyle demişti: “Rabbim! Ben onu kız (olarak) doğurdum. Erkek, kız gibi değildir. Ona Meryem adını verdim. Onu ve soyunu kovulmuş şeytandan (koruman için) sana sığınıyorum.”"},{"n":37,"t":"Rabbi onu (Meryem’i) güzel bir şekilde (duasını) kabul etmişti; onu güzel bir bitki olarak yetiştirmiş ve Zekeriya’yı da onun bakımıyla görevlendirmişti. Zekeriya mabette onun yanına her girişinde orada bir rızık bulurdu. (Zekeriya), “Ey Meryem, bu sana nereden (geliyor)?” dediğinde, o da “Bu, Allah katındandır.” demişti. Şüphesiz ki Allah dilediğine (layık olana) hesapsız rızık verir."},{"n":38,"t":"Zekeriya orada Rabbine dua etmiş ve şöyle demişti: “Rabbim! Bana tarafından hayırlı bir nesil ver! Şüphesiz ki sen duayı duyansın.”"},{"n":39,"t":"O (Zekeriya) mabette namaz kılarken melekler (ona şöyle) seslenmişlerdi: “Allah sana kendisi tarafından gelen bir sözü doğrulayıcı, efendi, onurlu ve iyilerden bir peygamber olarak Yahya’yı müjdeliyor.”"},{"n":40,"t":"(Zekeriya) şöyle demişti: “Rabbim! Yaşlılık bana gelip çattığına, hanımım da kısır olduğuna göre benim (bir) oğlum nasıl olabilir ki?” (Melekler) şöyle demişti: “Öyle, (ama) Allah dilediğini yapar.”"},{"n":41,"t":"(Zekeriya) “Rabbim! (Bu konuda) bana bir delil ver.” demişti. (Melek) “Senin delilin, işaret (etmen) dışında insanlarla üç gün konuşamamandır.” demişti. Rabbini çok an; akşam sabah (O’nu) tesbih et (yücelt)!"},{"n":42,"t":"Hani melekler şöyle demişlerdi: “Ey Meryem! Şüphesiz ki Allah seni seçti; seni tertemiz yarattı ve seni âlemlerin kadınlarının üzerine seçti."},{"n":43,"t":"Ey Meryem! Rabbine gönülden itaat et! Secde et; rükû edenlerle birlikte rükû et!”"},{"n":44,"t":"Bu(nlar), sana vahyetmekte olduğumuz gayb (bilinemeyen) haberlerindendir. İçlerinden hangisi Meryem’i himayesine alacak diye (kura çekmek için) kalemlerini atarlarken sen yanlarında değildin. Onlar (bu konuda) çekişirken de yanlarında değildin."},{"n":45,"t":"Hani melekler şöyle demişlerdi: “Ey Meryem! Şüphesiz ki Allah sana kendisinden bir kelimeyi müjdeliyor ki adı Mesih (yani) Meryem oğlu İsa’dır; dünyada da ahirette de itibarlıdır ve (Allah’a) yakın kılınanlardandır.”"},{"n":46,"t":"O, beşikte de yetişkinliğinde de insanlara konuşacak ve iyilerden (olacak)."},{"n":47,"t":"(Meryem) “Rabbim! Bana hiçbir insan dokunmamışken nasıl (bir) çocuğum olabilir ki?” demiş, (melekler ise) şöyle demişlerdi: “Öyle, (ama) Allah dilediğini yaratır. Bir işe hükmettiği zaman ona sadece ‘Ol!’ der, o da hemen olmaya başlar.”"},{"n":48,"t":"(Allah) ona Kitab'ı, hikmeti (doğru hüküm verme yeteneğini), Tevrat’ı ve İncil’i öğretecek."},{"n":49,"t":"İsrailoğullarına bir elçi olarak (görevlendirilecek olan İsa şöyle demişti): “Şüphesiz ki ben size Rabbinizden elbette delil getirmiş (olacağım). Şüphesiz ki ben size çamurdan bir kuş şeklinde bir şey (heykel) yapacağım, ona üfleyeceğim, o da Allah’ın izni ile kuş olacak. (Yine) Allah’ın izni ile körü ve (teni) alacalıyı iyileştirecek, ölüleri dirilteceğim. Evlerinizde ne yiyip ne biriktirdiğinizi size bildirereceğim. İnananlarsanız şüphesiz ki bunda sizin için bir delil vardır."},{"n":50,"t":"Önümdeki Tevrat’ı(n aslını) doğrulayıcı olarak ve size haram kılınan bazı şeyleri de helal kılmam için (gönderildim). Size Rabbinizden bir delil getirdim. Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":51,"t":"Şüphesiz ki Allah benim de Rabbimdir; sizin de Rabbinizdir. O’na kulluk edin! Doğru yol budur.”"},{"n":52,"t":"İsa, onlardaki inkârcılığı sezince “Allah’a doğru (giden yolda) kim bana yardımcı olacak?” demiş, Havariler de “Biz Allah’ın (yolunun) yardımcılarıyız; Allah’a iman ettik. Şahit ol ki biz müslümanlarız” demişlerdi."},{"n":53,"t":"(Havariler demişti ki:) “Rabbimiz! İndirdiğine inandık ve o Elçiye uyduk. Bizi şahitlerle birlikte yaz.”"},{"n":54,"t":"Onlar (yahudiler) tuzak kurdu. Allah da (buna karşı) tuzak kurdu. Allah tuzak kuranların en hayırlısıdır."},{"n":55,"t":"Hani Allah şöyle demişti: “Ey İsa! Şüphesiz ki seni ben vefat ettireceğim; seni bana (katıma) yükselteceğim; seni kâfir olanlardan arındıracağım ve sana uyanları kâfir olanlardan kıyamet gününe kadar üstün kılacağım. Sonunda dönüşünüz sadece banadır ve ayrılığa düştüğünüz şeyler hakkında aranızda ben hüküm vereceğim.”"},{"n":56,"t":"Kâfir olanlar var ya, onlara dünyada da ahirette de şiddetli bir azapla azap edeceğim; onların hiçbir yardımcısı da yoktur."},{"n":57,"t":"İman edip iyi işler yapanlara gelince, (Allah) onların ödüllerini tastamam verecektir. Allah zalimleri sevmez."},{"n":58,"t":"Bu, sana tilavet etmekte (okuyup aktarmakta) olduğumuz ayetlerden ve doğru hükümler içeren hatırlatma(lar)dandır."},{"n":59,"t":"Allah katında İsa’nın örneği, Âdem’in örneği gibidir. (Allah) onu topraktan yarattı. Sonra ona “Ol!” dedi, o da hemen olmaya başladı."},{"n":60,"t":"Gerçek, Rabbinden (gelen)dir. Sakın şüphe edenlerden olma!"},{"n":61,"t":"Sana bilgi geldikten sonra seninle bu konuda tartışanlara de ki: “Gelin, biz ve siz, çocuklarımızı ve çocuklarınızı, kadınlarımızı ve kadınlarınızı çağıralım; sonra da Allah’ın lanetinin yalancılar üzerine olması için gönülden lanetleşelim.”"},{"n":62,"t":"Şüphesiz ki bu, (İsa hakkındaki) gerçek haberlerin ta kendisidir. Allah’tan başka ilah yoktur. Şüphesiz ki Allah -evet O- güçlüdür, doğru hüküm verendir."},{"n":63,"t":"Yüz çevirirlerse, şüphesiz ki Allah bozguncuları bilendir."},{"n":64,"t":"De ki: “Ey kitap ehli! Sizinle bizim aramızdaki eşit (ortak) bir söze gelin: Allah’tan başkasına kulluk etmeyelim; O’na hiçbir şeyi ortak koşmayalım. Kimimiz kimimizi Allah’ın peşi sıra rabler edinmeyelim!” Yüz çevirirlerse (kitap ehline) “Şahit olun ki biz müslümanlarız” deyin."},{"n":65,"t":"Ey kitap ehli! İbrahim hakkında niçin tartışıyorsunuz? (Oysa) Tevrat ve İncil ondan sonra indirilmişti. Akıl etmiyor musunuz?"},{"n":66,"t":"İşte siz böyle kişilersiniz! Hakkında bilgi sahibi olduğunuz konuda tartıştınız (da), hakkında hiçbir bilgi sahibi olmadığınız konuda niçin tartışıyorsunuz! Allah bilir, siz bilmezsiniz."},{"n":67,"t":"İbrahim ne yahudi ne de hristiyandı fakat o, hanîf (Allah’ı birleyen) bir müslümandı ve müşriklerden değildi."},{"n":68,"t":"İnsanların İbrahim’e en yakın olanı, ona uyanlar, şu peygamber (Muhammed) ve (ona) iman edenlerdir. Allah müminlerin dostudur."},{"n":69,"t":"Kitap ehlinden bir kısmı, sizi saptırmak istemişlerdi. (Oysa) onlar sadece kendilerini saptırırlar ve farkına (bile) varmazlar."},{"n":70,"t":"Ey kitap ehli! (Gerçeği) gördüğünüz hâlde Allah’ın ayetlerini niçin inkâr ediyorsunuz?"},{"n":71,"t":"Ey kitap ehli! Neden gerçeği batılla karıştırıyor ve gerçeği bilerek gizliyorsunuz?"},{"n":72,"t":"Kitap ehlinden bir grup şöyle demişti: “Müminlere indirilmiş olana gündüzün önünde (sabah) inanıp, sonunda (akşam) inkâr edin! (Böylece) belki onlar (dinlerinden) dönerler."},{"n":73,"t":"Sizin dininize uyanlardan başka kimseye inanmayın!” (Onlara) de ki: “Şüphesiz ki (gerçek) rehberlik, Allah’ın rehberliğidir.” (O grup:) “Birine size verilenin benzerinin verilmesinden dolayı veya Rabbinizin huzurunda (aleyhinize) deliller getirecekleri için mi (böyle söylüyorsunuz)?” (Onlara) de ki: “Lütuf, Allah’ın elindedir. Onu dilediğine (layık olana) verir. Allah (imkânları) geniş olandır, bilendir."},{"n":74,"t":"(Allah) rahmetini dilediğine (layık olana) özgü kılar. Allah büyük lütuf sahibidir.”"},{"n":75,"t":"Kitap ehlinden öylesi vardır ki ona yığınla mal emanet etsen, onu sana (tastamam geri) öder. Onlardan öylesi de vardır ki ona bir dinar emanet etsen, başına dikilmediğin sürece onu sana (geri) ödemez. Bunun sebebi, “Ümmilere karşı (yaptıklarımızdan dolayı) bize hiçbir yol (sorumluluk) yoktur.” demeleridir. Onlar Allah hakkında bilerek yalan söylüyorlar."},{"n":76,"t":"Aksine kim sözünü yerine getirir ve takvâlı (duyarlı) davranırsa, şüphesiz ki Allah muttakîleri (duyarlı olanları) sever."},{"n":77,"t":"Allah’a verdikleri sözü ve yeminlerini az bir değer karşılığında satanlar (var ya), onların ahirette hiçbir payı yoktur. Allah kıyamet gününde onlara konuşmayacak, onlara bakmayacak ve onları temize çıkarmayacaktır. Onlar için elem verici bir azap vardır."},{"n":78,"t":"Şüphesiz ki onlardan (kitap ehlinden) bir grup, (okuduklarını) kitaptan sanasınız diye Kitab'ı (Tevrat’ı okurken) dillerini eğip bükerler. (Oysa) o (okudukları), Kitaptan (Tevrat’tan) değildir. (Söyledikleri) Allah katından olmadığı hâlde “O, Allah katındandır.” derler. Allah hakkında bilerek yalan söylerler."},{"n":79,"t":"Allah’ın kendisine Kitap, hikmet (doğru hüküm verme yeteneği) ve peygamberlik vermesinden sonra hiçbir insanın, insanlara “Allah’ın peşi sıra bana kullar olun!” demesi mümkün değildir. Aksine (şöyle derler): “Kitabı (okuyup) öğreterek ve (ondan) ders yaparak kendini Rabbe adayan kullar olun!”"},{"n":80,"t":"(Hiçbir peygamber) size “Melekleri ve peygamberleri rabler edinin.” diye de emretmez. Siz müslüman olduktan sonra (peygamberler) size kâfirliği emreder mi (hiç)!"},{"n":81,"t":"Hani Allah peygamberlerden “Ben size Kitap ve hikmet (doğru hüküm verme yeteneği) verdikten sonra beraberinizdekileri onaylayan bir elçi geldiğinde ona mutlaka inanacak ve yardım edeceksiniz.” diye söz almıştı. “Bunu kabul ettiniz mi? Bu ağır sözümü üstlendiniz mi?” dediğinde, “Kabul ettik.” demişlerdi. (Bunun üzerine Allah) “(Birbirinize) şahit olun! Ben de sizinle birlikte şahitlik edenlerdenim.” demişti."},{"n":82,"t":"Bundan sonra kim dönerse, işte onlar yoldan çıkmışların ta kendileridir."},{"n":83,"t":"Göklerde ve yerdekiler ister istemez yalnızca O’na teslim olduğu hâlde, onlar (kitap ehli), Allah’ın dininden başkasını mı arıyorlar? (Oysa) yalnızca O’na döndürülecekler."},{"n":84,"t":"(Onlara) de ki: “Biz Allah’a, bize indirilene; İbrahim’e, İsmail’e, İshak’a, Yakup’a ve (onların) torunlarına indirilene; Rableri tarafından Musa’ya, İsa’ya ve (diğer) peygamberlere verilenlere inandık. Onlardan hiçbiri arasında fark gözetmeyiz. Biz yalnızca O’na (Allah’a) teslim olanlarız.”"},{"n":85,"t":"Kim İslam’dan başka bir din ararsa, (bilsin ki bu) kendisinden asla kabul edilmeyecektir ve ahirette o, kaybedenlerden (olacak)tır."},{"n":86,"t":"İman etmelerinden, Elçinin gerçek olduğuna şahit olmalarından ve kendilerine apaçık deliller gelmesinden sonra (hâlâ) inkâr eden bir toplumu Allah nasıl doğru yola ulaştırır (ki)! Allah o zalimler topluluğunu doğru yola ulaştırmaz."},{"n":87,"t":"İşte onların cezası, şüphesiz ki Allah’ın, meleklerin ve bütün insanların lanetinin onların üzerine olmasıdır."},{"n":88,"t":"Onlar orada (lanet içinde) ebedî kalıcıdır. Azapları hafifletilmez ve onlara bakılmaz."},{"n":89,"t":"Ancak bundan sonra tevbe edip kendilerini düzeltenler hariçtir. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":90,"t":"İmandan sonra inkâr edip sonra da inkârda ileri gidenlerin tevbeleri asla kabul edilmez. İşte onlar sapkınların ta kendileridir."},{"n":91,"t":"Şüphesiz ki inkâr edip kâfir olarak ölenler var ya -dünya dolusu altını fidye olarak verse bile- (bu fidye) hiçbirinden asla kabul edilmeyecektir. Onlar için elem verici bir azap vardır; onların yardımcıları da yoktur."},{"n":92,"t":"Sevdiğiniz şeylerden (Allah yolunda) infak edinceye (verinceye) kadar asla iyiliğe ulaşamazsınız. Şüphesiz ki Allah her neyi infak ederseniz (verirseniz) onu bilendir."},{"n":93,"t":"Tevrat indirilmeden önce, İsrail’in (Yakup’un) kendisine haram kıldıkları dışında, İsrailoğullarına bütün yiyecekler helaldi. De ki: “Doğruysanız o zaman Tevrat’ı getirip onu okuyun!”"},{"n":94,"t":"Bundan sonra kim Allah’a yalan söylerse, işte onlar zalimlerin ta kendileridir."},{"n":95,"t":"De ki: “Allah doğruyu söylemiştir. hanîf (Allah’ı birleyen) olarak İbrahim’in milletine (dinine) uyun! O, müşriklerden değildi.”"},{"n":96,"t":"Şüphesiz ki insanlar için kurulan ilk ev (mabet), âlemlere bereket ve hidayet kaynağı olan Bekke’deki (Kâbe)’dir."},{"n":97,"t":"Onda apaçık deliller, (örneğin) İbrahim’in makamı vardır. Oraya giren güvende olur. Yoluna gücü yetenlerin o Evi haccetmesi, Allah’ın insanlar üzerindeki bir (hakkı)dır. Kim (haccın farz olduğunu) inkâr ederse, şüphesiz ki Allah bütün âlemlerden zengindir (muhtaç değildir)."},{"n":98,"t":"De ki: “Ey kitap ehli! Allah yaptıklarınıza şahitken, Allah’ın ayetlerini niçin inkâr ediyorsunuz?”"},{"n":99,"t":"De ki: “Ey kitap ehli! (Gerçeğe) şahit olduğunuz hâlde onu (Allah’ın yolunu) eğri göstermeye yeltenerek iman edenleri niçin Allah’ın yolundan engelliyorsunuz? Allah yaptıklarınızdan habersiz değildir.”"},{"n":100,"t":"Ey iman edenler! Kendilerine kitap verilenlerden bir gruba uyarsanız, imanınızdan sonra sizi kâfirliğe döndürürler."},{"n":101,"t":"Allah’ın ayetleri size tilavet edilirken (aktarılırken), Elçisi de aranızdayken nasıl inkâr edersiniz! Kim Allah’a sarılırsa elbette doğru yola ulaştırılmıştır."},{"n":102,"t":"Ey iman edenler! Allah’a karşı, O’na yakışır şekilde takvâlı (duyarlı) olun! Müslümanlar olmanın dışında ölmeyin!"},{"n":103,"t":"Hep birlikte Allah’ın ipine (Kur’an’a) sımsıkı sarılın; ayrılmayın! Allah’ın size olan nimetini hatırlayın: Hani siz birbirinize düşmandınız da kalplerinizi birleştirmişti ve O’nun nimeti sayesinde kardeşler olmuştunuz. Ateşten bir çukurun tam kenarındayken oradan da sizi kurtarmıştı. Allah doğru yolu bulasınız diye ayetlerini size işte böyle açıklıyor."},{"n":104,"t":"Hayra çağıran, iyiliği emredip (öğütleyip) kötülükten engelleyen (sakındıran) bir ümmet olun! İşte onlar kurtulanların ta kendileridir."},{"n":105,"t":"Kendilerine apaçık deliller geldikten sonra ayrılığa düşüp parçalananlar gibi olmayın! İşte onlar için büyük bir azap vardır."},{"n":106,"t":"O gün (bazı) yüzler ağarır, (bazı) yüzler (de) kararır. Yüzleri kararanlara “İmanınızdan sonra kâfir mi oldunuz! İnkâr etmenize karşılık azabı tadın!” (denecektir)."},{"n":107,"t":"Yüzleri ağaranlar ise Allah’ın merhametindedir; onlar orada ebedî kalıcıdır."},{"n":108,"t":"İşte bunlar, Allah’ın sana bir gerçek olarak tilavet etmekte (okuyup aktarmakta) olduğumuz ayetleridir. Allah âlemlere (yarattıklarına) haksızlık etmek istemez."},{"n":109,"t":"Göklerde olanlar da yerde olanlar da yalnızca Allah’a aittir. Bütün işler sadece Allah’a döndürülecektir."},{"n":110,"t":"Siz, insanlar için çıkarılmış en hayırlı ümmetsiniz (topluluksunuz): İyiliği emreder (öğütler), kötülükten engeller (sakındırır) ve Allah’a inan(ıp güvenir)siniz. Kitap ehli de inan(ıp güven)seydi, elbette bu kendileri için hayırlı olurdu. İçlerinden inanıp (güvenenler) de var; (fakat) çoğu yoldan çıkmışlardır."},{"n":111,"t":"Onlar (kitap ehli), size sıkıntı vermekten başka hiçbir zarar veremezler. Sizinle savaşsalar, size arkalarını dönüp (kaçar)lar. Sonra onlara yardım da edilmez."},{"n":112,"t":"Onlar (yahudiler) nerede bulunurlarsa bulunsunlar, Allah’ın ipine (sözüne) ve insanların (müminlerin) ipine (sözleşmesine) sığınmanın dışında kendilerine alçaklık (damgası) vurulmuştur. (Onlar) Allah’ın gazabına uğramış ve çaresizliğe mahkûm edilmiştir. Zira onlar Allah’ın ayetlerini inkâr ediyor ve peygamberleri haksız yere öldürüyordu. Çünkü isyan etmiş ve haddi aşmışlardı."},{"n":113,"t":"(Ancak) hepsi aynı değildir. Kitap ehlinden gece saatlerinde secde ederek Allah’ın ayetlerini tilavet eden (okuyup aktaran), ayakta olan bir topluluk vardır."},{"n":114,"t":"Onlar Allah’a ve ahiret gününe iman eder; iyiliği emreder (öğütler), kötülükten engeller (sakındırır) ve iyi işlerde yarışırlar. İşte bunlar, iyilerdendir."},{"n":115,"t":"Yaptıkları hiçbir iyilik inkâr edilmeyecektir (karşılıksız bırakılmayacaktır). Allah muttakîleri (duyarlı olanları) bilendir."},{"n":116,"t":"Şüphesiz ki kâfir olanların malları da çocukları da Allah’a karşı onlara hiçbir şeyde asla yarar sağlamayacaktır. İşte onlar ateş halkıdır; onlar orada ebedî kalıcıdır."},{"n":117,"t":"Bu dünya hayatında yapmakta oldukları harcamaların durumu, kendilerine haksızlık etmiş olan bir toplumun ekinlerini vurup da mahveden kavurucu rüzgârın durumuna benzer. Onlara Allah haksızlık etmedi fakat onlar kendilerine haksızlık ediyorlar."},{"n":118,"t":"Ey iman edenler! Kendi dışınızdakileri sırdaş edinmeyin! Onlar size kötülük etmekten asla geri durmaz, hep sıkıntıya düşmenizi isterler. Kin ve düşmanlıkları ağızlarından (sözlerinden) elbette belli olmaktadır. Kalplerinde sakladıkları (düşmanlıkları) ise daha büyüktür. Akıl ediyorsanız, ayetlerimizi elbette size açıkladık."},{"n":119,"t":"İşte siz şöyle kişilersiniz ki kitabın tamamına inandığınız hâlde, onlar sizi sevmezken siz onları seviyorsunuz. Onlar sizinle karşılaştıklarında “İnandık.” derler. Kendi başlarına kaldıklarında da size olan kinlerinden dolayı parmaklarının uçlarını ısırırlar. De ki: “Kininizle (kahrolup) ölün! Şüphesiz ki Allah göğüslerin (kalplerin) özünü bilendir.”"},{"n":120,"t":"Size bir iyilik dokunsa, bu onları üzer; başınıza bir kötülük gelse buna da sevinirler. Sabreder ve takvâlı (duyarlı) olursanız onların hilesi size hiçbir zarar veremez. Şüphesiz ki Allah onların yaptıklarını çepeçevre kuşatandır."},{"n":121,"t":"Hani sen sabah erkenden müminleri savaş mevzilerine yerleştirmek için ailenden ayrılmıştın. Allah duyandır, bilendir."},{"n":122,"t":"Hani Allah onların yardımcısıyken içinizden iki grup bozulmaya yüz tutmuştu. Müminler, yalnızca Allah’a güvensinler!"},{"n":123,"t":"Yemin olsun ki siz güçsüz olduğunuz hâlde Allah, Bedir’de de size yardım etmişti. Öyle ise Allah’a karşı takvâlı (duyarlı) olun ki şükretmiş olasınız."},{"n":124,"t":"Hani sen müminlere şöyle diyordun: “İndirilen üç bin melekle Rabbinizin sizi desteklemesi, sizin için yeterli değil midir?”"},{"n":125,"t":"Evet, siz direnç gösterir ve Allah’a karşı takvâlı (duyarlı) olursanız, onlar (düşmanlarınız) hemen şu anda üzerinize gelseler, Rabbiniz, nişanlı beş bin melekle sizi destekler."},{"n":126,"t":"Allah bunu (meleklerle yardımı) size sadece bir müjde olsun ve onunla kalbiniz yatışsın diye yapmıştı. Zafer yalnızca güçlü, doğru hüküm veren Allah katındandır."},{"n":127,"t":"(Allah) kâfir olanlardan bir kısmının kenarını (kökünü) kessin veya onları perişan etsin de umutsuz olarak geri dönsünler diye (size yardım eder)."},{"n":128,"t":"O konuda senin yapacağın herhangi bir şey yoktur. (Allah) ya tevbelerini kabul edip (onları affeder) ya da onlara azap eder. Şüphesiz ki onlar, zalimlerdir."},{"n":129,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. (Allah) dileyeni (layık gördüğünü) bağışlar; dileyene (layık gördüğüne) azap eder. Allah çok bağışlayandır, çok merhametlidir."},{"n":130,"t":"Ey iman edenler! Kat kat artırılmış olarak faiz yemeyin! Allah’a karşı takvâlı (duyarlı) olun! Umulur ki kurtulursunuz."},{"n":131,"t":"Kâfirler için hazırlanmış (olacak cehennem) ateş(in)den korunun!"},{"n":132,"t":"Allah’a ve Elçi'ye itaat edin ki merhamete kavuşturulasınız."},{"n":133,"t":"Rabbinizin bağışlamasına ve muttakîler (duyarlı olanlar) için hazırlanmış (olacak), genişliği de gökler ve yer kadar olan cennete koşun!"},{"n":134,"t":"Onlar (muttakiler), bollukta da darlıkta da infak eder; öfkelerini yutar ve insanları affederler. Allah güzel davrananları sever."},{"n":135,"t":"Onlar, bir çirkinlik yaptıklarında veya kendilerine haksızlık ettiklerinde Allah’ı hatırlayıp günahlarından dolayı hemen bağışlanma dilerler. (Zaten) günahları Allah’tan başka kim bağışlayabilir ki! Onlar, işledikleri kötülüklerde bilerek ısrar etmezler."},{"n":136,"t":"İşte onların ödülü, Rableri tarafından bağışlanma ve altlarından ırmaklar akan, içinde ebedî kalacakları cennetlerdir. (İyi) iş yapanların ödülü ne güzeldir!"},{"n":137,"t":"Sizden önce (nice milletler hakkında, ilahi) kanunlar elbette gelip geçmiştir. (Onun için) yeryüzünde dolaşın; sonra yalanlayanların sonunun nasıl olduğuna bakın!"},{"n":138,"t":"Bu (Kur’an), bütün insanlığa bir açıklamadır; muttakîler (duyarlı olanlar) için de bir rehber ve bir öğüttür."},{"n":139,"t":"Gevşemeyin; hüzünlenmeyin! İnanıyorsanız üstünsünüz."},{"n":140,"t":"Size (Uhud’da) bir acı dokunduysa, (Bedir’de de) o kavme benzer bir acı dokunmuştu. O (sıkıntılı) günleri biz, insanlar arasında döndürür (durur)uz. Sonunda Allah iman edenleri bilir (ortaya çıkarır) ve aranızdan şahitler edinir. Allah zalimleri sevmez."},{"n":141,"t":"Bir de (böylece) Allah iman edenleri arındırır; kâfirleri de helak eder."},{"n":142,"t":"Yoksa siz Allah içinizden cihad edenleri (fedakârlık edenleri) ve sabredenleri bil(dir)ip (ortaya çıkarmadan) cennete gireceğinizi mi sandınız!"},{"n":143,"t":"Yemin olsun ki siz onunla karşılaşmadan önce ölümü temenni etmiştiniz. Bakıp dururken onu (karşınızda) gördünüz."},{"n":144,"t":"Muhammed sadece bir elçidir. Ondan önce de elçiler elbette geçmiştir. O ölür veya öldürülürse, topuklarınız üzerine (geriye, eski dininize) mi döneceksiniz? Kim (böyle) iki topuğu üzerine (geri) dönerse, (bilsin ki) Allah’a asla zarar veremeyecektir. Allah şükredenleri ileride ödüllendirecektir."},{"n":145,"t":"Her nefis belirlenmiş bir kitap (ilahî yasa) hâlinde yalnızca Allah’ın izniyle ölür. Kim dünya nimetini isterse, kendisine ondan veririz; kim de ahiret sevabını isterse, ona da bundan veririz. Biz, şükredenleri ileride ödüllendireceğiz."},{"n":146,"t":"Nice peygamberler vardı ki beraberinde kendilerini Rablerine adayanlar bulunduğu hâlde savaşmışlardı. Bunlar, Allah yolunda başlarına gelenlerden dolayı gevşeklik göstermemiş, (düşmanlarına karşı) boyun eğmemişlerdi. Allah (işte böyle) sabredenleri sever."},{"n":147,"t":"Onların sözleri, sadece şöyle demekten ibaretti: “Rabbimiz! Günahlarımızı ve işimizdeki taşkınlığımızı bağışla. Ayaklarımızı sabit tut! kâfirler topluluğuna karşı bize yardım et!”"},{"n":148,"t":"Allah da onlara dünya nimetini vermiştir; ahiret sevabının güzelliğini de vermiş (olacak)tır. Allah güzel davrananları sever."},{"n":149,"t":"Ey iman edenler! kâfir olanlara itaat ederseniz, sizi topuklarınız üzere (eski dininize) döndürürler ve kaybedersiniz."},{"n":150,"t":"(Oysa) Allah sizin mevlanız (efendiniz)dir. O, yardımcıların en hayırlısıdır."},{"n":151,"t":"Hakkında hiçbir delil indirmediği şeyleri Allah’a ortak koşmaları sebebiyle, kâfir olanların kalplerine yakında korku salacağız. Onların barınağı ateştir. Zalimlerin yeri ne kötüdür!"},{"n":152,"t":"Yemin olsun ki siz O’nun izni ile düşmanlarınızı öldürürken, Allah size olan sözünü yerine getirmiştir. Sonunda gevşeklik göstermiştiniz; (Allah) size sevdiğiniz (istediğiniz) şeyi gösterdikten sonra durum hakkında birbirinizle tartışmış ve isyan etmiştiniz. Dünyayı isteyeniniz de ahireti isteyeniniz de vardı. Sonra (Allah) denemek için sizi onlardan geri çevirmişti. Yemin olsun ki sizi bağışlamıştı. Allah müminlere çok lütufkârdır."},{"n":153,"t":"Hani elçi sizi diğerlerinizin arasında (arkanızdan) çağırdığı hâlde siz uzaklaşıyor, kimseye dönüp bakmıyordunuz. Kaybettiğiniz (zafere ve ganimet)e de başınıza gelenlere de üzülemeyesiniz diye (Allah, Elçisinin) kederi üzerine size keder vermişti. Allah yaptıklarınızdan haberdardır."},{"n":154,"t":"Sonra (Allah) o kederin arkasından size bir güven indirdi ki (bu güvenin yol açtığı) uyuklama hâli bir kısmınızı kaplıyordu. Kendi canlarının kaygısına düşmüş bir grup da Allah hakkında cahiliye devrindeki türden yanlış ve yersiz zanlara kapılmışlar ve “Bu işten bize ne var?” diyorlardı. De ki: “İş (karar), tamamen Allah’a aittir. Onlar, sana açıklayamadıklarını içlerinde gizliyorlar.” (Onlar) “Bu işten bize bir şey olsaydı, burada öldürülmezdik.” diyorlar. (Onlara) de ki: “Evlerinizde kalmış olsaydınız bile öldürülmesi yazılmış olanlar, yataklarına (düşecekleri yerlere) çıkıp giderlerdi. Allah göğüslerinizdekileri (kalplerinizdekileri) deneyip ortaya çıkarmak ve göğüslerinizdekileri (kalplerinizdekileri) arındırmak için (böyle yaptı). Allah göğüslerin (kalplerin) özünü bilendir.”"},{"n":155,"t":"(Uhud’da) iki ordu karşılaştığı gün sizi bırakıp gidenleri, işledikleri bazı hatalar yüzünden şeytan (yerlerinden) kaydırmıştı. Yemin olsun ki Allah onları affetmiştir. Şüphesiz ki Allah çok bağışlayandır, hoşgörülüdür."},{"n":156,"t":"Ey iman edenler! kâfir olanlar ve yeryüzünde sefere çıkan veya savaşan kardeşleri hakkında “Bizim yanımızda olsalardı ölmezler, öldürülmezlerdi.” diyenler gibi olmayın! Sonunda Allah bunu kalplerinde bir pişmanlık kılacak. Allah diriltir (hayat verir) ve öldürür. Allah yaptıklarınızı görendir."},{"n":157,"t":"Allah yolunda öldürülür veya ölürseniz, (şunu bilin ki) Allah’ın bağışlaması ve merhameti, onların topladıkları (dünyalıklar)dan elbette hayırlıdır."},{"n":158,"t":"Ölseniz de öldürülseniz de Allah’ın huzurunda elbette toplanacaksınız."},{"n":159,"t":"Allah’tan bir merhamet sebebiyle onlara yumuşak davranmıştın. Kaba, katı yürekli olsaydın, şüphesiz ki etrafından dağılırlardı. Onları affet; bağışlanmaları için dua et; iş(ler) hakkında onlarla istişarede bulun! Kararını verdiğin zaman da artık Allah’a güven! Şüphesiz ki Allah kendisine güvenenleri sever."},{"n":160,"t":"Allah size yardım ederse, artık size üstün gelecek kimse yoktur. Sizi bırakırsa, ondan sonra size kim yardım edebilir ki! Müminler, yalnızca Allah’a güvensinler!"},{"n":161,"t":"Hiçbir peygambere, (emanete) ihanet etmesi yakışmaz. Kim ihanet ederse, kıyamet günü, ihanet ettiği şey(in günahı ile) gelir. Sonra da haksızlığa uğratılmaksızın kazandıkları şeyler herkese tastamam ödenecektir."},{"n":162,"t":"Allah’ın rızasını gözeten ile Allah’tan bir gazaba uğrayan kişi bir olur mu hiç! Onun barınağı cehennemdir. Ne kötü varış yeridir (orası)!"},{"n":163,"t":"Onlar, Allah katında derece derecedir. Allah onların yaptıklarını görendir."},{"n":164,"t":"Şüphesiz ki içlerinden kendilerine (Allah’ın) ayetlerini tilavet etmekte (okuyup aktarmakta), onları (kötülüklerden) arındırmakta ve kendilerine Kitap ve hikmeti (doğru hükümleri) öğretmekte olan bir elçi göndermekle Allah müminlere büyük bir lütufta bulunmuştur. Onlar daha önce apaçık bir sapkınlık içindeydi."},{"n":165,"t":"(Bedir’de düşmanınızın) başına iki katını getirdiğiniz bir musibet, (Uhud’da) kendi başınıza geldiği için mi “Bu nasıl oluyor?” demiştiniz? De ki: “O kendi (kusuru)nuzdandır. Şüphesiz ki Allah her şeye gücü yetendir.”"},{"n":166,"t":"166-167 (Uhud’da) iki ordu karşılaştığı gün başınıza gelenler ancak Allah’ın izniyle olmuştur ki bu da müminleri (diğerlerinden) ayırt etmesi ve münafıkları ortaya çıkarması içindi. Onlara (münafıklara) “Gelin, Allah yolunda çarpışın veya savunma yapın!” dendiği zaman, “Savaşmayı (savaşın olacağını) bilseydik elbette size uyardık.” demişlerdi. Onlar (o gün) imandan çok küfre yakındı. Ağızlarıyla, kalplerinde olmayanı söylüyorlardı. (Oysa) Allah onların içlerinde gizlediklerini çok iyi bilendir."},{"n":167,"t":"166-167 (Uhud’da) iki ordu karşılaştığı gün başınıza gelenler ancak Allah’ın izniyle olmuştur ki bu da müminleri (diğerlerinden) ayırt etmesi ve münafıkları ortaya çıkarması içindi. Onlara (münafıklara) “Gelin, Allah yolunda çarpışın veya savunma yapın!” dendiği zaman, “Savaşmayı (savaşın olacağını) bilseydik elbette size uyardık.” demişlerdi. Onlar (o gün) imandan çok küfre yakındı. Ağızlarıyla, kalplerinde olmayanı söylüyorlardı. (Oysa) Allah onların içlerinde gizlediklerini çok iyi bilendir."},{"n":168,"t":"(Evlerinde) oturup da kardeşleri hakkında “Bize uysalardı öldürülmezlerdi.” diyorlardı. De ki: “Doğruysanız kendinizden ölümü savın!”"},{"n":169,"t":"Allah yolunda öldürülenleri sakın ölüler sanma(yın)! Aksine onlar diridir, Rableri katında rızıklandırılıyorlar."},{"n":170,"t":"Allah’ın lütfundan kendilerine verdikleri ile sevinçli bir hâlde arkalarından gelecek ve henüz kendilerine katılmamış olan (kardeşlerine de) hiçbir keder ve korku bulunmadığı müjdesinin sevincini duymaktadırlar."},{"n":171,"t":"Onlar, Allah’tan gelen nimet ve iyiliğin, (yani) Allah’ın, müminlerin ödülünü elbette ziyan etmeyeceği müjdesinin sevinci içindedir."},{"n":172,"t":"Yara aldıktan sonra yine de Allah’ın ve Elçi’nin çağrısına uyanlar (özellikle) bunların içlerinden iyilik yapanlar ve takvâlı (duyarlı) olanlar için büyük bir ödül vardır."},{"n":173,"t":"Bir kısım insanlar, müminlere “Düşmanlarınız olan insanlar, size karşı (asker) topladılar; aman onlardan sakının!” dediklerinde, bu (durum) onların (müminlerin) imanlarını artırmış ve “Allah bize yeter. O, ne güzel vekildir (güven kaynağıdır)!” demişlerdi."},{"n":174,"t":"(Bunun üzerine), kendilerine hiçbir sıkıntı dokunmadan, Allah’ın nimet ve iyiliğiyle geri dönmüş, Allah’ın rızasına uymuşlardı. Allah büyük iyilik sahibidir."},{"n":175,"t":"İşte o şeytan ancak kendi dostlarıyla (onların adını kullanarak) sizi korkutmaya çalışır. İman etmişseniz onlardan korkmayın, benden korkun!"},{"n":176,"t":"İnkârda yarışanlar seni üzmesin! Şüphesiz ki onlar, Allah’a asla zarar veremezler. Allah onlara ahirette bir pay vermemek istiyor. Onlar için büyük bir azap vardır."},{"n":177,"t":"Şüphesiz ki imana karşılık inkârı satın alanlar, Allah’a asla zarar veremezler. Onlar için elem verici azap vardır."},{"n":178,"t":"Kâfir olanlar sanmasınlar ki kendilerine zaman tanımamız, onlar için hayırlıdır. Onlara zaman tanıyoruz; sonunda günahlarını artıracaklar. Onlar için küçük düşürücü bir azap vardır."},{"n":179,"t":"Allah pisi (kötüyü) temizden ayırana kadar müminleri, (şu) bulunduğunuz durumda bırakacak değildir. Allah size gaybı (bilinemeyeni) bildirecek değildir. Fakat Allah elçilerinden dilediğini seçer. Allah’a ve elçilerine iman edin! İman eder, takvâlı (duyarlı) olursanız sizin için büyük bir ödül vardır."},{"n":180,"t":"Allah’ın, lütfundan kendilerine verdikleriyle ilgili olarak (infakta) cimrilik gösterenler, bunun kendileri için hayırlı olduğunu sanmasınlar; aksine bu, onlar için şerdir. Cimrilik ettikleri şey de kıyamet gününde boyunlarına dolanacaktır. (Oysa) göklerin ve yerin mirası yalnızca Allah’a aittir. Allah yapmakta olduklarınızdan haberdardır."},{"n":181,"t":"Şüphesiz ki Allah fakirmiş, biz ise zenginmişiz!” diyenlerin sözünü Allah kesinlikle duymuştur. Onların (hem bu) söylediklerini, (hem de) haksız yere peygamberleri öldürmelerini yazacağız ve (onlara) “Tadın o yakıcı azabı!” diyeceğiz."},{"n":182,"t":"“İşte bu, ellerinizin öne sunduğu şeyler yüzündendir.” (denecektir). Elbette Allah kullara asla haksızlık edici değildir."},{"n":183,"t":"(Yahudiler) “Doğrusu Allah bize, (gökten inen) ateşin yiyeceği (yakıp kor edeceği) bir kurban getirmedikçe hiçbir Elçi'ye inanmamamızı emretti.” demişlerdi. De ki: “Size, benden önce apaçık deliller, (özellikle) dediğiniz (konu) ve elçiler elbette gelmişti. Doğruysanız peki onları niçin öldürdünüz?”"},{"n":184,"t":"Seni yalanlarlarsa (üzülme)! Apaçık deliller, sahifeler ve aydınlatıcı kitabı getiren senden önceki elçiler de elbette yalanlanmıştı."},{"n":185,"t":"Her nefis (can), ölümü tadıcıdır. Kıyamet günü yaptıklarınızın karşılığı size elbette tastamam verilecektir. Kim cehennemden uzaklaştırılıp cennete konulursa, elbette o kurtulmuştur. Dünya hayatı, aldatıcı bir geçimlikten başka bir şey değildir."},{"n":186,"t":"Şüphesiz ki mallarınız ve canlarınız konusunda deneneceksiniz. Şüphesiz ki sizden önce kendilerine kitap verilenlerden ve müşriklerden birçok eziyet (verici sözler) duyacaksınız. Sabreder ve takvâlı (duyarlı) davranırsanız şüphesiz ki bu(nlar), kararlılık (göstermeye) değer işlerdendir."},{"n":187,"t":"Hani Allah kendilerine kitap verilenlerden, “Onu mutlaka insanlara açıklayacaksınız ve onu gizlemeyeceksiniz” diye söz almıştı. Onlar ise bunu sırtlarının arkasına atmışlar; onu az bir değer karşılığında satmışlardı. Yaptıkları alışveriş ne kadar kötüdür!"},{"n":188,"t":"Sanma ki yaptıklarına sevinen, yapmadıkları ile övülmek isteyenler, (evet) sanma ki onlar azaptan kurtulacaklardır! Onlar için elem verici bir azap vardır."},{"n":189,"t":"Göklerin ve yerin otoritesi yalnızca Allah’a aittir. Allah her şeye gücü yetendir."},{"n":190,"t":"Şüphesiz ki göklerin ve yerin yaratılmasında, gece ile gündüzün değişmesinde (birbiri peşine gelişinde) öz akıl sahipleri için dersler vardır."},{"n":191,"t":"Onlar, ayakta dururken, otururken, yanları üzerineyken (her zaman) Allah’ı hatırlar; göklerin ve yerin yaratılışı hakkında düşünür (ve şöyle derler:) “Rabbimiz! Sen bunu batıl olarak (boş yere) yaratmadın. Sen yücesin. Bizi cehennem azabından koru!"},{"n":192,"t":"Rabbimiz! Doğrusu sen kimi ateşe koyarsan, artık onu elbette rezil etmişsindir. Zalimler için hiçbir yardımcı yoktur."},{"n":193,"t":"Rabbimiz! Gerçek şu ki biz ‘Rabbinize inanın!’ diye imana çağıran davetçiyi duyduk ve hemen iman ettik. Rabbimiz! Bizim için günahlarımızı bağışla; kötülüklerimizi ört ve iyilerle birlikte (olacak şekilde) bizi vefat ettir!"},{"n":194,"t":"Rabbimiz! Bize, elçilerin vasıtasıyla vadettiklerini de ikram et ve kıyamet gününde bizi rezil etme! Şüphesiz ki sen sözünden dönmezsin.”"},{"n":195,"t":"Bunun üzerine Rableri, onlar(ın duaların)a şöyle cevap verdi: “Şüphesiz ki ben erkek olsun kadın olsun, içinizden çalışıp bir iş (fedakârlık) yapan kimsenin yaptığını ziyan etmeyeceğim. (Çünkü) hepiniz birbirinizdensiniz. Hicret edenler, yurtlarından çıkarılanlar, benim yolumda eziyete uğratılanlar, savaşanlar ve öldürülenler (var ya), şüphesiz ki ben de onların kötülüklerini örteceğim ve onları altlarından ırmaklar akan cennetlere koyacağım.” (Bu ödül), Allah tarafından bir sevap olarak (verilecektir). Karşılıkların güzeli yalnızca Allah katında olandır."},{"n":196,"t":"Kâfir olanların (refah içinde) diyar diyar dolaşması sakın seni aldatmasın!"},{"n":197,"t":"Azıcık bir menfaattır (o). Sonra onların barınağı cehennemdir. (Orası) ne kötü bir yataktır!"},{"n":198,"t":"Fakat Rablerine karşı takvâlı (duyarlı) olanlar için, Allah tarafından bir ikram olarak altlarından ırmaklar akan, ebedî kalacakları cennetler vardır. İyi kişiler için Allah katındaki (nimetler) hayırlı olandır."},{"n":199,"t":"Kitap ehlinden öylesi var ki Allah’a hem size indirilene hem de kendilerine indirilene Allah’a boyun eğerek iman ederler. Allah’ın ayetlerini az bir değer karşılığında satmazlar. İşte onlar için Rableri katında ödüller vardır. Şüphesiz ki Allah, hesabı hızlı olandır."},{"n":200,"t":"Ey iman edenler! Sabredin; (düşman karşısında) dayanışmada bulunun; (savaş için) hazırlıklı ve nöbette bulunun! Allah’a karşı takvâlı (duyarlı) olun ki kurtulasınız."}],[{"n":1,"t":"Ey insanlar! Sizi tek bir nefisten (candan/cevherden) yaratan, eşini de ondan yaratan; ikisinden birçok erkek ve kadın (meydana getirip) yayan Rabbinize karşı takvâlı (duyarlı) olun! Kendisiyle ilgili birbirinizden dilekte bulunduğunuz Allah’a ve yakınlara karşı takvâlı olun! Şüphesiz ki Allah üzerinizde gözetleyicidir."},{"n":2,"t":"Yetimlere (yetişkin olduklarında) mallarını verin! Temizi pis olanla değişmeyin! Onların mallarını kendi mallarınıza (katarak kendi malınızmış gibi) yemeyin! Şüphesiz ki o, büyük bir günahtır."},{"n":3,"t":"(Kendileriyle evlendiğiniz takdirde) yetimlerin haklarını gözetememekten korkarsanız beğendiğiniz (size helal olan) kadınlardan ikişer, üçer, dörder alın! Adil olamamaktan korkarsanız bir tane ile veya sahip olduğunuzla (yetinin)! Bu (davranış), adaletten ayrılmamanız için en uygun olanıdır."},{"n":4,"t":"Kadınlara mehirlerini gönül rızası ile (cömertçe) verin! Ondan (verdiğiniz mehirden) bir kısmını (gönül hoşluğu ile) size bağışlarlarsa onu da afiyetle yiyin!"},{"n":5,"t":"Allah’ın geçiminize dayanak kıldığı mallarınızı aklı ermezlere (muhakemesi henüz gelişmemiş olanlara) vermeyin! Onlarla (kendi mallarıyla) onları besleyin, giydirin ve onlara güzel söz söyleyin!"},{"n":6,"t":"Evlilik çağına gelinceye kadar yetimleri (gözetip) deneyin! Onlarda yetişkinlik görürseniz hemen mallarını kendilerine verin! Büyüyecekler (de geri alacaklar) diye onları (yetimlerin mallarını) israf ile ve tez elden yemeyin! Zengin olan (veli, yetimin malına) tenezzül etmesin; fakir olan da (ihtiyacına) uygun olarak yesin! Mallarını kendilerine verdiğiniz zaman onlarla ilgili şahit bulundurun! Hesap görücü olarak Allah yeter."},{"n":7,"t":"Gerek azından, gerek çoğundan belirli bir hisse olmak üzere, ana babanın ve yakınların bıraktıklarından erkeklere bir pay vardır; ana babanın ve yakınların bıraktıklarından kadınlara da bir pay vardır."},{"n":8,"t":"(Mirastan payı olmayan) yakınlar, yetimler ve yoksullar miras paylaşımında hazır bulunduğu zaman, bundan (mirastan) onları da rızıklandırın ve onlara güzel söz söyleyin!"},{"n":9,"t":"Geriye gücü yetmez nesiller bıraktıkları takdirde (hâlleri ne olur) diye endişe edenler, (yetimlere haksızlık etmekten de) korkup titresinler! Allah’a karşı takvâlı (duyarlı) olsun ve doğru söz söylesinler!"},{"n":10,"t":"Haksızlıkla yetimlerin mallarını yiyenler, şüphesiz karınlarında ancak ateş yemiş olur. Onlar, alevlenmiş ateşe girecektir."},{"n":11,"t":"Allah size, çocuklarınız hakkında, erkeğe, kadının payının iki misli gibi (miras vermenizi) emreder. (Çocuklar) ikiden fazla kadın iseler, (ölünün) bıraktığının üçte ikisi onlarındır. (Mirasçı) tek bir (kadın) ise (mirasın) yarısı onundur. Ölenin çocuğu varsa, ana babasından her birinin mirastan altıda bir payı vardır. Çocuğu yok da ana babası ona mirasçı olmuş ise annesine üçte bir (düşer). Ölenin kardeşleri varsa, annesine altıda bir (düşer. Bütün bu paylar, ölenin daha önce yapmış olduğu) vasiyetten ve/veya borçtan sonradır. Babalarınız ve oğullarınız(dan) hangisinin size yarar bakımından daha yakın olduğunu bilemezsiniz. (Bunlar) Allah tarafından belirlenmiş farzlardır (paylardır). Şüphesiz ki Allah bilendir, doğru hüküm verendir."},{"n":12,"t":"Çocukları yoksa eşlerinizin (hanımlarınızın) bıraktıklarının yarısı sizindir. Yapacakları vasiyetten ve/veya borçtan sonra, onların (eşlerinizin) çocukları varsa bıraktıklarının dörtte biri sizindir. Çocuklarınız yoksa bıraktıklarınızın dörtte biri onların (hanımlarınızın)dır. Çocuğunuz varsa, yapacağınız vasiyetten ve/veya borçtan sonra, bıraktığınızın sekizde biri onlarındır. Bir erkek veya hanım bir kelâle (annesi, babası ve çocukları bulunmayan kişi)nin malı mirasçılara kalırsa ve (başka bir anneden) bir erkek kardeşi veya bir kız kardeşi varsa her birine altıda bir düşer. (Kelâle durumundakinin kardeşleri) bundan fazla iseler, yapılacak vasiyetten ve/veya borçtan sonra üçte bire ortaktırlar. (Bu vasiyetler ve/veya borçlar) kimse zarara uğratılmaksızın ve Allah’tan size bir vasiyet (farz bir görev) olarak (yapılacak)tır. Allah bilendir, hoşgörülüdür."},{"n":13,"t":"İşte şu(nlar), Allah’ın (koyduğu) sınırlarıdır. Kim Allah’a ve Elçisine gönülden itaat ederse, (Allah) onu, içinde ebedî kalıcılar olarak altlarından ırmaklar akan cennetlere koyar. İşte bu, büyük kurtuluştur."},{"n":14,"t":"Kim Allah’a ve Elçisine isyan eder ve (Allah’ın) sınırlarını aşarsa, (Allah) onu, içinde ebedî kalacağı ateşe koyar. Onun için küçük düşürücü bir azap vardır."},{"n":15,"t":"Kadınlarınızdan çirkinlik (fuhuş) yapanlara karşı aranızdan dört şahit getirin! Şahitlik ederlerse, o (kadı)nları ölüm alıp götürünceye veya Allah onlar için bir yol açıncaya kadar evlerde hapsedin!"},{"n":16,"t":"İçinizden onu (o fuhşu) yapan iki erkeği de cezalandırın! tevbe eder, kendilerini düzeltirlerse artık onlardan (kendilerine ceza vermekten) vazgeçin! Şüphesiz ki Allah tevbeleri çok kabul edendir, çok merhametlidir."},{"n":17,"t":"Allah’ın kabul edeceği tevbe, sadece bilmeden kötülük edip sonra hemen tevbe edenlerin tevbesidir. İşte Allah bunların tevbesini kabul eder. Allah bilendir, doğru hüküm verendir."},{"n":18,"t":"Kötülükleri (sürekli) yapıp da içlerinden birine ölüm gelip çatınca “Ben şimdi tevbe ettim.” diyenler ile kâfir olarak ölmekte olanlar için (kabul edilecek) tevbe yoktur. Onlar için acı bir azap hazırlamış (olacağ)ız."},{"n":19,"t":"Ey iman edenler! Kadınlara zorla mirasçı olmanız size helal değildir. Apaçık bir çirkinlik yapmaları hariç, onlara verdiğinizin (mehrinizin) bir kısmını gidermeniz (geri almanız) için de onları sıkıştırmayın! Onlarla iyi geçinin! Onlardan hoşlanmazsanız, (bilin ki) sizin hoşlanmadığınız bir şeye Allah çok hayır koymuş olabilir."},{"n":20,"t":"Bir eşin yerine (başka) bir eş değiştirmek (yeni bir eş almak) isterseniz, onlardan birine yüklerle (mehir) vermiş olsanız bile ondan hiçbir şeyi (geri) almayın! İftira ederek ve (böylece) apaçık bir günah işleyerek onu (verdiğiniz mehri) geri alır mısınız!"},{"n":21,"t":"Daha önce birbirinizle içli dışlı olduğunuz ve (kendilerini koruyacağınıza dair nikâhta) sizden sağlam bir söz almış oldukları hâlde onu (verdiğiniz mehri) nasıl geri alırsınız ki!"},{"n":22,"t":"Geçmişte olanlar hariç, babalarınızın evlendiği kadınlarla evlenmeyin! Şüphesiz ki bu bir çirkinliktir; öfke (sebebi)dir ve çok kötü bir yoldur."},{"n":23,"t":"Anneleriniz, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kız kardeş kızları, sizi emziren (süt) anneleriniz, süt (emmekten dolayı oluşan) kız kardeşleriniz, kadınlarınızın (eşlerinizin) anneleri, kendileriyle (cinsel ilişki ile) birleştiğiniz kadınlarınızdan (eşlerinizden) olup evlerinizde bulunan üvey kızlarınız da size haram kılınmıştır. Onlarla (hanımlarla nikâhlanmış da) henüz (cinsel ilişki ile) birleşmemiş (ve onlardan boşanmış)sanız, (onların kızlarını almanızda) size herhangi bir vebal yoktur. Kendi neslinizden olan oğullarınızın helalleri (gelinleriniz) ve iki kız kardeşi (aynı anda) birlikte almak da (size haram kılındı). Ancak geçen geçmiştir. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":24,"t":"Sağ ellerinizin (yeminlerinizin) sahip oldukları hariç, Allah’ın size bir yazısı (emri) olarak evli kadınlar da (size haram kılınmıştır). Bunların ötesinde (başkasını), namuslu olmak ve zina etmemek üzere mallarınızla (mehirlerini vererek) istemeniz size helal kılınmıştır. Onlardan yararlanmanıza karşılık, kararlaştırılmış olan mehirlerini verin! mehir kesiminden sonra (bir miktar indirim için) karşılıklı anlaşmanızda size herhangi bir vebal yoktur. Şüphesiz ki Allah bilendir, doğru hüküm verendir."},{"n":25,"t":"İçinizden, imanlı özgür kadınlarla evlenmeye gücü yetmeyen kişi, ellerinizin altında bulunan imanlı genç kızlarınız (sayılan, yeminlerinizin sahip oldukların)dan (cariyelerinizden alsın)! Allah sizin imanınızı çok iyi bilendir. Hepiniz birbirinizdensiniz. Onları sahiplerinin izni ile nikâhlayın ve namuslu yaşamaları, zina etmemeleri ve gizli dost da tutmamaları şartı ile uygun bir şekilde mehirlerini de (bizzat) kendilerine verin! Evlendikten sonra bir çirkinlik (fuhuş) yaparlarsa, onlara hür kadınların cezasının yarısı (uygulanır). Bu (cariye ile evlenme emri), içinizden günaha düşmekten korkanlar içindir. Sabretmeniz ise sizin için hayırlı olandır. Allah çok bağışlayandır, çok merhametlidir."},{"n":26,"t":"Allah size (hükümleri) açıklamak, sizi sizden önceki (iyi)lerin yollarına ulaştırmak ve tevbenizi kabul etmek istiyor. Allah bilendir, doğru hüküm verendir."},{"n":27,"t":"Allah sizin tevbenizi kabul etmek istiyor; şehvetlerine uyanlar ise büyük bir sapkınlığa sapmanızı (tamamen yoldan çıkmanızı) istiyorlar."},{"n":28,"t":"Allah sizden (yükünüzü) hafifletmek istiyor; (çünkü) insan zayıf yaratılmıştır."},{"n":29,"t":"Ey iman edenler! Velev ki aranızdaki rızaya dayalı ticaretle bile olsa mallarınızı batıl (yollar) ile aranızda yemeyin ve kendinizi öldürmeyin! Şüphesiz ki Allah size karşı çok merhametlidir."},{"n":30,"t":"Kim düşmanlık ve haksızlık ile bunu (bu yasakları) yaparsa (bilsin ki) onu ateşe atacağız; bu ise Allah’a çok kolaydır."},{"n":31,"t":"Yasaklandıklarınızın büyüklerinden (büyük günahlardan) kaçınırsanız, küçük günahlarınızı örteriz ve sizi değerli bir yere koyarız."},{"n":32,"t":"Allah’ın sizi birbirinizden üstün kıldığı şeyleri arzu etmeyin! Erkeklerin de kazandıklarından bir payı vardır; kadınların da kazandıklarından bir payı vardır. Allah’ın lütfundan isteyin! Şüphesiz ki Allah her şeyi bilendir."},{"n":33,"t":"(Erkek ve kadından) her biri için, ana, baba ve yakınların bıraktığından (paylarını alacak olan) vârisler kıldık. Yeminlerinizin bağladığı kişilere (gelince), onlara da paylarını verin! Şüphesiz ki Allah her şeye şahittir."},{"n":34,"t":"Allah’ın onlardan (insanlardan) bir kısmını diğerlerine (farklı oldukları noktalarda) üstün kılması ve (bir de) mallarından harcama yapmaları sebebiyle erkekler, kadınların koruyucusudur. (Onun için) iyi kadınlar, (Allah’a) itaatkâr; Allah’ın (kendilerini) korumasına karşılık gizliyi (namuslarını) koruyanlardır. Geçimsizliğinden endişe ettiğiniz kadınlara gelince, onlara öğüt verin; onları yataklarda yalnız bırakın ve kendilerini (kısa süreli yanınızdan) uzaklaştırın! Size gönülden bağlanırlarsa artık onların aleyhine başka bir yol aramayın! Şüphesiz ki Allah yücedir, büyüktür."},{"n":35,"t":"(Buna rağmen) onların (eşlerin) aralarının açılmasından korkarsanız, (hem erkeğin) ailesinden bir hakem, (hem de kadının) ailesinden bir hakem gönderin! Bunlar, (eşlerin arasını) düzeltmeyi isterlerse Allah aralarını bulur. Şüphesiz ki Allah bilendir, haberdardır."},{"n":36,"t":"Allah’a ibadet edin ve O’na hiçbir şeyi ortak koşmayın! Ana babaya, yakınlara, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yakın arkadaşa, yolcuya, sağ ellerinizin sahip olduklarına iyilik (edin)! Şüphesiz ki Allah, kendini beğenmiş, övünüp duranı sevmez."},{"n":37,"t":"Onlar, cimrilik edip insanlara da cimriliği emreden, Allah’ın kendilerine lütfundan verdiğini gizleyen kişilerdir. Biz, kâfirler için küçük düşürücü bir azap hazırlamış (olacağız)."},{"n":38,"t":"Allah’a ve ahiret gününe inanmadıkları hâlde, mallarını, insanlara gösteriş için infak edenleri (verenleri) de (Allah sevmez). Şeytan bir kişiye arkadaş olursa, (bilsin ki) o, ne kötü bir arkadaştır!"},{"n":39,"t":"Allah’a ve ahiret gününe iman edip Allah’ın kendilerine verdiğinden (O’nun yolunda) infak etselerdi (verselerdi) ya! Allah onları(n durumunu) bilendir."},{"n":40,"t":"Şüphesiz ki Allah zerre kadar haksızlık etmez. (Kulun yaptığı iş) iyilik olursa (Allah) onu katlar (kat kat artırır) ve katından bir de büyük bir ödül verir."},{"n":41,"t":"Her ümmetten bir şahit getirdiğimiz ve seni de onlara şahit olarak getirdiğimiz zaman (hâlleri) nasıl olacak!"},{"n":42,"t":"İnkâr edip Elçi'ye isyan edenler, o gün yer(in dibin)e batırılmayı isterler; Allah’tan hiçbir haberi gizleyemezler."},{"n":43,"t":"Ey iman edenler! Sarhoşken –ne söylediğinizi bilinceye kadar–, –yolcu olanlar hariç– cünüpken de yıkanıncaya kadar salât’a (namaza) yaklaşmayın! Hastaysanız veya yolculuktaysanız veya sizden biriniz tuvaletten gelmişse ya da kadınlara (cinsel olarak) dokunup da (bu durumlarda) su bulamamışsanız, o zaman temiz bir toprak arayın ve yüzlerinizi de ellerinizi de (onunla) mesh edin! Şüphesiz ki Allah çok affedicidir, çok bağışlayandır."},{"n":44,"t":"Kitaptan kendilerine bir pay verilenleri (kitap ehlini) görmedin mi? Sapkınlığı satın alıyor ve yoldan sapmanızı istiyorlar."},{"n":45,"t":"Allah düşmanlarınızı çok iyi bilendir. Dost olarak Allah yeter; yardımcı olarak da Allah yeter."},{"n":46,"t":"Yahudilerden bir kısmı kelimelerin yerlerini değiştirir; (Peygambere karşı) dillerini eğip bükerek ve dine saldırarak “İşittik ve karşı geldik”, “Dinle, dinlemez olası!” ve (bir de) ‘Râ‘ınâ’ (bize çobanlık et) derler. Onlar “İşittik, itaat ettik”, “(Bizi) dinle.” ve “Bizi gözet.” deselerdi, (bu ifadeler) kendileri için hayırlı ve çok doğru olurdu. Fakat inkârları sebebiyle Allah onları lanetlemiştir; artık azı inanır."},{"n":47,"t":"Ey kendilerine kitap verilenler! Birtakım yüzleri silerek arkalarına çevirmeden veya onları Cumartesi (yasağını çiğneyen) halk gibi lanetlemeden önce, elinizdekini (Tevrat’ın aslını) doğrulayıcı olarak indirdiğimize (Kur’an’a) iman edin! (Çünkü) Allah’ın emri yerine getirilmiştir."},{"n":48,"t":"Şüphesiz ki Allah kendisine ortak koşulmasını bağışlamaz; bundan başkasını, (diğer günahları) dilediği (layık olan) kimse için bağışlar. Allah’a ortak koşan kişi büyük bir günah(la) iftira etmiş olur."},{"n":49,"t":"Kendilerini temize çıkaranları görmedin mi? Hayır! Allah dileyeni (layık gördüğünü) temize çıkarır ve (onlar) en küçük bir haksızlığa uğratılmazlar."},{"n":50,"t":"Bak, nasıl da Allah’a yalan uyduruyorlar! Apaçık bir günah olarak bu (onlara) yeter!"},{"n":51,"t":"Kitaptan kendilerine bir pay verilenleri (kitap ehlini) görmedin mi? Putlara ve batıla (sahte ilahlara) iman ediyor; sonra da kâfir olanlar için “Bunlar, (Allah’a) iman edenlerden daha doğru yoldadır.” diyorlar!"},{"n":52,"t":"İşte onlar, Allah’ın lanetlediği (merhametinden uzaklaştırdığı) kişilerdir. Allah’ın lanet ettiğine hiçbir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların otoriteden herhangi bir payları mı varmış! Öyle olsaydı insanlara çekirdek filizi (kadar bile) vermezlerdi."},{"n":54,"t":"Yoksa onlar, Allah’ın lütfundan verdiği şeyler için insanlara haset mi ediyorlar! Elbette İbrahim’in soyuna Kitabı ve hikmeti (doğru hüküm verme yeteneğini) vermiş ve onlara büyük bir hükümdarlık lütfetmiştik."},{"n":55,"t":"Onlardan bir kısmı ona (İbrahim’e) inanmış; kimi de ondan yüz çevirmişti. (Onlara) kavurucu bir ateş olarak cehennem yeter."},{"n":56,"t":"Şüphesiz ki ayetlerimizi inkâr edenleri ileride ateşe atacağız. Derileri pişip dökülünce, onları başka derilerle değiştireceğiz ki azabı tatsınlar! Şüphesiz ki Allah güçlüdür, doğru hüküm verendir."},{"n":57,"t":"İman edip iyi işler yapanları da içlerinde ebedî kalmak üzere altlarından ırmaklar akan cennetlere koyacağız. Onlar için orada tertemiz eşler de vardır. Onları koyu (serinletici) bir gölgeye koyacağız."},{"n":58,"t":"Şüphesiz ki Allah size, emanetleri ehline vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emretmektedir. Allah size ne kadar güzel öğütler veriyor! Şüphesiz ki Allah duyandır, görendir."},{"n":59,"t":"Ey iman edenler! Allah’a itaat edin; Elçi'ye ve sizden olan emir sahiplerine de itaat edin! Bir konuda anlaşmazlığa düşerseniz Allah’a ve ahirete inanıyorsanız onu Allah’a ve Elçi'ye götürün! Bu (tutum) hem hayırlı olandır hem de sonuç itibarıyla daha güzeldir."},{"n":60,"t":"Sana indirilene ve senden önce indirilen(ler)e inandıklarını ileri sürenleri görmedin mi? Onu inkâr etmeleri emredilmiş olduğu hâlde Tağut’un (azgınlık edenin) önünde mahkemeleşmek istiyorlar. (Oysa) şeytan onları tamamen saptırmak istiyor."},{"n":61,"t":"Onlara “Allah’ın indirdiğine (Kitaba) ve Elçi'ye gelin (onlara başvuralım)” dendiği zaman, münafıkların senden iyice uzaklaştıklarını görürsün."},{"n":62,"t":"Elleriyle yaptıkları yüzünden başlarına bir musibet gelince, “Sadece iyilik ve uzlaştırma istedik.” diye (yalan yere) yemin ederek nasıl da hemen sana gelirler!"},{"n":63,"t":"Onlar, kalplerindekini Allah’ın bildiği kişilerdir. Onlardan yüz çevir! Kendilerine öğüt ver ve onlara, kendileri hakkında etkili söz söyle!"},{"n":64,"t":"Biz her elçiyi –Allah’ın buyruğu gereği– ancak kendisine itaat edilmesi için gönderdik. Onlar kendilerine haksızlık ettikleri zaman sana gelselerdi de Allah’tan bağışlanma dileselerdi, Elçi de onlar için bağışlanma dileseydi, Allah’ı, tevbeleri çok kabul edici, çok merhametli bulurlardı."},{"n":65,"t":"Hayır (onların yaptığı doğru değildir); Rabbine yemin olsun: Aralarında çıkan anlaşmazlık hakkında seni hakem kılıp sonra da verdiğin hükümden içlerinde hiçbir sıkıntı duymaksızın (onu) tamamen kabulleninceye kadar iman etmiş olmazlar."},{"n":66,"t":"Onlara “Kendinizi öldürün veya yurtlarınızdan çıkın.” diye emretmiş olsaydık, içlerinden azı hariç bunu yapmazlardı. Kendilerine verilen öğüdü yerine getirselerdi, (bu durum) onlar için hem hayırlı hem de (imanlarını) daha pekiştirici olurdu."},{"n":67,"t":"67-68 O zaman elbette kendilerine katımızdan büyük ödül verirdik ve onları elbette doğru yola ulaştırırdık."},{"n":68,"t":"67-68 O zaman elbette kendilerine katımızdan büyük ödül verirdik ve onları elbette doğru yola ulaştırırdık."},{"n":69,"t":"Kim Allah’a ve Elçi'ye itaat ederse işte onlar, Allah’ın kendilerine lütuflarda bulunduğu peygamberler, (gerçeği) doğrulayanlar, şahitler ve iyilerle beraberdir. Onlar, ne güzel arkadaştırlar!"},{"n":70,"t":"O lütuf Allah’tandır. Bilen olarak Allah yeter."},{"n":71,"t":"Ey iman edenler! Önleminizi alın; (ya) bölük bölük savaşa çıkın; veya (gerektiğinde) topyekün savaşın!"},{"n":72,"t":"İçinizden (savaş konusunda) ağırdan alanlar vardır. Size bir musibet gelirse, (böyleleri) “Elbette Allah bana lütfetti de onlarla birlikte bulunmadım.” der."},{"n":73,"t":"Allah’tan size herhangi bir lütuf gelirse, sanki sizinle onun arasında (görünüşte) bir sevgi (problemi) yokmuş gibi “Ah, keşke onlarla birlikte olsaydım da büyük bir başarı elde etseydim.” der."},{"n":74,"t":"Ahiret karşılığında dünya hayatını satanlar (feda edenler) Allah yolunda savaşsınlar! Kim Allah yolunda savaşır da öldürülür veya galip gelirse biz ona ileride büyük bir ödül vereceğiz."},{"n":75,"t":"Size ne oluyor da Allah yolunda ve “Rabbimiz! Bizi, halkı zalim olan bu şehirden çıkar; bize tarafından bir dost ver; bize katından bir yardımcı ver!” diyen zayıf düşürülmüş (zavallı) erkekler, kadınlar ve çocuklar uğrunda savaşmıyorsunuz!"},{"n":76,"t":"İman edenler Allah yolunda; kâfir olanlar ise Tağut (azgınlık yapanın) yolunda savaşırlar. Şeytanın dostlarına karşı savaşın! Şüphesiz ki şeytanın tuzağı zayıftır."},{"n":77,"t":"Kendilerine “Ellerinizi (savaştan) çekin; namazı kılın ve zekâtı verin!” denen kişileri görmedin mi? Onlara savaş farz kılınınca, içlerinden bir grup hemen Allah’tan korkar gibi, hatta daha fazla bir korku ile insanlardan korkmaya başladılar da “Rabbimiz! Savaşı bize niçin yazdın! Bizi yakın bir süreye kadar ertelesen olmaz mıydı?” dediler. (Onlara) de ki: “Dünya geçimliği (hayatı) azdır; takvâlı (duyarlı) olanlar için ahiret hayırlı olandır. En küçük bir haksızlığa da uğratılmayacaksınız.”"},{"n":78,"t":"Nerede olursanız olun, sağlam kalelerde bile olsanız ölüm size ulaşır. Kendilerine herhangi bir iyilik gelse “Bu, Allah’tandır.” derler. Kendilerine herhangi bir kötülük geldiğinde ise “Bu, sendendir.” derler. De ki: “Hepsi Allah’tandır. Bu topluluğa ne oluyor ki neredeyse hiçbir sözü anlamıyorlar!”"},{"n":79,"t":"(Bu yüzden hâlâ şöyle diyorlar:) “Sana gelen her bir iyilik Allah’tandır. Başına gelen her bir kötülük ise nefsindendir.” Seni (bütün) insanlara elçi olarak gönderdik; (buna) şahit olarak Allah yeter."},{"n":80,"t":"Kim Elçi'ye itaat ederse elbette Allah’a itaat etmiş olur. Yüz çevirene gelince, biz seni onların üzerine bekçi göndermedik."},{"n":81,"t":"(Münafıklar) “Başüstüne!” derler. Yanından ayrılınca onlardan bir kısmı, senin dediğinden başkasını gizlice kurar. Allah da onların gizlice kurduklarını yazmaktadır. Sen onlardan yüz çevir (aldırma) ve Allah’a güven! Vekil (güven kaynağı) olarak Allah yeter."},{"n":82,"t":"Onlar Kur’an’ı iyice düşünmüyorlar mı? O, Allah’tan başkası katından (gönderilmiş) olsaydı, elbette onda birçok çelişki bulurlardı."},{"n":83,"t":"Onlara güven veya korkuya dair bir haber gelince hemen onu yayarlar. (Oysa) onu, Elçi'ye veya aralarında yetki sahibi kişilere götürselerdi, onların arasından işin içyüzünü anlayanlar, onun ne olduğunu bilirlerdi. Allah’ın size bol lütfu ve merhameti olmasaydı, azınız hariç elbette şeytana uyardınız."},{"n":84,"t":"Allah yolunda savaş! Sen (öncelikle) sadece kendinden sorumlusun. Müminleri de (savaşa) teşvik et! Allah kâfir olanların gücünü elbette kıracaktır. Allah’ın gücü (azabı) daha ağır ve cezası daha şiddetlidir."},{"n":85,"t":"Kim güzel bir şekilde şefaat (iyi bir işe öncülük) ederse onun o işten bir payı olur. Kim de kötü bir şekilde şefaat (kötü bir işe öncülük) ederse onun da ondan bir payı olur. Allah her şeyin karşılığını vericidir."},{"n":86,"t":"Bir selam ile selamlandığınız zaman, siz de ondan daha güzeli ile selamlayın; veya onu (o şekilde) karşılayın! Şüphesiz ki Allah her şeyin hesabını tutandır."},{"n":87,"t":"Allah –(ki) O’ndan başka ilah yoktur– sizi, varlığında şüphe olmayan kıyamet gününde elbette toplayacaktır. Allah’tan daha doğru sözlü kim olabilir ki!"},{"n":88,"t":"Size ne oluyor da münafıklar hakkında iki gruba ayrılıyorsunuz? (Oysa) Allah onları kendi kazandıkları sebebiyle baş aşağı etmiştir. Allah’ın saptırdığı (bu kişileri) siz mi doğru yola getirmek istiyorsunuz! Allah’ın saptırdığı kimse için asla bir (kurtuluş) yolu bulamazsın!"},{"n":89,"t":"Kendileri inkâr ettikleri gibi sizin de inkâr etmenizi istediler ki onlarla eşit olasınız. Allah yolunda hicret edinceye kadar onlardan hiçbirini dost edinmeyin! Yüz çevirirlerse onları bulduğunuz yerde yakalayın ve öldürün; onlardan hiçbir dost ve yardımcı edinmeyin!"},{"n":90,"t":"Ancak kendileriyle aranızda antlaşma bulunan bir topluma sığınanlar veya sizinle de kendi toplumlarıyla da savaşmak (istemediklerin)den yürekleri sıkılarak size gelenler hariçtir. Allah dileseydi onları da başınıza salardı da sizinle savaşırlardı. Onlar sizden ayrılır da sizinle savaşmazlar ve size barış teklif ederlerse, (bu durumda) Allah size, onların aleyhinde bir yol(a girme hakkı) vermemiştir."},{"n":91,"t":"Hem sizden hem de kendi toplumlarından emin olmak isteyen başkalarını da bulacaksınız. Bunlar (münafıklar), her ne zaman Fitneye (Müslümanlara karşı savaşa) götürülseler ona hemen dalarlardı. Sizden uzak durmaz, size barış teklif etmez ve ellerini (sizden) çekmezlerse, bulduğunuz yerde onları yakalayın ve öldürün! İşte onlar aleyhinde (onlarla savaşmak için) size apaçık yetki verdik."},{"n":92,"t":"Hata (kaza) ile olması dışında, bir müminin bir mümini öldürmeye hakkı olamaz. Hata ile bir mümini öldüren kimsenin, mümin bir köleyi özgürlüğüne kavuşturması ve ölenin ailesine teslim edilecek bir diyet vermesi gereklidir. Ancak (ölünün ailesinin o diyeti) bağışlaması başka. (Hata ile öldürülen kişi) mümin olduğu hâlde, düşmanınız olan bir toplumdan ise mümin bir köleyi özgürlüğüne kavuşturması gerekir. (Hata ile öldürülen kişi) kendileriyle aranızda antlaşma bulunan bir toplumdan ise ailesine teslim edilecek bir diyet ve bir mümin köleyi özgürlüğüne kavuşturması gerekir. (Bunları) bulamayan kimsenin, Allah tarafından tevbesi(nin kabulü) olarak iki ay peşpeşe oruç tutması (gerekli)dir. Allah bilendir, doğru hüküm verendir."},{"n":93,"t":"Kim bir mümini kasten öldürürse onun cezası, içinde ebedî kalacağı cehennemdir. Allah ona gazap etmiş, onu lanetlemiş ve onun için büyük bir azap hazırlamış (olacak)tır."},{"n":94,"t":"Ey iman edenler! Allah yolunda (savaş) yolculuğuna çıktığınız zaman (durumu) iyice araştırın! Size selam verene (barış teklif edene), dünya hayatının geçici menfaatine göz dikerek “Sen mümin değilsin!” demeyin! (Çünkü) Allah’ın katında sayısız ganimetler vardır. Önceden siz de böyleyken Allah size lütfetmişti; (durumu) iyice araştırın! Şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":95,"t":"95-96 Müminlerden –mazeret sahibi olanlar dışında– (savaşa katılmayıp evlerinde) oturanlarla, malları ve canlarıyla Allah yolunda cihad edenler (fedakârlık yapanlar) bir olmaz. Allah, malları ve canları ile cihad edenleri (fedakârlık yapanları), derece bakımından oturanlardan üstün kılmıştır. Allah hepsine en güzel olanı vadetmiştir. (Ancak) kendinden dereceler, bağışlama ve merhamet (şeklinde büyük bir ödül vererek), cihad edenleri (fedakârlık yapanları) oturanlardan çok daha büyük bir ödülle üstün kılmıştır. Allah çok bağışlayandır, çok merhametlidir."},{"n":96,"t":"95-96 Müminlerden –mazeret sahibi olanlar dışında– (savaşa katılmayıp evlerinde) oturanlarla, malları ve canlarıyla Allah yolunda cihad edenler (fedakârlık yapanlar) bir olmaz. Allah, malları ve canları ile cihad edenleri (fedakârlık yapanları), derece bakımından oturanlardan üstün kılmıştır. Allah hepsine en güzel olanı vadetmiştir. (Ancak) kendinden dereceler, bağışlama ve merhamet (şeklinde büyük bir ödül vererek), cihad edenleri (fedakârlık yapanları) oturanlardan çok daha büyük bir ödülle üstün kılmıştır. Allah çok bağışlayandır, çok merhametlidir."},{"n":97,"t":"Melekler, canlarını alırken kendilerine yazık eden kişilere “Neredeydiniz?” derler. Onlar “Biz yeryüzünde güçsüzdük.” derler. Onlar (melekler) “Allah’ın arzı (yeryüzü) geniş değil miydi? Hicret etseydiniz ya!” derler. İşte onların barınağı cehennemdir. Ne kötü varış yeridir (orası)!"},{"n":98,"t":"Hiçbir çareye gücü yetmeyen, (hicret için) hiçbir yol bulamayan zayıf düşürülmüş erkekler, kadınlar ve çocuklar hariç."},{"n":99,"t":"İşte umulur ki Allah onları affeder. Allah çok affedicidir, çok bağışlayandır."},{"n":100,"t":"Allah yolunda hicret eden kimse, yeryüzünde gidecek birçok yer ve bolluk (imkân) bulur. Kim Allah’a ve Elçisine (din uğrunda) hicret ederek evinden çıkar da sonra kendisine ölüm yetişirse elbette onun ödülü Allah’a ait olmuştur. Allah çok bağışlayandır, çok merhametlidir."},{"n":101,"t":"Yeryüzünde sefere çıktığınız zaman kâfir olanların size kötülük etmelerinden endişe ederseniz, namazı kısaltmanızda size herhangi bir günah (sorumluluk) yoktur. Şüphesiz ki kâfirler, sizin için apaçık düşmandır."},{"n":102,"t":"Sen de içlerinde bulunup onlara namaz kıldırdığın zaman, onlardan bir kısmı seninle birlikte namaza durup, silahlarını alsınlar (kuşansınlar); böylece secde ettiklerinde (namazı kıldıklarında diğerleri) arkanızda olsunlar! (Ardından henüz) namazını kılmamış olan diğer grup gelip seninle birlikte namazı kılsın, onlar da önlemlerini ve silahlarını alsınlar! O kâfir olanlar sizin silahlarınızdan ve eşyanızdan habersiz olmanızı ve üstünüze birden baskın yapmayı isterler. Size yağmurdan (dolayı) bir eziyet dokunur veya hasta olursanız silahlarınızı bırakmanızda size herhangi bir vebal yoktur. (Yine de) önleminizi alın! Şüphesiz ki Allah kâfirler için küçük düşürücü bir azap hazırlamış (olacak)tır."},{"n":103,"t":"Namazı bitirince de ayakta, otururken ve yanınız üzerinde yatarken (daima) Allah’ı hatırlayın! Güvene kavuşunca namazı (tam) kılın! Şüphesiz ki namaz, müminler üzerine vakitle yazılmış (bir farz)dır."},{"n":104,"t":"O (düşman) topluluğu takip etmekte gevşeklik göstermeyin! Siz acı çekiyorsanız, onlar da sizin çektiğiniz gibi acı çekmektedir. (Üstelik) siz Allah’tan, onların ümit etmedikleri şeyleri umuyorsunuz. Allah bilendir, doğru hüküm verendir."},{"n":105,"t":"Allah’ın sana gösterdiği şekilde insanlar arasında hükmedesin diye sana Kitabı (Kur’an’ı) bir amaç ile indirdik; hainlerden taraf olma!"},{"n":106,"t":"Allah’tan bağışlanma dile! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":107,"t":"Kendilerine ihanet edenleri savunma! Şüphesiz ki Allah günaha dalmış hainleri sevmez."},{"n":108,"t":"İnsanlardan gizlerler de Allah’tan gizleyemezler. (Oysa) geceleyin, O’nun razı olmadığı sözü düzüp kurarken, O onlarla beraberdir. Allah onların yaptıklarını çepeçevre kuşatandır."},{"n":109,"t":"Siz dünya hayatında onlara taraf olup savundunuz; peki kıyamet günü Allah’a karşı onları kim savunacak veya onlara kim vekil (güven kaynağı) olacakmış!"},{"n":110,"t":"Kim bir kötülük yaparsa veya nefsine haksızlık eder de sonra Allah’tan bağışlanma dilerse, Allah’ı çok bağışlayıcı, çok merhametli bulacaktır."},{"n":111,"t":"Kim bir günah kazanırsa onu sadece kendi aleyhine kazanmış olur. Allah bilendir, doğru hüküm verendir."},{"n":112,"t":"Kim küçük veya büyük bir günah kazanır da sonra onu bir suçsuzun üzerine atarsa, şüphesiz ki büyük bir iftira ve apaçık bir günah yüklenmiş olur."},{"n":113,"t":"Allah’ın sana lütfu ve merhameti olmasaydı, onlardan bir grup seni saptırmaya (şaşırtmaya) yeltenirdi. (Oysa) onlar, sadece kendilerini saptırır ve sana asla zarar veremezler. Allah sana Kitabı (Kur’an’ı) ve hikmeti (doğru hüküm verme yeteneğini) indirmiş, sana bilmediğini öğretmiştir. Allah’ın sana olan lütfu büyüktür."},{"n":114,"t":"Onların gizli toplantılarının birçoğunda hayır yoktur. Ancak bir sadaka veya bir iyilik veya insanların arasını düzeltmeyi emredenin (öğütleyenin gizli toplantısı) hariç! Kim Allah’ın rızasını elde etmek için bunu yaparsa, biz ona ileride büyük bir ödül vereceğiz."},{"n":115,"t":"Kendisi için doğru yol belli olduktan sonra, kim Elçi'ye karşı çıkar ve müminlerin yolundan başka bir yola giderse, onu (kendisinin) döndüğü yere döndürecek ve cehenneme atacağız. Ne kötü varış yeridir (orası)!"},{"n":116,"t":"Şüphesiz ki Allah kendisine ortak koşulmasını bağışlamaz; bundan başkasını, (diğer günahları) dilediği (layık olan) kimse için bağışlar. Allah’a ortak koşan kimse, elbette uzak bir sapkınlığa düşmüş (demek)tir."},{"n":117,"t":"117-118 (Müşrikler) O’nun (Allah’ın) peşi sıra birtakım dişilerden (dişi isimli putlardan) başkasına yalvarmıyorlar. Onlar, Allah’ın kendisine lanet ettiği inatçı şeytandan başkasına yalvarmıyorlar ki o şöyle demişti: “Şüphesiz ki kullarından belirli bir pay edineceğim."},{"n":118,"t":"117-118 (Müşrikler) O’nun (Allah’ın) peşi sıra birtakım dişilerden (dişi isimli putlardan) başkasına yalvarmıyorlar. Onlar, Allah’ın kendisine lanet ettiği inatçı şeytandan başkasına yalvarmıyorlar ki o şöyle demişti: “Şüphesiz ki kullarından belirli bir pay edineceğim."},{"n":119,"t":"Onları mutlaka saptıracağım, elbette onları boş kuruntulara boğacağım; elbette onlara emredeceğim (fısıldayacağım) ve hayvanların kulaklarını yaracaklar; elbette onlara emredeceğim ve Allah’ın yarattığını değiştirecekler.” Kim Allah’ın dışında (O’nu bırakır da) şeytanı dost edinirse, elbette apaçık bir şekilde kaybetmiştir."},{"n":120,"t":"(Şeytan) onlara söz verir ve onları ümitlendirir. (Oysa) şeytan, onlara aldanmadan başka bir şey vadetmemektedir."},{"n":121,"t":"İşte onların barınağı cehennemdir; ondan (kaçabilecek) herhangi bir sığınak da bulamayacaklardır."},{"n":122,"t":"İman edip iyi işler yapanları, Allah’ın gerçek bir vaadi olarak ileride içlerinde ebedî kalmak üzere altlarından ırmaklar akan cennetlere koyacağız. Allah’tan daha doğru sözlü kim olabilir ki!"},{"n":123,"t":"(Cennete giriş) sizin kuruntularınızla da kitap ehlinin kuruntularıyla da değildir. Kim bir kötülük yaparsa ona (yaptığının) karşılığı verilir ve kendisi için Allah’tan başka dost da yardımcı da bulamaz."},{"n":124,"t":"Erkek veya kadın kim mümin olarak iyi işlerden yaparsa, işte onlar cennete girer ve zerre kadar haksızlığa uğratılmazlar."},{"n":125,"t":"Güzel davranarak yüzünü (benliğini) Allah’a teslim eden ve din bakımından hanîf (Allah’ı birleyen) İbrahim’in milletine (dinine) uyandan daha güzel kim olabilir ki! (Nitekim) Allah, İbrahim’i dost edinmişti."},{"n":126,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir ve Allah her şeyi çepeçevre kuşatandır."},{"n":127,"t":"Senden kadınlar hakkında fetva istiyorlar. De ki: “Onlarla ilgili fetvayı size Allah şöyle vermektedir: Kitapta, kendileri için yazılmışı (farz kılınan mirası, mehri) vermeyip nikâhlamak istediğiniz kadınların yetimleri, zayıf bırakılmış (çaresiz) çocuklar ve yetimlere karşı adil davranmanız hakkında size tilavet edilmekte (okunup aktarılmakta) olan ayetler (Allah’ın hükmünü apaçık ortaya koymakta)dır. Her ne hayır (yardım) yaparsanız şüphesiz ki Allah onu bilendir.”"},{"n":128,"t":"Bir hanım, kocasının geçimsizliğinden veya kendisinden yüz çevirmesinden endişe ederse, aralarında tamamen bir barış yapmalarında onlara hiçbir vebal yoktur. Barış hayırlı olandır. Zaten nefisler kıskançlığa hazır kılınmıştır. Güzel davranır (iyi geçinir) ve takvâlı (duyarlı) olursanız, şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":129,"t":"Ne kadar uğraşsanız da kadınlar arasında adil davranmaya asla güç yetiremezsiniz; (eşlerinizin birisine) tamamen yönelip (diğerini) askıdaymış gibi bırakmayın! Kendinizi düzeltir ve takvâlı (duyarlı) davranırsanız, şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":130,"t":"(Eşler birbirlerinden) ayrılırlarsa, Allah bol nimetinden her birini zenginleştirir. Allah imkânı geniş olandır, doğru hüküm verendir."},{"n":131,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. Yemin olsun ki sizden önce kendilerine Kitap verilenlere de size de “Allah’a karşı takvâlı (duyarlı) olun!” diye emrettik. İnkâr ederseniz (bilin ki) göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. Allah zengindir, övgüye layık olandır."},{"n":132,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. Vekil (güven kaynağı) olarak Allah yeter."},{"n":133,"t":"Ey insanlar! Allah dilerse sizi giderir (yok eder) ve (yerinize) başkalarını getirir; Allah’ın buna gücü yeter."},{"n":134,"t":"Kim dünya sevabını (ödülünü) isterse (bilsin ki) dünyanın da ahiretin de sevabı (ödülü) yalnızca Allah katındadır. Allah duyandır, görendir."},{"n":135,"t":"Ey iman edenler! Adaleti (titizlikle) ayakta tutan, kendiniz, ana baba(nız) ve yakınlar(ınız) aleyhinde de olsa Allah için şahitlik eden kişiler olun! (Haklarında şahitlik ettikleriniz) zengin de fakir de olsalar Allah onlara (sizden) daha yakındır. Adalet(ten sapma) konusunda arzular(ınız)a uymayın! (Şahitliği) eğip büker (doğru şahitlik etmez) veya şahitlik etmekten kaçınırsanız, (bilin ki) şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":136,"t":"Ey iman edenler! Allah’a, Elçisine, Elçisine indirdiği Kitaba ve daha önce indirdiği kitaba (vahiylere) iman edip güvenin! Kim Allah’ı, meleklerini, kitaplarını, elçilerini ve son günü (ahiret gününü) inkâr ederse elbette uzak bir sapma ile sapmıştır."},{"n":137,"t":"Şüphesiz ki iman edip sonra inkâr edenler, sonra yine iman edip tekrar inkâr edenler, sonra da inkârlarını artıranlar var ya, Allah (işte) onları bağışlamayacak ve onları doğru yola ulaştırmayacaktır."},{"n":138,"t":"Münafıklara, kendileri için elem verici bir azap olduğunu müjdele!"},{"n":139,"t":"Müminleri bırakıp da kâfirleri dost edinenler, onların (kâfirlerin) yanında itibar mı arıyorlar? Bilsinler ki itibar bütünüyle ve yalnızca Allah’a aittir."},{"n":140,"t":"(Allah) Kitapta size şöyle (bir hüküm) indirmiştir: “Allah’ın ayetlerinin inkâr edildiğini ve/veya onlarla alay edildiğini duyduğunuz zaman, onlar bundan başka bir söze dalıncaya kadar onlarla birlikte oturmayın! (Aksi takdirde) şüphesiz ki siz de onlar gibi olursunuz. Şüphesiz ki Allah münafıkları ve kâfirleri cehennemde bir araya getirecektir.”"},{"n":141,"t":"(Münafıklar) sizi gözetleyip dururlar. Size Allah’tan bir zafer (nasip) olursa, “Sizinle birlikte değil miydik?” derler. Kâfirlerin (zaferde) bir payları olursa (bu sefer de onlara), “Sizi yenip (öldürebileceğimiz hâlde öldürmeyip) müminlerden korumadık mı?” derler. Allah kıyamet gününde aranızda hükmedecektir. Allah kâfirler için müminler aleyhine asla bir yol vermeyecektir."},{"n":142,"t":"Şüphesiz ki münafıklar, Allah’ı aldat(tıklarını san)ıyorlar; (Oysa) O onları(n kendilerini) aldat(masını sağlayand)ır. Onlar namaza kalktıkları zaman insanlara gösteriş yaparak üşenerek kalkarlar; azı hariç Allah’ı hatırlamazlar."},{"n":143,"t":"Bunların arasında bocalayıp durmaktalar; ne onlara (yakınlar) ne de bunlara! Allah’ın saptırdığı kimse için asla bir (kurtuluş) yolu bulamazsın."},{"n":144,"t":"Ey iman edenler! Müminleri bırakıp da kâfirleri dost edinmeyin! (Bunu yaparak) Allah’a, aleyhinizde apaçık bir delil mi vermek istiyorsunuz!"},{"n":145,"t":"Şüphesiz ki münafıklar, ateşin en alt tabakasındadır. Onlar için asla hiçbir yardımcı bulamazsın."},{"n":146,"t":"Ancak tevbe edip kendilerini düzeltenler, Allah’a sımsıkı sarılıp dinlerini (ibadetlerini) yalnız onun için yapanlar başkadır. İşte bunlar, müminlerle beraberdir. Allah müminlere ileride büyük bir ödül verecektir."},{"n":147,"t":"Siz şükredip iman ederseniz, Allah size neden azap etsin ki! Allah şükre çok karşılık verendir, bilendir."},{"n":148,"t":"Allah kötü sözün açıkça söylenmesini sevmez; haksızlığa uğrayan(ın sözü) hariç! Allah duyandır, bilendir."},{"n":149,"t":"Bir iyiliği açıklar veya gizlerseniz veya bir kötülüğü affederseniz (Allah bunları da bilir). Şüphesiz ki Allah çok affedicidir, gücü yetendir."},{"n":150,"t":"Allah’ı ve elçilerini inkâr edenler ve Allah ile elçilerini birbirinden ayırmak isteyip “Bir kısmına iman eder, bir kısmını inkâr ederiz!” deyip (iman ile küfür) arasında bir yol tutmak isteyenler var ya,"},{"n":151,"t":"İşte onlar gerçek kâfirlerdir. Biz, kâfirler için küçük düşürücü bir azap hazırlamış (olacağız)."},{"n":152,"t":"Allah’a ve elçilerine iman edip onlardan hiçbiri arasında ayrım yapmayanlara (gelince), işte Allah onlara ileride ödüllerini verecektir. Allah çok bağışlayandır, çok merhametlidir."},{"n":153,"t":"Kitap ehli, senden kendilerine gökten bir kitap indirmeni istiyor. Onlar Musa’dan bunun daha büyüğünü istemiş ve “Bize Allah’ı apaçık göster.” demişlerdi de haksızlıkları sebebiyle onları hemen yıldırım çarpmıştı. Ardından kendilerine apaçık ayetler (mucizeler) geldikten sonra buzağıyı (ilah) edinmişlerdi. Biz bunu da affetmiş, Musa’ya da apaçık bir delil vermiştik."},{"n":154,"t":"Söz vermeleri (ve sözlerinde durmamaları) nedeniyle üzerlerine (âdeta Sînâ) Dağı’nı kaldırmıştık. (Başka bir sefer) onlara, “Baş eğerek kapıdan girin!” demiştik. (Bir başka zaman da) onlara, “Cumartesi günü sınırı aşmayın!” demiştik. Kendilerinden sağlam bir söz almıştık."},{"n":155,"t":"Sözlerinden dönmeleri, Allah’ın ayetlerini inkâr etmeleri, haksız olarak peygamberleri öldürmeleri ve “Kalplerimiz perdelidir!” demeleri sebebiyle (onları cezalandırmıştık). Aksine (dahası), küfürleri sebebiyle Allah onlara (kalplere) mühür vurmuştur; azı hariç artık iman etmezler."},{"n":156,"t":"(Bir de) inkâr etmeleri ve Meryem’e büyük bir iftira atmalarından dolayı (onları cezalandırmıştık)."},{"n":157,"t":"(İsrailoğulları'nın) “Allah elçisi (olduğunu sanan) Meryem’in oğlu İsa’yı öldürdük!” demeleri yüzünden (onları cezalandırmıştık). (Oysa) onu öldürememiş ve çarmıha gerememişlerdi fakat kafaları karıştırılmıştı. Onun hakkında anlaşmazlığa düşenler bundan dolayı tam bir kararsızlık içindedir; bu konuda Zanna uymak dışında hiçbir (sağlam) bilgileri yoktu. Kesin olarak onu öldürememişlerdi."},{"n":158,"t":"Aksine Allah onu (İsa’yı) kendine (katına) yükseltmiştir. Allah güçlüdür, doğru hüküm verendir."},{"n":159,"t":"Kitap ehlinden her biri, (kendi) ölümünden önce ona (İsa’ya) elbette iman edecektir. Kıyamet gününde de (İsa), onlara (aleyhte) şahit olacaktır."},{"n":160,"t":"Yahudilerin (yaptıkları) haksızlıktan, bir de çok kimseyi Allah yolundan engellemelerinden dolayı kendilerine (daha önce) helal kılınmış bulunan temiz şeyleri onlara haram kılmıştık."},{"n":161,"t":"Kendilerine yasaklanmasına rağmen faizi almaları ve insanların mallarını batıl yollarla yemelerinden dolayı içlerinden kâfirler için elem verici bir azap hazırladık."},{"n":162,"t":"Fakat içlerinden ilimde derinleşmiş olanlar ve müminler, sana indirilene ve senden önce indirilen(ler)e iman eden, namazı kılan, zekâtı veren, Allah’a ve ahiret gününe inananlar var ya, işte onlara ileride büyük bir ödül vereceğiz."},{"n":163,"t":"Biz Nuh’a ve ondan sonraki peygamberlere vahyettiğimiz gibi sana da vahyettik. İbrahim’e, İsmail’e, İshak’a, Yakup’a, (onların) torunlarına, İsa’ya, Eyüp’e, Yunus’a, Harun’a ve Süleyman’a vahyetmiştik. Davud’a da Zebur’u vermiştik."},{"n":164,"t":"Daha önce sana kıssasını anlattığımız elçilere de kıssasını sana anlatmadığımız elçilere de (vahy etmiştik). Allah Musa’ya da tam anlamıyla konuşmuştu."},{"n":165,"t":"Müjdeleyiciler ve uyarıcılar olarak (gönderilen) elçilere de (vahy etmiştik) ki elçilerden sonra insanların Allah’a karşı herhangi bir delili (bahanesi) olmasın! Allah güçlüdür, doğru hüküm verendir."},{"n":166,"t":"Fakat Allah sana indirdiğini kendi ilmi ile indirdiğine şahitlik eder; melekler de (buna) şahitlik ederler. Şahit olarak Allah yeter."},{"n":167,"t":"Şüphesiz ki inkar edip (insanları) Allah yolundan alıkoyanlar elbette (doğru yoldan) tamamen uzaklaşmışlardır."},{"n":168,"t":"168-169 İnkâr edip haksızlık edenleri Allah asla bağışlayacak değildir. Onları içinde ebedî kalacakları cehennemin yolundan başka bir yola ulaştıracak da değildir. Bu, Allah’a çok kolaydır."},{"n":169,"t":"168-169 İnkâr edip haksızlık edenleri Allah asla bağışlayacak değildir. Onları içinde ebedî kalacakları cehennemin yolundan başka bir yola ulaştıracak da değildir. Bu, Allah’a çok kolaydır."},{"n":170,"t":"Ey insanlar! Elbette Elçi size Rabbinizden gerçeği getirdi; kendi iyiliğinize olarak (ona) iman edin! İnkâr ederseniz, göklerde ve yerde ne varsa şüphesiz ki hepsi yalnızca Allah’a aittir. Allah bilendir, doğru hüküm verendir."},{"n":171,"t":"Ey kitap ehli! Dininiz hakkında aşırı gitmeyin ve Allah hakkında, gerçek(ler)den başkasını söylemeyin! Mesih (yani) Meryem oğlu İsa, sadece Allah’ın elçisidir; (o) Allah’ın, Meryem’e ulaştırdığı kelimesidir; O’ndan bir rûhtur (mesajdır). Allah’a ve elçilerine iman edin! “(Tanrı) üçtür!” demeyin; sizin için hayırlı olmak üzere bundan vazgeçin! Yalnızca Allah’tır tek ilah. O, çocuk sahibi olmaktan yücedir. Göklerde ve yerde ne varsa hepsi yalnızca O’na aittir. Vekil (güven kaynağı) olarak Allah yeter."},{"n":172,"t":"Mesih (İsa) ve (Allah’a) yakınlaştırılmış melekler, Allah’ın kulu olmaktan geri durmazlar. Kim O’na kulluktan geri durup kibirlenirse, (bilsin ki Allah) hepsini ileride huzuruna toplayacaktır."},{"n":173,"t":"İman edip iyi işler yapanlara (Allah) ödüllerini tam olarak verecek ve onlara lütfundan daha fazlasını da verecektir. (Kulluğundan) kaçınan ve kibirlenenlere gelince, (Allah) onlara elem verici bir şekilde azap edecektir. Onlar kendileri için Allah’a rağmen hiçbir dost da yardımcı da bulamayacaklardır."},{"n":174,"t":"Ey insanlar! Elbette size Rabbinizden kesin bir delil geldi ve size apaçık bir nûr (Kur’an) indirdik."},{"n":175,"t":"Allah’a iman edip O’na (vahyine) sımsıkı sarılanlara gelince, (Allah) onları kendinden bir merhamete ve lütfa koyacaktır; onları kendine (varan) doğru yola ulaştıracaktır."},{"n":176,"t":"Senden fetva istiyorlar. De ki: Kelâle (nin mirası hakkında) Allah size fetvayı (şöyle) vermektedir: Çocuksuz bir kişi ölürse ve onun bir kız kardeşi varsa, bıraktığının yarısı onundur (kız kardeşindir). Çocuksuz bir kadın (ölür ve onun bir erkek kardeşi olursa) o (erkek kardeş) ona mirasçı olur. Kız kardeşler iki tane olursa (erkek kardeşlerinin) geride bıraktığının üçte ikisi onlarındır. Şayet erkek ve kadın daha fazla kardeş var ise bir erkeğin payı iki kadının payı gibidir. Şaşırırsınız diye Allah size açıklıyor. Allah her şeyi bilendir."}],[{"n":1,"t":"Ey iman edenler! Sözleşmeleri(n gereğini) yerine getirin! İhramlıyken avlanmayı helal saymamak üzere, size tilavet edilecekler (okunup aktarılacaklar) dışında kalan hayvanlar sizin için helal kılındı. Şüphesiz ki Allah dilediği şekilde hükmeder."},{"n":2,"t":"Ey iman edenler! Allah’ın sembollerine, haram ay(lar)a, (hediye edilmiş) kurban(lar)a ve (onlardaki) gerdanlıklara, Rablerinin lütuf ve rızasını arayarak Saygın Ev’e (Kâbe’ye) yönelmiş kişilere saygısızlık etmeyin! İhramdan çıkınca avlanın! Mescid-i Haram’dan sizi engelledikleri için bir topluma karşı öfke(niz) sizi haddi aşma suçuna sevk etmesin! İyilik ve takvâ (duyarlılık) üzerine yardımlaşın; günah ve düşmanlık üzerine yardımlaşmayın! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah azabı şiddetli olandır."},{"n":3,"t":"(Şunlar) size haram kılınmıştır: Leş, kan, domuz eti, Allah’tan başkası adına kesilen (hayvanlar); -(ölmeden yetişip) kestikleriniz hariç-, boğulmuş, (taş, ağaç vb. ile) dövül(üp öldürül)müş, (yukarıdan) yuvarlan(ıp öl)müş, boynuzlan(ıp öl)müş (hayvanlar ile) yırtıcıların yediği (öldürdüğü hayvanlar) ve dikili taşlar (putlar) üzerine boğazlanmış (hayvanlar). Bunlar yoldan çıkmaktır. Kâfir olanlar bugün sizin dininizden (onu yok etmekten) ümit kesmiştir. Artık onlara saygınlık yakıştırmayın; bana saygı duyun! Bugün, sizin için dininizi olgunlaştırdım, üzerinize nimetimi tamamladım. Sizin için din olarak İslam’ı uygun gördüm. Kim gönülden günaha yönelmiş olmamak üzere açlık hâlinde dara düşerse (haram etlerden yiyebilir). Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":4,"t":"Kendileri için nelerin helal kılındığını sana soruyorlar. De ki: “Bütün temiz şeyler ve Allah’ın size öğrettiğinden kendilerine öğretip eğitilmiş (hâle getirdiğiniz) av hayvanlarının ele geçirdiği şeylerden (oluşan avlar da) size helal kılınmıştır. (Onların) sizin için tutup yakaladıklarından yiyin ve üzer(ler)ine Allah’ın adını hatırlayın! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah hesabı hızlı olandır.”"},{"n":5,"t":"Bugün, size temiz şeyler helal kılınmıştır. Kendilerine kitap verilenlerin yiyecek(ler)i size helaldir; sizin yiyecek(ler)iniz de onlara helaldir. Mümin kadınlardan namuslu olanlar ile sizden önce kendilerine kitap verilenlerden namuslu kadınlar da mehirlerini kendilerine verdiğiniz zaman, namuslu olmak, zina etmemek ve gizli dost tutmamak üzere size helaldir. Kim inanmayı inkâr ederse elbette yaptıkları boşa gitmiştir ve o, ahirette kaybedenlerdendir."},{"n":6,"t":"Ey iman edenler! Salâta (namaza) kalktığınız zaman yüzlerinizi ve dirseklerinize kadar ellerinizi (kollarınızı) yıkayın; başlarınızı ve aşık kemiklerine kadar ayaklarınızı mesh edin! Cünüp olduysanız temizlenin (yıkanın)! Hastaysanız veya yolculuktaysanız veya sizden biriniz tuvaletten gelmişse ya da kadınlara (cinsel olarak) dokunup da (bu durumlarda) su bulamamışsanız, o zaman temiz bir toprak arayın ve yüzlerinizi de ellerinizi de ondan (onunla) mesh edin! Allah size herhangi bir güçlük (çıkarmak) istemez fakat sizi tertemiz kılmak ve size (verdiği) nimetini tamamlamak ister ki şükredesiniz."},{"n":7,"t":"Allah’ın size olan nimetini, “İşittik ve itaat ettik!” dediğiniz zaman sizi bununla bağladığı (O’na verdiğiniz) sözü hatırlayın ve Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah göğüslerin (kalplerin) özünü bilendir."},{"n":8,"t":"Ey iman edenler! Allah için şahitlik edenler olarak adaleti titizlikle ayakta tutanlar olun! Bir topluma (karşı) öfke(niz) sizi adaletsizlik suçuna sevk etmesin! Adil olun! O (adil davranmak), (Allah’a karşı) takvâlı (duyarlı) olmaya daha yakın (bir davranış)tır. Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":9,"t":"Allah iman edip iyi işler yapanlara bağışlanma ve büyük bir ödül vadetmiştir."},{"n":10,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar cehennem halkıdır."},{"n":11,"t":"Ey iman edenler! Allah’ın size olan (şu) nimetini hatırlayın: Hani bir topluluk size el uzatmaya yeltenmişti de onların ellerini sizden çekmişti. Allah’a karşı takvâlı (duyarlı) olun! Müminler yalnızca Allah’a güvensinler!"},{"n":12,"t":"Yemin olsun ki Allah, İsrailoğullarından söz almıştı. (Yönetici olarak) içlerinden on iki de başkan göndermiştik (görevlendirmiştik). Allah onlara şöyle demişti: “Ben sizinle beraberim. Namazı doğru kılar, zekâtı verir, elçilerime inanır, onları destekler ve Allah’a güzel borç verirseniz, şüphesiz ki sizin kötülüklerinizi örtecek ve sizi, altlarından ırmaklar akan cennetlere yerleştireceğim. Bundan sonra sizden kim inkâr ederse elbette doğru yoldan sapmış olur.”"},{"n":13,"t":"Sözlerini bozmaları sebebiyle onları lanetlemiş ve kalplerini katılaştırmıştık. Onlar, kendilerine hatırlatılan (Tevrat’tan) paylarını unutarak kelimelerin yerlerini değiştirirler. İçlerinden azı hariç, onlardan daima bir ihanet göreceksin. (Yine de) sen onları affet ve (onları) hoşgör! Şüphesiz ki Allah güzel davrananları sever."},{"n":14,"t":"“Biz hristiyanlarız.” diyenlerden de kesin söz almıştık fakat onlar kendilerine hatırlatılan (İncil’den) paylarını unutmuşlardı. (Bu sebeple) kıyamet gününe kadar aralarına düşmanlık ve kin salmıştık. Allah ileride (mahşerde) onlara (dünyada) yapıp ettiklerini bildirecektir."},{"n":15,"t":"Ey kitap ehli! Elbette size gelen Elçimiz, kitaptan gizlemekte olduğunuz birçok şeyi açıklıyor; birçoğunu da geçiyor. Elbette size Allah’tan bir nûr (ışık) ve apaçık bir kitap gelmiştir."},{"n":16,"t":"Allah, rızasını gözeteni onunla (Kur’anla) esenlik yollarına ulaştırır; onları buyruğu gereği karanlıklardan aydınlığa çıkarır ve onları doğru yola ulaştırır."},{"n":17,"t":"“Şüphesiz ki Allah –işte o– Meryem oğlu Mesih (İsa)’dır!” diyenler elbette kâfir olmuşlardır. De ki: “(Allah) Meryem oğlu Mesih (İsa)’yı, annesini ve yeryüzündekilerin hepsini helak etmek isterse Allah’a karşı kimin elinde bir şey var ki! Göklerin, yerin ve ikisi arasında ne varsa hepsinin otoritesi yalnızca Allah’a aittir. Dilediğini yaratır. Allah her şeye gücü yetendir.”"},{"n":18,"t":"(Bazı) yahudi ve hristiyanlar “Biz Allah’ın çocukları ve sevgilileriyiz!” demişlerdi. De ki: “(Öyleyse) günahlarınızdan dolayı size niçin azap ediyor? Doğrusu siz de O’nun yarattıklarından birer insansınız. (Allah) dileyeni (layık gördüğünü) bağışlar; dileyene (layık gördüğüne) de azap eder. Göklerde, yerde ve ikisi arasında ne varsa hepsinin otoritesi yalnızca Allah’a aittir. Dönüş de yalnızca O’nadır.”"},{"n":19,"t":"Ey kitap ehli! (Kıyamet günü) “Bize bir müjdeleyici ve uyarıcı gelmedi.” dersiniz diye elçilerin arası kesildiği sırada (gerçekleri) açıklamakta olan Elçimiz size geldi. Size elbette bir müjdeleyici ve uyarıcı gelmiştir. Allah her şeye gücü yetendir."},{"n":20,"t":"Hani Musa, kavmine şöyle demişti: “Ey kavmim! Allah’ın size (lütfettiği) nimetini hatırlayın! Zira O, içinizden peygamberler görevlendirmiş ve sizi hükümdarlar kılmıştı. Âlemlerden (insanlardan) hiç kimseye vermediğini size vermişti."},{"n":21,"t":"Ey kavmim! Allah’ın size yazdığı (vadettiği) kutsal toprağa girin ve arkanıza dönmeyin! Yoksa kaybedenler olarak dönmüş olursunuz.”"},{"n":22,"t":"Onlar şu cevabı vermişlerdi: “Ey Musa! Orada zorba bir toplum var. Onlar oradan çıkıncaya kadar biz oraya asla girmeyeceğiz. Oradan çıkarlarsa biz de hemen gireriz.”"},{"n":23,"t":"(Allah’tan) korkanlar içinden Allah’ın kendilerine lütufta bulunduğu iki adam şöyle demişti: “Onların üzerine (yanlarına) kapıdan girin! Oraya girdiğinizde (artık) şüphesiz ki siz galip gelirsiniz. Müminlerseniz yalnızca Allah’a güvenin!”"},{"n":24,"t":"(İsrailoğulları) “Ey Musa! Onlar orada bulundukları sürece biz oraya asla girmeyeceğiz. Sen ve Rabbin gidin, savaşın! Biz burada oturacağız!” demişlerdi."},{"n":25,"t":"(Musa) “Rabbim! Ben kendim ve kardeşimden başkasına sahip (hâkim) olamıyorum; bizimle, yoldan çıkmış bu toplumun arasını ayır!” demişti."},{"n":26,"t":"(Allah) “Orası (kutsal toprak) onlara kırk sene yasaklanmıştır. (Bu sürede) yeryüzünde (o topraklarda) şaşkın şaşkın dolaşacaklar. Artık sen yoldan çıkmış o toplum için üzülme!” demişti."},{"n":27,"t":"Onlara, iki âdemoğlunun (şu) haberini gerçek olarak tilavet et (okuyup aktar): Hani birer kurban sunmuşlardı da birisinden kabul edilmiş, diğerinden ise kabul edilmemişti. (Kabul edilmeyen kişi, diğerine) “Şüphesiz ki seni öldüreceğim.” demişti. Diğeri de şöyle demişti: “Allah sadece muttakîlerden (duyarlı olanlardan) kabul eder."},{"n":28,"t":"Şüphesiz ki sen öldürmek için bana elini uzatsan (bile), ben sana öldürmek için asla el uzatacak değilim. Şüphesiz ki ben âlemlerin Rabbi olan Allah’tan korkarım."},{"n":29,"t":"Şüphesiz ki ben hem benim günahımı hem de kendi günahını yüklenip senin ateş halkından olmanı istiyorum! Zalimlerin cezası işte budur.”"},{"n":30,"t":"Sonunda nefsi onu, kardeşini öldürmeye itmiş ve onu öldürmüş; bu yüzden de kaybedenlerden olmuştu."},{"n":31,"t":"(Ardından) Allah, kardeşinin cesedini nasıl gömeceğini ona göstermek için yeri eşeleyen bir karga göndermişti. (Katil kardeş) “Yazıklar olsun bana! Şu karga kadar ol(amay)ıp kardeşimi gömmekten âciz mi oldum!” demiş ve pişmanlık duyanlardan olmuştu."},{"n":32,"t":"İşte bu yüzdendir ki İsrailoğulları’na şöyle yazmıştık: “Kim bir cana karşılık olmaksızın yani yeryüzünde bozgunculuk çıkarmaya karşılık olmaksızın, (haksız yere) bir cana kıyarsa bütün insanları öldürmüş gibi olur. Kim de bir cana hayat verirse (onun canını kurtarırsa) bütün insanlara hayat vermiş (onları kurtarmış) gibi olur.” Elçilerimiz onlara apaçık deliller getirmişlerdi. Sonra, onlardan çoğu yine yeryüzünde aşırıya kaçmaktadır."},{"n":33,"t":"Allah’a ve Elçisine karşı savaşanların ve yeryüzünde bozgunculuk için çalışanların cezası ancak ve ancak öldürülmeleri veya asılmaları veya döneklikleri nedeniyle ellerinin ve ayaklarının kesilmesi ya da (bulundukları) yerden sürülmeleridir. Bu, onlar için dünyadaki rezilliktir. Ahirette de onlara büyük bir azap vardır."},{"n":34,"t":"(Ancak), siz onlara güç yetirmeden (kendilerini yenmeden) önce tevbe edenler hariç! Bilin ki Allah çok bağışlayandır, çok merhametlidir."},{"n":35,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun! O’na yol arayın ve (Allah) yolunda cihad edin (fedakârlık yapın) ki kurtulasınız."},{"n":36,"t":"Şüphesiz ki kâfir olanlar, yeryüzündeki her şey ve bununla bir o kadarı daha kendilerinin olsa ve kıyamet gününün azabından dolayı onu fidye vermek isteseler de onlardan (asla) kabul edilmemiş (olacak)tır. Onlar için elem verici bir azap vardır."},{"n":37,"t":"Ateşten çıkmak isteyecekler fakat onlar oradan asla çıkamayacaklar. Onlar için kalıcı bir azap vardır."},{"n":38,"t":"Hırsızlık yapan erkek ve kadının, elde ettiklerine karşılık ve Allah’tan ibretlik bir ceza olmak üzere ellerini kesin! Allah güçlüdür, doğru hüküm verendir."},{"n":39,"t":"Kim (bu) haksız davranışından sonra tevbe eder ve kendini düzeltirse elbette Allah onun tevbesini kabul eder. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":40,"t":"Göklerin ve yerin otoritesinin yalnızca Allah’a ait olduğunu bilmez misin? (Allah) dileyene (layık gördüğüne) azap eder; dileyeni (layık gördüğünü) de bağışlar. Allah her şeye gücü yetendir."},{"n":41,"t":"Ey Elçi! Kalpleri iman etmediği hâlde ağızlarıyla “İnandık.” diyen kişilerden ve sürekli olarak yalana kulak veren, sana gelmeyen (bazı) kişileri can kulağıyla dinleyen yahudilerin bir kısmından küfürde koşuşanlar(ın hâli) seni üzmesin! Onlar, kelimelerin yerlerini değiştirirler. (Onlar) “Size şu verilirse hemen alın; o verilmezse sakının!” derler. Allah o kişinin fitnesini (azabını) isterse, sen Allah’a karşı onun için hiçbir şey yapamazsın. Onlar, kalplerini Allah’ın temizlemek istemediği kişilerdir. Onlar için dünyada rezillik vardır; onlar için ahirette de büyük bir azap vardır."},{"n":42,"t":"Hep yalana kulak verir, durmadan haram yerler. Sana gelirlerse, ister aralarında hüküm ver; ister onlardan yüz çevir! Onlardan yüz çevirirsen sana asla zarar veremezler. Hüküm verirsen, aralarında adaletle hükmet! Şüphesiz ki Allah adil olanları sever."},{"n":43,"t":"İçinde Allah’ın hükmü bulunan Tevrat yanlarında olduğu hâlde seni nasıl hakem tayin ediyorlar ve sonra bunun arkasından yüz çevirip gidiyorlar! Onlar, asla inanmış değildir."},{"n":44,"t":"İçinde hidayet ve nûr bulunan Tevrat’ı biz indirdik. (Allah’a) teslim olmuş peygamberler, yahudiler(e ait davalarda) onunla (Tevrat ile) hükmederler(di). Allah’ın Kitabı’nı korumakla görevlendirildikleri için Rablerine teslim olmuş kişiler ve bilginler de (onunla hükmederlerdi). Hepsi de ona (Tevrat’ın hak olduğuna) şahitti. (Ey hâkimler)! İnsanlardan korkmayın; bana saygı duyun! Ayetlerimi az bir değer karşılığında satmayın! Kim Allah’ın indirdiği ile hükmetmezse işte onlar kâfirlerin ta kendileridir."},{"n":45,"t":"Orada (Tevrat’ta) onlara şöyle yazmıştık: “Cana can, göze göz, buruna burun, kulağa kulak, dişe diş (karşılık ve cezadır). Yaralar da kısastır (her yaralama misli ile cezalandırılır). Kim bunu (kısası) bağışlarsa kendisi için o, kefaret (bir günahı örtme sebebi) olur. Kim Allah’ın indirdiği ile hükmetmezse işte onlar zalimlerin ta kendileridir.”"},{"n":46,"t":"Önündeki (kendinden önce gelen) Tevrat’ı(n aslını) doğrulayıcı olarak onların (peygamberlerin) izleri üzerine Meryem oğlu İsa’yı arkalarından göndermiştik. Ona, içinde hidayet ve nûr bulunan, önündeki Tevrat’ı(n aslını) doğrulayıcı, muttakîlere (duyarlı olanlara) bir rehber ve öğüt olmak üzere İncil’i vermiştik."},{"n":47,"t":"İncil’e inananlar, Allah’ın onda indirdiği ile hükmetsin! Kim Allah’ın indirdiği ile hükmetmezse işte onlar yoldan çıkanların ta kendileridir."},{"n":48,"t":"Sana da daha önceki Kitabı(n aslını) doğrulayıcı ve onu koruyucu olarak Kitabı (Kur’an’ı) bir amaç ile indirdik. Aralarında Allah’ın indirdiği ile hükmet! Sana gelen gerçeği bırakıp da onların arzularına uyma! Hepiniz için bir kanun ve bir yol belirledik. Allah dileseydi sizi tek bir ümmet yapardı fakat size verdiği imkânlarla sizi denemek için (böyle yaptı). İyiliklerde yarışın! Hepinizin dönüşü yalnızca Allah’adır. (Allah) hakkında ayrılığa düştüğünüz şeyleri(n içyüzünü) size bildirecektir."},{"n":49,"t":"Aralarında Allah’ın indirdiği ile hükmet ve onların arzularına uyma! Allah’ın sana indirdiği hükümlerin bir kısmından seni saptırmalarıyla ilgili olarak onlara karşı dikkatli ol! (Verdiğin hükümden) yüz çevirirlerse, bil ki Allah ancak günahlarının bir kısmı sebebiyle onlara sıkıntı vermek ister. İnsanların birçoğu yoldan çıkmışlardır."},{"n":50,"t":"(Yoksa) onlar, (İslam öncesi) Cahiliye hükmünü mü arıyorlar! Kesin bir şekilde inanan bir toplum için hüküm konusunda Allah’tan daha güzel kim olabilir ki!"},{"n":51,"t":"Ey iman edenler! Yahudi ve hristiyanları dost edinmeyin! (Zira) onlar, birbirinin dostudurlar. İçinizden onları dost edinen kişi şüphesiz ki onlardan olmuş olur. Şüphesiz ki Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":52,"t":"Kalplerinde hastalık bulunanların “Başımıza bir felaketin gelmesinden korkuyoruz.” diyerek onların arasına koşuştuklarını görürsün. Umulur ki Allah bir zafer veya katından bir emir getirecek de onlar, içlerinde gizledikleri şeyden dolayı pişman olacaklardır."},{"n":53,"t":"İman edenler “Bunlar mıdır (bize gelip de) ‘Şüphesiz ki sizinle beraberiz!’ diye bütün güçleriyle yemin edenler?” diyecekler. Onların bütün yaptıkları boşa gitmiştir de kaybedenlerden olmuşlardır."},{"n":54,"t":"Ey iman edenler! Sizden kim dininden dönerse, (bilsin ki) Allah kendilerini sevdiği, onların da O’nu (Allah’ı) sevdiği, müminlere karşı alçak gönüllü, kâfirlere karşı güçlü, (ayrıca) Allah yolunda cihad eden (fedakârlık yapan) ve kınayanın kınamasından korkmayan bir topluluk getirecektir. Bu, Allah’ın lütfudur. Onu dilediğine (layık olana) verir. Allah (imkânları) geniş olandır, bilendir."},{"n":55,"t":"Sizin dostunuz yalnızca Allah, Elçisi ve boyun eğerek namazı kılan ve zekâtı veren müminlerdir."},{"n":56,"t":"Kim Allah’ı, Elçisini ve iman edenleri dost edinirse, galip gelecek olanlar şüphesiz ki yalnızca Allah’ın tarafında olanlardır."},{"n":57,"t":"Ey iman edenler! Sizden önce kendilerine kitap verilenlerden dininizi alay ve oyun konusu edinenleri ve kâfirleri dost edinmeyin! Müminlerseniz Allah’a karşı takvâlı (duyarlı) olun!"},{"n":58,"t":"Salât’a (ibadete) çağırdığınız zaman onu alay ve oyun edinirler. Bu (davranış), onların düşünmeyen bir toplum olmalarındandır."},{"n":59,"t":"(Onlara) şöyle de: “Ey kitap ehli! Yalnızca Allah’a, bize indirilene ve daha önce indirilene inandığımız için mi bizden nefret ediyorsunuz? Oysa çoğunuz yoldan çıkmış kişilersiniz.”"},{"n":60,"t":"De ki: “Allah katında yeri bundan daha (feci olan asıl) kötülüğü size bildireyim mi? Allah’ın lanetlediği ve gazap ettiği, aralarından (ahlaken âdeta) maymunlar, domuz (gibi olan)lar ve Tağut (azgın) denen müşrik(ler var ya) yeri en kötü olan ve doğru yoldan tamamen sapanlar işte bunlardır.”"},{"n":61,"t":"Size geldiklerinde (yanınıza) inkârla girip yine inkârla çıktıkları hâlde “İnandık!” derler. (Oysa) Allah onların içlerinde gizlemiş oldukları şeyleri çok iyi bilendir."},{"n":62,"t":"Onlardan birçoğunun günah, düşmanlık ve haram yemede yarıştıklarını görürsün. Yaptıkları ne kadar kötüdür!"},{"n":63,"t":"Kendilerini Rabbe adayanlar ve din âlimleri, günah olan sözleri söylemek ve haram yemekten onları engelleseydi (sakındırsaydı) ya! İşledikleri (fiiller) ne kötüdür!"},{"n":64,"t":"Yahudiler “Allah’ın eli bağlıdır (sıkıdır)!” dediler. Dedikleri yüzünden elleri bağlanası ve lanet olasıcalar! Aksine (Allah’ın) iki eli de açıktır; dilediği şekilde verir. Şüphesiz ki sana Rabbinden indirilen (mesajlar), çoğunun azgınlığı ve küfrünü artıracaktır. Aralarına, kıyamet gününe kadar (sürecek) düşmanlık ve kin bıraktık. Ne zaman savaş için bir ateş yakmışlarsa Allah onu söndürmüştür. (Böyleyken yine de) onlar, yeryüzünde bozgunculuğa koşarlar. Allah ise bozguncuları sevmez."},{"n":65,"t":"Kitap ehli iman edip takvâlı (duyarlı) olsalardı, elbette onların (geçmiş) kötülüklerini örter ve onları nimeti bol cennetlere koyardık."},{"n":66,"t":"Onlar Tevrat’ı, İncil’i ve Rablerinden onlara indirileni (Kur’an’ı) tam olarak uygulasalardı, şüphesiz ki hem üstlerinden hem de ayaklarının altından (verilen pek çok nimet) yerlerdi. Onlardan aşırılığa kaçmayan bir topluluk vardır; (fakat) çoğunun yaptıkları ne kötüdür!"},{"n":67,"t":"Ey Elçi! Rabbinden sana indirileni tebliğ et! (Bunu) yapmazsan O’nun elçiliğini tebliğ etmemiş olursun. Allah seni (inkârcı) insanlardan koruyacaktır. Şüphesiz ki Allah o kâfirler topluluğunu doğru yola ulaştırmaz."},{"n":68,"t":"De ki: “Ey Kitap ehli! Siz Tevrat’ı, İncil’i ve Rabbinizden size indirileni (Kur’an’ı) uygulayıncaya kadar (doğru) bir şey üzerinde değilsiniz. Şüphesiz ki sana Rabbinden indirilen (mesajlar), çoğunun azgınlığını ve küfrünü artıracaktır. Kâfirler topluluğuna üzülme!”"},{"n":69,"t":"Şüphesiz ki iman edenler, yahudi olanlar, sabiiler ve hristiyanlardan kim Allah’a ve ahiret gününe iman edip iyi işler yaparsa onlara hiçbir korku yoktur; onlar üzülmeyecek de."},{"n":70,"t":"Şüphesiz ki İsrailoğulları'ndan sağlam bir söz almış ve onlara elçiler göndermiştik. Ne zaman elçi onlara nefislerinin arzu etmediğini (hükümler) getirse (onların) bir kısmını yalanlıyor, bir kısmını da öldürüyorlar(dı)."},{"n":71,"t":"Bir fitne (imtihan) olmayacak sanmışlar da kör ve sağır kesilmişlerdi. Sonra Allah tevbelerini kabul etmişti; ardından içlerinden çoğu yine kör ve sağır kesilmişti. Allah onların yapmakta olduklarını görendir."},{"n":72,"t":"“Şüphesiz ki Allah –işte o– Meryem oğlu Mesih (İsa)’dır!” diyenler elbette kâfir olmuşlardır. (Oysa) Mesih (İsa), “Ey İsrailoğulları! Benim Rabbim ve sizin Rabbiniz olan Allah’a kulluk edin!” demişti. (Bilin ki) kim Allah’a ortak koşarsa elbette Allah ona cenneti haram kılmıştır; onun barınağı ateştir ve zalimler için hiçbir yardımcı yoktur."},{"n":73,"t":"“Şüphesiz ki Allah, üçün üçüncüsüdür!” diyenler de şüphesiz ki kâfir olmuşlardır. (Oysa) tek bir ilahtan (Allah’tan) başka ilah yoktur. Söylediklerinden vazgeçmezlerse, içlerinden kâfir olanlara elem verici bir azap dokunacaktır."},{"n":74,"t":"(Hâlâ) bağışlanma dileyerek Allah’a tevbe etmeyecekler mi? Allah çok bağışlayandır, çok merhametlidir."},{"n":75,"t":"Meryem oğlu Mesih (İsa) sadece bir elçidir. Ondan önce de elçiler elbette geçmiştir. Annesi de çok doğru bir kadındır. Her ikisi de yemek yerlerdi. Bak, onlara delilleri nasıl açıklıyoruz; sonra bak ki nasıl da (gerçeklerden) döndürülüyorlar!"},{"n":76,"t":"De ki: “Allah’ın peşi sıra sizin için yarar ve zarara gücü yetmeyen şeylere mi tapıyorsunuz!” Allah -evet yalnızca O- duyandır, bilendir."},{"n":77,"t":"De ki: “Ey Kitap ehli! Haksız olarak dininizde aşırıya kaçmayın! Daha önceden sapmış olan, birçoğunu saptıran ve yolun doğrusundan uzaklaşan bir toplumun heveslerine uymayın!”"},{"n":78,"t":"İsrailoğullarından kâfir olanlar, Davud ve Meryem oğlu İsa’nın diliyle lanetlenmiştir. Bunun sebebi, (ilahî mesajlara) isyan etmiş ve hadlerini aşmış olmalarıdır."},{"n":79,"t":"Onlar, işledikleri (kötülükler)den, birbirlerini vazgeçirmeye çalışmazlardı. Yaptıkları ne kötüdür!"},{"n":80,"t":"Onlardan çoğunun, kâfir olanlarla dostluk ettiklerini görürsün. Nefislerinin onlar için hazırladığı şey ne kötüdür! (Bu yüzden) Allah onlara gazap etmiştir ve onlar azap içinde ebedî kalıcıdır!"},{"n":81,"t":"Onlar Allah’a, Peygamber’e ve ona indirilene iman etmiş olsalardı onları (müşrikleri) dost edinmezlerdi fakat çoğu yoldan çıkmışlardır."},{"n":82,"t":"İman edenlere düşmanlık bakımından insanların en şiddetlisini elbette yahudiler ve şirk koşanlar olarak bulacaksın. Onlar (inkârcılar) içinde iman edenlere sevgi bakımından en yakın olarak da elbette “Biz hristiyanlarız!” diyenleri bulacaksın. Bunun sebebi şüphesiz ki onların içinde keşişlerin ve rahiplerin bulunması ile onların kibirli davranmamasıdır."},{"n":83,"t":"Elçiye indirileni duydukları zaman, tanıdıkları gerçeklerden dolayı gözlerinden yaşlar boşaldığını görürsün. Derler ki: “Rabbimiz! İman ettik, bizi (gerçeğe) şahit olanlarla birlikte yaz!"},{"n":84,"t":"Rabbimizin bizi iyiler arasına katmasını umup dururken Allah’a ve bize gelen gerçeğe niçin iman etmeyecekmişiz ki!”"},{"n":85,"t":"Söyledikleri (bu) sözden dolayı Allah onlara, içinde ebedî kalmak üzere altlarından ırmaklar akan cennetleri ödül olarak vermiş (olacak)tır. Güzel davrananların karşılığı işte budur."},{"n":86,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar cehennem halkıdır."},{"n":87,"t":"Ey iman edenler! Allah’ın size helal kıldığı temiz şeyleri haram kılmayın ve aşırı gitmeyin! Şüphesiz ki Allah aşırıları sevmez."},{"n":88,"t":"Allah’ın size verdiği rızıktan temiz helal olarak yiyin ve kendisine iman etmiş olduğunuz Allah’a karşı takvâlı olun!"},{"n":89,"t":"Allah sizi (kasıtsız) yeminlerinizdeki boş sözlerle ilgili sorumlu tutmaz fakat bir şeye bağladığınız (kasıtlı) yeminlerden sorumlu tutar. (Bozduğunuz zaman) kefareti, ailenize yedirdiğiniz yemeğin orta hallisinden on fakire yedirmek veya onları giydirmek ya da bir köle azat etmektir. (Bunları) bulamayan kişinin üç gün oruç tutması (gerekir). Yemin ettiğiniz zaman (yemini bozduğunuz zaman) yeminlerinizin kefareti işte budur. Yeminlerinizi koruyun (bozmayın)! Allah şükredesiniz diye ayetlerini size işte böyle açıklıyor."},{"n":90,"t":"Ey iman edenler! İçki, kumar, dikili taşlar (putlar), fal (şans) okları şeytanın işinden bir pisliktir. Ondan (o pis şeylerden) uzak durun ki kurtulasınız."},{"n":91,"t":"Şeytan, içki ve kumar yoluyla aranıza yalnızca düşmanlık ve kin sokmak, (dahası), sizi Allah’ı hatırlamaktan ve salâttan (ibadetten) alıkoymak ister. (Artık bunlardan) vazgeçtiniz değil mi?"},{"n":92,"t":"Allah’a itaat edin, Elçi'ye de itaat edin ve (kötülüklerden) sakının! (İtaatten) yüz çevirirseniz, bilin ki elçimize (düşen görev), sadece apaçık tebliğdir."},{"n":93,"t":"Takvâlı (duyarlı) olup iman ettikleri ve iyi işler yaptıkları, sonra (yine) takvâlı (duyarlı) olup iman ettikleri, sonra da (bunu devam ettirerek) takvâlı (duyarlı) olup güzel davrandıkları sürece (haram kılınmadan önce) tattıklarından dolayı iman edip iyi işler yapanlara herhangi bir vebal yoktur. Allah güzel davrananları sever."},{"n":94,"t":"Ey iman edenler! Elbette Allah (hac veya umre için ihramlıyken) ellerinizin ve mızraklarınızın ulaşacağı bir avlanma ile (onu yasak ederek) sizi dener. Sonunda Allah, yalnız bir durumdayken kendisinden kimin korktuğunu bil(dir)ecektir. Kim bundan sonra haddi aşarsa onun için elem verici bir azap vardır."},{"n":95,"t":"Ey iman edenler! İhramlıyken av hayvanı öldürmeyin! İçinizden kim onu kasten öldürürse cezası, içinizden adil iki kişinin kararıyla, avlanılan hayvana denk, Kâbe’ye varacak (hediye) bir kurban göndermek veya yoksulları doyurmaktan (ibaret) bir kefarettir ya da onun dengi oruç (tutmaktır) ki işinin vebalini tatmış olsun. Allah geçmişi affetmiştir. Kim (suça) dönerse Allah da ondan intikamını alır. Allah güçlüdür, intikam sahibidir."},{"n":96,"t":"Hem size hem de yolculara yarar sağlamak üzere deniz avı yapmak ve onu yemek size helal kılındı. İhramlı olduğunuz sürece kara avı ise size haram kılındı. Huzurunda toplanacağınız Allah’a karşı takvâlı (duyarlı) olun!"},{"n":97,"t":"Allah; Kâbe’yi yani o Saygın Ev’i, haram ay(lar)ı, (hacdaki hediye) kurbanını ve (kurbanın boynuna asılan) gerdanlıkları insanlar için bir kıyam (diriliş vesilesi) kıldı. Bu da Allah’ın, göklerde ve yerde olanları bildiğini ve Allah’ın her şeyi bilici olduğunu (sizin de anlayıp) bilmeniz içindir."},{"n":98,"t":"Bilin ki Allah’ın cezalandırması şiddetlidir; (ayrıca) Allah çok bağışlayandır, çok merhametlidir."},{"n":99,"t":"Elçiye düşen, sadece tebliğdir. Allah sizin açığa vurduklarınızı da gizlediklerinizi de bilir."},{"n":100,"t":"De ki: “Pisliğin çokluğu sana cazip gelse de pis ile temiz bir olmaz. Ey öz akıl sahipleri! Allah’a karşı takvâlı (duyarlı) olun ki kurtulasınız.”"},{"n":101,"t":"Ey iman edenler! Size açıklanırsa hoşunuza gitmeyecek şeyleri sormayın! Kur’an indirilirken onları sorarsanız size açıklanır. (Bildirmediğine göre) Allah onları affetmiştir. Allah çok bağışlayandır, hoşgörülüdür."},{"n":102,"t":"Elbette sizden önce de bir toplum onları sormuş, sonra da bunları inkâr eder olmuştu."},{"n":103,"t":"Allah bahîrah, sâibeh, vasîleh ve hâm diye bir şey (haram) kılmamıştır. Fakat kâfir olanlar, Allah’a yalan uydurur. Onların çoğu akıl etmez."},{"n":104,"t":"Onlara “Allah’ın indirdiğine (kitaba) ve Elçi'ye gelin!” dendiği zaman, “Babalarımızı üzerinde bulduğumuz (yol) bize yeter!” derler. Ataları hiçbir şey bilmiyor ve doğru yol üzerinde bulunmuyor iseler de mi?"},{"n":105,"t":"Ey iman edenler! Siz kendinize bakın! Siz doğru yolda olunca sapan kimse size zarar veremez. Hepinizin dönüşü yalnızca Allah’adır; O da size (dünyada) yapmış olduğunuz her şeyi (mahşerde) bildirecektir."},{"n":106,"t":"Ey iman edenler! Birinize ölüm gelip çatınca, vasiyet esnasında içinizden adalet sahibi iki kişi aranızda şahitlik etsin! Veya yeryüzünde yolculuktayken başınıza ölüm musibeti gelmişse sizden olmayan başka iki kişi (şahit olsun)! Şüpheye düşerseniz o iki şahidi salâttan (ibadetten) sonra durdurup “Akraba (menfaatine) de olsa bu vasiyet karşılığında hiçbir şeyi satın almayacağız; Allah (için yaptığımız) şahitliği gizlemeyeceğiz; (aksini yaparsak) bu takdirde biz elbette günahkârlardan oluruz.” diye Allah’a yemin ettirirsiniz."},{"n":107,"t":"Bunların (iki şahidin) günah işledikleri anlaşılırsa, haklarına tecavüz edilen (mağdur durumdaki)lerden diğerlerinin yerine geçecek çok daha uygun başka iki kişi onların yerini alır. (Bu iki kişi) “Doğrusu bizim şahitliğimiz onların şahitliğinden daha doğrudur; biz (kimsenin hakkına) tecavüz etmedik; aksi takdirde biz de elbette zalimlerden oluruz.” diye Allah’a yemin ederler."},{"n":108,"t":"Bu (usul), şahitliği gerektiği şekilde yapmaya veya yeminlerinden sonra, yeminlerin reddedilmesinden korkmalarına daha uygundur. Allah’a karşı takvâlı (duyarlı) olun ve (O’nu) dinleyin! Allah yoldan çıkanlar topluluğunu doğru yola ulaştırmaz."},{"n":109,"t":"Allah’ın elçileri toplayıp da “Size ne cevap verildi?” dediği gün “Bizim hiçbir bilgimiz yok; şüphesiz ki gizlilikleri bilen ancak sensin sen” demiş (olacaklar)dır."},{"n":110,"t":"Allah o zaman şöyle diyecektir: “Ey Meryem oğlu İsa! Sana ve annene (verdiğim) nimet(ler)imi hatırla! Hani seni Kutsal Ruh (Cebrail) ile desteklemiştim; sen beşikteyken de yetişkin çağında da insanlarla konuşuyordun. Sana Kitab'ı (okuyup yazmayı), hikmeti (doğru hüküm verme yeteneğini), Tevrat’ı ve İncil’i öğretmiştim. Benim iznimle çamurdan bir kuşun benzeri gibi (sûret) yapıyordun da ona üflüyordun; o da benim iznimle hemen bir kuş oluyordu. Benim iznimle körü ve alacalıyı iyileştiriyordun. Benim iznimle ölüleri (hayata) çıkarıyordun. Hani İsrailoğullarını (seni öldürmekten) engellemiştim. Kendilerine apaçık deliller getirdiğin zaman içlerinden kâfir olanlar “Bu, apaçık bir büyüden başka bir şey değildir!” demişlerdi."},{"n":111,"t":"Hani Havarilere “Bana ve elçime iman edin!” diye vahyetmiştim (bildirmiştim). Onlar da “İman ettik, bizim Allah’a teslim olmuş kişiler (Müslümanlar) olduğumuza sen de şahit ol!” demişlerdi."},{"n":112,"t":"Hani Havariler “Ey Meryem oğlu İsa, Rabbin bize gökten bir sofra indirebilir mi?” diye sormuşlardı. O (İsa) da “İman etmiş kişilerseniz Allah’a karşı takvâlı (duyarlı) olun.” cevabını vermişti."},{"n":113,"t":"Onlar “Ondan yiyelim, kalplerimiz rahat olsun, bize doğru söylediğini (kesin olarak) bilelim ve ona şahitler olmak istiyoruz.” demişlerdi."},{"n":114,"t":"Meryem oğlu İsa şöyle dua etmişti: “Allah’ım! Rabbimiz! Bize hem bizim hem de öncekilerimiz ve sonrakilerimiz için bir bayram ve senden bir delil olacak şekilde gökten bir sofra indir! Bizi rızıklandır! Sen rızık verenlerin en hayırlısısın.”"},{"n":115,"t":"Allah da şöyle demişti: “Şüphesiz ki ben onu size indirebilirim; (ama) bundan sonra içinizden kim inkâr ederse, âlemlerde kimseye etmediğim azabı ona ederim!”"},{"n":116,"t":"Hani Allah “Ey Meryem oğlu İsa! İnsanlara ‘Beni ve annemi, Allah’ın peşi sıra iki ilah edinin!’ diye sen mi dedin?” dediği zaman, (İsa) “(Haşa)! Sen yücesin. Hakkım olmayan şeyi söylemek bana yakışmaz. Ben onu söyleseydim sen onu elbette bilirdin. Sen bendekini bilirsin, (oysa) ben sende olanı bilemem. Şüphesiz ki gizlilikleri bilen ancak sensin sen.” demiş (olacak)tır."},{"n":117,"t":"“Ben onlara, yalnızca senin bana emrettiğin (şu esası) söyledim: ‘Benim de Rabbim, sizin de Rabbiniz olan Allah’a kulluk edin!’ İçlerinde bulunduğum sürece durumlarına şahittim. Beni vefat ettirince artık onlar üzerine gözetleyici yalnız sen oldun. Sen her şeye şahitsin."},{"n":118,"t":"Onlara azap edersen şüphesiz ki onlar, senin kullarındır (dilediğini yaparsın). Onları bağışlarsan şüphesiz ki güçlü ve doğru hüküm veren yalnızca sensin.”"},{"n":119,"t":"Allah şöyle demiş (olacak)tır: “Bu(gün), doğrulara, doğruluklarının yarar sağlayacağı gündür. Onlara, içinde ebedî kalacakları, altlarından ırmaklar akan cennetler vardır. Allah kendilerinden razı, onlar da O’ndan memnun olmuşlardır. İşte bu, büyük kurtuluştur.”"},{"n":120,"t":"Göklerin, yerin ve içindekilerin otoritesi yalnızca Allah’a aittir. O, her şeye gücü yetendir."}],[{"n":1,"t":"Hamd (övgü), gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah içindir. (Bunca delilden) sonra kâfir olanlar (hâlâ putları) Rableri ile denk tutuyorlar."},{"n":2,"t":"Sizi bir çamurdan yaratan, sonra da bir süre belirleyen O’dur. (Bir de) O’nun katında belirlenmiş bir süre vardır. (Buna rağmen siz hâlâ) şüphe ediyorsunuz."},{"n":3,"t":"O, göklerde ve yerde (tek) Allah’tır. Gizlinizi, açığınızı bilir; ne kazanmakta olduğunuzu da bilir."},{"n":4,"t":"Kendilerine Rablerinin ayetlerinden bir ayet geldiğinde, mutlaka ondan yüz çevirmişlerdi."},{"n":5,"t":"Elbette onlar, kendilerine gerçek (bilgi) geldiğinde onu yalanlamışlardı. Alay edip durdukları şeylerin haberleri ileride kendilerine gelecektir."},{"n":6,"t":"Görmediler mi ki onlardan önce yeryüzünde size vermediğimiz bütün imkânları kendilerine verdiğimiz, üzerlerine göğü (yağmuru) bolca göndermiş, (evlerinin) altından ırmaklar akıttığımız nice nesilleri helak etmiştik. Onları, günahları sebebiyle helak etmiş ve onların ardından başka nesiller yaratmıştık."},{"n":7,"t":"Sana kâğıda (yazılmış) bir kitap indirseydik de onlar ona elleriyle dokunmuş olsalardı, kâfir olanlar “Bu, apaçık büyüden başka bir şey değildir!” derlerdi."},{"n":8,"t":"(Müşrikler) “Ona bir melek indirilseydi ya!” demişlerdi. Biz melek indirseydik elbette iş bitirilmiş olur, artık kendilerine göz bile açtırılmaz(dı)."},{"n":9,"t":"Onu (peygamberi) bir melek kılsaydık şüphesiz ki onu bir erkek (insan suretinde) yapar, düşmekte oldukları kuşkuya onları yine düşürürdük."},{"n":10,"t":"Yemin olsun ki senden önceki elçilerle de alay edilmişti ve alay edenleri alay ettikleri şey (çepeçevre) kuşatmıştı."},{"n":11,"t":"De ki: “Yeryüzünde dolaşın; sonra yalanlayanların sonunun nasıl olduğuna bakın!”"},{"n":12,"t":"(Onlara) “Göklerde ve yerde olanlar kimindir?” diye sor (ve) “Merhamet etmeyi kendi zatına yazmış olan Allah’a aittir.” de! Sizi, varlığında şüphe olmayan kıyamet gününde elbette toplayacaktır. Kendilerine yazık edenler var ya işte onlar inanmazlar."},{"n":13,"t":"Gecede ve gündüzde barınan her şey yalnızca O’na aittir. O, duyandır, bilendir."},{"n":14,"t":"De ki: “Gökleri ve yeri yoktan var eden, yedirdiği hâlde yedirilmeyen (buna ihtiyacı olmayan) Allah’tan başkasını mı dost edinecekmişim!” De ki: “Bana müslüman olanların ilki (öncüsü) olmam emredildi.” ve “Sakın müşriklerden olma!” (dendi)."},{"n":15,"t":"De ki: “Rabbime isyan edersem elbette büyük günün azabından korkarım."},{"n":16,"t":"O gün kim ondan (azaptan) uzak tutulursa, elbette (Allah) ona merhamet etmiştir. İşte apaçık kurtuluş budur.”"},{"n":17,"t":"Allah sana bir sıkıntı dokundurursa, onu O’ndan başka açıp (giderecek) yoktur. Sana herhangi bir hayır verirse, (onu geri alacak yoktur). O, her şeye gücü yetendir."},{"n":18,"t":"O, kullarının üzerinde (her türlü güce sahip)tir. O, doğru hüküm verendir, haberdardır."},{"n":19,"t":"De ki: “Hangi şey şahitlik bakımından en büyüktür? De ki: “Allah benimle sizin aranızda şahittir. Bu Kur’an, bana, kendisiyle sizi ve ulaştığı herkesi uyarmam için vahyolundu. Yoksa siz Allah ile birlikte başka ilahlar olduğuna şahitlik mi ediyorsunuz?” De ki: “Ben buna şahitlik etmem.” De ki: “O, yalnızca tek bir ilahtır; ben sizin ortak koştuğunuz şeylerden elbette uzağım.”"},{"n":20,"t":"Kendilerine kitap verdiklerimiz onu kendi çocuklarını tanıdıkları gibi tanırlar. Kendilerine yazık edenler var ya işte onlar inanmazlar."},{"n":21,"t":"Allah’a yalan uyduran veya O’nun ayetlerini yalanlayandan daha zalim kim olabilir ki! Şüphesiz ki zalimler kurtulamazlar."},{"n":22,"t":"O gün onların hepsini toplayacağız; sonra da (Allah’a) ortak koşmuş olanlara “(Varlığını) sandığınız ortaklarınız nerede?” diyeceğiz."},{"n":23,"t":"Sonra “Rabbimiz Allah’a yemin olsun ki biz ortak koşanlar değildik.” demekten başka onların mazeretleri olmayacak."},{"n":24,"t":"Gör(ün) ki kendi aleyhlerine nasıl yalan söylemiş olacaklar ve (ilah diye) uydurdukları şeyler (putlar) da kendilerinden kaybolup gitmiş olacaktır."},{"n":25,"t":"Onlardan seni dinleyenler de vardır. (İnkâra şartlanmış oldukları için) onu (Kur’an’ı) anlamaları konusunda kalplerine perdeler ve kulaklarına bir (s) ağırlık veririz. (Çünkü) onlar, her bir delili görseler de onlara iman etmezler. Hatta o kâfir olanlar sana geldiklerinde “Bu (Kur’an), öncekilerin masallarından başka bir şey değildir!” diyerek seninle tartışırlar."},{"n":26,"t":"Onlar hem insanları ondan engellemeye çalışır hem de kendileri ondan uzaklaşırlar. (Oysa) onlar, farkında olmadan ancak kendilerini helak ederler."},{"n":27,"t":"Onların ateşin karşısında durdurulup “Ah, keşke (dünyaya) geri gönderilsek de bir daha Rabbimizin ayetlerini yalanlamasak ve inananlardan olsak!” dediklerini bir görsen!"},{"n":28,"t":"Hayır! Daha önce gizlemekte oldukları şeyler (günahlar) kendilerine göründü. (Dünyaya) geri gönderilseler yine de kendilerine yasak edilen şeylere döneceklerdir. Şüphesiz ki onlar yalancıdır."},{"n":29,"t":"Onlar “Hayat ancak bu yakın (dünyadaki) hayatımızdan ibarettir; biz asla diriltilecek de değiliz!” demişlerdi."},{"n":30,"t":"Rablerinin huzuruna (çıkarılıp) durduruldukları zaman sen onları bir görsen! (Allah:) “Bu (diriltilme) gerçek değil miymiş!” diye soracak; onlar da “Rabbimize yemin olsun: Evet (gerçekmiş)!” diyeceklerdir. (Bunun üzerine Allah:) “İnkâr ettiğinizden dolayı azabı tadın!” diyecektir."},{"n":31,"t":"Allah ile karşılaşmayı yalanlayanlar, elbette kaybetmişlerdir. Sonunda o (Son) Saat onlara ansızın gelince, günahlarını sırtlarına yüklenerek “(Dünyada iyi davranışları) terk etmemizden dolayı bize yazıklar olsun!” diyecekler. Dikkat edin! Yüklendikleri şey ne kötüdür!"},{"n":32,"t":"Dünya hayatı bir oyun ve eğlenceden başka bir şey değildir. Ahiret yurdu, takvâlı (duyarlı) olanlar için şüphesiz ki hayırlı olandır. Akıl etmiyor musunuz?"},{"n":33,"t":"Onların söylediklerinin seni üzmekte olduğunu elbette biliyoruz. Şüphesiz ki onlar, seni yalanlamıyor ancak o zalimler Allah’ın ayetlerini inkâr ediyorlar."},{"n":34,"t":"Yemin olsun ki senden önceki elçiler de yalanlanmıştı. Onlar, yalanlanmalarına ve eziyet edilmelerine rağmen sabretmişler, sonunda yardımımız onlara yetişmişti. Allah’ın sözlerini (kanunlarını) değiştirebilecek kimse yoktur. Şüphesiz ki elçilerin haberlerinden bazısı sana da gelmiştir."},{"n":35,"t":"Onların yüz çevirmesi sana ağır geldi ise yerde (inebileceğin) bir tünel veya göğe (çıkabileceğin) bir merdiven edinmeye gücün yetseydi ve onlara bir delil getirseydin (yine de inanmazlardı). Allah dileseydi, elbette onları hidayet üzerinde toplardı; sakın cahillerden olma!"},{"n":36,"t":"Ancak (samimiyetle) dinleyenler (çağrıya) cevap verirler. Ölülere gelince, Allah onları diriltecek; sonra da O’na döndürüleceklerdir."},{"n":37,"t":"(İnkârcılar) “O’na Rabbinden bir ayet (mucize) indirilseydi ya!” demişlerdi. De ki: “Şüphesiz ki ayet (mucize) indirmeye gücü yeten Allah’tır. Fakat onların çoğu bilmezler.”"},{"n":38,"t":"Yerde yürüyen canlılar ve (gökte) iki kanadıyla uçan kuşlardan ne varsa hepsi ancak sizin gibi topluluklardır. Biz o kitapta hiçbir şeyi eksik bırakmadık. Sonra sadece Rablerinin huzurunda toplanacaklardır."},{"n":39,"t":"Ayetlerimizi yalanlayanlar karanlıklar içinde kalmış sağır ve dilsizlerdir. Allah dilediğini (layık olanı) saptırır; dilediğini (layık olanı) da doğru yola ulaştırır."},{"n":40,"t":"De ki: “Ne dersiniz; size Allah’ın azabı gelse veya o (Son) Saat size gelip çatsa, Allah’tan başkasına mı yalvarırsınız? Doğruysanız (söyleyin bakalım)!”"},{"n":41,"t":"Aksine yalnız O’na (Allah’a) yalvarırsınız. O da (kaldırılması için) kendisine yalvardığınız (belayı) dilerse kaldırır ve siz ortak koştuğunuz şeyleri unutursunuz."},{"n":42,"t":"Yemin olsun ki senden önceki ümmetlere de elçiler göndermiştik. (Gerçeğe) boyun eğsinler diye onları çeşitli sıkıntı ve darlık ile denemiştik."},{"n":43,"t":"Onlara bu şekilde azabımız geldiği zaman boyun eğselerdi ya! Fakat kalpleri iyice katılaşmış ve şeytan da onlara yaptıklarını süslü göstermişti."},{"n":44,"t":"Kendilerine yapılan uyarıları unuttuklarında, üzerlerine her şeyin kapılarını açmıştık. Sonunda kendilerine verilenler yüzünden şımardıkları zaman onları ansızın yakalamıştık; birdenbire bütün ümitlerini yitirmişlerdi."},{"n":45,"t":"Böylece haksızlık eden o toplum(ları)n kökü kesilmişti. Hamd (övgü), âlemlerin Rabbi olan Allah içindir."},{"n":46,"t":"De ki: “Bir düşünsenize; Allah işitme (duyu)nuzu ve gözlerinizi alırsa, kalplerinizi de mühürlerse (bunları) size Allah’tan başka hangi ilah getirebilir ki!” Bak, ayetleri nasıl açıklıyoruz. Onlar ise yüz çeviriyorlar!"},{"n":47,"t":"De ki: “Bir düşünsenize; size Allah’ın azabı ansızın veya açıkça gelirse, zalim toplumdan başkası mı helak edilirmiş!”"},{"n":48,"t":"Biz, elçileri sadece müjdeleyiciler ve uyarıcılar olarak göndeririz. Kim iman eder, kendilerini düzeltirse onlara korku yoktur. Onlar üzülmeyecek de."},{"n":49,"t":"Ayetlerimizi yalanlayanlara gelince, yoldan çıkmalarından dolayı onlara azap dokunacaktır."},{"n":50,"t":"De ki: “Ben size ‘Allah’ın hazineleri benim yanımdadır’ demiyorum. Gaybı (bilinemeyeni) de bilmem. Size ‘Şüphesiz ki ben bir meleğim’ de demiyorum. Ben, bana vahyolunandan başkasına uymuyorum.” De ki: “Kör ile gören bir olur mu? Hiç düşünmez misiniz?”"},{"n":51,"t":"Umulur ki takvâlı (duyarlı) davranırlar diye kendileri için O’nun peşi sıra hiçbir dost ve şefaatçinin bulunmadığı (mahşer gününde) Rablerinin huzurunda toplanacaklarından korkanları onunla (Kur’an ile) uyar!"},{"n":52,"t":"O’nun rızasını isteyerek Rablerine sabah akşam dua edenleri kovma! Onların hesabından sana herhangi bir şey (sorumluluk), senin hesabından da onlara herhangi bir şey (sorumluluk) yoktur ki onları kovup da zalimlerden olasın."},{"n":53,"t":"“Aramızdan Allah’ın kendilerine lütfettiği kişiler bunlar mı?” demeleri için onların bir kısmını diğerleri ile işte böyle imtihan ettik. Allah şükredenleri daha iyi bilmez mi?"},{"n":54,"t":"Ayetlerimize inananlar sana geldiğinde onlara de ki: “Selam üzerinize olsun! Rabbiniz merhamet etmeyi kendisine yazmıştır (gerekli kılmıştır).” Gerçek şu ki sizden kim bilmeyerek bir kötülük yapar, sonra ardından tevbe edip kendisini düzeltirse, O çok bağışlayandır, çok merhametlidir."},{"n":55,"t":"Böylece ayetleri ayrıntılı olarak açıklıyoruz; sonunda suçluların yolu iyice belli olacaktır."},{"n":56,"t":"De ki: “Allah’ın peşi sıra yalvardıklarınıza tapmam bana yasaklandı.” De ki: “Ben sizin arzularınıza uymam; aksi hâlde saparım ve doğru yola ulaştırılanlardan olmam.”"},{"n":57,"t":"De ki: “Şüphesiz ki ben Rabbimden gelen apaçık bir delile dayanmaktayım; siz ise onu yalanladınız. Acele gelmesini istediğiniz (gün) benim yanımda değildir. Hüküm yalnızca Allah’a aittir. O gerçeği anlatır ve O doğru hüküm verenlerin en hayırlısıdır.”"},{"n":58,"t":"De ki: “Acele istediğiniz (azap) benim elimde olsaydı, elbette benimle sizin aranızda iş bitirilmiş olurdu. Allah zalimleri çok iyi bilendir.”"},{"n":59,"t":"Gaybın (bilinemeyen şeylerin) anahtarları, yalnızca O’nun yanındadır; onları O’ndan başkası bilemez. Karada ve denizde ne varsa hepsini bilir; O’nun bilgisi dışında bir yaprak bile düşmez. Yerin karanlıkları içindeki tek bir tane, yaş ve kuru ne varsa hepsi apaçık bir kitaptadır."},{"n":60,"t":"Geceleyin sizi vefat ettiren (uyutan), gündüzün de ne işlediğinizi bilen; sonra belirlenmiş süre tamamlansın diye onda (gündüz) sizi dirilten (uyandıran) O (Allah)’tır. Sonra dönüşünüz yine yalnızca O’nadır. Sonunda yaptıklarınızı size bildirecektir."},{"n":61,"t":"O, kullarının üzerinde her türlü etkinliğe sahiptir ve size koruyucular göndermektedir. Sonunda birinize ölüm geldiğinde elçilerimiz (melekler) onu vefat ettirirler. Onlar (görevlerinde) kusur etmezler."},{"n":62,"t":"Sonra insanlar gerçek sahipleri olan Allah’a döndürülmüş (olacaklar)dır. Dikkat edin! Hüküm yalnızca O’na aittir ve O, hesap görenlerin en hızlısıdır."},{"n":63,"t":"De ki: “Şüphesiz ki bizi bundan kurtarırsa şükredenlerden olacağız’ diye boyun eğerek ve gizlice yalvararak O’na dua ederken karanın ve denizin karanlıklarından sizi kim kurtarabilir ki!”"},{"n":64,"t":"De ki: “Allah sizi onlardan (karanın ve denizin tehlikelerinden) ve bütün sıkıntılardan kurtarır. Sonra siz yine O’na ortak koşarsınız.”"},{"n":65,"t":"De ki: “O’nun size üstünüzden (gökten) veya ayaklarınızın altından (yerden) bir azap göndermeye ya da birbirinize düşürüp birbirinizin öfkesini tattırmaya da gücü yeter.” Bak, anlasınlar diye ayetleri nasıl açıklıyoruz!"},{"n":66,"t":"(Kur’an) gerçek olduğu hâlde kavmin onu yalanladı. De ki: “Ben size asla vekil (güven kaynağı) değilim.”"},{"n":67,"t":"Her haberin gerçekleşeceği bir zamanı vardır. İleride (gerçeği) bileceksiniz."},{"n":68,"t":"Ayetlerimiz hakkında ileri geri konuşanları gördüğün zaman, onlar başka bir konuşmaya (konuya) geçinceye kadar onlardan yüz çevir! Şeytan sana unutturursa, hatırladıktan sonra zalimlerle birlikte bulunma!"},{"n":69,"t":"Takvâ (duyarlılık) sahiplerine, onların (inkârcıların) hesabından herhangi bir şey (sorumluluk) yoktur. Fakat umulur ki takvâlı (duyarlı) olurlar diye (gerçekleri onlara) hatırlatmak (gerekir)."},{"n":70,"t":"Dinlerini oyun ve eğlence edinen ve dünya hayatının aldattığı kişileri terk et! (Yine de) kazandıkları sebebiyle hiçbir nefsin (mahşerde) alıkonmaması için onunla (Kur’an’la) gerçeği hatırlat! O (inkârcı her nefis) için Allah’tan başka hiçbir dost ve şefaatçı yoktur. (Her nefis), bütün varını fidye olarak verse, yine de ondan kabul edilmez. Onlar, kazandıkları (günahlar) yüzünden (mahşerde) alıkonulmuş olacaklardır. İnkâr ettiklerinden dolayı onlar için kaynar sudan ibaret bir içecek ve elem verici bir azap vardır."},{"n":71,"t":"De ki: “Allah’ı bırakıp da bize yarar da zarar da veremeyecek olan şeylere mi yalvaralım? Allah bizi doğru yola ulaştırdıktan sonra, halkının ‘Bize gel!’ diye doğru yola çağırdıkları hâlde, şeytanların ayartıp şaşkın şaşkın yeryüzünde dolaştırdığı kimse gibi topuklarımız üzerinde gerisin geri (inkârcılığa) mı döndürüleceğiz?” De ki: “Şüphesiz ki Allah’ın rehberliği, gerçek rehberliktir. Bize ‘âlemlerin Rabbine teslim olmamız’ emredilmiştir."},{"n":72,"t":"(Bize) ‘Namazı doğru kılın ve takvâlı (duyarlı) olun’ (diye de emredilmiştir). (Huzurunda) toplanacağınız da yalnızca O’dur."},{"n":73,"t":"O, gökleri ve yeri bir amaç ile yaratandır. ‘Ol!’ dediği gün (her şey) hemen olmaya başlar. O’nun sözü gerçektir. Sûr’a üflenecek gün de otorite yalnızca O’na aittir. Gaybı (bilinemeyeni, görünmeyeni) de görüneni de bilendir. O, doğru hüküm verendir, haberdardır.”"},{"n":74,"t":"Hani İbrahim, babası Âzer’e “Birtakım putları ilahlar mı ediniyorsun? Doğrusu ben seni de kavmini de apaçık bir sapkınlık içinde görüyorum.” demişti."},{"n":75,"t":"Böylece biz kesin iman edenlerden olması için İbrahim’e göklerin ve yerin egemenliğini gösteriyorduk."},{"n":76,"t":"Gece(nin karanlığı) onu kaplayınca bir gezegen (gök cismi) görmüş, “Bu (muymuş) benim rabbim!” demişti. (Gezegen) batınca da “Batanları sevmem.” demişti."},{"n":77,"t":"Ayı doğarken görünce “Bu (muymuş) benim rabbim!” demişti. O da batınca, “Rabbim bana doğru yolu göstermemiş olsaydı elbette sapkın topluluktan olur(d)um.” demişti."},{"n":78,"t":"Güneşi doğarken görünce de “Bu daha büyük. (Bu durumda) bu (muymuş) benim rabbim!” demişti. O da batınca, “Ey kavmim! Ben sizin (Allah’a) ortak koştuğunuz şeylerden uzağım!” demişti."},{"n":79,"t":"(İbrahim, kavmine şöyle demişti): “Ben hanîf (Allah’ı birleyen) olarak yüzümü gökleri ve yeri yoktan yaratan (Allah)a çevirdim ve ben müşriklerden değilim.”"},{"n":80,"t":"Kavmi onunla tartışmaya girişmişti. Onlara “Beni doğru yola ulaştırmışken, Allah hakkında benimle siz mi tartışıyorsunuz?” demişti. “Ben sizin O’na ortak koştuğunuz şeylerden korkmam. Ancak, Rabbimin bir şey dilemesi hariç! Rabbimin bilgisi her şeyi kapsamıştır. (Gerçeği) hatırlamıyor musunuz?"},{"n":81,"t":"Allah’ın size haklarında hiçbir hüküm indirmediği şeyleri O’na ortak koşmaktan korkmazken, ben sizin ortak koştuğunuz şeylerden nasıl korkarım ki!” Şimdi biliyorsanız (söyleyin), iki gruptan hangisi güvende olmaya daha layıktır?"},{"n":82,"t":"İman edenler ve imanlarına herhangi bir zulüm (şirk) bulaştırmayanlar var ya işte güven onlarındır ve onlar doğru yola ulaştırılmışlardır."},{"n":83,"t":"İşte şu(nlar), kavmine karşı İbrahim’e verdiğimiz delillerimizdir. Dilediğimizi (layık olanı) derecelerle yükseltiriz. Şüphesiz ki Rabbin, doğru hüküm verendir, bilendir."},{"n":84,"t":"Biz ona İshak ve (İshak’ın oğlu) Yakup’u armağan etmiş, hepsini de doğru yola ulaştırmıştık. Daha önce de Nuh’u ve onun soyundan Davud’u, Süleyman’ı, Eyüp’ü, Yusuf’u, Musa’yı ve Harun’u doğru yola ulaştırmıştık. Biz güzel davrananları işte böyle ödüllendiririz."},{"n":85,"t":"Zekeriya, Yahya, İsa ve İlyas’ı da (doğru yola ulaştırmıştık). Hepsi de iyilerdendi."},{"n":86,"t":"İsmail, Elyesa, Yunus ve Lut’u da (doğru yola ulaştırmıştık). Hepsini âlemlere üstün kılmıştık."},{"n":87,"t":"Onların, babalarından, çocuklarından ve kardeşlerinden bazılarını da (doğru yola ulaştırmıştık). Onları biz seçmiş ve doğru yola ulaştırmıştık."},{"n":88,"t":"İşte bu, Allah’ın hidayetidir, kullarından dilediğini (layık olanı) ona ulaştırır. Onlar da Allah’a ortak koşsalardı, yaptıkları işler elbette boşa giderdi."},{"n":89,"t":"İşte onlar, kendilerine kitap, hikmet (doğru hüküm verme yeteneği) ve peygamberlik verdiğimiz kişilerdir. Onlar (kâfirler) bunları inkâr ederse elbette yerlerine bunları inkâr etmeyecek bir toplum getiririz."},{"n":90,"t":"İşte onlar (peygamberler), Allah’ın doğru yola ulaştırdığı kişilerdir. Sen de onların yoluna uy! De ki: “Ben buna (peygamberlik görevime) karşılık sizden hiçbir ücret istemiyorum. Bu (Kur’an), âlemler için ancak bir hatırla(t)madır.”"},{"n":91,"t":"(İnkârcılar) Allah’ı gerektiği gibi tanımadılar; çünkü “Allah hiçbir insana hiçbir şey indirmemiştir!” demişlerdi. De ki: “Musa’nın insanlara bir nûr (ışık) ve rehber olarak getirdiği, kâğıtlara yazıp (istediğinizi) açıkladığınız, çoğunu gizlediğiniz ve sizin de atalarınızın da bilemediği şeylerin size öğretildiği Kitabı kim indirdi?” De ki: “(Kitabı da indiren) Allah’tır; sonra onları bırak, daldıkları batılda oyalanadursunlar!”"},{"n":92,"t":"Bu (Kur’an), şehirlerin anasını (Mekke)yi ve çevresindekileri uyarman için sana indirdiğimiz ve kendinden öncekileri doğrulayıcı bereket kaynağı bir kitaptır. Ahirete inananlar buna (Kur’an’a) da inanır ve onlar ibadetini yapmaya devam ederler."},{"n":93,"t":"Allah’a iftira edenden veya kendisine hiçbir şey vahyedilmemişken “Bana da vahyolundu.” diyenden ve “Ben de Allah’ın indirdiği ayetlerin benzerini indireceğim!” diyenden daha zalim kim olabilir ki! Ölümün (boğucu) dalgaları içinde, melekler de ellerini uzatmış, onlara “Canlarınızı çıkarın!” derken o zalimlerin hâlini bir görsen! Allah hakkında gerçek olmayanı söylemeniz ve O’nun ayetlerine karşı kibirlilik taslamış olmanız nedeniyle bugün alçaklık azabı ile cezalandırılacaksınız!"},{"n":94,"t":"Yemin olsun ki sizi ilk kez yarattığımız gibi teker teker bize gelmiş ve (dünyada) size verdiğimiz şeyleri arkanızda bırakmış (olacaksınız). Ortaklarımız sandığınız şefaatçılarınızı da beraberinizde göremiyoruz. Şüphesiz ki (ilişkiniz) kesilmiş ve (şefaatçı ilah) sandığınız şeyler sizden kaybolup gitmiştir."},{"n":95,"t":"Şüphesiz ki Allah; tohumu ve çekirdeği yarandır (çatlatandır). (Böylece) ölüden diriyi; diriden de ölüyü çıkarandır. İşte Allah budur. Nasıl oluyor da (gerçeklerden) döndürülüyorsunuz!"},{"n":96,"t":"O, sabahı da yarandır (aydınlatandır). Geceyi dinlenme zamanı, güneşi ve ayı birer hesap ölçüsü kılmıştır. İşte bu, güçlü ve bilen (Allah)’ın ölçüsüdür."},{"n":97,"t":"O, kara ve denizin karanlıklarında kendileri ile yol bulasınız diye sizin için yıldızları yaratandır. Elbette biz bilen bir toplum için ayetleri geniş geniş açıkladık."},{"n":98,"t":"O, sizi tek bir nefisten (candan/cevherden) yaratandır. (Sizin için) bir durma yeri, bir de bırakılacak yer vardır. Elbette anlayan bir toplum için ayetleri ayrıntılı bir şekilde açıkladık."},{"n":99,"t":"O, gökten su indirendir. İşte biz her çeşit bitkiyi onunla (topraktan bitirip) çıkarmaktayız. Ondan (o bitkiden) de kendisinde üst üste binmiş taneler bitireceğimiz bir yeşillik, hurmanın tomurcuğundan sarkan salkımlar, bir kısmı birbirine benzeyen, bir kısmı da benzemeyen üzüm bağları, zeytin ve nar bahçeleri çıkarıp (yaratmaktayız). Oluşurken meyvesine ve olgunlaşmış hâline bakın! Kuşkusuz bütün bunlarda, inanan bir toplum için dersler vardır."},{"n":100,"t":"Cinleri Allah’a ortaklar koştular. (Oysa) onları da (Allah) yaratmıştı. Bilgisizce O’na oğullar ve kızlar yakıştırdılar. O, onların ileri sürdüğü yakıştırmalardan yücedir."},{"n":101,"t":"Göklerin ve yerin yoktan yaratıcısıdır. O’nun eşi (hanımı) olmadığı hâlde nasıl çocuğu olabilir ki! Her şeyi yaratmıştır ve O her şeyi bilendir."},{"n":102,"t":"İşte Rabbiniz Allah budur. O’ndan başka ilah yoktur. Her şeyin yaratıcısıdır. (Öyle ise) O’na kulluk edin! O, her şeye vekildir (güven kaynağıdır)."},{"n":103,"t":"Gözler O’nu idrak edemez (göremez); (oysa) O, gözleri idrak eder (görür). O derin bilgi sahibidir, haberdardır."},{"n":104,"t":"(De ki:) “Elbette size Rabbiniz tarafından öngörüler gelmiştir. Artık kim (gerçeği) görürse yararı kendisine, kim de kör davranırsa zararı kendisinedir. Ben üzerinize asla bekçi değilim.”"},{"n":105,"t":"Böylece biz ayetleri geniş geniş açıklıyoruz ki “Sen ders almışsın.” desinler de biz de bilen bir toplum için onu (Kur’an’ı) iyice açıklayalım."},{"n":106,"t":"Kendisinden başka ilah olmayan Rabbinden sana vahyedilmiş olana uy! Müşriklerden yüz çevir!"},{"n":107,"t":"Allah dileseydi, onlar (Allah’a) ortak koşamazlardı. Biz seni onların üzerine bir bekçi kılmadık. Sen onlar üzerinde asla vekil (güven kaynağı) da değilsin."},{"n":108,"t":"Allah’ın peşi sıra (varlıklara) yalvaranlara (bile) sövmeyin; (sonra) onlar da bilmeyerek Allah’a söverler. Böylece biz her ümmete kendi işlerini süslü gösterdik. Sonunda dönüşleri sadece Rablerinedir. O da yaptıklarını kendilerine bildirecektir."},{"n":109,"t":"Kendilerine bir ayet (mucize) gelirse ona mutlaka inanacaklarına dair güçlü bir şekilde Allah’a yemin etmişlerdi. De ki: “Ayetler (mucizeler) yalnızca Allah’ın katındadır. (Mucizeler) geldiğinde de inanmayacaklarının farkında mısınız?”"},{"n":110,"t":"Ona (vahye) iman etmedikleri ilk durumdaki gibi onların gönüllerini ve gözlerini ters çeviririz. Onları azgınlıkları içerisinde bocalar hâlde bırakırız."},{"n":111,"t":"Biz onlara melekleri indirseydik, ölüler onlara konuşsaydı ve her şeyi toplayıp karşılarına getirseydik, Allah dilemedikçe yine de inanacak değillerdi fakat çoğu bilmezler."},{"n":112,"t":"Böylece biz (insanları) aldatmak için birbirlerine yaldızlı sözler vahyeden (fısıldayan) insan ve Cin şeytanlarını her peygambere düşman kıldık. Rabbin dileseydi onu da yapamazlardı. Artık onları uydurdukları şeylerle bırak!"},{"n":113,"t":"Ahirete inanmayanların kalpleri ona (yaldızlı söze) kansın, ondan hoşlansınlar ve işledikleri suçu işlemeye devam etsinler diye (böyle yaparlar)."},{"n":114,"t":"(De ki): “Size (gerçekler) apaçık ortaya konulmuş olarak Kitabı indiren Allah’tan başka bir hakem mi arayacakmışım!” Doğrusu kendilerine kitap verdiğimiz kişiler, onun (Kur’an’ın) Rabbin tarafından indirilmiş olduğunu bilirler. Sakın şüpheye düşenlerden olma!"},{"n":115,"t":"Rabbinin söz(leri), doğruluk ve Adalet bakımından tamamlanmıştır. O’nun sözlerini değiştirecek kimse yoktur. O, duyandır, bilendir."},{"n":116,"t":"Yeryüzünde bulunanların çoğuna uyacak olursan, seni Allah’ın yolundan saptırırlar. Onlar, zandan başka bir şeye uymuyorlar ve onlar yalandan başka bir şey söylemiyorlar."},{"n":117,"t":"Şüphesiz ki Rabbin -evet yalnızca O- kendi yolundan kimin sapmakta olduğunu iyi bilendir ve O kimlerin doğru yola ulaştırıldığını da iyi bilendir."},{"n":118,"t":"O’nun ayetlerine inanıyorsanız, üzerine Allah’ın adı anılan (hayvan)lardan yiyin!"},{"n":119,"t":"Üzerine Allah’ın adı anılan (hayvan)lardan yememenize sebep nedir ki! (Oysa Allah), mecbur bırakıldıklarınız dışında, haram kıldığı şeyleri elbette size ayrıntılı açıklamıştır. Doğrusu birçoğu, bilgisizce kendi arzularına uyarak (insanları) saptırıyorlar. Şüphesiz ki Rabbin, haddi aşanları çok iyi bilendir."},{"n":120,"t":"Haramın açığını da gizlisini de bırakın! Haram işleyenler, yaptıklarının cezasını mutlaka ileride çekeceklerdir."},{"n":121,"t":"Üzerine Allah’ın adı anılmayan (hayvan)lardan yemeyin! Şüphesiz ki o elbette yoldan çıkmaktır. Şüphesiz ki şeytanlar, dostlarına sizinle mücadele etmeleri için vahyeder (fısıldar)lar. Onlara uyarsanız siz de müşrik olursunuz."},{"n":122,"t":"(Manen) ölüyken (Vahiy ile) dirilttiğimiz ve kendisine insanlar arasında yürüyebileceği bir nûr (ışık) verdiğimiz kimse, karanlıklar içinde kalıp ondan hiç çıkamayacak durumdaki kimse gibi olur mu? İşte yaptıkları şeyler kâfirlere böyle süslü gösterilmiştir."},{"n":123,"t":"Böylece biz her şehirde oranın suçlularını liderler yaptık; sonunda oralarda bozgunculuk yapmayı tercih ederler. Onlar, kendilerinden başkasını aldatamazlar; (fakat) farkında olmazlar."},{"n":124,"t":"Onlara bir delil geldiğinde, “Allah’ın elçilerine verilenin benzeri bize de verilinceye kadar elbette inanmayız!” dediler. Allah, elçiliği kime vereceğini çok iyi bilendir. Suç işleyenlere, (dünyada) yapmış oldukları hilelere karşılık Allah katında aşağılanma ve şiddetli bir azap isabet edecektir."},{"n":125,"t":"Allah kimi doğru yola ulaştırmak isterse onun göğsünü İslam’a açar. Kimi de saptırmak isterse (sapkınlıkta bıraktığı o kişinin) göğsünü sanki göğe çıkıyormuş gibi iyice daraltıp sıkıştırır. Allah inanmayanların üstüne işte böyle pislik verir."},{"n":126,"t":"Rabbinin doğru yolu işte budur. Biz (gerçeği) hatırlayacak bir toplum için ayetleri elbette ayrıntılı olarak açıkladık."},{"n":127,"t":"Rableri katında onlara barış yurdu (cennet) vardır. Yapmış oldukları (güzel) işler sebebiyle O, onların dostudur."},{"n":128,"t":"(Allah) onların hepsini bir araya toplayacağı gün, “Ey cinler (şeytanlar) topluluğu! Siz, insanlarla çok uğraştınız!” (diyecektir). İnsanlardan olan dostları ise “Rabbimiz! (Biz) birbirimizden yararlandık ve bize verdiğin sürenin sonuna ulaştık.” diyecekler. (Allah da şöyle) diyecektir: “Allah’ın dilediği hariç, ateş, içinde ebedî kalacağınız yerdir. Şüphesiz ki Rabbin, doğru hüküm verendir, bilendir.”"},{"n":129,"t":"İşte böylece işledikleri (günahlar) nedeniyle zalimlerin bir kısmını diğer bir kısmına dost/yoldaş yaparız."},{"n":130,"t":"(Allah) “Ey cin ve insan topluluğu! İçinizden size ayetlerimi anlatan ve bu gününüzle karşılaşacağınıza dair sizi uyaran elçiler gelmedi mi?” (deyince), onlar “Kendi aleyhimize şahitlik ederiz.” demiş olacaklardır. Dünya hayatı onları aldatmış ve kâfir olduklarına dair kendi aleyhlerine şahitlik etmiş (olacak)lardır."},{"n":131,"t":"Gerçek şu ki halkı habersizken Rabbin, haksızlık ile şehirleri helak edici değildir."},{"n":132,"t":"Herkesin yaptığı işlere göre dereceleri vardır. Rabbin onların yaptıklarından asla habersiz değildir."},{"n":133,"t":"Rabbin zengindir, merhamet sahibidir. Dilerse sizi yok eder ve sizi başka bir toplumun neslinden yarattığı gibi sizden sonra yerinize dilediği (bir toplumu) getirir."},{"n":134,"t":"Size vadedilen mutlaka gelecektir; siz (bunları) asla aciz bırakıcılar değilsiniz."},{"n":135,"t":"De ki: “Ey kavmim! Elinizden geleni yapın; ben de yapacağım! Yurdun (bu dünyanın) sonunun kimin olacağını ileride bileceksiniz. Şüphesiz ki zalimler kurtulamazlar.”"},{"n":136,"t":"Yarattığı ekinlerle hayvanlardan Allah’a birer pay ayırıp, zanlarınca “Bu Allah için, bu da ortaklarımız (putlarımız) için.” dediler. Ortakları için ayrılan (pay) Allah’a ulaşmıyor, Allah için ayrılan (pay ise) ortaklarına ulaşıyor! Vermekte oldukları hüküm (ne) kötüdür!"},{"n":137,"t":"Aynı şekilde, ortakları, müşriklerden çoğuna çocuklarını (kızlarını) öldürmeyi hoş gösterdi ki hem kendilerini mahvetsinler hem de dinlerini karıştırıp bozsunlar! Allah dileseydi bunu yapamazlardı. Onları uydurdukları ile bırak!"},{"n":138,"t":"Onlar zanlarına göre dediler ki: “Bu (ilahlar için ayrılan) hayvanlar ve ekinler haramdır. Bunları bizim dilediğimizden başkası yiyemez. Bunlar da binilmesi yasaklanmış hayvanlardır.” Birtakım hayvanlar da vardır ki (Allah böyle emrediyor diye) O’na iftira ederek üzerlerine Allah’ın adını anmazlar. Yapmakta oldukları iftiralar yüzünden Allah onları ileride cezalandıracaktır."},{"n":139,"t":"Dediler ki: “Şu hayvanların karınlarında olanlar(ın etleri) yalnız erkeklerimize aittir, eşlerimize (kadınlarımıza) ise haram kılınmıştır. (Yavru) ölü doğarsa, o zaman (kadın erkek) hepsi onda ortaktır.” (Allah) ileride bu değerlendirmelerinin cezasını verecektir. Şüphesiz ki O, doğru hüküm verendir, bilendir."},{"n":140,"t":"Bilgisizlikleri yüzünden beyinsizce çocuklarını öldürenler ve Allah’ın kendilerine verdiği rızkı, Allah’a iftira ederek (kadınlara) haram kılanlar, elbette kaybetmişlerdir. Onlar, elbette sapmışlardır ve doğru yolda değillerdir."},{"n":141,"t":"Çardaklı ve çardaksız bahçeler, hurma(lar), ürünleri çeşitli ekinler, birbirine benzeyen ve benzemeyen biçimde zeytin ve narları yaratan O’dur. Her biri meyve verdiği zaman meyvesinden yiyin! Toplandığı gün de hakkını (zekâtını ve sadakasını) verin (fakat) israf etmeyin! Şüphesiz ki O, israf edenleri sevmez."},{"n":142,"t":"Hayvanlardan yük taşıyanı ve tüyünden (kılından) döşek yapılanları da (yaratandır). Allah’ın sizi rızıklandırdığı şeylerden yiyin! Şeytanın adımlarını izlemeyin! Şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":143,"t":"(Dişi ve erkek) sekiz eş (yarattı): Koyundan iki, keçiden iki. De ki: “(Allah) bunların erkeklerini mi dişilerini mi yoksa bu iki dişinin rahimlerinde bulunan (yavrular)ı mı haram kılmış! Doğruysanız bana bilgiyle söyleyin!”"},{"n":144,"t":"Deveden de iki, inekten de iki (çift yarattı). De ki: “(Allah), bunların erkeklerini mi dişilerini mi yoksa bu iki dişinin rahimlerinde bulunan (yavrular)ı mı haram kılmış! Yoksa Allah’ın size böyle vasiyet ettiğine şahit mi oldunuz?” Bilgisizce insanları saptırmak için Allah’a yalan uydurandan daha zalim kim olabilir ki! Şüphesiz ki Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":145,"t":"De ki: “Bana vahyolunanda, leş veya akıtılmış kan veya domuz eti –ki bu pisliğin kendisidir– ya da günah işlenerek Allah’tan başkası adına kesilmiş bir hayvandan başka, onu yiyecek kimseye haram kılınmış bir şey bulamıyorum.” (Ancak) azgınlık yapmayacak ve sınırı aşmayacak şekilde kim (bunlardan yemek) zorunda kalırsa, (bilsin ki) Rabbin çok bağışlayandır, çok merhametlidir."},{"n":146,"t":"Yahudilere bütün tırnaklı hayvanları haram kılmıştık. Sırtlarının veya bağırsaklarının taşıdığı ya da kemiğe karışan yağlar hariç olmak üzere, sığır ve koyunun iç yağlarını da onlara (haram kılmıştık). Bu (durum), haksızlıkları yüzünden onlara verdiğimiz cezadır. Şüphesiz ki biz elbette doğru söyleyenleriz."},{"n":147,"t":"Seni yalanlarsa (onlara) de ki: “Rabbiniz geniş merhamet sahibidir. O’nun azabı, suçlular topluluğundan geri döndürülemez.”"},{"n":148,"t":"Müşrikler şöyle diyecekler: “Allah dileseydi biz de ortak koşmazdık; atalarımız da. Hiçbir şeyi de haram kılmazdık.” Onlardan öncekiler de aynı şekilde (peygamberleri) yalanlamış ve sonunda azabımızı tatmışlardı. De ki: “Yanınızda bize açıklayacağınız bir bilgi var mı? Doğrusu siz zandan başka bir şeyin peşine düşmüyor ve sadece yalan söylüyorsunuz.”"},{"n":149,"t":"De ki: “Kesin (en üstün) delil, yalnızca Allah’a aittir. (Allah) dileseydi elbette hepinizi doğru yola ulaştırırdı.”"},{"n":150,"t":"De ki: “Allah şunu yasakladı diye şahitlik edecek şahitlerinizi getirin!” Onlar (yalan yere) şahitlik ederlerse, sen onlarla birlikte şahitlik etme! Ayetlerimizi yalanlayan ve ahiret gününe inanmayanların arzularına uyma! Onlar, (başka varlıkları) Rablerine denk tutuyorlar."},{"n":151,"t":"De ki: “Gelin Rabbinizin size neleri saygın kıldığını tilavet edeyim (okuyup aktarayım): O’na hiçbir şeyi ortak koşmayın ve ana babaya iyilik (edin)! Fakirlik korkusuyla çocuklarınızı öldürmeyin; (çünkü) sizi de onları da biz rızıklandırmaktayız. Çirkinliklerin açığına da gizlisine de yaklaşmayın! Allah’ın saygın kıldığı (öldürülmesini yasakladığı) canı haksız yere öldürmeyin! İşte bunlar (Allah’ın) size emrettikleridir. Umulur ki akıl edersiniz."},{"n":152,"t":"Yetimin malına, yetişkinlik zamanına ulaşıncaya kadar en güzel olanın dışında sakın yaklaşmayın! Ölçü ve tartıyı adaletle yapın! Biz kimseye gücünün yeteceğinden başkasını yüklemeyiz. Söz söylediğiniz zaman, akraba bile olsa adil olun! Allah’a (verdiğiniz) sözü tutun! İşte bunlar (O’nun) size emrettikleridir. Umulur ki (gerçeği) hatırlarsınız."},{"n":153,"t":"Şüphesiz ki bu benim doğru yolumdur; ona uyun! (Başka) yollara uymayın! (O yollar) sizi (Allah’ın) yolundan ayırır. İşte bunlar takvâlı olmanız için (Allah’ın) size emrettikleridir."},{"n":154,"t":"Sonra iyilik edenlere (nimetimizi) tamamlamak ve her şeyi açıklamak için, bir rehber ve rahmet olarak Musa’ya da Kitabı vermiştik. Umulur ki Rableriyle buluşmaya iman ederler."},{"n":155,"t":"İşte bu (Kur’an da) bizim indirdiğimiz bereket kaynağı bir kitaptır. Ona uyun ve takvâlı (duyarlı) olun ki size merhamet edilsin!"},{"n":156,"t":"“Kitap, sadece bizden önceki iki topluluğa (yahudi ve hristiyanlara) indirildi. Doğrusu biz onların okumasından habersizdik.” dersiniz diye (Kur’an’ı indirdik)."},{"n":157,"t":"Veya “Kitap (ilahî mesaj) bize indirilseydi, biz onlardan daha fazla doğru yolda olurduk.” dersiniz diye (Kur’an’ı indirdik). Elbette size de Rabbinizden apaçık bir delil, bir rehber ve rahmet gelmiştir. Allah’ın ayetlerini yalanlayıp onlardan yüz çevirenden daha zalim kim olabilir ki! Ayetlerimizden yüz çevirenleri, yüz çevirmeleri nedeniyle ileride azabın en kötüsüyle cezalandıracağız."},{"n":158,"t":"Onlar ille de kendilerine meleklerin veya Rabbinin (azap emrinin) gelmesini veya Rabbinin bazı delillerinin gelmesini mi bekliyorlar? Rabbinin bazı delilleri geldiği gün, önceden inanmamış veya imanında bir hayır kazanmamış olan kimseye artık imanı bir yarar sağlamaz. De ki: “Bekleyin! Şüphesiz ki biz de bekleyenleriz.”"},{"n":159,"t":"Dinlerini parça parça edip gruplara ayrılanlar var ya, senin onlarla hiçbir ilişkin yoktur. Onların işi ancak Allah’a kalmıştır. Sonra (Allah) onlara yapmış olduklarını (mahşerde) bildirecektir."},{"n":160,"t":"Kim (Allah huzuruna) iyilikle gelirse ona getirdiğinin on katı vardır. Kim de kötülükle gelirse o sadece getirdiğinin dengiyle cezalandırılır. Onlar haksızlığa uğratılmazlar."},{"n":161,"t":"De ki: “Şüphesiz ki Rabbim beni doğru yola, doğru dine, (Allah’ı) bir tanıyan ve müşriklerden olmayan İbrahim’in milletine (dinine) ulaştırdı.”"},{"n":162,"t":"De ki: “Şüphesiz ki benim salâtım (desteğim), ibadetlerim, hayatım ve ölümüm âlemlerin Rabbi olan Allah içindir."},{"n":163,"t":"O’nun hiçbir ortağı yoktur. Ben bununla emrolundum ve ben müslümanların ilkiyim (öncüsüyüm).”"},{"n":164,"t":"De ki: “O, her şeyin Rabbiyken ben Allah’tan başka Rab mı arayacakmışım!” Herkesin kazanacağı (kötülük) yalnız kendi aleyhinedir. Hiçbir (günah) yüklüsü, başkasının (günah) yükünü yüklenemez. Sonunda dönüşünüz sadece Rabbinizedir ve O, anlaşmazlığa (çelişkiye) düşmüş olduğunuz şeyleri size bildirecektir."},{"n":165,"t":"Sizi yeryüzünün halifeleri (sorumluları olarak) görevlendiren ve verdiği (nimetler) hakkında sizi denemek için kiminizi kiminizden derecelerle üstün kılan O’dur. Şüphesiz ki Rabbin, cezası hızlı olandır. Şüphesiz ki O, çok bağışlayandır, çok merhametlidir."}],[{"n":1,"t":"Elif. Lâm. Mîm. Sâd."},{"n":2,"t":"Kendisiyle uyarman için ve müminlere (gerçeği) hatırlatma olsun diye sana indirilen bu kitaptan dolayı kalbinde hiçbir sıkıntı olmasın!"},{"n":3,"t":"Rabbinizden size indirilene (Kur’an’a) uyun! O’nun peşi sıra (onu bırakıp da) başka dostlara uymayın! Ne kadar da azınız (gerçeği) hatırlıyor!"},{"n":4,"t":"Nice şehirler vardı ki biz onları helak etmiştik. Azabımız onlara gece veya gündüz uyurlarken gelmişti."},{"n":5,"t":"Azabımız kendilerine geldiğinde “Biz zalimlermişiz!” diye sızlanıp yalvarmaktan başka sözleri kalmamıştı."},{"n":6,"t":"Elbette kendilerine elçi gönderilenleri de elçileri de sorgulayacağız."},{"n":7,"t":"Onlara (bütün olup bitenleri) tam bir bilgi ile elbette anlatacağız. Zaten biz onlardan habersiz değildik."},{"n":8,"t":"O günkü terazi tamamen hakka uygun olacaktır. Kimin terazi(de sevap)ları ağır gelirse, işte onlar kurtulanlardır."},{"n":9,"t":"Kimin de terazi(de sevap)ları hafif gelirse, işte onlar ayetlerimize karşı haksızlık ettiklerinden dolayı kendilerine yazık edenlerdir."},{"n":10,"t":"Yemin olsun ki sizi yeryüzüne biz yerleştirdik ve orada sizin için (gerekli) geçim vasıtaları sağladık. Ne kadar da azınız şükrediyor!"},{"n":11,"t":"Yemin olsun ki sizi biz yaratmış, sonra size biçim vermiş, sonra da meleklere, “Âdem için (Allah’a) secde edin.” demiştik; onlar da hemen secde etmişlerdi. İblis hariç. O, secde edenlerden olmamıştı."},{"n":12,"t":"(Allah) şöyle demişti: “Ben sana emretmişken seni secde etmekten alıkoyan neydi?” (İblis de) “Ben ondan hayırlıyım (üstünüm). Beni ateşten yarattın; onu çamurdan yarattın.” demişti."},{"n":13,"t":"(Allah) “İn oradan! Orada kibirlenmek senin haddine değildir. Çık, (git); şüphesiz ki sen aşağılıklardansın!” demişti."},{"n":14,"t":"14-15 (İblis) “Bana, (insanların) tekrar diriltilecekleri güne kadar zaman tanı.” deyince, (Allah da) “(Tamam), sen zaman tanınanlardansın.” demişti"},{"n":15,"t":"14-15 (İblis) “Bana, (insanların) tekrar diriltilecekleri güne kadar zaman tanı.” deyince, (Allah da) “(Tamam), sen zaman tanınanlardansın.” demişti"},{"n":16,"t":"(İblis) “Beni saptırmana karşılık, ben de onları (saptırmak) için senin doğru yolunun üzerine oturacağım."},{"n":17,"t":"Sonra elbette onlara önlerinden, arkalarından, sağlarından, sollarından gelip (sokul)acağım; sen onların çoğunu şükredenler olarak bulamayacaksın!” demişti."},{"n":18,"t":"(Allah ise) şöyle demişti: “Yerilmiş ve kovulmuş olarak çık oradan! İnsanlardan sana kim uyarsa, sizden hepinizi cehenneme dolduracağım.”"},{"n":19,"t":"(Allah): “Ey Âdem! Sen ve eşin şu bahçede yerleşip dilediğiniz yerden (ürünlerden) yiyin! Şu ağaca yaklaşmayın; yoksa kaybedenlerden olursunuz!” (demişti)."},{"n":20,"t":"(O sırada) şeytan, birbirine kapalı edep yerlerini kendilerine göstermek için onlara (Âdem ve eşine) vesvese vermiş, “Rabbiniz size bu ağacı ancak melek olursunuz veya çok uzun yaşayanlardan olursunuz diye yasakladı!” demişti."},{"n":21,"t":"“Doğrusu ben sizin için öğüt verenlerdenim!” diye yemin etmişti."},{"n":22,"t":"Onları aldatarak (yasağı işlemeye) sarkıtmış (sevk etmiş)ti. (Yasak) ağacı tattıklarında edep yerleri kendilerine görünmüştü. (Ardından) bahçenin yapraklarından üzerlerine örtmeye başlamışlardı. Rableri onlara “Ben sizi o ağaçtan engellememiş miydim ve size ‘Şeytan, sizin apaçık düşmanınızdır’ dememiş miydim?” diye seslenmişti."},{"n":23,"t":"(Âdem ve eşi) şöyle dua etmişlerdi: “Rabbimiz! Biz kendimize haksızlık ettik. Bizi bağışlamaz ve bize merhamet etmezsen elbette kaybedenlerden olacağız.”"},{"n":24,"t":"(Bunun üzerine Allah) “Bir kısmınız diğerine düşman olarak inin! Sizin için yeryüzünde (bahçe dışında) belirli bir süre kalma ve geçim imkânları vardır.” demişti."},{"n":25,"t":"“Orada yaşayacak; orada ölecek ve oradan (diriltilip) çıkartılacaksınız.” demişti."},{"n":26,"t":"Ey âdemoğulları! Size edep yerlerinizi örtecek giysi ve süslenecek elbise indirdik (verdik). Hayırlı olan ise takvâ (duyarlılık) elbisesidir. İşte bu, (gerçeği) hatırlasınlar diye Allah’ın ayetlerindendir."},{"n":27,"t":"Ey âdemoğulları! Şeytan, ana babanızı, ayıp yerlerini kendilerine göstermek için elbiselerini soyarak o bahçeden çıkardığı gibi sizi de aldatmasın! Çünkü o ve yandaşları, sizin onları göremeyeceğiniz yerden sizi görürler. Şüphesiz ki biz, şeytanları inanmayanların dostları yaptık."},{"n":28,"t":"Onlar bir çirkinlik yaptıkları zaman “Babalarımızı bu yolda bulduk. Allah da bize bunu emretti.” derler. De ki: “Allah çirkinliği emretmez. Allah hakkında bilmediğiniz şeyleri mi söylüyorsunuz?”"},{"n":29,"t":"De ki: “Rabbim adaleti emretmiştir. Her secdede yüzlerinizi O’na yöneltin ve dini yalnız O’na (Allah’a) özgü kılarak O’na dua edin (yalvarın)! Başlangıçta sizi O yarattığı gibi (sonunda yine O’na) döneceksiniz.”"},{"n":30,"t":"Bir kısmı(nız)ı doğru yola ulaştırmış olarak, bir kısmı(nız) hakkında da sapkınlık gerçekleşmiş olarak (O’na döneceksiniz). Şüphesiz ki onlar, kendilerinin doğru yolda olduğunu sanarak Allah’ın peşi sıra şeytanları kendilerine dostlar edinmişlerdi."},{"n":31,"t":"Ey âdemoğulları! Her secdede ziynetinizi takının! Yiyin, için, israf etmeyin! Şüphesiz ki O, israf edenleri sevmez."},{"n":32,"t":"De ki: “Allah’ın kulları için çıkarttığı ziyneti ve temiz rızıkları kim haram kılmış ki!” De ki: “Onlar, kıyamet günü sadece kendilerine özel olmanın yanında dünya hayatında da (sadece inançsızların değil), müminlerindir de. Bilen bir topluluk için ayetleri işte böyle açıklıyoruz.”"},{"n":33,"t":"De ki: “Rabbim ancak ve ancak açık ve gizli çirkinlikleri, günahı, azgınlık yapmayı, hakkında hiçbir delil indirmediği herhangi bir şeyi Allah’a ortak koşmanızı ve Allah hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır.”"},{"n":34,"t":"Her ümmetin bir süresi vardır. Süreleri gelince ne bir saat (bir an) geri kalır ne de öne gelebilirler."},{"n":35,"t":"Ey âdemoğulları! Kendi içinizden size ayetlerimi anlatacak elçiler gelirse, kim takvâlı (duyarlı) davranır ve (bozulmayı) düzeltirse, artık onlara korku yoktur ve onlar üzülmeyecek de."},{"n":36,"t":"Ayetlerimizi yalanlayıp onlara karşı kibirlenenler ise ateş halkıdır; onlar orada ebedî kalıcıdır."},{"n":37,"t":"Allah’a yalan uyduran veya O’nun ayetlerini yalanlayandan daha zalim kim olabilir ki! Onlara, kitapta (yazılı olan azaptan) payları ulaşacaktır. Sonunda onları vefat ettirecek elçilerimiz (melekler) kendilerine geldiğinde “Allah’ın peşi sıra yalvardıklarınız nerede?” diyeceklerdir. Onlar da kâfir olduklarına dair kendi aleyhlerine şahitlik ederek “Bizden kaybolup gitmişler!” diyeceklerdir."},{"n":38,"t":"(Allah şöyle) diyecektir: “Sizden önce geçmiş (cehennemlik olan) cin ve insan toplulukları arasında siz de ateşe girin!” Her topluluk (ateşe) girdikçe yoldaşlarına lanet edecektir. Hepsi birbiri ardına cehennemde toplanınca, sonrakiler önce giren (önderleri) için “Rabbimiz! Bizi işte bunlar saptırdılar! Onlara kat kat ateş azabı ver!” diyeceklerdir. (Allah da) “Zaten herkes için kat kat azap vardır fakat siz bilmezsiniz!” cevabını verecektir."},{"n":39,"t":"Öncekiler sonrakilere şöyle diyecekler: “(Belli ki) sizin bizden hiçbir farkınız yokmuş. Siz de (bizim gibi) yaptıklarınıza karşılık azabı tadın!”"},{"n":40,"t":"Ayetlerimizi yalanlayıp da onlara karşı kibirlenenlere göğün kapıları açılmayacak ve onlar halat/deve iğne deliğine girinceye kadar cennete giremeyeceklerdir! Suçluları işte böyle cezalandıracağız!"},{"n":41,"t":"Onların cehennem ateşinden yatağı, üstlerinden de (ateşten) örtüleri olacaktır. İşte zalimleri böyle cezalandırırız!"},{"n":42,"t":"İman edip iyi işler yapanlara gelince –ki kimseye gücünün üzerinde bir görev yüklemeyiz–, işte onlar da cennet halkıdır; orada ebedî kalacaklardır."},{"n":43,"t":"(Cennette) altlarından ırmaklar akarken, göğüslerinde (kalplerinde) kinden ne varsa hepsini çıkarıp atmış olacağız. (İşte bu cennetlikler) şöyle diyeceklerdir: “Bizi bu (cennete) ulaştıran Allah’a hamdolsun; (çünkü) Allah bize yol göstermeseydi, biz yolumuzu bulamayacaktık. Şüphesiz ki Rabbimizin elçileri gerçeği getirmişler.” Onlara “İşte yaptıklarınıza karşılık miras olarak size verilen cennet burasıdır” diye seslenilecektir."},{"n":44,"t":"44-45 Cennet halkı ateş halkına “Biz Rabbimizin bize vadettiğini gerçekleşmiş bulduk; siz de Rabbinizin size vadettiğini gerçekleşmiş buldunuz mu?” diye seslenecekler; onlar da “Evet!” diyecekler. Aralarında bir çağrıcı “Allah’ın laneti, (insanları) Allah’ın yolundan alıkoyan, o (yol)u eğri gösteren ve ahireti de inkâr eden zalimlerin üzerine olsun!” diye seslenecektir."},{"n":45,"t":"44-45 Cennet halkı ateş halkına “Biz Rabbimizin bize vadettiğini gerçekleşmiş bulduk; siz de Rabbinizin size vadettiğini gerçekleşmiş buldunuz mu?” diye seslenecekler; onlar da “Evet!” diyecekler. Aralarında bir çağrıcı “Allah’ın laneti, (insanları) Allah’ın yolundan alıkoyan, o (yol)u eğri gösteren ve ahireti de inkâr eden zalimlerin üzerine olsun!” diye seslenecektir."},{"n":46,"t":"İki taraf (cennetlikler ve cehennemlikler) arasında bir perde ve a‘rafta herkesi yüzlerinden tanıyan adamlar vardır. (Cennete girmeyi) arzulamalarına rağmen henüz oraya (cennete) giremeyen bu kişiler, cennet halkına “Selam üzerinize olsun!” diye seslenmiş (olacaklar)dır."},{"n":47,"t":"Gözleri ateş halkı tarafına döndürülünce de “Rabbimiz! Bizi zalimler topluluğu ile birlikte bulundurma!” diyecekler."},{"n":48,"t":"A‘raf halkı, yüzlerinden tanıdıkları (cehennemdeki) kişilere şöyle seslenecekler: “Çokluğunuzun da kibirlenmenizin de size hiçbir yararı olmadı."},{"n":49,"t":"(Haklarında) ‘Allah’ın merhameti onlara ulaşmaz!’ diye yemin ettiğiniz kişiler bunlar mı?” (Oysa onlara:) “Cennete girin! Size hiçbir korku yoktur ve siz üzülmeyeceksiniz de.” (denecektir)."},{"n":50,"t":"50-51 Ateş halkı cennet halkına “Su veya Allah’ın size verdiği rızıklardan biraz da bize dökün!” diye seslenince, (cennetlikler) “Allah onları dinlerini bir eğlence ve oyun edinen, dünya hayatı da kendilerini aldatan kâfirlere haram kılmıştır.” diyecekler. Onlar bu günün karşılaşmasını nasıl unutmuş ve ayetlerimizi nasıl inkâr etmişlerse işte biz de bugün onları unutmaktayız."},{"n":51,"t":"50-51 Ateş halkı cennet halkına “Su veya Allah’ın size verdiği rızıklardan biraz da bize dökün!” diye seslenince, (cennetlikler) “Allah onları dinlerini bir eğlence ve oyun edinen, dünya hayatı da kendilerini aldatan kâfirlere haram kılmıştır.” diyecekler. Onlar bu günün karşılaşmasını nasıl unutmuş ve ayetlerimizi nasıl inkâr etmişlerse işte biz de bugün onları unutmaktayız."},{"n":52,"t":"Yemin olsun ki onlara, bilgiyle açıkladığımız ve inanan bir toplum için yol gösterici ve rahmet olan bir kitap getirmiştik (göndermiştik)."},{"n":53,"t":"(Onlar), onun (kitabın) tevilinden (yorumundan) başka bir şey beklemiyorlar. Onun tevili (yorumu, Son Saat) geldiği gün, önceden onu unutmuş olanlar şöyle diyecekler: “Elbette Rabbimizin elçileri gerçeği getirmişler. Şimdi şefaat edebilenler var mı ki bize de şefaat etsinler veya (dünyaya) geri gönderilsek de yaptıklarımızın tersini yapabilsek?” Onlar elbette kendilerine yazık etmişlerdir ve uydurdukları şeyler (putlar) da kendilerinden kaybolup gitmiş olacaktır."},{"n":54,"t":"Şüphesiz ki Rabbiniz, gökleri ve yeri altı günde (dönemde) yaratan, sonra da arşa istiva eden, geceyi durmadan kendisini takip eden gündüze bürüyüp örten, emrine boyun eğdirilmiş olarak güneşi, ayı ve yıldızları da (yaratan) Allah’tır. Dikkat edin! Yaratmak da emretmek de yalnızca O’na aittir. Âlemlerin Rabbi olan Allah ne yücedir!"},{"n":55,"t":"Rabbinize boyun eğerek ve gizlice dua edin! Şüphesiz ki O, haddi aşanları sevmez."},{"n":56,"t":"Düzenine kavuşturulduktan sonra yeryüzünde bozgunculuk yapmayın! O’na (Allah’ın azabından) korkarak ve (merhametini) umarak dua edin! Şüphesiz ki Allah’ın merhameti güzel davrananlara çok yakındır."},{"n":57,"t":"Rahmetinin (yağmurun) önünde rüzgârları müjdeci olarak gönderen O’dur. Sonunda (o rüzgârlar), ağır bulutları yüklenince onu (bulutu) ölü (kurak) bir şehre sevk ederiz. Böylece onun sayesinde (bulut sebebiyle oraya) suyu indirir ve bütün meyvelerden çıkarırız. İşte ölüleri de (topraktan) böyle çıkaracağız. Umulur ki (gerçeği) hatırlarsınız."},{"n":58,"t":"Toprağı iyi olan şehrin bitkisi de Rabbinin izniyle (güzel) çıkar; kötü olanın ise yararsız bitkiden başka bir şeyi çıkmaz. Biz şükreden bir topluluk için ayetleri işte böyle açıklıyoruz."},{"n":59,"t":"Şüphesiz ki Nuh’u elçi olarak kavmine biz göndermiştik de “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. Şüphesiz ki üzerinize gelecek büyük bir günün azabından korkuyorum!” demişti."},{"n":60,"t":"Kavminden yöneticiler ona “Doğrusu biz seni apaçık bir sapkınlık içinde görüyoruz!” demişlerdi."},{"n":61,"t":"(Nuh da onlara) şöyle demişti: “Ey kavmim! Bende herhangi bir sapkınlık yoktur; aksine ben âlemlerin Rabbinin (seçtiği) bir elçiyim."},{"n":62,"t":"Size Rabbimin mesajlarını duyuruyor, size öğüt veriyorum ve ben sizin bilmediklerinizi Allah’tan (gelen vahiy ile) biliyorum.”"},{"n":63,"t":"Sizi uyarsın, takvâlı (duyarlı) olasınız ve size merhamet edilsin diye içinizden bir adama (bir kişiye) Rabbinizden bir hatırlatma gelmesine mi şaştınız?"},{"n":64,"t":"(Kavmi Nuh’u) yalanlamış, biz de onu ve onunla birlikte olanları gemide kurtarmıştık; ayetlerimizi yalanlayanları da (denizde) boğmuştuk! Şüphesiz ki onlar kör bir toplumdu."},{"n":65,"t":"Âd (kavmine) de kardeşleri Hud’u (göndermiştik) de “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. (Hâlâ) takvâlı (duyarlı) davranmayacak mısınız?” demişti."},{"n":66,"t":"Kavminden kâfir olan yöneticiler şöyle demişti: “Doğrusu biz seni elbette bir beyinsizlik içinde görüyor ve yalancılardan olduğuna inanıyoruz.”"},{"n":67,"t":"(Hud da onlara) şöyle demişti: “Ey kavmim! Bende herhangi bir beyinsizlik yoktur; aksine ben âlemlerin Rabbinin (seçtiği) bir elçiyim."},{"n":68,"t":"Size Rabbimin mesajlarını duyuruyorum ve ben sizin için güvenilir bir öğüt vericiyim.”"},{"n":69,"t":"Sizi uyarsın diye içinizden bir adama (bir kişiye) Rabbinizden bir hatırlatma gelmesine mi şaştınız! Hatırlayın ki O (Allah) sizi Nuh kavminden sonra onların yerine getirdi ve yaratılışta sizi onlardan güçlü kıldı. Allah’ın nimetlerini hatırlayın ki kurtulasınız."},{"n":70,"t":"(Kavmi ise) “Sen bize tek Allah’a kulluk etmemiz ve atalarımızın tapmakta olduklarını bırakmamız için mi geldin? Doğru söyleyenlerdensen bize vadettiğini bize getir!” demişti."},{"n":71,"t":"(Hud da onlara) şöyle demişti: “Elbette üzerinize Rabbinizden gelecek bir bela ve azap gerçekleşmiştir. Haklarında Allah’ın hiçbir delil indirmediği, sizin ve atalarınızın taktığı isimler hakkında mı benimle tartışıyorsunuz? (Öyleyse) bekleyin! Şüphesiz ki ben de sizinle birlikte bekleyenlerdenim!”"},{"n":72,"t":"(Bunun üzerine) onu (Hud’u) ve onunla birlikte olanları merhametimizle kurtarmış ve ayetlerimizi yalanlayanların ve iman etmeyenlerin kökünü de kesmiştik."},{"n":73,"t":"Semûd’a da kardeşleri Salih’i (göndermiştik de onlara) şöyle demişti: “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. Elbette size Rabbinizden apaçık bir delil gelmiştir. İşte Allah’ın şu devesi sizin için bir delildir. Onu bırakın da Allah’ın (yarattığı bu) toprakta yesin (otlasın). Ona hiçbir kötülük etmeyin! Yoksa sizi elem verici bir azap yakalar."},{"n":74,"t":"(Allah’ın) Âd (kavmin)den sonra sizi halifeler (sorumlular) kıldığını ve yeryüzüne (bu topraklara) yerleştirdiğini hatırlayın! Ovalarında köşkler ediniyor ve dağlarından evler yontuyorsunuz. Allah’ın nimetlerini hatırlayın ve yeryüzünde bozguncular olarak karışıklık çıkarmayın!”"},{"n":75,"t":"Kavminden kibirli yöneticiler zayıf düşürülmüşlere yani içlerinden iman edenlere “Siz Salih’in Rabbinden gönderilen bir (elçi) olduğunu (gerçekten) biliyor (buna inanıyor) musunuz?” diye sormuşlardı. Onlar da “Şüphesiz ki biz onunla gönderilen her şeye inanıyoruz.” demişlerdi."},{"n":76,"t":"Kibirlenenler “Biz sizin inandığınız şeyleri inkâr ediyoruz!” demişlerdi."},{"n":77,"t":"Rablerinin emrinden çıkarak o dişi deveyi boğazlamış ve “Ey Salih! Elçilerdensen bize vadettiğini bize getir!” demişlerdi."},{"n":78,"t":"(Bunun üzerine) onları bir sarsıntı yakalamıştı da yurtlarında diz üstü (hareketsiz) kalmışlardı."},{"n":79,"t":"(Salih) onlardan yüz çevirip kendilerine şöyle demişti: “Ey kavmim! Şüphesiz ki ben size Rabbimin mesajını ulaştırdım ve size öğüt verdim fakat siz öğüt verenleri sevmiyorsunuz.”"},{"n":80,"t":"Lut’u da (peygamber göndermiştik de) kavmine şöyle demişti: “Sizden önce âlemlerden (insanlardan) kimsenin yapmadığı bir çirkinliği mi yapıyorsunuz?"},{"n":81,"t":"Şüphesiz ki siz, kadınları bırakıp da şehvetle erkeklere yanaşıyorsunuz. Doğrusu siz haddi aşan bir topluluksunuz.”"},{"n":82,"t":"Kavminin cevabı “Onları (Lut’u ve arkadaşlarını) şehrinizden çıkarın; çünkü onlar (güya) temizlik taslayan insanlarmış!” sözünden başka bir şey olmamıştı."},{"n":83,"t":"Bunun üzerine onu ve ailesini kurtarmıştık. Yalnız hanımı hariç; o, geride kalanlardandı."},{"n":84,"t":"Üzerlerine büyük bir bela yağmuru yağdırmıştık. Bak ki suçluların sonu nasıl olmuştu!"},{"n":85,"t":"Medyen’e de kardeşleri Şuayb’ı (göndermiştik de onlara) şöyle demişti: “Ey kavmim, Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. Elbette size Rabbinizden apaçık bir delil gelmiştir. Ölçüyü ve tartıyı tam yapın, insanların eşyalarını eksik vermeyin! Düzenine kavuşturulduktan sonra yeryüzünde bozgunculuk yapmayın! İnanırsanız böylesi sizin için hayırlı olandır."},{"n":86,"t":"İnananları tehdit ederek, onları Allah yolundan alıkoyarak ve o yolu eğip bükerek her yolun başında oturmayın! Az iken (Allah’ın) sizi çoğalttığını hatırlayın! Bozguncuların sonu nasıl olmuş bir bakın!"},{"n":87,"t":"İçinizden bir grup benimle gönderilene inanır, bir grup da inanmazsa, Allah aranızda hükmedinceye kadar sabredip bekleyin! O hüküm verenlerin en hayırlısıdır.”"},{"n":88,"t":"(Şuayb’ın) kavminden kibirli yöneticiler demişti ki: “Ey Şuayb! Ya mutlaka seni ve seninle birlikte inananları şehrimizden çıkaracağız ya da dinimize döneceksiniz!” (Şuayb şu) cevabı vermişti: “İstememiş olsak da mı?"},{"n":89,"t":"Allah bizi o (yanlış inanış)tan kurtardıktan sonra sizin dininize dönersek Allah’a iftira etmiş oluruz. Rabbimiz Allah’ın dilemesi hariç, ona (Medyenlilerin dinine) dönmemiz mümkün değildir. Rabbimiz ilim bakımından her şeyi kapsamıştır. Biz yalnızca Allah’a güvendik! Rabbimiz! Bizimle kavmimiz arasında adaletle hükmü sen ver! Sen hüküm verenlerin en hayırlısısın.”"},{"n":90,"t":"Kavminin kâfir olan yöneticileri “Şuayb’a uyarsanız bu durumda siz kaybedersiniz!” demişlerdi."},{"n":91,"t":"(Bunun üzerine) onları bir sarsıntı yakalamıştı da yurtlarında diz üstü (hareketsiz) kalmışlardı."},{"n":92,"t":"Şuayb’ı yalanlayanlar sanki yurtlarında hiç kalmamış gibiydiler; Şuayb’ı yalanlayanlar kaybedenlerin ta kendileridir."},{"n":93,"t":"(Şuayb) onlardan yüz çevirmiş ve şöyle demişti: “Ey kavmim! Ben size Rabbimin mesajlarını duyurmuş ve size öğüt de vermiştim. Artık kâfir bir kavme nasıl acırım!”"},{"n":94,"t":"Her şehre bir peygamber gönderdiğimizde (gerçeğe) boyun eğsinler diye onları elbette çeşitli sıkıntı ve darlıkla denemiştik."},{"n":95,"t":"Sonra kötülüğü iyilikle değiştirmiştik de refah içinde yaşamışlardı. “Atalarımıza da elbette böyle sıkıntı ve sevinç (vesileleri) gelmişti.” demişlerdi. Biz de onları, hiç farkına varmadıkları bir şekilde ansızın yakalamıştık (cezalandırmıştık)."},{"n":96,"t":"O şehirlerin halkı iman edip takvâlı (duyarlı) olsalardı, elbette üzerlerine gökten ve yerden bereketler açardık. Fakat yalanlamışlardı; biz de kazandıkları şeyler nedeniyle onları yakalamıştık (cezalandırmıştık)."},{"n":97,"t":"O şehirlerin halkı, uyurlarken geceleyin kendilerine azabımızın gelmesinden güvende miydi!"},{"n":98,"t":"Veya o şehirlerin halkı, eğlenirlerken kuşluk vakti kendilerine azabımızın gelmesinden güvende miydi!"},{"n":99,"t":"Allah’ın tuzağından (ince düzeninden) güvende miydiler! Kendilerine yazık eden topluluktan başkası Allah’ın tuzağından (ince düzeninden) kendini güvende göremez."},{"n":100,"t":"Önceki sakinlerinden sonra yeryüzüne mirasçı olanlara şu gerçek yol göstermedi mi: Dileseydik günahlarından dolayı onlara da (sıkıntılar) isabet ettirirdik. Kalplerini mühürleriz de (gerçekleri) duyamazlar."},{"n":101,"t":"İşte o şehirler, haberlerinden sadece bir bölümünü sana anlatmakta olduklarımızdır. Yemin olsun ki elçileri onlara apaçık deliller getirmişlerdi. Fakat önceden yalanladıklarına yine de iman edecek değillerdi. İşte Allah kâfirlerin kalplerini böyle mühürler."},{"n":102,"t":"Onların çoğunda sözünde durma bulamamıştık; çoğunu yoldan çıkmış bulmuştuk."},{"n":103,"t":"Sonra onların ardından da Musa’yı delillerimizle Firavun ve yöneticilerine göndermiştik de onlara (delillerimize) haksızlık etmişlerdi. Bozguncuların sonu nasıl olmuş, bir bak!"},{"n":104,"t":"Musa şöyle demişti: “Ey Firavun! Ben âlemlerin Rabbi tarafından gönderilmiş bir elçiyim."},{"n":105,"t":"Allah hakkında gerçek(ler)den başka bir şey söylememek benim üzerime borçtur. Elbette Rabbinizden size apaçık bir belge getirdim; artık İsrailoğulları'nı benimle gönder!”"},{"n":106,"t":"(Firavun) şöyle demişti: “Bir delil getirdiysen, doğru söyleyenlerdensen onu getir (göster)!”"},{"n":107,"t":"(Musa) asasını atmıştı. Bir de ne görsünler, o (asa) apaçık bir yılan (olmuş)!"},{"n":108,"t":"Elini de (koynundan) çıkarmıştı. Bir de ne görsünler, o (eli) bakanlara bembeyaz (görünmüştü)."},{"n":109,"t":"109-110 Firavun’un kavminden yöneticiler şöyle demişlerdi: “Şüphesiz ki bu, sizi yurdunuzdan çıkarmak isteyen çok bilgili bir büyücüdür.” (Firavun) “Öneriniz nedir?” demişti."},{"n":110,"t":"109-110 Firavun’un kavminden yöneticiler şöyle demişlerdi: “Şüphesiz ki bu, sizi yurdunuzdan çıkarmak isteyen çok bilgili bir büyücüdür.” (Firavun) “Öneriniz nedir?” demişti."},{"n":111,"t":"111-112 (Yöneticiler) “Musa’yı ve kardeşini alıkoy! Bütün bilgin büyücüleri sana getirsinler diye şehirlere toplayıcı (görevli)ler gönderip haber sal!” demişlerdi."},{"n":112,"t":"111-112 (Yöneticiler) “Musa’yı ve kardeşini alıkoy! Bütün bilgin büyücüleri sana getirsinler diye şehirlere toplayıcı (görevli)ler gönderip haber sal!” demişlerdi."},{"n":113,"t":"Büyücüler Firavun’a gelmiş ve “Galip gelirsek bize ödül var, değil mi?” demişti."},{"n":114,"t":"(Firavun) “Tamam; siz gözdeler(im)den olacaksınız!” demişti."},{"n":115,"t":"(Büyücüler) “Ey Musa, ya (asayı önce) sen atacaksın ya da atanlar biz (mi) olalım?” demişlerdi."},{"n":116,"t":"(Musa) “Siz atın!” demişti. Onlar atınca, insanların gözlerini büyülemiş, onları korkutmuş ve (zanlarınca) büyük bir büyü getirmişlerdi (göstermişlerdi)."},{"n":117,"t":"(Bunun üzerine) Musa’ya “Şimdi de sen asanı (yere) at!” diye vahyetmiştik. Bir de ne görsünler, (Musa’nın asası) onların uydurduklarını yutuyordu."},{"n":118,"t":"Böylece gerçek ortaya çıkmış ve onların yapmakta olduğu şeyler de yok olup gitmişti."},{"n":119,"t":"Orada kendilerini küçük düşüren bir yenilgiye uğramışlardı."},{"n":120,"t":"Büyücüler hemen secdeye kapanmışlardı."},{"n":121,"t":"121-122 (Büyücüler) “Âlemlerin Rabbine, yani Musa ve Harun’un Rabbine inanıp güvendik.” demişlerdi."},{"n":122,"t":"121-122 (Büyücüler) “Âlemlerin Rabbine, yani Musa ve Harun’un Rabbine inanıp güvendik.” demişlerdi."},{"n":123,"t":"Firavun onlara şöyle demişti: “Ben size izin vermeden ona iman ettiniz (öyle mi)? Şüphesiz ki bu, halkını oradan çıkarasınız diye şehirde kurduğunuz bir tuzaktır. İleride (gerçeği) bileceksiniz."},{"n":124,"t":"Dönekliğinizden dolayı ellerinizi ve ayaklarınızı keseceğim, sonra da hepinizi asacağım!”"},{"n":125,"t":"(Büyücüler) şöyle demişlerdi: “Biz zaten Rabbimize döneceğiz."},{"n":126,"t":"Sen sırf Rabbimizin ayetleri bize geldiğinde onlara inandığımız için bizden intikam alıyorsun.” (Sonra) “Rabbimiz! Bize bol bol sabır ver ve müslümanlar olarak bizi vefat ettir.” diye dua etmişlerdi."},{"n":127,"t":"Firavun’un kavminden yöneticiler: “(Büyücüleri kesip) Musa’yı ve kavmini hem seni hem de ilahlarını terk edip yeryüzünde bozgunculuk çıkarsınlar diye serbest mi bırakacaksın?” demişlerdi. (Firavun) “(Hayır hayır), oğullarını öldürtüp kadınlarını sağ bırakacağız. Elbette biz onlara üstünüz (onları ezecek güçteyiz)!” demişti."},{"n":128,"t":"(O sırada) Musa kavmine şöyle demişti: “Allah’tan yardım isteyin ve sabırlı olun! Şüphesiz ki yer, Allah’a aittir. Kullarından dilediğine (layık olana) onu mirasçı yapar. (Mutlu) son, muttakîler (duyarlı olanlar) içindir.”"},{"n":129,"t":"Onlar “Sen bize (peygamber olarak) gelmeden önce de eziyete uğratılmıştık; geldikten sonra da!” demişlerdi. (Musa ise): “Elbette Rabbiniz, düşmanınızı helak edecek ve onların yerine sizi yeryüzüne hâkim kılacak ve nasıl hareket edeceğinize bakacaktır.” demişti."},{"n":130,"t":"Yemin olsun ki biz de Firavun’un ailesini (destekçilerini gerçeği) hatırlasınlar diye kuraklık ve ürün kıtlığı ile cezalandırmıştık."},{"n":131,"t":"Onlara bir iyilik geldiğinde “Bu, sadece bizim hakkımızdır.” demişlerdi. Kendilerine bir kötülük geldiğinde onu da Musa ve beraberindekiler nedeniyle (gelen) uğursuzluğa bağlarlar(dı). Dikkat edin! Onların uğursuzluğu Allah katında(n)dır fakat çoğu bilmez."},{"n":132,"t":"(Mısırlılar) şöyle demişlerdi: “Bizi büyülemen için her ne ayet (mucize) getirirsen (getir), biz sana asla inanacak değiliz.”"},{"n":133,"t":"Bunun üzerine biz de ayrı ayrı ayetler (mucizeler) olarak üzerlerine tufan, çekirgeler, haşereler, kurbağalar ve kan göndermiştik. Yine de kibirlenmeye devam etmişlerdi; zaten onlar suçlu bir toplumdu."},{"n":134,"t":"Tepelerine her bela indiğinde, “Ey Musa! Sana verdiği söz gereği bizim için Rabbine dua et! Bizden o azabı kaldırırsan, elbette sana inanacak ve elbette İsrailoğulları'nı seninle göndereceğiz.” demişlerdi."},{"n":135,"t":"Biz ulaşacakları bir süreye kadar onlardan o azabı kaldırınca hemen sözlerinden dönmüşlerdi."},{"n":136,"t":"(Buna karşılık) biz de onlardan intikam almış, ayetlerimizi yalanlamaları ve onlardan habersizmiş gibi davranmaları sebebiyle kendilerini denizde boğmuştuk."},{"n":137,"t":"Zayıf düşürülmüş olan o toplumu (İsrailoğullarını), bereketli kıldığımız yerin doğu ve batı taraflarına mirasçı kılmıştık. Sabırlarına karşılık Rabbinin İsrailoğullarına verdiği güzel söz yerine gelmişti. Firavun ve kavminin yaptıkları (eserlerini) ve yükselttiklerini (çardaklarını, binalarını) yerle bir etmiştik."},{"n":138,"t":"İsrailoğulları'nı denizden geçirmiştik. Orada kendilerine ait birtakım putlara tapan bir kavmin yanına gelmişlerdi. Bunun üzerine (Musa’ya) “Ey Musa! Onların ilahları olduğu gibi, sen de bizim için bir ilah yap!” demişlerdi. (Musa) şöyle demişti: “Şüphesiz ki siz cahillik eden bir toplumsunuz.”"},{"n":139,"t":"Şüphesiz ki bunların içinde bulundukları (yol) helak sebebidir; yapmakta oldukları işler de batıldır."},{"n":140,"t":"“Sizi âlemlere (inançsızlara) üstün kılmışken, size Allah’tan başka bir ilah mı arayayım?” demişti."},{"n":141,"t":"Hatırlayın ki (erkek) çocuklarınızı öldürtüp kadınlarınızı sağ bırakacak şekilde size işkencenin en kötüsünü yapan Firavun’un ailesinden (destekçilerinden) sizi kurtarmıştık. İşte bunda (size anlatılanlarda), Rabbinizden büyük bir imtihan vardır."},{"n":142,"t":"(Vahyetmek üzere) Musa’ya otuz gece belirlemiş ve ona on gece daha ilave etmiştik; böylece Rabbinin belirlediği zaman kırk geceyi bulmuştu. Musa, kardeşi Harun’a şöyle demişti: “Kavmimin arasında benim yerime geç; onları ıslah etmeye devam et; bozguncuların yoluna uyma!”"},{"n":143,"t":"Musa, belirlediğimiz zamanda (Sînâ Dağı’na) gelip Rabbi ona konuşunca “Rabbim! Bana (kendini) göster de seni göreyim!” demişti. (Allah) “Sen beni asla göremeyeceksin. Fakat şu dağa bak; yerinde durabilirse sen de beni görebileceksin!” demişti. Rabbi dağa tecelli edince onu paramparça etmiş, Musa da baygın düşmüştü. Ayılınca şöyle demişti: “Sen yücesin; sana yöneldim ve ben inananların öncüsüyüm.”"},{"n":144,"t":"(Allah) “Ey Musa! Ben mesajlarımla ve hitabım sayesinde seni insanlar üzerine seçkin kıldım. Sana verdiklerimi al (onlara sımsıkı sarıl) ve şükredenlerden ol!” demişti."},{"n":145,"t":"Her şeyle ilgili öğüt ve her şeyin açıklamasını levhalarda onun için (Musa için) yazmış ve “Onlara kuvvetle sarıl; kavmine de en güzel olanlarını almalarını emret! Yakında size, yoldan çıkmışların yurdunu göstereceğim.” (demiştik)."},{"n":146,"t":"Yeryüzünde kibirlenenleri delillerimden uzaklaştıracağım. (Çünkü) onlar, her bir delili görseler de onlara iman etmezler. Doğru yolu görseler onu yol edinmezler. (Fakat) azgınlık yolunu görürlerse yol olarak onu benimserler. Bu durum, onların ayetlerimizi yalanlamaları ve onlardan habersizmiş gibi davranmalarından kaynaklanmaktadır."},{"n":147,"t":"(Oysa) ayetlerimizi ve ahiretle karşılaşmayı yalanlayanların yaptıkları boşa gitmiştir. Onlara, yaptıklarından başka karşılık verilir mi!"},{"n":148,"t":"Musa’nın kavmi, ondan (Sînâ’ya gidişinden) sonra ziynet (eşya)larından boğuk bir sese sahip bir ceset şeklindeki buzağı heykelini (ilah) edinmişti. O (buzağının) kendilerine konuşamadığı ve onlara yol gösteremediğini görmediler mi? Onu (ilah olarak) benimsemişler ve zalimlerden olmuşlardı."},{"n":149,"t":"(Başları) ellerine düşünce (pişman olup) saptıklarını görüp anladıklarında “Rabbimiz bize merhamet etmez ve bizi bağışlamazsa elbette kaybedenlerden olacağız!” demişlerdi."},{"n":150,"t":"Musa, öfkeli ve üzgün bir hâlde kavmine dönünce, “Benden sonra arkamdan ne kötü işler yapmışsınız! Rabbinizin emrini (beklemeden) acele ettiniz, öyle mi?” deyip (Tevrat) levhaları(nı yere) bırakmış ve kardeşinin başını tutup kendine doğru çekmeye başlamıştı. Harun “Ey annemin oğlu! Bu toplum beni cidden zayıf gördü (bana baskı yaptılar), neredeyse beni öldüreceklerdi. Sen de (onları sevindirircesine) düşmanları bana güldürme ve beni bu zalim toplumla bir tutma!” demişti."},{"n":151,"t":"(Bunun üzerine Musa), “Rabbim! Beni ve kardeşimi bağışla; bizi merhametine koy! Sen merhametlilerin en merhametlisisin.” diye dua etmişti."},{"n":152,"t":"Buzağıyı (ilah) edinenlere, Rablerinden (mutlaka) bir gazap ve dünya hayatında bir aşağılanma gelecektir. Biz, iftiracıların karşılığını işte böyle veririz."},{"n":153,"t":"Kötülükler yapıp sonrasında (Allah’a) yönelerek iman edenler(e gelince), bu (tevbelerin)den sonra şüphesiz ki Rabbin çok bağışlayandır, çok merhametlidir."},{"n":154,"t":"Musa’nın öfkesi dinince, içinde Rablerinden korkanlar için yol gösterme ve rahmet bulunan o levhaları (tekrar eline) almıştı."},{"n":155,"t":"Musa, belirlediğimiz zaman için kavminden yetmiş adam seçmişti. Kendilerini o müthiş deprem yakalamış ve (Musa) şöyle demişti: “Rabbim! Dileseydin onları da beni de daha önce helak edebilirdin. İçimizden bazı beyinsizlerin işlediği şeyler yüzünden hepimizi mi helak edeceksin? Bu iş, senin imtihanından başka bir şey değildir. Onunla dilediğini (layık olanı) sapkınlıkta bırakır; dilediğini (layık olanı) doğru yola ulaştırırsın. Sen bizim dostumuzsun (sahibimizsin); bizi bağışla ve bize merhamet et! Sen bağışlayanların en hayırlısısın."},{"n":156,"t":"Bizim için bu dünyada da iyilik yaz, ahirette de! Şüphesiz ki biz sana yöneldik.” (Allah da) şöyle demişti: “Dilediğime (layık olana) azap ederim. Merhametim ise her şeyi kapsamıştır ve onu takvâlı (duyarlı) olanlara, zekâtı verenlere ve ayetlerimize inananlara yazacağım."},{"n":157,"t":"(Yani) yanlarındaki Tevrat ve İncil’de yazılı buldukları Elçi'ye, o ümmi Peygamber’e uyanlara (yazacağım) ki (o Peygamber), onlara iyiliği emreder (öğütler), onları kötülükten engeller (sakındırır); onlara temiz şeyleri helal, pis şeyleri de haram kılar; kendilerinden ağır yüklerini ve üzerlerindeki zincirleri kaldırır (atar). Ona (o Peygamber’e) inanıp saygı gösteren, ona yardım eden ve onunla birlikte gönderilen nur’a (Kur’an’a) uyanlar, kurtulanların ta kendileridir.”"},{"n":158,"t":"De ki: “Ey insanlar! Ben göklerin ve yerin otoritesinin sahibi, kendisinden başka ilah bulunmayan, diriltebilen ve öldürebilen Allah’ın, sizin hepinize gönderdiği elçisiyim. Öyle ise Allah’a; kendisi de Allah’a ve sözlerine (mesajlarına) inanan ümmi Peygamber olan Elçisine inanın ve ona uyun ki doğru yolu bulasınız.”"},{"n":159,"t":"Musa’nın kavminden de gerçeğe rehberlik eden ve onunla adil davranan bir topluluk vardır."},{"n":160,"t":"Biz İsrailoğullarını topluluk olarak on iki boya (oymağa) ayırmıştık. Kavmi kendisinden su isteyince, Musa’ya “Asanla taşa vur!” diye vahyetmiştik. Derhal ondan on iki pınar fışkırmıştı. Her kabile de içeceği yeri elbette bilmişti. Kendilerini bulutla gölgelendirip onlara kudret helvası ile bıldırcın eti indirmiş (vermiş), “Size rızık olarak verdiğimiz temiz şeylerden yiyin!” (demiştik). (Emirlerimizi dinlememekle) onlar bize zulmetmemişlerdi; ancak kendilerine yazık etmişlerdi."},{"n":161,"t":"Hani onlara şöyle denmişti: “Şu şehirde yerleşin; onun (nimetlerinden) dilediğiniz gibi yararlanın; ‘Hıttah!’ (bizi bağışla) deyin ve kapıdan eğilerek girin ki hatalarınızı bağışlayalım.” Güzel davrananların (ödülünü) ileride daha da artıracağız."},{"n":162,"t":"Fakat içlerinden bazı zalimler, kendilerinden (söylemeleri) istenen sözü başkasıyla değiştirmişlerdi. Biz de haksızlık etmeleri nedeniyle üzerlerine gökten bir azap göndermiştik."},{"n":163,"t":"Onlara, deniz kıyısında bulunan şehir (halkının) durumunu sor! Hani balıklar o yöre halkının yasağa uymadığı cumartesi gelmeyip yasağa uydukları cumartesi günü akın akın (bolca) kıyıya geldiklerinde, haddi aşıp (avlanma) yasağını delmişlerdi. İşte biz yoldan çıkmalarından dolayı onları böyle imtihan ediyorduk."},{"n":164,"t":"Hani içlerinden bir topluluk da “Allah’ın kendilerini (dünyada) helak edeceği veya (ahirette) şiddetli bir şekilde azap edeceği bir halka ne diye öğüt veriyorsunuz?” dediklerinde, (öğüt verenler) şöyle demişlerdi: “Rabbinize mazeret(imiz) olsun; bir de umulur ki takvâlı (duyarlı) olurlar diye (öğüt veriyoruz).”"},{"n":165,"t":"Kendilerine yapılan uyarıları unutunca, kötülükten engelleyenleri kurtarmış, haksızlık edenleri de yapmakta oldukları kötülükler nedeniyle çok kötü bir azaba çarptırmıştık."},{"n":166,"t":"Yasaklanan şeyler nedeniyle haddi aşınca onlara “Aşağılık maymunlar (gibi) olun!” demiştik."},{"n":167,"t":"Rabbin, kıyamet gününe kadar onlara (o tip insanlara) en kötü eziyeti yapacak kişiler göndereceğini ilan etmişti. Şüphesiz ki Rabbin, cezası hızlı olandır. Şüphesiz ki O çok bağışlayandır, çok merhametlidir."},{"n":168,"t":"Onları (yahudileri), çeşitli ümmetler hâlinde yeryüzüne dağıtmıştık. İyi olanları da bunun dışındakileri de (iyi olmayanları da) vardı. Gerçeğe dönerler diye onları iyiliklerle ve kötülüklerle denemiştik."},{"n":169,"t":"Onlardan sonra da şu değersiz (dünya) malını alıp, “(Nasıl olsa) bağışlanacağız!” diyerek Kitab'a (Tevrat’a) mirasçı olan birtakım kötü kişiler gelmişti. Onlara, benzer bir menfaat daha gelse onu da alırlardı. (Peki), Allah hakkında gerçek(ler)den başka bir şey söylemeyeceklerine dair kendilerinden Kitap'ta (Tevrat’ta) söz alınmamış mıydı ve onlar (bunu Kitap'ta) okumamışlar mıydı? Ahiret yurdu takvâlı (duyarlı) olanlar için hayırlı olandır. Akıl etmiyor musunuz?"},{"n":170,"t":"Kitaba sımsıkı sarılıp namazı kılanlar(a gelince), şüphesiz ki biz kendilerini düzeltenlerin ödülünü ziyan etmeyeceğiz."},{"n":171,"t":"Hani üstlerine düşeceğini sandıkları (Sînâ) Dağı’nı onların üzerine gölge gibi kaldırmıştık. (Onlara) “Size verdiğimizi (Kitabı) kuvvetle alın (sıkıca tutunun) ve içinde olanı hatırlayın ki takvâlı olabilesiniz.” (demiştik)."},{"n":172,"t":"Hani Rabbin âdemoğullarından, onların sırtlarından nesillerini çıkarıp (yaratıp) onları kendilerine şahit tutmuş ve “Ben sizin Rabbiniz değil miyim?” (demiş), onlar da “Evet, buna şâhidiz” demişlerdi. Kıyamet gününde “Biz bundan habersizdik.” dersiniz diye,"},{"n":173,"t":"Veya “Daha önce atalarımız Allah’a ortak koşmuştu; biz de onlardan sonra gelen nesiller olduğumuz için; (yani) yanlış yapanlar nedeniyle bizi de mi helak edeceksin?” dersiniz diye (işte böyle yapmıştık)."},{"n":174,"t":"Ayetleri ayrıntılı bir şekilde işte böyle açıklıyoruz; umulur ki (gerçeğe) dönerler."},{"n":175,"t":"Onlara, kendisine delillerimizi verdiğimiz fakat onlardan sıyrılıp ayrılan, o yüzden şeytanın takip ettiği ve sonunda azgınlardan olan şu kimsenin haberini tilavet et (okuyup aktar)!"},{"n":176,"t":"Dileseydik elbette onu bu deliller sayesinde yükseltirdik. Fakat o, arzusuna mahkûm olup dünyaya saplandı. Böylesi bir kişinin durumu, kovsan da kendi hâline bıraksan da dilini çıkartıp soluyan köpeğin durumuna benzer. İşte ayetlerimizi yalanlayan kavmin örneği de böyledir. Bu kıssayı anlat; umulur ki düşünürler."},{"n":177,"t":"Ayetlerimizi yalanlayan ve böylece kendilerine haksızlık etmiş olanların hâli ne kadar da kötüdür!"},{"n":178,"t":"Allah’ın hidayet ettiği kişi doğru yola ulaş(tırıl)mıştır. Kimi saptırırsa işte onlar kaybedenlerin ta kendileridir."},{"n":179,"t":"Yemin olsun ki (akıl eden) kalpleri olmasına rağmen anlamayan, gözleri olmasına rağmen görmeyen, kulakları olmasına rağmen duymayan, sadece hayvanlar gibi, hatta daha da şaşkın bir hâlde bulunan ve sonunda habersizmiş gibi davranan pek çok cin ve insanı cehennem için hazırlamışızdır."},{"n":180,"t":"En güzel isimler yalnızca Allah’a aittir. O’na o (isim)lerle dua edin! O’nun isimleri hakkında eğri yola gidenleri bırakın! Yaptıklarının karşılığı ileride kendilerine verilecektir."},{"n":181,"t":"Yarattıklarımızdan gerçeğe rehberlik eden ve onunla adil davranan bir topluluk vardır."},{"n":182,"t":"Ayetlerimizi yalanlayanları, bilemeyecekleri şekilde yavaş yavaş helake yaklaştıracağız."},{"n":183,"t":"Onlara zaman tanıyorum. Şüphesiz ki benim tuzağım (ince planım) çok sağlamdır."},{"n":184,"t":"Arkadaşlarında hiçbir cinlenmişlik olmadığını hiç mi düşünmediler? O ancak apaçık bir uyarıcıdır."},{"n":185,"t":"Göklerin ve yerin egemenliği, Allah’ın yarattığı her bir şey ve ecellerinin yaklaşmış olabileceği hakkında hiç mi düşünmediler? Ondan (Kur’an’dan) sonra hangi söze inanıyorlar!"},{"n":186,"t":"Allah’ın saptırdığına (sapkınlığını onayladığına) kimse yol gösteremez. (Allah) onları azgınlıkları içerisinde bocalar hâlde bırakır."},{"n":187,"t":"Sana, o (Son) Saat’in demir atma zamanından soruyorlar. De ki: “Onun bilgisi, sadece Rabbimin katındadır. Onun zamanını O’ndan başkası ortaya koyamaz. (O olay) bütün ağırlığını göklerde ve yerde hissettirecektir. (Son Saat) size ancak ve ancak ansızın gelecektir.” Sanki sen onu bilebilirmişsin gibi sana soruyorlar. De ki: “Onun bilgisi yalnızca Allah katındadır fakat insanların çoğu bilmez.”"},{"n":188,"t":"De ki: “Allah’ın dilemesi hariç, kendime herhangi bir yarar da zarar da verecek güce sahip değilim. Gaybı (bilinemeyeni) bilseydim elbette daha çok hayır yapardım ve bana hiçbir kötülük de dokunmazdı. İnanan bir toplum için yalnızca bir uyarıcı ve müjdeleyiciyim.”"},{"n":189,"t":"Sizi tek bir nefisten (candan/cevherden) yaratan, (yine) ondan kendisiyle huzur bulsun diye eşini yaratan O’dur. Eşini kucaklayınca (eşi ile birleşince) eşi hafif bir yük yüklenir (hamile kalır) ve onu bir süre taşır. (Yük) ağırlaşınca “Bize iyi (sağlıklı) bir çocuk verirsen elbette şükredenlerden olacağız.” diye Rableri Allah’a dua ederler."},{"n":190,"t":"(Allah) onlara iyi (sağlıklı) bir çocuk verince, kendilerine verdiği (çocuk) hakkında O’na ortaklar koşarlar. Allah ise onların ortak koştuklarından yücedir."},{"n":191,"t":"Kendileri yaratılmakta olan ve hiçbir şey yaratamayan varlıkları mı (Allah’a) ortak koşuyorlar!"},{"n":192,"t":"(Oysa putlar), onlara yardıma güç yetiremez, (kendilerine bile) yardım edemezler."},{"n":193,"t":"Onları doğru yola çağırırsanız size uyamazlar; onları davet etseniz de sussanız da sizin için birdir."},{"n":194,"t":"Allah’ın peşi sıra yalvardıklarınız da sizin gibi kullardır. Doğruysanız, kendilerini çağırın da çağrınıza cevap versinler!"},{"n":195,"t":"(Putların) yürüyebilecekleri ayakları, tutacakları elleri, görecekleri gözleri veya duyacakları kulakları mı var (neleri var)! De ki: “Ortaklarınızı çağırın, sonra bana (istediğiniz) tuzağı kurun; bana göz bile açtırmayın!”"},{"n":196,"t":"(De ki:) “Şüphesiz ki benim dostum, iyileri sahiplenen (koruyan) ve Kitabı (Kur’an’ı) indiren Allah’tır."},{"n":197,"t":"O’nun (Allah’ın) peşi sıra yalvardıklarınızın size yardıma güçleri yetmez; onlar kendilerine de yardım edemezler.”"},{"n":198,"t":"Onları doğru yola çağırırsanız size kulak veremezler. Onları sana bakar görürsün; oysa onlar görmezler."},{"n":199,"t":"Sen af yolunu tut; iyiliği emret ve cahillerden yüz çevir!"},{"n":200,"t":"Sana şeytandan bir kışkırtma gelirse hemen Allah’a sığın! Şüphesiz ki yalnızca O duyandır, bilendir."},{"n":201,"t":"Takvâlı (duyarlı) olanlara şeytandan bir vesvese ulaştığında hemen (Allah’ı) hatırlayıp (gerçeği) görürler."},{"n":202,"t":"(Şeytanların) kardeşleri ise onları azgınlığa sürükler; peşlerini bırakmazlar."},{"n":203,"t":"Onlara herhangi bir delil getirmediğin zaman, “Onu da derleyip getirseydin ya!” derler. De ki: “Ben sadece Rabbimden bana vahyedilene uyuyorum. Bu (Kur’an), Rabbinizden gelen öngörülerdir; (ayrıca) inanan bir toplum için yol gösterme ve merhamettir.”"},{"n":204,"t":"Kur’an okunduğu zaman onu dinleyin ve susun ki size de merhamet edilsin!"},{"n":205,"t":"İçinden yalvararak ve ürpererek, yüksek olmayan bir sesle sabah akşam (gündüz gece) Rabbini an ve habersizmiş gibi davrananlardan olma!"},{"n":206,"t":"Şüphesiz ki Rabbinin katındakiler (melekler), O’na (Allah’a) kulluk etmekten kibirlenmez, O’nu tesbih eder (yüceltir) ve yalnızca O’na secde ederler."}],[{"n":1,"t":"Sana ganimetlerden soruyorlar. De ki: “Ganimetler Allah ve Elçisi içindir. Allah’a karşı takvâlı (duyarlı) olun; aranızı düzeltin! Müminlerseniz Allah’a ve Elçisine itaat edin!”"},{"n":2,"t":"Müminler Allah anıldığı zaman yürekleri titreyen, kendilerine O’nun ayetleri tilavet edildiği (okunup aktarıldığı) zaman imanları artan ve sadece Rablerine güvenen kişilerdir."},{"n":3,"t":"Onlar, namazlarını doğru kılan ve kendilerine rızık olarak verdiğimiz (şeyler)den (Allah yolunda) infak edenlerdir (verenlerdir)."},{"n":4,"t":"İşte onlar, gerçek müminlerdir. Onlar için Rableri katında dereceler, bağışlanma ve değerli bir rızık vardır."},{"n":5,"t":"Nitekim müminlerden bir grup istemediği hâlde, Rabbin seni bir amaç uğrunda evinden çıkarmıştı."},{"n":6,"t":"Gerçek ortaya çıktıktan sonra, sanki göz göre göre ölüme sürükleniyorlarmış gibi o amaçla ilgili olarak (savaş hakkında) seninle tartışıyorlardı."},{"n":7,"t":"Hani Allah size, iki gruptan (kervan veya Kureyş ordusundan) birinin sizin olduğunu vadediyordu; siz de güçsüz olanın (kervanın) sizin olmasını istiyordunuz. (Oysa) Allah, sözleriyle hakkı gerçekleştirmek ve (Kureyş ordusunu yok ederek) kâfirlerin ardını kesmek istiyordu."},{"n":8,"t":"(Bütün bunlar), suçlular istemese de hakkı gerçekleştirmek ve batılı ortadan kaldırmak içindi."},{"n":9,"t":"Hani siz Rabbinizden yardım istiyordunuz. O da “Şüphesiz ki ben peş peşe gelen bin melek ile size yardım edeceğim.” (diyerek) size cevap vermişti."},{"n":10,"t":"Allah bunu sadece müjde olsun ve onunla kalbiniz yatışsın diye yapmıştı. Zaten yardım, yalnızca Allah katındandır. Şüphesiz ki Allah güçlüdür, doğru hüküm verendir."},{"n":11,"t":"O zaman, katından bir güven olmak üzere sizi hafif bir uykuya daldırıyordu. Sizi onunla temizlemek için, şeytanın pisliğini (vesvesesini) sizden gidermek, kalplerinizi (birbirine) bağlamak ve onunla ayakları(nızı savaşta) sabit kılmak için üzerinize gökten su indiriyordu."},{"n":12,"t":"Hani Rabbin meleklere “Şüphesiz ki ben sizinle beraberim; iman edenlere destek olun! Ben kâfir olanların yüreğine korku salacağım. Vurun boyunlarının üzerine! Onların bütün parmak uçlarını vurun!” diye vahyediyordu (bildiriyordu)."},{"n":13,"t":"Bu (uygulama), onların Allah’a ve Elçisine karşı gelmelerinden ötürüdür. Kim Allah’a ve Elçisine karşı gelirse, şüphesiz ki Allah azabı şiddetli olandır."},{"n":14,"t":"İşte (ey kâfirler, cezanız) bu; şimdi onu tadın! Şüphesiz ki kâfirler için ateş azabı vardır."},{"n":15,"t":"Ey iman edenler! Toplu hâlde kâfirlerle karşılaştığınız zaman onlara arkanızı dönmeyin (kaçmayın)!"},{"n":16,"t":"Tekrar savaşmak için bir tarafa çekilme veya diğer bölüğe ulaşıp mevzi tutma durumu dışında, kim öyle bir günde onlara arka çevirirse (kaçarsa), elbette o, Allah’ın gazabını hak etmiş olarak döner. Onun barınağı cehennemdir. Ne kötü varış yeridir (orası)!"},{"n":17,"t":"(Savaşta) onları siz öldürmemiştiniz fakat onları Allah öldürmüştü; attığın zaman da sen atmamıştın fakat Allah atmıştı. Bunu, müminleri güzel bir imtihanla denemek için (yapmıştı). Şüphesiz ki Allah duyandır, bilendir."},{"n":18,"t":"İşte böyle olmuştu. Şüphesiz ki Allah kâfirlerin tuzağını bozucudur."},{"n":19,"t":"(Ey kâfirler)! Siz zafer istiyorsanız, elbette size zafer geldi! (İnkârdan) vazgeçerseniz bu sizin için daha iyidir. (Peygamber’e düşmanlığa) dönerseniz, biz de (ona yardıma) döneriz. Topluluğunuz çok bile olsa, sizden hiçbir şeyi savamaz. Şüphesiz ki Allah müminlerle beraberdir."},{"n":20,"t":"Ey iman edenler! Allah’a ve Elçisine itaat edin, duyduğunuz hâlde O’ndan yüz çevirmeyin!"},{"n":21,"t":"Duymadıkları hâlde “Duyduk!” diyenler gibi olmayın!"},{"n":22,"t":"Şüphesiz ki Allah katında canlıların en kötüsü, akıl etmeyen dilsizlerdir, sağırlardır."},{"n":23,"t":"Allah onlarda bir hayır bilseydi elbette onlara duyururdu. Fakat duyursaydı bile yine onlar yüz çevirerek dönerlerdi."},{"n":24,"t":"Ey iman edenler! Size hayat verecek şeylere sizi çağırdığı zaman, Allah’a ve Elçisine (çağrısına) cevap verin! Bilin ki Allah, kişi ile kalbi arasına girer ve siz şüphesiz ki O’nun huzurunda toplanacaksınız."},{"n":25,"t":"Öyle bir fitneye (sıkıntı ve zor imtihana) karşı takvâlı (duyarlı) olun ki o, içinizden sadece haksızlık edenlere ulaşmakla (kalmaz). Bilin ki şüphesiz Allah’ın azabı şiddetlidir."},{"n":26,"t":"Hatırlayın ki hani siz yeryüzünde zayıf düşürülmüş az (bir toplum)dunuz; insanların sizi kapıp götürmesinden korkuyordunuz da şükredesiniz diye (Allah) sizi barındırmıştı; yardımıyla sizi desteklemişti ve sizi temiz şeylerden rızıklandırmıştı."},{"n":27,"t":"Ey iman edenler! Allah’a ve Elçi'ye ihanet etmeyin; (sonra) bilerek kendi emanetlerinize ihanet etmiş olursunuz."},{"n":28,"t":"Bilin ki mallarınız ve çocuklarınız, sadece bir imtihandır ve şüphesiz ki büyük ödül yalnızca Allah’ın katındadır."},{"n":29,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olursanız size furkân verir; sizden günahlarınızı örter ve sizi bağışlar. Allah büyük lütuf sahibidir."},{"n":30,"t":"Hani kâfir olanlar seni tutup bağlamaları veya öldürmeleri veya seni (yurdundan) çıkarmaları için sana tuzak kuruyorlardı. Onlar (sana) tuzak kuruyorlar. Allah da (buna karşı) tuzak kuruyor. Allah tuzak kuranların en hayırlısıdır."},{"n":31,"t":"Onlara ayetlerimiz tilavet edildiği (okunup aktarıldığı) zaman şöyle demişlerdi: “Elbette duyduk; isteseydik biz de bunun benzerini elbette söyleyebilirdik. Bu, öncekilerin masallarından başka bir şey değildir.”"},{"n":32,"t":"Hani (o kâfirler) bir zaman da şöyle demişlerdi: “Ey Allah’ım! Bu (Kur’an) senin katından ise üzerimize gökten taş yağdır veya bize elem verici bir azap getir!”"},{"n":33,"t":"Sen onların içindeyken Allah onlara azap edecek değildir. Onlar bağışlanma dileğinde bulunuyorken de Allah onlara azap edici değildir."},{"n":34,"t":"Onlar gerçek dostları olmadıkları hâlde (Müslümanları) Mescid-i Haram’dan engellerken Allah onlara ne diye azap etmeyecekmiş ki! Onun (Kâbe’nin) gerçek dostları, muttakîlerden başkası değildir. Fakat onların çoğu bilmez."},{"n":35,"t":"Ev'in (Kâbe’nin) yanındaki (sözde) ibadetleri, ıslık çalmak ve el çırpmaktan başka bir şey değildi. İnkâr ettikleriniz nedeniyle azabı tadın!"},{"n":36,"t":"Şüphesiz ki kâfir olanlar, mallarını (insanları) Allah yolundan alıkoymak için harcıyorlar; daha da harcayacaklar. Sonunda bu, onlara pişmanlık olacak ve en sonunda yenileceklerdir. Kâfirler cehenneme sürüleceklerdir."},{"n":37,"t":"(Bu toplama), Allah’ın kirliyi (kâfiri) temizden (müminden) ayıklaması ve (bütün) kötülerin bir kısmını diğer bir kısmının üstüne koyup hepsini istifleyerek, hepsini cehenneme atması içindir. İşte onlar, kaybedenlerin ta kendileridir."},{"n":38,"t":"Kâfir olanlara de ki: (İnkârdan) vazgeçerlerse, geçmiş (günahları) bağışlanacaktır. (İnkâra) geri dönerlerse öncekilere (uygulanan ilahi) kanun elbette geçmiştir (onlar için geçerlidir)."},{"n":39,"t":"Fitne (baskı ve zulüm) kalmayıncaya ve bütünüyle din de yalnızca Allah için oluncaya kadar onlarla savaşın! (İnkârdan) vazgeçerlerse şüphesiz ki Allah onların yaptıklarını çok iyi görendir."},{"n":40,"t":"Yüz çevirirlerse, bilin ki Allah sizin mevlanızdır (efendinizdir). Ne güzel mevla (efendi)dir ve ne güzel yardımcıdır!"},{"n":41,"t":"Allah’a ve doğru ile yanlışın ayrıldığı gün, (yani) iki ordunun karşılaştığı gün (Bedir savaşında) kulumuza indirdiğimize inanmışsanız, bilin ki ganimet olarak aldığınız herhangi bir şeyin beşte biri, Allah, Elçi, yakınlık sahibi (olanlar), yetimler, yoksullar ve yolcu(lar) içindir. Allah her şeye gücü yetendir."},{"n":42,"t":"Hani (Bedir savaşında) siz vadinin yakın kenarında (Medine tarafında)ydınız; onlar da uzak kenarında (Mekke tarafında)ydılar. Kervan ise sizden daha aşağıda (sahilde)ydi. (Savaş için) sözleşmiş olsaydınız, zaman hakkında anlaşmazlığa düşerdiniz. Fakat Allah, yapılması (gerekli) olan emri yerine getirmesi, helak olanın apaçık bir delille helak olması, yaşayanın da apaçık bir delille yaşaması için (böyle yapmıştı). Şüphesiz ki Allah duyandır, bilendir."},{"n":43,"t":"Hani Allah uykunda sana onları “az” göstermişti. Sana onları “çok” gösterseydi, elbette çekinecek ve bu iş hakkında elbette tartışmaya girişecektiniz. Fakat Allah (sizi bundan) kurtarmıştı. Şüphesiz ki O, göğüslerin (kalplerin) özünü bilendir."},{"n":44,"t":"Hani (Allah) yapılması (gerekli) olan emri yerine getirmesi için (savaş alanında) karşılaştığınız zaman size onları gözlerinizde az gösteriyor, sizi de onların gözlerinde azaltıyordu. Bütün işler, yalnızca Allah’a döndürülecektir."},{"n":45,"t":"Ey iman edenler! (Daha önce size savaş açan) herhangi bir topluluk ile karşılaştığınız zaman dayanıklı olun ve Allah’ı çok hatırlayın ki kurtulasınız!"},{"n":46,"t":"Allah’a ve Elçisine itaat edin; birbirinizle çekişmeyin; sonra korkuya kapılırsınız da gücünüz gider. Sabredin (direnç gösterin)! Şüphesiz ki Allah sabredenlerle beraberdir."},{"n":47,"t":"Çalım satmak, insanlara gösteriş yapmak ve (insanları) Allah yolundan alıkoymak için yurtlarından çıkanlar (saldıran kâfirler) gibi olmayın! Allah onların yaptıklarını çepeçevre kuşatandır."},{"n":48,"t":"Hani şeytan onlara yaptıklarını güzel göstermiş ve “Bugün insanlardan size galip gelecek kimse yoktur; şüphesiz ki ben de sizin yardımcınızım!” demişti. Ne zaman ki iki ordu birbirini görünce (şeytan) iki topuğunun üzerine geriye dönmüş ve “Şüphesiz ki ben sizden uzağım; şüphesiz ben sizin göremediğinizi görüyorum; gerçek şu ki ben Allah’tan korkuyorum. Allah’ın azabı şiddetlidir.” demişti."},{"n":49,"t":"Hani münafıklar ve kalplerinde hastalık bulunanlar, (Bedir’e giden müslümanlar için) “Bunları dinleri aldatmış!” diyorlardı. (Oysa) kim Allah’a güvenirse, şüphesiz ki Allah güçlüdür, doğru hüküm verendir."},{"n":50,"t":"Hani melekler yüzlerine ve arkalarına vurarak ve “Tadın yakıcı azabı!” (diyerek) o kâfir olanların canlarını alırken onları bir görseydin!"},{"n":51,"t":"İşte bu, ellerinizin öne sunduğu şeyler yüzündendir. Şüphesiz ki Allah kullarına asla haksızlık edici değildir."},{"n":52,"t":"(Bunların durumu) tıpkı Firavun’un ailesi (destekçileri) ve onlardan öncekilerin durumu gibidir. (Onlar da) Allah’ın ayetlerini inkâr etmişlerdi de Allah onları günahları sebebiyle yakalamıştı. Şüphesiz ki Allah güçlüdür, azabı şiddetli olandır."},{"n":53,"t":"Bunun sebebi, bir toplum kendilerinde bulunanı değiştirinceye kadar Allah’ın onlara verdiği nimeti değiştirmemesi ve şüphesiz ki Allah’ın duyan ve bilen olmasıdır."},{"n":54,"t":"(Bunların durumu) tıpkı Firavun’un ailesi (destekçileri) ve onlardan öncekilerin durumu gibidir. Onlar Rablerinin ayetlerini yalanlamışlardı; biz de onları günahları nedeniyle helak etmiş ve Firavun’un ailesini (destekçilerini denizde) boğmuştuk. Hepsi de zalimdiler."},{"n":55,"t":"Şüphesiz ki Allah katında canlıların en kötüsü, kâfir olanlardır. (Çünkü) onlar, iman etmezler."},{"n":56,"t":"Kendileriyle antlaşma yaptığın, sonra her defasında takvâlı (duyarlı) davranmayıp sözleşmelerini bozanlar(a gelince),"},{"n":57,"t":"Savaşta onları yakalarsan, onları darmadağın et ki arkalarından gelenler için (gerçeği) hatırlamaları noktasında (bir ders olsun)."},{"n":58,"t":"(Antlaşma yaptığın) bir kavmin ihanet etmesinden korkarsan, sen de (onlarla yaptığın antlaşmayı) aynı şekilde bozduğunu kendilerine bildir! Şüphesiz ki Allah hainleri sevmez."},{"n":59,"t":"Kâfir olanlar (Allah’ı) geçtiklerini (azaptan kurtulduklarını) sanmasınlar! Şüphesiz ki onlar, (bizi) aciz bırakamazlar."},{"n":60,"t":"Onlara (düşmanlara) karşı gücünüz yettiği kadar kuvvet ve bağlanıp beslenen atlar hazırlayın ki onunla Allah’ın düşman(lar)ını, sizin düşman(lar)ınızı ve onlardan başka sizin bilmediğiniz, Allah’ın bildiği diğerlerini korkutursunuz. Allah yolunda ne infak ederseniz (verirseniz) size eksiksiz ödenir; siz asla haksızlığa uğratılmazsınız."},{"n":61,"t":"Onlar barışa yanaşırlarsa sen de ona (barışa) yanaş ve Allah’a güven! Şüphesiz ki yalnızca O duyandır, bilendir."},{"n":62,"t":"Sana hile yapmak isterlerse, sana Allah yeter. O seni yardımıyla ve müminlerle destekleyendir."},{"n":63,"t":"(Allah) onların kalplerinin arasını birleştirmiştir. Sen yeryüzünde bulunan her şeyi verseydin, yine onların kalplerinin arasını birleştiremezdin fakat Allah onların arasını kaynaştırdı. Şüphesiz ki O güçlüdür, doğru hüküm verendir."},{"n":64,"t":"Ey Peygamber! Sana ve sana uyan müminlere Allah yeter!"},{"n":65,"t":"Ey Peygamber! (Saldırıya karşılık) müminleri savaşa teşvik et! Sizden sabırlı yirmi (kişi) olursa, iki yüz (kâfir)e galip gelebilir. Sizden yüz (kişi) olursa, (gerçeği) anlamayan bir topluluk olmaları sebebiyle kâfir olanlardan bin (kâfir)e galip gelebilir."},{"n":66,"t":"Şimdi Allah yükünüzü hafifletti; sizde zayıflık olduğunu bildi. Sizden sabırlı yüz (kişi) olursa, (onlardan) iki yüz (kâfir)e galip gelebilir. Sizden bin (kişi) olursa, Allah’ın izniyle (onlardan) iki bin (kâfir)e galip gelebilir. Allah sabredenlerle beraberdir."},{"n":67,"t":"Hiçbir peygambere yeryüzünde ağır basıncaya (kesin bir zafere ulaşıncaya) kadar, (yanında) esirler bulundurmak yakışmaz. Siz geçici dünya malını istiyorsunuz, Allah ise (sizin için) ahireti istiyor. Allah güçlüdür, doğru hüküm verendir."},{"n":68,"t":"Allah tarafından (bir hüküm) geçmiş olmasaydı, aldığınız (ganimet)le ilgili size mutlaka büyük bir azap dokunurdu."},{"n":69,"t":"Artık elde ettiğiniz ganimetten temiz, helal olarak yiyin! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":70,"t":"Ey Peygamber! Elinizdeki esirlere de ki: Allah kalplerinizde hayır olduğunu bilirse, sizden alınandan daha hayırlısını size verir ve sizi bağışlar. Allah çok bağışlayandır, çok merhametlidir."},{"n":71,"t":"Sana ihanet (etmek) isterlerse -ki daha önce Allah’a da ihanet etmişlerdi- ve Allah onlar nedeniyle (sana) imkân vermişti. Allah bilendir, doğru hüküm verendir."},{"n":72,"t":"Şüphesiz ki iman edip hicret edenler, Allah yolunda mallarıyla, canlarıyla cihad eden (fedakârlık yapan muhacir)ler ve (onları) barındırıp yardım edenler (ensar) var ya, işte onlar birbirlerinin dostudur. İman edip hicret etmeyenlere gelince, onlar hicret edinceye kadar size onların sahiplenip korunmalarıyla ilgili hiçbir sorumluluk yoktur. Onlar din hakkında sizden yardım isterlerse, sizinle aralarında sözleşme bulunan bir toplum aleyhine olmaksızın (o müslümanlara) yardım etmek üzerinize borçtur. Allah yapmakta olduğunuz her şeyi görendir."},{"n":73,"t":"Kâfir olanlar da birbirlerinin dostudur. Siz onu (o dostluk birlikteliğini) yerine getirmezseniz, yeryüzünde bir fitne ve büyük bir bozgunculuk olur."},{"n":74,"t":"İman edip Allah yolunda hicret ve cihad edenler (fedakârlık yapanlar), (muhacirleri) barındırıp yardım edenler (ensar) var ya, işte gerçek müminler onlardır. Onlar için bağışlanma ve değerli bir rızık vardır."},{"n":75,"t":"Sonradan iman edecek olan ve hicret edip sizinle birlikte cihad edecekler (fedakârlık yapacaklar) da sizdendir. Allah’ın kitabına göre yakınlık sahibi olanlar birbirlerine daha uygundur. Şüphesiz ki Allah her şeyi bilendir."}],[{"n":1,"t":"(Bu), Allah ve Elçisi'nden kendileriyle antlaşma yapmış olduğunuz müşriklere bir ayrılış (uyarısı)dır!"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın! İyi bilin ki Allah’ı aciz bırakıcı değilsiniz; Allah ise kâfirleri rezil edecektir."},{"n":3,"t":"(Bu), en büyük hac gününde Allah ve Elçisinden (bütün) insanlara bir bildiridir: Allah müşriklerden uzaktır, Elçisi de. Tevbe ederseniz, bu sizin için hayırlı olandır. Yüz çevirirseniz, bilin ki siz Allah’ı aciz bırakacak değilsiniz. O kâfir olanlara elem verici bir azabı müjdele!"},{"n":4,"t":"Ancak kendileriyle antlaşma yaptığınız müşriklerden (antlaşma şartlarına uyan), hiçbir şeyi size eksik bırakmayan ve sizin aleyhinize herhangi bir kimseye arka çıkmayanlar (bu hükmün) dışındadır. Onların antlaşmalarını süreleri bitinceye kadar tamamlayın! Şüphesiz ki Allah muttakîleri (duyarlı olanları) sever."},{"n":5,"t":"Haram aylar çıkınca (antlaşmayı bozan) o müşrikleri bulduğunuz yerde öldürün; onları yakalayın; onları hapsedin ve onları her gözetleme yerinde oturup bekleyin! Tevbe eder, namazı kılar, zekâtı da verirlerse artık yollarını serbest bırakın! Allah çok bağışlayandır, çok merhametlidir."},{"n":6,"t":"Müşriklerden biri senden yakınlık (güvence) dilerse, Allah’ın kelamını (duyup) dinleyinceye kadar ona yakınlık (güvence) ver! Sonra (Müslüman olmazsa) onu güven içinde bulunacağı bir yere ulaştır! İşte bu (hoşgörü, gerçeği) bilmeyen bir topluluk olmalarından dolayıdır."},{"n":7,"t":"Mescid-i Haram’ın yanında kendileriyle antlaşma yaptıklarınızın dışında, müşriklerin Allah ve Elçisi yanında nasıl bir sözü olabilir ki! Onlar size karşı dürüst davrandıkları sürece siz de onlara dürüst davranın! Şüphesiz ki Allah muttakîleri (duyarlı olanları) sever."},{"n":8,"t":"Nasıl (onların bir sözü) olabilir ki! Onlar size galip gelselerdi, sizin hakkınızda söz de antlaşma da gözetmezlerdi. Onlar ağızlarıyla sizi razı ediyorlar; (oysa) kalpleri yüz çeviriyor. Onların çoğu yoldan çıkmışlardır."},{"n":9,"t":"Allah’ın ayetlerini az bir değer karşılığında sattılar ve (insanları) O’nun yolundan alıkoydular. Şüphesiz ki onların yapmakta oldukları şeyler ne kötüdür!"},{"n":10,"t":"Bir mümin hakkında söz ve antlaşma gözetmezler. (Çünkü) onlar, saldıranların ta kendileridir."},{"n":11,"t":"(Fakat) tevbe eder, namaz kılar ve zekât verirlerse artık onlar dinde kardeşlerinizdir. Bilen bir topluma ayetlerimizi ayrıntılı bir şekilde açıklıyoruz."},{"n":12,"t":"Antlaşmalarından sonra yeminlerini bozar ve dininize dil uzatırlarsa, yeminleri olmayan (yeminlere sadakat göstermeyen) küfrün önderlerine karşı savaşın! Umulur ki küfre son verirler."},{"n":13,"t":"Antlaşma yeminlerini bozan, Elçiyi (yurdundan) çıkarmaya çalışan ve ilk önce size karşı (savaşa) başlamış olan bir kavme karşı savaşmayacak mısınız? Yoksa onlardan korkuyor musunuz? (Gerçek) müminlerseniz, (bilin ki) Allah kendisinden korkmanıza daha layıktır."},{"n":14,"t":"Onlarla savaşın ki Allah sizin ellerinizle onları cezalandırsın, onları rezil etsin; onlara karşı size yardım etsin ve mümin topluluğun kalplerini ferahlatsın!"},{"n":15,"t":"Kalplerinden öfkeyi gidersin! Allah dileyenin (layık gördüğünün) tevbesini kabul eder. Allah bilendir, doğru hüküm verendir."},{"n":16,"t":"Yoksa Allah, sizden cihad edip (fedakârlık yapıp) Allah’tan, Elçisinden ve müminlerden başkasını kendilerine sırdaş edinmeyenleri bil(dir)meden (ortaya çıkarmadan) terk edileceğinizi (bırakılacağınızı) mı sandınız? Allah yaptıklarınızdan haberdardır."},{"n":17,"t":"Müşriklerin, kendilerinin kâfirliğine bizzat kendileri şahitlik ederlerken, Allah’ın mescitlerini imar etme görevleri yoktur. Onların bütün işleri boşa gitmiştir. Onlar, ateşte ebedî kalacaklardır."},{"n":18,"t":"Allah’ın mescitlerini ancak Allah’a ve ahiret gününe iman eden, namazı kılan, zekâtı veren ve Allah’tan başkasından korkmayan (kişiler) ömürlendirir. İşte doğru yola ulaşanlardan olmaları umulanlar bunlardır."},{"n":19,"t":"(Ey müşrikler)! Siz hacılara su vermeyi ve Mescid-i Haram’ı onarmayı, Allah’a ve ahiret gününe iman edip Allah yolunda cihad edenlerin (fedakârlık yapanların) imanı ile bir mi tutuyorsunuz? (Oysa) onlar Allah katında eşit değillerdir. Allah o zalimler topluluğunu doğru yola ulaştırmaz."},{"n":20,"t":"İman edip hicret edenler ve Allah yolunda mallarıyla, canlarıyla cihad edenler (fedakârlık yapanlar), derece bakımından Allah katında daha üstündürler. İşte onlar kurtulanların ta kendileridir."},{"n":21,"t":"Rableri onlara, tarafından bir merhamet ve hoşnutluk ile kendileri için içinde kalıcı (tükenmez) nimetler bulunan cennetler müjdeler."},{"n":22,"t":"Onlar orada ebedî kalacaklardır. Şüphesiz ki büyük ödül yalnızca Allah’ın katındadır."},{"n":23,"t":"Ey iman edenler! Küfrü imana tercih ediyorlarsa babalarınızı ve kardeşlerinizi (bile) dostlar edinmeyin! Sizden kim onları dost edinirse işte onlar zalimlerin ta kendileridir."},{"n":24,"t":"De ki: “Babalarınız, çocuklarınız, kardeşleriniz, eşleriniz, hısım akrabanız, kazandığınız mallar, kesada uğramasından (yok olup gitmesinden) korktuğunuz ticaret, hoşlandığınız meskenler size Allah’tan, Elçisinden ve Allah yolunda cihad etmekten (fedakârlık yapmaktan) daha sevgili ise artık Allah emrini getirinceye kadar bekleyin!” Allah yoldan çıkanlar topluluğunu doğru yola ulaştırmaz."},{"n":25,"t":"Şüphesiz ki Allah birçok yerde ve Huneyn gününde size yardım etmişti. Hani çokluğunuz size kendinizi beğendirmiş, (fakat bu durum) sizden hiçbir (sıkıntıyı) gidermemişti. Yeryüzü bütün genişliğine rağmen size dar gelmişti; sonunda (bozulup) geri dönenler olarak yüz çevirmiştiniz (kaçmıştınız)."},{"n":26,"t":"Sonra Allah, Elçisine ve müminlere güven indirmişti. Sizin görmediğiniz ordular (melekler) göndermişti de kâfirlere azap etmişti. İşte bu, kâfir olanların cezasıdır."},{"n":27,"t":"Sonra Allah bunun ardından yine dilediğinin (layık olanın) tevbesini kabul edecektir. Allah çok bağışlayandır, çok merhametlidir."},{"n":28,"t":"Ey iman edenler! Müşrikler ancak bir pisliktir. Onun için bu yıllarından sonra Mescid-i Haram’a yaklaşmasınlar! Yoksulluktan korkarsanız, (bilin ki) Allah dilerse sizi kendi lütfundan zengin edecektir. Şüphesiz ki Allah bilendir, doğru hüküm verendir."},{"n":29,"t":"Kendilerine kitap verilenlerden Allah’a ve ahiret gününe inanmayan, Allah’ın ve Elçisinin haram kıldığını haram saymayan ve gerçek dini din edinmeyen kişilerle, küçülerek elden (peşin) cizye verinceye kadar savaşın!"},{"n":30,"t":"(Bazı) yahudiler, “Üzeyir Allah’ın oğludur.” demişlerdi. (Bazı) hristiyanlar da “Mesih (İsa) Allah’ın oğludur.” demişlerdi. Bu, onların ağızlarındaki (anlamsız) sözleridir. (Sözlerini) daha önce kâfir olanların sözlerine benzetiyorlar. Allah onları kahretsin! Nasıl da (gerçeklerden) döndürülüyorlar!"},{"n":31,"t":"(Yahudiler) hahamlarını (bilginlerini), (hristiyanlar) da rahiplerini ve Meryem oğlu Mesih’i (İsa’yı) Allah’ın peşi sıra rabler edinmişlerdi. (Oysa) onlara ancak tek bir ilaha kulluk etmeleri emrolunmuştu. O’ndan başka ilah yoktur. O, onların ortak koştuklarından yücedir."},{"n":32,"t":"Onlar ağızlarıyla Allah’ın nurunu söndürmek istiyorlar. (Oysa) kâfirler istemeseler de Allah nurunu tamamlamaktan asla vazgeçmez."},{"n":33,"t":"Müşrikler istemese de (dinini) bütün din(ler)e üstün kılmak için Elçisini bir rehber ve gerçek din ile gönderen O’dur."},{"n":34,"t":"Ey iman edenler! (Bilin ki) hahamlardan ve rahiplerden birçoğu insanların mallarını batıl yollarla yerler ve (insanları) Allah yolundan engellerler. Altın ve gümüşü yığıp da onları Allah yolunda infak etmeyenler (vermeyenler) var ya, işte onlara elem verici bir azabı müjdele!"},{"n":35,"t":"O gün cehennem ateşinde (bu biriktirilen şeylerin) üzeri kızdırılacaktır ve bu (birikim)lerle onların alınları, yanları ve sırtları dağlanacaktır. (Kendilerine şöyle denecektir): “İşte bu, kendiniz için biriktirdiğiniz (servet)tir. Artık yığmış olduğunuz şeylerin (azabını) tadın!”"},{"n":36,"t":"Gökleri ve yeri yarattığı günde Allah’ın kitabına (yasasına) göre Allah katında ayların sayısı on iki olup, bunlardan dördü haram aylardır. İşte bu doğru dindir (yasadır). Onlarda (haram aylar konusunda) kendinize haksızlık etmeyin ve onlar nasıl sizinle topyekûn savaşıyorlarsa siz de müşriklerle topyekûn savaşın! Bilin ki Allah muttakîlerle (duyarlı olanlarla) beraberdir."},{"n":37,"t":"(Haram ayları) ertelemek (sayısını artırmak), sadece küfürde bir artış (sebebi)dir. Onunla, kâfir olanlar saptırılır. O (haram ayı)nı bir yıl helal sayarlar, bir yıl haram sayarlar ki Allah’ın haram kıldığının sayısını denk getirsinler ve (böylece) Allah’ın haram kıldığını helal kılsınlar. (Bu şekilde) onların kötü işleri kendilerine güzel gösterilmiştir. Allah kâfirler topluluğunu doğru yola ulaştırmaz."},{"n":38,"t":"Ey iman edenler! Size ne oldu ki “Allah yolunda savaşa çıkın!” dendiği zaman yere çakılıp kalıyorsunuz! Dünya hayatını ahirete tercih mi ediyorsunuz! Dünya hayatının geçimliği (yararı) ahirete göre azdır."},{"n":39,"t":"(Gerektiğinde savaşa) çıkmazsanız, (Allah) sizi elem verici bir azapla cezalandırır ve yerinize sizden başka bir toplum getirir. Siz (savaşa çıkmamakla) ona hiçbir zarar veremezsiniz. Allah her şeye gücü yetendir."},{"n":40,"t":"Siz ona (Tebük’te) yardım etmezseniz (bu önemli değil); kâfir olanlar onu, iki kişinin ikincisi olarak (Mekke’den) çıkardıklarında elbette Allah ona yardım etmişti. Hani onlar mağaradaydı da (Elçi), arkadaşına “Üzülme, şüphesiz ki Allah bizimledir.” diyordu. (Bunun üzerine) Allah ona güven duygusu indirmiş, onu sizin görmediğiniz bir ordu ile desteklemişti. kâfir olanların sözünü alçaltmıştı. Allah’ın sözü gerçek yüce olandır. Allah güçlüdür, doğru hüküm verendir."},{"n":41,"t":"Gerek hafif, gerek ağır olarak savaşa çıkın; mallarınızla ve canlarınızla Allah yolunda cihad edin (fedakârlık yapın)! Bilirseniz bu sizin için hayırlı olandır."},{"n":42,"t":"Yakın bir dünya malı ve kolay bir yolculuk olsaydı (o münafıklar) mutlaka sana uyup peşinden gelirlerdi. Fakat meşakkatli (zor) yol onlara uzak geldi. Onlar “Gücümüz yetseydi mutlaka sizinle birlikte çıkardık.” diye kendilerini helak edercesine (yalan yere) Allah’a yemin edecekler. Allah onların mutlaka yalancı olduklarını bilmektedir."},{"n":43,"t":"Allah seni affetsin! Doğru söyleyenler sana iyice belli olup, yalancıları bilinceye kadar onlara niçin izin verdin?"},{"n":44,"t":"Allah’a ve ahiret gününe iman edenler, mallarıyla ve canlarıyla cihad (fedakârlık) konusunda (geri kalmak için) senden izin istemezler. Allah muttakîleri (duyarlı olanları) bilendir."},{"n":45,"t":"Senden izin isteyenler yalnızca Allah’a ve ahiret gününe inanmayan, kalpleri şüpheye düşüp, kuşkuları içinde bocalayanlardır."},{"n":46,"t":"Onlar (savaşa) çıkmak isteselerdi elbette bunun için bir hazırlık yaparlardı. Fakat Allah onların katılmasını uygun görmedi ve onları geri bıraktırdı. Onlara “Oturanlarla (kadın ve çocuklarla) birlikte oturun!” dendi."},{"n":47,"t":"Aranızda (onlar da savaşa) çıksalardı, size bozgunculuktan başka hiçbir katkıları olmazdı ve mutlaka size (karşı) fitne (çıkarmak) isteyerek aranıza sokulurlardı. İçinizde, onlara iyice kulak verenler de vardır. Allah zalimleri bilendir."},{"n":48,"t":"Şüphesiz ki onlar (Tebük’ten) önce de fitne çıkarmak (huzur bozmak) istemişler ve sana (karşı) nice işler çevirmişlerdi. Sonunda gerçek gelmiş ve onlar istemedikleri hâlde Allah’ın emri ortaya çıkmıştı (yerini bulmuştu)."},{"n":49,"t":"Onlardan öylesi de var ki: “Bana izin ver; beni fitneye düşürme!” der. Dikkat edin! Onlar zaten fitneye düşmüşlerdir. Şüphesiz ki cehennem, kâfirleri mutlaka kuşatıcıdır."},{"n":50,"t":"Sana bir iyilik gelirse bu onları üzer. Başına bir musibet gelirse “(İyi ki) biz daha önce tedbirimizi almışız.” derler ve kibirlenerek dönüp giderler."},{"n":51,"t":"De ki: “Allah’ın bizim için yazdığından başkası bize asla ulaşmaz. O bizim mevlamızdır (efendimizdir). Onun için müminler yalnızca Allah’a güvensinler!”"},{"n":52,"t":"De ki: “Siz bizim için sadece iki güzellikten birini beklemektesiniz. Biz de Allah’ın ya kendi katından veya bizim elimizle size bir azap vermesini bekliyoruz. Bekleyin! Şüphesiz ki biz de sizinle birlikte beklemekteyiz.”"},{"n":53,"t":"De ki: “İster gönüllü, isterse zorla verin; (yaptığınız infak) sizden asla kabul edilmeyecektir. Şüphesiz ki siz yoldan çıkan bir topluluk oldunuz.”"},{"n":54,"t":"Onların infaklarının (verdiklerinin) kabul edilmesini engelleyen sebep, onların Allah’ı ve Elçisini inkâr etmeleri, namaza sadece üşenerek gelmeleri ve sadece istemeyerek infakta bulunmalarından (vermelerinden) başka bir şey değildir."},{"n":55,"t":"Onların malları ve çocukları seni imrendirmesin! Şüphesiz ki Allah bunlarla ancak dünya hayatında onların azaplarını çoğaltmayı ve onların kâfir olarak can vermesini istiyor."},{"n":56,"t":"(O münafıklar) mutlaka sizden olduklarına dair Allah’a yemin ederler. (Oysa) onlar sizden değillerdir fakat onlar korkan bir toplumdur."},{"n":57,"t":"Sığınacak herhangi bir yer veya (barınabilecek) mağaralar veya (sokulabilecek) herhangi bir delik bulsalardı koşarak o tarafa yönelip giderlerdi."},{"n":58,"t":"Onlardan sadakaların (dağıtımı) hakkında seni ayıplayanlar da vardır. (Sadakalardan) onlara da (bir pay) verilirse razı olurlar; kendilerine onlardan verilmezse hemen kızarlar."},{"n":59,"t":"Onlar Allah’ın ve Elçisinin kendilerine verdiğine razı olup “Allah bize yeter; yakında bize Allah da lütfundan verecektir, Elçisi de. Biz yalnızca Allah’a rağbet edenleriz.” deselerdi (daha iyi olurdu)."},{"n":60,"t":"Sadakalar Allah’tan bir farz olarak ancak yoksullara, düşkünlere, (zekât toplayan) memurlara, kalpleri (İslam’a) ısındırılmış olanlara, (özgürleşmek isteyen) kölelere, borçlulara, Allah yolunda olanlara, yolcuya mahsustur. Allah bilendir, doğru hüküm verendir."},{"n":61,"t":"(Münafıklardan:) “O (Peygamber, her söyleneni dinleyen) bir kulaktır.” diyerek Peygamber’i incitenler de vardır. De ki: “O, sizin için bir hayır kulağıdır. (Çünkü) o Allah’a inanır, müminlere güvenir ve o sizden iman edenler için de bir rahmettir. Allah’ın Elçisine eziyet edenler için elem verici bir azap vardır.”"},{"n":62,"t":"Sizi memnun etmek için (gelip) Allah’a (yalan yere) yemin ederler. Mümin iseler Allah ve Elçisi razı edilmeye daha layıktır."},{"n":63,"t":"(Hâlâ) bilmediler mi ki kim Allah’a ve Elçisine karşı çıkarsa, onun için içinde ebedî kalacağı cehennem ateşi vardır. İşte bu büyük rezilliktir."},{"n":64,"t":"O münafıklar, kalplerinde olanı kendilerine bildirecek bir surenin onlara (müminlere) indirilmesinden çekinirler. De ki: “Siz alay edin (bakalım)! Şüphesiz ki Allah çekindiğiniz şeyi ortaya çıkaracaktır.”"},{"n":65,"t":"Onlara (niçin alay ettiklerini) sorarsan, elbette “Biz sadece lafa dalmış şakalaşıyorduk.” derler. De ki: “Allah ile, O’nun ayetleri ile ve Elçisi ile mi alay ediyordunuz?”"},{"n":66,"t":"(Boşuna) özür dilemeyin! (Çünkü) siz iman ettikten sonra elbette kâfir oldunuz. Sizden (tevbe eden) bir grubu bağışlasak bile suçlu olduklarından dolayı bir gruba da azap edeceğiz."},{"n":67,"t":"Münafık erkekler ve münafık kadınlar (sizden değil), birbirlerindendir. Kötülüğü emreder, iyilikten alıkor ve ellerini kısarlar (cimrilik ederler). Onlar Allah’ı unuttular. (Allah da) onları (kendi hallerinde) unuttu (terk etti)! Şüphesiz ki münafıklar, yoldan çıkanların ta kendileridir."},{"n":68,"t":"Allah münafık erkeklere de münafık kadınlara da kâfirlere de içinde ebedî kalacakları cehennem ateşini vadetmiştir. O (cehennem) onlara yeter. Allah onlara lanet etmiştir! Onlar için kalıcı bir azap vardır."},{"n":69,"t":"(Ey münafıklar! Siz de) sizden kuvvetçe daha üstün, mal ve evlatça daha çok olan sizden öncekiler gibi (yaptınız). Onlar (dünya malından) paylarına düşenden yararlanmışlardı. Sizden öncekiler nasıl paylarına düşenden yararlandıysalar siz de payınıza düşenden yararlandınız ve (yanlışa) dalanlar gibi siz de daldınız. İşte onların işleri dünyada da ahirette de boşa gitmiştir. Onlar kaybedenlerin ta kendileridir."},{"n":70,"t":"Onlara kendilerinden öncekilerin, Nuh kavminin, Âd’in, Semûd’un, İbrahim kavminin, Medyen halkının ve altüst olan şehirlerin haberi ulaşmadı mı? Elçileri onlara apaçık deliller getirmişti. Allah onlara haksızlık edecek değildi fakat onlar kendi kendilerine haksızlık etmekteydiler."},{"n":71,"t":"Mümin erkeklerle mümin kadınlar birbirlerinin dostudurlar. (Birbirlerine) iyiliği emreder (öğütler), kötülükten engeller (sakındırır); namazı kılar, zekâtı verir; Allah’a ve Elçisine itaat ederler. İşte Allah onlara merhamet edecektir. Şüphesiz ki Allah güçlüdür, doğru hüküm verendir."},{"n":72,"t":"Allah mümin erkeklere ve mümin kadınlara, içinde ebedî kalmak üzere altlarından ırmaklar akan cennetler ve durmaya değer cennetlerde güzel meskenler vadetmiştir. Allah’ın rızası ise (hepsinden) büyüktür. Asıl büyük kurtuluş işte budur."},{"n":73,"t":"Ey Peygamber! O kâfirlerle ve o münafıklarla cihad et; onlara karşı sert davran! Onların barınağı cehennemdir. Ne kötü varış yeridir (orası)!"},{"n":74,"t":"(Münafıklar o sözleri) söylemediklerine dair Allah’a yemin ediyorlar. (Oysa) o küfür sözünü elbette söylemişler ve Müslümanlıktan sonra kâfir olmuşlar, başaramadıkları bir şeye de yeltenmişlerdi. Sırf Allah ve Elçisi kendi lütfundan onları zenginleştirdiği için öç almaya kalkışmışlardı. Tevbe ederlerse onlar için hayırlı olur. Yüz çevirirlerse Allah onlara dünyada da ahirette de elem verici şekilde azap edecektir. Yeryüzünde onların dostu da yardımcısı da yoktur."},{"n":75,"t":"Onlardan kimi de “(Allah) lütfundan bize verirse, mutlaka sadaka vereceğiz ve (özü sözü) iyilerden olacağız!” diye Allah’a söz vermişti."},{"n":76,"t":"Fakat (Allah) lütfundan onlara (zenginlik) verince, onda cimrilik edip (Allah’ın emrinden) yüz çevirerek (sözlerinden) dönmüşlerdi."},{"n":77,"t":"Sonunda, Allah’a verdikleri sözden döndüklerinden ve yalan söylediklerinden dolayı, (Allah) kendisiyle karşılaşacakları güne kadar onların kalbine nifakı (ikiyüzlülüğü) yerleştirmiştir."},{"n":78,"t":"(Münafıklar), Allah’ın, onların sırrını da fısıltılarını da bildiğini ve gaybları (bilinemeyenleri) çok iyi bilen olduğunu (hâlâ) anlamadılar mı?"},{"n":79,"t":"Sadakalar hakkında, müminlerden gönüllü verenleri ve güçlerinin yettiğinden başkasını bulamayanları çekiştirip onlarla alay edenler var ya, Allah da onlarla alay edecektir. Onlar için elem verici azap vardır."},{"n":80,"t":"Onlar için ister af dile, ister dileme; onlar için yetmiş kez af dilesen de Allah onları asla affetmeyecektir. Bu, onların Allah’ı ve Elçisini inkâr etmelerinden ötürüdür. Allah yoldan çıkanlar topluluğunu doğru yola ulaştırmaz."},{"n":81,"t":"Allah’ın Elçisine muhalefet etmek için geri kalanlar (sefere çıkmayıp) oturmaları ile sevinmişler, mallarıyla, canlarıyla Allah yolunda cihad (fedakârlık) etmeyi çirkin görmüşler ve “Bu sıcakta sefere çıkmayın.” demişlerdi. De ki: “Cehennem ateşi daha sıcaktır! Keşke anlasalardı!”"},{"n":82,"t":"Artık yapıp ettiklerinin bir karşılığı olarak az gülsünler, çok ağlasınlar!"},{"n":83,"t":"Allah seni onlardan bir grubun yanına döndürür de (başka bir savaşa seninle birlikte) çıkmak için senden izin isterlerse, (onlara) de ki: “Benimle birlikte asla (savaşa) çıkmayacaksınız ve düşmana karşı benimle birlikte asla savaşmayacaksınız! Şüphesiz ki siz birinci kez (Tebük seferinde) yerinizde kalmaya razı oldunuz. Şimdi de geri kalanlarla (kadınlarla ve çocuklarla) birlikte oturun!”"},{"n":84,"t":"Onlardan ölmüş olan hiçbirine asla salât (dua) etme; onun kabri (başı)nda da durma! Şüphesiz ki onlar, Allah’ı ve Elçisini inkâr ettiler ve yoldan çıkanlar olarak öldüler."},{"n":85,"t":"Onların malları ve çocukları seni imrendirmesin! Şüphesiz ki Allah bunlarla ancak dünyada onlara azap etmeyi ve onların kâfir olarak can vermesini istiyor."},{"n":86,"t":"(Onlara) “Allah’a inanın, Elçisi ile birlikte cihad edin (fedakârlık yapın)!” diye bir sure indirildiği zaman, içlerinden servet sahibi olanlar senden izin istemişler ve “Bizi bırak; (evlerinde) oturanlarla birlikte olalım.” demişlerdi."},{"n":87,"t":"Geride kalan kadınlarla birlikte olmaya (kalmaya) razı oldular; (bu nedenle) onların kalplerine mühür vuruldu. Artık (gerçeği) anlamazlar."},{"n":88,"t":"Fakat Elçi ve onunla birlikte inananlar, mallarıyla, canlarıyla cihad ettiler (fedakârlık yaptılar). İşte bütün hayırlar onlarındır ve onlar kurtulanların ta kendileridir."},{"n":89,"t":"Allah onlara içlerinde ebedî kalacakları ve altlarından ırmaklar akan cennetler hazırlamış (olacak)tır. İşte bu, büyük kurtuluştur."},{"n":90,"t":"Göçebelerden mazeret ileri sürenler, kendilerine izin verilsin diye gelmişlerdi. Allah’a ve Elçisine yalan söyleyenler ise (evlerinde) oturmuşlardı. Onlardan kâfir olanlara yakında elem verici bir azap gelecektir."},{"n":91,"t":"Allah ve Elçisi için samimi olduklarında, zayıflara, hastalara ve (savaşta) infak edecek (verecek) bir şey bulamayanlara herhangi bir günah yoktur. (Zira) güzel davrananların aleyhine hiçbir yol yoktur. Allah çok bağışlayandır, çok merhametlidir."},{"n":92,"t":"Kendilerine binek sağlaman için sana geldiklerinde “Sizi bindirecek bir (binek) bulamıyorum.” deyince, (savaş için) infak edecek hiçbir şey bulamadıklarından dolayı üzüntüden gözyaşı dökerek dönen kişilere de (sorumluluk yoktur)."},{"n":93,"t":"Sorumluluk sadece zengin oldukları hâlde senden izin isteyenlerin üzerinedir. (Çünkü) onlar geride kalan kadınlarla birlikte olmaya razı oldular. (Bu nedenle) Allah da onların kalplerini mühürlemiştir; artık (gerçeği) bilemezler."},{"n":94,"t":"(Seferden) kendilerine döndüğünüz zaman sizden özür dileyecekler. De ki: “(Boşuna) özür dilemeyin! Size asla inanmayız; Allah elbette haberlerinizi bize bildirmiştir. İş(ler)inizi Allah da görecektir, Elçisi de. Sonra da görünmeyeni de görüneni de bilen (Allah)’a döndürüleceksiniz ve yaptıklarınızı size bildirecektir.”"},{"n":95,"t":"Onların yanına döndüğünüz zaman, size kendilerinden (onları cezalandırmaktan) vazgeçmeniz için Allah’a yemin edecekler. Artık onlardan yüz çevirin! Çünkü onlar (manevi olarak) pistir. Kazandıklarına karşılık onların barınağı cehennemdir."},{"n":96,"t":"Onlardan memnun olasınız diye size yemin edecekler. Fakat siz onlardan memnun olsanız bile Allah yoldan çıkanlar topluluğundan razı olmaz."},{"n":97,"t":"Göçebeler, kâfirlik ve münafıklık bakımından hem daha beter hem de Allah’ın Elçisine indirdiği sınırları tanımamaya daha meyillidir. Allah bilendir, doğru hüküm verendir."},{"n":98,"t":"Göçebelerden öylesi vardır ki (Allah yolunda) harcayacağını kayıp sayar ve sizin başınıza belâlar gelmesini bekler. (Müslümanlar için bekledikleri) kötülük çemberi kendi başlarına gelsin! Allah duyandır, bilendir."},{"n":99,"t":"Göçebelerden öylesi de vardır ki Allah’a ve ahiret gününe iman eder; (hayır için) yapmakta oldukları infaklarını Allah katında yakınlıklar ve o Elçinin salavâtı (yardımları) edinir. Dikkat edin! O (harcadıkları mal, Allah katında) onlar için bir yakınlıktır. Allah onları merhametine koyacaktır. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":100,"t":"(Müslüman olmada) öne geçen ilk muhacirler ve ensar ile onlara güzellikle uyanlar var ya, Allah kendilerinden razı, onlar da O’ndan memnun olmuşlardır. (Allah) onlara, içinde ebedî kalacakları, alt taraflarında ırmaklar akan cennetler hazırlamış (olacak)tır. İşte bu, büyük kurtuluştur."},{"n":101,"t":"Çevrenizdeki göçebe (Arap)lardan ve Medine halkından birtakım münafıklar vardır ki bunlar münafıklıkta ileri gitmiştir. Sen onları bilemezsin; onları biz biliriz. Onlara yakında iki kez azap edeceğiz; sonra da onlar büyük bir azaba itileceklerdir."},{"n":102,"t":"Diğerleri ise günahlarını itiraf ettiler; iyi işi diğer kötü olanla karıştırdılar. Umulur ki Allah onların tevbesini kabul eder. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":103,"t":"Onların mallarından sadaka al; bununla onları temizlersin, onları arındırırsın. Onlara salât et (destek ol)! Şüphesiz ki senin salâtın (desteğin) onlar için huzur ve güven (kaynağı)dır. Allah duyandır, bilendir."},{"n":104,"t":"Yalnızca Allah’ın, kullarının tevbesini kabul edip sadakaları alacağını (geri çevirmeyeceğini) ve şüphesiz ki Allah’ın tevbeleri çok kabul eden, çok merhametli olduğunu (hâlâ) bilmezler mi?"},{"n":105,"t":"De ki: “(Yapacağınızı) yapın! İş(ler)inizi Allah da görecektir, Elçisi de müminler de. (Sonra) görünmeyeni de görüneni de bilen (Allah)’a döndürüleceksiniz de O size yapmış olduklarınızı bildirecektir.”"},{"n":106,"t":"(Tebük Gazvesi’ne katılmayanlardan) diğer bir grup da Allah’ın emrine bırakılmışlardır. O, kendilerine ya azap eder veya tevbelerini kabul eder. Allah bilendir, doğru hüküm verendir."},{"n":107,"t":"(Münafıklar arasında) bir de zarar vermek, inkâr etmek, müminlerin arasına ayrılık sokmak ve daha önce Allah’a ve Elçisine karşı savaşmış olan kişiyi beklemek için bir mescit edinenler ve “Biz güzellikten başka bir şey istemedik.” diye mutlaka yemin edecek olanlar vardır. Allah onların elbette yalancı olduklarına şahittir."},{"n":108,"t":"Orada asla (namaza) durma! İlk günden takvâ (duyarlılık) üzerine kurulan mescitte namaz kılman elbette doğrudur. Onda temizlenmeyi seven adamlar vardır. Allah temizlenenleri sever."},{"n":109,"t":"Binasını Allah’a karşı bir takvâ (duyarlılık) ve (Allah) rızası üzerine kuran kimse mi hayırlıdır, yoksa yapısını yıkılacak bir uçurumun kenarına kurup, onunla birlikte kendisi de cehennem ateşine düşen kimse(ninki) mi? Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":110,"t":"Yaptıkları bina, kalpleri parçalanıncaya kadar yüreklerine devamlı olarak bir kuşku (sebebi) olacaktır. Allah bilendir, doğru hüküm verendir."},{"n":111,"t":"Şüphesiz ki Allah, Allah yolunda savaşan, öldüren ve öldürülen müminlerden, canlarını ve mallarını, kendilerine (verilecek) cennet karşılığında satın almıştır. (Bu), Tevrat’ta, İncil’de ve Kur’an’da O’nun üzerinde gerçek bir vaat olarak (böyledir). Sözünde Allah’tan daha vefalı kim olabilir ki! O’nunla yapmış olduğunuz alışverişinizden dolayı sevinin! Asıl büyük kurtuluş işte budur."},{"n":112,"t":"(Bu alışverişi yapanlar), tevbe edenler, ibadet edenler, hamd edenler (övenler), (Allah yolunda) seyahat edenler (oruç tutanlar), rükû ve secde edenler, iyiliği emredip (öğütleyip) kötülükten engelleyen (sakındıran) ve Allah’ın sınırlarını koruyanlardır. (İşte bu) müminleri müjdele!"},{"n":113,"t":"(Kâfir olarak ölüp) cehennem halkı oldukları onlara açıkça belli olduktan sonra, akraba bile olsalar, (Allah’a) ortak koşanlar için af dilemek, Peygamber için de iman etmiş olanlar için de söz konusu olamaz."},{"n":114,"t":"İbrahim’in babası için af dilemesi, sadece ona verdiği sözden dolayıydı. Onun Allah’ın düşmanı olduğu kendisi için açıklanınca ondan uzaklaşmıştı. Şüphesiz ki İbrahim çok yufka yürekliydi; çok hoşgörülüydü."},{"n":115,"t":"Allah doğru yola ulaştırdıktan sonra, takvâlı (duyarlı) olacakları şeyleri kendilerine açıklayıncaya kadar hiçbir topluluğu sapkın (kabul) edecek değildir. Şüphesiz ki Allah her şeyi bilendir."},{"n":116,"t":"Göklerin ve yerin otoritesi yalnızca Allah’a aittir. Diriltir ve öldürür. Sizin için Allah’a rağmen dost da yardımcı da yoktur."},{"n":117,"t":"Şüphesiz ki Allah içlerinden bir grubun kalpleri eğrilmeye yüz tuttuktan sonra, Peygamber’in ve güçlük zamanında ona uyan muhacirlerin ve ensarın tevbesini kabul etmiştir. Sonra da onların tevbelerini kabul etmiştir. Şüphesiz ki O, onlara karşı çok şefkatlidir, çok merhametlidir."},{"n":118,"t":"(Allah, Tebük Gazvesi’nden) geri bırakılan üç kişinin de (tevbelerini kabul etmişti). Yeryüzü (bütün) genişliğine rağmen onlara dar gelmiş, vicdanları kendilerini sıktıkça sıkmıştı. Allah’tan yine yalnızca Allah’a sığınmaktan başka çare olmadığını anlamışlardı. Sonra tevbe etmeleri (eski düzgün hallerine dönmeleri) için Allah onların tevbesini kabul etmiştir. Şüphesiz ki yalnızca Allah tevbeyi çok kabul edendir, çok merhametlidir."},{"n":119,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun ve doğrularla birlikte olun!"},{"n":120,"t":"Medine halkının ve civarlarındaki göçebe Arapların Allah’ın Elçisinden geri kalmaları ve onun canından (önce) kendi canlarını düşünmeleri doğru olmaz. İşte onların Allah yolunda bir susuzluğa, yorgunluğa ve açlığa uğramaları, kâfirleri öfkelendirecek bir yere (ayak) basmaları ve düşmana karşı bir başarı kazanmaları da sadece bunların karşılığında kendilerine iyi bir iş yazılması içindir. Şüphesiz ki Allah güzel davrananların ödülünü ziyan etmez."},{"n":121,"t":"Küçük büyük yaptıkları her bir infak ve geçtikleri her bir vadi mutlaka onların lehine yazılır. Sonunda, Allah onları yapmakta olduklarının en güzeli ile ödüllendirecektir."},{"n":122,"t":"Müminlerin hepsinin toptan çıkmaları (çıkıp gelmeleri) doğru değildir. Her birinden (her toplumdan) bir grup dinde derin anlayış sahibi olmak ve sakınırlar ümidiyle kendilerine döndüklerinde toplumlarını uyarmak için nefer olmalıdır (yola çıkmalıdır)."},{"n":123,"t":"Ey iman edenler! kâfirlerden yakınınızda olanlara karşı savaşın ve onlar (savaş anında) sizde bir sertlik bulsunlar! Bilin ki Allah şüphesiz ki muttakîlerle (duyarlı olanlarla) beraberdir."},{"n":124,"t":"Herhangi bir sure indirildiği zaman içlerinden bir kısmı “Bu, sizin hanginizin imanını artırdı ki?” der. İman edenler var ya, (indirilen her sure) onların imanlarını artırır ve onlar sevinirler."},{"n":125,"t":"Kalplerinde hastalık bulunanlara gelince, onların da inkârlarını tamamen artırır ve onlar artık kâfir olarak ölürler."},{"n":126,"t":"Onlar, her yıl bir veya iki kez (çeşitli belâlarla) imtihan edildiklerini görmüyorlar mı? Sonra tevbe de etmiyorlar, (gerçeği) de hatırlamıyorlar."},{"n":127,"t":"Bir sure indirildiği zaman “(Çevreden) sizi birisi görüyor mu?” diye (sorar gibi) birbirlerine bakar, sonra da (sıvışıp) giderler. Anlamayan bir topluluk oldukları için Allah da onların kalplerini (gerçeklerden) uzaklaştırmıştır."},{"n":128,"t":"Şüphesiz ki size kendinizden öyle bir Elçi gelmiştir ki sıkıntıya uğramanız ona çok ağır gelir. Size çok düşkündür; müminlere karşı elbette çok şefkatlidir, merhametlidir."},{"n":129,"t":"(İnkârcılar) yüz çevirirlerse de ki: “Bana yalnızca Allah yeter. O’ndan başka ilah yoktur. Ben yalnızca O’na güvendim. O yüce arşın sahibidir.”"}],[{"n":1,"t":"Elif. Lâm. Râ. İşte şu(nlar), doğru hükümler içeren Kitabın ayetleridir."},{"n":2,"t":"İçlerinden bir adama “İnsanları uyar ve iman edenlere, Rableri katında onlar için (yüksek) bir doğruluk makamı olduğunu müjdele!” diye vahyetmemiz insanlar için şaşılacak bir şey mi oldu ki o kâfirler “Bu elbette apaçık bir büyücüdür” dediler!"},{"n":3,"t":"Şüphesiz ki Rabbiniz, gökleri ve yeri altı günde (dönemde) yaratan, sonra da her işi düzenleyip yöneterek arşa istiva eden Allah’tır. O’nun izni olmadan kimse şefaatçi olamaz. İşte O Rabbiniz Allah’tır. O’na kulluk edin! (Gerçeği) hatırlamıyor musunuz?"},{"n":4,"t":"Allah’ın gerçek bir vaadi olarak hepinizin dönüşü yalnızca O’nadır. Şüphesiz ki O, yaratılanları önce (yoktan) yaratır; sonra da iman edip iyi işler yapanlara adaletle karşılık vermek için (onları mahşerde) yeniden yaratır. Kâfir olanlara gelince, inkar ettiklerinden dolayı onlar için kaynar sudan bir içecek ve elem verici bir azap vardır."},{"n":5,"t":"Güneşi ışık kaynağı, ayı da parlak kılan, yılların sayısını ve hesabı bilmeniz için ona (aya) birtakım evreler belirleyen O’dur. Allah bunları ancak bir amaçla yaratmıştır. Bilen bir kavme ayetlerini açıklamaktadır."},{"n":6,"t":"Şüphesiz ki gece ve gündüzün değişmesinde, Allah’ın göklerde ve yerde yarattığı şeylerde takvâlı (duyarlı) bir toplum için dersler vardır."},{"n":7,"t":"Bizimle karşılaşacaklarını ummayanlar, dünya hayatına razı olup onunla huzur bulanlar ve ayetlerimizden habersizmiş gibi davrananlar var ya,"},{"n":8,"t":"İşte kazanmakta oldukları (günahlar) yüzünden onların barınağı ateştir!"},{"n":9,"t":"İman edip iyi işler yapanlara gelince, Rableri onları imanları sebebiyle doğru yola ulaştırır. Nimetlerle dolu cennetlerde altlarından ırmaklar akar."},{"n":10,"t":"Onların oradaki duası şudur: “Ey Allah’ım! Sen yücesin!” Orada birbirlerine esenlik dilekleri ise ‘selam’dır. Dualarının sonu da “Hamd (övgü), âlemlerin Rabbi olan Allah içindir.” şeklindedir."},{"n":11,"t":"Allah (inkârcı) insanlara, hayrı acele istedikleri gibi şerri de acele verseydi, elbette onların süreleri bitirilmiş olurdu. Bizimle karşılaşacaklarını ummayanları (ahirete inanmayanları) azgınlıkları içerisinde bocalar hâlde bırakırız."},{"n":12,"t":"(İnkârcı) insana bir sıkıntı dokunduğu zaman, yan yatarak, oturarak veya ayakta durarak bize dua eder. Fakat ondan sıkıntısını kaldırınca, sanki kendisine dokunan bir sıkıntı yüzünden bize yalvarmamış gibi geçip gider. İşte böylece yapmakta oldukları şeyler haddi aşanlara güzel gösterilmiştir."},{"n":13,"t":"Yemin olsun ki haksızlık ettikleri için sizden önce nice nesilleri helak etmiştik. Elçileri kendilerine apaçık deliller getirmiş, (ancak) onlar iman etmemişlerdi. İşte suçlu toplumları böyle cezalandırırız."},{"n":14,"t":"Sonra da nasıl davranacağınızı görmemiz için onların ardından sizi yeryüzünde halifeler (sorumlular) olarak görevlendirdik."},{"n":15,"t":"Onlara ayetlerimiz açıkça tilavet edildiği (okunup aktarıldığı) zaman, (öldükten sonra) bizimle karşılaşmayı ummayanlar (ahirete inanmayanlar), “Ya bundan başka bir Kur’an getir veya bunu değiştir!” dediler. De ki: “Onu kendiliğimden değiştirmem benim için olacak şey değildir. Ben, bana vahyolunandan başkasına uymam. Rabbime isyan edersem elbette büyük günün azabından korkarım.”"},{"n":16,"t":"De ki: “Allah dileseydi onu size tilavet edemezdim (okuyup aktaramazdım); (Allah da) onu size bildirmezdi. Ben bundan önce bir ömür içinizde kalmıştım. Akıl etmiyor musunuz?”"},{"n":17,"t":"Allah’a yalan uyduran veya O’nun ayetlerini yalanlayandan daha zalim kim olabilir ki! Şüphesiz ki suçlular kurtulamazlar!"},{"n":18,"t":"Onlar Allah’ın peşi sıra kendilerine zarar da yarar da sağlamayacak şeylere tapıyorlar ve “Bunlar, Allah katında bizim şefaatçilerimizdir.” diyorlar. De ki: “Siz Allah’a göklerde ve yerde bilemeyeceği bir şeyi mi bildiriyorsunuz! O, onların ortak koştuklarından yüce ve uzaktır.”"},{"n":19,"t":"İnsanlar sadece tek bir ümmetti; sonradan ayrılığa düştüler. Rabbinden bir söz geçmemiş olsaydı, ayrılığa düştükleri konuda aralarında elbette (hemen) hüküm verilirdi."},{"n":20,"t":"“Ona (Muhammed’e) Rabbinden bir ayet (mucize) indirilse ya!” diyorlar. De ki: “Gayb (bilinemeyen her şey) yalnızca Allah’ın kontrolündedir. Bekleyin! Şüphesiz ki ben de sizinle birlikte bekleyenlerdenim.”"},{"n":21,"t":"Kendilerine dokunan bir sıkıntıdan sonra o (nankör) insanlara bir merhamet tattırdığımız zaman, bir de bakarsın ki ayetlerimiz hakkında bir tuzak (kurmuşlar). De ki: “Allah’ın tuzağı daha hızlıdır.” Şüphesiz ki elçilerimiz (meleklerimiz) kurduğunuz tuzakları yazıyorlar."},{"n":22,"t":"Sizi karada ve denizde yürüten (gezdiren) O’dur. Hatta siz gemilerde bulunduğunuz, gemiler de içindekileri tatlı bir rüzgârla alıp götürdüğü ve (yolcular) bu yüzden neşelendikleri zaman, ona (gemiye) şiddetli bir fırtına gelip çatar; her yerden onlara dalgalar hücum eder ve onlar çepeçevre kuşatıldıklarını anlarlar da işte o zaman, dini yalnız O’na (Allah’a) özgü kılarak “Bizi bundan kurtarırsan elbette şükredenlerden olacağız” diye Allah’a yalvarırlar."},{"n":23,"t":"(Allah) kendilerini kurtarınca bir de bakarsın ki onlar yeryüzünde haksız yere taşkınlık ediyorlar. Ey insanlar! Sizin taşkınlığınız dünya hayatının menfaatini elde etmek üzere ancak kendi aleyhinizedir. Sonunda dönüşünüz sadece bizedir. Yaptıklarınızı size bildireceğiz."},{"n":24,"t":"Dünya hayatının durumu, gökten indirdiğimiz bir su gibidir ki insanların ve hayvanların yiyeceklerinden olan yer bitkileri o (su) sayesinde (gürleşip) birbirine karışır. Sonunda yeryüzü, süsünü takınıp (rengârenk) zinetlendiği ve sahipleri de onun üzerinde güç sahibi olduklarını sandıkları sırada, bir gece veya gündüz ona (azap) emrimiz gelir de onu sanki dün (orada bir zenginlik) yokmuş gibi hasat edilmiş bir hale getiririz. Düşünen bir toplum için ayetlerimizi ayrıntılı bir şekilde işte böyle açıklıyoruz."},{"n":25,"t":"Allah kullarını barış yurduna (cennete) çağırıyor ve dileyeni (layık gördüğünü) doğru yola ulaştırıyor."},{"n":26,"t":"Güzel davrananlara daha güzel karşılık, bir de fazlası vardır. Onların yüzlerine herhangi bir toz (leke) ve aşağılanma bulaşmaz. İşte onlar cennet halkıdır; orada ebedî kalacaklardır."},{"n":27,"t":"Kötülük yapanlara gelince, herhangi bir kötülüğün karşılığı misli iledir. Onları aşağılanma kaplayacaktır. Kendilerini Allah’tan (gelecek herhangi bir cezaya karşı) koruyacak kimse de yoktur. Onların yüzleri sanki karanlık geceden bir parçaya bürünmüştür. İşte onlar da ateş halkıdır; orada ebedî kalacaklardır."},{"n":28,"t":"Onların hepsini bir araya toplayacağımız, sonra da (Allah’a) ortak koşmuş olanlara “Siz ve koştuğunuz ortaklar, yerinizde bekleyin!” diyeceğimiz gün artık onların (putlarıyla) aralarını tamamen ayırmışız (olacağız). Onların ortakları şöyle diyecektir: “Siz bize ibadet etmiyordunuz."},{"n":29,"t":"Bu yüzden bizimle sizin aranızda şahit olarak Allah yeter. Şüphesiz ki biz sizin (bize) tapmanızdan tamamen habersizdik.”"},{"n":30,"t":"Orada herkes geçmişte yaptıklarını karşısında bulacaktır. (Artık) onlar gerçek sahipleri olan Allah’a döndürülmüş (olacaklar)dır. Uydurmakta oldukları şeyler (putlar) da onlardan kaybolup gitmiş (olacak)tır."},{"n":31,"t":"De ki: “Size gökten ve yerden kim rızık veriyor? Veya işitme (duyu)suna ve gözlere kim hâkim bulunuyor? Ölüden diriyi kim çıkarıyor; diriden ölüyü kim çıkarıyor? (Her türlü) işi kim idare ediyor?” Hemen “Allah” diyecekler. De ki: “(Hâlâ) takvâlı (duyarlı) olmayacak mısınız?"},{"n":32,"t":"İşte O, sizin gerçek Rabbiniz olan Allah’tır. Artık gerçek(ler)den sonra sapkınlıktan başka ne kalır ki! Nasıl da (sapkınlığa) döndürülüyorsunuz!”"},{"n":33,"t":"İşte böylece Rabbinin “Onlar inanmazlar” şeklinde yoldan çıkanlar hakkındaki sözü gerçekleşmiş oldu."},{"n":34,"t":"De ki: “(Allah’a) ortak koştuklarınız arasında (yoktan) yaratmayı başlatacak, sonra onu (tekrar) iade edebilecek biri var mı?” De ki: “Allah (yoktan) yaratmayı başlatır; sonra onu (tekrar) iade eder. Nasıl oluyor da (gerçeklerden) döndürülüyorsunuz!”"},{"n":35,"t":"De ki: “Ortak koştuklarınızdan gerçeğe ulaştıracak olan var mı?” De ki: “Allah gerçeğe ulaştırır. Gerçeğe ulaştıran mı uyulmaya daha layıktır; yoksa hidayet verilmedikçe kendi kendine doğru yolu bulamayan mı? Ne oluyor size? Nasıl (böyle) hükmediyorsunuz?”"},{"n":36,"t":"Onların çoğu zandan başka bir şeye uymaz. Şüphesiz ki zan, gerçeklik bakımından hiçbir şey ifade etmez. Şüphesiz ki Allah onların yapmakta olduklarını bilendir."},{"n":37,"t":"Bu Kur’an, Allah’ın peşi sıra (varlıklar tarafın)dan (tasarlanıp) uydurulabilecek (bir söz) değildir. Ancak (o) kendinden öncekini doğrulayan ve o Kitab'ı (Tevrat’ı) açıklayandır. Onda şüphe yoktur; o âlemlerin Rabbindendir."},{"n":38,"t":"Yoksa “Onu (Muhammed) uydurdu!” mu diyorlar? De ki: “Doğruysanız Allah’tan başka, gücünüzün yettiklerini çağırın da onun benzeri bir sure getirin!”"},{"n":39,"t":"Aksine onlar bilgisini kavrayamadıkları ve yorumu kendilerine asla gelmemiş olan (Kur’an’ı) yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Şimdi bak, zalimlerin sonu nasıl olmuştu!"},{"n":40,"t":"İçlerinden ona (Kur’an’a) inanan da var; inanmayacak olan da. Rabbin bozguncuları çok iyi bilendir."},{"n":41,"t":"Onlar seni yalanlamaya devam ederlerse, de ki: “Benim işim bana, sizin işiniz de size aittir. Siz benim yaptığımdan uzaksınız; ben de sizin yaptığınızdan uzağım.”"},{"n":42,"t":"Onlardan seni dinleyenler vardır. Fakat kendileri akıl etmiyorlarsa sağırlara sen mi duyuracaksın?"},{"n":43,"t":"Onlardan sana bakan da vardır. Fakat (gerçeği) göremiyorlarsa körleri sen mi doğru yola ulaştıracaksın!"},{"n":44,"t":"Şüphesiz ki Allah insanlara hiçbir şekilde haksızlık etmez fakat insanlar kendilerine haksızlık ederler."},{"n":45,"t":"(Allah) o gün onları, (dünyada) sanki günün ancak aralarında birbirleriyle tanışabilecekleri bir saati kadar kalmış gibi toplayacaktır. Allah ile karşılaşmayı yalanlayıp doğru yola gelmemiş olanlar elbette zarara uğramışlardır."},{"n":46,"t":"Ya onları uyardığımız şeylerin bir kısmını sana gösteririz ya da seni vefat ettiririz. Dönüşleri sadece bizedir. Sonra Allah onların yapmakta olduklarına da şahittir."},{"n":47,"t":"Her ümmetin bir elçisi vardır. Elçileri geldiği zaman, aralarında adaletle hükmedilir ve onlara haksızlık edilmez."},{"n":48,"t":"“Doğruysanız o vaat (Son Saat) ne zamanmış!” derler."},{"n":49,"t":"De ki: “Allah’ın dilemesi hariç, kendime herhangi bir zarar veya yarar sağlayacak güce sahip değilim.” Her ümmetin bir süresi vardır. Süreleri geldiği zaman artık ne bir saat (bir an) geri kalabilir ne de ileri gidebilirler."},{"n":50,"t":"De ki: “Hiç düşündünüz mü O’nun azabı size geceleyin veya gündüzün gelirse (ne yaparsınız)!” Suçlular bunun hangisini istemekte acele ediyorlar!"},{"n":51,"t":"(Azap) başınıza geldikten sonra mı ona inanmış (olacak)sınız? Şimdi mi (iman ettiniz)? Onu (azabı) istemekte acele ediyordunuz!"},{"n":52,"t":"Sonra (kendilerine) haksızlık edenlere “Ebedî azabı tadın!” denmiş (olacak)tır. Kazanmakta olduğunuzdan başkasının karşılığını mı bulacaksınız?"},{"n":53,"t":"(Bazı inkârcılar) “O (azap) gerçek midir?” diye senden haber bekliyorlar. De ki: “Evet, Rabbime yemin olsun: Şüphesiz ki o gerçektir ve siz asla (O’nu) aciz bırakıcılar değilsiniz.”"},{"n":54,"t":"Haksızlık eden kişi yeryüzündeki (her şeye) sahip olsaydı (azaptan kurtulmak için) elbette onu fidye olarak verirdi. Azabı gördüklerinde, pişmanlık gizlemiş (veya pişmanlıklarını açıklamış) olacaklardır. Aralarında adaletle hükmedilecektir ve kendilerine haksızlık edilmeyecektir."},{"n":55,"t":"Dikkat edin! Göklerde ve yerde olan her şey yalnızca Allah’a aittir. Dikkat edin! Allah’ın vaadi gerçektir fakat onların çoğu bilmez."},{"n":56,"t":"O, diriltir, öldürür; yalnızca O’na döndürüleceksiniz."},{"n":57,"t":"Ey insanlar! Elbette size Rabbinizden bir öğüt, göğüslerdeki (kalplerdeki inançsızlığa) bir şifa, müminler için bir rehber ve rahmet gelmiştir."},{"n":58,"t":"De ki: “Ancak Allah’ın lütfu ve merhametiyle, işte bunlarla sevinsinler! Bu, onların (dünya malı olarak) topladıklarından daha hayırlıdır.”"},{"n":59,"t":"De ki: “Allah’ın size indirdiği rızıktan (bir kısmını) helâl, (bir kısmını da) haram kıldığınızı gördünüz mü?” De ki: “Allah mı size izin verdi, yoksa Allah’a iftira mı ediyorsunuz?”"},{"n":60,"t":"Allah’a yalan uyduranların kıyamet günü hakkındaki kanaati nedir? Şüphesiz ki Allah insanlara karşı lütuf sahibidir. Fakat onların çoğu şükretmezler."},{"n":61,"t":"Her ne işte bulunsan, o işle ilgili Kur’an’dan her ne tilâvet edersen (okuyup aktarsan) ve siz her ne iş yapıyorsanız o işe daldığınız zaman biz mutlaka üstünüzde şahidiz. Yerde de gökte de zerre ağırlığınca bir şey Rabbinden uzak (ve gizli) kalmaz. Bundan daha küçük ve daha büyük (hiçbir şey) yoktur ki apaçık bir kitapta (ilahi kanunda) bulunmasın."},{"n":62,"t":"Dikkat edin! Allah’ın dostlarına korku yoktur; onlar üzülmeyecek de."},{"n":63,"t":"Onlar, iman edip takvâlı olanlardır."},{"n":64,"t":"Dünya hayatında da ahirette de müjde onlarındır. Allah’ın sözlerinde asla değişme yoktur. Asıl büyük kurtuluş işte budur."},{"n":65,"t":"Onların (inkârcıların) sözleri seni üzmesin! Şüphesiz ki itibar bütünüyle Allah’a aittir. O, duyandır, bilendir."},{"n":66,"t":"Dikkat edin! Göklerde ve yerde kim varsa (hepsi) yalnızca Allah’a aittir. Allah’ın peşi sıra ortaklara yalvaranlar neyin peşine düşüyorlar! Onlar, zandan başka bir şeye uymuyorlar ve onlar yalandan başka bir şey de söylemiyorlar."},{"n":67,"t":"O, içinde dinlenesiniz diye sizin için geceyi yaratan, (çalışıp kazanmanız için de) gündüzü aydınlık kılandır. Şüphesiz ki bunda, dinleyen bir toplum için dersler vardır."},{"n":68,"t":"(Müşrikler:) “Allah çocuk edindi!” dediler. (Haşa)! O yücedir. O, (gerçek) zengindir. Göklerde ve yerde ne varsa yalnızca O’na aittir. Bu konuda yanınızda herhangi bir delil yoktur. Allah hakkında bilmediğiniz şeyleri mi söylüyorsunuz?"},{"n":69,"t":"De ki: “Allah’a yalan uyduranlar kurtulamazlar.”"},{"n":70,"t":"Dünyada bir miktar geçim (sağlarlar); sonra dönüşleri sadece bizedir; ardından da inkâr etmekte oldukları şeyler nedeniyle onlara şiddetli azabı tattırırız."},{"n":71,"t":"Onlara Nuh’un haberini tilavet et (okuyup aktar)! Hani o, kavmine şöyle demişti: “Ey kavmim! Benim konumum ve Allah’ın ayetlerini hatırlatmam size ağır geldi ise –ki ben yalnızca Allah’a güvenirim–; siz de ortaklarınızla birlikte işinizle ilgili olarak toplanın! Sonra işiniz başınıza dert olmasın! Bundan sonra (vereceğiniz) hükmü bana uygulayın ve bana zaman da tanımayın!"},{"n":72,"t":"Yüz çevirirseniz, ben sizden hiçbir ücret istememiştim. Benim ücretim yalnızca Allah’a aittir. Bana da müslümanlardan olmam emredilmiştir.”"},{"n":73,"t":"(Yine de) onu yalanlamışlardı. Biz de hem onu hem de onunla birlikte gemide bulunanları kurtarmış ve onları (yeryüzünde) halifeler (sorumlular olarak) görevlendirmiştik. Ayetlerimizi yalanlayanları da (denizde) boğmuştuk. Bak ki uyarılanların (fakat inanmayanların) sonu nasıl olmuş!"},{"n":74,"t":"Sonra onun arkasından elçileri kendi toplumlarına göndermiştik. Onlara deliller getirmişlerdi. Fakat onlar daha önce yalanladıkları şeye inanacak değillerdi. İşte haddi aşanların kalplerini biz böyle mühürleriz."},{"n":75,"t":"Sonra onların ardından da Musa ile Harun’u delillerimizle Firavun’a ve yöneticilerine göndermiştik; (fakat) onlar kibirlenmiş ve suçlu bir toplum olmuşlardı."},{"n":76,"t":"Katımızdan onlara gerçek (bilgi) gelince “Elbette bu, apaçık bir büyüdür!” demişlerdi."},{"n":77,"t":"Musa “Size gerçek (bilgi) geldiğinde onun için ‘Bu bir büyü müdür? (Hep böyle mi) dersiniz? (Oysa) büyücüler başarılı olamazlar!” diye sormuştu."},{"n":78,"t":"Onlar “Babalarımızı üzerinde bulduğumuz (dinden) bizi döndüresin ve yeryüzünde yücelik sizin ikinizin olsun diye mi bize geldin? Biz size asla inanacak değiliz.” demişlerdi."},{"n":79,"t":"Firavun şöyle demişti: “Bilgili bütün büyücüleri bana getirin!”"},{"n":80,"t":"Büyücüler gelince Musa onlara “Ne atacaksanız atın!” demişti."},{"n":81,"t":"Onlar (iplerini) atınca Musa şunu söylemişti: “Sizin getirdiğiniz şey (bilinen bir) büyüdür. Şüphesiz ki Allah onu boşa çıkaracaktır.” Şüphesiz ki Allah bozguncuların işini düzeltmez."},{"n":82,"t":"Suçluların hoşuna gitmese de Allah sözleriyle gerçeği açığa çıkaracaktır."},{"n":83,"t":"Firavun ve yöneticilerinin kendilerine fitne (sıkıntı) vermelerinden korkmaları nedeniyle, kavminden bir grup insandan başka kimse Musa’ya iman etmemişti. Şüphesiz ki Firavun yeryüzünde kibirlenen biriydi ve elbette o, haddi aşanlardandı."},{"n":84,"t":"Musa şöyle demişti: “Ey kavmim! Allah’a inandıysanız, O’na teslim olduysanız yalnızca O’na güvenin!”"},{"n":85,"t":"Onlar da şöyle demişlerdi: “Yalnızca Allah’a güvendik. Rabbimiz! Bizi zalimler topluluğu için deneme konusu kılma!"},{"n":86,"t":"Bizi merhametinle o kâfirler topluluğundan kurtar!”"},{"n":87,"t":"Biz de Musa ve kardeşine “Kavminiz için şehirde evler hazırlayın! Evlerinizi kıble yapın! Namazınızı da doğru kılın! (Ey Musa)! Müminleri müjdele!” diye vahyetmiştik."},{"n":88,"t":"Musa şöyle demişti: “Rabbimiz! Şüphesiz ki sen Firavun ve yöneticilerine dünya hayatında ziynet ve mallar verdin. Rabbimiz! (Onlara bu nimetleri) insanları senin yolundan saptırsınlar (diye mi verdin?) Rabbimiz! Onların mallarını sil, kalplerine sıkıntı ver! Onlar o elem verici azabı görünceye kadar iman etmeyecekler.”"},{"n":89,"t":"(Allah) “İkinizin duasına da elbette cevap verilmiştir. Siz doğru yolda olun ve o (gerçekleri) bilmeyenlerin yoluna uymayın!” demişti."},{"n":90,"t":"Biz İsrailoğullarını denizden geçirmiştik de Firavun ve askerleri haksızlık etmek ve saldırmak üzere onları takip etmişti. Sonunda (denizde) boğulma zamanı gelince (Firavun) “İsrailoğullarının inandığı ilahtan başka ilah olmadığına ben de iman ettim. Ben de müslümanlardanım!” demişti."},{"n":91,"t":"(Ona şöyle denmişti): “Şimdi mi (iman ettin)! (Oysa) daha önce isyan etmiş ve bozgunculardan olmuştun.”"},{"n":92,"t":"Senden sonra geleceklere bir ibret olması için bugün senin bedenini (cansız olarak) kurtaracağız. Şüphesiz ki insanlardan birçoğu delillerimizden habersizmiş gibi davranır."},{"n":93,"t":"Yemin olsun ki biz İsrailoğullarını güzel bir yurda yerleştirmiştik ve onlara temiz nimetlerden rızık vermiştik. Kendilerine ilim gelinceye kadar ayrılığa düşmemişlerdi. Şüphesiz ki Rabbin, anlaşmazlığa düştüğü şeyler hakkında kıyamet günü aralarında hükmedecektir."},{"n":94,"t":"Sana indirdiğimizden şüphedeysen, senden önce Kitab'ı (Tevrat’ı) okuyanlara sor! Şüphesiz ki Rabbinden sana gerçek (bilgi) gelmiştir. Sakın şüphelenenlerden olma!"},{"n":95,"t":"Allah’ın ayetlerini yalanlayanlardan da olma; sonra kaybedenlerden olursun."},{"n":96,"t":"Şüphesiz ki haklarında Rabbinin sözü (hükmü) gerçekleşenler inanmazlar."},{"n":97,"t":"Kendilerine her bir delil gelmiş olsa bile elem verici azabı görünceye kadar (inanmayacaklardır)."},{"n":98,"t":"Yunus’un kavmi hariç, herhangi bir şehir (halkı), keşke iman etmiş olsaydı da bu imanları kendilerine yarar sağlasaydı! (Yunus’un kavmi) iman edince, kendilerinden dünya hayatındaki rezillik azabını kaldırmış ve onları bir süre (daha) yararlandırmıştık."},{"n":99,"t":"Rabbin dileseydi yeryüzündekilerin hepsi elbette iman ederlerdi. (Şimdi) sen inanmaları için insanları zorlayacak mısın!"},{"n":100,"t":"Allah’ın izni olmadan kimse inanamaz. Akıllarını kullanmayanlara pislik verir (yağdırır)."},{"n":101,"t":"De ki: “Göklerde ve yerde neler var, bakın!” İnanmayacak bir topluma deliller ve uyarılar yarar sağlamaz."},{"n":102,"t":"Onlar, kendilerinden önce geçmiş toplumların (felaket) günlerinin benzerlerinden başkasını mı bekliyorlar? De ki: “Bekleyin! Şüphesiz ki ben de sizinle birlikte bekleyenlerdenim.”"},{"n":103,"t":"Sonra biz elçilerimizi ve iman edenleri kurtarırız. İşte böylece, üzerimize bir borç olarak inananları kurtaracağız."},{"n":104,"t":"104-105 De ki: “Ey insanlar! Benim (tebliğ ettiğim) dinimden şüphedeyseniz, ben Allah’ın peşi sıra tapmakta olduklarınıza tapmam. Ancak sizi öldürecek olan Allah’a taparım. Bana müminlerden olmam ve ‘hanîf (Allah’ı birleyen) olarak yüzünü dine çevir; sakın müşriklerden olma!’ diye emredildi.”"},{"n":105,"t":"104-105 De ki: “Ey insanlar! Benim (tebliğ ettiğim) dinimden şüphedeyseniz, ben Allah’ın peşi sıra tapmakta olduklarınıza tapmam. Ancak sizi öldürecek olan Allah’a taparım. Bana müminlerden olmam ve ‘hanîf (Allah’ı birleyen) olarak yüzünü dine çevir; sakın müşriklerden olma!’ diye emredildi.”"},{"n":106,"t":"Allah’ın peşi sıra sana yarar da zarar da veremeyecek şeylere yalvarma! Bunu yaparsan, o takdirde şüphesiz ki zalimlerden olursun."},{"n":107,"t":"Allah sana bir sıkıntı dokundurursa, onu O’ndan başka açıp (giderecek) yoktur. Sana bir iyilik dilerse, lütfunu geri çevirebilecek de yoktur. Onu kullarından dilediğine (layık olana) ulaştırır. O çok bağışlayandır, çok merhametlidir."},{"n":108,"t":"De ki: “Ey insanlar! Rabbinizden size elbette gerçek gelmiştir. Kim doğru yola gelirse yalnızca kendisi için gelmiş olur; kim de saparsa sadece kendi aleyhine sapmış olur. Ben sizin üzerinize asla vekil (güven kaynağı) değilim.”"},{"n":109,"t":"Sana vahyolunana uy ve Allah (aranızda) hükmedinceye kadar sabret! O, hüküm verenlerin en iyisidir."}],[{"n":1,"t":"1-2 Elif. Lâm. Râ. (Bu), Allah’tan başkasına ibadet etmemeniz için doğru hüküm veren, her şeyden haberdar olan (Allah) tarafından ayetleri sağlamlaştırılmış, sonra da açıkça ortaya konulmuş bir kitaptır. (De ki:) “Şüphesiz ki ben O’nun tarafından size (gönderilmiş) bir uyarıcı ve müjdeleyiciyim."},{"n":2,"t":"1-2 Elif. Lâm. Râ. (Bu), Allah’tan başkasına ibadet etmemeniz için doğru hüküm veren, her şeyden haberdar olan (Allah) tarafından ayetleri sağlamlaştırılmış, sonra da açıkça ortaya konulmuş bir kitaptır. (De ki:) “Şüphesiz ki ben O’nun tarafından size (gönderilmiş) bir uyarıcı ve müjdeleyiciyim."},{"n":3,"t":"(Bu kitap) Rabbinizden bağışlanma dilemeniz, sonra da ona tevbe etmeniz (yönelmeniz) için (indirildi) ki (Allah) sizi belirlenmiş bir süreye kadar güzel bir şekilde yaşatsın ve iyilik sahibi olan her bir kişiye de iyiliğinden (daha çok) versin. Yüz çevirirseniz, size gelecek büyük bir günün azabından korkarım.”"},{"n":4,"t":"Dönüşünüz yalnızca Allah’adır. O, her şeye gücü yetendir."},{"n":5,"t":"Dikkat edin! Onlar, O’ndan (Allah’ın gözetiminden) gizlemeleri için göğüslerini çevirirler. Dikkat edin! Onlar elbiselerine büründükleri zaman bile (Allah) onların gizlediklerini de açığa çıkardıklarını da bilir. Şüphesiz ki O, göğüslerin (kalplerin) özünü bilendir."},{"n":6,"t":"Yeryüzünde hiçbir canlı yoktur ki rızkı yalnızca Allah’a ait olmasın. (Allah) onun durduğu ve sonunda bırakılacağı mekânı bilir. (Bunların) hepsi apaçık bir kitaptadır."},{"n":7,"t":"O, hanginizin davranış olarak daha güzel olacağını denemek için arşı su üzerindeyken gökleri ve yeri altı günde (dönemde) yaratandır. “Ölümden sonra şüphesiz ki diriltileceksiniz!” desen, kâfir olanlar elbette “Bu, apaçık büyüden başka bir şey değildir!” derler."},{"n":8,"t":"Onlardan azabı sayılı (belirli) bir süreye kadar ertelesek, mutlaka “Onu(n gelmesini) engelleyen nedir?” derler. Dikkat edin! Kendilerine azap geldiği gün, bir daha onlardan uzaklaştırılacak değildir. Alay etmekte oldukları şey, onları çepeçevre kuşatmış (olacak)tır."},{"n":9,"t":"O insana tarafımızdan bir rahmet tattırır da sonra bunu ondan çekip alırsak, (bu durumda) şüphesiz ki o tamamen ümitsiz, nankör olur."},{"n":10,"t":"Kendisine dokunan bir zarardan sonra ona bir nimet tattırırsak, elbette “Kötülükler benden gitti.” der. Şüphesiz ki o, çok şımarıktır, çok kibirlidir."},{"n":11,"t":"Ancak sabredip güzel işler yapanlar başka. İşte onlar için bağışlanma ve büyük bir ödül vardır."},{"n":12,"t":"Neredeyse sen (müşriklerin) “Ona (gökten) bir hazine indirilseydi veya onunla birlikte bir melek gelseydi ya!” demeleri yüzünden sana vahyolunan ayetlerin bir kısmını terk edeceksin ve (bu yüzden) ruhun daralacak. Sen sadece bir uyarıcısın. Allah her şeye vekildir (güven kaynağıdır)."},{"n":13,"t":"Yoksa “Onu (Muhammed) uydurdu” mu diyorlar? De ki: “Doğruysanız Allah’tan başka, gücünüzün yettiklerini çağırın da onun benzeri uydurulmuş on sure getirin!”"},{"n":14,"t":"Size cevap veremezseler, bilin ki (Kur’an) ancak Allah’ın ilmiyle indirilmiştir ve O’ndan başka ilah yoktur. Artık siz müslüman oluyor musunuz?"},{"n":15,"t":"Kim dünya hayatını ve süsünü isterse, işlerinin karşılığını orada onlara tam olarak veririz ve orada onlar hiçbir zarara uğratılmazlar."},{"n":16,"t":"İşte onlar, ahirette kendileri için ateşten başka hiçbir şey olmayanlardır. (Dünyada) yaptıkları boşa gitmiştir; yapmakta oldukları şeyler de batıldır."},{"n":17,"t":"Rabbi tarafından apaçık bir delil üzere olan ve kendisini O’ndan (Rabbinden) bir şahidin tilavet (takip) ettiği, ayrıca kendisinden önce önder ve rahmet olarak Musa’nın Kitabı (elinde) bulunan kimse (inkârcılar gibi) midir? Bunlar, ona (Kur’an’a) inanırlar. O gruplardan hangisi onu inkâr ederse işte cehennem ateşi onun varacağı yerdir. Bundan şüphen olmasın! Şüphesiz ki bu, Rabbin tarafından (bildirilmiş) gerçektir fakat insanların çoğu inanmazlar."},{"n":18,"t":"Allah’a yalan uydurandan daha zalim kim olabilir ki! Onlar (mahşerde) Rablerine sunulacaklar; şahitler de “İşte bunlar, Rablerine karşı yalan uyduranlardır!” diyeceklerdir. Dikkat edin! Allah’ın laneti, o zalimlerin üzerinedir!"},{"n":19,"t":"Onlar, (insanları) Allah’ın yolundan alıkoyan ve o (yol)u eğri gösterenlerdir. Onlar -evet onlar- ahireti de inkâr edenlerdir."},{"n":20,"t":"Onlar yeryüzünde (Allah’ı) aciz bırakacak değillerdir; onların Allah’tan başka dostları da yoktur. Azap onlar için katlanacaktır. (Çünkü) onlar (gerçekleri) duymaya güç yetiremez ve (onları) göremezler."},{"n":21,"t":"İşte onlar kendilerine yazık etmişlerdir ve uydurdukları şeyler (putlar) da kendilerinden kaybolup gitmiş olacaktır."},{"n":22,"t":"Şüphesiz ki onlar ahirette en çok kaybedenlerdir."},{"n":23,"t":"Şüphesiz ki iman edip iyi işler yapanlara ve Rablerine gönülden boyun eğenlere gelince, işte onlar cennet halkıdır. Onlar orada ebedî kalacaklardır."},{"n":24,"t":"Bu iki grubun (müminlerle kâfirlerin) durumu, kör ve sağır ile gören ve duyan kişiler(in farkı) gibidir. Bunlar, örnek olarak hiç eşit olur mu! (Hâlâ gerçeği) hatırlamıyor musunuz?"},{"n":25,"t":"Yemin olsun ki Nuh’u elçi olarak kavmine göndermiştik de onlara “Şüphesiz ki ben sizin için apaçık bir uyarıcıyım."},{"n":26,"t":"Allah’tan başkasına kulluk etmeyin! Şüphesiz ki ben size (gelecek) elem verici bir günün azabından korkuyorum.” (demişti)."},{"n":27,"t":"Kavminden kâfir olan yöneticiler şöyle demişlerdi: “Biz seni bizim gibi bir insandan başka bir şey olarak görmüyoruz. İçimizden, basit görüşlü, en rezillerimizden başkasının da sana uyduğunu görmüyoruz. Sizin bize karşı hiçbir üstünlüğünüzü de görmüyoruz. Aksine sizin yalancılar olduğunuzu sanıyoruz.”"},{"n":28,"t":"(Nuh onlara) şöyle demişti: “Ey kavmim! Bir düşünsenize! Ben Rabbim tarafından apaçık bir delil üzerinde isem ve O bana kendi katından bir rahmet vermiş de bu size gizli tutulmuşsa (siz kendinizi buna kapattıysanız) buna ne dersiniz? Onu istemediğiniz hâlde biz (beraberimdekiler) sizi ona zorlayacak mıyız?"},{"n":29,"t":"Ey kavmim! Buna (tebliğe) karşılık sizden herhangi bir mal istemiyorum. Benim ödülüm yalnızca Allah’a aittir. Ben iman edenleri kovacak değilim. Şüphesiz ki onlar, Rablerine kavuşacaklardır. Fakat ben sizi, bilgisizce davranan bir topluluk olarak görüyorum."},{"n":30,"t":"Ey kavmim! Ben onları kovarsam, beni Allah’tan kim koruyabilir ki! Hiç (gerçeği) hatırlamıyor musunuz?"},{"n":31,"t":"Ben size ‘Allah’ın hazineleri benim yanımdadır’ demiyorum; gaybı (bilinemeyeni) de bilemem. ‘Ben bir meleğim’ de demiyorum. Gözlerinizin hor gördüğü kişiler için ‘Allah onlara asla bir hayır vermeyecektir’ diyemem. Kalplerinde olanı Allah çok iyi bilendir. (Onları kovduğum) takdirde doğrusu ben zalimlerden olurum.”"},{"n":32,"t":"Onlar “Ey Nuh! Bizimle mücadele ettin ve bize karşı mücadelede çok ileri gittin. Doğrulardansan bize vadettiğini bize getir!” demişlerdi."},{"n":33,"t":"(Nuh ise) şöyle demişti: “Dilerse onu size ancak Allah getirir. Siz (Allah’ı) asla aciz bırakacak değilsiniz."},{"n":34,"t":"Allah sizi saptırmak (sapkınlık kararınızı onaylamak) istiyorsa, ben size öğüt vermek istesem de öğüdüm size yarar sağlamaz. (Çünkü) O, sizin Rabbinizdir; yalnızca O’na döndürüleceksiniz.”"},{"n":35,"t":"Yoksa “Onu (Muhammed) uydurdu!” mu diyorlar? De ki: “Ben onu uydurursam günahım bana aittir. Ben de sizin işlediğiniz günahtan uzağım.”"},{"n":36,"t":"(Tarafımızdan) Nuh’a şöyle vahyedilmişti: “Kavminden iman etmiş olanlardan başkası artık (sana) asla inanmayacak. Onların işlemekte olduklarından dolayı üzülme!"},{"n":37,"t":"Gözlerimizin önünde ve vahyimiz (emrimiz) uyarınca gemiyi yap! Haksızlık edenler hakkında bana (herhangi bir şey) söyleme! Şüphesiz ki onlar mutlaka boğulacaklardır.”"},{"n":38,"t":"(Nuh) gemiyi yapıyor, kavminden yöneticiler ise yanına her uğradıklarında onunla alay ediyorlardı. (Nuh onlara) şöyle demişti: “Bizimle alay ediyorsanız, sizin alay edişiniz gibi ileride biz de sizinle alay edeceğiz!”"},{"n":39,"t":"Kendisini rezil edecek azabın kime geleceğini ve kalıcı bir azabın kime konacağını ileride bileceksiniz."},{"n":40,"t":"Sonunda emrimiz gelip de tandır kaynayınca (Nuh’a) şöyle demiştik: “Her tür (canlı)dan iki çift ile –içlerinden (boğulacağına dair) aleyhinde söz geçen(ler) dışında- aileni ve iman etmiş olan(lar)ı ona (gemiye) bindir!” (Nitekim) onunla birlikte çok az (kişi)den başkası iman etmemişti."},{"n":41,"t":"(Nuh) şöyle demişti: “Gemiye binin! Onun yüzüp gitmesi de durması da Allah’ın adıyladır. Şüphesiz ki Rabbim çok bağışlayandır, çok merhametlidir.”"},{"n":42,"t":"Gemi, dağlar gibi dalga(lar) arasında onları götürüyor(du). Nuh bir kenarda olan oğluna “Ey yavrucuğum! Bizimle birlikte (gemiye) bin; kâfirlerle olma!” diye seslenmişti."},{"n":43,"t":"(Oğlu) “Beni sudan koruyacak bir dağa sığınacağım.” demişti. (Nuh) “Bugün Allah’ın (azap) emrinden, merhamet eden (Allah)tan başka koruyacak kimse yoktur.” demişti. (Ardından) aralarına dalga girmiş ve (oğlu) boğulanlardan olmuştu."},{"n":44,"t":"“Ey yer, suyunu yut (çek)! Ey gök, (suyunu) tut (dindir)!” denmiş, su çekilmiş, iş bitirilmişti. (Gemi) Cûdî (dağı)nın üzerine yerleşmişti. O zalimler topluluğuna “(Merhametten) uzak olun!” denmişti."},{"n":45,"t":"Nuh, Rabbine şöyle seslenmişti: “Rabbim! Şüphesiz ki oğlum da ailemdendir. Senin vaadin elbette gerçektir. Sen hüküm verenlerin en isabetli hüküm verenisin.”"},{"n":46,"t":"(Allah) şöyle demişti: “Ey Nuh! O asla senin ailenden (destekçilerinden) değildir; şüphesiz ki o (yaptığı) kötü bir iştir. Hakkında bilgin olmayanı benden isteme! Şüphesiz ki cahillerden olma(ma)n konusunda sana öğüt veriyorum.”"},{"n":47,"t":"(Nuh) şöyle demişti: “Rabbim! Senden hakkında bilgim olmayanı istemekten sana sığınırım. Beni bağışlamaz ve merhamet etmezsen kaybedenlerden olurum!”"},{"n":48,"t":"(Nuh’a) şöyle denmişti: “Ey Nuh! Sana ve seninle birlikte olan ümmetlere bizden bir selam ve pek çok bereketle (gemiden) in! Kendilerini yararlandıracağımız, sonra da bizden kendilerine elem verici bir azabın dokunacağı ümmetler de olacaktır.”"},{"n":49,"t":"İşte şu(nlar), sana vahyettiğimiz gayb (bilinemeyen) haberlerindendir. Bundan önce onları ne sen biliyordun ne de kavmin. Sabret! Şüphesiz ki (mutlu) son, muttakîler (duyarlı olanlar) içindir."},{"n":50,"t":"Âd (kavmine) de kardeşleri Hud’u (göndermiştik ve onlara) şöyle demişti: “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. Siz yalan uyduranlardan başkası değilsiniz."},{"n":51,"t":"Ey kavmim! Buna karşılık sizden ücret istemiyorum. Benim ücretim, beni yoktan yaratandan başkasına ait değildir. Akıl etmiyor musunuz?"},{"n":52,"t":"Ey kavmim! Rabbinizden bağışlanma dileyin! Sonra da O’na tevbe edin (yönelin) ki üzerinize göğü (yağmuru) bol bol göndersin ve gücünüze güç katsın. Suç işleyerek (Allah’tan) yüz çevirmeyin!”"},{"n":53,"t":"(Kavmi) şöyle demişti: “Ey Hud! Sen bize apaçık bir delil getirmedin; biz de senin sözünle ilahlarımızı asla terk edecek değiliz ve biz sana asla iman edecek değiliz."},{"n":54,"t":"54-55 Biz ‘İlahlarımızdan biri seni fena hâlde çarpmış!’ demekten başka bir söz söylemiyoruz.” (Hud ise) şöyle demişti: “Ben Allah’ı şahit tutuyorum; siz de şahit olun ki ben O’nun peşi sıra ortak koştuklarınızdan uzağım. Hepiniz bana tuzak kurun; sonra da bana zaman tanımayın!"},{"n":55,"t":"54-55 Biz ‘İlahlarımızdan biri seni fena hâlde çarpmış!’ demekten başka bir söz söylemiyoruz.” (Hud ise) şöyle demişti: “Ben Allah’ı şahit tutuyorum; siz de şahit olun ki ben O’nun peşi sıra ortak koştuklarınızdan uzağım. Hepiniz bana tuzak kurun; sonra da bana zaman tanımayın!"},{"n":56,"t":"Ben, benim de Rabbim, sizin de Rabbiniz olan Allah’a güvendim. Hiçbir canlı yoktur ki O, onun perçeminden tutmuş olmasın. Şüphesiz ki Rabbim doğru yoldadır."},{"n":57,"t":"Yüz çevirirseniz, elbette ben benimle size gönderileni size bildirdim. Rabbim (dilerse) sizden başka bir kavmi yerinize getirebilir ve siz O’na hiçbir şekilde zarar veremezsiniz. Şüphesiz ki benim Rabbim her şeyi koruyup gözetendir.”"},{"n":58,"t":"(Azap) emrimiz gelince Hud’u ve onunla birlikte iman edenleri tarafımızdan bir merhametle kurtarmıştık. Biz onları ağır bir azaptan kurtarmıştık."},{"n":59,"t":"İşte şu, Âd (kavmi)dir: Rablerinin ayetlerini inkâr etmişler, (Allah’ın) elçilerine asi olmuşlar ve inatçı her zorbanın emrine uymuşlardı."},{"n":60,"t":"Onlar hem bu dünyada hem de kıyamet gününde lanete tabi tutulmuşlardı. Dikkat edin! Âd (kavmi) Rablerini inkâr etmişlerdi. Dikkat edin! Hud’un kavmi olan Âd, (Allah’ın merhametinden) uzak kılınmıştı."},{"n":61,"t":"Semûd (kavmine) de kardeşleri Salih’i (göndermiştik). “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. O sizi yerden (topraktan) yaratmış ve sizi orada yaşatmıştı. O’ndan bağışlanma dileyin; sonra da O’na tevbe edin! Şüphesiz ki Rabbim (kullarına) yakındır; (dualarına) karşılık verendir.” demişti."},{"n":62,"t":"(Kavmi ise) şöyle demişti: “Ey Salih! Elbette sen bundan önce içimizde ümit beslenen birisiydin. (Şimdi) babalarımızın taptıklarına tapmaktan bizi engelliyor musun? Şüphesiz ki bizi kendisine (kulluğa) çağırdığın şeyden kuşkulandıran bir şüphe içindeyiz.”"},{"n":63,"t":"(Salih onlara) şöyle demişti: “Ey kavmim! Bir düşünsenize! Ben Rabbim tarafından apaçık bir delil üzerinde isem ve O bana kendinden bir rahmet vermiş ise (hâliniz nasıl olacak?) O’na asi olursam, beni Allah’tan (O’nun azabından) kim koruyabilir ki! (O zaman) siz de kaybımı artırmaktan başka bir şey yapmamış olurdunuz."},{"n":64,"t":"Ey kavmim! İşte Allah’ın şu devesi sizin için bir delildir. Onu bırakın da Allah’ın (yarattığı bu) toprakta yesin (otlasın). Ona hiçbir kötülük etmeyin! Yoksa sizi yakın bir azap yakalar.”"},{"n":65,"t":"(Fakat Semûd kavmi) onu (deveyi) hunharca katledince (Salih onlara) şöyle demişti: “Yurdunuzda üç gün daha yaşayın (sonra helak olacaksınız)!” Bu, yalanlanamayacak bir vaattir."},{"n":66,"t":"(Kendilerine azap) emrimiz gelince, Salih’i ve onunla birlikte iman edenleri tarafımızdan bir merhametle (helakten) ve o günün rezilliğinden kurtarmıştık. Şüphesiz ki Rabbin kuvvetlidir, güçlüdür."},{"n":67,"t":"67-68 Haksızlık edenleri de o korkunç ses yakalamış ve sanki orada hiç oturmamışlar gibi yurtlarında diz üstü (hareketsiz) kalmışlardı. Dikkat edin! Şüphesiz ki Semûd (kavmi) Rablerini inkâr etmişlerdi. Dikkat edin! Semûd kavmi (Allah’ın merhametinden) uzak kılınmıştı."},{"n":68,"t":"67-68 Haksızlık edenleri de o korkunç ses yakalamış ve sanki orada hiç oturmamışlar gibi yurtlarında diz üstü (hareketsiz) kalmışlardı. Dikkat edin! Şüphesiz ki Semûd (kavmi) Rablerini inkâr etmişlerdi. Dikkat edin! Semûd kavmi (Allah’ın merhametinden) uzak kılınmıştı."},{"n":69,"t":"Yemin olsun ki (melek) elçilerimiz İbrahim’e müjde getirmiş ve “Selam (sana)!” demişler, o da “(Size de) selam!” demiş ve çok geçmeden kızartılmış bir buzağı getirmişti."},{"n":70,"t":"Ellerini yemeğe uzatmadıklarını görünce, onları yadırgamış ve onlardan dolayı içine bir korku düşmüştü. (Elçiler de ona) “Korkma! Biz Lut kavmine gönderildik.” demişlerdi."},{"n":71,"t":"(O esnada) hanımı (Sâre) ayaktaydı ve (bu sözleri duyunca) gülmüştü. Ona da İshak’ı, İshak’ın ardından da Yakup’u müjdelemiştik."},{"n":72,"t":"(Sâre) “Aa, vay başıma gelenler! Ben bir yaşlı, bu kocam da bir ihtiyarken çocuk mu doğuracağım? Şüphesiz ki bu şaşılacak bir şey!” demişti."},{"n":73,"t":"(Melekler şu) cevabı vermişlerdi: “Allah’ın emrine şaşıyor musun? Ey ev halkı! Allah’ın merhameti ve bereketleri sizin üzerinizdedir. Şüphesiz ki O övülmeye layıktır, yücedir.”"},{"n":74,"t":"İbrahim’den korku gidip kendisine müjde gelince, Lut kavmi hakkında (âdeta) bizimle mücadeleye başlamıştı."},{"n":75,"t":"Şüphesiz ki İbrahim, çok hoşgörülü, çok yufka yürekli, (Allah’a) yönelmiş (biriydi)."},{"n":76,"t":"(Melekler) şöyle demişlerdi: “Ey İbrahim! Bundan vazgeç! Çünkü Rabbinin (azap) emri elbette gelmiştir. Şüphesiz ki onlara geri döndürülemez bir azap gelecektir!”"},{"n":77,"t":"Elçilerimiz Lut’a gelince, (Lut) onların yüzünden üzülmüş ve onlardan dolayı içi daralmıştı da “Bu, zor bir gündür.” demişti."},{"n":78,"t":"(Lut’un) kavmi, koşarak onun yanına gelmişlerdi. Daha önce de o kötü işleri yapmaktalardı. (Lut, kavmine) şöyle demişti: “Ey kavmim! İşte şunlar kızlarımdır (onlarla evlenin)! Sizin için onlar daha temizdir. Allah’a karşı takvâlı (duyarlı) olun ve misafirlerimin önünde beni rezil etmeyin! İçinizde hiç mi aklı başında bir adam yok!”"},{"n":79,"t":"(Kavmi) “Senin kızlarında bizim herhangi bir hakkımız olmadığını bilirsin. Sen bizim ne istediğimizi elbette biliyorsun!” demişlerdi."},{"n":80,"t":"(Lut) “Keşke benim size karşı (koyacak) bir gücüm olsaydı veya güçlü bir kaleye sığınabilseydim!” demişti."},{"n":81,"t":"(Bunun üzerine melekler) şöyle demişti: “Ey Lut! Biz Rabbinin elçileriyiz. Onlar sana asla dokunamazlar. Sen gecenin bir kısmında ailenle (yola çıkıp) yürü! Hanımından başka sizden hiçbiri geride kalmasın! Çünkü onlara gelecek olan (azap), şüphesiz ki ona da isabet edecektir. Onlara vadolunan (helak) zamanı sabah vaktidir. Sabah yakın değil mi?”"},{"n":82,"t":"82-83 (Azap) emrimiz gelince, oranın üstünü altına getirmiş ve üzerlerine Rabbin katında işaretlenerek (balçıktan) pişirilip istif edilmiş taşlar yağdırmıştık. Onlar (işaretli taşlar), zalimlerden uzak değildir."},{"n":83,"t":"82-83 (Azap) emrimiz gelince, oranın üstünü altına getirmiş ve üzerlerine Rabbin katında işaretlenerek (balçıktan) pişirilip istif edilmiş taşlar yağdırmıştık. Onlar (işaretli taşlar), zalimlerden uzak değildir."},{"n":84,"t":"Medyen’e de kardeşleri Şuayb’ı (göndermiştik; onlara) şöyle demişti: “Ey kavmim, Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. Ölçüyü ve tartıyı eksik yapmayın! Şüphesiz ki ben sizi hayır (bolluk) içinde görüyorum. Şüphesiz ki ben sizin için kuşatıcı bir günün azabından korkuyorum."},{"n":85,"t":"Ey kavmim! Ölçüyü ve tartıyı adaletle tam yapın! İnsanlara eşyalarını eksik vermeyin! Yeryüzünde bozguncular olarak karışıklık çıkarmayın!"},{"n":86,"t":"Müminseniz Allah’ın (helalinden) bıraktığı (kâr) sizin için hayırlı olandır. Ben üzerinize asla bekçi değilim.”"},{"n":87,"t":"(Medyenliler Şuayb’a) şöyle demişlerdi: “Ey Şuayb! Babalarımızın taptıklarını (putları) veya mallarımız hakkında dilediğimizi yapmayı terketmemizi sana salâtın (ibadetin) mi emrediyor? Şüphesiz ki sen çok hoşgörülüsün; akıllısın!”"},{"n":88,"t":"(Şuayb ise onlara) şöyle demişti: “Ey kavmim! Bir düşünsenize! Ben Rabbim tarafından apaçık bir delil üzerinde isem ve O bana kendi katından güzel bir rızık vermişse (hâliniz nasıl olacak?) Sizi yasakladığım şeylerin tersini yaparak size (olan sözüme) aykırı davranmak istemiyorum. Ben gücümün yettiği kadar ıslah etmekten başka bir şey istemiyorum. Başarmam ancak Allah’ın yardımı iledir. Yalnız O’na güvendim ve yalnız O’na yöneleceğim."},{"n":89,"t":"Ey kavmim! Sakın bana karşı düşmanlığınız, Nuh’un kavmi veya Hud’un kavmi veya Salih’in kavminin başına gelenler gibi size de bir musibet getirmesin! (Zaten) Lut kavmi de sizden uzak değildir."},{"n":90,"t":"Rabbinizden bağışlanma dileyin; sonra O’na tevbe edin (yönelin)! Şüphesiz ki Rabbim çok merhametlidir; (müminleri) çok sevendir.”"},{"n":91,"t":"(Medyenliler) şöyle demişti: “Ey Şuayb! Söylediklerinin çoğunu anlamıyoruz ve içimizde seni cidden zayıf görüyoruz! Kabilen olmasaydı seni mutlaka kovardık. Sen asla bize göre güçlü değilsin.”"},{"n":92,"t":"(Şuayb ise onlara) şöyle demişti: “Ey kavmim! Size göre benim kabilem, Allah’tan daha mı güçlü ki O’nu arkanıza atıp unuttunuz. Şüphesiz ki Rabbim, yapmakta olduklarınızı kuşatıcıdır."},{"n":93,"t":"Ey kavmim! Bulunduğunuz yerde (elinizden geleni) yapın! Şüphesiz ki ben de (görevimi) yapacağım! Kendisini rezil edecek azabın kime geleceğini ve yalancının kim olduğunu ileride öğreneceksiniz! Gözetleyin! Şüphesiz ki ben de sizinle birlikte gözetlemekteyim!”"},{"n":94,"t":"94-95 (Azap) emrimiz gelince, Şuayb’ı ve onunla birlikte iman edenleri tarafımızdan bir merhametle (azaptan) kurtarmıştık. Haksızlık edenleri de o korkunç ses yakalamış ve sanki orada hiç oturmamışlar gibi yurtlarında diz üstü (hareketsiz) kalmışlardı. Dikkat edin! Semûd (kavmi Allah’ın merhametinden) uzak olduğu gibi Medyen (kavmi) de uzak kılınmıştı."},{"n":95,"t":"94-95 (Azap) emrimiz gelince, Şuayb’ı ve onunla birlikte iman edenleri tarafımızdan bir merhametle (azaptan) kurtarmıştık. Haksızlık edenleri de o korkunç ses yakalamış ve sanki orada hiç oturmamışlar gibi yurtlarında diz üstü (hareketsiz) kalmışlardı. Dikkat edin! Semûd (kavmi Allah’ın merhametinden) uzak olduğu gibi Medyen (kavmi) de uzak kılınmıştı."},{"n":96,"t":"96-97 Yemin olsun ki Musa’yı da ayetlerimizle ve apaçık bir delille Firavun’a ve onun yöneticilerine göndermiştik. Onlar, Firavun’un emrine uymuşlardı. (Oysa) Firavun’un emri asla doğru değildi."},{"n":97,"t":"96-97 Yemin olsun ki Musa’yı da ayetlerimizle ve apaçık bir delille Firavun’a ve onun yöneticilerine göndermiştik. Onlar, Firavun’un emrine uymuşlardı. (Oysa) Firavun’un emri asla doğru değildi."},{"n":98,"t":"(Firavun), kıyamet gününde kavminin önüne düşecek ve onları ateşe sürükleyecektir. Varılacak o yer ne kötü bir yerdir!"},{"n":99,"t":"Onlar burada (dünyada) da kıyamet gününde de lanete uğratıldılar. (Onlara) verilen bu armağan ne kötü armağandır!"},{"n":100,"t":"İşte bu, (halkı helak olmuş) şehirlerin haberlerindendir. Biz onu sana anlatıyoruz. Onlardan (izleri) kalan da vardır; biçilmiş (ekin gibi yok olan) da."},{"n":101,"t":"Onlara biz haksızlık etmemiştik; fakat, onlar kendilerine haksızlık etmişlerdi. Rabbinin (azap) emri geldiğinde, Allah’ın peşi sıra yalvardıkları ilahları onlardan hiçbir (sıkıntı) giderememişti. (Putlar onların) kayıplarından başka bir şey artırmamıştı."},{"n":102,"t":"Haksızlık eden şehirleri(n halkını helak için) yakaladığında, Rabbinin yakalayışı işte böyle (şiddetli)dir. Şüphesiz ki O’nun yakalaması elem vericidir; şiddetlidir!"},{"n":103,"t":"Şüphesiz ki bunda, ahiret azabından korkanlar için elbette ayet (ders) vardır. O gün, bütün insanların bir araya toplandığı bir gündür ve o gün (herkes için) şahit kılınmış bir gündür."},{"n":104,"t":"Biz onu (kıyamet gününü) sadece (belirlenmiş) sayılı bir süre için ertelemekteyiz."},{"n":105,"t":"O geldiği gün O’nun (Allah’ın) izni olmadan kimse konuşamaz. Onlardan kimi azgındır, kimi mutlu."},{"n":106,"t":"Azgın olanlar ateştedir; orada onların (öyle feci) bir nefes alıp vermeleri vardır ki!"},{"n":107,"t":"Rabbinin dilemesi hariç, gökler ve yer durdukça orada ebedî kalacaklardır. Şüphesiz ki Rabbin istediğini yapandır."},{"n":108,"t":"Mutlu kılınanlara gelince, onlar da cennettedir. Rabbinin dilemesi hariç, gökler ve yer durdukça bitmez bir lütuf olarak onlar da orada ebedî kalacaklardır."},{"n":109,"t":"Onların tapmakta oldukları şeylerle ilgili şüphen olmasın! Onlar daha önce babalarının taptığından başka bir şekilde tapmıyorlar. Biz onların (azaptan) paylarını mutlaka eksiksiz olarak vereceğiz."},{"n":110,"t":"Yemin olsun ki biz Musa’ya da Kitabı vermiştik fakat onda anlaşmazlığa düşülmüştü. Rabbinden bir söz geçmemiş olsaydı, elbette aralarında hüküm verilirdi. Şüphesiz ki onlar (Mekkeliler) de ondan (Kur’an’dan) kuşkulandıran bir şüphe içindedir."},{"n":111,"t":"Onların her birinin işlerinin (karşılığını Rabbin) kendilerine elbette tam olarak verecektir. Şüphesiz ki O, onların yapmakta olduklarından haberdardır."},{"n":112,"t":"Seninle birlikte tevbe edenlerle birlikte emrolunduğun gibi doğru ol! Aşırıya kaçmayın! O, sizin yaptıklarınızı elbette görendir."},{"n":113,"t":"Haksızlık edenlere eğilim göstermeyin; ateş size de dokunur. Allah’ın peşi sıra dostlarınız (da) olmaz. Sonra size yardım da edilmez."},{"n":114,"t":"Gündüzün iki bölümünde (öğle ve ikindi) ve gecenin de (gündüze) yakın bölümlerinde (akşam, yatsı ve sabah) namaz kıl! Şüphesiz ki iyilikler kötülükleri giderir. Bu, (gerçeği) hatırlamak isteyenlere bir hatırla(t)madır."},{"n":115,"t":"Sabırlı ol! Şüphesiz ki Allah güzel davrananların ödülünü ziyan etmez."},{"n":116,"t":"Sizden önceki nesillerden yeryüzünde (insanları) bozgunculuktan alıkoyacak değerli (bilge) kişiler bulunsaydı ya! Fakat onlardan görevlerini yapan, kurtardığımız az bir kısmı hariç (diğerleri görevlerini yapmamışlardı). Haksızlık edenler ise kendilerine verilen refahın peşine düşmüşlerdi; zaten onlar suça dalan kişilerdi."},{"n":117,"t":"Halkı ıslah ediciler olduğu hâlde, Rabbin haksızlıkla şehirleri (halkları) helak etmez."},{"n":118,"t":"Rabbin dileseydi bütün insanları tek bir ümmet yapardı. (Fakat) onlar anlaşmazlığa düşmeye devam ederler."},{"n":119,"t":"Ancak Rabbinin merhamet ettikleri hariçtir. Zaten (Rabbin) onları bunun için yaratmıştır. Rabbinin, “Şüphesiz ki cehennemi bütünüyle insanlar ve cinlerle dolduracağım!” sözü yerini bulmuş (olacak)tır."},{"n":120,"t":"Elçilerin haberlerinden senin kalbini pekiştireceğimiz her şeyi sana anlatıyoruz. Bunlarda sana gerçeğin bilgisi, müminlere de bir öğüt ve (gerçeği) hatırlatıcı (mesaj) gelmiştir."},{"n":121,"t":"İman etmeyenlere de ki: “Bulunduğunuz yerde (elinizden geleni) yapın! Şüphesiz ki biz de (görevimizi) yapacağız!"},{"n":122,"t":"Bekleyin! Şüphesiz ki biz de bekleyenleriz.”"},{"n":123,"t":"Göklerin ve yerin gaybı (bilinemeyeni) yalnızca Allah’a aittir. Her iş yalnızca O’na döndürülür. Öyle ise O’na kulluk et ve O’na güven! Rabbin yaptıklarınızdan asla habersiz değildir."}],[{"n":1,"t":"Elif. Lâm. Râ. İşte şu(nlar), apaçık Kitabın ayetleridir."},{"n":2,"t":"Şüphesiz ki biz akıl edesiniz diye onu Arapça bir Kur’an olarak indirdik."},{"n":3,"t":"Biz sana bu Kur’an’ı vahyetmekle (eskilere dair) haberleri sana en güzel şekilde anlatıyoruz. Elbette sen bundan önce habersizlerdendin."},{"n":4,"t":"Hani Yusuf, babasına (Yakup’a) şöyle demişti: “Ey Babacığım! Şüphesiz ki ben (rüyamda) on bir gezegeni, güneşi ve ayı gördüm; onları benim için secde ederlerken gördüm.”"},{"n":5,"t":"(Babası ona) “Ey yavrucuğum! Rüyanı kardeşlerine anlatma; sonra sana bir tuzak kurarlar! Şüphesiz ki şeytan, insana apaçık bir düşmandır.” demişti."},{"n":6,"t":"İşte böylece Rabbin seni seçecek; sana (rüyada gördüğün) olayların yorumunun bir kısmını öğretecek ve daha önceki iki atan İbrahim ve İshak’a nimetini tamamladığı gibi sana ve Yakup soyuna da nimetini tamamlayacaktır. Şüphesiz ki Rabbin bilendir, doğru hüküm verendir."},{"n":7,"t":"Şüphesiz ki Yusuf ve kardeşlerinde, (almak) isteyenler için dersler vardır."},{"n":8,"t":"Hani (kardeşleri) şöyle demişlerdi: “Biz (kalabalık) bir topluluk olmamıza rağmen Yusuf ile kardeşi (Bünyamin) babamıza bizden daha sevgilidir. Şüphesiz ki babamız apaçık bir şaşkınlık içindedir."},{"n":9,"t":"Yusuf’u öldürün veya onu (uzak) bir yere bırakın ki babanızın ilgisi yalnız size kalsın! Ondan sonra da (tevbe ederek) iyi kişiler olursunuz!”"},{"n":10,"t":"İçlerinden biri “Yusuf’u öldürmeyin; (mutlaka bir şey) yapacaksanız onu o kuyunun görünmeyen yerine bırakın da kervanlardan biri onu alsın.” demişti."},{"n":11,"t":"(Kardeşler babalarına) şöyle demişti: “Ey babamız! Sana ne oluyor da Yusuf hakkında bize güvenmiyorsun? Oysa biz onun için samimi olanlarız."},{"n":12,"t":"Yarın onu bizimle birlikte gönder de bol bol gezsin, oynasın! Biz onu mutlaka koruruz.”"},{"n":13,"t":"(Babaları) “Onu götürmeniz şüphesiz ki beni üzer. Siz ondan habersizken onu bir kurdun yemesinden korkarım.” demişti."},{"n":14,"t":"(Kardeşler) şöyle demişti: “Gerçekten biz (kalabalık) bir topluluk olduğumuz hâlde onu kurt yerse, o zaman biz kaybedenler oluruz.”"},{"n":15,"t":"Onu götürüp de o kuyunun görünmeyen yerine bırakmaya birlikte karar verdikleri zaman, (Yusuf’a) “Şüphesiz ki sen onlar farkına varamadan onların bu işlerini kendilerine bildireceksin.” diye vahyetmiştik (bildirmiştik)."},{"n":16,"t":"(Oğulları) yatsı vakti ağlayarak babalarına gelmişlerdi:"},{"n":17,"t":"“Ey babamız! Biz Yusuf’u eşyamızın yanında bırakmış bir şekilde yarışmak üzere (yanından) uzaklaşmıştık. (Ne yazık ki) kurt onu yemiş! Fakat biz doğru söyleyenler olsak da sen asla bize inanmazsın.”"},{"n":18,"t":"Gömleğinin üzerinde sahte bir kan ile (Yusuf’un kanlı gömleğiyle) gelmişlerdi. (Yakup onlara) şöyle demişti: “Hayır! Nefisleriniz sizi (kötü) bir işe sürüklemiş. Artık (bana düşen) güzelce sabretmektir. Anlattığınız şeyler karşısında yardımına sığınılacak olan Allah’tır.”"},{"n":19,"t":"Bir kervan gelmiş ve sucularını (kuyuya) göndermişler, o da kovasını (kuyuya) salmıştı. (Yusuf’u görünce) “Aa, müjde! İşte bir erkek çocuk!” demişti. Onu bir ticaret için saklamışlardı. Allah onların yaptıklarını bilendir."},{"n":20,"t":"(Kafile Mısır’a vardığında) onu basit bir değere, sayılı birkaç dirheme satmışlardı. Onlar ona değer vermeyenlerdendiler."},{"n":21,"t":"Mısır’da onu satın alan kişi, hanımına şöyle demişti: “Ona değer ver (güzel bak)! Belki bize yararı olur veya onu evlat ediniriz.” İşte böylece kendisine (rüyadaki) olayların yorumunu öğretmemiz için Yusuf’u o yere (Mısır’a) yerleştirmiştik. Allah işinde üstündür. Fakat insanların çoğu bilmezler."},{"n":22,"t":"(Yusuf) yetişkinlik çağına ulaşınca, ona doğru hüküm verme yeteneği ve ilim vermiştik. Güzel davrananları biz işte böyle ödüllendiririz."},{"n":23,"t":"Evinde bulunduğu kadın, (cinsel olarak) ondan yararlanmak istemiş, kapıları kilitlemiş ve “Haydi gel!” demişti. O da “Allah’a sığınırım! Şüphesiz ki o (eşiniz) benim efendimdir; bana güzel davrandı.” demişti. Gerçek şu ki zalimler başarılı olmaz!"},{"n":24,"t":"Yemin olsun ki kadın ona eğilim göstermişti. Rabbinin delilini görmeseydi o da kadına eğilim göster(ecek)ti. İşte böylece biz kötülük ve çirkinliği ondan uzaklaştırmak için (delilimizi göstermiştik). Şüphesiz ki o, samimi kullarımızdandı."},{"n":25,"t":"İkisi de kapıya doğru koşmuş ve o (Züleyha) onun (Yusuf’un) gömleğini arkadan yırtmıştı. Kapının yanında onun efendisine (kocasına) rastlamışlardı. (Züleyha eşine) şöyle demişti: “Senin ailene (eşine) kötülük etmek isteyenin cezası, hapsedilmekten veya elem verici bir azaptan başka ne olabilir ki!”"},{"n":26,"t":"(Yusuf) “(Asıl) kendisi cinsel olarak benden yararlanmak istedi!” demişti. Onun (kadının) tarafından bir şahit (bilirkişi) şöyle şahitlik etmişti: “Gömleği önden yırtılmışsa, kadın doğru söylemiştir; o (Yusuf) ise yalancılardandır."},{"n":27,"t":"(Yok) gömleği arkadan yırtılmışsa, kadın yalan söylemiştir; o (Yusuf) ise doğru söyleyenlerdendir.”"},{"n":28,"t":"(Aziz, Yusuf’un) gömleğinin arkadan yırtılmış olduğunu görünce, (eşine) “Şüphesiz ki bu, sizin tuzaklarınızdandır; şüphesiz ki sizin tuzağınız büyüktür.” demişti."},{"n":29,"t":"(Aziz şöyle demişti): “Yusuf! Sen bundan (bu işi sürdürmekten) vazgeç! (Ey Züleyha)! Sen de günahından dolayı bağışlanma dile! Şüphesiz ki sen günahkârlardan oldun.”"},{"n":30,"t":"Şehirdeki bazı kadınlar şöyle demişti: “Aziz’in hanımı cinsel olarak delikanlısından yararlanmak istiyormuş. (Yusuf’un) sevdası onu tamamen kaplamış! Doğrusu biz onu apaçık bir şaşkınlık içinde görüyoruz.”"},{"n":31,"t":"(Züleyha) onların dedikodusunu duyunca, onlara (davetçi) göndermiş, onlar için dayanacak yastıklar (iyi bir sofra ortamı) hazırlamış, her birine bir bıçak vermiş, (Yusuf’a da): “Çık karşılarına!” demişti. (Kadınlar) onu görünce, onu (gözlerinde) büyütmüş, (şaşkınlıklarından) ellerini kesmişler ve şöyle demişlerdi: “Haşa, Rabbimiz! Bu, bir insan olamaz. Bu ancak değerli bir melektir!”"},{"n":32,"t":"(Züleyha) şöyle demişti: “İşte hakkında beni kınadığınız (şahıs) budur. Yemin olsun ki ben (cinsel olarak) ondan yararlanmak istedim; o, masumdu. Şüphesiz ki kendisine emredeceğimi yapmazsa mutlaka hapse atılacak ve elbette aşağılananlardan olacaktır!”"},{"n":33,"t":"(Yusuf:) “Rabbim! Hapis, bunların benden istediklerinden bana daha sevimlidir! Onların hilelerini benden çevirmezsen onlara eğilim gösterir ve cahillerden olurum!” demişti."},{"n":34,"t":"Rabbi onun duasına cevap vermiş ve onların hilesini ondan uzaklaştırmıştı. Şüphesiz ki yalnızca O duyandır, bilendir."},{"n":35,"t":"Sonunda kesin delilleri görmelerine rağmen onu bir süreliğine mutlaka hapse atmaları (gerektiği fikri), onlar (Aziz ve arkadaşları) için belirmişti."},{"n":36,"t":"Onunla birlikte hapse iki delikanlı daha girmişti. Onlardan biri “Ben kendimi (rüyamda) içki için (üzüm) sıktığımı görüyorum.” demişti. Diğeri de “Ben de kendimi başımın üzerinde kuşların yemekte (gagalamakta) olduğu bir ekmek taşıdığımı görüyorum.” demişti. “Bunun yorumunu bize bildir! Çünkü biz seni güzel davrananlardan görüyoruz.” (demişlerdi)."},{"n":37,"t":"(Yusuf ise onlara) şöyle demişti: “Size verilecek yemek gelmeden önce, onun (gördüğünüz rüyaların) yorumunu mutlaka size bildireceğim. Bu, Rabbimin bana öğrettiklerindendir. Şüphesiz ki ben Allah’a inanmayan bir kavmin milletinden (dininden) uzaklaştım. Onlar, ahireti inkâr edenlerin ta kendileridir."},{"n":38,"t":"Atalarım İbrahim, İshak ve Yakup’un milletine (dinine) uydum. Allah’a herhangi bir şeyi ortak koşmamız bize yakışmaz. Bu, Allah’ın bize ve insanlara olan lütfundandır. Fakat insanların çoğu şükretmezler."},{"n":39,"t":"Ey iki hapis arkadaşım! Çeşitli rabler mi hayırlıdır yoksa ezici güç sahibi olan tek bir Allah mı?"},{"n":40,"t":"(Allah’ın) peşi sıra taptıklarınız, haklarında Allah’ın hiçbir delil indirmediği, sizin ve atalarınızın taktığı isimlerden başka bir şey değildir. Hüküm yalnızca Allah’a aittir. O, size kendisinden başkasına ibadet etmemenizi emretmiştir. İşte doğru din budur fakat insanların çoğu (bu gerçeği) bilmezler."},{"n":41,"t":"Ey iki hapis arkadaşım! (Rüyalarınıza gelince), biriniz (eskisi gibi) efendisine içki içirecek; diğeri ise asılacak ve kuşlar onun başından (beynini) yiyecekler. Yorumunu sorduğunuz iş (bu şekilde) kesinleşmiştir.”"},{"n":42,"t":"O iki (arkadaş)ından, kurtulacağını bildiği kişiye “Beni efendinin yanında an.” demişti.” Fakat şeytan ona, efendisine anmayı unutturmuştu. Dolayısıyla (Yusuf), birkaç sene daha hapiste kalmıştı."},{"n":43,"t":"Hükümdar şöyle demişti: “Ben (rüyada) yedi zayıf (ineğin) yediği yedi besili inek ile yedi yeşil başak ve diğerlerini de kuru görüyorum. Ey yöneticiler! Rüya yorumluyorsanız, benim rüyamı da yorumlayın!"},{"n":44,"t":"Onlar şöyle demişlerdi: “Bunlar karmakarışık rüyalardır. Biz böyle rüyaların yorumunu bilenler değiliz.”"},{"n":45,"t":"(Hapisteki) iki kişiden, kurtulmuş olan, uzun bir zaman sonra (Yusuf’u) hatırlayarak: “Ben size onun yorumunu bildiririm; beni hemen (Yusuf’a) gönderin.” demişti."},{"n":46,"t":"“Ey Yusuf, ey doğru sözlü kişi! (Rüyada görülen) yedi zayıf ineğin yediği yedi besili inek ile yedi yeşil başak ve diğerleri de kuru olan (başaklar) hakkında bize yorum yap! Ümit ederim ki insanlara (yorumunla) dönerim de belki onlar da (gerçeği) öğrenirler.” (demişti)."},{"n":47,"t":"(Yusuf ise) şöyle demişti: “Yedi sene âdetiniz üzere ekin ekeceksiniz. (Sonra da) yiyeceklerinizden az bir miktar hariç, biçtiklerinizi başağında bırakınız!"},{"n":48,"t":"Sonra onun ardından, koruyacaklarınızdan az bir miktar (tohumluk) hariç, biriktirdiklerinizi yiyip (tüketecek) yedi şiddetli (kıtlık yılı) gelecektir."},{"n":49,"t":"Sonra onun ardından da bir yıl gelecek ki o yılda, insanlara (Allah tarafından) yardım edilecek ve o yılda (bolca meyve) sıkacaklar.”"},{"n":50,"t":"Hükümdar “Onu bana getirin!” demişti. Elçi ona geldiğinde (Yusuf) şöyle demişti: “Efendine dön ve ona ‘Ellerini kesen o kadınların derdi neydi?’ diye sor! Şüphesiz ki Rabbim onların hilesini çok iyi bilendir.”"},{"n":51,"t":"(Hükümdar, kadınlara) şöyle demişti: “Yusuf’un nefsinden yararlanmak istediğiniz zaman durumunuz neydi?” Onlar “Haşa! Allah için, biz ondan hiçbir kötülük görmedik.” demişlerdi. Aziz’in hanımı şöyle demişti: “Şimdi gerçek ortaya çıktı. Ben (cinsel olarak) ondan yararlanmak istemiştim. Şüphesiz ki o doğru söyleyenlerdendir.”"},{"n":52,"t":"“Bu (itirafım, Yusuf’un) yokluğunda (o şimdi hapisteyken) ona hainlik etmediğimi ve Allah’ın hainlerin hilesini başarıya ulaştırmayacağını (herkesin) bilmesi içindir."},{"n":53,"t":"Nefsimi temize de çıkarmıyorum. Şüphesiz ki Rabbim merhamet etmemiş olsa, o nefis aşırı şekilde kötülüğü emreder. Şüphesiz ki Rabbim çok bağışlayandır, çok merhametlidir.”"},{"n":54,"t":"Hükümdar şöyle demişti: “Onu (Yusuf’u) bana getirin; onu kendime özel (danışman) yapayım!’ Ona konuşunca “Bugün sen yanımızda yüksek makam sahibisin; güvenilirsin (güvendesin)” demişti."},{"n":55,"t":"(Yusuf) “Beni o yerin (Mısır’ın) hazinelerine (bakan) ata! Şüphesiz ki ben (hazineyi) korurum; (bu işi iyi) bilirim.” demişti."},{"n":56,"t":"Böylece Yusuf’a dilediği gibi hareket etmek üzere o yerde (Mısır’da) yetki vermiştik. Dilediğimiz (layık olan) kimseye rahmetimizi (işte böyle) ulaştırır ve güzel davrananların ödülünü boşa çıkarmayız."},{"n":57,"t":"İman edip takvâlı (duyarlı) olanlar için ahiret ödülü ise hayırlı olandır."},{"n":58,"t":"Yusuf’un kardeşleri gelip huzuruna girmişlerdi. (Yusuf) onları tanımış, onlar ise onu tanımamışlardı."},{"n":59,"t":"(Yusuf) yüklerini hazırlatınca (onlara) şöyle demişti: “(Bir dahaki sefer) baba bir kardeşinizi (Bünyamin’i) de bana getirin! Görmüyor musunuz, ben ölçeği tam dolduruyorum ve misafirperverlerin en iyisiyim."},{"n":60,"t":"Onu bana getirmezseniz, artık benim yanımda size verilecek hiçbir ölçek (tahıl) yoktur; (bu durumda sakın) bana (yanıma) yaklaşmayın!”"},{"n":61,"t":"62 (Yusuf, emrindeki) gençlere demişti ki: “Sermayelerini yüklerinin içine koyun! Olur ki ailelerine döndüklerinde bunun farkına varırlar da belki (tekrar) gelirler.”"},{"n":62,"t":"63 Babalarına döndüklerinde (ona şöyle) demişlerdi: “Ey babamız! Böyle bir ölçek (tahıl verilmesi artık) bize yasaklandı. Kardeşimizi (Bünyamin’i) bizimle birlikte gönder de (onun sayesinde) ölçüp alalım! Biz onu mutlaka koruyacağız.”"},{"n":63,"t":"64 (Yakup, oğullarına) şöyle demişti: “Daha önce kardeşi (Yusuf) hakkında size ne kadar güvendiysem, bunun hakkında da size ancak o kadar güvenirim; Allah en hayırlı koruyucudur. O, merhametlilerin en merhametlisidir.”"},{"n":64,"t":"65 Eşyalarını açtıklarında sermayelerinin kendilerine geri verildiğini görmüş ve şöyle demişlerdi: “Ey babamız! Daha ne istiyoruz! İşte sermayemiz de bize geri verilmiş. (Onunla yine) ailemize yiyecek getiririz; kardeşimizi korur ve bir deve ölçek (tahıl) da fazla alırız. Bu (aldığımız) az bir ölçek (tahıl)dır.”"},{"n":65,"t":"66 (Yakup, oğullarına): “Kuşatılmanız hariç, onu bana mutlaka getireceğinize dair Allah adına bana sağlam bir söz verinceye kadar onu sizinle birlikte asla göndermem!” demişti. Ona (istediği şekilde) güvencelerini verdiklerinde (Yakup) “Söylediklerimize Allah vekildir (şahittir)” demişti."},{"n":66,"t":"67 “Ey oğullarım! (Şehre) hepiniz bir kapıdan girmeyin, ayrı ayrı kapılardan girin! (Ancak) Allah’tan (gelecek) hiçbir şeyi sizden savamam. Hüküm yalnızca Allah’a aittir. (Onun için) ben yalnızca O’na güvendim. Güvenenler yalnız O’na güvensinler!” demişti."},{"n":67,"t":"68 Babalarının kendilerine emrettiği yerden (çeşitli kapılardan) girdiklerinde (onun emrini yerine getirmişlerdi. Fakat bu önlem) Allah’tan gelecek hiçbir şeyi onlardan savamazdı; ancak Yakup’un (oğullarını korumak için) söylemek istediği şeyin yerine getirilmesi (söz konusuydu). Şüphesiz ki o, biz kendisine bildirdiğimiz için bilgi sahibiydi. Fakat insanların çoğu (bu gerçeği) bilmezler."},{"n":68,"t":"69 Yusuf’un yanına girdiklerinde kardeşini (Bünyamin’i) yanına almış ve (Yusuf, ona) “Şüphesiz ki ben senin kardeşinim; yapmış olduklarına üzülme!” demişti."},{"n":69,"t":"70 (Yusuf) onların yükünü hazırlattığında bir su kabını kardeşinin yükünün içine koy(dur)muştu. (Kervan hareket ettikten) sonra bir seslenici: “Ey kervan! Siz hırsızsınız!” diye seslenmişti."},{"n":70,"t":"71 (Yusuf’un kardeşleri) onlara dönerek “Ne arıyorsunuz (neyiniz kayboldu)?” diye sormuşlardı."},{"n":71,"t":"72 (Onlar) “Hükümdarın su kabını arıyoruz; onu getirene bir deve yükü (ödül) var.” demişlerdi. (İçlerinden biri) “Ben buna kefilim.” demişti."},{"n":72,"t":"73 (Onlar) “Allah’a yemin olsun: Bizim, yeryüzünde bozgunculuk çıkarmak için gelmediğimizi şüphesiz ki siz de biliyorsunuz. Biz hırsız da değiliz.” demişlerdi."},{"n":73,"t":"74 (Yusuf’un adamları) “Peki, yalancıysanız bunun (hırsızlığın) cezası nedir?” diye sormuştu."},{"n":74,"t":"75 (Onlar da) “Onun cezası, kayıp eşya kimin yükünde bulunursa işte o (şahsın alıkonulması) onun cezasıdır. Biz zalimleri böyle cezalandırırız.” cevabını vermişlerdi."},{"n":75,"t":"76 Bunun üzerine (Yusuf), kardeşinin (Bünyamin’in) yükünden önce onların (diğer kardeşlerinin) yüklerini (aramaya) başlamıştı. Sonra da onu (kayıp su kabını) kardeşinin (Bünyamin’in) yükünden çıkartmıştı. İşte biz Yusuf’a böyle bir tedbir (çare) öğretmiştik; (yoksa) –Allah’ın dilemesi hariç– hükümdarın kanununa göre kardeşini (yanında) tutamayacaktı. Biz dilediğimizi (layık olanı) derecelerle yükseltiriz. Her bilgi sahibinin üzerinde daha iyi bilen (birisi) vardır."},{"n":76,"t":"77 (Kardeşleri) şöyle demişlerdi: “O çalarsa, daha önce onun kardeşi de çalmıştı.” Yusuf onu (düşüncesini) içinde saklamış, onlara açmamıştı. (İçinden): “Siz çok daha kötü durumdasınız! Allah sizin anlattığınızı çok iyi bilendir.” demişti."},{"n":77,"t":"78 (Kardeşleri) şöyle demişti: “Ey vezir (Yusuf)! Şüphesiz ki onun büyük, yaşlı bir babası var. Onun yerine bizim birimizi alıkoy! Şüphesiz ki biz seni güzel davrananlardan görüyoruz.”"},{"n":78,"t":"79 (Yusuf) şöyle demişti: “Eşyamızı yanında bulduğumuz kimseden başkasını alıkoymaktan Allah’a sığınırız; doğrusu o takdirde biz zalimler oluruz!”"},{"n":79,"t":"80 Ondan ümitlerini kesince, (konuyu) gizli görüşmek üzere ayrılıp (bir kenara) çekilmişlerdi. Büyük (olan kardeş)leri şöyle demişti: “Babanızın sizden Allah adına söz aldığını, daha önce de Yusuf hakkında yaptığınız aşırılığı bilmiyor musunuz? Babam bana izin verinceye veya Allah benim için hükmedinceye kadar bu yerden (Mısır’dan) asla ayrılmayacağım. O hükmedenlerin en hayırlısıdır.”"},{"n":80,"t":"81 Babanıza dönün ve deyin ki: “Ey babamız! Oğlun hırsızlık yapmış. Biz sadece bildiğimize şahitlik ettik. Biz bilinemeyenlerin bekçileri de değiliz."},{"n":81,"t":"82 (İstersen) içinde bulunduğumuz şehre (Mısır halkına) ve birlikte geldiğimiz kervana sor! Şüphesiz ki biz doğru söyleyenleriz.”"},{"n":82,"t":"83 (Yakup onlara) şöyle demişti: “Hayır! Nefisleriniz sizi (kötü) bir işe sürüklemiş. Artık (bana düşen) güzelce sabretmektir. Umulur ki Allah onların hepsini bana getirir. Şüphesiz ki O bilendir, doğru hüküm verendir.”"},{"n":83,"t":"84 (Yakup) onlardan yüz çevirmiş (bir kenara çekilmiş) ve “Ah Yusuf’um ah!” diye sızlanmıştı. Kederini içine gömerek üzüntüden dolayı iki gözüne ak inmişti."},{"n":84,"t":"85 (Oğulları:) “Allah’a yemin olsun: Sen hâlâ Yusuf’u anıyorsun. Sonunda ya perişan olacak ya da helak olanlardan olacaksın!” demişlerdi."},{"n":85,"t":"86 (Yakup ise) şöyle demişti: “Ben, kederimi ve hüznümü yalnızca Allah’a arz ediyorum. Ben sizin bilemeyeceğiniz şeyleri Allah tarafından (Vahiy ile) biliyorum."},{"n":86,"t":"87 Ey yavrularım! Gidin de Yusuf ve kardeşinden (haber almayı) araştırın! Allah’ın merhametinden ümit kesmeyin! Şüphesiz ki kâfirler topluluğundan başkası Allah’ın merhametinden ümit kesmez.”"},{"n":87,"t":"88 (Kardeşleri) Yusuf’un yanına girdiklerinde şöyle demişlerdi: “Ey vezir! Bizi ve ailemizi kıtlık bastı ve biz değersiz (az) bir sermaye ile geldik. Hakkımızı tam ölçerek ver! (Ayrıca) bize bağışta da bulun! Şüphesiz ki Allah bağışta bulunanları ödüllendirir.”"},{"n":88,"t":"89 (Yusuf onlara) şöyle demişti: “Siz cahilken Yusuf’a ve kardeşine yaptıklarınızı biliyor (hatırlıyor) musunuz?”"},{"n":89,"t":"90 (Kardeşleri) “Yoksa sen -evet sen- Yusuf musun?” diye sormuşlar, o da “(Evet) ben Yusuf’um, bu da kardeşim!” cevabını vermişti. “(Birbirimize kavuşmayı) Allah bize lütfetti. Çünkü kim (Allah’a) karşı takvâlı (duyarlı) olur ve sabrederse, şüphesiz ki Allah güzel davrananların ödülünü boşa çıkarmaz.”"},{"n":90,"t":"91 (Kardeşleri): “Allah’a yemin olsun: Şüphesiz ki Allah seni bize üstün kılmış. Biz ise hataya düşmüşüz.” demişlerdi."},{"n":91,"t":"92 (Yusuf ise kendilerine) şöyle demişti: “Bugün sizi kınamak yok; Allah sizi affetsin! O, merhametlilerin en merhametlisidir."},{"n":92,"t":"93 Şu gömleğimi götürün de onu babamın yüzüne koyun; görecek duruma gelir. (Ayrıca) bütün ailenizi de bana getirin!”"},{"n":93,"t":"94 Kafile (Mısır’dan) ayrılınca, babaları (yanındakilere): “Bana bunamış demezseniz ben Yusuf’un kokusunu alıyorum!” demişti."},{"n":94,"t":"95 (Onlar da:) “Allah’a yemin olsun: Şüphesiz ki sen hâlâ eski şaşkınlığındasın.” demişlerdi."},{"n":95,"t":"96 Müjdeci gelince, gömleği yüzüne koyar koymaz (Yakup) görür olmuştu. “Ben size ‘Allah tarafından (Vahiy ile) sizin bilemeyeceğiniz şeyleri bilirim’ dememiş miydim!” demişti."},{"n":96,"t":"97 (Oğulları:) “Ey babamız! (Allah’tan) bizim günahlarımızın affını dile! Doğrusu günahkârlardık.” demişlerdi."},{"n":97,"t":"98 (Yakup ise:) “Sizin için Rabbimden af dileyeceğim. Şüphesiz ki O’dur O, çok bağışlayan; çok merhamet eden.” cevabını vermişti."},{"n":98,"t":"99 (Hep birlikte Mısır’a gelip) Yusuf’un yanına girdikleri zaman, ana babasını yanına almıştı. (Yusuf onlara:) “Güven içinde Mısır’a girin inşallah!” demişti."},{"n":99,"t":"100 Ana babasını tahtın(ın) üstüne çıkartıp oturtmuş ve hepsi onun için (ona kavuştukları için Allah’a) secde etmişlerdi. (Yusuf) şöyle demişti: “Ey babacığım! İşte bu, daha önce (gördüğüm) rüyanın yorumudur. Elbette Rabbim onu gerçekleştirdi. Doğrusu şeytan benimle kardeşlerimin arasını bozduktan sonra, Rabbim beni hapisten çıkararak ve sizi çölden getirerek bana (çok şey) lütfetti. Şüphesiz ki Rabbim dilediği şeyi çok ince düzenleyendir. Şüphesiz ki yalnızca O bilendir, doğru hüküm verendir."},{"n":100,"t":"101 Rabbim! Elbette otoriteden bana (bir pay) verdin ve bana (rüyada görülen) olayların yorumundan da bir kısmını öğrettin. Göklerin ve yerin yoktan yaratanı! Sen dünyada da ahirette de benim dostumsun. Beni müslüman olarak vefat ettir ve beni iyilere kat!”"},{"n":101,"t":"102 Bu(nlar), sana vahyetmekte olduğumuz gayb (bilinemeyen) haberlerindendir. Onlar tuzak kurarak (kötü) bir işte fikir birliğine vardıklarında sen onların yanında değildin (ki bunları bilesin)."},{"n":102,"t":"103 Sen ne kadar üstüne düşsen de insanların çoğu asla iman edecek değildir."},{"n":103,"t":"104 Sen bunun için onlardan herhangi bir ücret istemiyorsun. O (Kur’an), âlemler için sadece (gerçeği) hatırla(t)madır."},{"n":104,"t":"105 Göklerde ve yerde nice delil vardır ki onlara uğrarlar da onlardan yüz çevirirler."},{"n":105,"t":"106 Onların çoğu ancak ortak koşarak Allah’a iman ederler."},{"n":106,"t":"107 Allah tarafından kendilerine kuşatıcı bir azap gelmesinden veya farkında olmadan o (Son) Saat’in kendilerine ansızın gelmesinden güvende midir!"},{"n":107,"t":"108 De ki: “İşte bu, benim yolumdur. Allah’a çağırıyorum; ben ve bana uyanlar aydınlık bir yol üzerindeyiz. Allah yücedir! Ben asla ortak koşanlardan değilim.”"},{"n":108,"t":"109 Senden önce de şehirlerin halkından kendilerine vahyettiğimiz erkeklerden başkasını (peygamber olarak) göndermedik. Kendilerinden öncekilerin sonunun nasıl olduğunu görmek üzere yeryüzünde hiç mi dolaşmadılar? Ahiret yurdu takvâlı (duyarlı) olanlar için hayırlı olandır. Akıl etmiyor musunuz?"},{"n":109,"t":"110 Sonunda elçiler ümitlerini yitirip de kendilerinin (ümmetleri tarafından) yalanlandıklarını kesin olarak anladıkları sırada onlara yardımımız gelmiş ve dilediğimiz kimse(ler) kurtarılmıştır. Azabımız, suçlular topluluğundan geri döndürülemez."},{"n":110,"t":"111 Şüphesiz ki onların kıssalarında, öz akıl sahipleri için bir ibret vardır. (Bu Kur’an, başkaları tarafından tasarlanıp) uydurulabilecek bir söz değildir. Fakat o, kendinden öncekileri onaylayan, her şeyin açıklaması olan (bir kitap)tır; iman eden toplum için bir rahmet ve bir rehberdir."},{"n":111,"t":"1 Elif. Lâm. Mîm. Râ. İşte şu(nlar), Kitabın ayetleridir. Sana Rabbinden indirilen gerçektir fakat insanların çoğu inanmazlar."}],[{"n":1,"t":"Elif. Lâm. Mîm. Râ. İşte şu(nlar), Kitabın ayetleridir. Sana Rabbinden indirilen gerçektir fakat insanların çoğu inanmazlar."},{"n":2,"t":"Allah gökleri görebileceğiniz direkler olmadan yükseltmiş, sonra arşa istiva etmiş, güneşi ve ayı emri altına almıştır. (Bunların) her biri belirlenmiş bir süreye kadar akıp gitmektedir. Rabbinizle karşılaşacağınıza kesin olarak inanmanız için her işi düzenleyip ayetleri açıklamaktadır."},{"n":3,"t":"Yeri döşeyen, onda ağırlıklar ve ırmaklar yaratan ve orada bütün meyvelerden çifter çifter yaratan O’dur. Geceyi de gündüzün üzerine O örtüyor. Şüphesiz ki bunlarda düşünen bir toplum için dersler vardır."},{"n":4,"t":"Yeryüzünde birbirine komşu kıtalar, üzüm bağları, ekinler, bir kökten ve çeşitli köklerden dallanmış (çatallı ve çatalsız) hurma ağaçları vardır. Bunların hepsi bir su ile sulanır. Yemişlerinde onların bir kısmını bir kısmına farklı kılarız. İşte bunlarda, akıl eden bir toplum için dersler vardır."},{"n":5,"t":"(Kâfirlerin seni yalanlamalarına) şaşıyorsan, asıl şaşılacak şey, onların “Biz toprak olduğumuz zaman yeni bir yaratılışta mı olacağız!” demeleridir. İşte onlar, Rablerini inkâr edenlerdir; işte onlar (kıyamet gününde) boyunlarında halkalar bulunanlardır. İşte onlar ateş halkıdır. Onlar orada ebedî kalacaklardır!"},{"n":6,"t":"(Müşrikler) senden, iyilikten önce kötülüğü acele istiyorlar. (Oysa) onlardan önce nice örnekler geçmiştir. Şüphesiz ki haksızlıklarına rağmen Rabbin insanlar için bağışlama sahibidir. Şüphesiz ki Rabbinin azabı da çok şiddetlidir."},{"n":7,"t":"Kâfir olanlar diyorlar ki: “Ona Rabbinden bir ayet (mucize) indirilseydi ya!” (Oysa) sen sadece bir uyarıcısın; her toplumun da bir rehberi vardır."},{"n":8,"t":"Allah her dişinin neyi taşımakta olduğunu (neye gebe olduğunu), rahimlerin neyi eksilttiğini ve neyi artırdığını bilir. O’nun katında her şey bir ölçü iledir."},{"n":9,"t":"Görünmeyeni de görüneni de bilendir, büyüktür, çok yücedir."},{"n":10,"t":"Sizden, sözü gizleyenle onu açığa vuran, geceleyin gizlenenle gündüzün yürüyen (onun bilgisinde) eşittir."},{"n":11,"t":"(Her insanın) önünden ve arkasından Allah’ın emriyle onu koruyan takipçiler (melekler) vardır. (Kişiler) kendilerindekini değiştirinceye kadar Allah hiçbir toplumu değiştirmez. Allah bir topluma kötülük diledi mi, artık onun için geri döndürülme diye bir şey yoktur. Onların O’ndan (Allah’tan) başka yardımcıları da yoktur."},{"n":12,"t":"Size korku ve ümit olarak şimşeği gösteren ve ağır bulutları meydana getirip (sevk eden) de O’dur."},{"n":13,"t":"Gök gürültüsü (Allah’ı) hamd (övgü) ile, melekler ise O’ndan korktukları için tesbih ederler (yüceltirler). Onlar Allah hakkında tartışıp dururken, O yıldırımlar gönderip onlarla dilediğini çarpar. O, azabı (tuzağı) çok şiddetli olandır."},{"n":14,"t":"Gerçek dua yalnızca O’na (Allah’a)dır. O’nun peşi sıra dua ettikleri varlıklar onlara asla cevap veremezler. (Onların durumu, kendisi) ona ulaşamamışken ağzına ulaşsın diye iki avucunu suya uzatan kimse gibidir. Kâfirlerin yalvarması şaşkınlıkta olmaktan başka bir şey değildir."},{"n":15,"t":"Göklerde ve yerde bulunanlar da onların gölgeleri de sabah akşam ister istemez (zorunlu olarak) yalnızca Allah’a secde ederler."},{"n":16,"t":"De ki: “Göklerin ve yerin Rabbi kimdir?” (Cevaben de) de ki: “Allah’tır.” De ki: “O’nun peşi sıra kendilerine bile yarar ve zarar verme gücüne sahip olamayan dostlar mı edindiniz!” De ki: “Körle gören bir olur mu hiç! Veya karanlıklarla aydınlık eşit olur mu! Yoksa Allah’a O’nun yarattığı gibi (şeyler) yaratan ortaklar buldular da bu yaratma onlar tarafından birbirine benzer mi göründü!” De ki: “Allah her şeyin yaratıcısıdır. O, tektir; ezici güç sahibidir.”"},{"n":17,"t":"O, gökten su indirir de vadiler kendi hacimlerince sel olup akar. Bu sel, üste çıkan bir köpüğü yüklenip (götürür). Süs veya eşya yapmak için ateşte yak(ıp erit)tikleri şeylerden de buna benzer köpük olur. İşte Allah gerçekle batıla böyle örnek vermektedir. Köpük atılıp gider. İnsanlara yarar sağlayan şeye gelince o, yeryüzünde kalır. İşte Allah böyle örnekler vermektedir."},{"n":18,"t":"Rablerinin davetine uyanlar için en güzel (ödül) vardır. Ona uymayanlara gelince, yeryüzünde ne varsa hepsi ve onunla birlikte bir benzeri daha onların olsaydı, (azaptan kurtulmak için) elbette onu fidye verirlerdi (feda ederlerdi). İşte hesabın en kötüsü onlaradır. Onların barınağı cehennemdir. (Orası) ne kötü bir yataktır!"},{"n":19,"t":"Rabbinden sana indirilenin gerçek olduğunu bilen kimse, kör (inkâr eden) kimse gibi olur mu! Öz akıl sahiplerinden başkası (gerçeği) hatırlamaz."},{"n":20,"t":"Onlar Allah’a verdikleri sözü yerine getirir ve o sözü bozmazlar."},{"n":21,"t":"Onlar Allah’ın gözetilmesini emrettiği şeyleri gözetirler; Rablerine saygı duyar ve hesabın kötüsünden korkarlar."},{"n":22,"t":"Onlar Rablerinin rızasını isteyerek sabreden, namazı doğru kılan, kendilerine rızık olarak verdiğimiz şeylerden gizli ve açık olarak (Allah yolunda) infak eden (veren) ve kötülüğü iyilikle savan kişilerdir. İşte onlar var ya, (dünya) yurdunun (güzel) sonu sadece onlarındır."},{"n":23,"t":"23-24 (O yurt) durmaya değer cennetlerdir; oraya babalarından, eşlerinden ve çocuklarından iyi olanlarla birlikte gireceklerdir. Melekler de “Sabretmenize karşılık size selam olsun! Dünya yurdunun sonu (cennet) ne güzeldir!” (diyerek) her kapıdan onların yanına varacaklardır."},{"n":24,"t":"23-24 (O yurt) durmaya değer cennetlerdir; oraya babalarından, eşlerinden ve çocuklarından iyi olanlarla birlikte gireceklerdir. Melekler de “Sabretmenize karşılık size selam olsun! Dünya yurdunun sonu (cennet) ne güzeldir!” (diyerek) her kapıdan onların yanına varacaklardır."},{"n":25,"t":"Allah’a verdikleri sözü sözleştikten sonra bozanlar, Allah’ın birleştirilmesini (gözetilmesini) emrettiği şeyleri kesenler (terk edenler) ve yeryüzünde bozgunculuk çıkaranlar var ya, işte lanet onlar içindir; kötü yurt (cehennem) de onlar içindir."},{"n":26,"t":"Allah rızkı dileyene (layık gördüğüne) açarak (bol) da verebilir, kısarak (dar) da. Onlar dünya hayatıyla şımardılar. Oysa ahirete göre dünya hayatı, geçici bir yarardan başka bir şey değildir."},{"n":27,"t":"Kâfir olanlar diyorlar ki: “Ona Rabbinden bir ayet (mucize) indirilseydi ya!” De ki: “Şüphesiz ki Allah dileyeni (layık gördüğünü) saptırır (sapkınlığını onaylar); kendisine yöneleni ise doğru yola ulaştırır.”"},{"n":28,"t":"(Bunlar), iman edenler ve Allah’ı hatırlamayla kalpleri huzur bulanlardır. Dikkat edin! Kalpler ancak Allah’ı hatırlamakla huzur bulur."},{"n":29,"t":"İman edip iyi işler yapanlara ne mutlu! Varılacak güzel yurt da (onlar içindir)."},{"n":30,"t":"Böylece seni, kendilerinden önce nice ümmetlerin geçtiği bir ümmete gönderdik ki sana vahyettiğimizi onlara tilavet edesin (okuyup aktarasın). (Oysa) onlar Rahmân’ı inkâr ediyorlar. De ki: “O benim Rabbimdir. O’ndan başka ilah yoktur. Yalnızca O’na güvendim; dönüşüm de yalnızca O’nadır.”"},{"n":31,"t":"Okunan bir (kitapla) dağlar yürütülseydi veya onunla yer parçalansaydı veya onunla ölüler konuşturulsaydı (o kitap yine bu Kur’an olurdu). Fakat bütün işler, Allah’a aittir. İman edenler (şunu) bilmediler mi: Allah dileseydi bütün insanları doğru yola ulaştırırdı! Allah’ın vaadi gelinceye kadar kâfir olanlara, yaptıklarından dolayı ya ansızın büyük bir bela gelmeye devam edecek veya o (bela) evlerinin yakınına inecek. Allah vaadinden (sözünden) dönmez."},{"n":32,"t":"Şüphesiz ki senden önceki elçilerle de alay edilmişti de ben kâfir olanlara zaman tanımış, sonra da onları yakalamıştım. Benim azabım (bak) nasıl olmuştu!"},{"n":33,"t":"Herkesin kazandığının başında duran (onları gözetleyen kişi, hiç böyle yapamayan kişi gibi olur) mu! (Buna rağmen) onlar Allah’a ortaklar koştular. De ki: “Onlara isim verin (onlar neciymiş bakalım)! Yoksa siz O’na (Allah’a) yeryüzünde bilemeyeceği bir şeyi mi bildiriyorsunuz? Veya boş laf mı ediyorsunuz?” Doğrusu kâfir olanlara hileleri süslü gösterildi ve onlar (doğru) yoldan alıkonuldular. Allah kimi saptırırsa (sapkınlığını onaylarsa, artık) ona hiçbir yol gösteren olamaz."},{"n":34,"t":"Dünya hayatında onlara bir azap vardır. Ahiret azabı ise çok daha şiddetlidir. Onları Allah’tan (O’nun azabından) koruyacak kimse de yoktur."},{"n":35,"t":"Muttakîlere (duyarlı olanlara) vadolunan cennetin örneği şöyledir: Altından ırmaklar akar. Yemişleri ve gölgesi devamlıdır. İşte şu, takvâlı (duyarlı) olanların (mutlu) sonudur. Kâfirlerin sonu ise ateştir."},{"n":36,"t":"Kendilerine kitap verdiğimiz kişiler, sana indirilene (Kur’an’a) sevinirler. Fakat (diğer) gruplardan onun bir kısmını inkâr eden de vardır. De ki: “Bana, yalnızca Allah’a kulluk etmem ve O’na ortak koşmamam emrolundu. Ben yalnız O’na çağırıyorum ve dönüşüm de yalnız O’nadır.”"},{"n":37,"t":"Böylece biz onu Arapça, doğru bir hüküm olarak indirdik. Sana gelen bilgiden sonra onların arzularına uyarsan, Allah’tan (gelecek azaba karşı) senin için herhangi bir dost ve koruyucu olmayacaktır."},{"n":38,"t":"Yemin olsun ki senden önce de elçiler göndermiştik ve onlara da eşler ve çocuklar vermiştik. Allah’ın izni olmadan hiçbir elçi için bir ayet (mucize) getirme imkânı yoktur. Her sürenin yazıldığı bir kitap (yasa) vardır."},{"n":39,"t":"Allah dilediğini siler ve dilediğini sabit bırakır. Kitabın anası (esası) O’nun yanındadır."},{"n":40,"t":"Biz onlara vadettiğimiz (azab)ın bir kısmını sana göstersek de veya (ondan önce) seni öldürürsek de sana ancak (Allah’ın emirlerini) tebliğ etmek düşer. Hesap, yalnız bize aittir."},{"n":41,"t":"Yeryüzüne gelip, onu uçlarından eksilttiğimizi görmediler mi? Allah (dilediği gibi) hükmeder, O’nun hükmünü bozacak kimse yoktur. O, hesabı hızlı olandır."},{"n":42,"t":"Onlardan öncekiler de (peygamberlerine) tuzak kurmuşlardı; (oysa) bütün tuzaklar Allah’a aittir. Çünkü O, herkesin ne kazanacağını bilir. Kâfirler, bu yurdun (dünyanın) sonunun kimin olduğunu yakında bileceklerdir!"},{"n":43,"t":"Kâfir olanlar “Sen elçi değilsin.” derler. De ki: “Benimle sizin aranızda şahit olarak Allah ve yanında Kitabın bilgisi olan yeter.”"}],[{"n":1,"t":"1-2 Elif. Lâm. Râ. (Bu Kur’an), Rablerinin izniyle insanları karanlıklardan aydınlığa, yani güçlü, övgüye layık, göklerdekiler ve yerdekiler kendisine ait olan Allah’ın yoluna çıkarman için sana indirdiğimiz bir kitaptır. Şiddetli azaptan dolayı kâfirlerin vay hâllerine!"},{"n":2,"t":"1-2 Elif. Lâm. Râ. (Bu Kur’an), Rablerinin izniyle insanları karanlıklardan aydınlığa, yani güçlü, övgüye layık, göklerdekiler ve yerdekiler kendisine ait olan Allah’ın yoluna çıkarman için sana indirdiğimiz bir kitaptır. Şiddetli azaptan dolayı kâfirlerin vay hâllerine!"},{"n":3,"t":"Onlar dünya hayatını ahirete tercih eder; Allah yolundan alıkoyar ve o (yol)un eğriliğini isterler. İşte onlar uzak bir sapkınlık içindedir."},{"n":4,"t":"(Allah’ın emirlerini) onlara açıklasın diye her elçiyi yalnız kendi kavminin diliyle gönderdik. Allah dileyeni (layık gördüğünü) saptırır, dileyeni (layık gördüğünü) de doğru yola ulaştırır. O güçlüdür, doğru hüküm verendir."},{"n":5,"t":"Yemin olsun ki Musa’yı da “Kavmini karanlıklardan aydınlığa çıkar ve onlara Allah’ın (geçmiş toplumların başına getirdiği felaket) günlerini hatırlat!” diye delillerimizle göndermiştik. Şüphesiz ki bunda çok sabreden, çok şükreden herkes için dersler vardır."},{"n":6,"t":"Hani Musa kavmine demişti ki: “Allah’ın üzerinizdeki nimet(ler)ini hatırlayın! Çünkü sizi işkencenin en kötüsüne sürmekte ve oğullarınızı kestirip, kadınlarınızı sağ bırakmakta olan Firavun ailesinden O kurtarmıştı.” İşte bunda Rabbinizden büyük bir imtihan vardır."},{"n":7,"t":"Hani Rabbiniz size “Şükrederseniz elbette size (nimetimi) artıracağım; nankörlük ederseniz şüphesiz ki azabım çok şiddetlidir!” diye bildirmişti."},{"n":8,"t":"Musa şöyle demişti: “Siz ve yeryüzünde olanların hepsi nankörlük etseniz bile, Allah (gerçek) zengindir, övgüye layıktır.”"},{"n":9,"t":"Sizden öncekilerin yani Nuh, Âd ve Semûd kavimleri ile onlardan sonrakilerin haberleri size gelmedi mi? Onları Allah’tan başkası bilemez. Elçileri kendilerine deliller getirmişti de onlar ellerini onların (peygamberlerin) ağızlarına koyup tıkamışlar ve demişlerdi ki: “Biz size gönderileni inkâr ettik ve bizi kendisine çağırdığınız şeye karşı derin bir şüphe içindeyiz.”"},{"n":10,"t":"Elçileri şöyle demişti: “Gökleri ve yeri yoktan yaratan Allah hakkında şüphe mi var? (Oysa) O, sizin günahlarınızdan bir kısmını bağışlamak ve sizi belirlenmiş bir vakte kadar ertelemek için sizi (gerçeğe) çağırıyor.” Onlar da şöyle demişlerdi: “Siz de ancak bizim gibi bir insansınız. Siz bizi atalarımızın tapmış olduğu şeylerden döndürmek istiyorsunuz. (Öyleyse) bize apaçık bir delil getirin!”"},{"n":11,"t":"Elçileri ise onlara şöyle demişti: “(Evet) biz de ancak sizin gibi bir insanız. Fakat Allah (vahyi) kullarından dilediğine (layık olana) lütfeder. Allah’ın izni olmadan bizim size herhangi bir delil getirmemiz mümkün değildir. Müminler yalnızca Allah’a güvensinler!"},{"n":12,"t":"Hem bize yollarımızı göstermiş olduğu hâlde ne diye biz Allah’a güvenmeyelim! Sizin bize verdiğiniz eziyete elbette direneceğiz. Güvenenler yalnızca Allah’a güvensinler!”"},{"n":13,"t":"13-14 Kâfir olanlar elçilerine şöyle demişlerdi: “Elbette sizi ya yurdumuzdan çıkaracağız ya da mutlaka dinimize döneceksiniz!” Rableri de “Zalimleri mutlaka helak edeceğiz! Onlardan sonra sizi mutlaka o yerde yerleştireceğiz” diye onlara vahyetmişti. İşte bu (durum) makamımdan korkan ve tehdidimden sakınanlar içindir."},{"n":14,"t":"13-14 Kâfir olanlar elçilerine şöyle demişlerdi: “Elbette sizi ya yurdumuzdan çıkaracağız ya da mutlaka dinimize döneceksiniz!” Rableri de “Zalimleri mutlaka helak edeceğiz! Onlardan sonra sizi mutlaka o yerde yerleştireceğiz” diye onlara vahyetmişti. İşte bu (durum) makamımdan korkan ve tehdidimden sakınanlar içindir."},{"n":15,"t":"(Peygamberler) zafer istemişlerdi (Allah da vermişti). Her inatçı zorba kaybetmiş (olacak)tır."},{"n":16,"t":"Ardından da (o inatçı zorbaya) cehennem vardır; kendisine irinli su içirilecektir!"},{"n":17,"t":"Onu yudumlamaya çalışacak fakat neredeyse boğazından geçiremeyecektir. Ona her yandan ölüm gelecek, oysa o asla ölecek değildir. Bundan ötede ağır bir azap daha vardır."},{"n":18,"t":"Rablerini inkâr edenlerin durumu, işleri fırtınalı bir günde rüzgârın şiddetle savurduğu küle benzer. Kazandıklarından hiçbir şeye güç yetiremezler. Asıl uzak sapkınlık işte budur!"},{"n":19,"t":"Allah’ın gökleri ve yeri bir amaç ile yarattığını görmüyor musun? Dilerse sizi giderir ve (yerinize) yepyeni bir halk getirir."},{"n":20,"t":"Bu, asla Allah’a zor değildir."},{"n":21,"t":"(Kıyamet gününde) hepsi Allah’ın huzuruna çıkmış (olacak) ve zayıf olanlar kibirlenenlere diyecekler ki: “Şüphesiz ki biz size uymuştuk. Şimdi siz Allah’ın azabından herhangi bir şeyi bizden savabilir misiniz?” Onlar da şöyle diyeceklerdir: “Allah bizi doğru yola ulaştırsaydı biz de sizi doğru yola ulaştırırdık. Şimdi sızlansak da sabretsek de birdir. Artık bizim için hiçbir sığınak yoktur.”"},{"n":22,"t":"(Hesapları görülüp) iş bitirilince, şeytan şöyle diyecektir: “Şüphesiz ki Allah size gerçek olanı vadetmişti; ben de size (bir şeyler) vadetmiş ve size tersini yapmıştım. (Zaten) benim size karşı hiçbir gücüm yoktu. Sadece sizi (inkâra) çağırmıştım; siz de hemen bana (çağrıma) koşmuştunuz. (Şimdi) beni kınamayın; kendinizi kınayın! Ben sizin feryadınıza yetişemem; siz de benim feryadıma yetişemezsiniz! Şüphesiz ki daha önce ben, beni (Allah’a) ortak koşmanızı da reddetmiştim.” Şüphesiz ki zalimler için elem verici bir azap vardır."},{"n":23,"t":"İman edip iyi işler yapanlar Rablerinin izniyle içinde ebedî kalacakları ve altlarından ırmaklar akan cennetlere konulmuş (olacak)lardır. Orada esenlik dilekleri “selam”dır."},{"n":24,"t":"Görmüyor musun Allah nasıl bir örnek verdi! Güzel bir sözü, kökü (yerde) sabit, dalları yüksekte olan güzel bir ağaca (benzetti)."},{"n":25,"t":"(O ağaç), Rabbinin izniyle her zaman (her yıl) yemişini verir. (Gerçeği) hatırlasınlar diye Allah insanlara örnekler vermektedir."},{"n":26,"t":"Kötü bir sözün örneği, gövdesi yerden koparılmış, (o yüzden) sabit olmayan (ayakta duramayan) bir ağaç gibidir."},{"n":27,"t":"Allah iman edenleri sağlam sözle hem dünya hayatında hem de ahirette sapasağlam tutar; zalimleri ise saptırır. Allah dilediğini yapar."},{"n":28,"t":"Allah’ın nimetine nankörlükle karşılık veren ve toplumlarını helak yurduna sürükleyenleri görmüyor musun?"},{"n":29,"t":"Onlar cehenneme girecekler. (O) ne kötü bir karargâhtır!"},{"n":30,"t":"(İnsanları) O’nun yolundan saptırmak için Allah’a ortaklar koştular. De ki: “(İstediğiniz gibi) yaşayın! Şüphesiz ki varışınız ateşedir.”"},{"n":31,"t":"İman eden kullarıma söyle: “Namazlarını doğru kılsınlar, kendisinde alışverişin de dostluğun da bulunmadığı bir günün gelmesinden önce kendilerini rızıklandırdıklarımızdan bir kısmını (Allah için) gizli de açık da infak etsinler (versinler).”"},{"n":32,"t":"Allah gökleri ve yeri yaratan, gökten su indirip onunla size rızık olarak türlü meyveler çıkarandır. İzni ile denizde yüzüp gitmeleri için gemileri emrinize vermiş, nehirleri sizin (yararlanmanız için) hizmetinize sunmuştur."},{"n":33,"t":"Düzenli seyreden (sistemi gereği) güneşi ve ayı sizin hizmetinize vermiş, geceyi ve gündüzü de hizmetinize sunmuştur."},{"n":34,"t":"O, size istediğiniz her şeyden bir kısmını vermiştir. Allah’ın nimet(ler)ini sayacak olsanız onları sayamazsınız. Şüphesiz ki insan çok zalimdir, çok nankördür!"},{"n":35,"t":"Hani İbrahim şöyle demişti: “Rabbim! Bu şehri (Mekke’yi) güvenli kıl; beni ve oğullarımı putlara tapmamızdan uzak tut!"},{"n":36,"t":"Rabbim, onlar (putlar) insanlardan birçoğunu saptırdılar. Şimdi kim bana uyarsa o bendendir. Kim de bana karşı gelirse, sen çok bağışlayansın, çok merhamet edensin."},{"n":37,"t":"Rabbimiz! Ben neslimden bir kısmını senin Saygın Ev’inin (Kâbe’nin) yanında, tarım yapılmayan bir vadiye yerleştirdim. Rabbimiz! Namazı doğru kılmaları için (böyle yaptım). İnsanlardan bir kısmının gönüllerini onlara eğilimli kıl ve ürünlerden onlara rızık ver! Umulur ki şükrederler."},{"n":38,"t":"Rabbimiz! Şüphesiz ki sen bizim gizlemekte olduğumuzu da açıklamakta olduğumuzu da bilirsin. Yerde de gökte de hiçbir şey Allah’a gizli kalmaz."},{"n":39,"t":"İhtiyar hâlimde bana İsmail’i ve İshak’ı lütfeden Allah’a hamdolsun! Şüphesiz ki Rabbim elbette duayı duyandır."},{"n":40,"t":"Rabbim! Beni ve soyumdan gelecekleri namaz kılanlardan eyle! Rabbimiz! Duamı kabul et!"},{"n":41,"t":"Rabbimiz! Hesabın gerçekleşeceği gün, beni, ana babamı ve müminleri bağışla!”"},{"n":42,"t":"Sakın zalimlerin yaptıklarından Allah’ı habersiz sanma! Şüphesiz ki (Allah) onları (cezalandırmayı), korkudan gözlerin dışarı fırlayacağı bir güne erteliyor."},{"n":43,"t":"Kalpleri bomboş olarak bakışlarını kontrol edemez şekilde, başları yukarı dikilmiş bir durumda (davetçiye doğru) seğirtip koşarlar."},{"n":44,"t":"Kendilerine azabın geleceği, bu yüzden zalimlerin “Rabbimiz! Yakın bir süreye kadar bizi ertele (bize süre ver) de senin davetine icabet edelim ve elçilere uyalım!” diyecekleri gün hakkında insanları uyar! (Onlara şöyle denecek:) “Daha önce, sizin için bir yok oluş olmadığına yemin etmemiş miydiniz?"},{"n":45,"t":"(Sizden önce) kendilerine haksızlık edenlerin yurtlarında yerleşmiştiniz. Onlara nasıl davrandığımız size apaçık belli olmuştu. (Böylece) size (pek çok) örnekler de vermiştik.”"},{"n":46,"t":"Dağları yerlerinden edeceğini sandıkları tuzakları Allah katında (bilinmekte)yken onlar tuzak kurmuşlardı."},{"n":47,"t":"Sakın Allah’ın, elçilerine verdiği söze ters davranacağını sanma! Şüphesiz ki Allah güçlüdür, intikam sahibidir."},{"n":48,"t":"O gün, yer başka bir yer, gökler de (başka gökler) hâline getirilecek, (insanlar) tek, ezici güç sahibi olan Allah’ın huzuruna çıkacaklardır."},{"n":49,"t":"O gün, suçluların zincire vurulmuş olduğunu göreceksin."},{"n":50,"t":"Onların gömlekleri katrandandır; yüzlerini de ateş kaplayacaktır."},{"n":51,"t":"Allah herkese kazandığının karşılığını vermek için (onları diriltecektir). Şüphesiz ki Allah hesabı hızlı olandır."},{"n":52,"t":"İşte bu (Kur’an) kendisiyle uyarılsınlar, (Allah’ın) ancak tek bir ilah olduğunu bilsinler ve öz akıl sahipleri de gerçeği hatırlasınlar diye insanlara (gönderilmiş) bir bildiridir."}],[{"n":1,"t":"Elif. Lâm. Râ. İşte şu(nlar), Kitabın ve apaçık Kur’an’ın ayetleridir."},{"n":2,"t":"Bir zaman gelecek, kâfir olanlar “Keşke biz de müslüman olsaydık.” diye arzu edecekler."},{"n":3,"t":"Onları bırak; yesinler, eğlensinler ve boş ümit onları oyalayadursun! İleride (gerçeği) bilecekler!"},{"n":4,"t":"Helak ettiğimiz hiçbir şehir yoktur ki hakkında (bizce) bilinen (belirlenmiş) bir yasa olmasın."},{"n":5,"t":"Hiçbir ümmet, ecelinin önüne geçemez ve onu geciktiremez."},{"n":6,"t":"6-7 (Müşrikler) “Ey kendisine zikr (Kur’an) indirildiğini (sanan) kişi! Sen şüphesiz ki cinlenmişsin. (Peygamberlik iddianda) doğru söyleyenlerdensen bize melekleri getirsene!”"},{"n":7,"t":"6-7 (Müşrikler) “Ey kendisine zikr (Kur’an) indirildiğini (sanan) kişi! Sen şüphesiz ki cinlenmişsin. (Peygamberlik iddianda) doğru söyleyenlerdensen bize melekleri getirsene!”"},{"n":8,"t":"Biz, melekleri ancak ve ancak bir amaç ile indiririz. O zaman da onlara zaman tanınmaz."},{"n":9,"t":"Zikri (Kur’an’ı) indiren şüphesiz ki biziz, biz; elbette onu koruyucular da biziz."},{"n":10,"t":"Yemin olsun ki senden önceki milletler arasında da (elçiler) göndermiştik."},{"n":11,"t":"Kendilerine gelen her elçi ile elbette alay ederlerdi."},{"n":12,"t":"İşte böylece biz onu (alaycılığı) suçluların kalplerine sokarız."},{"n":13,"t":"Öncekilere (uygulanan) kanun gelip geçmiş olmasına rağmen onlar (hâlâ) buna (Kur’an’a) inanmıyorlar."},{"n":14,"t":"Onlara gökten bir kapı açsak ve oradan yukarı çıksalar,"},{"n":15,"t":"“Kesin olarak gözlerimiz bağlandı, aslında bize büyü yapılmıştır.” derlerdi."},{"n":16,"t":"Yemin olsun ki biz gökte birtakım burçlar yarattık ve bakanlar için onu süsledik."},{"n":17,"t":"Onu (göğü), taşlanmış (kovulmuş) her şeytandan koruduk."},{"n":18,"t":"Ancak duyma (bilgi) hırsızlığı yapan olursa, onun da peşine açık bir alev yumağı takılır."},{"n":19,"t":"Yeri genişlettik ve içine ağırlıklar yerleştirdik. Orada ölçülü olan her şeyden (bitkiler) yetiştirdik."},{"n":20,"t":"Orada hem sizin için hem de kendi(leri)ni sizin rızıklandırmadığınız kişiler için geçim kaynakları yarattık."},{"n":21,"t":"Hiçbir şey yoktur ki onun hazineleri bizim katımızda olmasın. Biz onu ancak belirli bir ölçüyle indiririz."},{"n":22,"t":"Biz, rüzgârları aşılayıcılar olarak gönderdik ve gökten su indirdik de onunla su ihtiyacınızı karşıladık. Siz onu depolayamazdınız."},{"n":23,"t":"Dirilten de öldüren de elbette biziz! Her şeye vâris olan biziz."},{"n":24,"t":"Yemin olsun ki biz sizden önce gelip geçenleri de geri kalanları da biliriz."},{"n":25,"t":"Şüphesiz ki Rabbin onları (mahşerde) toplayacaktır. Şüphesiz ki O doğru hüküm verendir, bilendir."},{"n":26,"t":"Yemin olsun ki biz insanı (pişmiş) kuru bir çamurdan, şekillenmiş kara balçıktan yarattık."},{"n":27,"t":"Cini (İblis’i) de daha önce kavurucu ateşten yaratmıştık."},{"n":28,"t":"Hani Rabbin meleklere “Ben kupkuru bir çamurdan, şekillenmiş kara balçıktan bir insan yaratacağım.” demişti."},{"n":29,"t":"“Ona düzgün şekil verip kendisine rûhumdan üflediğim zaman onun için (bana) secde edin!”"},{"n":30,"t":"Bütün melekler hemen secde etmişlerdi."},{"n":31,"t":"İblis hariç. Secde edenlerle birlikte olmaktan kaçınmıştı."},{"n":32,"t":"(Allah ona:) “Ey İblis! Secde edenlerle olmayışının sebebi nedir?” diye sormuştu."},{"n":33,"t":"(İblis de:) “Ben (pişmiş) kuru bir çamurdan, şekillenmiş kara balçıktan yarattığın bir insana secde edecek değildim!” cevabını vermişti."},{"n":34,"t":"(Allah) şöyle demişti: “Çık oradan! Şüphesiz ki sen kovuldun."},{"n":35,"t":"Hesap gününe kadar lanet(im) senin üzerinedir!”"},{"n":36,"t":"(İblis) “Rabbim! İnsanların diriltilecekleri güne kadar bana zaman ver.” demişti."},{"n":37,"t":"37-38 (Allah) “Bilinen vaktin gününe kadar zaman verilenlerdensin.” demişti."},{"n":38,"t":"37-38 (Allah) “Bilinen vaktin gününe kadar zaman verilenlerdensin.” demişti."},{"n":39,"t":"39-40 (İblis) şöyle demişti: “Rabbim! Beni azdırmana karşılık ben de yeryüzünde onlara (günahları) süsleyeceğim ve içlerinden samimi kulların hariç hepsini mutlaka azdıracağım!”"},{"n":40,"t":"39-40 (İblis) şöyle demişti: “Rabbim! Beni azdırmana karşılık ben de yeryüzünde onlara (günahları) süsleyeceğim ve içlerinden samimi kulların hariç hepsini mutlaka azdıracağım!”"},{"n":41,"t":"(Allah) şöyle demişti: “İşte bana ait doğru yol budur."},{"n":42,"t":"Şüphesiz ki azgınlardan sana uyanlar hariç, kullarım üzerinde senin hiçbir hâkimiyetin yoktur.”"},{"n":43,"t":"Şüphesiz ki cehennem onların hepsine vadolunan yerdir."},{"n":44,"t":"Onun yedi kapısı vardır. Onlardan her kapı için ayrılmış (birer) grup vardır."},{"n":45,"t":"Muttakîler (duyarlı olanlar), mutlaka cennetlerde ve (su) kaynaklarında (olacaklar)dır."},{"n":46,"t":"(Kendilerine) “Güven ve selametle oraya girin!” (denecektir)."},{"n":47,"t":"(Birbirlerine) kardeş bir şekilde tahtlar üzerinde karşılıklı olarak göğüslerinde (kalplerinde) kinden ne varsa hepsini çıkarıp atmış (olacağ)ız."},{"n":48,"t":"Onlara orada hiçbir yorgunluk dokunmayacak ve onlar oradan asla çıkartılmayacaklardır."},{"n":49,"t":"49-50 Kullarıma, benim çok bağışlayan, çok merhametli olduğumu, azabımın da elem verici bir azap olduğunu bildir!"},{"n":50,"t":"49-50 Kullarıma, benim çok bağışlayan, çok merhametli olduğumu, azabımın da elem verici bir azap olduğunu bildir!"},{"n":51,"t":"Onlara İbrahim’in misafir(ler)inden (meleklerden) de haber ver!"},{"n":52,"t":"Hani onun yanına girdikleri zaman “Selam!” demişler, (İbrahim de onlara:) “Şüphesiz ki biz sizden korkuyoruz.” demişti."},{"n":53,"t":"(Melekler:) “Korkma; şüphesiz ki biz sana bilgili bir erkek çocuk müjdeliyoruz!” demişlerdi."},{"n":54,"t":"(İbrahim:) “Yaşlılık bana dokunmasına (gelmesine) rağmen beni müjdeliyor musunuz? (Beni) ne ile müjdeliyorsunuz?” diye sormuştu."},{"n":55,"t":"(Melekler:) “Sana gerçeği müjdeledik. Sakın ümitsizliğe düşenlerden olma!” demişlerdi."},{"n":56,"t":"(İbrahim ise:) “Rabbinin merhametinden sapkınlardan başka kim ümit keser ki!” demişti."},{"n":57,"t":"(İbrahim:) “Ey elçiler (melekler)! (Başka) ne işiniz var?” diye sormuştu."},{"n":58,"t":"58-59 Onlar “Şüphesiz ki biz suçlu bir topluma (onları helak etmeye) gönderildik. Ancak Lut’un ailesi hariç! Şüphesiz ki onların hepsini kurtaracağız.” cevabını vermişlerdi."},{"n":59,"t":"58-59 Onlar “Şüphesiz ki biz suçlu bir topluma (onları helak etmeye) gönderildik. Ancak Lut’un ailesi hariç! Şüphesiz ki onların hepsini kurtaracağız.” cevabını vermişlerdi."},{"n":60,"t":"Hanımı hariç; onun geride (azaba uğrayanların içinde) kalmasını uygun görmüştük."},{"n":61,"t":"61-62 (Melek) elçiler Lut’un ailesine gelince (Lut) onlara “Şüphesiz ki siz tanınmayan kişilersiniz!” demişti."},{"n":62,"t":"61-62 (Melek) elçiler Lut’un ailesine gelince (Lut) onlara “Şüphesiz ki siz tanınmayan kişilersiniz!” demişti."},{"n":63,"t":"63-64 (Melekler) “Doğrusu biz sana, onların şüphe etmekte oldukları şeyi (helak haberini) getirdik. Sana gerçeği getirdik. Doğrusu biz doğru söyleyenleriz.” demişlerdi."},{"n":64,"t":"63-64 (Melekler) “Doğrusu biz sana, onların şüphe etmekte oldukları şeyi (helak haberini) getirdik. Sana gerçeği getirdik. Doğrusu biz doğru söyleyenleriz.” demişlerdi."},{"n":65,"t":"Gecenin bir kısmında ailenle (yola çıkıp) yürü; sen de arkalarından git! Sizden kimse sakın dönüp de arkasına bakmasın; sizden istenen yere doğru gidin!"},{"n":66,"t":"Ona (Lut’a) şu hükmümüzü vahyetmiştik: “Sabaha çıkarlarken mutlaka onların kökü kesilmiş olacaktır.”"},{"n":67,"t":"Şehrin (sapkın) halkı sevinç içinde (Lut’un yanına) gelmişlerdi."},{"n":68,"t":"(Lut onlara:) “Bunlar, benim misafirimdir; sakın beni utandırmayın!"},{"n":69,"t":"Allah’a karşı takvâlı (duyarlı) olun! Beni rezil etmeyin!” demişti."},{"n":70,"t":"(Kavmi:) “Biz seni, elalemden (başkalarının işine karışmaktan) engellememiş miydik?” demişlerdi."},{"n":71,"t":"(Lut:) “İşte kızlarım! (Düşündüğünüzü) yapacaksanız (onlarla evlenin)!” demişti."},{"n":72,"t":"(Melekler Lut’a) şöyle demişlerdi: “Ömrüne yemin olsun: Şüphesiz ki onlar sarhoşlukları içinde bocalıyorlardı.”"},{"n":73,"t":"Güneş doğarken onları o korkunç ses yakalamıştı."},{"n":74,"t":"Hemen oranın üstünü altına getirmiştik. Üzerlerine (balçıktan) pişirilmiş (sert) taşlar yağdırmıştık."},{"n":75,"t":"Şüphesiz ki bunda anlayış sahipleri için dersler vardır."},{"n":76,"t":"Onlar gözler önünde duran bir yol üzerindedir."},{"n":77,"t":"Doğrusu bunda iman edenler için bir ders vardır."},{"n":78,"t":"Eyke halkı da zalimdi."},{"n":79,"t":"Onlardan intikam almıştık. İkisi de apaçık bir yol üzerindedir."},{"n":80,"t":"Yemin olsun ki Hicr halkı da elçileri yalanlamıştı."},{"n":81,"t":"Biz onlara delillerimizi vermiştik fakat onlardan yüz çevirmişlerdi."},{"n":82,"t":"Onlar, dağlardan güven içinde kalacakları evler oyarlardı."},{"n":83,"t":"Onları sabaha çıkarlarken o korkunç ses yakalamıştı."},{"n":84,"t":"Kazandıkları şeyler onlardan hiçbir şeyi savmamıştı."},{"n":85,"t":"Biz gökleri, yeri ve ikisinin arasındakileri ancak ve ancak bir amaç ile yarattık. O (Son) Saat de mutlaka gelecektir. Onlara güzel bir şekilde hoşgörülü davran!"},{"n":86,"t":"Şüphesiz ki Rabbin her çeşit yaratandır, bilendir."},{"n":87,"t":"Biz sana tekrarlanan yedi (mesajı) ve yüce Kur’an’ı verdik."},{"n":88,"t":"Sakın onlardan bazı çiftlere verdiğimiz şeye gözlerini dikme! Onlardan dolayı üzülme ve müminlere kanadını indir (alçak gönüllü ol)!"},{"n":89,"t":"De ki: “Ben sadece apaçık bir uyarıcıyım.”"},{"n":90,"t":"Nitekim biz yalan yere yemin edenlere (azabı) indirmişizdir."},{"n":91,"t":"91-93 Rabbine yemin olsun: Yaptıklarından dolayı mutlaka Kur’an’ı bölüp ayıranların hepsini sorguya çekeceğiz."},{"n":92,"t":"91-93 Rabbine yemin olsun: Yaptıklarından dolayı mutlaka Kur’an’ı bölüp ayıranların hepsini sorguya çekeceğiz."},{"n":93,"t":"91-93 Rabbine yemin olsun: Yaptıklarından dolayı mutlaka Kur’an’ı bölüp ayıranların hepsini sorguya çekeceğiz."},{"n":94,"t":"Sana emrolunanı açıkça söyle ve ortak koşanlardan yüz çevir!"},{"n":95,"t":"Şüphesiz ki biz alay edenlere karşı sana yeteriz."},{"n":96,"t":"Onlar Allah ile birlikte başka bir ilah edinenlerdir. İleride (gerçeği) bilecekler!"},{"n":97,"t":"Yemin olsun ki onların söyledikleri şeyler yüzünden senin içinin daraldığını biliyoruz."},{"n":98,"t":"Rabbini hamd (övgü) ile tesbih et (yücelt) ve secde edenlerden ol!"},{"n":99,"t":"Sana kesin bir gerçek (olan ölüm) gelinceye kadar Rabbine ibadet et!"}],[{"n":1,"t":"Allah’ın emri gelmiştir. Onu istemekte acele etmeyin! (Allah) onların ortak koştuklarından yüce ve uzaktır."},{"n":2,"t":"(Allah) kendi emri gereği “Benden başka ilah olmadığına dair (kullarımı) uyarın ve bana karşı muttakî (duyarlı) olun!” diye melekleri kullarından dilediği (layık olan) kimseye rûh (Vahiy) ile gönderir."},{"n":3,"t":"(Allah) gökleri ve yeri bir amaç ile yaratmıştır. O, (müşriklerin) ortak koştuklarından yücedir."},{"n":4,"t":"O, insanı nutfeden (zigottan) yaratmıştır. Bir de bakarsın ki o apaçık bir tartışmacı olmuş."},{"n":5,"t":"Hayvanları da O yaratmıştır. Onlarda sizin için ısıtıcı (şeyler) ve birçok yarar vardır. Onların bir kısmından da yersiniz."},{"n":6,"t":"(Ayrıca) onlarda sizin için akşam getirirken, sabah salıverirken bir (başka) güzellik vardır."},{"n":7,"t":"(O hayvanlar) yüklerinizi, (büyük) güçlüklere katlanmadan ulaşamayacağınız şehir(ler)e taşırlar. Şüphesiz ki Rabbiniz çok şefkatlidir, çok merhametlidir."},{"n":8,"t":"Kendilerine binmeniz ve güzel görüntü olsun diye atı, katırı ve eşeği de (yaratmıştır). (Allah) henüz bilemediğiniz (daha nice şeyler) yaratmaktadır."},{"n":9,"t":"Yolun doğrusu(nu göstermek) yalnızca Allah’a aittir. (Yolun) eğrisi de vardır. (Allah) dileseydi hepinizi doğru yola ulaştırırdı."},{"n":10,"t":"Gökten sizin için suyu indiren O’dur. Ondan hem (size) içecek vardır hem de hayvanlarınızı otlatacağınız bitkiler vardır."},{"n":11,"t":"(Allah) o (su) sayesinde sizin için ekin, zeytin, hurma, üzümler ve diğer meyvelerin hepsinden yetiştirmektedir. Şüphesiz ki bunda düşünen bir toplum için bir delil vardır."},{"n":12,"t":"O, geceyi, gündüzü, güneşi ve ayı emre boyun eğdirmiştir. Yıldızlar da (Allah’ın) emri ile boyun eğdirilmiştir. Şüphesiz ki bunda aklını kullanan bir toplum için dersler vardır."},{"n":13,"t":"Yerde sizin için rengârenk yarat(ıp yayd)ıklarını da (hizmetinize sunmuştur). Şüphesiz ki bunda, (gerçeği) hatırlayan bir toplum için bir delil vardır."},{"n":14,"t":"Kendisinden taze et (balık) yemeniz ve içinden giyeceğiniz (takacağınız) bir süs (eşyası) çıkarmanız için denizi emrinize veren de O’dur. Gemilerin denizi yarıp orada gittiğini görürsün. (Bu durum, Allah’ın) nimetlerinden aramanız ve şükretmeniz içindir."},{"n":15,"t":"15-16 Sizi sarsmasıyla ilgili yer içinde ağır baskılar, (ayrıca gideceğiniz yerlere) ulaşmanız için ırmaklar, yollar ve işaretler yerleştirmiştir. Onlar, yıldızlarla da yollarını (yönlerini) bulurlar."},{"n":16,"t":"15-16 Sizi sarsmasıyla ilgili yer içinde ağır baskılar, (ayrıca gideceğiniz yerlere) ulaşmanız için ırmaklar, yollar ve işaretler yerleştirmiştir. Onlar, yıldızlarla da yollarını (yönlerini) bulurlar."},{"n":17,"t":"Yaratan, yaratamayan gibi olur mu (hiç)! (Hâlâ gerçekleri) hatırlamıyor musunuz?"},{"n":18,"t":"Allah’ın nimet(ler)ini saymaya kalksanız onu sayamazsınız. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":19,"t":"Allah gizlediğinizi de açıkladığınızı da bilir."},{"n":20,"t":"Allah’ın peşi sıra yalvardıkları (putlar) hiçbir şey yaratamazlar. (Çünkü) onlar kendileri yaratılmaktadır."},{"n":21,"t":"(Onlar) ölülerdir; diriler değillerdir. Ne zaman diriltileceklerini de bilmezler."},{"n":22,"t":"İlahınız tek bir ilahtır. (Fakat) ahirete inanmayanlar var ya, onların kalpleri inkârcıdır; kendileri de kibirlenen kişilerdir."},{"n":23,"t":"Hiç şüphe yok ki Allah onların gizlediklerini de açıkladıklarını da bilir. O, kibirlenenleri sevmez."},{"n":24,"t":"Onlara “Rabbiniz ne indirdi?” dendiği zaman, “Öncekilerin masalları!” derler."},{"n":25,"t":"Böylece kıyamet gününde kendi günahlarını tam olarak taşıyacak ve bilgisizce saptırmakta oldukları kişilerin günahlarından bir kısmını da yükleneceklerdir. Dikkat edin! Yüklenecekleri şey ne kötüdür!"},{"n":26,"t":"Elbette onlardan öncekiler de (peygamberlere) tuzak kurmuşlardı. Sonunda Allah da onların temellerinden binalarına gelmiş, üstlerinden tavan da tepelerine çökmüştü. Bu azap, onlara fark edemedikleri bir yerden gelmişti."},{"n":27,"t":"Sonra (Allah) kıyamet gününde onları rezil edecek ve şöyle diyecektir: “Kendileri hakkında (müminlere) düşman olduğunuz ortaklarım(!) nerede?” Kendilerine ilim verilmiş olanlar da “Şüphesiz ki bugün rezillik ve kötülük kâfirleredir.” demiş (olacaklar)dır."},{"n":28,"t":"Melekler canlarını alırken kendilerine yazık eden kişiler, “Biz hiçbir kötülük yapmıyorduk ki!” diyerek teslim olurlar. (Melekler şöyle diyeceklerdir) “Hayır! Allah sizin yaptıklarınızı elbette çok iyi bilendir."},{"n":29,"t":"İçinde ebedî kalıcılar olarak cehennemin kapılarına girin!” Kibirlenenlerin yeri ne kötüdür!"},{"n":30,"t":"Takvâlı (duyarlı) olanlara “Rabbiniz ne indirdi?” dendiği (zaman) “İyilik (indirdi)” derler. Bu dünyada güzel davrananlara güzel (karşılık) vardır. Ahiret yurdu ise daha hayırlıdır. Doğrusu muttakîlerin (duyarlı olanların) yurdu ne güzeldir!"},{"n":31,"t":"(O güzel yurt), girecekleri, altlarından ırmaklar akan durmaya değer cennetlerdir. Onlar için orada diledikleri her şey vardır. Allah muttakîlere (duyarlı olanlara) işte böyle karşılık verecektir."},{"n":32,"t":"(Muttakîler), meleklerin “Size selam olsun! Yapmış olduğunuz (iyi) işlere karşılık cennete girin!” diyerek tertemiz olarak canlarını aldığı kişilerdir."},{"n":33,"t":"(Kâfirler) ille de kendilerine meleklerin gelmesini veya Rabbinin (azap) emrinin gelmesini mi bekliyorlar! Onlardan öncekiler de böyle yapmışlardı. Allah onlara haksızlık etmedi fakat onlar kendilerine haksızlık ediyorlardı."},{"n":34,"t":"Sonunda yaptıklarının kötülükleri onlara ulaşmış ve alay etmiş oldukları şey onları çepeçevre kuşatmış (olacak)tır."},{"n":35,"t":"Ortak koşanlar şöyle demişlerdi: “Allah dileseydi biz de babalarımız da O’nun peşi sıra başka şeylere tapmazdık. O’nun peşi sıra (O’na rağmen) hiçbir şeyi de haram kılmazdık.” Onlardan öncekiler de böyle yapmışlardı. Elçilere apaçık tebliğden başka ne düşer ki!"},{"n":36,"t":"Yemin olsun ki biz “Allah’a kulluk edin ve Tağut’tan (azgınlık edenden) kaçının!” diye (emretmeleri için) her ümmete bir elçi göndermiştik. Allah onlardan bir kısmını doğru yola ulaştırmıştır; bir kısmı da sapkınlığı hak etmişlerdi. Yeryüzünde dolaşın; sonra yalanlayanların sonunun nasıl olduğuna bakın!"},{"n":37,"t":"Sen onların doğru yola ulaşmalarına çok düşkünlük göstersen de bil ki Allah saptırdığı (sapkınlığını onayladığı) kimseyi (kişi dilemediği sürece) doğru yola ulaştırmaz. Onların hiçbir yardımcısı da yoktur."},{"n":38,"t":"Onlar, Allah’ın ölen kişiyi dirilt(e)meyeceğine dair güçlü bir şekilde Allah’a yemin etmişlerdi. Aksine bu (diriltme), O’nun bizzat kendisine ait kesin bir vaadidir. Fakat insanların çoğu bilmez."},{"n":39,"t":"Hakkında anlaşmazlığa düştükleri şeyi onlara açıklaması ve kâfir olanların da kendilerinin yalancılar olduklarını bilmeleri için (Allah onları diriltecektir)."},{"n":40,"t":"Biz bir şeyin olmasını istediğimiz zaman, ona (söyleyecek) sözümüz sadece “Ol!” dememizdir; hemen olmaya başlar."},{"n":41,"t":"Haksızlığa uğratıldıktan sonra Allah yolunda hicret edenlere gelince, onları dünyada güzel bir şekilde yerleştireceğiz. Ahiretin ödülü elbette daha büyüktür. Keşke bilselerdi!"},{"n":42,"t":"(Ödülü hak edenler) sadece Rablerine güvenerek sabredenlerdir."},{"n":43,"t":"43-44 Senden önce de kendilerine vahyettiğimiz erkeklerden başkasını (peygamber olarak) göndermedik. Apaçık delilleri ve (ilahî) kitapları bilmiyorsanız, zikr (Vahiy) ehline sorun! Kendilerine indirileni insanlara açıklaman (ilan etmen) için ve düşünsünler diye sana da zikri (Kur’an’ı) indirdik."},{"n":44,"t":"43-44 Senden önce de kendilerine vahyettiğimiz erkeklerden başkasını (peygamber olarak) göndermedik. Apaçık delilleri ve (ilahî) kitapları bilmiyorsanız, zikr (Vahiy) ehline sorun! Kendilerine indirileni insanlara açıklaman (ilan etmen) için ve düşünsünler diye sana da zikri (Kur’an’ı) indirdik."},{"n":45,"t":"Kötülük tuzakları kuranlar, Allah’ın kendilerini yer(in dibin)e geçirmesinden veya kendilerine bilemeyecekleri bir yerden azabın gelmesinden güvende midirler?"},{"n":46,"t":"Veya onlar dönüp dolaşırlarken (Allah’ın) kendilerini yakalamasından (güvende midirler)? Onlar (Allah’ı) asla aciz bırakıcı değillerdir."},{"n":47,"t":"Veya (Allah’ın) kendilerini bir korkuyla yakalamasından (güvende midirler?) Şüphesiz ki Rabbin çok şefkatlidir, çok merhametlidir."},{"n":48,"t":"Allah’ın yarattığı herhangi bir şeyi görmediler mi? On(lar)ın gölgeleri, boyun eğerek Allah’a secde eder durumda sağ(lar)dan ve sollardan döner."},{"n":49,"t":"Göklerde ve yerdeki canlılar ve melekler kibirlenmeyerek Allah’a secde ederler."},{"n":50,"t":"(Melekler), üstlerindeki Rablerinden korkar ve kendilerine ne emrolunursa onu yaparlar."},{"n":51,"t":"Allah şöyle demiştir: “İki ilah edinmeyin! O, yalnızca tek bir ilahtır. Yalnız benden (azabımdan) korkun!”"},{"n":52,"t":"Göklerde ve yerde ne varsa yalnızca O’na aittir; din (itaat) de devamlı olarak yalnız O’nun içindir. Allah’tan başkasına karşı mı takvâlı (duyarlı) oluyorsunuz?"},{"n":53,"t":"Nimet olarak size (ulaşan) ne varsa (hepsi) Allah’tandır. Sonra size bir zarar (sıkıntı) dokunduğu zaman da yalnız O’na yalvarırsınız."},{"n":54,"t":"Sonra da sizden o zararı giderdiğinde içinizden bir grup hemen Rablerine ortak koşarlar!"},{"n":55,"t":"Kendilerine verdiklerimize karşılık nankörlük etmeleri için (öyle yaparlar). Bir süre (daha) yararlanın! İleride bileceksiniz!"},{"n":56,"t":"Kendilerine rızık olarak verdiklerimizin bir kısmından, (mahiyetini) bilmedikleri şeylere (putlara) pay ayırıyorlar. Allah’a yemin olsun: İftira etmekte olduğunuz şeylerden mutlaka sorguya çekileceksiniz!"},{"n":57,"t":"Onlar, kızları Allah’a yakıştırıyorlar. (Haşa)! O yücedir. Beğendikleri de (erkek çocukları da) kendilerinin (sanıyorlar)."},{"n":58,"t":"Onlardan birine kız çocuğu müjdelendiği zaman öfkelenmiş olarak yüzü kapkara kesilir."},{"n":59,"t":"Kendisine verilen müjdenin kötülüğünden dolayı toplumdan gizlenir. Onu, aşağılık duygusu içinde yanında mı tutsun yoksa onu toprağa mı gömsün! Dikkat edin! Verdikleri hüküm ne kadar kötüdür!"},{"n":60,"t":"Kötü örnek(ler) ahirete inanmayanlar içindir. En yüce örnek(ler) ise yalnızca Allah’a aittir. O güçlüdür, doğru hüküm verendir."},{"n":61,"t":"Allah insanları haksızlıkları yüzünden (hemen) hesaba çekseydi, onun üzerinde (yeryüzünde) hiçbir canlı (insan) bırakmazdı. Ancak, onları belirlenmiş bir süreye kadar erteliyor. Ecelleri geldiği (süreleri dolduğu) zaman artık ne bir saat (bir an) geri kalır ne de ileri giderler."},{"n":62,"t":"Kendilerinin hoşlarına gitmeyen şeyleri Allah’a yakıştırıyorlar; dilleri de (mahşerde) en güzel (ödülün) kendilerinin olduğu yalanını yakıştırıyor. Şüphesiz ki onlar için sadece ateş vardır ve onlar şüphesiz ki (ateşe) terk edileceklerdir."},{"n":63,"t":"Allah’a yemin olsun: Senden önceki ümmetlere de (elçi) göndermişizdir. (Fakat) şeytan onlara işlerini süslü göstermişti. İşte o (şeytan), bugün onların dostudur; onlar için elem verici bir azap vardır."},{"n":64,"t":"Biz bu Kitabı sana ancak hakkında anlaşmazlığa düştükleri şeyi insanlara açıklayasın (duyurasın) ve inanan bir toplum için bir rehber ve rahmet olsun diye indirdik."},{"n":65,"t":"Allah gökten su indirmiş ve onunla yeri ölümünden sonra diriltmiştir. Şüphesiz ki bunda dinleyen bir toplum için bir delil vardır."},{"n":66,"t":"Şüphesiz ki hayvanlarda da sizin için ibret vardır. Size, onların karınlarındaki atık (gübre) ile kan arasından (gelen), içenlerin boğazından kolayca geçen saf bir süt içiriyoruz."},{"n":67,"t":"Hurma ve üzümlerin ürünlerinden hem sarhoş edici şeyler hem de güzel gıdalar ediniyorsunuz. Şüphesiz ki bunda aklını kullanan bir toplum için bir delil vardır."},{"n":68,"t":"Rabbin bal arısına şöyle vahyetmişti (bildirmişti): “Dağlardan, ağaçlardan ve (insanların) yaptıkları çardaklardan kendine yuvalar edin!"},{"n":69,"t":"Sonra meyvelerin her birinden ye ve Rabbinin sana kolaylaştırdığı yollarına gir!” Karınlarından renkleri çeşitli bir içecek (bal) çıkar ki onda insanlar için şifa vardır. Şüphesiz ki bunda düşünen bir toplum için bir delil vardır."},{"n":70,"t":"Sizi Allah yaratmıştır; sonra sizi vefat ettirecektir. Bilgiliyken hiçbir şeyi bilmez hâle gelsin diye sizden bazı kişiler ömrün en sıkıntılı çağına kadar yaşatılacaktır. Şüphesiz ki Allah bilendir, gücü yetendir."},{"n":71,"t":"Allah rızık bakımından kiminizi kiminize üstün (farklı) kılmıştır. Farklı (bol rızık) verilenler, rızıklarını ellerinin altındakilere verip de bu konuda kendilerini onlara eşit kılmazlar. Allah’ın nimet(ler)ini inkâr mı ediyorlar!"},{"n":72,"t":"Allah size kendi nefislerinizden eşler yaratmış, eşlerinizden de sizin için çocuklar ve torunlar yaratmış, (ayrıca) sizi temiz gıdalardan rızıklandırmıştır. Onlar, Allah’ın nimet(ler)ine nankörlük edip batıla mı inanıyorlar!"},{"n":73,"t":"(Müşrikler) Allah’ın peşi sıra kendilerine göklerden ve yerden hiçbir rızık veremeyen ve (hiçbir şeye) güçleri yetmeyen şeylere tapıyorlar."},{"n":74,"t":"Allah’a örnekler vermeyin! Şüphesiz ki Allah bilir; siz bilemezsiniz."},{"n":75,"t":"Allah hiçbir şeye gücü yetmeyen, başkasına ait bir köle ile katımızdan kendisine verdiğimiz güzel rızıktan gizli ve açık olarak harcayan (hür) bir kimseyi örnek vermektedir. Bunlar hiç eşit olurlar mı! Hamd (övgü) Allah içindir. Fakat onların çoğu (bunu) bilmezler."},{"n":76,"t":"Allah şu iki adamı da örnek vermektedir: Onlardan biri dilsizdir, hiçbir şey beceremez ve efendisine bir yüktür. Onu her nereye gönderse hiçbir hayır (yarar) da getiremez. Bu kişi ile doğru yolda olarak adaleti emreden (diğer) kişi eşit olur mu hiç!"},{"n":77,"t":"Göklerin ve yerin gaybı (bilinemeyeni) yalnızca Allah’a aittir. O (Son) Saat’in (gerçekleşme) işi, göz açıp kapama gibi hatta çok daha yakın bir (zamanda gerçekleşecek olaydan) başka bir şey değildir. Şüphesiz ki Allah her şeye gücü yetendir."},{"n":78,"t":"Allah siz hiçbir şey bilmezken sizi analarınızın karınlarından çıkarmış, şükredesiniz diye size işitme (duyusu), gözler ve kalpler vermiştir."},{"n":79,"t":"Göğün boşluğunda emre boyun eğdirilmiş olarak uçuşan (kuş)ları görmezler mi? Onları (orada) Allah’tan başkası tutamaz. Şüphesiz ki bunda inanan bir toplum için dersler vardır."},{"n":80,"t":"Allah size huzur yeri olarak evlerinizi (yapma imkânı) vermiştir. Sizin için hayvan derilerinden gerek yolculuğunuzda, gerekse konaklama gününüzde kolayca taşıyabileceğiniz evler (çadırlar); yünlerinden, yapağılarından ve kıllarından bir süreye kadar (yararlanacağınız) ev eşyası ve ticaret malı yaratmıştır."},{"n":81,"t":"Allah yarattığı şeylerden sizin için gölgeler var etmiştir. Dağlardan da sizin için barınaklar yaratmıştır. Sizi sıcaktan (ve soğuktan) koruyacak elbiseler ve (yine) savaşta sizi koruyacak elbiseler (zırhlar) yaratmıştır. İşte böylece (Allah) teslimiyet göstermeniz için üzerinize nimetini tamamlıyor."},{"n":82,"t":"Yine de yüz çevirirlerse, artık sana düşen (görev) ancak apaçık tebliğdir."},{"n":83,"t":"Onlar, Allah’ın nimet(ler)ini bilir (itiraf eder); sonra da onu inkâr ederler. Onların çoğu kâfirdir."},{"n":84,"t":"Her ümmetten bir şahit göndereceğimiz (getireceğimizi) gün, artık (özür dilemeleri için) kâfir olanlara izin verilmez; onların özür dilemeleri de istenmez."},{"n":85,"t":"Haksızlık edenler azabı gördüklerinde, artık onlardan azap hafifletilmez, onlara bakılmaz da."},{"n":86,"t":"(Allah’a) ortak koşanlar, ortak koştuklarını (mahşerde) gördükleri zaman şöyle diyecekler: “Rabbimiz! İşte bunlar, senin peşin sıra yalvardığımız ortaklarımızdır.” Onlar (ortaklar) da diğerlerine “Siz mutlaka yalancılarsınız!” diye laf atmış (olacak)lardır."},{"n":87,"t":"(Kâfirler) o gün Allah’a teslim olacaklar ve uydurmakta oldukları şeyler (putlar) onlardan kaybolup gidecektir."},{"n":88,"t":"Kâfir olup (insanları) Allah yolundan alıkoyanlar var ya, işte bozgunculuk yapmaları sebebiyle onların azaplarını artırdıkça artıracağız."},{"n":89,"t":"O gün kendilerinden her ümmete bir şahit göndereceğiz (getireceğiz). Seni de bunların üzerine şahit olarak getirmiş olacağız. Bu Kitabı sana, her şey için bir açıklama, müslümanlar için de bir rehber, rahmet ve müjde olarak indirdik."},{"n":90,"t":"Şüphesiz ki Allah adaleti, iyiliği, akrabaya yardım etmeyi emreder; çirkinliği, fenalığı ve azgınlığı da yasaklar. (O, gerçekleri) hatırlayasınız diye size öğüt vermektedir."},{"n":91,"t":"Antlaşma yaptığınız zaman, Allah’ın sözünü yerine getirin ve Allah’ı üzerinize şahit tutarak, pekiştirdikten sonra yeminleri bozmayın! Şüphesiz ki Allah yapmakta olduğunuz şeyleri bilir."},{"n":92,"t":"Bir toplum diğer bir toplumdan daha kabarık (çok, güçlü) olduğu için, yeminlerinizi aranızda bir bozgunculuk aracı edinerek ipliğini sağlamca büktükten sonra, çözüp bozan (kişiler) gibi olmayın! Allah bununla (bu eyleminizle) sizi imtihan etmektedir. Hakkında anlaşmazlığa düşmekte olduğunuz şeyi kıyamet gününde mutlaka size açıklayacaktır."},{"n":93,"t":"Allah dileseydi sizi tek bir ümmet yapardı fakat (Allah) dileyeni (layık gördüğünü) saptırır (sapkınlığını onaylar), dileyeni (layık gördüğünü) de doğru yola ulaştırır. Yaptıklarınızdan mutlaka sorumlu tutulacaksınız."},{"n":94,"t":"Yeminlerinizi aranızda aldatma sebebi edinmeyin! Aksi hâlde sağlam bastıktan sonra ayaklar(ınız) kayar da (insanları) Allah yolundan alıkoymanız sebebiyle kötülüğü tadarsınız. Sizin için (ahirette de) büyük bir azap vardır."},{"n":95,"t":"Allah’ın sözünü az bir değere satmayın! (Gerçeği) biliyorsanız şüphesiz ki Allah katında olan (sevap) sizin için hayırlı olandır."},{"n":96,"t":"Sizin yanınızdaki (dünya malı) tükenir; Allah katındakiler ise kalıcıdır. Sabredenlere elbette yapmış olduklarının en güzeliyle ödüllerini vereceğiz."},{"n":97,"t":"Erkek veya kadın kim mümin olarak iyi iş(ler) yaparsa, onu mutlaka güzel bir hayat ile yaşatacağız. Ödüllerini de elbette yapmakta olduklarının en güzeli ile vereceğiz."},{"n":98,"t":"Kur’an’ı okuduğun zaman kovulmuş şeytandan Allah’a sığın!"},{"n":99,"t":"Gerçek şu ki iman edip yalnız Rablerine güvenenler üzerinde onun (şeytanın) hiçbir hâkimiyeti yoktur."},{"n":100,"t":"Onun hakimiyeti kendisini dost edinenler ve O’na (Allah’a) ortak koşanlar üzerindedir."},{"n":101,"t":"Biz bir ayetin yerine başka bir ayeti değiştirdiğimiz zaman –ki Allah neyi indireceğini çok iyi bilendir– “Sen ancak bir iftiracısın!” dediler. Hayır; onların çoğu (gerçeği) bilmezler."},{"n":102,"t":"De ki: “Kutsal Ruh (Cebrail) onu (Kur’an’ı) iman edenlere güç vermek için, müslümanlara rehber ve müjde olarak Rabbinin katından bir amaç ile indirmiştir.”"},{"n":103,"t":"Yemin olsun ki biz onların “Onu (Kur’an’ı ona) ancak bir insan öğretiyor!” dediklerini biliyoruz. İtham ettikleri şahsın dili yabancıdır. (Oysa) bu (Kur’an), apaçık bir Arapça’dır."},{"n":104,"t":"Allah’ın ayetlerine inanmayanlar (var ya) Allah onları doğru yola ulaştırmaz; onlar için elem verici bir azap vardır."},{"n":105,"t":"Gerçekte sadece yalan uyduranlar Allah’ın ayetlerine inanmayanlardır. İşte onlar yalancıların ta kendileridir."},{"n":106,"t":"Kim iman ettikten sonra Allah’ı inkâr ederse –kalbi iman ile dolu olduğu hâlde (inkâra) zorlanan başka–, fakat kim kalbini inkara açarsa, işte Allah’ın öfkesi bunlaradır; onlar için büyük bir azap vardır."},{"n":107,"t":"Bu (azap), onların dünya hayatını ahirete tercih etmeleri ve Allah’ın, kâfirler topluluğunu doğru yola ulaştırmaması nedeniyledir."},{"n":108,"t":"İşte onlar kalplerini, işitme (duyu)sunu ve gözlerini Allah’ın mühürlediği kişilerdir. Onlar habersizmiş gibi davrananların ta kendileridir."},{"n":109,"t":"Şüphesiz ki onlar ahirette kaybedenlerin de ta kendileridir."},{"n":110,"t":"Sonra şüphesiz ki Rabbin, eziyete uğratıldıktan sonra hicret edip ardından da sabrederek cihad edenlerin (fedakârlık yapanların yardımcısıdır). Bun(lar)dan sonra Rabbin elbette çok bağışlayandır, çok merhametlidir."},{"n":111,"t":"O gün herkes kendi canını savunmak (azaptan kurtarmak) için uğraşmak üzere (huzura) gelecektir. Herkese yaptığının tam karşılığı ödenecek; onlara haksızlık edilmeyecektir."},{"n":112,"t":"Allah güvenli, huzurlu olan, rızkı her yerden bol bol gelen bir şehir (halkını) örnek vermektedir. (Sonra) onlar, Allah’ın nimetlerine karşı nankörlük etmişler, Allah da onlara, yaptıkları yüzünden açlık ve korku sıkıntısını tattırmıştı."},{"n":113,"t":"Yemin olsun ki kendi içlerinden onlara elçi gelmişti de onu yalanlamışlardı. Onlar haksızlık ederlerken azap onları yakalamıştı."},{"n":114,"t":"Allah’ın size verdiği rızıktan temiz, helal olarak yiyin! Yalnız O’na ibadet ediyorsanız Allah’ın nimet(ler)ine şükredin!"},{"n":115,"t":"(Allah) size, özellikle leşi, kanı, domuz etini ve Allah’tan başkası adına kesilen (hayvanlar)ı haram kılmıştır. (Ancak) azgınlık yapmayacak ve sınırı aşmayacak şekilde kim (bunlardan yemek) zorunda kalırsa, (bilsin ki) Allah çok bağışlayandır, çok merhametlidir."},{"n":116,"t":"Dillerinizin uydurduğu yalana dayanarak “Şu helaldir, şu da haramdır!” demeyin; sonunda Allah’a yalan uydurmuş olursunuz. Allah’a yalan uyduranlar kurtulamazlar."},{"n":117,"t":"(Kazandıkları) az bir menfaattir. Onlar için elem verici bir azap vardır."},{"n":118,"t":"Sana daha önce anlattıklarımızı yahudi olanlara da haram kılmıştık. Biz onlara haksızlık etmedik fakat onlar kendilerine haksızlık ediyorlardı."},{"n":119,"t":"Sonra şüphesiz ki Rabbin, cahillik sebebiyle kötülük yapan, sonra da bunun ardından tevbe edip kendilerini düzeltenleri (bağışlayacaktır). Şüphesiz ki ondan (tevbe ettikten) sonra Rabbin elbette çok bağışlayandır, çok merhametlidir."},{"n":120,"t":"Şüphesiz ki İbrahim hanîf (Allah’ı birleyen), Allah’a itaat eden, (tek başına) bir ümmetti; ortak koşanlardan değildi."},{"n":121,"t":"Allah’ın nimetlerine şükrediciydi. (Allah) onu seçmiş ve doğru yola ulaştırmıştı."},{"n":122,"t":"Ona dünyada güzellik vermiştik. Şüphesiz ki o, ahirette de iyilerden (olacak)tır."},{"n":123,"t":"Sonra da sana “hanîf (Allah’ı birleyen) olarak İbrahim’in milletine (dinine) uy! O müşriklerden değildi!” diye vahyetmiştik."},{"n":124,"t":"Cumartesi (yasağı) ancak onda anlaşmazlığa düşenlere (gerekli) kılınmıştı. Şüphesiz ki Rabbin, çelişkiye düştükleri şey hakkında kıyamet günü aralarında hükmedecektir."},{"n":125,"t":"Sen Rabbinin yoluna hikmetle (doğru hükümlerle), güzel öğütle davet et ve onlarla en güzel şekilde mücadele et! Şüphesiz ki Rabbin -evet yalnızca O- kendi yolundan kimin saptığını iyi bilendir ve O kimlerin doğru yola ulaştırıldığını da iyi bilendir."},{"n":126,"t":"Ceza verecekseniz, (en fazla) size yapılanın misliyle (benzeriyle) ceza verin! Sabrederseniz, elbette bu (durum) sabredenler için daha hayırlıdır."},{"n":127,"t":"Sabret! Senin sabrın da ancak Allah’ın yardımı iledir. Onlardan dolayı üzülme! Kurmakta oldukları tuzaklar yüzünden sıkıntı içinde olma!"},{"n":128,"t":"Şüphesiz ki Allah takvâ sahibi olanlarla ve işini güzel yapanlarla beraberdir."}],[{"n":1,"t":"Bir gece, kendisine delillerimizden gösterelim diye kulunu Mescid-i Haram’dan, çevresini bereketlendirdiğimiz Mescid-i Aksa’ya (en uzak mescide) yürüten Allah yücedir. Şüphesiz ki O duyandır, görendir."},{"n":2,"t":"Musa’ya da Kitabı vermiş ve onu “Benden başka hiçbir vekil (güven kaynağı) edinmeyin!” diye İsrailoğullarına bir rehber kılmıştık."},{"n":3,"t":"Ey Nuh ile birlikte (gemide) taşıdıklarımızın nesli! Şüphesiz ki o çok şükreden bir kuldu."},{"n":4,"t":"Biz Kitapta İsrailoğullarına “Siz yeryüzünde iki kez bozgunculuk çıkaracak ve büyük bir kibre kapılacaksınız.” diye bildirmiştik."},{"n":5,"t":"Bunlardan ilkinin (cezalandırma) zamanı gelince, üzerinize güçlü kullarımızı salmıştık da evlerin aralarını bile köşe bucak aramışlardı. Bu, yerine getirilmiş bir vaatti."},{"n":6,"t":"(Bu ilk sıkıntıdan) sonra onlara karşı size tekrar (fırsat) vermiştik; servet ve çocuklarla sizi (gücünüzü) desteklemiş, sayınızı daha da çoğaltmıştık."},{"n":7,"t":"(Size şöyle demiştik): “İyilik yaparsanız kendiniz için iyilik yapmış olursunuz; kötülük yaparsanız yine kendinize yapmış olursunuz. Artık sonuncu (ikinci cezalandırma) zamanı gelince, yüzlerinizi kapkara edecek, daha önce girdikleri gibi yine Mescide (Süleyman Mabedi’ne) girecek ve üstün gelip her şeyi tahrip edecek (ordular size musallat olur).”"},{"n":8,"t":"Rabbiniz size merhamet edecektir. (Bozgunculuğa) dönerseniz, biz de (sizi cezalandırmaya) döneriz. Cehennemi kâfirler için bir kuşatma yeri yaptık."},{"n":9,"t":"Şüphesiz ki bu Kur’an, (tek) doğruya ulaştırır; iyi işler yapan müminlere büyük bir ödül olduğunu müjdeler."},{"n":10,"t":"Ahirete inanmayanlar için ise elem verici bir azap hazırlamışızdır."},{"n":11,"t":"(Nankör) insan, iyiliği istediği (gibi) kötülüğü de ister. İnsan çok acelecidir!"},{"n":12,"t":"Biz geceyi ve gündüzü iki delil olarak yarattık. Rabbinizin lütfundan aramanız ve yılların sayısını ve hesabı bilmeniz için gecenin delilini (ayı) silip, (yerine) aydınlatan gündüzün delilini (güneşi) getirdik. İşte (bu konuda) her şeyi açıkça anlattık."},{"n":13,"t":"Her insanın uçup (gittiğini sandığı davranışlar)ını boynuna bağladık. İnsan için kıyamet gününde, (önünde) açılmış bir kitap (amel defteri) çıkartacağız."},{"n":14,"t":"(Kendisine şöyle diyeceğiz): “Kitabını oku! Bugün hesap görücü olarak sana kendi nefsin yeter.”"},{"n":15,"t":"Kim doğru yola gelirse, sadece kendisi için gelmiş olur; kim de saparsa, sadece kendi aleyhine sapmış olur. Hiçbir (günah) yüklüsü, başkasının (günah) yükünü yüklenemez. Biz bir elçi gönderinceye kadar (kimseye) azap ediciler değiliz."},{"n":16,"t":"Bir şehri helak etmek istediğimizde, o şehrin şımarık elebaşlarını yönetici yaparız da onlar orada kötülük işlerler. Böylece ona (şehir halkına azap) sözü gerçek olur; orayı darmadağın ederiz."},{"n":17,"t":"Nitekim Nuh’tan sonraki nice nesilleri helak etmiştik. Rabbin, kullarının günahlarını bilip görmede yeterlidir."},{"n":18,"t":"Kim bu çabucak geçen (dünyayı) isterse, ona yani (helakini) dilediğimiz kimseye dilediğimiz kadarını dünyada hemen veririz. Sonra da onu kınanmış ve kovulmuş olarak gireceği cehenneme yerleştirmiş (olacağız)."},{"n":19,"t":"Kim de ahireti ister ve mümin olarak çalışırsa, işte bunların çalışmaları değerlidir."},{"n":20,"t":"Hepsine yani onlara da bunlara da Rabbinin cömertliğinden (istediklerini) veririz. Rabbinin verdiği, kimse tarafından engellenemez."},{"n":21,"t":"Bak ki biz insanların kimini kiminden nasıl farklı yaratmışız! Elbette ahiret derece ve üstünlük farkları bakımından çok daha büyüktür."},{"n":22,"t":"Allah ile birlikte başka ilah edinme! Aksi takdirde kınanmış ve (azaba) terkedilmiş olarak oturup kalırsın."},{"n":23,"t":"Rabbin, sadece kendisine kulluk etmenizi ve ana babaya iyiliği emretmiştir. Onlardan biri veya her ikisi senin yanında yaşlanırsa, kendilerine sakın “Öf!” bile deme; onları azarlama; kendilerine güzel sözler söyle!"},{"n":24,"t":"Onlara merhametten kaynaklanan alçak gönüllülük kanadını ger ve şöyle de: “Rabbim! Küçüklüğümde onlar beni nasıl sahiplendiyseler (özenle büyüttüyseler), şimdi sen de onlara merhamet et!”"},{"n":25,"t":"Rabbiniz kalplerinizdekini çok iyi bilendir. Siz iyiler olursanız (şunu bilin ki) şüphesiz ki O, kendisine yönelenleri çok bağışlayandır."},{"n":26,"t":"Akrabaya, yoksula ve yolda kalmışa hakkını ver! Saçıp savurma!"},{"n":27,"t":"Şüphesiz ki saçıp savuranlar şeytanların kardeşleridir. Şeytan ise Rabbine karşı çok nankördür."},{"n":28,"t":"Rabbinden beklediğin bir rahmet arzusu için onlardan yüz çevirirsen (en azından) kendilerine gönül alıcı bir söz söyle!"},{"n":29,"t":"Elini boynuna kilitleme; onu büsbütün de açma! Sonra kınanmış, (kaybettiklerinin) hasret(ini) çekmiş olarak oturur kalırsın."},{"n":30,"t":"Şüphesiz ki Rabbin, rızkı dilediğine (layık olana) açarak (bol) da verebilir, kısarak (dar) da. Şüphesiz ki O, kullarından haberdardır, görendir."},{"n":31,"t":"Geçim endişesiyle çocuklarınızı öldürmeyin! Onları da sizi de rızıklandıran biziz. Şüphesiz ki onları öldürmek, büyük bir günahtır."},{"n":32,"t":"Zinaya yaklaşmayın! Şüphesiz ki o bir çirkinliktir; kötü bir yoldur."},{"n":33,"t":"Allah’ın saygın kıldığı (öldürülmesini yasakladığı) canı haksız yere öldürmeyin! (Haksız yere) öldürülen kişinin velisine (yakınına) elbette yetki verdik. (Yine de) o öldürmede ileri gitmesin (ille de karşılığında ölüm istemesin)! Şüphesiz ki (öldürülen kişiye) yardım edilmiş (olacak)tır."},{"n":34,"t":"Yetimin malına, yetişkinlik zamanına ulaşıncaya kadar en güzel olanın dışında sakın yaklaşmayın! Verdiğiniz sözü de yerine getirin! Şüphesiz ki verilen söz sorumluluğu gerektirir."},{"n":35,"t":"Ölçtüğünüz zaman tastamam ölçün ve doğru bir terazi ile tartın! Bu (tutum) hem hayırlı olandır hem de sonuç itibarıyla güzel olandır."},{"n":36,"t":"Hakkında bilgin olmayan şeyin peşine (biliyormuş gibi) düşme! Şüphesiz ki işitme (duyusu), göz ve kalp, bütün bunlar o (kazandığı)ndan sorumludur."},{"n":37,"t":"Yeryüzünde kibirlenerek yürüme! Şüphesiz ki sen asla yeri yaramazsın; boyun da asla dağlara ulaşamaz."},{"n":38,"t":"Bütün bu (sayıla)nların kötülüğü, Rabbinin katında çirkin sayılmalarıdır."},{"n":39,"t":"İşte (bütün) bunlar, Rabbinin sana vahyettiği doğru hükümler içeren konulardandır. Allah ile birlikte başka ilah edinme! Kınanmış ve (Allah’ın merhametinden) uzaklaştırılmış olarak cehenneme atılırsın."},{"n":40,"t":"Kendisi meleklerden kız çocuklar edinmiş (!) olarak, Rabbiniz erkek çocukları size mi ayırmış! Şüphesiz ki siz (sorumluluğu) çok ağır bir söz söylüyorsunuz."},{"n":41,"t":"Yemin olsun ki biz bu Kur’an’da (gerçeği) hatırlasınlar diye (her şeyi) türlü şekillerde sayıp dökmüşüzdür. (Fakat bu), onların sadece nefretini artırıyor."},{"n":42,"t":"De ki: “Söyledikleri gibi O’nunla birlikte başka ilahlar olsaydı, arşın sahibine (Allah’a ulaşmak için) bir yol ararlardı.”"},{"n":43,"t":"O (Allah) onların söylediklerinden yücedir ve büyüktür."},{"n":44,"t":"Yedi (kat) gök, yer ve bunlardaki herkes, O’nu (Allah’ı) tesbih eder (yüceltir). Hiçbir şey yoktur ki O’nu hamdiyle (övgüyle) tesbih ediyor (yüceltiyor) olmasın. Ancak siz onların tesbihini (yüceltmesini) anlayamıyorsunuz. Şüphesiz ki O hoşgörülüdür, çok bağışlayandır."},{"n":45,"t":"Kur’an okuduğun zaman, seninle ahirete inanmayanların arasına gizlenmiş bir örtü çekeriz."},{"n":46,"t":"(İnkârcıların) onu (Kur’an’ı) anlamalarıyla ilgili kalplerine bir kapalılık ve kulaklarına bir (s) ağırlık veririz. Kur’an’da O’nu (Allah’ı tek ilah olarak) andığında, nefret ederek arkalarını dön(üp gid)erler."},{"n":47,"t":"Biz onların seni dinlerken onu (Kur’an’ı ne amaçla) dinlediklerini, kendi aralarında fısıldaşırlarken zalimlerin “Siz büyülenmiş bir adamdan başkasına uymuyorsunuz!” dediklerini çok iyi bileniz."},{"n":48,"t":"Baksana; senin için ne türlü benzetmeler yapıp saptılar; (doğru) yolu bulamazlar."},{"n":49,"t":"Şöyle dediler: “Biz kemik ve ufalanmış toprak olmuşken mi yepyeni bir varlık olarak mı diriltilecekmişiz?”"},{"n":50,"t":"De ki: “İster taş olun, ister demir!"},{"n":51,"t":"İsterse göğüslerinizde (kalplerinizde) büyüyen (abarttığınız varlıklardan) herhangi bir yaratık olun!” (Müşrikler) “Bizi tekrar (hayata) döndürecek (olan) kimmiş?” deyince, (onlara) de ki: “Sizi ilk kez yaratan.” Onlar, sana (alaycılıkla) başlarını sallayarak “O (diriltilme) ne zamanmış!” diyecekler. De ki: “Belki de çok yakındır.”"},{"n":52,"t":"(Allah’ın) sizi çağıracağı o gün, kendisini överek çağrısına uyacak ve (dünyada) az kaldığınızı anlayacaksınız."},{"n":53,"t":"Kullarıma söyle, (tartışırken karşısındakilere) sözün en güzelini söylesinler (güzelce tartışsınlar)! Şüphesiz ki şeytan aralarına fitne sokar. Şüphesiz ki şeytan insanın apaçık düşmanıdır."},{"n":54,"t":"Rabbiniz sizi çok iyi bilendir. Dilerse size merhamet eder; dilerse azap eder. Biz seni onların üstüne bir vekil olarak göndermedik."},{"n":55,"t":"Rabbin, göklerde ve yerde olan herkesi çok iyi bilendir. Yemin olsun ki biz peygamberlerin bir kısmını bir kısmına (farklı oldukları noktalarda) üstün kıldık; Davud’a da Zebur’u verdik."},{"n":56,"t":"De ki: “O’nun (Allah’ın) peşi sıra (ilah olduğunu) sandıklarınıza yalvarın! (Ne var ki) onlar, sizin darlığınızı gidermeye de (hakkınızdaki hükmü) değiştirmeye de güç yetiremezler.”"},{"n":57,"t":"Onların yalvardıkları bu varlıklar bile aslında –hangisi daha yakın olacak diye– Rablerine yol ararlar. O’nun merhametini umar ve azabından korkarlar. Şüphesiz ki Rabbinin azabı sakınılması gereken önemdedir."},{"n":58,"t":"(Halkı günaha saplanmış) ne kadar şehir varsa hepsini kıyamet gününden önce ya helak eder ya da şiddetli bir azaba uğratırız. Bu (uygulamamız), Kitapta yazılı bir (hükmümüz)dür."},{"n":59,"t":"Bizi, ayetler (mucizeler) göndermekten alıkoyan tek şey, öncekilerin onları yalanlamış olmasıdır. (Nitekim) Semûd kavmine de (mucize olarak) aydınlatıcı, (ders verici) bir dişi deve vermiştik de onlar (vahşice katlettikleri için) ona haksızlık etmişlerdi. (Oysa) biz ayetleri (mucizeleri) ancak (inkârcıları) korkutmak için göndeririz."},{"n":60,"t":"Hani sana şöyle demiştik: “Rabbin, insanları çepeçevre kuşatmıştır. Sana (isra esnasında) gösterdiğimiz o rüyayı ve Kur’an’da lanetlenmiş (zakkum) ağacını, ancak insanları sınamak için meydana getirmiştik. Biz onları (insanları) korkutuyoruz; (bu durum) onların sadece büyük azgınlığını artırıyor.”"},{"n":61,"t":"Hani meleklere “Âdem için (Allah’a) secde edin.” demiştik; onlar da hemen secde etmişlerdi. İblis hariç. (O) “Ben çamurdan yarattığın bir kişi için secde eder miyim hiç!” demişti."},{"n":62,"t":"(İblis) “Bana üstün kıldığın şu (insan)a bakar mısın? Beni kıyamet gününe kadar ertelersen, azı dışında onun neslini kendime bağlayacağım.” demişti."},{"n":63,"t":"(Allah) şöyle demişti: “Çık! Onlardan kim sana uyarsa, cehennem hak ettiğiniz tastamam karşılıktır."},{"n":64,"t":"Gücünün yettiği kişileri davetinle (gerçeklerden) uzaklaştır! Süvarilerinle ve yayalarınla onları yaygaraya boğ! Malları ve çocukları (aracılığıyla yapacakları kötülükler)de onlara ortak ol! Kendilerine vaatlerde bulun!” Şeytan, insanlara aldatmadan başka bir şey vadetmez."},{"n":65,"t":"“(Samimi) kullarım üzerinde senin hiçbir gücün yoktur.” Vekil (güven kaynağı) olarak Rabbin yeter."},{"n":66,"t":"Rabbiniz, nimetlerinden edinmeniz için gemileri denizde sizin için yüzdürendir. Şüphesiz ki O size çok merhametlidir."},{"n":67,"t":"Denizde size bir sıkıntı geldiğinde, O’ndan başka yalvardıklarınız kaybolup gider. Sizi kurtarıp karaya çıkardığında (eski hâlinize) dönersiniz. İnsanoğlu çok nankördür."},{"n":68,"t":"(Allah’ın), sizi kara tarafında yerin dibine geçirmesinden veya üzerinize taş yağdırmasından güvende misiniz? Sonra kendiniz için hiçbir koruyucu da bulamazsınız."},{"n":69,"t":"Veya inkâr etmiş olmanız sebebiyle O’nun sizi bir kez daha oraya (denize) gönderip üzerinize bir kasırga yollayarak sizi boğmasından güvende misiniz? Sonra bize karşı sizi takip edecek kimse bulamazsınız."},{"n":70,"t":"Yemin olsun ki âdemoğlunu değerli kıldık; onları karada ve denizde taşıdık; kendilerine tertemiz rızıklar verdik ve onları, yarattıklarımızın birçoğundan üstün kıldık."},{"n":71,"t":"Her insan topluluğunu imamıyla (önderiyle) çağıracağımız o günde, kimin kitabı (amel defteri) sağından verilirse, onlar kitabını okuyacaklar ve en küçük bir şekilde haksızlığa uğratılmayacaklardır."},{"n":72,"t":"Bu dünyada (gerçeğe karşı) kör kalan kimse, ahirette de kör olacaktır; hatta yolunu iyice şaşırmış olacaktır."},{"n":73,"t":"(Müşrikler), sana vahyettiğimizden (Kur’an’dan) başka bir şeyi bize iftira etmen için neredeyse seni fitneye düşüreceklerdi. İşte o takdirde seni candan dost kabul edeceklerdi."},{"n":74,"t":"Seni dayanıklı (kararlı) kılmasaydık, az kalsın onlara birazcık eğilim gösterecektin."},{"n":75,"t":"İşte o zaman, sana ölümün kat kat (sıkıntılar)ıyla birlikte hayatın sıkıntılarını da kat kat tattırırdık. Sonunda bize karşı kendin için hiçbir yardımcı da bulamazdın."},{"n":76,"t":"Onlar, seni o yerden (yurdundan) çıkarmak için neredeyse dünyayı başına dar edecekler. O takdirde senin ardından kendileri de (Mekke’de) fazla kalamayacaklar."},{"n":77,"t":"(Nitekim) senden önce gönderdiğimiz elçiler hakkındaki kanun (da böyleydi). Bizim kanunumuzda asla hiçbir değişiklik bulamazsın."},{"n":78,"t":"Güneşin (batıya) yönelip gecenin karanlığı bastırıncaya kadar ve tan vaktinin (sabah ışıklarının) toplanması (vaktinde) namaz kıl! Şüphesiz ki tan vaktinin (sabah ışıklarının) toplanmasına şahit olunmaktadır."},{"n":79,"t":"Sana özel olmak üzere gece uykuya ara ver! (Böylece) Rabbin seni, mutlaka övgüye değer bir makama ulaştıracaktır."},{"n":80,"t":"De ki: “Rabbim! Gireceğim yere dürüstlükle girmemi; çıkacağım yerden de dürüstlükle çıkmamı sağla! Bana tarafından yardım edici bir güç ver!”"},{"n":81,"t":"De ki: “Gerçek geldi; batıl yıkıldı. Şüphesiz ki batıl yıkılmaya mahkûmdur.”"},{"n":82,"t":"Biz, müminler için şifa ve rahmet olan, zalimlerin de sadece zararını artıran Kur’an’ı indiriyoruz."},{"n":83,"t":"Biz o (nankör) insana nimet verdiğimizde yüz çevirip yan çizer. Kendisine bir sıkıntı dokununca da iyice karamsarlığa düşer."},{"n":84,"t":"De ki: “Herkes kendi kalıbına göre iş yapar. Rabbiniz, kimin doğru yolu tuttuğunu çok iyi bilendir.”"},{"n":85,"t":"Sana rûhtan soruyorlar. De ki: “Rûh, Rabbimin emrindendir.” (Bu konuda) size ancak az bir bilgi verilmiştir."},{"n":86,"t":"Dilersek sana vahyettiğimizi gideririz; sonra bize karşı kendin için hiçbir vekil (güven kaynağı) da bulamazsın."},{"n":87,"t":"Rabbinin merhameti hariç! Şüphesiz ki O’nun sana yönelik iyiliği büyüktür."},{"n":88,"t":"De ki: “Bu Kur’an’ın bir benzerini getirmek üzere insanlar ve cinler bir araya gelseler, hatta birbirlerine destek de olsalar onun benzerini getiremezler.”"},{"n":89,"t":"Yemin olsun ki biz bu Kur’an’da insanlara her türlü örneği çeşitli şekillerde anlattık. İnsanların çoğu sadece nankörler olarak yüz çevirdiler."},{"n":90,"t":"(İnkârcılar) şöyle demişlerdi: “Bizim için yerden bir kaynak fışkırtıncaya kadar sana asla inanmayacağız."},{"n":91,"t":"Veya sana ait bir hurma bahçen ve üzüm bağın olup içlerinden bolca ırmaklar akıtıncaya kadar (sana inanmayacağız)."},{"n":92,"t":"Veya iddia ettiğin gibi üzerimize gökten parçalar yağdırıncaya veya Allah’ı ve melekleri önümüze getirinceye kadar (sana inanmayacağız)."},{"n":93,"t":"Veya altından bir evin (köşkün) oluncaya ya da göğe yükselinceye kadar (sana inanmayacağız)! Bize, okuyacağımız bir kitap indirinceye kadar (göğe) yükselmene de asla inanmayacağız!” De ki: “Rabbim yücedir. Ben insan bir elçiden başka neyim ki!”"},{"n":94,"t":"Kendilerine rehber geldiğinde insanları iman etmekten alıkoyan şey, “Allah elçi olarak bir insanı mı gönderdi” demelerinden başka bir şey değildir."},{"n":95,"t":"De ki: “Yerde yerleşip yürüyenler melekler olsaydı, elbette biz de gökten onlara elçi melek indirirdik.”"},{"n":96,"t":"De ki: “Benimle sizin aranızda şahit olarak Allah yeter. Şüphesiz ki O, kullarından haberdardır, görendir.”"},{"n":97,"t":"Allah’ın hidayet ettiği kişi doğru yola ulaş(tırıl)mıştır. Saptırdığı (sapkınlığını onayladığı) kişi içinse O’ndan başka (O’na rağmen) dostlar (yardımcılar) bulamazsın. Kıyamet gününde onları kör, dilsiz ve sağır olarak yüzüstü bir araya toplayacağız. Onların barınağı, ateşi her yavaşladıkça alevini artıracağımız cehennemdir."},{"n":98,"t":"Ayetlerimizi inkâr etmeleri ve “Biz kemik ve ufalanmış toprak olmuşken mi yepyeni bir varlık olarak mı diriltilecekmişiz?” demeleri nedeniyle cezaları işte budur."},{"n":99,"t":"Gökleri ve yeri yaratan Allah’ın onları (mahşerde) benzer şekilde yaratmaya ve kendileri için şüphe duyulamayacak bir süre tayin etmeye gücünün yeteceğini hiç mi düşünmediler? Zalimler, sadece inkârcılar olarak yüz çevirdiler."},{"n":100,"t":"(Onlara) de ki: “Rabbimin merhamet hazinelerine sahip olsaydınız, harcanır korkusuyla (onlara) yapışırdınız (kimseye vermezdiniz).” İnsan çok cimridir."},{"n":101,"t":"Yemin olsun ki Musa’ya apaçık dokuz ayet (mucize) vermiştik. (Musa) yanlarına geldiğinde Firavun’un ona “Ey Musa, senin büyülenmiş olduğunu sanıyorum.” dediğini İsrailoğullarına sor!"},{"n":102,"t":"(Musa da) “Bunları (mucizeleri) öngörüler olarak, göklerin ve yerin Rabbinden başkasının indirmediğini gayet iyi biliyorsun. Ey Firavun! Doğrusu ben senin mahvolacağını sanıyorum.” demişti."},{"n":103,"t":"(Firavun) onları o yerden (o ülkeden) çıkarmak istemişti. Bu yüzden biz de onu ve beraberindekileri (denizde) boğmuştuk."},{"n":104,"t":"Arkasından da İsrailoğullarına “O topraklarda yerleşip oturun! Ahiret vaadi geldiğinde hepinizi toplayıp bir araya getireceğiz.” demiştik."},{"n":105,"t":"Biz onu (Kur’an’ı), bir amaç ile indirdik; zaten o da gerçeği getirmiştir. Seni yalnızca müjdeleyici ve uyarıcı olarak gönderdik."},{"n":106,"t":"Biz onu (Kur’an’ı), insanlara yavaş yavaş okuyasın diye (bölümlere) ayırdık ve onu bu şekilde indirdik."},{"n":107,"t":"De ki: “Siz ona ister inanın, ister inanmayın! Şüphesiz ki daha önce kendilerine ilim verilenlere (Kur’an) okununca yüz üstü secdeye kapanırlar."},{"n":108,"t":"Rabbimizi tesbih ederiz (yüceltiriz) ki O’nun vaadi mutlaka yerine getirilmiştir.” derler."},{"n":109,"t":"(Kur’an okumak) onların saygısını artırmış bir şekilde ağlayarak yüzüstü yere kapanırlar."},{"n":110,"t":"De ki: “İster Allah diye dua edin; ister Rahmân diye dua edin! Hangisiyle dua ederseniz edin, en güzel isimler yalnızca O’na aittir.” Duanı yüksek sesle yapma; sesini fazla da kısma; bu (ikisi) arasında bir yol tut!"},{"n":111,"t":"De ki: “Hamd (övgü), çocuk edinmemiş olan, otoritesinde ortağı bulunmayan, düşkünlük sebebiyle dosta (ihtiyacı) olmayan Allah’a aittir.” O’nu gerektiği gibi yücelt!"}],[{"n":"1-4","t":"Katından (gelecek) şiddetli azaba karşı (inkârcıları) uyarmak, iyi işler yapan müminlere içinde ebedî kalacakları güzel ödül (cennet) bulunduğunu müjdelemek ve “Allah çocuk edindi!” diyenleri de korkutmak için doğru (bir kelam) olarak içerisine hiçbir eğrilik koymadığı Kitabı kulu (Muhammed’e) indiren Allah’a hamdolsun."},{"n":5,"t":"Onların da babalarının (atalarının) da bu konuda hiçbir bilgisi yoktur! Ağızlarından çıkan söz ne de büyüktür (çirkindir)! Yalandan başka bir şey söylemiyorlar."},{"n":6,"t":"Bu söze (Kitaba) inanmıyorlar (diye) arkalarından üzüntüden neredeyse kendini harap edeceksin."},{"n":7,"t":"Biz, (insanların) hangisinin daha güzel iş(ler) yapacağını deneyelim diye yerdeki her şeyi ona ait bir süs yaptık."},{"n":8,"t":"Biz mutlaka onun üzerindeki her şeyi kupkuru bir toprak yapacağız."},{"n":9,"t":"Yoksa sen bizim ayetlerimizden (mucizelerimizden, sadece) kehf ve rakîm halkının durumlarını mı şaşırtıcı buldun?"},{"n":10,"t":"Hani o gençler mağaraya sığınmışlar ve “Rabbimiz! Bize tarafından merhamet ver ve bize (şu) durumumuzdan bir kurtuluş yolu hazırla!” demişlerdi."},{"n":11,"t":"Biz de senelerce o mağarada onların kulaklarına perde yerleştirmiştik (onları uykuya daldırmıştık)."},{"n":12,"t":"Sonra da iki taraftan (Ashab-ı Kehf ile karşıtlarından) hangisinin (mağarada) kaldıkları uzun süreyi daha iyi hesap edeceğini bil(dir)ip (ortaya çıkaralım) diye onları uyandırmıştık."},{"n":13,"t":"Biz sana onların haberini bir amaç için anlatıyoruz. Şüphesiz ki onlar, Rablerine inanıp güvenmiş gençlerdi. Biz de onların hidayetini artırmıştık."},{"n":14,"t":"Onların kalplerini sağlam kılmıştık. Hani onlar ayağa kalkarak şöyle demişlerdi: “Bizim Rabbimiz, göklerin ve yerin Rabbidir. Biz O’nun peşi sıra hiçbir ilaha asla yalvarmayacağız. O takdirde şüphesiz ki saçma konuşmuş oluruz."},{"n":15,"t":"Şu bizim kavmimiz, O’nun peşi sıra ilahlar edindiler.” Bunlar apaçık bir delil getirseler ya! Allah’a yalan uydurandan daha zalim kim olabilir ki!"},{"n":16,"t":"(İçlerinden biri şöyle demişti:) “Madem siz onlardan ve Allah’tan başka tapmakta olduklarından uzaklaştınız; mağaraya sığının ki Rabbiniz size merhametinden yaysın ve işinizde sizin için kolaylık sağlasın.”"},{"n":17,"t":"(Orada bulunsaydın) onlar onun (mağaranın) geniş bir yerindeyken güneşi doğduğunda mağaranın sağına yönelirken, batarken de sol taraftan (onlara vurmadan) geçerken görürdün. İşte bu, Allah’ın delillerindendir. Allah kime hidayet ederse işte o, doğru yola ulaştırılmıştır. Kimi de saptırırsa (sapkınlığını onaylarsa) artık ona yol gösterecek herhangi bir dost asla bulamazsın."},{"n":18,"t":"Kendileri uykuda oldukları hâlde sen onları uyanık sanırdın. Onları sağa sola çeviriyorduk. Köpekleri de (mağaranın) girişinde ön ayaklarını uzatmıştı. Onları görüp bilseydin dönüp onlardan kaçardın ve gördüklerin yüzünden için korku ile dolardı."},{"n":19,"t":"(Onları uyuttuğumuz gibi) durumlarını birbirlerine sormaları için aynı şekilde kendilerini uyandırmıştık. İçlerinden biri “Ne kadar kaldınız?” demişti. (Kimileri) “Bir gün veya günün bir parçası kadar kaldık.” demiş, (kimileri de) “Rabbiniz, kaldığınız süreyi daha iyi bilendir.” cevabını vermişti. İçinizden birini şu gümüş paranızla şehre gönderin de baksın, hangi yiyecek daha temiz ise size ondan rızık getirsin! Ayrıca nazik (dikkatli) davransın ve sakın sizi kimseye sezdirmesin!"},{"n":20,"t":"Şüphesiz ki onlar, sizden haberdar olurlarsa sizi taşlarlar (kovarlar) veya sizi kendi dinlerine çevirirler ki o zaman asla kurtulamazsınız."},{"n":21,"t":"Böylece (insanları) onlardan haberdar etmiştik ki Allah’ın vaadinin gerçek olduğunu ve o (Son) Saat’te şüphe olmadığını bilsinler. Hani aralarında onların durumunu tartışıyor ve şöyle diyorlardı: “Üzerlerine bir bina yapın! Rableri onları çok iyi bilendir.” Onların durumunu bilenler ise “Biz elbette onların üzerlerine (yanlarına) bir mescit yapacağız” demişlerdi."},{"n":22,"t":"(Bazıları) gayba taş atarak (tahmin yürüterek) “(Onlar) üç kişidir; dördüncüleri köpekleridir.” derler. (Bazıları) “(Onlar) beş kişidir; altıncıları köpekleridir.” derler. (Kimileri de) “(Onlar) yedi kişidir; sekizincisi köpekleridir.” derler. De ki: “Onların sayılarını Rabbim gayet iyi bilendir.” Onları sadece az kişi bilir(di). Öyle ise onlar hakkında delillerin apaçık olması dışında bir tartışmaya girme ve onlar hakkında (konuşan) kişilerin hiçbirinden soru sorma!"},{"n":23,"t":"Hiçbir şey için sakın “Bunu yarın mutlaka yapacağım.” deme!"},{"n":24,"t":"“Ancak Allah dilerse (yapacağım.” de)! Unuttuğun zaman Rabbini an ve “Umarım Rabbim beni doğruya bundan daha yakın olana ulaştırır.” de!"},{"n":25,"t":"(Bazıları şöyle diyor): “Onlar, mağaralarında üç yüz sene kadar kalmış ve dokuz (sene) de buna ilave etmişlerdir.”"},{"n":26,"t":"De ki: “Ne kadar kaldıklarını Allah gayet iyi bilendir. Göklerin ve yerin gizli bilgisi yalnızca O’na aittir. O’nun görmesi de duyması da ne muhteşemdir! Onların (insanların) O’ndan başka bir dostu yoktur. O kendi hükmüne kimseyi ortak etmez.”"},{"n":27,"t":"Rabbinin Kitabı’ndan sana vahyedileni tilavet et (okuyup aktar)! O’nun sözlerini (kanunlarını) değiştirebilecek yoktur. O’ndan başka hiçbir sığınak da asla bulamazsın."},{"n":28,"t":"O’nun rızasını isteyerek Rablerine sabah akşam dua edenlerle birlikte olmaya devam et! Dünya hayatının süsünü isteyerek gözlerini onlardan çevirme! Arzusuna uymuş ve işi gücü aşırılık olduğu için kalbini bizi hatırlamaktan habersiz kıldığımız kimseye boyun eğme!"},{"n":29,"t":"De ki: “Hak (gerçek), Rabbinizdendir.” Öyle ise dileyen iman etsin; dileyen inkâr etsin! Biz, zalimlere öyle bir ateş hazırladık ki (ateşten) duvarları kendilerini çepeçevre kuşatmıştır. Yardım dileyecek olsalar, erimiş maden gibi yüzleri haşlayan bir su ile yardım edilir. Ne fena bir içecektir o ve ne kötü bir kalma yeridir orası!"},{"n":30,"t":"İman edip iyi işler yapanlar (bilmelidir ki), biz güzel iş yapanların ödülünü boşa çıkarmayacağız."},{"n":31,"t":"İşte onlara, altlarından ırmaklar akan durmaya değer cennetler vardır. Onlar orada koltuklara kurularak altın bileziklerle süslenip bezenecek; ince ve kalın ipekli kumaştan yeşil elbiseler giyecekler. Ne güzel karşılıktır o ve ne güzel kalma yeridir orası!"},{"n":32,"t":"Onlara şu iki adamı örnek ver: Bunlardan birine iki üzüm bağı vermiş, her ikisinin de çevresini hurmalarla donatmış, aralarında da ekinler yetiştirmiştik."},{"n":33,"t":"O iki bağ da yemişlerini vermiş, hiçbirini eksik bırakmamıştı. İkisinin arasından bir de nehir fışkırtmıştık."},{"n":34,"t":"Bu kişinin bolca ürünü vardı. Arkadaşıyla konuşurken ona şöyle demişti: “Ben servetçe senden daha zenginim; nüfus bakımından da senden daha güçlüyüm.”"},{"n":35,"t":"(Bu şımarık kişi) kendisine haksızlık ederek bağına girmiş ve şöyle demişti: “Bunun (bağın) hiçbir zaman yok olacağını sanmıyorum."},{"n":36,"t":"O (Son) Saat’in gerçekleşeceğini de sanmıyorum. Rabbime döndürülürsem, (orada) bundan daha hayırlı bir karşılık mutlaka bulacağım.”"},{"n":37,"t":"Onunla konuşan arkadaşı ona şöyle demişti: “Seni topraktan, sonra nutfeden (zigottan) yaratan, daha sonra seni bir erkek (insan) biçimine sokan (Allah)ı inkâr mı ettin?"},{"n":38,"t":"Fakat O, Allah’tır; Rabbimdir ve ben Rabbime hiçbir şeyi ortak koşmam.”"},{"n":39,"t":"39-40 Bahçene girdiğinde “Maşallah! Kuvvet yalnızca Allah’a aittir.” deseydin ya! “Malca ve evlatça beni kendinden güçsüz görüyorsan, (şunu bil ki) belki Rabbim bana senin bahçenden daha iyisini verir; oraya (bahçene) gökten yıldırımlar gönderir ve kupkuru bir toprak hâline gelir."},{"n":40,"t":"39-40 Bahçene girdiğinde “Maşallah! Kuvvet yalnızca Allah’a aittir.” deseydin ya! “Malca ve evlatça beni kendinden güçsüz görüyorsan, (şunu bil ki) belki Rabbim bana senin bahçenden daha iyisini verir; oraya (bahçene) gökten yıldırımlar gönderir ve kupkuru bir toprak hâline gelir."},{"n":41,"t":"Veya (bahçenin) suyu dibe çekilir de onu istemeye (elde etmeye) asla güç yetiremezsin.”"},{"n":42,"t":"(O şımarık kişinin) serveti kuşatılmıştı (yok edilmişti). Böylece, çardakları üzerine yıkılmış hâlde (bahçesiyle ilgili) yaptığı harcamalar yüzünden ellerini ovuşturarak şöyle diyordu: “Ah, eyvah, keşke Rabbime kimseyi ortak koşmamış olsaydım!”"},{"n":43,"t":"Kendisine Allah’tan başka yardım edecek destekçileri yoktu. Kendi kendini de kurtaracak güçte değildi."},{"n":44,"t":"İşte burada yardım ve dostluk gerçek olan Allah’a aittir. O sevap bakımından hayırlı olandır; son bakımından da hayırlı olandır."},{"n":45,"t":"Onlara şunu da örnek ver: “Dünya hayatının durumu gökten indirdiğimiz bir su gibidir ki yerin bitki(ler)i o (su) sayesinde (gürleşip) birbirine karışmış, rüzgârların savurduğu çer çöp hâline gelmiştir.” Allah her şey üzerinde güç sahibidir."},{"n":46,"t":"Mal ve çocuklar dünya hayatının süsüdür. İyi işlerden oluşan kalıcı faaliyetlerin hem ödül bakımından hayırlı olandır hem de ümit beslenmesi Rabbinin katında hayırlı olandır."},{"n":47,"t":"Dağları yürüteceğimiz gün yeryüzünü çıplak (dümdüz) görürsün. Hiçbirini bırakmaksızın onları (mahşerde) toplayacağız."},{"n":48,"t":"Hepsi sıra sıra Rabbinin huzuruna çıkarılacak ve (kendilerine) şöyle denecektir: “Şüphesiz ki sizi ilk yarattığımız şekilde bize geldiniz. Aslında sizin için böyle bir buluşmayı asla gerçekleştiremeyeceğimizi sanmıştınız.”"},{"n":49,"t":"Kitap (amel defteri) ortaya konulacaktır. Suçluların, onda yazılı olanlardan korkmakta olduklarını göreceksin. (Onlar) “Ah, vay hâlimize! Bu nasıl kitapmış! Küçük büyük hiçbir şey bırakmaksızın hepsini sayıp dökmüş!” diyecekler. Yaptıklarını (karşılarında) hazır bulacaklardır. Rabbin, kimseye haksızlık etmeyecektir."},{"n":50,"t":"Hani meleklere “Âdem için (Allah’a) secde edin!” demiştik. Onlar da hemen secde etmişlerdi. İblis hariç. (Zaten O) cinlerdendi ve Rabbinin emrinden dışarı çıkmıştı. (Şimdi siz) benim peşim sıra onu ve onun soyunu mu dostlar ediniyorsunuz? Oysa onlar sizin için düşmandır. Zalimler için bu ne kötü bir değişimdir!"},{"n":51,"t":"Ben onları (İblis ve soyunu) göklerin ve yerin yaratılışına da kendilerinin yaratılışına da şahit tutmadım. Ben yoldan çıkaranları yardımcı edinecek değilim."},{"n":52,"t":"O gün (Allah, kâfirlere) “Benim ortaklarım olduğunu sandıklarınızı çağırın!” diyecek; onlar da kendilerini(!) çağırmış (fakat ortakları) onlara cevap verememiş olacaklardır. Biz onların arasına uçurum koyacağız."},{"n":53,"t":"Suçlular ateşi görür görmez, orayı boylayacaklarını iyice anlamış olacaklar; ondan kaçış (kurtuluş yolu) da bulamayacaklardır."},{"n":54,"t":"Yemin olsun ki bu Kur’an’da insanlar için her türlü örneği sayıp dökmüşüzdür. (Nankör) insan tartışmaya en çok düşkün olandır."},{"n":55,"t":"Kendilerine rehber geldiğinde insanları iman etmekten ve Rablerinden bağışlanma dilemekten alıkoyan şey, öncekilere (uygulanan) kanunun kendilerine de gelmesini veya azabın önlerine gelmesini beklemekten başka bir şey değildir!"},{"n":56,"t":"Biz, elçileri sadece müjdeleyiciler ve uyarıcılar olarak göndeririz. kâfir olanlar ise gerçeği batılla gidermek için mücadele ederler. Onlar ayetlerimle ve uyarıldıkları şeylerle alay etmişlerdir."},{"n":57,"t":"Kendisine Rabbinin ayetleri hatırlatılıp da onlara sırt çevirenden, kendi elleriyle yaptıklarını unutanlardan daha zalim kim olabilir ki! Şüphesiz ki onu (Kur’an’ı) anlamaları konusunda biz onların kalplerine perdeler, kulaklarına da (s) ağırlık verdik. Sen onları doğru yola çağırsan da asla doğru yola gelmeyeceklerdir."},{"n":58,"t":"Senin çok bağışlayan Rabbin merhamet sahibidir. Yaptıkları yüzünden onları (hemen) sorumlu tutacak olsaydı, onlara azabı çabucak verirdi. Fakat kendilerine (tanınmış) belirli bir süre vardır ki O’ndan başka bir sığınak asla bulamayacaklardır."},{"n":59,"t":"İşte haksızlık ettikleri zaman şu şehirler(in halkları)nı helak etmiştik. Onları helak etmek için de belirli bir zaman belirlemiştik."},{"n":60,"t":"Hani Musa beraberindeki (gence) şöyle demişti: “Durup dinlenmeyeceğim; ya iki denizin birleştiği yere kadar varacağım ya da çok uzun süre yürüyeceğim.”"},{"n":61,"t":"İki denizin birleştiği yere varınca balıklarını unutmuşlardı. Balık da denizde bir yol tutmuştu (gözden kaybolup gitmişti)."},{"n":62,"t":"(İki denizin birleştiği yeri) geçip gittiklerinde (Musa beraberindeki) gence “Azığımızı bize getir! Şüphesiz ki bu yolculuğumuz nedeniyle çok yorulduk.” demişti."},{"n":63,"t":"(Genç) “Gördün mü (bak şu işe)! Kayaya sığındığımız sırada balığı(n denize düştüğünü söylemeyi) unutmuşum. Onu hatırlamamı bana şeytandan başkası unutturmadı.” demişti: O (balık), şaşılacak bir şekilde denizde yolunu tutup gitmişti."},{"n":64,"t":"(Musa) “İşte aradığımız (yer) orasıydı!” demiş, hemen izlerinin üzerine geri dönmüşlerdi."},{"n":65,"t":"(Derken), kendisine katımızdan bir rahmet verdiğimiz ve ona tarafımızdan bir ilim öğrettiğimiz kullarımızdan bir kul bulmuşlardı."},{"n":66,"t":"(Musa) ona “Doğruyu bulmak üzere sana öğretilenden bana da öğretmen için sana uyabilir miyim?” demişti."},{"n":67,"t":"(O bilge melek) şu cevabı vermişti: “Doğrusu sen benimle beraberliğe sabredemezsin."},{"n":68,"t":"(İç yüzünü) kavrayamadığın bir bilgiye nasıl sabredeceksin?”"},{"n":69,"t":"(Musa) “İnşallah sen beni sabreder bulacaksın. Senin emrine de karşı gelmeyeceğim.” demişti."},{"n":70,"t":"(Melek) “Bana uyarsan, sana o konuda bilgi verinceye kadar hiçbir şey hakkında bana soru sorma!” demişti."},{"n":71,"t":"Yola çıkmışlardı. Sonunda gemiye bindikleri zaman (melek) gemiyi delmişti. (Musa) “Halkını boğmak için mi onu deldin? Şüphesiz ki sen çok çirkin (tehlikeli) bir iş yaptın!” demişti."},{"n":72,"t":"(Melek) “Ben sana benimle beraberliğe sabredemezsin dememiş miydim?” demişti."},{"n":73,"t":"(Musa) “Unuttuğum şeyden dolayı beni sorumlu tutma; (bu) işimden dolayı beni ağır bir şekilde kınama.” demişti."},{"n":74,"t":"(Yeniden) yola koyulmuşlardı. Sonunda bir erkek çocuğa rastladıklarında (melek) onu hemen öldürmüştü. (Musa) şöyle demişti: “Tertemiz (suçsuz) bir canı, bir can karşılığı olmaksızın öldürdün, öyle mi? Şüphesiz ki sen fena bir şey yaptın!”"},{"n":75,"t":"(Bilge melek) “Ben sana benimle beraberliğe sabredemezsin dememiş miydim?” diye sormuştu."},{"n":76,"t":"(Musa) şöyle demişti: “Bundan sonra sana bir şey sorarsam artık benimle arkadaşlık etme! Elbette benim tarafımdan (ileri sürebilecek) mazeretin sonuna ulaştın.”"},{"n":77,"t":"Yine yola çıkmışlardı. Sonunda bir şehir halkına ulaşıp onlardan yiyecek istemişlerdi. Ancak (şehir halkı) onları misafir etmekten kaçınmıştı. Orada yıkılmak üzere bulunan bir duvarla karşılaşmışlardı. (Melek) hemen onu doğrultmuştu (tamir etmişti). (Musa) “Dileseydin, elbette buna karşı bir ücret alırdın.” demişti."},{"n":78,"t":"(Bunun üzerine melek): “İşte bu (durum) benimle senin aramızın ayrılmasıdır. Şimdi sana sabredemediğin şeylerin açıklamasını bildireceğim.” demişti."},{"n":79,"t":"“Gemi var ya o, denizde çalışan yoksul kişilerindi. Onu kusurlu kılmak istedim. (Çünkü) onların arkasında her (sağlam) gemiye el koymakta olan bir hükümdar vardı."},{"n":80,"t":"Erkek çocuğa gelince, onun ana babası mümin kişilerdi. Onları azdırıp inkâra sürüklemesini uygun görmemiştik."},{"n":81,"t":"Böylece Rablerinin onun yerine kendilerine, ondan daha temiz ve daha merhametlisini vermesini istemiştik."},{"n":82,"t":"Duvara gelince, o da şehirdeki iki öksüz çocuğa aitti. Duvarın altında onlara ait bir hazine vardı. Babaları iyi biriydi. Rabbin onların yetişkinlik çağına ulaşıp da kendi katından bir rahmet olarak hazinelerini çıkarmalarını istemişti. Ben bun(lar)ı kendiliğimden yapmadım. İşte bu (anlattıklarım) senin sabredemediğin şey(ler)in yorumudur."},{"n":83,"t":"Sana Zülkarneyn’den soruyorlar. De ki: “Size ondan bir hatıra tilavet edeceğim (okuyup aktaracağım).”"},{"n":84,"t":"Şüphesiz ki biz onu yeryüzünde iktidar sahibi kılmıştık; ona her şey için bir sebep (bir vasıta) vermiştik."},{"n":85,"t":"O da (batıya doğru) bir yol tutup gitmişti."},{"n":86,"t":"Sonunda güneşin battığı yere varınca, onu kara balçık bir (su) kaynağında batar bulmuştu. Onun yanında (orada) bir toplum bulmuştu. Bunun üzerine “Ey Zülkarneyn! Onlara ya (kötü yöneterek) azap edersin ya da haklarında güzel davranma yolunu seçersin.” demiştik."},{"n":87,"t":"(Allah) şöyle demişti: “Haksızlık edeni cezalandıracağız; sonra da Rabbine gönderilecek, (Allah) ona korkunç bir azap uygulayacaktır."},{"n":88,"t":"İman edip iyi işler yapan kimseye gelince, onun için de en güzel karşılık vardır. Buyruğumuzdan ona kolay olanını söyleyeceğiz.”"},{"n":89,"t":"Sonra (doğuya doğru) bir yol tutmuştu."},{"n":90,"t":"Sonunda güneşin doğduğu yere ulaşınca, onu öyle bir toplum üzerine doğar buldu ki onlar için onun ardında (güneşe karşı) bir örtü yapmamıştık."},{"n":91,"t":"İşte böylece onunla ilgili her şeyden haberdardık."},{"n":92,"t":"Sonra (farklı) bir yol tutmuştu."},{"n":93,"t":"Sonunda iki set (dağ) arasına ulaştığında onların önünde, neredeyse hiçbir sözü anlayamayan bir toplum bulmuştu."},{"n":94,"t":"(O toplum) şöyle demişti: “Ey Zülkarneyn! Şüphesiz ki Ye’cûc ve Me’cûc yeryüzünde bozgunculuk yapmaktadır. Bizimle onlar arasında bir set yapman için sana bir vergi verelim, olur mu?”"},{"n":95,"t":"(Zülkarneyn) şöyle demişti: “Rabbimin beni içinde bulundurduğu kudret daha hayırlıdır. Siz bana kuvvetinizle destek olun da sizinle onlar arasına aşılmaz bir engel yapayım."},{"n":96,"t":"Bana demir kütleleri getirin!” Sonunda dağın iki yanı arasını aynı seviyeye getirince “Üfleyin (körükleyin)!” demişti. Onu kor hâline sokunca da “Getirin bana, üzerine bir miktar erimiş bakır dökeyim.” demişti."},{"n":97,"t":"(Artık Ye’cûc ve Me’cûc) o (seddi) ne aşabilmiş ne de onu delebilmişlerdi."},{"n":98,"t":"(Zülkarneyn) “Bu, Rabbimden bir rahmettir. Fakat Rabbimin vaadi gelince, O bunu yerle bir eder. Rabbimin vaadi gerçektir.” demişti."},{"n":99,"t":"O gün (kıyamet gününde bakarsın ki) biz onları birbirine karışmış bir hâlde bırakmışızdır. Sûr’a da üflenecek, böylece onları tamamen bir araya getireceğiz."},{"n":100,"t":"100-101 Gözleri beni anmaya kapalı olmuş ve (gerçeği) duymaya da dayanamayan kâfirleri o gün cehennemle yüz yüze getireceğiz."},{"n":101,"t":"100-101 Gözleri beni anmaya kapalı olmuş ve (gerçeği) duymaya da dayanamayan kâfirleri o gün cehennemle yüz yüze getireceğiz."},{"n":102,"t":"Kâfir olanlar, benim peşim sıra kullarımı dostlar edineceklerini mi sandılar! Biz cehennemi kâfirlere bir konak olarak hazırladık."},{"n":103,"t":"De ki: “(Yaptıkları) işler bakımından en çok kaybedenleri size bildirelim mi?"},{"n":104,"t":"(Bunlar) iyi işler yaptıklarını sandıkları hâlde dünya hayatında çabaları boşa giden kişilerdir.”"},{"n":105,"t":"İşte onlar, Rablerinin ayetlerini ve O’na kavuşmayı inkâr eden, bu yüzden işleri boşa giden kişilerdir ki biz onlar için kıyamet gününde hiçbir ölçü (terazi) tutmayacağız."},{"n":106,"t":"İşte, inkâr ettikleri için, (ayrıca) ayetlerimle ve elçilerimle alay ettikleri için onların cezası cehennemdir."},{"n":107,"t":"İman edip iyi işler yapanlara gelince, onlar için makam olarak Firdevs cennetleri vardır."},{"n":108,"t":"Orada ebedî kalacaklardır. Oradan hiç ayrılmak istemezler."},{"n":109,"t":"De ki: “Rabbimin sözleri(ni yazmak) için deniz mürekkep olsa ve bir o kadar da ilave getirsek, Rabbimin sözleri bitmeden önce deniz tükenirdi.”"},{"n":110,"t":"De ki: “Ben yalnızca sizin gibi bir insanım. Bana ‘ilahınızın tek bir ilah olduğu’ vahyolunuyor.” Artık kim Rabbine kavuşmayı umuyorsa iyi işler yapsın ve Rabbine ibadette kimseyi ortak koşmasın!"}],[{"n":1,"t":"Kâf. Hâ. Yâ. ‘Ayn. Sâd."},{"n":2,"t":"(Bu), Rabbinin Zekeriya kuluna rahmetini hatırla(t)masıdır."},{"n":3,"t":"Hani o, gizli bir sesle Rabbine şöyle seslenmişti:"},{"n":4,"t":"“Rabbim! Kemiklerim zayıfladı, saçım başım ağardı. Rabbim, senden isteklerim konusunda (bu zamana kadar) hiç mahrum kalmadım."},{"n":5,"t":"5-6 Şüphesiz ki ben, benden sonraki yakınlarımdan endişe ediyorum. Hanımım da kısırdır. Bana katından hem bana hem de Yakup ailesine mirasçı olabilecek bir veli (çocuk) ver! Rabbim! Onu rızana layık eyle!”"},{"n":6,"t":"5-6 Şüphesiz ki ben, benden sonraki yakınlarımdan endişe ediyorum. Hanımım da kısırdır. Bana katından hem bana hem de Yakup ailesine mirasçı olabilecek bir veli (çocuk) ver! Rabbim! Onu rızana layık eyle!”"},{"n":7,"t":"(Melekler şöyle demişti:) “Ey Zekeriya! Sana daha önce kimseye vermediğimiz (benzeri olmayan), ismi Yahya olan bir erkek çocuk müjdeliyoruz.”"},{"n":8,"t":"(Zekeriya), “Rabbim! Hanımım kısır, ben de yaşlılığımın sonuna ulaşmışken nasıl benim bir oğlum olacak?” diye sormuştu."},{"n":9,"t":"(Melek) şu cevabı vermişti: “Öyle, (ama) Rabbin ‘Bu (iş) benim için kolaydır. Sen daha önce hiçbir şey değilken seni ben yaratmıştım’ demişti.”"},{"n":10,"t":"(Zekeriya) “Rabbim! (Bu konuda) bana bir delil ver.” demişti. (Melek) “Senin delilin, sapasağlam olduğun hâlde (üç gün) üç gece insanlarla konuşamamandır.” cevabını vermişti."},{"n":11,"t":"(Bu sırada Zekeriya) mabetten kavminin karşısına çıkarak onlara “Sabah akşam tesbih edin (Allah’ı yüceltin)!” diye vahyetmişti (işaret etmişti)."},{"n":12,"t":"12-13 “Ey Yahya! Kitab'a (Tevrat’a) sımsıkı sarıl!” (demiştik) ve henüz küçük çocukken ona muhakeme gücü, katımızdan şefkat ve arınmışlık vermiştik; o da takvâlı (duyarlı) biriydi."},{"n":13,"t":"12-13 “Ey Yahya! Kitab'a (Tevrat’a) sımsıkı sarıl!” (demiştik) ve henüz küçük çocukken ona muhakeme gücü, katımızdan şefkat ve arınmışlık vermiştik; o da takvâlı (duyarlı) biriydi."},{"n":14,"t":"Ona ana babasına iyilik yapmasını (emretmiştik); o da asi zorba biri değildi."},{"n":15,"t":"Doğduğu gün, öleceği gün ve sağ olarak diriltileceği gün selam onun üzerine olsun!"},{"n":16,"t":"Kitapta Meryem’i de hatırla! Hani o, ailesinden ayrılarak doğu tarafında bir yere gitmişti."},{"n":17,"t":"(Kendisini görmemeleri için) onların aşağı tarafından bir perde çekmişti. Biz ona düzgün bir insan şeklinde görünen rûhumuzu (Cebrail’i) göndermiştik."},{"n":18,"t":"(Meryem) “Takvâlı (duyarlı) biriysen, senden Rahmân’a sığınıyorum.” demişti."},{"n":19,"t":"(Cebrail) “Ben sana tertemiz bir erkek çocuk vermem için Rabbinin sadece bir elçisiyim.” demişti."},{"n":20,"t":"(Meryem) “Bana hiçbir insan dokunmamışken ve üstelik ahlaksız olmadığım hâlde benim nasıl çocuğum olabilir ki?” demişti."},{"n":21,"t":"(Cebrail ise) şöyle demişti: “Öyle, (ama) Rabbin ‘O (iş) benim için kolaydır. Biz onu insanlara bir ayet (mucize) ve katımızdan bir rahmet kılmak için (böyle yapacağız. Zaten bu iş), karara bağlanmış (olmuş bitmiş) bir iştir’ demiştir.”"},{"n":22,"t":"(O esnada Meryem) çocuğa hamile kalmış ve onunla uzak bir yere çekilmişti."},{"n":23,"t":"(Zamanı geldiğinde) doğum sancısı onu bir hurma ağacının gövdesine yaslanmaya zorlamıştı da “Ah, keşke bundan önce ölseydim ve unutulup gitseydim!” demişti."},{"n":24,"t":"(Cebrail, ağacın) alt tarafından ona şöyle seslenmişti: “Sakın üzülme! Elbette Rabbin senin alt tarafında bir su arkı var etmiştir."},{"n":25,"t":"Hurmanın gövdesini kendine doğru silkele ki (ağaç) sana taze hurma döksün."},{"n":26,"t":"Ye, iç; gözün aydın olsun! Herhangi bir insan görürsen de ki: ‘Ben Rahmân için oruç adadım; bugün hiçbir insanla konuşmayacağım.”"},{"n":27,"t":"Onu (çocuğunu) taşıyarak kavmine getirmişti. Demişlerdi ki: “Ey Meryem! Şüphesiz ki sen çok iğrenç bir şey yaptın!"},{"n":28,"t":"Ey Harun’un kız kardeşi! Baban kötü bir kişi değildi; annen de ahlaksız değildi”"},{"n":29,"t":"(Meryem) ona (çocuğa) işaret etmişti. Onlar da “Beşikteki bir bebekle nasıl konuşuruz!” demişlerdi."},{"n":30,"t":"(İsa) şöyle demişti: “Ben Allah’ın kuluyum. O, bana Kitabı verdi ve beni peygamber yaptı."},{"n":31,"t":"Beni bulunduğum her yerde bereketli kıldı. Yaşadığım sürece salâtı (namazı) ve zekâtı bana emretti."},{"n":32,"t":"Beni, anneme iyilik yapar (saygılı) kıldı ve beni azgın bir zorba yapmadı."},{"n":33,"t":"Doğduğum gün, öleceğim gün ve sağ olarak diriltileceğim gün selam banadır.”"},{"n":34,"t":"İşte, hakkında tartıştıkları Meryem oğlu İsa ile ilgili doğru söz budur."},{"n":35,"t":"Allah asla çocuk edinmemiştir. (Haşa)! O, yücedir. Bir işe hükmettiği zaman ona sadece “Ol!” der; o da hemen olmaya başlar."},{"n":36,"t":"(İsa şunu söylemiştir:) “Şüphesiz ki Allah benim de Rabbimdir; sizin de Rabbinizdir. O’na kulluk edin! Doğru yol budur.”"},{"n":37,"t":"(Çeşitli) gruplar kendi aralarında (İsa hakkında) ayrılığa düştüler. Büyük günün şahitliği nedeniyle kâfir olanların vay hâllerine!"},{"n":38,"t":"Huzurumuza gelecekleri gün (gerçeği) nasıl da duyacak ve nasıl da görecekler! Fakat o zalimler, bugün apaçık bir şaşkınlıktadır."},{"n":39,"t":"Hükmün kesinleştiği o pişmanlık günü hakkında onları uyar! Onlar gaflettedir ve (ahirete) inanmazlar."},{"n":40,"t":"Yeryüzüne ve onun üzerindekilere ancak biz vâris oluruz; üstelik onlar da sadece bize döndürüleceklerdir."},{"n":41,"t":"Kitapta İbrahim’i de hatırla! Şüphesiz ki o, çok doğrulayıcı (biriydi), peygamberdi."},{"n":42,"t":"Hani babasına demişti ki: “Ey babacığım! Duyamayan, göremeyen ve sana hiçbir yarar sağlayamayacak şeylere niçin tapıyorsun?"},{"n":43,"t":"Ey babacığım! Şüphesiz ki sana gelmeyen bir ilim (Allah tarafından) bana geldi. Bana uy ki sana düzgün (doğru) yolu göstereyim."},{"n":44,"t":"Ey babacığım! Şeytana kulluk etme! Şüphesiz ki şeytan, Rahmân’a asi oldu."},{"n":45,"t":"Ey babacığım! Rahmân’dan sana azap dokunup da şeytanın dostu olmandan korkuyorum.”"},{"n":46,"t":"(Babası) şöyle demişti: “Ey İbrahim! Sen ilahlarımdan yüz mü çeviriyorsun? Vazgeçmezsen şüphesiz ki seni (taşlayarak) kovarım! Uzun bir süre benden uzak dur!”"},{"n":47,"t":"(İbrahim) şöyle demişti: “Selam sana! Rabbimden senin için bağışlanma dileyeceğim. Şüphesiz ki O, bana lütufkârdır."},{"n":48,"t":"Sizden de Allah’ın dışında yalvardığınız şeylerden de uzaklaşıyorum ve Rabbime yalvarıyorum. Umarım ki Rabbime duada mahrum olmam.”"},{"n":49,"t":"Sonunda (İbrahim) onlardan ve Allah’tan başka taptıkları şeylerden uzaklaşınca ona İshak’ı ve (bir süre sonra da torunu) Yakup’u bağışlamıştık; her birini de peygamber yapmıştık."},{"n":50,"t":"Onlara rahmetimizden lütufta bulunmuş ve kendilerine yüksek bir doğruluk dili vermiştik."},{"n":51,"t":"Kitapta Musa’yı da hatırla! Şüphesiz ki o samimi biriydi ve peygamber olan elçiydi."},{"n":52,"t":"Ona (Musa’ya) Tûr’un sağ tarafından seslenmiş ve özel bilgiler vermek için onu yaklaştırmıştık."},{"n":53,"t":"Merhametimiz gereği ona kardeşi Harun’u da peygamber olarak armağan etmiştik."},{"n":54,"t":"Kitapta İsmail’i de hatırla! Şüphesiz ki o hem sözünün eriydi hem de peygamber olan elçiydi."},{"n":55,"t":"Ayrıca o, ailesine (halkına) salâtı (namazı) ve zekâtı emrederdi. Rabbi katında da hoşnutluk kazanmış biriydi."},{"n":56,"t":"Kitapta İdris’i de hatırla! Şüphesiz ki o, çok doğrulayıcı (biriydi) ve peygamberdi."},{"n":57,"t":"Kendisini üstün bir makama yükseltmiştik."},{"n":58,"t":"İşte bunlar, Allah’ın Âdem’in soyundan kendilerine nimetler verdiği peygamberlerden, Nuh ile birlikte (gemide) taşıdıklarımızdan, İbrahim ve İsrail’in (Yakup’un) soyundan, doğruya ulaştırdığımız ve seçkin kıldığımız peygamberlerden bir bölümüdür. Onlara Rahmân’ın ayetleri tilavet edildiği (okunup aktarıldığı) zaman ağlayarak secde ederlerdi."},{"n":59,"t":"Onlardan hemen sonra salâtı (namazı/ibadeti) ziyan eden ve şehvetlere uyan bir nesil geldi. İleride bir cehennem çukuru ile karşılaşacaklardır."},{"n":60,"t":"Ancak (Allah’a) yönelen, iman edip iyi işler yapan(lar) cennete girecekler ve asla haksızlığa uğratılmayacaklardır."},{"n":61,"t":"Yani Rahmân’ın kullarına gıyaben vadettiği durmaya değer cennetlere (girecekler). Şüphesiz ki O’nun (Allah’ın) vaadi gerçekleşmiştir."},{"n":62,"t":"Orada herhangi bir boş söz duymayacaklar. Sadece ‘selam’ (duyacaklar). Onlar için orada sabah akşam rızıkları vardır."},{"n":63,"t":"Kullarımızdan takvâlı (duyarlı) olanları mirasçı kılacağımız cennet işte odur."},{"n":64,"t":"(Melekler) “Biz sadece Rabbinin emri ile ineriz. Önümüzde, arkamızda ve bunun arasında olan her şey yalnızca O’na (Allah’a) aittir. Rabbin unutkan değildir.” (demişlerdi)."},{"n":65,"t":"Göklerin, yerin ve ikisi arasındaki şeylerin Rabbi olan (Allah)’a kulluk et! O’na kullukta sabırlı (kararlı) ol! O’nun herhangi bir adaşı (benzeri) olduğunu mu biliyorsun!"},{"n":66,"t":"(İnkârcı) insan der ki: “Öldüğüm zaman mı (mahşerde) diri olarak (topraktan) çıkartılacağım!”"},{"n":67,"t":"O insan, daha önce hiçbir şey değilken onu yarattığımızı hiç hatırlamaz (düşünmez) mi?"},{"n":68,"t":"Rabbine yemin olsun: Şüphesiz ki onları (inkârcıları) ve şeytanları toplayacağız. Sonra elbette hepsini cehennemin çevresinde diz üstü hazır bulunduracağız."},{"n":69,"t":"Ardından her gruptan Rahmân’a en çok asi olanları kesin olarak çekip ayıracağız."},{"n":70,"t":"Sonunda oraya yaslanmaya en layık olanları elbette biz çok iyi bileniz."},{"n":71,"t":"(Ey inkârcılar)! Sizden oraya (cehenneme) girmeyecek kimse yoktur. Bu, Rabbinin katında kesinleşmiş bir hükümdür."},{"n":72,"t":"Sonra elbette biz takvâlı (duyarlı) olanları koruy(up kurtar)acağız; zalimleri ise diz üstü çökmüş olarak orada bırakacağız."},{"n":73,"t":"Kendilerine ayetlerimiz açıkça tilavet edildiği (okunup aktarıldığı) zaman, kâfir olanlar iman edenlere “İki gruptan hangisinin konumu daha iyidir ve meclis (topluluk) olarak hangisi daha güzeldir?” derlerdi."},{"n":74,"t":"(Oysa) kendilerinden önce güç ve gösteriş bakımından daha güzel olan nice nesilleri helak etmiştik."},{"n":75,"t":"(Onlara) de ki: “Rahmân, sapkınlıkta olanın (süresini) uzatsın (ne çıkar)! Sonunda ya (dünyadaki) azabı ya da o (Son) Saat’i gördükleri zaman, kimin konumunun daha kötü ve ordusunun daha güçsüz olduğunu anlayacaklardır.”"},{"n":76,"t":"Allah hidayete erenlerin hidayetini artırır. İyi davranışlardan oluşan kalıcı işler Rabbinin katında hem ödül bakımından hayırlı olandır hem de varacağı yer bakımından hayırlı olandır."},{"n":77,"t":"Ayetlerimizi inkâr edeni ve “Kuşkusuz bana mal da çocuk da verilecektir!” diyeni hiç düşündün mü?"},{"n":78,"t":"Bu kişi, gaybı (bilinemeyenleri) mi biliyor yoksa Rahmân’ın katında bir söz mü aldı?"},{"n":79,"t":"Hayır! Biz onun söylediğini yazacağız ve azabını da uzattıkça uzatacağız."},{"n":80,"t":"Dediğine biz vâris oluruz; kendisi de bize yapayalnız gelecektir."},{"n":81,"t":"Onlar, kendilerine itibar (kaynağı) olsunlar diye Allah’ın peşi sıra ilahlar edindiler."},{"n":82,"t":"Hayır! (Taptıkları putlar) onların ibadetlerini tanımayacak ve onlara hasım (düşman) olacaklardır."},{"n":83,"t":"Onları sürekli olarak kışkırtan şeytanları o kâfirlerin üzerine gönderdiğimizi düşünmedin mi hiç?"},{"n":84,"t":"Öyle ise onlar hakkında (azap gelmesi için) acele etme! Biz onların (günlerini) elbette teker teker sayıyoruz."},{"n":85,"t":"Rahmân’a karşı muttakî (duyarlı) olanları o gün misafir olarak toplayacağız."},{"n":86,"t":"Suçluları da susuz olarak cehenneme sevk edeceğiz."},{"n":87,"t":"O gün Rahmân’ın katında söz alandan başkaları şefaat (etme iznin)e sahip olamayacaklardır."},{"n":88,"t":"(Müşrikler) “Rahmân çocuk edindi!” dediler."},{"n":89,"t":"Şüphesiz ki çok çirkin bir şey ortaya attınız."},{"n":90,"t":"90-91 Rahmân’a çocuk yakıştırmaları nedeniyle neredeyse gökler çatlayacak, yer yarılacak ve dağlar yıkılıp düşecekti!"},{"n":91,"t":"90-91 Rahmân’a çocuk yakıştırmaları nedeniyle neredeyse gökler çatlayacak, yer yarılacak ve dağlar yıkılıp düşecekti!"},{"n":92,"t":"Çocuk edinmek Rahmân’a yakışmaz."},{"n":93,"t":"Göklerde ve yerde olan herkes elbette kul olarak Rahmân’a gelecektir."},{"n":94,"t":"Şüphesiz ki (Allah) onları kuşatmıştır ve teker teker onları sayıp tespit etmiştir."},{"n":95,"t":"Kıyamet günü hepsi O’nun huzuruna tek başına (yapayalnız) gelecektir."},{"n":96,"t":"Şüphesiz ki iman edip iyi işler yapanlar için Rahmân bir sevgi yaratacaktır."},{"n":97,"t":"Şüphesiz ki biz onu (Kur’an’ı) muttakîleri (duyarlı olanları) müjdeleyesin ve (gerçeğe) karşı çıkan bir topluluğu uyarasın diye senin diline kolaylaştırdık."},{"n":98,"t":"Onlardan önce nice nesilleri helak etmiştik. Sen onlardan herhangi birinden bir şey hissediyor veya onlara ait cılız bir ses (bile) duyabiliyor musun!"}],[{"n":1,"t":"Tâ. Hâ."},{"n":2,"t":"Biz Kur’an’ı sana sıkıntı çekesin diye indirmedik."},{"n":"3-4","t":"Yeri ve en yüksek gökleri yaratan (Allah)’ın indirmesi olarak saygı duyanlara sadece (gerçeği) hatırlatmak için (gönderdik)."},{"n":5,"t":"Rahmân arşa istiva etmiştir."},{"n":6,"t":"Göklerde, yerde, ikisi arasında ve toprağın altındaki her şey sadece O’na aittir."},{"n":7,"t":"Sözü açıktan söylesen de (O) gizliyi ve gizlinin gizlisini bilir."},{"n":8,"t":"Allah, kendisinden başka ilah olmayandır. En güzel isimler de yalnızca O’na aittir."},{"n":9,"t":"Musa’nın haberi sana ulaştı (değil) mi?"},{"n":10,"t":"Hani o, bir ateş görmüş ve ailesine, “(Siz burada) bekleyin! Bir ateş gördüm. Umarım ki ondan size bir kor (bir tutam ateş parçası) getiririm veya ateşin yanında bir rehber bulurum.” demişti."},{"n":11,"t":"Oraya ulaştığında (tarafımızdan) kendisine şöyle seslenilmişti:"},{"n":12,"t":"“Ey Musa! Şüphesiz ki ben -evet ben- senin Rabbin’im! Hemen ayakkabılarını çıkar! Şüphesiz ki sen (iki kez) kutsanmış tuvâ Vadi(si’n)desin!"},{"n":13,"t":"Seni (elçi olarak) ben seçtim. vahyedilmekte olanı dinle!"},{"n":14,"t":"Şüphesiz ki ben -evet ben- Allah’ım. Benden başka ilah yoktur. Bana kulluk et ve beni hatırlamak için namaz kıl!"},{"n":15,"t":"O (Son) Saat mutlaka gelecektir. Herkese, peşinde koştuğu şeyin karşılığı verilsin diye neredeyse onu (kendimden bile) gizleyeceğim."},{"n":16,"t":"Ona inanmayıp arzusuna uyanlar sakın seni ona (Son Saat’e inanmak)tan alıkoymasın; sonra mahvolursun!"},{"n":17,"t":"Ey Musa, şu sağ elindeki nedir, bilir misin?” (diye sormuştu)."},{"n":18,"t":"(Musa) “O benim asamdır; ona dayanır, onunla davarlarıma yaprak silkelerim. Benim ona başka ihtiyaçlarım da vardır.” demişti."},{"n":19,"t":"(Allah) “Onu (yere) at ey Musa!” demişti."},{"n":20,"t":"(Musa da) hemen onu yere atmıştı. Bir de ne görsün, o (asa) yılan olmuş sürünüyor."},{"n":21,"t":"(Allah) “Onu al ve korkma! Biz onu eski hâline çevireceğiz."},{"n":22,"t":"22-23 Elini koltuğunun altına koy; en büyük ayetlerimizden (mucizelerimizden) birini sana göstermemiz için bir başka ayet (mucize) olarak elin kusursuz ve lekesiz beyazlıkta çıkacaktır” demişti."},{"n":23,"t":"22-23 Elini koltuğunun altına koy; en büyük ayetlerimizden (mucizelerimizden) birini sana göstermemiz için bir başka ayet (mucize) olarak elin kusursuz ve lekesiz beyazlıkta çıkacaktır” demişti."},{"n":24,"t":"(Allah şöyle demişti): “Firavun’a git! O iyice azdı.”"},{"n":25,"t":"(Musa ise) şöyle dua etmişti: “Rabbim! Benim için yüreğime genişlik ver!"},{"n":26,"t":"İşimi bana kolaylaştır!"},{"n":27,"t":"27-28 Dilimden bağı çöz ki sözümü anlasınlar."},{"n":28,"t":"27-28 Dilimden bağı çöz ki sözümü anlasınlar."},{"n":29,"t":"29-30 Bana ailemden kardeşim Harun’u vezir (yardımcı) görevlendir!"},{"n":30,"t":"29-30 Bana ailemden kardeşim Harun’u vezir (yardımcı) görevlendir!"},{"n":31,"t":"Onunla arkamı güçlendir."},{"n":32,"t":"Onu işime ortak (destekçi) kıl."},{"n":33,"t":"Bu sayede seni çok tesbih edelim (yüceltelim)."},{"n":34,"t":"Seni çok analım!"},{"n":35,"t":"Şüphesiz ki sen bizi görensin.”"},{"n":36,"t":"(Allah) şöyle demişti: “Ey Musa! İstediklerin sana elbette verildi."},{"n":37,"t":"Yemin olsun ki sana bir kez daha bir lütufta bulunmuştuk."},{"n":38,"t":"Hani annene vahyedilecek şeyi şöyle vahyetmiştik (bildirmiştik):"},{"n":39,"t":"“Onu (Musa’yı) sandığa koy ve onu nehre bırak! Nehir onu kıyıya bıraksın; benim de onun da düşmanı olan biri onu alsın!” Sana tarafımdan bir sevgi vermiştim; böylece gözetimimde yetiştirilesin diye (böyle yapmıştık)."},{"n":40,"t":"Hani kız kardeşin (ablan, Firavun ailesine) gidip, “Ona bakacak birini size göstereyim mi?” demişti. Böylece, gözü aydın olsun ve (artık) üzülmesin diye seni annene geri vermiştik. (Gençken) birini öldürmüştün; seni endişeden kurtarmıştık; böylece seni iyiden iyiye denemiştik. (Bu nedenle), Medyen halkı arasında senelerce kalmıştın. Ey Musa! Sonra da bir plana göre (bu makama) gelmiştin."},{"n":41,"t":"Ben seni kendim için seçmiştim."},{"n":42,"t":"Sen ve kardeşin (Harun) delillerimle gidin! Beni anmada gevşek davranmayın!"},{"n":43,"t":"Firavun’a gidin; şüphesiz ki o iyice azdı."},{"n":44,"t":"Ona yumuşak söz söyleyin; umulur ki (gerçeği) hatırlar veya saygı duyar!”"},{"n":45,"t":"(Musa ve Harun) “Rabbimiz! Doğrusu, onun bize kötülük yapmasından veya iyice azmasından endişe ediyoruz.” demişlerdi."},{"n":46,"t":"(Allah ise şöyle) demişti: “Korkmayın, elbette ben sizinle beraberim, duyuyor ve görüyorum."},{"n":47,"t":"Ona (Firavun’a) gidin ve deyin ki: ‘Şüphesiz ki biz Rabbinin elçileriyiz. İsrailoğullarını bizimle gönder; onlara eziyet etme! Elbette biz sana Rabbinden bir delil ile geldik. Selam, rehbere (vayhe) uyanlara olacaktır."},{"n":48,"t":"Azabın, (gerçeği) yalanlayıp yüz çevirenlere (uygulanacağı) elbette bize vahyolunmuştur.”"},{"n":49,"t":"(Firavun) “Ey Musa! Rabbiniz de kimmiş?” demişti."},{"n":50,"t":"(Musa da) “Bizim Rabbimiz her şeye yaratılışını veren sonra da (yaratılışa uygun) yol gösterendir.” demişti."},{"n":51,"t":"(Firavun) “(Peki) önceki nesillerin hali ne olacak?” diye sormuştu."},{"n":52,"t":"(Musa ise) şöyle demişti: “Onlar hakkındaki bilgi Rabbimin katında bir kitaptadır. Rabbim şaşırmaz ve unutmaz.”"},{"n":53,"t":"(Allah) yeri sizin için beşik yapan, onda sizin için yollar açan ve gökten de su indirendir. O (su) saye(sin)de çeşitli bitkilerden de çiftler çıkarmıştık."},{"n":54,"t":"Yiyin; hayvanlarınızı otlatın! Şüphesiz ki bunda (kötülüklerden) engelleyen akıl sahipleri için deliller vardır."},{"n":55,"t":"Sizi topraktan yarattık; sizi yine oraya döndüreceğiz ve bir kez daha sizi oradan çıkaracağız."},{"n":56,"t":"Yemin olsun ki ona (Firavun’a) bütün delillerimizi göstermiştik; o ise yalanlamış ve yüz çevirmişti."},{"n":57,"t":"(Firavun) demişti ki: “Ey Musa! Yaptığın büyü ile bizi yurdumuzdan çıkarmaya mı geldin?"},{"n":58,"t":"Biz de sana, aynen onun gibi bir büyü yapacağız. Seninle bizim aramızda, senin de bizim de muhalefet etmeyeceğimiz uygun bir yerde buluşma zamanı ayarla!"},{"n":59,"t":"(Musa) şöyle demişti: “Buluşma zamanınız, süs günü ve insanların toplanacağı kuşluk vaktidir.”"},{"n":60,"t":"(Bunun üzerine Firavun) dönüp gitmiş, hilesini toplamış, sonra da (buluşma yerine) gelmişti."},{"n":61,"t":"Musa onlara şöyle demişti: “Yazıklar olsun size! Allah’a iftira etmeyin! Yoksa O da bir azap ile kökünüzü kazır! (Allah’a) iftira edenler elbette kaybedenlerdir.”"},{"n":62,"t":"(Büyücüler) durumlarını aralarında tartışmış, gizlice fısıldaşmışlardı."},{"n":63,"t":"Şöyle demişlerdi: “Bu ikisi (Musa ve Harun), büyüleriyle sizi yurdunuzdan çıkarmak ve örnek yolunuzu ortadan kaldırmak isteyen iki büyücüdür.”"},{"n":64,"t":"(Musa): “Hilenizi toplayın (yanınıza alın); sonra da sırayla gelin! Bugün üstün gelen elbette başaracaktır.”"},{"n":65,"t":"(Büyücüler) “Ey Musa, ya (önce asayı) sen atacaksın ya da ilk atanlar biz (mi) olalım?” demişlerdi."},{"n":66,"t":"(Musa) “Hayır, siz atın.” demişti. Bir de ne görsün, büyüleri sayesinde ipleri ve asaları gerçekten kendisine koşuyormuş gibi görünüyor."},{"n":67,"t":"Musa (o esnada) içinde bir korku hissetmişti."},{"n":68,"t":"(Biz de Musa’ya) şöyle demiştik: “Korkma! Şüphesiz ki sen galip geleceksin!"},{"n":69,"t":"Sağ elindekini (yere) at da onların yaptıklarını yutsun! Yaptıkları, sadece bir büyücü hilesidir. Büyücü ise nereye gelirse gelsin (ne yaparsa yapsın) başarılı olamaz.”"},{"n":70,"t":"(Büyücüler) secdeye kapanmış, “Harun’un ve Musa’nın Rabbine iman ettik!” demişlerdi."},{"n":71,"t":"(Firavun) şöyle demişti: “Ben size izin vermeden ona iman ettiniz, (öyle mi)! Şüphesiz ki o (Musa), size büyü öğreten büyüğünüzdür (akıl hocanızdır). Dönekliğ(iniz)den dolayı elbette ellerinizi ve ayaklarınızı kestireceğim. sizi elbette hurma dallarına asacağım! Hangimizin azabının daha şiddetli ve kalıcı olduğunu elbette bileceksiniz.”"},{"n":72,"t":"(Büyücüler) şöyle demişlerdi: “Bize gelen apaçık bilgilere ve bizi yoktan yaratana karşı asla seni tercih etmeyeceğiz. Yapacağını yap! Sen ancak bu dünya hayatında hükmünü geçirebilirsin."},{"n":73,"t":"Hatalarımızı ve senin bize zorla yaptırdığın büyüyü bağışlaması için Rabbimize iman ettik.” Allah hayırlı olandır; (ödülü ve azabı) daha kalıcıdır."},{"n":74,"t":"Kim Rabbine suçlu olarak gelirse, cehennem sadece onun içindir. Orada (tam olarak) ölemeyecek ve dirilemeyecektir."},{"n":75,"t":"Kim de iyi işler yapmış bir mümin olarak O’na gelirse, üstün dereceler sadece bunlar içindir."},{"n":76,"t":"(Yani) içlerinde ebedî kalacakları, altlarından ırmaklar akan durmaya değer cennetler. İşte (kötülüklerden) arınanların karşılığı budur."},{"n":77,"t":"Yemin olsun ki Musa’ya “Kullarımla birlikte geceleyin yola çık; yetişilmesinden korkmaksızın ve (boğulmaktan) endişe etmeksizin onlara denizde kuru bir yol aç!” diye vahyetmiştik."},{"n":78,"t":"Firavun, askerleriyle birlikte onların peşine düşmüştü. Denizde onları kuşatan şey (felaket) onları kuşatmıştı."},{"n":79,"t":"(Çünkü) Firavun, kavmini saptırmış ve (onlara) doğru yolu göstermemişti."},{"n":80,"t":"Ey İsrailoğulları! Elbette sizi düşmanınızdan kurtarmıştık; Tûr’un (Sînâ Dağı’nın) sağ tarafında (oraya gelmeniz için) sizinle sözleşmiş ve size kudret helvası ile bıldırcın eti ikram etmiştik."},{"n":81,"t":"Size rızık olarak verdiğimiz tertemiz şeylerden yiyin; bu konuda sınırı aşmayın! Sonra gazabım size gelir. Gazabım kime gelirse elbette o yıkılıp gitmiştir."},{"n":82,"t":"Şüphesiz ki ben (Allah’a) yönelen, iman edip iyi iş(ler) yapan, sonra da doğru yolda olan kimseyi çok bağışlayıcıyım."},{"n":83,"t":"Ey Musa! Seni kavminden (ayrılmak üzere) acele ettiren nedir ki!"},{"n":84,"t":"(Musa:) “Onlar benim arkamdalar. Rabbim! Memnun olasın diye sana (gelmek için) acele ettim.” demişti."},{"n":85,"t":"(Allah) şöyle buyurmuştu: “Elbette senden sonra biz kavmini imtihan etmiştik; Samiri onları yoldan çıkarmıştı.”"},{"n":86,"t":"(Bunun üzerine) Musa, öfkeli ve üzüntülü olarak kavmine dönmüş ve onlara şöyle demişti: “Ey kavmim! Rabbiniz size güzel bir vaatte bulunmamış mıydı? Size zaman mı çok uzun geldi; yoksa Rabbinizin gazabının size gelmesini mi istediniz ve bana verdiğiniz sözden döndünüz?”"},{"n":87,"t":"(Kavmi) şöyle demişti: “Biz sana verdiğimiz sözden kendi başımıza dönmedik. Fakat o kavmin (Mısırlıların) ziynetinden birtakım ağırlıklar yüklenmiştik. Onları (bırakıp) atmıştık. Aynı şekilde Samiri de (kendi taşıdığını oraya) bırakmıştı.”"},{"n":88,"t":"(Samiri), onlar için (önlerine), boğuk bir sese sahip ceset şeklinde bir buzağı heykeli çıkarmıştı. (Birbirlerine) “İşte bu, sizin de Musa’nın da ilahıdır. Fakat Musa (bunu) unuttu!” demişlerdi."},{"n":89,"t":"(O heykelin), kendilerine herhangi bir söz çevirip (söyleyemediğini), kendilerine hiçbir zarar da yarar da veremediğini görmüyorlar mı?"},{"n":90,"t":"Yemin olsun ki Harun, daha önce onlara “Ey kavmim! Siz bununla (buzağı heykeli ile) sadece imtihan edildiniz. Şüphesiz ki Rabbiniz Rahmân’dır; bana uyun ve emrime itaat edin!” demişti."},{"n":91,"t":"(Kavmi) “Musa bize dönünceye kadar (buzağı heykeline) boyun eğmeye devam edeceğiz!” demişti."},{"n":92,"t":"92-93 (Musa geldiğinde) “Ey Harun! Sapkınlığa düştüklerini gördüğünde bana uyman konusunda seni engelleyen neydi? Sen de mi emrime asi oldun?” demişti."},{"n":93,"t":"92-93 (Musa geldiğinde) “Ey Harun! Sapkınlığa düştüklerini gördüğünde bana uyman konusunda seni engelleyen neydi? Sen de mi emrime asi oldun?” demişti."},{"n":94,"t":"(Harun) şöyle demişti: “Ey annemin oğlu! Saçıma, sakalıma yapışma! Şüphesiz ki ben senin ‘İsrailoğullarının arasına ayrılık düşürdün; sözümü tutmadın!’ demenden korktum.”"},{"n":95,"t":"(Musa) “Ey Samiri! Ya senin durumun (derdin) nedir?” demişti."},{"n":96,"t":"O da “Ben onların göremediği (bir gerçeği) gördüm. Elçinin mesajından bir kısmını aldım ve onu attım. İşte böyle, bunu nefsim bana hoş gösterdi.” demişti."},{"n":97,"t":"(Musa) şöyle demişti: “Çık (git)! Artık hayatın boyunca sen sadece ‘Bana dokunmayın!’ diyeceksin. Ayrıca senin için, kurtulamayacağın bir sözleşme (ceza) günü daha var. Tapmakta olduğun ilahına bir bak! Elbette onu (heykelini) yakacağız; sonra da elbette onu parçalayıp denize savuracağız!"},{"n":98,"t":"Sizin ilahınız, kendisinden başka ilah olmayan Allah’tır. O’nun ilmi her şeyi kapsamıştır.”"},{"n":99,"t":"İşte böylece geçmiştekilerin haberlerinden bir bölümünü sana anlatıyoruz. Elbette sana tarafımızdan (gerçeği) hatırlatan (bir mesaj) verdik."},{"n":100,"t":"100-101 Ondan yüz çeviren kişi, kıyamet günü içinde ebedî kalacakları ağır bir günah yükünü yüklenecektir. Bu, onlar için kıyamet gününde ne kötü bir yüktür!"},{"n":101,"t":"100-101 Ondan yüz çeviren kişi, kıyamet günü içinde ebedî kalacakları ağır bir günah yükünü yüklenecektir. Bu, onlar için kıyamet gününde ne kötü bir yüktür!"},{"n":102,"t":"O gün Sûr’a üflenecektir ve biz o zaman suçluları, gözleri (korkudan) donuk bir hâlde toplayacağız."},{"n":103,"t":"Aralarında “Dünyada sadece on (gün) kaldınız.” diyerek fısıldaşacaklar."},{"n":104,"t":"İçlerinden yolu en iyi örnek olan (en akıllıları) “Sadece bir gün kaldınız.” dediğinde, (diğerlerinin) neler söyleyeceklerini çok iyi bileniz."},{"n":105,"t":"Sana (Son Saat’te) dağlar(ın durumun)dan soruyorlar. De ki: “Rabbim, onları şiddetli bir şekilde savuracaktır."},{"n":106,"t":"Orayı (yerlerini) dümdüz, bomboş bırakacaktır."},{"n":107,"t":"Orada hiçbir çukur ve tümsek göremeyeksin.”"},{"n":108,"t":"O gün insanlar yan çizemeyecekleri davetçiye uyacaklardır. Rahmân’ın (huzurunda) sesler kısılmış olacaktır. Fısıltıdan başka hiçbir şey duymayacaksın."},{"n":109,"t":"O gün Rahmân’ın izin verdiği ve sözünden razı olduğundan başkasına şefaat yarar sağlayamayacaktır."},{"n":110,"t":"(Allah şefaat bekleyenlerin) önündekilerini de arkalarındakini de bilir. Onlar, bilgi bakımından O’nu kuşatamazlar."},{"n":111,"t":"(Bütün) yüzler, gerçek diri ve hayatı elinde tutan (Allah) için boyun eğmiş (olacak)tır. Zulüm (şirk) yüklenen (yüzler) ise elbette perişan olacaktır."},{"n":112,"t":"Kim mümin olarak iyi işlerden yaparsa, artık o, haksızlıktan da hakkının çiğnenmesinden de korkmayacaktır."},{"n":113,"t":"Biz o (Kur’an’ı), insanlar takvâlı (duyarlı) olsunlar veya onlar için (gerçeği) hatırlama oluştursun diye Arapça bir Kur’an olarak indirdik ve uyarıları onda tekrar tekrar açıkladık."},{"n":114,"t":"Gerçek hükümdar olan Allah yücedir. Sana onun vahyi tamamlanmadan önce Kur’an’la ilgili acele etme ve “Rabbim! İlmimi artır!” de."},{"n":115,"t":"Yemin olsun ki biz daha önce de Âdem’e (ağaca yaklaşmaması için) ahit (emir) vermiştik de o unutmuştu ve onda bir kararlılık bulamamıştık."},{"n":116,"t":"Hani meleklere “Âdem için (Allah’a) secde edin.” demiştik; onlar da hemen secde etmişlerdi. İblis hariç. O, (secde etmemekte) direnmişti."},{"n":117,"t":"Demiştik ki: “Ey Âdem! Bu (İblis) hem senin için hem de eşin için düşmandır. Sakın sizi cennetten (bahçeden) çıkarmasın! Sonra sıkıntı çekersin."},{"n":118,"t":"Orada (cennette) acıkmayacak ve çıplak kalmayacaksın."},{"n":119,"t":"Orada susamayacak ve kuşluk sıcağından da etkilenmeyeceksin.”"},{"n":120,"t":"(Buna rağmen), şeytan ona (Âdem’e) vesvese verip “Ey Âdem! Sana ebedîlik ağacını ve sonu gelmez bir otoriteyi göstereyim mi?” demişti."},{"n":121,"t":"(Âdem ve eşi yasak ağaçtan) yemiş ve edep yerleri görünmüştü. (Ardından) bahçenin yapraklarından üzerlerine örtmeye başlamışlardı. (Böylece) Âdem (unutarak) Rabbine karşı gelmişti ve şaşmıştı."},{"n":122,"t":"Daha sonra Rabbi, onu (Âdem’i) seçkin kılmış, tevbesini (yönelmesini) kabul etmiş ve (ona) doğru yolu göstermişti."},{"n":123,"t":"(Allah) şöyle demişti: “Birbirinize düşman olarak hepiniz oradan (bahçeden) inin! Artık benden size bir hidayet geldiğinde, kim hidayetime uyarsa sapmayacak ve sıkıntı çekmeyecektir."},{"n":124,"t":"Kim de benim zikrimden (Kur’an’dan) yüz çevirirse, şüphesiz ki onun için sıkıntılı bir hayat olacak ve biz onu, kıyamet günü kör olarak dirilteceğiz.”"},{"n":125,"t":"(Bu kişi), “Rabbim! Beni neden kör olarak dirilttin? (Oysa) ben gören biriydim.” diyecektir."},{"n":126,"t":"(Allah) şöyle buyurmuş (olacak)tır: “İşte bu şekilde sana ayetlerimiz gelmişti de sen onları unutmuştun. Bugün sen de aynı şekilde unutulacaksın!”"},{"n":127,"t":"Haddi aşanları ve Rabbinin ayetlerine inanmamış olanları işte böyle cezalandıracağız. Ahiret azabı ise elbette daha şiddetlidir ve daha kalıcıdır."},{"n":128,"t":"Yurtlarında dolaştıkları kendilerinden önceki nice nesilleri helak etmiş olmamız, onlara bir yol göstermedi mi? Şüphesiz ki bunda, (kötülüklerden) engelleyen akıl sahipleri için deliller vardır."},{"n":129,"t":"Rabbinin sözü ve belirlenmiş bir süre olmasaydı (azap) kaçınılmaz olurdu."},{"n":130,"t":"Onların söylediklerine sabret! Güneşin doğuşundan önce ve batışından önce Rabbini hamd (övgü) ile tesbih et (yücelt)! Gecenin bir kısım saatlerinde ve gündüzün uçlarında da tesbih et (yücelt) ki huzur bulasın."},{"n":131,"t":"Sakın, içinde kendilerini denememiz için pek çok çifti yararlandırdığımız dünya hayatının süsüne gözlerini dikme! Rabbinin rızkı hem hayırlı olandır hem de daha kalıcıdır."},{"n":132,"t":"Ailene (destekçilerine) ibadeti (namazı) emret! Kendin de ona sabırla devam et! Senden rızık istemiyoruz; seni de biz rızıklandırıyoruz. (Mutlu) son, takvâlı (duyarlı olanlar) içindir."},{"n":133,"t":"(Kâfirler) “(Muhammed) bize Rabbinden bir ayet (mucize) getirseydi ya!” dediler. “Önceki sahifelerin (kitapların) açıklaması onlara gelmedi mi?”"},{"n":134,"t":"Biz (Vahiy göndermeden) önce onları bir azapla helak etseydik, “Rabbimiz! Bize bir elçi göndermen gerekmez miydi ki aşağılık duruma düşmeden ve perişan (rezil) olmadan önce ayetlerine uysaydık.” derlerdi."},{"n":135,"t":"De ki: “Herkes beklemektedir; siz de bekleyin! İleride düzgün yolda olan halkı ve doğru yola ulaşanların kimler olduğunu bileceksiniz!”"}],[{"n":1,"t":"İnsanların hesab(a çekilmeler)i yaklaştı. Onlar (ise) gaflet içinde yüz çevirmektedir."},{"n":2,"t":"2-3 Kendilerine, Rablerinden her yeni mesaj geldiğinde, onlar kalpleri eğlencede olduğu hâlde elbette bununla hep alay ederek dinlemişlerdi. O zalimler şu gizli fısıltıyı yapmışlardı: “Bu (Muhammed) sizin gibi bir insandan başka nedir ki! Siz şimdi göz göre göre büyüye mi geliyorsunuz?”"},{"n":3,"t":"2-3 Kendilerine, Rablerinden her yeni mesaj geldiğinde, onlar kalpleri eğlencede olduğu hâlde elbette bununla hep alay ederek dinlemişlerdi. O zalimler şu gizli fısıltıyı yapmışlardı: “Bu (Muhammed) sizin gibi bir insandan başka nedir ki! Siz şimdi göz göre göre büyüye mi geliyorsunuz?”"},{"n":4,"t":"(Peygamber) şöyle demişti: “Rabbim, yerde ve gökte(ki her) sözü bilir. O duyandır, bilendir.”"},{"n":5,"t":"(Müşrikler:) “Hayır! (Bunlar) karmakarışık rüyalardır; aksine onu kendisi uydurmuştur; dahası o bir şairdir. (Öyle değilse) bize hemen, öncekilere gönderilenin benzeri bir ayet (mucize) getirsin!” demişlerdi."},{"n":6,"t":"Bunlardan önce helak ettiğimiz hiçbir şehir (halkı) iman etmemişti; şimdi bunlar mı iman edecekler!"},{"n":7,"t":"Biz senden önce de kendilerine vahyettiğimiz erkeklerden başkasını (peygamber) olarak göndermedik. Bilmiyorsanız zikr (Kur’an) ehline sorun!"},{"n":8,"t":"Biz onları (peygamberleri), yemek yemeyen birer ceset olarak yaratmadık. Onlar (bu dünyada) ebedi kalıcı da değillerdi."},{"n":9,"t":"Sonra onlara (verdiğimiz) sözü yerine getirmiştik; böylece hem onları hem de dilediğimiz (layık olan) kişileri kurtarmış; haddi aşanları da helak etmiştik."},{"n":10,"t":"Şüphesiz ki size, içinde (gerçekleri) hatırlamanız (için bilgiler) bulunan bir kitap indirdik. Akıl etmiyor musunuz?"},{"n":11,"t":"Zalim olan nice şehir (halkını) kırıp geçirmiş; arkasından da başka topluluklar yaratmıştık."},{"n":12,"t":"Azabımızı hissettiklerinde bir de bakarsın ki oralardan (azap bölgesinden) kaçıyorlar!"},{"n":13,"t":"(Onlara şöyle demiştik:) “Kaçmayın! İçinde bulunduğunuz refaha ve yurtlarınıza dönün! Çünkü size sorular sorulacak!”"},{"n":14,"t":"(Onlar:) “Ah, eyvah bize! Şüphesiz ki biz zalimlermişiz!” demişlerdi."},{"n":15,"t":"Biz kendilerini yere serilmiş, hasat edilmiş (ekin)e çevirinceye kadar o feryatları sürüp gitmişti."},{"n":16,"t":"Biz göğü, yeri ve bunlar arasındakileri oyuncular olarak yaratmadık."},{"n":17,"t":"Bir eğlence edinmek isteseydik, onu kendi tarafımızdan edinirdik. (Ama) biz (bunu) yapanlar değiliz."},{"n":18,"t":"Aksine biz gerçeği batılın üzerine atarız da o, batılın işini bitirir. Bir de bakarsın ki batıl yok olup gitmiştir. (Allah’a) yakıştırdığınız sıfatlardan dolayı yazıklar olsun size!"},{"n":19,"t":"Göklerde ve yerde kim varsa hepsi yalnızca O’na aittir. O’nun huzurunda bulunanlar, O’na ibadetten dolayı kibirlenmez ve yorulmazlar."},{"n":20,"t":"Onlar, gece gündüz bıkmadan (Allah’ı) tesbih ederler (yüceltirler)."},{"n":21,"t":"Yoksa yerden (dünyevi) birtakım ilahlar edindiler de (ölüleri) onlar mı diriltecekmiş!"},{"n":22,"t":"O ikisinde (yerde ve gökte) Allah’tan başka ilahlar bulunsaydı, (düzenleri) elbette bozul(up gitmiş)ti. Arşın Rabbi olan Allah onların yakıştırdıkları (şeyler)den yücedir."},{"n":23,"t":"(Allah) yaptığından sorumlu tutulamaz; onlar ise sorguya çekileceklerdir."},{"n":24,"t":"Yoksa O’nun peşi sıra birtakım ilahlar mı edindiler! De ki: “Delilinizi getirin! Bu, benimle birlikte olanların ve benden öncekilerin (gerçeği içeren) öğretisidir.” Hayır! Onların çoğu gerçeği bilmezler; (bu yüzden) yüz çevirirler."},{"n":25,"t":"Senden önce hiçbir elçi göndermedik ki ona “Benden başka ilah yoktur; bana kulluk edin!” diye vahyetmiş olmayalım."},{"n":26,"t":"(Müşrikler): “Rahmân (olan Allah, melekleri) çocuk edindi!” dediler. (Haşa)! O yücedir. Aksine (melekler) ikram edilmiş kullardır."},{"n":27,"t":"O’ndan (emir almadan) önce konuşmaz, yalnızca O’nun emri ile iş yaparlar."},{"n":28,"t":"(Allah) onların önlerindekini de arkalarındakini de bilir. (Allah’ın) razı olduğundan başkasına şefaat edemezler. Onlar (Allah’a) saygıları nedeniyle titrerler!"},{"n":29,"t":"Onlardan kim “O’nun peşi sıra ben (de) ilahım!” derse biz onu (bile) cehennemle cezalandırırız. İşte biz, zalimlere böyle ceza veririz!"},{"n":30,"t":"Kâfir olanlar, göklerle yer bitişik bir hâldeyken, onları birbirinden ayırdığımızı ve her canlı şeyi sudan yarattığımızı gör(üp düşün)mediler mi? (Hâlâ) inanmayacaklar mı?"},{"n":31,"t":"Onları sarsmasıyla ilgili yerin içinde ağır baskılar yarattık. Yol bulsunlar diye orada geniş yollar yarattık."},{"n":32,"t":"Biz göğü korunmuş bir tavan yaptık. Onlar ise (göğün) delillerinden yüz çevirirler."},{"n":33,"t":"O, geceyi, gündüzü, güneşi ve ayı yaratandır. Hepsi bir(er) yörüngede yüzerler."},{"n":34,"t":"Senden önce (de) hiçbir insana çok uzun hayat vermedik. Şimdi sen ölürsen, onlar çok uzun süre mi kalacaklar!"},{"n":35,"t":"Her nefis (can), ölümü tadıcıdır. Bir deneme olarak sizi hayırla da şerle de imtihan ederiz. Sadece bize döndürüleceksiniz."},{"n":36,"t":"Kâfir olanlar seni gördükleri zaman “Sizin ilahlarınızı diline dolayan bu mu!” diyerek seninle hep alay ederler. (Oysa) onlar, Rahmân’ın zikrini (Kur’an’ı) inkâr edenlerin ta kendileridir."},{"n":37,"t":"İnsan aceleci (olarak) yaratılmıştır. Size delillerimi ileride göstereceğim; (azabı) benden acele istemeyin!"},{"n":38,"t":"“Doğruysanız o vaat (Son Saat) ne zamanmış!” derler."},{"n":39,"t":"Kâfir olanlar, yüzlerinden ve sırtlarından (saran) ateşi savamayacakları, kendilerine yardım edilemeyeceği zamanı (o günün dehşetini keşke) bir bilselerdi!"},{"n":40,"t":"Doğrusu o (Son Saat) kendilerine öyle ani gelir ki onları şaşırtır. Artık onu reddetmeye (geri çevirmeye) güçleri yetmez ve kendilerine bakılmaz da."},{"n":41,"t":"Yemin olsun ki senden önceki elçilerle de alay edilmişti ve alay edenleri alay ettikleri şey (çepeçevre) kuşatmıştı."},{"n":42,"t":"De ki: “Rahmân’dan (O’nun azabından) sizi gece gündüz kim koruyabilir ki!” Hayır! Onlar Rablerini hatırlamaktan yüz çevirirler."},{"n":43,"t":"Yoksa Allah’ın peşi sıra kendilerini (bize karşı) savunacak ilahlar mı varmış! (O ilahlar) hem kendilerine yardıma güç yetiremez hem de bizden sahiplenme göremezler."},{"n":44,"t":"(Oysa) onları da atalarını da yararlandırdık. Sonunda ömür kendilerine (hiç bitmeyecek gibi) uzun geldi. Yeryüzüne gelip, onu uçlarından eksilttiğimizi görmezler mi? Üstün gelen onlar mıymış!"},{"n":45,"t":"De ki: “Ben sizi sadece vahiy ile uyarıyorum.” Sağır(lar), uyarıldıkları zaman bu çağrıyı duymaz."},{"n":46,"t":"Onlara Rabbinin azabından ufak bir esinti dokunsa, elbette “Ah, eyvah bize! Şüphesiz ki biz zalimlermişiz!” derler."},{"n":47,"t":"Biz kıyamet günü için adalet terazileri kuracağız. Kimseye hiçbir şekilde haksızlık edilmeyecek. (Yapılan iş) bir hardal tanesi kadar bile olsa, onu (teraziye) getirmiş (olacağ)ız. Hesap görenler olarak biz yeteriz."},{"n":48,"t":"Yemin olsun ki biz Musa’ya ve Harun’a, muttakîler (duyarlı olanlar) için furkân’ı (doğruyu yanlıştan ayırma yeteneğini), aydınlığı ve (gerçeği) hatırlatan (öğüdü) vermiştik."},{"n":49,"t":"Onlar takvâ (duyarlılık) sahipleri, gaybdaki (bilinemeyendeki) Rablerine saygı duyarlar; (dahası) onlar o (Son) Saat’ten de tir tir titreyenlerdir."},{"n":50,"t":"İşte bu (Kur’an) da bizim indirdiğimiz bereket kaynağı bir hatırla(t)madır. Şimdi onu inkâr mı ediyorsunuz!"},{"n":51,"t":"Yemin olsun ki İbrahim’e olgunluğunu daha önce vermiştik. Biz onu iyi tanırdık."},{"n":52,"t":"Hani o, babasına ve kavmine “Şu tapmakta olduğunuz heykeller de ne oluyor?” diye sormuştu."},{"n":53,"t":"Onlar da “Biz atalarımızı bunlara tapanlar olarak bulduk.” demişlerdi."},{"n":54,"t":"(İbrahim) “Şüphesiz ki siz de atalarınız da apaçık bir sapkınlık içindesiniz!” demişti."},{"n":55,"t":"Onlar da “Bize gerçeği mi getirdin yoksa sen oyun oynayanlardan biri misin?” demişlerdi."},{"n":56,"t":"(İbrahim) “Hayır, sizin Rabbiniz, yoktan yarattığı göklerin ve yerin Rabbidir; ben buna şahitlik edenlerdenim.” demişti."},{"n":57,"t":"“Allah’a yemin olsun: Siz dönüp gittikten sonra putlarınıza elbette bir plan uygulayacağım!”"},{"n":58,"t":"(İbrahim), sonunda belki ona dönerler (sorarlar) diye büyükleri hariç onları (putları) paramparça etmişti."},{"n":59,"t":"(Kavmi) “Bunu ilahlarımıza kim yaptı? Şüphesiz ki o (bunu yapan kişi) zalimlerden biridir.” demişlerdi."},{"n":60,"t":"(Bir kısmı) “Bunları diline dolayan, kendisine ‘İbrahim’ denen bir genç duyduk.” demişlerdi."},{"n":61,"t":"“Onu hemen insanların gözü önüne getirin! Belki şahitlik ederler.” demişlerdi."},{"n":62,"t":"Onlar “Bunu ilahlarımıza sen mi yaptın ey İbrahim?” demişlerdi."},{"n":63,"t":"(İbrahim ise): “Belki de bu işi şu büyük olan yapmıştır. Konuşabiliyorlarsa onlara sorun!” demişti."},{"n":64,"t":"Kendilerine dönüp “Zalimler sizsiniz, siz!” demişlerdi."},{"n":65,"t":"Sonra (eski) kafalarına dönmüşler de “Sen bunların konuşamadığını pekâlâ biliyorsun!” (demişlerdi)."},{"n":66,"t":"(İbrahim) “Allah’ın peşi sıra size hiçbir yarar ve zarar veremeyen şeylere (hâlâ) tapacak mısınız?” demişti."},{"n":67,"t":"“Size de Allah’ın peşi sıra tapmakta olduğunuz şeylere de yazıklar olsun! Akıl etmiyor musunuz?”"},{"n":68,"t":"(Bir kısmı) “(Bir iş) yapacaksanız, onu (İbrahim’i) yakın da ilahlarınıza yardım edin!” demişti."},{"n":69,"t":"Biz de “Ey ateş! İbrahim için serinlik ve esenlik ol!” demiştik."},{"n":70,"t":"Ona tuzak kurmak istemişler; biz de onları, en çok kaybedenler hâline getirmiştik."},{"n":71,"t":"Onu ve Lut’u kurtararak, insanlar için bereketli kıldığımız toprağa (ulaştırmıştık)."},{"n":72,"t":"Ona (İbrahim’e) ilave (bir bağış) olarak İshak’ı ve (torunu) Yakup’u lütfetmiştik. Hepsini iyi insanlar yapmıştık."},{"n":73,"t":"Onları, emrimizle doğru yolu gösteren önderler yapmış ve kendilerine hayırlı işler yapmayı, namaz kılmayı ve zekât vermeyi vahyetmiştik. Onlar daima bizim kullarımızdılar."},{"n":74,"t":"Lut’a gelince, ona da doğru hüküm verme yeteneği ve ilim vermiştik. Onu çirkin işler yapmakta olan şehir (halkın)dan kurtarmıştık. Şüphesiz ki onlar kötü iş yapan yoldan çıkan bir toplumdu."},{"n":75,"t":"Onu (Lut’u) merhametimize yerleştirmiştik. Şüphesiz ki o da iyilerdendi."},{"n":76,"t":"Nuh’u da (an)! Daha önce bize dua etmişti. Biz de duasına cevap vermiş, böylece, onu ve ailesini (destekçilerini) büyük sıkıntıdan kurtarmıştık."},{"n":77,"t":"Onu, delillerimizi inkâr eden o toplumdan korumuştuk. Şüphesiz ki onlar, kötü bir toplumdu; hepsini (suda) boğmuştuk."},{"n":78,"t":"Davud’u ve Süleyman’ı da (an)! Hani içinde halkın koyunlarının yayıldığı bir ekin konusunda hüküm veriyorlardı. Biz onların hükmüne şahittik."},{"n":79,"t":"Böylece bunu (bu fetvayı) Süleyman’a biz öğretmiştik. Biz onların hepsine doğru hüküm verme yeteneği ve ilim vermiştik. Kuşları ve tesbih eden (yücelten) dağları da Davud’a boyun eğdirmiştik. (Bunları) biz yapmaktayız."},{"n":80,"t":"Ona, savaştan (düşmandan) sizi koruması için zırh yapmayı öğretmiştik. (Artık) şükredecek misiniz?"},{"n":81,"t":"Kasırga (gibi esen) rüzgârı da Süleyman’ın hizmetine vermiştik; O’nun emriyle içinde bereketli kıldığımız toprağa doğru akardı (eserdi). Biz her şeyi bilenleriz."},{"n":82,"t":"Şeytan(laşmış insan)lar arasından da onun için dalgıçlık yapan (inci çıkaran) ve bundan başka işler görenler vardı. Onları gözetim altında tutuyorduk."},{"n":83,"t":"Eyüp’ü de (an)! Hani Rabbine “Başıma bu dert geldi. Sen merhametlilerin en merhametlisisin.” diye seslenmişti."},{"n":84,"t":"Tarafımızdan bir merhamet ve kulluk edenler için bir hatırla(t)ma olmak üzere onun duasına cevap vermiş, kendisindeki sıkıntıyı gidermiş ve ona ailesini, ayrıca bunlarla birlikte bir mislini (beklemediği diğer yakınlarını) daha vermiştik."},{"n":85,"t":"İsmail’i, İdris’i ve Zülkifl’i de (an)! Hepsi de sabreden kişilerdendi."},{"n":86,"t":"Onları merhametimize yerleştirmiştik. Şüphesiz ki onlar da iyilerdendi."},{"n":87,"t":"Balık sahibini de (Yunus’u da an)! Hani o, kendisine gücümüzün yetmeyeceğini sanarak öfkeyle çekip gitmişti. Karanlıkların içinde şöyle dua etmişti: “(Rabbim)! Senden başka ilah yoktur; sen yücesin. Şüphesiz ki ben haksızlık edenlerden oldum.”"},{"n":88,"t":"Biz de onun bu duasına cevap vermiş ve (içine düştüğü) sıkıntıdan onu kurtarmıştık. Biz, müminleri işte böyle kurtarırız."},{"n":89,"t":"Zekeriya’yı da (an)! Hani o, Rabbine şöyle seslenmişti: “Rabbim! Beni yalnız bırakma! Sen vârislerin en hayırlısısın.”"},{"n":90,"t":"Biz onun da duasına cevap vermiş ve ona Yahya’yı bağışlamıştık; eşini de kendisi için (çocuk doğurmaya) elverişli kılmıştık. Onlar hayır işlerinde koşuşur, (merhametimizi) umarak ve (azabımızdan) korkarak bize yalvarırlardı. Onlar, bize saygı içindeydiler."},{"n":91,"t":"Namusunu korumuş olanı (Meryem’i de an)! Biz ona rûhumuzdan üflemiş, onu ve oğlunu âlemler (insanlar) için bir ayet (mucize) kılmıştık."},{"n":92,"t":"Şüphesiz ki bu (peygamberler ve iman edenler), tek bir ümmet olarak sizin ümmetinizdir. Ben de sizin Rabbinizim. Öyle ise bana kulluk edin!"},{"n":93,"t":"(İnsanlar) kendi aralarında işlerini paramparça ettiler. (Oysa) hepsi bize döneceklerdir."},{"n":94,"t":"Kim mümin olarak iyi işlerden yaparsa onun çabası görmezden gelinmez. Şüphesiz ki biz onu yazmaktayız."},{"n":95,"t":"Helak ettiğimiz bir şehir için artık (yenilenmek) imkânsızdır; şüphesiz ki onlar geri dönemeyeceklerdir."},{"n":96,"t":"Sonunda Ye’cûc ve Me’cûc (setleri) açıldığı, onlar her tepeden akın ettiği,"},{"n":97,"t":"Ve gerçek vaat (Son Saat) yaklaşınca, kâfir olanların gözleri birdenbire donakalır! (Onlar) “Ah, eyvah, yazıklar olsun bize! Elbette bu durumdan habersizmişiz; hatta biz zalimlermişiz!” (diyeceklerdir)."},{"n":98,"t":"Siz ve Allah’ın peşi sıra taptığınız şeyler cehennem yakıtısınız. Siz oraya gireceksiniz."},{"n":99,"t":"Onlar ilah olsalardı, oraya girmezlerdi. Hepsi orada ebedî kalacaklardır."},{"n":100,"t":"Orada onlar için inlemek vardır. Onlar orada (iyi haber) duyamayacaklardır."},{"n":101,"t":"Tarafımızdan kendileri için güzel (hüküm) verilmiş olanlara gelince, işte onlar cehennemden uzak tutulmuş olacaklardır."},{"n":102,"t":"Onun (cehennemin) uğultusunu bile duymayacaklardır; onlar canlarının istediği (nimetler) içinde ebedî kalıcıdır."},{"n":103,"t":"En büyük dehşet bile onları hüzünlendirmeyecektir. Melekler kendilerini şöyle karşılayacaktır: “İşte bu, size vadedilmiş olan (mutlu) gününüzdür.”"},{"n":104,"t":"O gün, yazılı kâğıt tomarlarını dürer gibi göğü toplayıp düreriz. İlk yaratmaya başladığımız gibi üzerimize aldığımız bir vaat olarak onu tekrar yaratacağız. Şüphesiz ki biz (vadettiğimizi) yaparız."},{"n":105,"t":"Yemin olsun ki Zikr’den (Tevrat’tan) sonra Zebur’da da “Yeryüzüne iyi kullarım vâris olacaktır.” diye yazmıştık."},{"n":106,"t":"Şüphesiz ki bunda, (bize) kulluk eden toplum için bir mesaj vardır."},{"n":107,"t":"Biz seni ancak âlemlere rahmet(imiz) için gönderdik."},{"n":108,"t":"De ki: “Bana ‘ilahınızın tek bir ilah olduğu’ vahyolunuyor. O’na boyun eğecek misiniz?”"},{"n":109,"t":"Yüz çevirirlerse de ki: “(Bana emrolunanı) hepinize eşit olarak açıkladım. Size vadolunan şey yakın mı uzak mı bilmiyorum."},{"n":110,"t":"Şüphesiz ki (Allah) sözün açığını da bilir, gizlediklerinizi de bilir.”"},{"n":111,"t":"(Peygamber:) “Bilmiyorum, belki de o (azabın ertelenmesi), sizin için bir imtihan ve belirli bir zamana kadar sizi yararlandırmak içindir."},{"n":112,"t":"Rabbim! (Onlar hakkında) adaletinle hükmünü ver! Bizim Rabbimiz, sizin anlattıklarınıza karşı yardımı umulan Rahmân’dır.” demişti."}],[{"n":1,"t":"Ey insanlar! Rabbinize karşı takvâlı (duyarlı) olun! Şüphesiz ki o (Son) Saat’in sarsıntısı müthiş bir şeydir!"},{"n":2,"t":"Onu gördüğünüz gün, her emziren emzirdiğini unutur; her gebe de taşıdığını düşürür. İnsanları sarhoş olmamalarına rağmen sarhoş bir hâlde görürsün. Fakat Allah’ın azabı çok daha şiddetlidir!"},{"n":3,"t":"İnsanların bir kısmı, bilgisi olmaksızın Allah hakkında tartışmaya girer ve her azgın şeytana uyar."},{"n":4,"t":"Onun (şeytanın) hakkında şöyle yazılmıştır: “Kim onu yoldaş edinirse, bilsin ki (şeytan) kendisini saptıracak ve alevli ateşin azabına sürükleyecektir.”"},{"n":5,"t":"Ey insanlar! Diriltilmekten şüphedeyseniz, (bilin ki) biz sizi topraktan, sonra nutfeden (zigottan), sonra ‘alakadan (embriyodan), sonra organları belirlenmiş, (detayları) belirlenmemiş bir mudğadan (et parçacığından) yarattık ki size (kudretimizi) gösterelim. Dilediğimizi, belirlenmiş bir süreye kadar rahimlerde bekletiriz; sonra sizi bir bebek olarak doğumla (dışarı) çıkartırız. Sonra güçlü çağınıza ulaşmanız için (sizi büyütürüz). Kiminiz vefat ettirilir; kiminiz de bilgiden sonra (biliyorken) bir şey bilmez hâle gelsin diye ömrün en sıkıntılı çağına kadar götürülür. Yeri de kupkuru (ölü) bir hâlde görürsün; biz onun (toprağın) üzerine suyu indirdiğimiz zaman bir de bakarsın ki kıpırdayıp kabarır ve her iç açıcı çiftten (bitkiler) yetiştirir."},{"n":6,"t":"Çünkü Allah gerçeğin ta kendisidir; şüphesiz ki O, ölüleri diriltir; O, her şeye gücü yetendir."},{"n":7,"t":"O (Son) Saat mutlaka gelecektir; bunda hiçbir şüphe yoktur. Şüphesiz ki Allah mezarlardakileri diriltecektir."},{"n":8,"t":"İnsanların bir kısmı –bilgisi, rehberi ve aydınlatıcı bir kitabı olmaksızın– Allah hakkında tartışmaktadır."},{"n":9,"t":"Allah yolundan (insanları) saptırmak için yanını eğip bükerek (kibir içinde tartışmaya kalkar). Onun için dünyada bir rezillik vardır; kıyamet gününde ise ona yakıcı azabı tattıracağız."},{"n":10,"t":"(Onlara): “İşte bu, ellerini(zi)n öne sunduğu şeyler yüzündendir.” (denecektir). Elbette Allah kullara asla haksızlık edici değildir."},{"n":11,"t":"İnsanlardan kimi, Allah’a (imanla küfrün) sınır(ın)da kulluk eder. Kendisine bir iyilik dokunursa bununla huzurlu olur; ağır imtihana uğrarsa yüzü değişir (dinden yüz çevirir). O, dünya(sın)ı da ahiret(in)i de kaybetmiştir. Asıl apaçık kayıp işte budur!"},{"n":12,"t":"O, Allah’ın peşi sıra kendisine yararı da zararı da dokunamayacak şeylere yalvarır. Asıl uzak sapkınlık işte budur."},{"n":13,"t":"O, zararı yararından daha yakın (fazla) olan birine yalvarır. O (yalvardığı) ne kötü bir yardımcı ne kötü bir dosttur!"},{"n":14,"t":"Şüphesiz ki Allah iman edip iyi işler yapanları, altlarından ırmaklar akan cennetlere koyacaktır. Şüphesiz ki Allah istediğini yapar."},{"n":15,"t":"Kim Allah’ın, dünya ve ahirette kendisine asla yardım etmeyeceğini sanıyorsa, artık göğe doğru bir sebebe uzansın; sonra da (diğer şeylerle ilişkisini) kessin! Baksın ki bu önlemi kendisini öfkelendiren şeyin kökünü nasıl da kazıyacak!"},{"n":16,"t":"İşte böylece biz onu (Kur’an’ı) apaçık ayetler hâlinde indirdik. Şüphesiz ki Allah dileyeni (layık gördüğünü) doğru yola ulaştırır."},{"n":17,"t":"Şüphesiz ki iman edenler, yahudi olanlar, sabiiler, hristiyanlar, mecusiler ve müşrik olanlara gelince, şüphesiz ki Allah bunlar arasında kıyamet gününde (ayrı ayrı) hükmünü verecektir. Şüphesiz ki Allah her şeye şahit olandır."},{"n":18,"t":"Görmüyor musun ki göklerde ve yerde olanlar, güneş, ay, yıldızlar, dağlar, ağaçlar, canlılar ve insanların birçoğu Allah’a secde ediyor. Bir çoğunun üzerine de azap hak olmuştur. Allah kimi değersiz kılarsa, artık onu değerli kılacak kimse yoktur. Şüphesiz ki Allah dilediğini yapar."},{"n":19,"t":"Şu iki grup, Rableri hakkında çekişen iki hasımdır: kâfir olanlar için ateşten bir elbise biçilmiştir. Başlarının üzerinden kaynar su dökülecektir!"},{"n":20,"t":"Bununla, karınlarının içindeki (organlar) ve deriler(i) eritilecektir!"},{"n":21,"t":"Onlar için demir kamçılar da vardır!"},{"n":22,"t":"Izdıraptan dolayı oradan her çıkmak istediklerinde, oraya geri döndürülecekler ve (onlara) “Tadın bu yakıcı azabı!” (denecektir)."},{"n":23,"t":"Şüphesiz ki Allah iman edip iyi işler yapanları, altlarından ırmaklar akan cennetlere koyacaktır. Bunlar, orada altın bilezikler ve incilerle bezeneceklerdir. Orada giyecekleri ise ipektir."},{"n":24,"t":"Onlar, sözün en temizine (güzeline) yöneltilmiş, övgüye layık olan (Allah)’ın yoluna ulaştırılmıştır."},{"n":25,"t":"Kâfir olanlar, Allah’ın yolundan ve yerli (veya) uzaktan gelen bütün insanlara eşit (kıble) kıldığımız Mescid-i Haram’dan (insanları) alıkoymaya kalkanlar (bilmeliler ki) kim orada (böyle) haksızlık ile gerçek(ler)den sapmak isterse ona acı azaptan tattırırız."},{"n":26,"t":"Hani İbrahim’e Evin (Kâbe’nin) yerini göstermiş (şöyle demiştik): “Bana hiçbir şeyi ortak koşma; tavaf edenler, ayakta ibadet edenler, rükû ve secde edenler için evimi temiz tut!"},{"n":27,"t":"İnsanlar arasında haccı ilan et ki gerek yaya olarak, gerekse uzak yoldan gelen binekler üzerinde sana gelsinler!"},{"n":28,"t":"Kendilerine ait birtakım yararları görmeleri, (Allah’ın) onlara rızık olarak verdiği kurbanlık hayvanlar üzerine belirli günlerde Allah’ın ismini anmaları için (insanları hacca çağır)! Artık o (hayvanların eti)nden hem kendiniz yiyin hem de yoksula, fakire yedirin!"},{"n":29,"t":"(Hacca gidenler bundan) sonra kirlerini gidersin; adaklarını (görevlerini) yerine getirsin ve o Eski Ev’i (Kâbe’yi) tavaf etsinler!”"},{"n":30,"t":"İşte böyle. Kim Allah’ın saygın kıldığı şeyleri yüceltirse, bu, Rabbinin katında kendisi için hayırlı olandır. (Haram olduğu) size tilavet edilen (okunup aktarılan)ların dışında kalan hayvanlar size helal kılınmıştır. Putlardan oluşan pislikten kaçının; yalan sözden de kaçının!"},{"n":31,"t":"Kendisine ortak koşmaksızın Allah’ın hanîfleri (Allah’ı birleyenler) olarak (yaşayın)! Kim Allah’a ortak koşarsa, sanki o gökten düşüp kendisini kuş kapıyor veya rüzgâr onu uzak bir yere sürüklüyor gibidir."},{"n":32,"t":"İşte böyle. Kim Allah’ın sembollerini yüceltirse, şüphesiz ki bu kalplerin takvâsından (duyarlılığından)dır."},{"n":33,"t":"Onlarda (hac hükümlerinde) sizin için belirli bir süreye kadar birtakım yararlar vardır. Sonra bunların varacakları yer, Eski Ev’e (Kâbe’ye) kadardır."},{"n":34,"t":"Biz her ümmete kurban kesmeyi gerekli kıldık ki kendilerine rızık olarak verdiği hayvanlar üzerine Allah’ın adını ansınlar! İlahınız tek bir ilahtır. O’na teslim olun! O alçak gönüllü insanları müjdele!"},{"n":35,"t":"Onlar Allah anıldığı zaman kalpleri titrer; başlarına gelene sabreder, namaz kılar ve kendilerine rızık olarak verdiğimiz şeylerden infak ederler."},{"n":36,"t":"Biz büyükbaş hayvanları da sizin için Allah’ın sembollerinden kıldık. Onlarda sizin için hayır vardır. Onlar sıra sıra (dururken) üzerlerine Allah’ın ismini hatırlayın (ve kurban edin)! Yan üstü yere düştüklerinde (öldüklerinde) onlardan hem kendiniz yiyin hem de kanaatkâr olana ve fakirlere yedirin! İşte şükredesiniz diye bunları sizin hizmetinize verdik."},{"n":37,"t":"Onların etleri de kanları da asla Allah’a ulaşmaz fakat O’na sadece sizden takvâ (duyarlılık) ulaşır. Sizi doğru yola ulaştırdığı için Allah’ı yüceltesiniz diye O, bunları (bu hayvanları) böylece sizin hizmetinize verdi. Güzel davrananları müjdele!"},{"n":38,"t":"Şüphesiz ki Allah iman edenleri savunur (korur). Şüphesiz ki Allah hiçbir nankör haini sevmez."},{"n":39,"t":"Kendileriyle savaşılanlara, haksızlığa uğratılmaları sebebiyle (savaş için) izin verildi. Şüphesiz ki Allah onlara yardıma gücü yetendir."},{"n":40,"t":"Onlar -başka değil- sadece “Rabbimiz Allah’tır.” dedikleri için haksız yere yurtlarından çıkarılmışlardır. Allah bir kısım insanları diğer bir kısmı ile def edip önlemeseydi, elbette içlerinde Allah’ın ismi çok anılan manastırlar, kiliseler, havralar ve mescitler yıkılırdı. Şüphesiz ki Allah kendisine (dinine) yardım edenlere yardım edecektir. Şüphesiz ki Allah kuvvetlidir, güçlüdür."},{"n":41,"t":"Onlar (muhacirler), kendilerine yeryüzünde güç versek (de) namazı kılar, zekâtı verir; iyiliği emreder (öğütler), kötülükten engeller (sakındırır)lar. İşlerin sonu yalnızca Allah’a (var)ır."},{"n":42,"t":"Onlar (inkârcılar) seni yalanlarsa, elbette onlardan önce Nuh’un kavmi, Âd ve Semûd (kavimleri de) yalanlamıştı."},{"n":43,"t":"İbrahim’in kavmi de Lut’un kavmi de."},{"n":44,"t":"(Şuayb’ın kavmi) Medyen halkı da (peygamberlerini yalanlamışlardı). Musa da yalanlanmıştı. İşte ben o kâfirlere süre tanımış; sonra onları (azapla) yakalamıştım. Benim cezalandırmam (bak) nasıl olmuştu!"},{"n":45,"t":"(Nitekim), nice şehirler vardı ki o şehir(lerin halkı) haksızlık etmekteyken biz onları helak etmiştik. (O şehirlerde) duvarlar, (çökmüş) tavanların üzerine yıkılmıştır. Kullanılmaz hâle gelmiş bir kuyu ve (ıssız kalmış) heybetli bir köşk vardır."},{"n":46,"t":"(İnkârcılar) yeryüzünde hiç dolaşmadılar mı? (Dolaşsalardı) kendileriyle akıl edecek kalpleri veya duyacak kulakları olurdu. (Gerçek şu ki) gözler kör olmaz fakat göğüslerdeki kalpler kör olur."},{"n":47,"t":"Onlar senden azabı acele istiyorlar. Allah sözünden asla dönmeyecektir. Şüphesiz ki Rabbinin katında bir gün, sizin saymakta olduklarınızdan bin sene gibidir."},{"n":48,"t":"Nice şehir (halkı) vardı ki haksızlık edip dururlarken onlara süre vermiş, sonunda onları yakalamıştım. Dönüş sadece banadır."},{"n":49,"t":"De ki: “Ey insanlar! Ben ancak sizin için apaçık bir uyarıcıyım.”"},{"n":50,"t":"İman edip iyi işler yapanlar için bağışlanma ve değerli rızık vardır."},{"n":51,"t":"Ayetlerimiz hakkında (onları) aciz (kılmaya) çalışanlara gelince, işte bunlar cehennem halkıdır."},{"n":52,"t":"Biz senden önce hiçbir elçi veya peygamber göndermedik ki o, bir temennide bulunduğunda, şeytan onun dileğine mutlaka (bir şeyler) katmaya kalkışmasın. Ne var ki Allah, şeytanın katacağı şeyi iptal eder. Sonra Allah kendi ayetlerini sağlam olarak yerleştirir. Allah bilendir, doğru hüküm verendir."},{"n":53,"t":"Kalplerinde hastalık bulunanlar ve kalpleri katılaşanlar için, şeytanın kattığı şeyi bir fitne (imtihan) yapsın (diye Allah buna izin verir). Şüphesiz ki zalimler, uzak bir ayrılık içindedir."},{"n":54,"t":"Bir de kendilerine ilim verilenler, onun (Kur’an’ın) Rabbin tarafından (gelmiş) gerçek olduğunu bilsinler de ona inansınlar ve kalpleri saygıyla boyun eğsin. Şüphesiz ki Allah iman edenleri doğru yola ulaştırır."},{"n":55,"t":"Kâfir olanlar, kendilerine o (Son) Saat ansızın gelinceye veya kısır bir günün azabı gelinceye kadar onun (Kur’an’ın) hakkında hep şüphe içindedir."},{"n":56,"t":"O gün, otorite Allah’a aittir. Onlar (insanlar) arasında hükmü O verecektir. İman edip iyi işler yapanlar nimet cennetlerinde olacaklardır."},{"n":57,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, işte onlar için küçük düşürücü bir azap vardır."},{"n":58,"t":"Allah yolunda hicret edip sonra öldürülen veya ölenleri şüphesiz ki Allah güzel bir rızıkla rızıklandıracaktır. Şüphesiz ki Allah -evet O- rızık verenlerin en hayırlısıdır."},{"n":59,"t":"(Allah) onları, memnun kalacakları bir yere elbette yerleştirecektir. Şüphesiz ki Allah bilendir, hoşgörülüdür."},{"n":60,"t":"İşte böyle. Kim kendisine verilen eziyetin dengi ile karşılık verir de bundan sonra kendisine yine bir azgınlık (saldırı) yapılırsa, (bilsin ki) Allah ona mutlaka yardım edecektir. Şüphesiz ki Allah çok affedicidir, çok bağışlayandır."},{"n":61,"t":"Zira Allah geceyi gündüzün içine koyuyor, gündüzü de gecenin içine koyuyor. Şüphesiz ki Allah duyandır, görendir."},{"n":62,"t":"Çünkü Allah gerçeğin ta kendisidir; O’nun peşi sıra yalvardıkları ise batılın ta kendisidir. Şüphesiz ki Allah -evet yalnız O- yücedir, büyüktür."},{"n":63,"t":"Şüphesiz ki Allah’ın, gökten su indirmekte olduğunu ve (böylece) yerin yeşerdiğini görmüyor musun? Şüphesiz ki Allah çok lütufkârdır, haberdardır."},{"n":64,"t":"Göklerde ve yerde ne varsa hepsi yalnızca O’na aittir. Şüphesiz ki Allah -evet yalnız O- (gerçek) zengindir, övgüye layık olandır."},{"n":65,"t":"Görmedin mi Allah yerdeki her şeyi ve emri uyarınca denizde yüzen gemileri sizin hizmetinize vermiştir. Göğü de kendi izni olmadıkça yer üzerine düşmekten korumaktadır. Şüphesiz ki Allah insanlara çok şefkatlidir, çok merhametlidir."},{"n":66,"t":"O, (önce) size hayat veren, sonra sizi öldürecek, sonra yine diriltecek olandır. Şüphesiz ki o (inkârcı) insan, çok nankördür."},{"n":67,"t":"Biz her ümmete, uygulamakta oldukları bir ibadet tarzı gösterdik. Öyle ise onlar (kitap ehli) bu işte seninle çekişmesinler! Sen Rabbine davet et! Şüphesiz ki sen doğru bir hidayet üzeresin."},{"n":68,"t":"Seninle tartışmaya girişirlerse, (onlara) de ki: “Allah yaptığınızı çok iyi bilendir."},{"n":69,"t":"Allah kıyamet gününde, anlaşmazlığa düştüğünüz konular hakkında aranızda hüküm verecektir."},{"n":70,"t":"Bilmez misin ki Allah yerde ve gökte ne varsa bilir! Bu, bir kitapta mevcuttur. Şüphesiz ki bu, Allah’a çok kolaydır.”"},{"n":71,"t":"Onlar, Allah’ın peşi sıra, hakkında Allah’ın hiçbir delil indirmediği, kendilerinin de hakkında bilgi sahibi olmadıkları şeylere tapıyorlar. Zalimlerin hiçbir yardımcısı yoktur."},{"n":72,"t":"Ayetlerimiz kendilerine açıkça tilavet edildiği (okunup aktarıldığı) zaman, kâfir olanların yüzlerinde hoşnutsuzluk (olduğunu) bilirsin (fark edersin). Onlar, kendilerine ayetlerimizi tilavet edenlere (okuyup aktaranlara) neredeyse saldırırlar. De ki: “Size bundan (bu öfkenize sebep olan şeyden) daha kötüsünü bildireyim mi? Allah’ın kâfir olanlara vadettiği (cehennemdeki) ateş!” Ne kötü varış yeridir (orası)!"},{"n":73,"t":"Ey insanlar! (Size) bir örnek verildi; (şimdi) onu dinleyin: Allah’ın peşi sıra yalvardıklarınız bunun için bir araya gelseler bir sivrisinek bile yaratamazlar. Sinek onlardan bir şey kapsa bile bunu ondan kurtaramazlar. İsteyen de aciz, kendinden istenen de!"},{"n":74,"t":"Onlar (inkârcılar), Allah’ı gerektiği gibi tanımadılar. Şüphesiz ki Allah kuvvetlidir, güçlüdür."},{"n":75,"t":"Allah meleklerden de elçiler seçer, insanlardan da. Şüphesiz ki Allah duyandır, görendir."},{"n":76,"t":"(Allah) onların önlerindekini de arkalarındakini de bilir. Bütün işler, yalnızca Allah’a döndürülecektir."},{"n":77,"t":"Ey iman edenler! Rükû edin; secde edin; Rabbinize ibadet edin; hayır işleyin ki kurtulasınız!"},{"n":78,"t":"Allah uğrunda, hakkıyla cihad edin (fedakarlık yapın)! O, sizi seçti; dinde üzerinize hiçbir zorluk yüklemedi; babanız İbrahim’in milletinde (dininde de bu böyleydi). Elçinin size şahit olması, sizin de insanlara şahit olmanız için O, gerek daha önce (gelmiş kitaplarda), gerekse bunda (Kur’an’da) size “Müslümanlar.” adını vermiştir. Öyle ise namazı kılın; zekâtı verin ve Allah’a (O’nun vahyine) sımsıkı sarılın! O, sizin mevlanızdır (efendinizdir). O ne güzel mevladır (efendidir) ve O ne güzel yardımcıdır!"}],[{"n":1,"t":"Müminler elbette kurtulmuş (olacak)tır."},{"n":2,"t":"Onlar, salâtlarında (ibadetlerinde) huşu içinde (saygılı) olanlardır."},{"n":3,"t":"Onlar boş (şeyler)den yüz çevirenlerdir."},{"n":4,"t":"Onlar arınmak için çalışanlardır."},{"n":5,"t":"Onlar namuslarını koruyanlardır."},{"n":6,"t":"Ancak eşleri yani (evlilik yoluyla) meşru olarak sahip oldukları kişiler hariç; şüphesiz ki onlar (eşleriyle ilişkilerinde) kınanmazlar."},{"n":7,"t":"Bundan öteye (geçmek) isteyenler ise haddini aşanların ta kendileridir."},{"n":8,"t":"Onlar, emanetlerine ve sözlerine uyanlardır."},{"n":9,"t":"Onlar, bütün ibadetlerini koruyanlardır."},{"n":10,"t":"İşte onlar, gerçek mirasçıların ta kendileridir."},{"n":11,"t":"Firdevs (cennetin)e mirasçı olacak olan bu kişiler orada ebedî kalıcıdır."},{"n":12,"t":"Yemin olsun ki biz insanı çamurdan (süzülen) bir özden yarattık."},{"n":13,"t":"Sonra onu sağlam bir yerde nutfe (zigot) hâline getirdik."},{"n":14,"t":"Sonra o nutfeyi (zigotu) ‘alaka (embriyo) yaptık. Sonra o ‘alakayı (embriyoyu) bir mudğa (et parçacığı) hâline soktuk; o et parçacığını kemiğe çevirdik; o kemiği de etle (kasla) kapladık. Sonra onu başka bir yaratışla oluşturduk. Yaratanların en güzeli olan Allah çok yücedir."},{"n":15,"t":"Sonra, şüphesiz ki bunun ardından elbette öleceksiniz."},{"n":16,"t":"Sonra da şüphesiz ki kıyamet gününde diriltileceksiniz."},{"n":17,"t":"Yemin olsun ki üzerinizde yedi yol yarattık. Biz yaratmaktan habersiz değiliz."},{"n":18,"t":"Gökten bir ölçüyle su indirip onu yerde durdurmaktayız. Şüphesiz ki onu gidermeye de gücümüz yeter."},{"n":19,"t":"Böylece o (su)yun sayesinde sizin yararınıza hurma bahçeleri ve üzüm bağları meydana getirdik. Bunlarda sizin için pek çok meyveler vardır; onlardan yiyorsunuz."},{"n":20,"t":"Sînâ Dağı (çevresi)nde yetişen bir ağaç daha (yarattık ki) bu ağaç hem yağ hem de yiyenler(in ekmeğin)e katık edecekleri (zeytini) verir."},{"n":21,"t":"Şüphesiz ki hayvanlarda da sizin için ibret vardır. Onların karınlarındakinden (sütlerinden) size içiriyoruz. Onlarda sizin için yararlar vardır; etlerinden de yiyorsunuz."},{"n":22,"t":"O (hayvan)ların ve gemilerin üzerinde taşınıyorsunuz."},{"n":23,"t":"Yemin olsun ki Nuh’u elçi olarak kavmine göndermiştik de “Ey kavmim! Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. (Hâlâ) takvâlı (duyarlı) davranmayacak mısınız?” demişti."},{"n":24,"t":"Bunun üzerine, kavminden kâfir olan yöneticiler şöyle demişlerdi: “Bu ancak sizin gibi bir adamdır (insandır). Size üstün olmak istiyor. Allah (peygamber göndermek) isteseydi, elbette melekleri gönderirdi. Biz önceki atalarımızdan böyle bir şey duymadık."},{"n":25,"t":"Bu, yalnızca kendisinde cinlenmişlik bulunan bir adam (insan)dır. (Öyle ise) bir süreye kadar onu gözetleyin (bakalım)!”"},{"n":26,"t":"(Nuh) “Rabbim! Beni yalanlamalarına karşı bana yardım et!” demişti."},{"n":27,"t":"Ona şöyle vahyetmiştik: “Gözlerimizin önünde ve vahyettiğimiz şekilde gemiyi yap! Emrimiz gelip de tandır kaynayınca her tür (canlı)dan iki çift ile –içlerinden (boğulacağına dair) aleyhinde söz geçen(ler) dışında- aileni ona (gemiye) bindir! Haksızlık edenler hakkında bana (herhangi bir şey) söyleme! Şüphesiz ki onlar boğulacaklardır.”"},{"n":28,"t":"Sen beraberindekilerle birlikte gemiye yerleştiğinde de ki: “Bizi zalimler topluluğundan kurtaran Allah’a hamdolsun!”"},{"n":29,"t":"De ki: “Rabbim! Beni bereketli bir yere indir! Sen (insanları uygun bir yere) indirilenlerin en hayırlısısın.”"},{"n":30,"t":"Şüphesiz ki bunda çeşitli dersler vardır. Doğrusu biz (kullarımızı böyle) deneriz."},{"n":31,"t":"Sonra onların ardından bir başka nesil meydana getirmiştik."},{"n":32,"t":"Onlardan kendilerine “Allah’a kulluk edin! Sizin için O’ndan başka ilah yoktur. (Hâlâ) takvâlı (duyarlı) davranmayacak mısınız?” (diye mesajı ulaştıran) bir Elçi (Hud’u) göndermiştik."},{"n":33,"t":"Onun halkından, kâfir olan, ahirete ulaşmayı inkâr eden ve dünya hayatında kendilerine refah verdiğimiz yöneticiler “Bu ancak sizin gibi bir insandır. Sizin yediğinizden yiyor, içtiğinizden içiyor!” demişlerdi."},{"n":34,"t":"(Şöyle demişlerdi): “Doğrusu, sizin gibi bir insana itaat ederseniz şüphesiz ki kaybedersiniz!"},{"n":35,"t":"Size, öldüğünüz, toprak ve kemik hâline geldiğinizde, (mezardan) çıkartılacağınızı mı vadediyor?"},{"n":36,"t":"Size vadedilen çok uzaktır, çok uzak!"},{"n":37,"t":"O (hayat), sadece şu dünya hayatımızdan ibarettir. (Kimimiz) ölürüz, (kimimiz) yaşarız; bir daha asla diriltilecek de değiliz."},{"n":38,"t":"O (Hud), Allah hakkında sadece yalan uyduran bir adamdır; biz ona asla inananlar değiliz.”"},{"n":39,"t":"(Hud) “Rabbim! Beni yalanlamalarına karşı bana yardım et!” demişti."},{"n":40,"t":"(Allah da) şöyle buyurmuştu: “Pek yakında onlar mutlaka pişman olacaklar!”"},{"n":41,"t":"(Nitekim) onları bir amaç için korkunç bir ses yakalamış ve kendilerini hemen sel süprüntüsüne çevirmiştik. O zalimler topluluğuna “Uzak olun (defolun)!” (denmişti)."},{"n":42,"t":"Sonra onların ardından başka nesiller meydana getirmiştik."},{"n":43,"t":"Hiçbir ümmet, ecelinin önüne geçemez ve onu geciktiremez."},{"n":44,"t":"Sonra elçilerimizi peyderpey göndermiştik. Her toplum, kendilerine gelen elçiyi yalanlamıştı. Biz de onları (helak ederek) birbiri ardına takmış ve onları sözlere (ibretlik anılara) dönüştürmüştük. İman etmeyen kavim (merhametten) uzak olsun!"},{"n":45,"t":"45-46 Sonra Musa’yı ve kardeşi Harun’u ayetlerimizle ve apaçık bir delille Firavun ve yöneticilerine göndermiştik. Fakat onlar, kibirlenmiş ve yücelik taslayan bir toplum olmuşlardı."},{"n":46,"t":"45-46 Sonra Musa’yı ve kardeşi Harun’u ayetlerimizle ve apaçık bir delille Firavun ve yöneticilerine göndermiştik. Fakat onlar, kibirlenmiş ve yücelik taslayan bir toplum olmuşlardı."},{"n":47,"t":"Onlar şöyle demişlerdi: “Toplumları bize kölelik ederken, bizim gibi olan bu iki insana inanır mıyız hiç!”"},{"n":48,"t":"Böylece o ikisini yalanlamış ve helak edilenlerden olmuşlardı."},{"n":49,"t":"Yemin olsun ki biz Musa’ya, doğru yola ulaşsınlar diye Kitabı vermiştik."},{"n":50,"t":"Meryem oğlunu ve (onun) annesini de bir ayet (mucize) kılmıştık. Onları yerleşime elverişli, suyu bulunan bir tepeye yerleştirmiştik."},{"n":51,"t":"Ey elçiler! Temiz olan şeylerden yiyin; güzel işler yapın! Şüphesiz ki ben sizin yaptıklarınızı bilmekteyim."},{"n":52,"t":"Şüphesiz ki bu (peygamberler ve müminler), tek bir ümmet olarak sizin ümmetinizdir. Ben sizin Rabbinizim. Öyle ise bana karşı takvâlı (duyarlı) olun!"},{"n":53,"t":"(Ne var ki) insanlar, kendi aralarında işlerini parça parça edip kitaplara ayrıldılar. Her grup kendi yanında bulunanla sevinmektedir."},{"n":54,"t":"Şimdi sen onları bir zamana kadar şaşkınlıkları içinde bırak!"},{"n":55,"t":"55-56 Onlara verdiğimiz servet ve çocuklar ile kendilerine iyilik noktasında yardım ettiğimizi mi sanıyorlar! Hayır! Onlar (işin) farkına varamıyorlar."},{"n":56,"t":"55-56 Onlara verdiğimiz servet ve çocuklar ile kendilerine iyilik noktasında yardım ettiğimizi mi sanıyorlar! Hayır! Onlar (işin) farkına varamıyorlar."},{"n":57,"t":"Şüphesiz ki onlar; Rablerine olan saygıdan dolayı korkanlar,"},{"n":58,"t":"Rablerinin ayetlerine inananlar,"},{"n":59,"t":"Rablerine ortak koşmayanlar,"},{"n":60,"t":"Rablerine dönecekleri için verdiklerini kalpleri korkudan ürpererek verenler;"},{"n":61,"t":"İşte onlar, hayırlarda yarışanlar ve onun için önde olanlardır."},{"n":62,"t":"Biz kimseye gücünün yeteceğinden başkasını yüklemeyiz. Katımızda gerçeği konuşan bir kitap vardır; onlar, haksızlığa uğratılmayacaklardır."},{"n":63,"t":"(Hayır), aslında onların (inkârcıların) kalpleri bu konuda şaşkındır. Onların bunun dışında (bazı kötü) işleri vardır ki onlar bu işleri yapanlardır."},{"n":64,"t":"Sonunda şımarıklarını azaba uğrattığımızda bir de bakarsın ki feryat ediyorlar."},{"n":65,"t":"(Onlara şöyle denecektir:) “(Boşuna) sızlanmayın bugün! Şüphesiz ki siz bizden yardım göremeyeceksiniz!"},{"n":66,"t":"66-67 Elbette ayetlerim size tilavet ediliyordu (okunup aktarılıyordu) da siz buna karşı kibirlenerek arkanızı dönüyor, geceleyin (Kâbe’nin etrafında) saçmalıyordunuz.”"},{"n":67,"t":"66-67 Elbette ayetlerim size tilavet ediliyordu (okunup aktarılıyordu) da siz buna karşı kibirlenerek arkanızı dönüyor, geceleyin (Kâbe’nin etrafında) saçmalıyordunuz.”"},{"n":68,"t":"Onlar bu sözü (Kur’an’ı) hiç düşünmediler mi? Yoksa kendilerine, daha önce geçmişteki atalarına gelmeyen bir şey mi geldi!"},{"n":69,"t":"Yoksa elçilerini tanımadılar da bu yüzden mi onu inkâr ediyorlar!"},{"n":70,"t":"Yoksa onda bir cinlenmişlik olduğunu mu söylüyorlar? Hayır; o, kendilerine gerçeği getirmiştir. Onların çoğu ise gerçek(ler)den hoşlanmamaktadır."},{"n":71,"t":"Gerçek onların isteklerine uysaydı, gökler, yer ve bunlarda bulunanlar bozulup giderdi. Hayır! Biz onlara zikirlerini (Kur’an’ı) getirdik; (fakat) onlar (gerçeği) hatırlamalarından yüz çevirenlerdir."},{"n":72,"t":"Yoksa sen onlardan herhangi bir karşılık (ücret) mi istiyorsun? Rabbinin vereceği karşılık (nimet) hayırlı olandır. O, rızık verenlerin en hayırlısıdır."},{"n":73,"t":"Şüphesiz ki sen onları doğru bir yola çağırıyorsun."},{"n":74,"t":"Şüphesiz ki ahirete inanmayanlar ise yoldan çıkanlardır."},{"n":75,"t":"Onlara merhamet edip içinde bulundukları sıkıntıyı giderseydik, elbette azgınlıkları içerisinde bocalayarak direnirlerdi."},{"n":76,"t":"Yemin olsun ki biz onları azapla yakalamıştık da Rablerine yine boyun eğmemişler, yalvarıp yakarmamışlardı."},{"n":77,"t":"Sonunda üzerlerine azabı çok şiddetli bir kapı açtığımız zaman, bir de bakarsın ki onlar orada ümitsiz kalmışlardır!"},{"n":78,"t":"O, sizin için işitme (duyusu), gözler ve kalpler yaratandır. Ne kadar da azınız şükrediyor!"},{"n":79,"t":"Sizi yeryüzünde çoğaltıp yayan O’dur; (mahşerde) yalnızca O’nun huzurunda toplanacaksınız."},{"n":80,"t":"O, yaşatan ve öldürendir. Gecenin ve gündüzün (birbiri ardınca) değişmesi yalnızca O’na aittir. Akıl etmiyor musunuz?"},{"n":81,"t":"Gerçekte onlar da öncekilerin dedikleri gibi dediler:"},{"n":82,"t":"“Biz ölüp de toprak ve kemik hâline gelmişken mi biz mi diriltileceğiz?"},{"n":83,"t":"Şüphesiz ki bu (tehdit), bize de daha önce atalarımıza da vadedilmişti. Bu, öncekilerin masallarından başka bir şey değildir” demişlerdi."},{"n":84,"t":"De ki: “Biliyorsanız (söyleyin bakalım), bu dünya ve onda bulunanlar kime aittir?”"},{"n":85,"t":"“Allah’a aittir.” diyeceklerdir. De ki: “Öyle ise (gerçeği) hatırlamaz mısınız?”"},{"n":86,"t":"De ki: “Yedi kat göklerin Rabbi, yüce arşın Rabbi kimdir?”"},{"n":87,"t":"“Allah’a aittir.” diyecekler. De ki: “(O’na karşı) takvâlı (duyarlı) olmaz mısınız?”"},{"n":88,"t":"De ki: “Biliyorsanız (söyleyin), her şeyin egemenliği kendisinin elinde olan, her şeyi koruyup kollayan fakat kendisi korunmaya (ihtiyacı olmaya)n (güç) kime aittir?”"},{"n":89,"t":"“Allah’a aittir.” diyeceklerdir. De ki: “Öyle ise nasıl da büyüleniyorsunuz?”"},{"n":90,"t":"Doğrusu biz onlara gerçeği getirdik; şüphesiz ki onlar yalancıdır."},{"n":91,"t":"Allah asla çocuk edinmemiştir; O’nunla birlikte ilah da yoktur. Aksi takdirde, her ilah kendi yarattığına gider (onunla ilgilenir); mutlaka onlardan biri diğerine üstün gelirdi. Allah onların (müşriklerin) yakıştırmalarından yücedir."},{"n":92,"t":"Görünmeyeni ve görüneni bilendir. (Müşriklerin) ortak koştuklarından yücedir."},{"n":93,"t":"De ki: “Rabbim! Onlara vadedileni (azabı) mutlaka bana göstereceksen,"},{"n":94,"t":"Rabbim! Bu durumda beni zalimler topluluğunun içinde bulundurma!”"},{"n":95,"t":"Biz onlara vadettiğimiz (azabı) sana göstermeye elbette gücü yetenleriz."},{"n":96,"t":"Sen kötülüğü en güzel şekilde sav! Biz onların yakıştırmalarını çok iyi bileniz."},{"n":97,"t":"De ki: “Rabbim! Şeytanların kışkırtmalarından sana sığınıyorum!"},{"n":98,"t":"Rabbim! Onların bana yaklaşmalarından da sana sığınıyorum.”"},{"n":99,"t":"Sonunda onlardan birine ölüm geldiğinde “Rabbim! Beni geri gönderin!” der."},{"n":100,"t":"“Belki terk ettiğim (dünya)da iyi iş(ler) yaparım!” Hayır! Söylediği bu söz, (boş) laftan ibarettir. Onların arkasında diriltilecekleri güne kadar bir engel vardır."},{"n":101,"t":"Sûr’a üflendiği zaman artık aralarında akrabalık bağları kalmamıştır; birbirlerini de soramazlar."},{"n":102,"t":"Kimin terazi(de sevap)ları ağır gelirse, işte onlar kurtulanların ta kendileridir."},{"n":103,"t":"Kimin de terazi(de sevap)ları hafif gelirse, artık onlar kendilerine yazık edenlerdir; (onlar) ebedî cehennemdedir."},{"n":104,"t":"Ateş, yüzlerini yalar (yakar); orada dişleri dışarı fırlar bir hâlde bulunurlar."},{"n":105,"t":"Ayetlerim size tilavet edilmemiş (okunup aktarılmamış) mıydı! Siz de onları yalanlamıştınız."},{"n":106,"t":"Onlar şöyle demiş (olacak)lardır: “Rabbimiz! Azgınlığımız bize galip geldi; biz bir sapkınlar topluluğuyduk."},{"n":107,"t":"Rabbimiz! Bizi buradan çıkar! Bir daha (yaptıklarımıza) dönersek, artık belli ki biz zalim insanlarız.”"},{"n":108,"t":"(Allah) şöyle buyurmuş (olacak)tır: “Alçaldıkça alçalın orada! Bana karşı konuşmayın artık!"},{"n":109,"t":"Şüphesiz ki kullarımdan bir grup, ‘Rabbimiz! İman ettik, bizi affet; bize merhamet et! Sen merhametlilerin en hayırlısısın’ demişlerdi."},{"n":110,"t":"İşte siz onlarla alay etmiştiniz; sonunda (bu alaycılığınız) size beni anmayı unutturdu; onlara gülüyordunuz."},{"n":111,"t":"Şüphesiz ki bugün ben de onlara, (dünyada) sabretmelerinin karşılığını verdim; şüphesiz ki onlar başaranlardır.”"},{"n":112,"t":"(Allah, inkârcılara) “Yeryüzünde kaç sene kaldınız?” diye soracaktır."},{"n":113,"t":"Onlar da “(Muhtemelen) bir gün veya günün bir kısmı kadar kaldık; işte sayanlara sor!” cevabını vereceklerdir."},{"n":114,"t":"(Allah) şöyle buyuracaktır: “Sadece az bir süre kaldınız; keşke (bunu) bilmiş olsaydınız!"},{"n":115,"t":"Sizi sadece boş yere yarattığımızı ve şüphesiz ki huzurumuza döndürülmeyeceğinizi mi sandınız?”"},{"n":116,"t":"Gerçek hükümdar olan Allah yücedir. O’ndan başka ilah yoktur. O, değerli arşın sahibidir."},{"n":117,"t":"Kim Allah ile birlikte başka bir ilaha yalvarırsa –ki bu kişinin hiçbir delili yoktur– o kimsenin hesabı ancak Rabbinin katındadır. Şüphesiz ki kâfirler kurtulamayacaklardır."},{"n":118,"t":"De ki: “Rabbim! Affet! Merhamet et! Sen merhametlilerin en hayırlısısın.”"}],[{"n":1,"t":"(Bu), bizim indirdiğimiz ve (hükümlerini) farz kıldığımız bir suredir. Umulur ki (düşünüp gerçeği) hatırlarsınız diye onda apaçık ayetler indirdik."},{"n":2,"t":"Zina eden kadın ve zina eden erkekten her birine yüz(er) celde (değnek) vurun! Allah’a ve ahiret gününe inanıyorsanız, Allah’ın dininde (hükümlerini uygulamada) onlara şefkatiniz tutmasın! Müminlerden bir grup da onlara (uygulanan) cezaya şahit olsun!"},{"n":3,"t":"Zina eden erkek, zina eden veya müşrik bir kadından başkası ile evlen(e)mez; zina eden kadınla da ancak zina eden veya müşrik erkek evlen(ebil)ir. Bu, (diğer) müminlere haram kılınmıştır."},{"n":4,"t":"Namuslu kadınlara zina iftirasında bulunup, sonra da dört şahit getiremeyenlere seksen(er) celde (değnek) vurun ve artık onların şahitliğini hiçbir zaman kabul etmeyin! Onlar, yoldan çıkanların ta kendileridir."},{"n":5,"t":"Ancak bundan sonra tevbe edip kendilerini düzeltenler hariçtir. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":6,"t":"Eşlerine zina iddiasında bulunup da kendilerinden başka şahitleri olmayanlara gelince, onların her birinin şahitliği, kendisinin doğru söyleyenlerden olduğuna dair Allah’ı dört kez şahit tutmasıdır."},{"n":7,"t":"Beşinci (yemin) ise yalan söyleyenlerden ise Allah’ın lanetinin kendi üzerine olması(nı kabul etmesidir)."},{"n":8,"t":"(Kocasının) yalan söyleyenlerden olduğuna dair (kadının) Allah’ı dört kez şahit tutması kendisinden cezayı kaldırır."},{"n":9,"t":"Beşinci (yemin) ise (kocası) doğru söyleyenlerden ise Allah’ın gazabının kendi üzerine olması(nı kabul etmesidir)."},{"n":10,"t":"Allah’ın size lütfu ve merhameti olmasaydı ve Allah tevbeleri çok kabul eden, doğru hüküm veren olmasaydı (hâliniz nasıl olurdu)!"},{"n":11,"t":"(Peygamber’in eşine) o iftirayı atanlar, şüphesiz ki içinizden (küçük) bir gruptur. Bunu kendiniz için bir kötülük sanmayın; aksine o, sizin için bir iyiliktir. Onlardan her bir kişiye, günah olarak ne işlemişse (onun karşılığı) vardır. Onlardan bu günahın büyüklüğünü yüklenen kimse için büyük bir azap vardır."},{"n":12,"t":"Bunu (iftirayı) duyduğunuzda erkek ve kadın müminlerin, kendi vicdanları ile olumlu zanda bulunup da “Bu, apaçık bir iftiradır!” demeleri gerekmez miydi!"},{"n":13,"t":"Onların (iftiracıların) da bu konuda dört şahit getirmeleri gerekmez miydi! Madem ki şahitler(i) getiremediler, onlar Allah katında yalancıların ta kendileridir."},{"n":14,"t":"Size dünyada da ahirette de Allah’ın lütuf ve merhameti olmasaydı, içine daldığınız bu konuda (bu iftirada) size mutlaka büyük bir azap isabet ederdi."},{"n":15,"t":"Çünkü siz bunu (iftirayı), dilden dile aktarıyor, hakkında bilgi sahibi olmadığınız şeyi ağızlarınızda geveleyip duruyor, bunun önemsiz olduğunu sanıyorsunuz. (Oysa) bu, Allah katında çok büyük (bir günah)tır."},{"n":16,"t":"Onu (iftirayı) duyduğunuzda “Bu konuda konuşmamız bize yakışmaz. (Allah’a yönelerek) Sen yücesin. Bu, çok büyük bir iftiradır!” demeniz gerekmez miydi!"},{"n":17,"t":"İnanıyorsanız, Allah bir daha buna (benzer bir hataya) dönmeniz konusunda sizi uyarıyor!"},{"n":18,"t":"Allah ayetleri size açıklıyor. Allah bilendir, doğru hüküm verendir."},{"n":19,"t":"Şüphesiz ki inananlar arasında çirkinliğin yayılmasını arzulayanlar için dünyada da ahirette de elem verici bir azap vardır. Allah bilir, siz bilmezsiniz."},{"n":20,"t":"Allah’ın size lütfu ve merhameti olmasaydı ve Allah çok şefkatli, çok merhametli olmasaydı (hâliniz nasıl olurdu)!"},{"n":21,"t":"Ey iman edenler! Şeytanın adımlarını izlemeyin! Kim şeytanın adımlarını izlerse, (bilsin ki) o (şeytan), şüphesiz ki çirkinliği ve kötülüğü emreder. Allah’ın size lütfu ve merhameti olmasaydı, içinizden kimse asla temize çıkamazdı. Fakat Allah dileyeni (layık gördüğünü) arındırır. Allah duyandır, bilendir."},{"n":22,"t":"İçinizden lütuf ve servet sahibi kişiler, yakınlara, yoksullara, Allah yolunda hicret edenlere (mallarından) vermeleri konusunda yemin etmesin; (onları) bağışlasınlar! Dikkat edin! Allah’ın sizi bağışlamasını sevmez misiniz? Allah çok bağışlayandır, çok merhametlidir."},{"n":23,"t":"Namuslu, kötülüklerden habersiz mümin kadınlara zina iftirasında bulunanlar, dünya ve ahirette lanetlenmişlerdir. Onlar için büyük bir azap vardır."},{"n":24,"t":"O gün, dilleri, elleri ve ayakları, yapmış olduklarıyla ilgili olarak aleyhlerinde şahitlik edecektir."},{"n":25,"t":"O gün, Allah onlara gerçek karşılıklarını tastamam verecektir ve Allah’ın sadece apaçık gerçek olduğunu bilip anlayacaklardır."},{"n":26,"t":"Pis kadınlar pis erkeklere, pis erkekler de pis kadınlara; temiz kadınlar temiz erkeklere, temiz erkekler de temiz kadınlara yakışır. Bu (temiz olanlar iftiracıların) söylediklerinden uzaktır. Onlar için bağışlanma ve değerli bir rızık vardır."},{"n":27,"t":"Ey iman edenler! (Geldiğinizi) farkettirip ev halkına selam verinceye (onlar selamınızı alıncaya) kadar kendi evinizden başka evlere girmeyin! Bu (davranış), sizin için hayırlı olandır; umulur ki (gerceği) hatırlarsınız."},{"n":28,"t":"Orada hiçbir kimse bulamazsanız, size izin verilinceye kadar oraya girmeyin! Size “Geri dönün!” denirse hemen dönün! (Çünkü) bu, sizin için daha uygundur. Allah yapmakta olduğunuz her şeyi bilendir."},{"n":29,"t":"İçinde kendinize ait eşyanın (ihtiyaçlarınızın) bulunduğu oturulmayan evlere (izinsiz) girmenizde size herhangi bir vebal yoktur. Allah sizin açığa vurduklarınızı da gizlediklerinizi de bilir."},{"n":30,"t":"Mümin erkeklere söyle: “Gözlerini (harama bakmaktan) kıssınlar ve namuslarını korusunlar!” Bu, kendileri için daha uygundur. Şüphesiz ki Allah yapmakta olduklarından haberdardır."},{"n":31,"t":"Mümin kadınlara da söyle: “Gözlerini (harama bakmaktan) kıssınlar ve namuslarını korusunlar! (Kendiliğinden) görünen kısımları hariç olmak üzere, ziynetlerini (süslerini) açmasınlar! Başörtülerini, yakalarının üzerine vurup (salsın)lar! Kocaları veya babaları veya kocalarının babaları veya kendi oğulları veya kocalarının oğulları veya erkek kardeşleri veya erkek kardeşlerinin oğulları veya kız kardeşlerinin oğulları veya kendi kadınları veya (meşru olarak) ellerinin altında bulunanlar veya şehvet sahibi olmayıp (evde) bulunan erkek (yaşlı hizmetçiler) veya kadınların avretlerinin henüz farkında olmayan çocuklardan başkasına ziynetlerini açmasınlar! Gizlemekte oldukları ziynetleri bilinsin diye ayaklarını yere vurmasınlar! Ey müminler! Hep birden Allah’a yönelin ki kurtulasınız!”"},{"n":32,"t":"İçinizden bekârları, kölelerinizden ve cariyelerinizden (durumu evlenmeye) elverişli olanları evlendirin! Fakir iseler, Allah kendi lütfu ile onları zenginleştirir. Allah (imkânları) geniş olandır, bilendir."},{"n":33,"t":"Nikâh (imkânı) bulamayanlar, Allah lütfundan kendilerini zenginleştirene kadar namuslu olsunlar! Kendilerinde bir hayır görüyorsanız ellerinizin sahip olduklarından (kölelerden ve cariyelerden) özgürlük sözleşmesi yapmak isteyenlerle hemen özgürlük sözleşmesi yapın! Allah’ın size vermiş olduğu maldan (servetten) siz de onlara verin! Dünya hayatının geçici menfaatini elde edeceksiniz diye namuslu olmak isteyen genç cariyelerinizi fuhşa zorlamayın! Kim onları zorlarsa, (bilinmelidir ki) zorlanmalarından sonra Allah (o zorlananlar için) çok bağışlayandır, çok merhametlidir."},{"n":34,"t":"Yemin olsun ki biz size apaçık ayetler, sizden önce geçmiş olanlardan bir örnek ve muttakîler (duyarlı olanlar) için bir öğüt indirdik."},{"n":35,"t":"Allah göklerin ve yerin nurudur. O’nun nurunun durumu, içinde kandil bulunan bir oyuk gibidir. O kandil, cam (billur) bir fanus içindedir. O fanus da sanki inci (görünümlü) bir gezegen gibidir ki doğuya da batıya da ait olmayan bereketli bir ağaçtan, yani zeytinden (çıkan yağ ile) tutuşturulur. O (ağac)ın yağı, kendisine ateş değmese bile neredeyse nûr (ışık) verir. (Bu), nûr üstüne nûrdur. Allah dileyeni (layık gördüğü) kimseyi nûruna ulaştırır. Allah insanlara (işte böyle) örnekler verir. Allah her şeyi bilendir."},{"n":36,"t":"(Bu kandil) birtakım evlerdedir ki Allah (o evlerin) yücelmesine ve içlerinde isminin anılmasına izin vermiştir. Orada sabah akşam O’nu (şöyle kişiler) tesbih ederler (yüceltirler):"},{"n":37,"t":"O adamlar, ticaretin de alışverişin de kendilerini Allah’ı hatırlamaktan, namaz kılmaktan ve zekât vermekten alıkoyamadığı kişilerdir. Onlar, kalplerin ve gözlerin ters döneceği bir günden korkarlar."},{"n":38,"t":"Sonunda Allah onları yaptıklarının en güzeli ile ödüllendirecek ve lütfundan onlara fazlasıyla verecektir. Allah dilediğine (layık olana) hesapsız rızık verir."},{"n":39,"t":"Kâfir olanlara gelince, onların işleri, ıssız çöllerdeki serap gibidir ki susayan onu su sanır. Sonunda ona (su sandığı yere) vardığında herhangi bir şey bulamamış, yanıbaşında Allah’ı bulmuş (olacak)tır ki O da onun hesabını tastamam görmüş (olacak)tır. Allah hesabı hızlı olandır."},{"n":40,"t":"Veya (o kâfirlerin davranışları) derin bir denizdeki yoğun karanlıklar gibidir; (öyle) ki onu dalga üstüne dalga kuşatıyor; üzerinde de (bir) bulut; birbiri üstüne karanlıklar. (İnsan), elini çıkar(ıp bak)sa, neredeyse onu bile göremez. Allah bir kimseye nûr (ışık) vermemişse, artık onun hiçbir nuru olmaz."},{"n":41,"t":"Göklerde ve yerde bulunanlarla dizi dizi kuşların Allah’ı tesbih ettiklerini görmüyor musun? Elbette her biri kendi salâtını (duasını) ve tesbihini (yüceltmesini) bilmektedir. Allah onların yapmakta olduklarını bilendir."},{"n":42,"t":"Göklerin ve yerin otoritesi yalnızca Allah’a aittir. Dönüş de yalnız Allah’adır."},{"n":43,"t":"Görmüyor musun ki Allah birtakım bulutları (çıkarıp) sürüyor; sonra onları bir araya getiriyor, sonra üst üste yığıyor. (Sonunda bulutların) arasından yağmurun çıktığını görüyorsun. (Allah) gökteki dağlar (gibi büyük bulutlar)dan dolu indirir de onu dilediğine (layık olana) isabet ettirir; dilediğinden de onu öteye çevirir (uzak tutar). (Bu bulutların) şimşeğinin parıltısı neredeyse gözleri alır!"},{"n":44,"t":"Allah gece ile gündüzü birbirine çeviriyor. Şüphesiz ki bunda, öngörü sahipleri için bir ibret vardır."},{"n":45,"t":"Allah her canlıyı sudan yaratmıştır. İşte onlardan kimi karnı üzerinde yürür (sürünür); kimi iki ayak üzerinde yürür; kimi dört ayak üzerinde yürür. Allah dilediğini yaratır; şüphesiz ki Allah her şeye gücü yetendir."},{"n":46,"t":"Şüphesiz ki apaçık ayetler indirdik. Allah dileyeni (layık gördüğünü) doğru yola ulaştırır."},{"n":47,"t":"(Bazı insanlar:) “Allah’a ve Elçi'ye inandık ve itaat ettik!” diyor; sonra da içlerinden bir grup yüz çeviriyor. Bunlar asla inanmış değillerdir."},{"n":48,"t":"Onlar, aralarında hüküm vermesi için Allah’a ve Elçi'ye çağrıldıklarında (bir de bakarsın ki) içlerinden bir kısmı yüz çevirenler (olmuşlardır)."},{"n":49,"t":"Gerçek kendi lehlerine ise ona boyun eğip gelirler."},{"n":50,"t":"Kalplerinde bir hastalık mı var? Yoksa (vahiy konusunda) şüphe içinde mi kaldılar? Veya Allah’ın ve Elçisinin kendilerine haksızlık edeceğinden mi korkuyorlar? Hayır! Onlar zalimlerin ta kendileridir!"},{"n":51,"t":"Aralarında hüküm vermesi için Allah’a ve Elçisine davet edildiklerinde, müminlerin sözü sadece “İşittik ve itaat ettik!” demeleridir. İşte onlar kurtulanların ta kendileridir."},{"n":52,"t":"Kim Allah’a ve Elçisine itaat eder, Allah’a saygı duyar ve O’na karşı takvâlı (duyarlı) olursa, işte onlar da mutluluğa ulaşanların ta kendileridir."},{"n":53,"t":"(Münafıklar), sen kendilerine emrettiğin takdirde mutlaka (yanında savaşa) çıkacaklarına dair var güçleriyle Allah’a yemin ettiler. De ki: “Yemin etmeyin! İtaatiniz bilinmektedir! Şüphesiz ki Allah yaptıklarınızdan haberdardır.”"},{"n":54,"t":"De ki: “Allah’a itaat edin; Elçi'ye de itaat edin! Yüz çevirirseniz (onun sorumluluğu) kendisine yüklenen (tebliğ görevini yapmak)tır; sizin (sorumluluğunuz da) size yüklenen (görevleri yerine getirmeniz)dir. Ona itaat ederseniz, doğru yola ulaşmış olursunuz! Elçi'ye düşen, sadece apaçık tebliğdir.”"},{"n":55,"t":"Allah sizden iman edip iyi işler yapanlara, kendilerinden öncekileri halife (sorumlu) kıldığı gibi onları da yeryüzüne halife (sorumlu) kılacağını, onlar için uygun gördüğü dini (İslam’ı) güçlendireceğini ve (geçirdikleri) korkularından sonra kendilerine güven sağlayacağını vadetmiştir. (Çünkü) onlar, bana kulluk eder; hiçbir şeyi bana eş tutmazlar. Artık bundan sonra kim inkâr ederse, işte onlar yoldan çıkanların ta kendileridir."},{"n":56,"t":"Namazı kılın, zekâtı verin! Elçi'ye itaat edin ki merhamete ulaştırılasınız."},{"n":57,"t":"Kâfir olanların, yeryüzünde (Allah’ı) aciz bırakacaklarını sanmayasın! Onların barınağı ateştir. Ne kötü varış yeridir (orası)!"},{"n":58,"t":"Ey iman edenler! Ellerinizin (meşru bir şekilde) sahip olduğu kişiler ve içinizden henüz ergenlik çağına girmemiş olanlar, sabah ibadetinden önce, öğleyin elbiselerinizi çıkardığınız zaman ve yatsı ibadetinden sonra (yanınıza gireceklerinde) sizden izin istesinler! (Bunlar), sizin için üç avret (açık bulunabilme) zamanıdır. (Bunun dışında izin istememelerinde) sizin için de onlar için de herhangi bir vebal yoktur. Birbirinizin yanına çok girip çıkanlarsınız. Allah, ayetleri size işte böyle açıklıyor. Allah bilendir, doğru hüküm verendir."},{"n":59,"t":"Çocuklarınız ergenlik çağına ulaştığında, kendilerinden öncekiler (büyükler) izin istedikleri gibi onlar da izin istesinler! Allah, ayetlerini size işte böyle açıklıyor. Allah bilendir, doğru hüküm verendir."},{"n":60,"t":"Nikâh ümidi kalmayan yaşlı kadınların, ziynet(lerin)i açmaksızın elbiselerini çıkarmalarında kendilerine herhangi bir vebal yoktur. (Her şeye rağmen) iffetli davranmaları, kendileri için hayırlı olandır. Allah duyandır, bilendir."},{"n":61,"t":"Görme engelliye zorluk yoktur; topala zorluk yoktur; hastaya da zorluk yoktur. Sizin için kendi evlerinizden veya babalarınızın evlerinden veya annelerinizin evlerinden veya erkek kardeşlerinizin evlerinden veya kız kardeşlerinizin evlerinden veya amcalarınızın evlerinden veya halalarınızın evlerinden veya dayılarınızın evlerinden veya teyzelerinizin evlerinden veya anahtarlarına sahip olduğunuz (yerler)den veya dostlarınızın evlerinden yemenizde (sakınca yoktur). Toplu hâlde veya ayrı ayrı yemenizde de sakınca yoktur. Evlere girdiğiniz zaman Allah tarafından bir esenlik, bereket, iyilik dileği olarak kendinize (evdekilere) selam verin! Allah akıl edesiniz diye ayetleri size işte böyle açıklıyor."},{"n":62,"t":"Gerçek müminler, Allah’a ve Elçisine iman edip güvenen kişilerdir. Onunla (Peygamber’le) toplumu ilgilendiren bir konu üzerindeyken, ondan izin isteyinceye kadar gitmezler. Senden izin isteyenler var ya, işte onlar, Allah’a ve Elçisine iman edip güvenenlerdir. Bazı işleri için senden izin istediklerinde, sen de onlardan dilediğine izin ver ve kendileri için Allah’tan bağışlanma dile! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":63,"t":"Elçinin çağrısını kendi aranızdaki çağrı gibi tutmayın! İçinizden birini siper edinerek sıvışıp gidenleri elbette Allah bilmektedir. Onun emrine aykırı davrananlar, başlarına bir sıkıntı gelmesinden veya kendilerine elem verici bir azap gelmesinden sakınsınlar!"},{"n":64,"t":"Dikkat edin! Göklerde ve yerde ne varsa yalnızca Allah’a aittir. O, sizin ne hâlde olduğunuzu elbette bilmektedir. Huzuruna döndürülecekleri gün (dünyada) yapmış olduklarını (Allah) onlara bildirecektir. Allah her şeyi bilendir."}],[{"n":1,"t":"Âlemler (insanlar) için uyarıcı olsun diye kuluna Furkân’ı (Kur’an’ı) indiren (Allah) yüceler yücesidir."},{"n":2,"t":"Göklerin ve yerin otoritesi yalnızca O’na aittir; çocuk edinmemiştir; otoritede ortağı yoktur; (O) her şeyi yaratmış ve belirli bir ölçüye kavuşturmuştur."},{"n":3,"t":"(Müşrikler) O’nun peşi sıra kendileri yaratılmakta olup hiçbir şey yaratamayan, ayrıca kendilerine zarar da yarar da sağlama imkanına sahip olamayan, ölüme, hayata ve ölüleri yeniden diriltmeye de güçleri yetmeyen çeşitli ilahlar edindiler."},{"n":4,"t":"Kâfir olanlar “Bu (vahiy) ancak o (Muhammed)’in uydurduğu ve kendisine başka bir grubun da yardım ettiği bir iftiradır.” diyerek, elbette bir haksızlığa ve yalana vardılar."},{"n":5,"t":"(Müşrikler) “Bu (ayetler, başkasına) yazdırıp sabah akşam kendisine okunmakta olan öncekilerin masallarıdır!” dediler."},{"n":6,"t":"De ki: “Onu (Kur’an’ı) göklerde ve yerdeki gizliliği bilen (Allah) indirmiştir. Şüphesiz ki o çok bağışlayandır, çok merhametlidir.”"},{"n":7,"t":"(Kâfirler) şöyle dediler: “Bu ne biçim elçi! Yemek yiyor, çarşılarda dolaşıyor! Kendisine bir melek indirilip o da onunla uyarıcı olmalı değil miydi?"},{"n":8,"t":"Veya kendisine bir hazine verilmeli ya da beslenebileceği bir bahçesi olmalı (değil miydi)?” (Ayrıca) o zalimler “Siz sadece büyülenmiş bir adama uymaktasınız!” dediler."},{"n":9,"t":"Senin için bak ne biçim örnekler verdiler! Onlar zaten sapmışlardı ve (artık) gerçeğe giden yolu da bulamazlar."},{"n":10,"t":"Şanı yüce olan (Allah) dilerse sana bunların söylediklerinden çok daha iyisini, altlarından ırmaklar akan bahçeler verir ve senin için özel saraylar da yaratır."},{"n":11,"t":"Gerçekte onlar o (Son) Saat’i yalanlamışlardı. Biz de o (Son) Saat’i yalanlayanlara alevli bir ateş (cehennem) hazırladık."},{"n":12,"t":"(O ateş) uzak bir yerden kendilerini görünce (cehennemlikler) onun kükremesini ve uğultusunu duyacaklar."},{"n":13,"t":"Bağlı olarak oradan (cehennemin) dar bir yerine atıldıkları zaman oracıkta yok olmayı isteyecekler."},{"n":14,"t":"(Kendilerine) “Bugün (yalnız) bir kez değil, defalarca yok olmayı isteyin!” (denecektir)."},{"n":15,"t":"(Onlara) de ki: “Bu mu hayırlı olan yoksa muttakîlere (duyarlı olanlara) vadedilen, kendileri için bir ödül ve varış yeri olan ebedî cennet mi?”"},{"n":16,"t":"Onların, cennette ebedî kalmak üzere diledikleri her şeyleri olacaktır. İşte bu, Rabbinin arzu edilen bir vaadidir."},{"n":17,"t":"Onları (cehennemlikleri) ve Allah’ın peşi sıra taptıkları varlıkları bir araya getirdiği gün, (Allah) “Şu kullarımı siz mi saptırdınız, yoksa kendileri mi yolu şaşırdılar (yoldan saptılar)?” diye sormuş (olacak)tır."},{"n":18,"t":"Onlar (melekler) de şöyle demiş (olacaklar)dır: “Sen yücesin. Senin peşin sıra dostlar edinmek bize yakışmazdı. Fakat sen onlara ve atalarına bol nimet verince (Allah’ı) hatırlamayı unuttular ve helaki hak eden bir toplum oldular.”"},{"n":19,"t":"(Allah şöyle diyecektir:) “İşte (taptıklarınız) sizin söylediklerinizi yalanladılar. Artık (azabı) geri çevirmeye de yardıma da gücünüz yetmez. İçinizden haksızlık edenlere büyük bir azap tattıracağız!”"},{"n":20,"t":"Yemek yiyen ve çarşılarda dolaşan (insan elçi)lerin dışında, bir başkasını senden önce de elçi olarak göndermedik. Sabırlı olup olmayacağınızı denemek için bir kısmınızı bir kısmına imtihan kıldık. Rabbin görendir."},{"n":21,"t":"Bizimle karşılaşacaklarını ummayanlar, “(İnanmamız için) ya bize de melekler indirilmeliydi ya da Rabbimizi görmeliydik!” dediler. Şüphesiz ki onlar, kendileri hakkında kibir gösterdiler ve büyük bir azgınlığa düştüler."},{"n":22,"t":"Melekleri görecekleri gün -işte o gün- suçlulara hiçbir müjde yoktur ve (o suçlular) “(Her yerden) tamamen engellenmişiz!” diyeceklerdir."},{"n":23,"t":"Yaptıkları her bir işi ele alacağız ve onu saçılmış zerreler hâline getireceğiz."},{"n":24,"t":"O gün, cennet halkına kalınacak yerlerin en hayırlısı ve dinlenilecek yerlerin de en güzeli (verilecektir)."},{"n":25,"t":"25-26 Göğün bulutlarla yarılacağı ve meleklerin de bölük bölük indirilecekleri o gün, gerçek otorite Allah’a aittir. kâfirler için o gün çok zordur."},{"n":26,"t":"25-26 Göğün bulutlarla yarılacağı ve meleklerin de bölük bölük indirilecekleri o gün, gerçek otorite Allah’a aittir. kâfirler için o gün çok zordur."},{"n":27,"t":"O gün zalim kişi “Ah, n’olaydım, keşke o Elçi ile birlikte bir yol tutsaydım!” diyerek, (pişmanlığından) ellerini ısıracaktır."},{"n":28,"t":"“Ah, yazık bana! Keşke falancayı dost edinmeseydim!"},{"n":29,"t":"Zikr (Kur’an) bana geldikten sonra (o kişi) beni şüphesiz (Kur’an’dan) saptırmıştır. (Meğer) şeytan(laşmış olanlar) insanı yüzüstü bırakırmış.”"},{"n":30,"t":"Elçi şöyle diyecektir: “Ey Rabbim! Kavmim bu Kur’an’ı yalnız bıraktı.”"},{"n":31,"t":"İşte böylece her peygamber için suçlulardan düşman(lar) yaptık. Doğru yola ulaştıran ve yardımcı olarak Rabbin yeter."},{"n":32,"t":"Kâfir olanlar “Kur’an ona bir kerede (topluca) indirilseydi ya!” dediler. İşte böylece, kalbini onunla iyice pekiştirmek için (peyderpey indirdik) ve onu tane tane okuduk."},{"n":33,"t":"Onlar sana örnek getirdiklerinde biz de sana gerçeği ve en güzel tefsiri (açıklamayı) mutlaka getirmişizdir."},{"n":34,"t":"Yüzüstü cehenneme (sürülüp) toplanacaklara (gelince), konumları çok kötü olanlar ve yolu en şaşkınlar işte onlardır."},{"n":35,"t":"Yemin olsun ki Musa’ya Kitabı vermiştik; beraberindeki kardeşi Harun’u ona yardımcı yapmıştık."},{"n":36,"t":"(Onlara) “Ayetlerimizi yalanlayan o kavme gidin!” demiştik. Sonunda (inkârcıları) yerle bir etmiştik."},{"n":37,"t":"Nuh kavmi de elçileri yalanladıklarında onları (suda) boğmuş ve kendilerini insanlar için bir ders kılmıştık. (Ahirette de) zalimler için acıklı bir azap hazırladık."},{"n":38,"t":"38-39 Âd, Semûd, Ress halkı ve bunlar arasında daha birçok nesle de örnekler vermiştik; (reddettikleri için) hepsini kırıp geçirmiştik."},{"n":39,"t":"38-39 Âd, Semûd, Ress halkı ve bunlar arasında daha birçok nesle de örnekler vermiştik; (reddettikleri için) hepsini kırıp geçirmiştik."},{"n":40,"t":"Yemin olsun ki (müşrikler) bela yağmuruna tutulmuş olan o şehre (Sodom’a) elbette uğramışlardır. Orayı (orada olup biteni) hiç mi görmediler? Hayır! Onlar diriltilmeyi ummuyorlar."},{"n":41,"t":"Seni gördükleri zaman “Allah elçi olarak bunu mu gönderdi!” (diyerek) seninle hep alay ediyorlar."},{"n":42,"t":"(Müşrikler) “Onları (savunmakta) kararlılık göstermemiş olsaydık, neredeyse bizi ilahlarımızın (yolundan) saptıracaktı!” (diyorlar). Azabı gördüklerinde kimin yolu şaşırdığını ileride bilecekler!"},{"n":43,"t":"Arzusunu ilahı edineni gördün mü? Sen ona koruyucu olabilir misin!"},{"n":44,"t":"Yoksa sen onların çoğunun gerçeği dinleyeceğini veya aklını kullanacağını mı sanıyorsun! Onlar (diğer canlılar) gibidir; hatta yol bakımından daha şaşkındırlar."},{"n":45,"t":"Rabbinin gölgeyi nasıl uzattığını görmedin mi? Dileseydi onu hareketsiz yapardı. Sonra güneşi ona (gölgeye) kılavuz yaptık."},{"n":46,"t":"Ardından onu (gölgeyi) kolayca kendimize çekip (aldık)."},{"n":47,"t":"Geceyi sizin için örtü, uykuyu dinlenme (zamanı) kılan, gündüzü diriliş (çalışma zamanı) yapan da O’dur."},{"n":48,"t":"48-49 Rüzgârları rahmetinin (yağmurun) önünde müjdeci olarak gönderen O’dur. O (su) sayesinde ölü toprağı canlandırmak ve onunla yarattıklarımızdan hayvanlara ve insanlara su vermek için gökten tertemiz suyu biz indirmekteyiz."},{"n":49,"t":"48-49 Rüzgârları rahmetinin (yağmurun) önünde müjdeci olarak gönderen O’dur. O (su) sayesinde ölü toprağı canlandırmak ve onunla yarattıklarımızdan hayvanlara ve insanlara su vermek için gökten tertemiz suyu biz indirmekteyiz."},{"n":50,"t":"Yemin olsun ki (gerçeği) hatırlasınlar diye bu (gibi gerçekleri) aralarında etraflı bir şekilde anlattık. İnsanların çoğu küfürden başka (bir karşılık vermemekte) direttiler."},{"n":51,"t":"Dileseydik elbette her şehre bir uyarıcı gönderirdik."},{"n":52,"t":"Kâfirlere boyun eğme! Bununla (Kur’an’la) onlara karşı büyük cihadı gerçekleştir."},{"n":53,"t":"Biri tatlı ve susuzluk giderici, diğeri tuzlu ve acı olan iki denizi salan da aralarına bir engel, yani karışmalarını engelleyen bir perde koyan da O’dur."},{"n":54,"t":"Sudan bir insan yaratan, onu (kan) akrabalıkları ve (evlilik) hısımlıkları sahibi yapan da O’dur. Rabbin gücü yetendir."},{"n":55,"t":"(Kâfirler) Allah’ın peşi sıra kendilerine yarar da zarar da veremeyen varlıklara tapıyorlar. İşte bu kâfir(ler), Rabbine karşı (şeytana) destek çıkmaya çalışır."},{"n":56,"t":"Biz seni sadece müjdeleyici ve uyarıcı olarak gönderdik."},{"n":57,"t":"De ki: “Buna karşılık sizden, Rabbine (giden) bir yol tutmayı dileyen kimse(ler olmanız) dışında herhangi bir ücret istemiyorum.”"},{"n":58,"t":"Ölümsüz diri olan (Allah)a güven ve O’nu hamd (övgü) ile tesbih et (yücelt)! Kullarının günahlarını bilen olarak O yeter."},{"n":59,"t":"Gökleri, yeri ve ikisinin arasındaki şeyleri altı günde (dönemde) yaratandır. Sonra da arşa istiva etmiştir. (O) Rahmân(dır)! Haberdar olan O’ndan sor (dile)!"},{"n":60,"t":"Onlara “Rahmân’a secde edin!” dendiği zaman, “Rahmân da neymiş! Bize emrettiğine boyun mu eğecekmişiz!” demişler ve bu istek onların nefretini artırmıştı."},{"n":61,"t":"Gökte burçlar var eden, orada bir kandil (güneş) ve aydınlatan bir ay yaratan (Allah) yüceler yücesidir."},{"n":62,"t":"(Gerçeği) hatırlamak isteyen veya şükretmek isteyen için gece ile gündüzü birbirinin peşine getiren de O’dur."},{"n":63,"t":"Rahmân’ın (iyi) kulları, yeryüzünde tevazu ile yürür ve o cahiller (müşrikler) onlara laf attığında ‘Selam!’ diyip (geçer)ler."},{"n":64,"t":"Rableri için gecelerini secde ve kıyam hâlinde geçirirler."},{"n":65,"t":"Şöyle derler: “Rabbimiz! Cehennem azabını bizden uzak tut! Şüphesiz ki onun azabı sargındır."},{"n":66,"t":"Orası ne kötü bir konaklama yeri ve makamdır!”"},{"n":67,"t":"Onlar infak ettikleri zaman israf da etmezler, cimrilik de yapmazlar; ikisi arasında orta bir yol tutarlar."},{"n":68,"t":"68-69 Onlar, Allah ile birlikte başka bir ilaha yalvarmazlar; Allah’ın haram (saygın) kıldığı cana haksız yere kıymazlar; zina yapmazlar. Bunu yapan kişi, kıyamet günü azabı katlanan ve içinde alçaltılmış olarak ebedî kalacağı bir ceza ile karşılaşacaktır."},{"n":69,"t":"68-69 Onlar, Allah ile birlikte başka bir ilaha yalvarmazlar; Allah’ın haram (saygın) kıldığı cana haksız yere kıymazlar; zina yapmazlar. Bunu yapan kişi, kıyamet günü azabı katlanan ve içinde alçaltılmış olarak ebedî kalacağı bir ceza ile karşılaşacaktır."},{"n":70,"t":"Ancak iman eden ve iyi iş(ler) yapıp (O’na) yönelenlerin kötülüklerini Allah iyiliklere çevirir. Allah çok bağışlayandır, çok merhametlidir."},{"n":71,"t":"(O’na) yönelip iyi iş(ler) yapan kişi Allah’a tam yönelmiş olur."},{"n":72,"t":"(Rahmân’ın kulları), yalana şahitlik etmez; boş şeylerle karşılaştıklarında onurlu bir şekilde geçip giderler."},{"n":73,"t":"Kendilerine Rablerinin ayetleri hatırlatıldığında ise onlara karşı sağır ve kör davranmazlar."},{"n":74,"t":"Onlar şöyle dua ederler: “Rabbimiz! Eşlerimizden ve nesillerimizden bize gözler aydınlığı ver ve bizi muttakîlere (duyarlı olanlara) önder kıl!”"},{"n":75,"t":"İşte onlar, sabretmelerine karşılık (cennette) yüksek bir makamla ödüllendirilecekler, orada esenlik ve selam ile karşılanacaklardır."},{"n":76,"t":"İçlerinde ebedî kalacaklardır. Orası ne güzel bir ikamet yeri ve makamdır!"},{"n":77,"t":"De ki: “Duanız olmasaydı, Rabbim size neden değer versin ki!” (kâfirlere de ki): “Siz ise elbette (gerçeği) yalanladınız. Onun için ileride (bu günah size) yapışacaktır!”"}],[{"n":1,"t":"Tâ. Sîn. Mîm."},{"n":2,"t":"İşte şu(nlar), apaçık Kitabın ayetleridir."},{"n":3,"t":"Onlar iman etmiyor diye nerdeyse kendine yazık edeceksin!"},{"n":4,"t":"Dilesek, üzerlerine gökten bir ayet (mucize) indiririz de ona boyunları eğik kalır."},{"n":5,"t":"Kendilerine, Rahmân’dan her yeni mesaj geldiğinde ondan yüz çevirirler."},{"n":6,"t":"Elbette (bu mesajı) da yalanladılar; (fakat) alay edip durdukları şeylerin haberleri yakında kendilerine gelecektir."},{"n":7,"t":"Yerde her değerli çiftten nice (bitkiler) yetiştirdiğimizi hiç mi görmediler?"},{"n":8,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":9,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":10,"t":"10-11 Hani Rabbin, Musa’ya “Zalim topluma, yani Firavun’un kavmine git! (Hâlâ) takvâlı (duyarlı) davranmayacaklar mı?” diye seslenmişti."},{"n":11,"t":"10-11 Hani Rabbin, Musa’ya “Zalim topluma, yani Firavun’un kavmine git! (Hâlâ) takvâlı (duyarlı) davranmayacaklar mı?” diye seslenmişti."},{"n":12,"t":"(Musa) şöyle demişti: “Rabbim! Beni yalanlamalarından korkuyorum."},{"n":13,"t":"İçim daralabilir, dilim dönmeyebilir; (bu nedenle) Harun’a da elçilik ver!"},{"n":14,"t":"Onların lehinde, benim aleyhimde bir suç(um) var. beni öldürmelerinden korkuyorum.”"},{"n":15,"t":"(Allah) şöyle demişti: “Hayır! İkiniz mesajlarımı götürün! Biz sizinle birlikteyiz; (olup biteni) duymaktayız."},{"n":16,"t":"16-17 Firavun’a gidin ve deyin ki: ‘Şüphesiz ki biz, İsrailoğullarını bizimle göndermen için âlemlerin Rabbi’nin elçi(leri)yiz.”"},{"n":17,"t":"16-17 Firavun’a gidin ve deyin ki: ‘Şüphesiz ki biz, İsrailoğullarını bizimle göndermen için âlemlerin Rabbi’nin elçi(leri)yiz.”"},{"n":18,"t":"(Firavun) şöyle demişti: “Biz seni aramızda çocukken büyütmemiş miydik? Sen de ömründen senelerce aramızda kalmıştın."},{"n":19,"t":"Yaptığın o işini de yapmıştın. Sen nankörlerdensin.”"},{"n":20,"t":"(Musa) şöyle demişti: “Ben o zaman şaşkınlardan olarak o işi yapmıştım."},{"n":21,"t":"Sizden korktuğum için de aranızdan kaçmıştım. Sonra Rabbim bana hikmet (doğru hüküm verme yeteneği) verdi ve beni elçilerden (biri olarak) görevlendirdi."},{"n":22,"t":"Başıma kaktığın o nimete gelince, (onun sebebi de) İsrailoğullarını kendine kul köle etmendi.”"},{"n":23,"t":"(Firavun) “Âlemlerin Rabbi de nedir?” demişti."},{"n":24,"t":"(Musa ise) “Kesin inananlar olursanız, (bilin ki) O, göklerin, yerin ve ikisi arasında bulunan her şeyin Rabbidir.” demişti."},{"n":25,"t":"(Firavun) etrafındakilere “Duymuyor musunuz?” demişti."},{"n":26,"t":"(Musa ise) “O, sizin de Rabbinizdir; önceki atalarınızın da Rabbidir.” demişti."},{"n":27,"t":"(Firavun) “Size gönderilen bu Elçiniz mutlaka cinlenmiştir!” demişti."},{"n":28,"t":"(Musa ise) “Aklınızı kullanırsanız (anlarsınız ki Allah), doğunun, batının ve ikisi arasında bulunanların da Rabbidir.” demişti."},{"n":29,"t":"(Firavun) “Benden başkasını ilah edinirsen şüphesiz ki seni hapse atılanlardan yaparım!” demişti."},{"n":30,"t":"(Musa ise) “Sana apaçık bir şey (delil) getirsem de mi (hapse atarsın)?” diye sormuştu."},{"n":31,"t":"(Firavun da) “Doğru söyleyenlerdensen getir onu (delilini)!” demişti."},{"n":32,"t":"(Musa) asasını atmıştı. Bir de ne görsünler, o (asa) apaçık bir yılan (olmuş)!"},{"n":33,"t":"Elini de (koynundan) çıkarmıştı. Bir de ne görsünler, o (eli) bakanlara bembeyaz (görünmüştü)."},{"n":34,"t":"34-35 (Firavun) çevresindeki yöneticilere şöyle demişti: “Bu, sizi büyüsüyle yurdunuzdan çıkarmak isteyen çok bilgili bir büyücüdür. Öneriniz nedir?”"},{"n":35,"t":"34-35 (Firavun) çevresindeki yöneticilere şöyle demişti: “Bu, sizi büyüsüyle yurdunuzdan çıkarmak isteyen çok bilgili bir büyücüdür. Öneriniz nedir?”"},{"n":36,"t":"36-37 (Onlar) şöyle demişlerdi: “Kardeşiyle birlikte onu (Musa’yı) alıkoy ve bütün bilgin büyücüleri sana getirmeleri için toplayıcıları şehirlere gönder!”"},{"n":37,"t":"36-37 (Onlar) şöyle demişlerdi: “Kardeşiyle birlikte onu (Musa’yı) alıkoy ve bütün bilgin büyücüleri sana getirmeleri için toplayıcıları şehirlere gönder!”"},{"n":38,"t":"(Ardından) büyücüler belirli bir günün belirlenen vaktinde bir araya getirilmişlerdi."},{"n":39,"t":"İnsanlara da “Siz de toplanıyor musunuz? (toplanın)!” denmişti."},{"n":40,"t":"(Şehir halkı:) “Umarız ki büyücüler üstün gelirlerse büyücülere uyarız!” (demişti)."},{"n":41,"t":"Büyücüler geldiklerinde, Firavun’a “Galip gelirsek bize ödül var, değil mi?” demişlerdi."},{"n":42,"t":"(Firavun) “Tamam! Şüphesiz ki o takdirde siz gözdelerimden (olacaksı)nız!” demişti."},{"n":43,"t":"Musa onlara “Ne atacaksanız atın!” demişti."},{"n":44,"t":"İplerini ve asalarını atmış ve “Firavun’un itibarı için elbette biz galip geleceğiz!” demişlerdi."},{"n":45,"t":"Musa da asasını atmıştı. Bir de ne görsünler, (Musa’nın asası) onların uydurduklarını yutuyor."},{"n":46,"t":"(Bunu gören) büyücüler derhal secdeye kapanmışlardı."},{"n":47,"t":"47-48 “Âlemlerin Rabbine, yani Musa ve Harun’un Rabbine inanıp güvendik!” demişlerdi."},{"n":48,"t":"47-48 “Âlemlerin Rabbine, yani Musa ve Harun’un Rabbine inanıp güvendik!” demişlerdi."},{"n":49,"t":"(Firavun) şöyle demişti: “Ben size izin vermeden ona iman ettiniz, (öyle mi)! Şüphesiz ki o (Musa), size büyü öğreten büyüğünüzdür (akıl hocanızdır). İleride (size neler yapacağımı) elbette bileceksiniz. Dönekliğ(iniz)den dolayı kesinlikle ellerinizi ve ayaklarınızı elbette kestireceğim ve hepinizi astıracağım!”"},{"n":50,"t":"(Büyücüler) şöyle demişlerdi: “Zararı yok, (nasıl olsa) Rabbimize döneceğiz."},{"n":51,"t":"İlk iman edenler (iman edenlerin öncüleri) olduğumuz için Rabbimizin hatalarımızı bağışlayacağını umuyoruz.”"},{"n":52,"t":"Musa’ya “Kullarımı geceleyin yola çıkar; şüphesiz ki takip edileceksiniz!” diye vahyetmiştik."},{"n":53,"t":"Firavun da şehirlere (asker) toplayıcılar göndermişti."},{"n":54,"t":"54-56 “Şüphesiz ki bunlar az bir topluluktur; (ama) bize karşı öfke doludurlar. Biz ise donanımlı bir topluluğuz!” (demişti)."},{"n":55,"t":"54-56 “Şüphesiz ki bunlar az bir topluluktur; (ama) bize karşı öfke doludurlar. Biz ise donanımlı bir topluluğuz!” (demişti)."},{"n":56,"t":"54-56 “Şüphesiz ki bunlar az bir topluluktur; (ama) bize karşı öfke doludurlar. Biz ise donanımlı bir topluluğuz!” (demişti)."},{"n":57,"t":"57-58 Onları (Firavun ve halkını) bahçeler(in)den, (su) kaynaklarından, hazinelerden ve değerli makamlardan çıkarmıştık."},{"n":58,"t":"57-58 Onları (Firavun ve halkını) bahçeler(in)den, (su) kaynaklarından, hazinelerden ve değerli makamlardan çıkarmıştık."},{"n":59,"t":"Böylece İsrailoğullarını onlara (geride bıraktıklarına) mirasçı yapmıştık."},{"n":60,"t":"(Firavun ve adamları) gün doğarken onların peşine düşmüşlerdi."},{"n":61,"t":"İki topluluk birbirini görünce Musa’nın halkı “Şüphesiz ki yakalandık!” demişlerdi."},{"n":62,"t":"(Musa) “Asla! Şüphesiz ki Rabbim benimledir, bana yol gösterecektir!” demişti."},{"n":63,"t":"Musa’ya “Asanla denize vur!” diye vahyetmiştik. (Deniz) derhal yarılmış; her bölüm koca bir dağ gibi olmuştu."},{"n":64,"t":"Diğerlerini oraya yaklaştırmıştık."},{"n":65,"t":"Musa ve beraberindekilerin hepsini kurtarmıştık."},{"n":66,"t":"Sonra diğerlerini (suda) boğmuştuk."},{"n":67,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":68,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":69,"t":"Onlara İbrahim’in haberini tilavet et (okuyup aktar)!"},{"n":70,"t":"Hani o (İbrahim), babasına ve kavmine “Neye tapıyorsunuz?” diye sormuştu."},{"n":71,"t":"Onlar “Putlara tapıyoruz ve onlara tapmaya devam edeceğiz!” demişlerdi."},{"n":72,"t":"72-73 (İbrahim) “Kendilerine yalvardığınızda sizi duyuyorlar veya size yarar ya da zarar verebiliyorlar mı?” diye sormuştu."},{"n":73,"t":"72-73 (İbrahim) “Kendilerine yalvardığınızda sizi duyuyorlar veya size yarar ya da zarar verebiliyorlar mı?” diye sormuştu."},{"n":74,"t":"Onlar “Hayır ama biz babalarımızı böyle yapar bulduk!” cevabını vermişlerdi."},{"n":75,"t":"75-76 (İbrahim) şöyle demişti: “Siz ve önceki atalarınız neye taptığınızı hiç düşündünüz mü?"},{"n":76,"t":"75-76 (İbrahim) şöyle demişti: “Siz ve önceki atalarınız neye taptığınızı hiç düşündünüz mü?"},{"n":77,"t":"Şüphesiz ki onlar (putlar) benim düşmanımdır; sadece âlemlerin Rabbine (kulluk ederim)."},{"n":78,"t":"Beni yaratan ve bana doğru yolu gösterendir."},{"n":79,"t":"Beni yediren ve içirendir."},{"n":80,"t":"Hastalandığımda bana şifa verendir."},{"n":81,"t":"Beni öldürüp sonra diriltecek olandır."},{"n":82,"t":"Hesap gününde benim için hatalarımı bağışlayacağını umduğum O’dur."},{"n":83,"t":"Rabbim! Bana doğru hüküm verme yeteneği ver ve beni iyiler arasına kat!"},{"n":84,"t":"Bana, (benden) sonra gelecekler arasında iyilikle anılmayı nasip et!"},{"n":85,"t":"Beni, nimet cennetinin mirasçılarından kıl!"},{"n":86,"t":"Şaşkınlardan olan babamı da bağışla!"},{"n":87,"t":"87-89 Samimi bir kalp ile gelenlerin dışında, mal ve çocukların (kişiye) yarar sağlayamayacağı gün, yani (insanların) diriltilecekleri gün beni rezil etme!”"},{"n":88,"t":"87-89 Samimi bir kalp ile gelenlerin dışında, mal ve çocukların (kişiye) yarar sağlayamayacağı gün, yani (insanların) diriltilecekleri gün beni rezil etme!”"},{"n":89,"t":"87-89 Samimi bir kalp ile gelenlerin dışında, mal ve çocukların (kişiye) yarar sağlayamayacağı gün, yani (insanların) diriltilecekleri gün beni rezil etme!”"},{"n":90,"t":"(O gün) cennet, muttakîlere (duyarlı olanlara) yaklaştırılacaktır."},{"n":91,"t":"Cehennem de azgınlar için ortaya çıkartılacaktır."},{"n":92,"t":"92-93 Onlara (cehennemliklere) “Allah’ın peşi sıra taptıklarınız nerede? Size yardım edebiliyorlar mı veya kendilerine yardımları dokunuyor mu?” denecektir."},{"n":93,"t":"92-93 Onlara (cehennemliklere) “Allah’ın peşi sıra taptıklarınız nerede? Size yardım edebiliyorlar mı veya kendilerine yardımları dokunuyor mu?” denecektir."},{"n":94,"t":"94-95 Onlar (İbrahim’in kavmi) bütün azgınlar ve İblis’in askerleri, hepsi tepetaklak cehenneme atılacaklardır."},{"n":95,"t":"94-95 Onlar (İbrahim’in kavmi) bütün azgınlar ve İblis’in askerleri, hepsi tepetaklak cehenneme atılacaklardır."},{"n":96,"t":"(Cehennemlikler) orada birbirleriyle çekişerek şöyle diyeceklerdir:"},{"n":97,"t":"97-98 Allah’a yemin olsun: Sizi âlemlerin Rabbiyle eşit saymakla doğrusu apaçık bir sapkınlık içindeymişiz."},{"n":98,"t":"97-98 Allah’a yemin olsun: Sizi âlemlerin Rabbiyle eşit saymakla doğrusu apaçık bir sapkınlık içindeymişiz."},{"n":99,"t":"Bizi, o suçlulardan başkası saptırmadı."},{"n":100,"t":"Bizim için şefaatçiler de yok."},{"n":101,"t":"Yakın bir dost da yok."},{"n":102,"t":"Keşke bizim için (dünyaya) bir daha dönüş olsaydı da müminlerden olsa(ydı)k!”"},{"n":103,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":104,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":105,"t":"Nuh’un kavmi de elçileri yalanlamıştı."},{"n":106,"t":"Kardeşleri Nuh onlara şöyle demişti: “(Allah’a karşı) takvâlı (duyarlı) olmaz mısınız?"},{"n":107,"t":"Ben size (gönderilmiş) güvenilir bir elçiyim."},{"n":108,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":109,"t":"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim yalnızca âlemlerin Rabbine aittir."},{"n":110,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!”"},{"n":111,"t":"(Kavmi) “Sana düşük (seviyeli) insanlar uymuşken, biz sana iman eder miyiz hiç!” demişti."},{"n":112,"t":"(Nuh) şöyle demişti: “Onların (daha önce) neler yaptığına dair hiçbir bilgim yok."},{"n":113,"t":"Düşünürseniz, onların hesabının ancak Rabbime ait olduğunu anlarsınız."},{"n":114,"t":"Ben müminleri asla (yanımdan) kovamam."},{"n":115,"t":"Ben ancak apaçık bir uyarıcıyım.”"},{"n":116,"t":"(Kavmi) şöyle demişti: “Ey Nuh! (Bu davandan) vazgeçmezsen (iyi bil ki) kovulmuşlardan olacaksın!”"},{"n":117,"t":"(Nuh, Rabbine yönelerek) “Rabbim! Kavmim beni yalanladı."},{"n":118,"t":"Benimle onlar arasında hükmünü ver ve hem beni hem de benimle birlikte inananları kurtar!” demişti."},{"n":119,"t":"Biz de onu ve beraberindekileri dolu gemide (taşıyarak) kurtarmıştık."},{"n":120,"t":"Sonra da geride kalanları (suda) boğmuştuk."},{"n":121,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":122,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":123,"t":"Âd (kavmi) de elçileri yalanlamıştı."},{"n":124,"t":"Kardeşleri Hud onlara şöyle demişti: “(Allah’a karşı) takvâlı (duyarlı) olmaz mısınız?"},{"n":125,"t":"Ben size (gönderilmiş) güvenilir bir elçiyim."},{"n":126,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":127,"t":"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim yalnızca âlemlerin Rabbine aittir."},{"n":128,"t":"Siz övünüp eğlenmek üzere her yüksek yere bir ayet (anıt) mı dikiyorsunuz?"},{"n":129,"t":"Sürekli kalacağınızı umarak sağlam yapılar yapıyorsunuz."},{"n":130,"t":"(İnsanları) yakaladığınız zaman zorbalar olarak yakalıyorsunuz."},{"n":131,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":132,"t":"132-134 Bildiğiniz şeyleri size bolca verene yani hayvanları, çocukları, bahçeleri ve (su) kaynaklarını size bolca verene (Allah’a karşı) takvâlı (duyarlı) olun!"},{"n":133,"t":"132-134 Bildiğiniz şeyleri size bolca verene yani hayvanları, çocukları, bahçeleri ve (su) kaynaklarını size bolca verene (Allah’a karşı) takvâlı (duyarlı) olun!"},{"n":134,"t":"132-134 Bildiğiniz şeyleri size bolca verene yani hayvanları, çocukları, bahçeleri ve (su) kaynaklarını size bolca verene (Allah’a karşı) takvâlı (duyarlı) olun!"},{"n":135,"t":"Şüphesiz ki üzerinize gelecek büyük bir günün azabından korkuyorum.”"},{"n":136,"t":"(Kavmi ise) şöyle demişti: “Öğüt versen de öğüt verenlerden olmasan da bizim için birdir."},{"n":137,"t":"Bu (söylediklerin) öncekilerin uydurmalarından başka bir şey değildir."},{"n":138,"t":"Biz asla azaba uğratılacak da değiliz.”"},{"n":139,"t":"Böylece onu (Hud’u) yalanlamışlar; biz de kendilerini helak etmiştik. Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":140,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":141,"t":"Semûd (kavmi) de elçileri yalanlamıştı."},{"n":142,"t":"Kardeşleri Salih onlara şöyle demişti: “(Allah’a karşı) takvâlı (duyarlı) olmuyor musunuz?"},{"n":143,"t":"Ben size (gönderilmiş) güvenilir bir elçiyim."},{"n":144,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":145,"t":"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim yalnızca âlemlerin Rabbine aittir."},{"n":146,"t":"146-148 Siz burada, bahçelerde, (su) kaynaklarında, ekinlerin ve salkımları aşağıya sarkmış hurmalıkların içinde güvende bırakılacak mısınız?"},{"n":147,"t":"146-148 Siz burada, bahçelerde, (su) kaynaklarında, ekinlerin ve salkımları aşağıya sarkmış hurmalıkların içinde güvende bırakılacak mısınız?"},{"n":148,"t":"146-148 Siz burada, bahçelerde, (su) kaynaklarında, ekinlerin ve salkımları aşağıya sarkmış hurmalıkların içinde güvende bırakılacak mısınız?"},{"n":149,"t":"Şımarıklık yaparak dağlardan (kayalardan) evler yontuyorsunuz."},{"n":150,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":151,"t":"151-152 Yeryüzünde bozgunculuk yapıp ıslah edici olmayan haddi aşanların emrine itaat etmeyin!”"},{"n":152,"t":"151-152 Yeryüzünde bozgunculuk yapıp ıslah edici olmayan haddi aşanların emrine itaat etmeyin!”"},{"n":153,"t":"(Kavmi ise Salih’e) şöyle demişti: “Sen sadece büyülenmişlerdensin."},{"n":154,"t":"Sen de ancak bizim gibi bir insansın. Doğru söyleyenlerdensen (bize) bir delil getir!”"},{"n":155,"t":"(Salih de) şöyle demişti: “İşte (delil) bu dişi devedir. (Belirli bir gün) su içme (hakkı) onun; belirli (bir) günün içme (hakkı da) sizindir!"},{"n":156,"t":"Sakın ona hiçbir kötülük yapmayın; yoksa büyük bir günün azabı sizi yakalar.”"},{"n":157,"t":"Onu (deveyi) hunharca katletmiş, (sonradan) pişman olmuşlardı."},{"n":158,"t":"(Ama çoktan) o azap kendilerini yakalamıştı. Çoğu inanmamış olsa da şüphesiz ki bunda, bir ders vardır."},{"n":159,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":160,"t":"Lut kavmi de (gelen) elçileri yalanlamıştı."},{"n":161,"t":"Kardeşleri Lut onlara şöyle demişti: “(Allah’a karşı) takvâlı (duyarlı) olmuyor musunuz?"},{"n":162,"t":"Ben size gönderilmiş (güvenilir) bir elçiyim."},{"n":163,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":164,"t":"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim yalnızca âlemlerin Rabbine aittir."},{"n":165,"t":"Rabbinizin sizin için yarattığı eşlerinizi bırakıyorsunuz."},{"n":166,"t":"İnsanlar içinden erkeklere mi yaklaşıyorsunuz! Doğrusu siz sınırı aşmış (sapkın) bir topluluksunuz!”"},{"n":167,"t":"(Kavmi), “Ey Lut! (Bu davandan) vazgeçmezsen mutlaka (kovulup) çıkartılanlardan olacaksın!” demişti."},{"n":168,"t":"(Lut da) “Doğrusu ben sizin bu işiniz nedeniyle (sizi) kınayanlardanım!” demişti."},{"n":169,"t":"Rabbim! Onların yaptıkları işin (sonucundan) beni ve ailemi kurtar!” (diye dua etmişti)."},{"n":170,"t":"170-171 Biz de geride kalanlar arasındaki yaşlı (eşi) hariç, onu ve bütün ailesini kurtarmıştık."},{"n":171,"t":"170-171 Biz de geride kalanlar arasındaki yaşlı (eşi) hariç, onu ve bütün ailesini kurtarmıştık."},{"n":172,"t":"Ardından diğerlerini helak etmiştik."},{"n":173,"t":"Üzerlerine büyük bir bela yağmuru yağdırmıştık. Uyarılanların (ama yola gelmeyenlerin) bela yağmuru ne de kötü (olmuştu)!"},{"n":174,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":175,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":176,"t":"Eyke halkı da (bütün) elçileri yalanlamıştı."},{"n":177,"t":"Şuayb onlara şöyle demişti: “(Allah’a karşı) takvâlı (duyarlı) olmaz mısınız?"},{"n":178,"t":"Ben size gönderilmiş (güvenilir) bir elçiyim."},{"n":179,"t":"Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":180,"t":"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim yalnızca âlemlerin Rabbine aittir."},{"n":181,"t":"Ölçüyü tastamam yapın; (başkalarının hakkını) eksik verenlerden olmayın!"},{"n":182,"t":"Doğru bir terazi ile tartın!"},{"n":183,"t":"İnsanlara eşyalarını eksik vermeyin! Yeryüzünde bozguncular olarak karışıklık çıkarmayın!"},{"n":184,"t":"Sizi de önceki nesilleri de yaratan (Allah’a karşı) takvâlı (duyarlı) olun!”"},{"n":185,"t":"(Kavmi) şöyle demişti: “Sen sadece büyülenmişlerdensin."},{"n":186,"t":"Sen de ancak bizim gibi bir insansın. Biz seni şüphesiz ki yalancılardan sanıyoruz."},{"n":187,"t":"Doğru sözlülerdensen üzerimize gökten bir parça indir!”"},{"n":188,"t":"(Şuayb) “Rabbim yaptıklarınızı çok iyi bilendir.” demişti."},{"n":189,"t":"Onu yalanlamışlar ve kendilerini o gölge gününün azabı yakalamıştı. Şüphesiz ki o, büyük bir günün azabıydı!"},{"n":190,"t":"Çoğu inanmamış olsa da şüphesiz ki bunda bir ders vardır."},{"n":191,"t":"Şüphesiz ki Rabbin güçlüdür, çok merhametlidir."},{"n":192,"t":"Şüphesiz ki o (Kur’an), âlemlerin Rabbi tarafından indirilmiştir."},{"n":193,"t":"193-195 Uyarıcılardan olasın diye onu (Kur’an’ı) apaçık Arapça diliyle Güvenilir Ruh (Cebrail) senin kalbine indirmiştir."},{"n":194,"t":"193-195 Uyarıcılardan olasın diye onu (Kur’an’ı) apaçık Arapça diliyle Güvenilir Ruh (Cebrail) senin kalbine indirmiştir."},{"n":195,"t":"193-195 Uyarıcılardan olasın diye onu (Kur’an’ı) apaçık Arapça diliyle Güvenilir Ruh (Cebrail) senin kalbine indirmiştir."},{"n":196,"t":"O (Kur’an’ın ilkeleri), öncekilerin kitaplarında da vardı."},{"n":197,"t":"İsrailoğulları âlimlerinin onu (Kur’an’ı) tanıyıp bilmesi, o (inkârcılar) için bir delil değil midir?"},{"n":198,"t":"198-199 Biz Kur’an’ı, Arap olmayanlardan birine indirseydik de onu kendilerine (farklı bir dilde) okusaydık yine de ona inanmazlardı."},{"n":199,"t":"198-199 Biz Kur’an’ı, Arap olmayanlardan birine indirseydik de onu kendilerine (farklı bir dilde) okusaydık yine de ona inanmazlardı."},{"n":200,"t":"Biz onu (Kur’an’ı), suçluların kalplerine (gözlerinin içine) böylece soktuk."},{"n":201,"t":"201-202 Hiç farkına varmadan kendilerine ansızın gelecek acıklı azabı görünceye kadar ona iman etmezler."},{"n":202,"t":"201-202 Hiç farkına varmadan kendilerine ansızın gelecek acıklı azabı görünceye kadar ona iman etmezler."},{"n":203,"t":"(Azabı gördüklerinde) “Bize süre tanınır mı?” diyeceklerdir."},{"n":204,"t":"Azabımızı acele mi istiyorlar?"},{"n":205,"t":"205-206 Şimdi şunu bir düşün: “Biz onları senelerce yaşatsak, sonra da (kendilerine) söz verilmiş olan (azap) başlarına gelse,"},{"n":206,"t":"205-206 Şimdi şunu bir düşün: “Biz onları senelerce yaşatsak, sonra da (kendilerine) söz verilmiş olan (azap) başlarına gelse,"},{"n":207,"t":"Yararlandırıldıkları nimetlerin kendilerine hiçbir yararı olmayacaktır.”"},{"n":208,"t":"208-209 Zaten gerçeği hatırlatan uyarıcılar olmadan hiçbir şehri helak etmemiştik; biz kimseye haksızlık edici de değildik."},{"n":209,"t":"208-209 Zaten gerçeği hatırlatan uyarıcılar olmadan hiçbir şehri helak etmemiştik; biz kimseye haksızlık edici de değildik."},{"n":210,"t":"210-211 Onu (Kur’an’ı) şeytanlar indirmemiştir; bu onlara yaraşmaz; zaten (buna) güçleri de yetmez."},{"n":211,"t":"210-211 Onu (Kur’an’ı) şeytanlar indirmemiştir; bu onlara yaraşmaz; zaten (buna) güçleri de yetmez."},{"n":212,"t":"Onlar (şeytanlar), vahyi duymaktan kesin olarak uzak tutulmuşlardır."},{"n":213,"t":"Allah ile birlikte herhangi bir ilaha sakın yalvarma; yoksa sen de azap edilenlerden olursun!"},{"n":214,"t":"(Önce) yakın akrabanı uyar!"},{"n":215,"t":"Sana uyan müminlere (merhamet) kanadını indir!"},{"n":216,"t":"Onlar sana isyan ederlerse de ki: “Ben sizin yapmakta olduğunuz şeylerden uzağım.”"},{"n":217,"t":"217-220 Ayağa kalktığında ve secde edenler arasındaki dolaşmanda seni görene, (ayrıca) duyan, bilen, güçlü, çok merhametli olana (Allah’a) güven!"},{"n":218,"t":"217-220 Ayağa kalktığında ve secde edenler arasındaki dolaşmanda seni görene, (ayrıca) duyan, bilen, güçlü, çok merhametli olana (Allah’a) güven!"},{"n":219,"t":"217-220 Ayağa kalktığında ve secde edenler arasındaki dolaşmanda seni görene, (ayrıca) duyan, bilen, güçlü, çok merhametli olana (Allah’a) güven!"},{"n":220,"t":"217-220 Ayağa kalktığında ve secde edenler arasındaki dolaşmanda seni görene, (ayrıca) duyan, bilen, güçlü, çok merhametli olana (Allah’a) güven!"},{"n":221,"t":"Şeytanların kime ineceğini size bildireyim mi?"},{"n":222,"t":"Onlar günaha, iftiraya düşkün olan herkese inerler."},{"n":223,"t":"Onlar (yalan sözlere) kulak verirler; çoğu da yalancıdır."},{"n":224,"t":"(İnançsız) şairler(e gelince), onlara azgınlar uyarlar."},{"n":225,"t":"225-226 Onların her vadide şaşkın şaşkın dolaştıklarını ve yapmayacakları şeyleri söylediklerini görmüyor musun?"},{"n":226,"t":"225-226 Onların her vadide şaşkın şaşkın dolaştıklarını ve yapmayacakları şeyleri söylediklerini görmüyor musun?"},{"n":227,"t":"Ancak iman edip iyi işler yapanlar, Allah’ı çok ananlar ve haksızlığa uğratıldıklarında kendilerini savunanlar hariç. Haksızlık edenler, nasıl bir devrimle devrileceklerini ileride bileceklerdir."}],[{"n":1,"t":"Tâ. Sîn. İşte şu(nlar) Kur’an’ın ve apaçık Kitabın ayetleridir."},{"n":2,"t":"(Kur’an) müminler için bir rehber ve müjdedir."},{"n":3,"t":"Onlar namazı kılar, zekatı verir ve ahirete de kesin bir şekilde inanırlar."},{"n":4,"t":"Ahirete inanmayanların işlerini, kendilerine süslü gösterdik; bocalayıp duruyorlar."},{"n":5,"t":"İşte onlar, azabı en kötü olanlardır; ahirette en çok kaybedecek olanlar da onlardır."},{"n":6,"t":"Şüphesiz ki Kur’an doğru hüküm veren, bilen (Allah) tarafından sana vahyedilmektedir."},{"n":7,"t":"Hani Musa ailesine şöyle demişti: “Ben bir ateş gördüm. Size oradan bir haber getireceğim veya ısınacağınız bir kor getireceğim.”"},{"n":8,"t":"Oraya geldiğinde (kendisine) şöyle seslenilmişti: “Ateşin yanındakiler ve çevresindekiler bereketli kılınmıştır. Âlemlerin Rabbi olan Allah yücedir."},{"n":9,"t":"Ey Musa! Güçlü, doğru hüküm veren Allah, benim ben!"},{"n":10,"t":"Asanı (yere) bırak!” Onu yılan gibi depreşir görünce, arkasına bakmadan geri dönmüştü. (Ona şöyle söylenmişti): “Ey Musa! Korkma! Çünkü benim huzurumda elçiler korkmaz."},{"n":11,"t":"Ancak haksızlık edip sonra da işlediği kötülüğün ardından güzel davranan kişi (bilsin ki) ben çok bağışlayanım; çok merhametliyim."},{"n":12,"t":"Elini koynuna sok ki kusursuz bembeyaz çıksın! (Sen de) dokuz delil (mucize) ile Firavun’a ve kavmine (git)! Çünkü onlar, yoldan çıkmış bir topluluk oldular."},{"n":13,"t":"Gerçeği ortaya koyucu delillerimiz kendilerine gelince ‘Bu, apaçık bir büyüdür!’ demişlerdi."},{"n":14,"t":"Kendileri bu delillere kesin olarak inandıkları hâlde, haksızlık ve kibirleri nedeniyle onları inkâr etmişlerdi. Bozguncuların sonunun nasıl olduğuna bir bak!”"},{"n":15,"t":"Yemin olsun ki biz Davud’a ve Süleyman’a bir ilim vermiştik; (onlar) “Bizi mümin kullarından birçoğuna üstün kılan Allah’a hamd (övgü) olsun.” demişlerdi."},{"n":16,"t":"Süleyman, Davud’a mirasçı olmuş ve şöyle demişti: “Ey insanlar! Bize kuşların dili öğretildi ve bize (yararlı) her şeyden (pay) verildi.” Doğrusu bu apaçık bir lütuftur."},{"n":17,"t":"Süleyman için cinden, insandan ve kuştan oluşan orduları toplanmıştı; hepsi düzenli olarak sevk ediliyor(du)."},{"n":18,"t":"Sonunda Karınca Vadisi’ne geldikleri zaman bir karınca “Ey karıncalar! Yuvalarınıza girin! Süleyman ve ordusu, farkına varmadan sizi ezmesin!” demişti."},{"n":19,"t":"(Süleyman, karıncanın) sözünden dolayı neşeyle tebessüm etmiş ve şöyle demişti: “Rabbim! Bana ve ana babama verdiğin nimet(ler)e şükretmemde ve razı olacağın iyi iş(ler) yapmamda beni başarılı kıl! Beni merhametinle iyi kullarının arasına kat!”"},{"n":20,"t":"(Süleyman) kuşları denetlemiş ve “Neden Hüdhüd’ü göremiyorum? Yoksa kayıplardan mı oldu?"},{"n":21,"t":"Şüphesiz ki ya onu şiddetli bir şekilde cezalandıracağım veya onu keseceğim ya da bana apaçık bir delil (mazeret) getirecek!” demişti."},{"n":22,"t":"Çok geçmeden (Hüdhüd) gelmiş ve şöyle demişti: “Ben senin bilmediğin bir şeyi öğrendim ve sebe’den sana kesin bir haber getirdim."},{"n":23,"t":"Kendisine her şeyden (bolca) verilmiş ve büyük de bir tahtı olan bir hanımı (Belkıs’ı) onları yönetir buldum."},{"n":24,"t":"Onu ve kavmini, Allah’ın peşi sıra güneşe secde eder buldum. Şeytan, yaptıkları işleri kendilerine süslü göstermiş ve onları doğru yoldan alıkoymuştur. Onlar doğru yolu bulamıyorlar."},{"n":25,"t":"25-26 (Oysa) göklerde ve yerde gizleneni açığa çıkaran, gizlediğinizi ve açıkladığınızı bilen, (asıl en) büyük tahtın sahibi, kendisinden başka ilah olmayan Allah’a secde etmeleri gerekmez mi?”"},{"n":26,"t":"25-26 (Oysa) göklerde ve yerde gizleneni açığa çıkaran, gizlediğinizi ve açıkladığınızı bilen, (asıl en) büyük tahtın sahibi, kendisinden başka ilah olmayan Allah’a secde etmeleri gerekmez mi?”"},{"n":27,"t":"(Süleyman, Hüdhüd’e) şöyle demişti: “Doğru mu söyledin yoksa yalancılardan mısın, bakacağız."},{"n":28,"t":"Şu mektubumu götür ve kendilerine ver; sonra (kenara) çekil de ne sonuca varacaklarına bak!”"},{"n":29,"t":"29-31 (Belkıs) “Ey yöneticiler! Bana Süleyman’dan gelen, ‘Rahmân, Rahîm olan Allah’ın adıyla’ diye (başlayan ve) ‘Bana baş kaldırmayın; teslim olarak bana gelin!’ (mesajını içeren) çok değerli bir mektup gönderildi.” demişti."},{"n":30,"t":"29-31 (Belkıs) “Ey yöneticiler! Bana Süleyman’dan gelen, ‘Rahmân, Rahîm olan Allah’ın adıyla’ diye (başlayan ve) ‘Bana baş kaldırmayın; teslim olarak bana gelin!’ (mesajını içeren) çok değerli bir mektup gönderildi.” demişti."},{"n":31,"t":"29-31 (Belkıs) “Ey yöneticiler! Bana Süleyman’dan gelen, ‘Rahmân, Rahîm olan Allah’ın adıyla’ diye (başlayan ve) ‘Bana baş kaldırmayın; teslim olarak bana gelin!’ (mesajını içeren) çok değerli bir mektup gönderildi.” demişti."},{"n":32,"t":"(Belkıs:) “Ey yöneticiler! Bu işimde bana bir fikir verin! Bana şahit oluncaya (çözüm üretinceye) kadar hiçbir işe kesin karar vermeyeceğim.” demişti."},{"n":33,"t":"(Yöneticiler) şöyle demişti: “Biz kuvvet sahibi ve şiddetli savaş bilen kişileriz. Emir senindir; artık ne emredeceğine sen karar ver!”"},{"n":34,"t":"(Belkıs) şöyle demişti, “Hükümdarlar bir şehre girdikleri zaman orayı perişan eder ve halkının itibarlılarını alçaltırlar. (Herhâlde) onlar da böyle yapacaklar(dır)."},{"n":35,"t":"Ben (şimdi) onlara bir hediye ile elçi göndereceğim; bakalım elçiler ne (gibi bir sonuç) ile dönecekler!”"},{"n":36,"t":"(Elçiler, hediye ile) Süleyman’a gelince o şöyle demişti: “Siz bana mal (hediye) ile yardım mı ediyorsunuz? Allah’ın bana verdiği size verdiğinden daha hayırlıdır. Hediyenizle (ben değil), aksine siz sevinirsiniz.”"},{"n":37,"t":"(Ey elçi)! Kavmine dön (onlara de ki): “Kendilerine asla karşı koyamayacakları orduyla geleceğiz; onları aşağılanmış bir şekilde hor ve değersiz olarak oradan çıkaracağız.”"},{"n":38,"t":"(Süleyman devamla) şöyle demişti: “Ey yöneticiler! Onlar teslimiyet gösterip bana gelmesinden önce hanginiz o (Belkıs)’ın tahtını bana getirebilir?”"},{"n":39,"t":"Cinlerden bir ifrit “Oturduğun yerden kalkmadan önce onu sana getiririm. Ben bu konuda güçlüyüm, güvenilirim!” demişti."},{"n":40,"t":"Kendisinde Kitaptan bir bilgi olan kimse ise “Gözünü açıp kapamadan önce onu ben sana getiririm!” demişti. (Süleyman, Belkıs’ın) tahtını yanında yerleşmiş görünce şunu söylemişti: “Bu, şükür mü edeceğimi yoksa nankörlük mü yapacağımı denemek üzere Rabbimin (bana verdiği) iyiliklerindendir. Şükreden ancak kendisi için şükretmiş olur; kâfir olana gelince, Rabbim zengindir, cömerttir.”"},{"n":41,"t":"(Süleyman) şöyle demişti: “Onun (denenmesi) için tahtını değiştirin; bakalım doğruyu bulabilecek mi, yoksa doğruyu bulamayanlardan mı olacak?”"},{"n":42,"t":"(Belkıs oraya) gelince, kendisine “Senin tahtın da böyle mi?” denmiş, o da “Sanki o! Bu olaydan önce bize bilgi verilmiş ve biz müslümanlar olmuştuk.” demişti."},{"n":43,"t":"Onu (Belkıs’ı), Allah’ın peşi sıra taptığı şeyler (gerçeklerden) alıkoymuştu. Şüphesiz ki o da inkârcı bir toplumdandı."},{"n":44,"t":"(Belkıs’a) “Saraya gir!” denmişti. O, (zemini) görünce derin bir su var sanmış ve ayaklarını açmıştı (eteğinin ucunu sıvamıştı). (Süleyman) “Bu, billurdan yapılmış bir köşk (zemini)dir” deyince, (Belkıs) şunu söylemişti: “Rabbim! Şüphesiz ki ben (güneşe tapmakla) kendime yazık etmişim. Süleyman’la birlikte âlemlerin Rabbi olan Allah’a teslim oldum.”"},{"n":45,"t":"Yemin olsun ki “Allah’a kulluk edin!” (demesi için) Semûd’a kardeşleri Salih’i (peygamber olarak) göndermiştik ve birdenbire birbiriyle çekişen iki gruba ayrılmışlardı."},{"n":46,"t":"(Salih) şöyle demişti: “Ey kavmim! İyiliğin öncesinde niçin kötülüğ(ün gelmesin)e acele ediyorsunuz? Merhamete ulaştırılasınız diye Allah’tan bağışlanma dilesenize!”"},{"n":47,"t":"(Kavmi) şöyle demişti: “Senin ve beraberindekilerin yüzünden uğursuzluğa uğradık.” (Salih ise) “Size gelen uğursuzluk (yapıp ettikleriniz nedeniyle) Allah katında(n gelmiş)tir. Aslında siz deneniyorsunuz.” demişti."},{"n":48,"t":"O şehirde bozgunculuk yapan ve ıslah etmeyen dokuzlu çete vardı."},{"n":49,"t":"(Bu çete) Allah’a yeminleşerek birbirlerine şöyle demişlerdi: “Ona ve ailesine gece baskın yapıp (hepsini öldürelim); sonra da (Salih’in) dostu olan kişiye ‘Biz (Salih’in) ailesinin yok edilişini görmedik, gerçekten doğru söylüyoruz!’ diyelim.”"},{"n":50,"t":"Onlar tuzak kurmuşlardı. Onlar farkına varmadan biz de (buna karşı) tuzak kurmuştuk."},{"n":51,"t":"Bak tuzaklarının sonu nasıl oldu! Onları da toplumlarını da toptan helak etmiştik!"},{"n":52,"t":"İşte haksızlıkları yüzünden çökmüş, ıssız kalmış evleri! Gerçeği bilen bir toplum için şüphesiz ki bunda bir ders vardır."},{"n":53,"t":"İman edip takvâlı (duyarlı) davranmış olanları ise kurtarmıştık."},{"n":54,"t":"Lut’u da (peygamber olarak göndermiştik). Kavmine şöyle demişti: “Göz göre göre o çirkinliği (hâlâ) yapıyor musunuz?"},{"n":55,"t":"Siz, kadınları bırakıp da şehvetle erkeklere mi yanaşıyorsunuz? Doğrusu siz cahillikte devam eden bir topluluksunuz!”"},{"n":56,"t":"Kavminin cevabı ise “Lut’un ailesini şehrinizden çıkarın; şüphesiz ki onlar temiz kalmak isteyen insanlarmış!” sözünden başka bir şey olmamıştı."},{"n":57,"t":"Bunun üzerine onu (Lut’u) ve ailesini kurtarmıştık. Hanımı hariç; onun geride (azaba uğrayanların içinde) kalmasını uygun görmüştük."},{"n":58,"t":"Üzerlerine büyük bir bela yağmuru yağdırmıştık. Uyarılanların (ama yola gelmeyenlerin) bela yağmuru ne de kotu (olmuştu)!"},{"n":59,"t":"De ki: “Hamd (övgü) Allah’a, selam da seçkin kıldığı kullarına olsun!” Allah mı hayırlıdır; yoksa ortak koşma(ya çalıştıkları) mı?"},{"n":60,"t":"(Onlar mı hayırlı) yoksa gökleri ve yeri yaratan, gökten size su indiren (Allah) mı? Bir ağacını bile yetiştiremeyeceğiniz güzel bahçeleri o (su) sayesinde yetiştirdik. Allah’la birlikte bir ilah mı (varmış)! Doğrusu onlar, (putları Allah’a) denk tutan bir topluluktur."},{"n":61,"t":"(Onlar mı hayırlı) yoksa yeryüzünü oturmaya elverişli kılan, (vadiler) arasında nehirler yaratan, yeryüzü için ağırlıklar yaratan ve iki deniz arasına engel koyan (Allah) mı? Allah’la birlikte bir ilah mı (varmış)! Doğrusu onların pek çoğu, gerçeği bilm(ek iste)miyorlar."},{"n":62,"t":"(Onlar mı hayırlı) yoksa kendine yalvardığında zorda kalana cevap veren, sıkıntıyı açan (gideren) ve sizi yeryüzünün halifeleri (sorumluları olarak) görevlendiren (Allah) mı? Allah’la birlikte bir ilah mı (varmış)! Ne kadar da azınız (gerçeği) hatırlıyor!"},{"n":63,"t":"(Onlar mı hayırlı) yoksa karanın ve denizin karanlıkları içinde size yol gösteren, rahmetinin (yağmurun) önünde rüzgârları müjdeci olarak gönderen (Allah) mı? Allah’la birlikte bir ilah mı (varmış)! Allah onların ortak koştuklarından yücedir."},{"n":64,"t":"(Onlar mı hayırlı) yoksa yaratmaya başlayan, sonra onu iade (tekrar) eden, gökten ve yerden sizi rızıklandıran (Allah) mı? Allah’la birlikte bir ilah mı (varmış)! De ki: “Doğruysanız kesin delilinizi getirin!”"},{"n":65,"t":"De ki: “Göklerde ve yerde Allah’tan başka kimse gaybı (bilinemeyeni) bilemez.” Onlar ne zaman diriltileceklerini de bilemezler."},{"n":66,"t":"Aksine ahiret hakkındaki bilgiler art arda kendilerine gelmesine rağmen, ondan şüphelenmeye devam etmektedir; ahiretten yana da kördürler."},{"n":67,"t":"Kâfir olanlar şöyle demişlerdi: “Biz ve atalarımız toprak olduğumuz zaman, gerçekten (diriltilip topraktan) mı çıkartılacağız!"},{"n":68,"t":"Şüphesiz ki bu, daha önce bize de atalarımıza da vadedilmişti. Bu, öncekilerin masallarından başka bir şey değildir.”"},{"n":69,"t":"(Onlara) de ki: “Yeryüzünde dolaşın da suçluların sonu nasıl olmuş, bakın!”"},{"n":70,"t":"Onlardan dolayı üzülme; kurmakta oldukları tuzaklar yüzünden sıkıntı içinde olma!"},{"n":71,"t":"“Doğruysanız o vaat (Son Saat) ne zamanmış!” derler."},{"n":72,"t":"De ki: “Acele gelmesini istediğiniz (azab)ın bir kısmı başınıza gelmek üzeredir.”"},{"n":73,"t":"Şüphesiz ki Rabbin insanlara karşı lütuf sahibidir. Fakat onların çoğu şükretmezler."},{"n":74,"t":"Şüphesiz ki Rabbin kalplerinin gizlediğini de açıkladıklarını da bilir."},{"n":75,"t":"Gökte ve yerde gaib (yaratılmışların bilemeyeceği) ne varsa hepsi ancak ve ancak apaçık bir kitaptadır."},{"n":76,"t":"Şüphesiz ki bu Kur’an İsrailoğullarına, tartıştıkları şeylerin pek çoğunu anlatmaktadır."},{"n":77,"t":"Şüphesiz ki o (Kur’an), müminler için bir rehber ve rahmettir."},{"n":78,"t":"Şüphesiz ki Rabbin onların arasında hükmünü verecektir. O güçlüdür, bilendir."},{"n":79,"t":"Allah’a güven! Şüphesiz ki sen apaçık hakikat üzeresin."},{"n":80,"t":"Şüphesiz ki sen ölülere duyuramaz; sağırlara da arkalarını dönüp giderlerken çağrıyı duyuramazsın."},{"n":81,"t":"Sen körleri şaşkınlıklarından (çevirip) doğru yola iletemezsin. Ayetlerimize inanıp teslim olanlardan başkasına duyuramazsın."},{"n":82,"t":"Onlar hakkında o (azap) sözü gerçekleştiği zaman, onlar için yerden bir canlı çıkarmış olacağız ve bu (inkârcı) insanların ayetlerimize kesin bir şekilde inanmamış olduklarını kendilerine söyleyecektir."},{"n":83,"t":"O gün, her ümmet içinden ayetlerimizi yalanlayanlardan (çeşitli) grup(ları) toplayacağız; onlar, (hesap yerine) sevk edilecektir."},{"n":84,"t":"Sonunda, (hesap yerine) geldikleri zaman (Allah) kendilerine şöyle soracaktır: “Bilip kavramadan ayetlerimi yalanladınız, öyle mi? (Değilse, bu) yaptığınız neydi?”"},{"n":85,"t":"Yaptıkları haksızlıktan dolayı haklarında (azap) sözü gerçekleşmiştir; artık onlar konuşamazlar."},{"n":86,"t":"Dinlensinler diye geceyi (karanlık) ve (çalışsınlar diye) gündüzü aydınlık kıldığımızı hiç mi düşünmediler? İman eden bir topluluk için şüphesiz ki bunda dersler vardır."},{"n":87,"t":"Sûr’a üfleneceği gün, –Allah’ın diledikleri hariç– göklerde ve yerde bulunanlar şiddetli bir şekilde korkacaktır. Hepsi boynu bükük olarak O’na gelecekler."},{"n":88,"t":"Görüp sabit sandığın dağlar, her şeyi en güçlü biçimde şekillendiren Allah’ın bir sanatı olarak, bulutların gidişi (gibi) gidiyor (olacaktır). Şüphesiz ki Allah yapmakta olduklarınızdan haberdardır."},{"n":89,"t":"Kim bir iyilikle gelirse onun için çok daha hayırlısı olacaktır. Onlar o gün korkudan güvende olacaklardır."},{"n":90,"t":"Kötülükle gelen kişiler ise yüzüstü cehenneme atılacaklardır ve (kendilerine) “Sadece yaptıklarınızın karşılığını görmektesiniz.” (denecektir)."},{"n":91,"t":"(De ki:) “Ben her şey sadece kendisine ait olan ve saygın kıldığı bu şehrin (Mekke’nin) Rabbine kulluk etmekle emrolundum. Ben müslümanlardan olmakla emrolundum."},{"n":92,"t":"Kur’an’ı tilavetle (okuyup aktarmakla) da (emrolundum). Kim doğru yola gelirse yalnızca kendisi için gelmiş olur; kim de saparsa ona de ki: “Ben sadece uyarıcılardanım.”"},{"n":93,"t":"De ki: “Hamd (övgü) Allah içindir. O, ayetlerini size gösterecektir; siz de onları (görüp) tanıyacaksınız. Rabbin yaptıklarınızdan habersiz değildir.”"}],[{"n":1,"t":"Tâ. Sîn. Mîm."},{"n":2,"t":"İşte şu(nlar), apaçık Kitabın ayetleridir."},{"n":3,"t":"İman edecek bir toplum için Musa ile Firavun’un haberinden bir kısmını sana bir amaç ile tilavet etmekteyiz (okuyup aktarmaktayız)."},{"n":4,"t":"Şüphesiz ki Firavun, o yerde (Mısır’da) zorbalaşmış, erkek çocuklarını kestirip kadınlarını sağ bırakarak (ve) her birini (her grubu) zayıf düşürerek halkını çeşitli gruplara ayırmıştı. Şüphesiz ki o (Firavun) bozgunculardandı."},{"n":5,"t":"Biz ise o yerde, zayıf düşürülenlere lütufta bulunmak, onları önderler yapmak ve onları (o topraklara) mirasçı kılmak istiyorduk."},{"n":6,"t":"Ayrıca onları o yerde hâkim kılmak; Firavun, Haman ve ordularına korktukları şeyi göstermek de (istiyorduk)."},{"n":7,"t":"Musa’nın annesine, “Onu emzir; onun hakkında korktuğunda onu denize (nehre) bırak; (başına bir şey gelmesinden) korkma ve hüzünlenme! Şüphesiz ki biz onu sana geri döndürecek ve kendisini elçilerden biri yapacağız!” diye vahyetmiştik (bildirmiştik)."},{"n":8,"t":"Firavun ailesi (sonunda) kendilerine bir düşman ve bir üzüntü kaynağı (olacağını bilmeden) onu (Musa’yı) bulup almışlardı. Şüphesiz ki Firavun, Haman ve askerleri suçlu insanlardı."},{"n":9,"t":"Firavun’un hanımı (Asiye, Musa’yı görünce) “(Bu bebek) benim için de senin için de göz aydınlığı (olabilir); onu öldürmeyin! Belki bize yararı dokunur veya onu evlat ediniriz.” demişti. Oysa onlar (işin sonunun) farkına varmamışlar(dı)."},{"n":10,"t":"Musa’nın annesinin kalbi korku dolmuştu. İnanıp güvenenlerden olması için kalbine dayanıklılık vermemiş olsaydık neredeyse işi açığa vuracaktı."},{"n":11,"t":"(Annesi, Musa’nın) ablasına “Onun izini takip et!” demişti. O da (Firavun’un adamları) farkına varmadan uzaktan onu (Musa’yı) gözetlemişti."},{"n":12,"t":"Biz daha önce ona (Musa’ya) hiçbir kadının (sütannenin) sütünü emmesine izin vermemiştik (onları emmesini engellemiştik). Bunun üzerine (ablası, Firavun ailesine) “Size, onun bakımını sizin adınıza üstlenecek ve kendisine samimi davranacak bir aile göstereyim mi?” demişti."},{"n":13,"t":"Böylelikle gözü aydın olsun, (daha fazla) üzülmesin ve insanların çoğu bilmeseler bile Allah’ın vaadinin gerçek olduğunu bilsin diye biz onu annesine geri vermiştik."},{"n":14,"t":"(Musa) yetişkinlik çağına ulaşıp olgunlaşınca ona doğru hüküm verme yeteneği ve ilim vermiştik. Güzel davrananları biz işte böyle ödüllendiririz."},{"n":15,"t":"(Musa), halkının habersiz olduğu bir sırada şehre girmiş ve orada biri kendi tarafından diğeri düşmanı tarafından olan iki adamı dövüşür bulmuştu. Kendi tarafından olanın, düşmanına karşı ondan yardım istemesi üzerine, (Musa, o) kişiyi itekleyip işini bitirmişti (ölümüne sebep olmuştu). (Sonunda) “Bu, şeytan işidir. Şüphesiz ki o, apaçık saptırıcı bir düşmandır.” demişti."},{"n":16,"t":"(Musa) “Rabbim! Doğrusu kendime haksızlık ettim; beni bağışla!” demiş, (Allah) da onu bağışlamıştı. Şüphesiz ki O çok bağışlayandır, çok merhametlidir."},{"n":17,"t":"(Musa) “Rabbim! Bana verdiğin nimetlere karşılık suçlulara asla arka çıkmayacağım!” demişti."},{"n":18,"t":"Şehirde korku içinde, (etrafı) gözetleyerek sabahladıktan sonra bir de ne görsün, dün kendisinden yardım isteyen kişi, feryat ederek tekrar ondan yardım istiyor. (Musa) ona, “Doğrusu sen apaçık bir azgınsın!” demişti."},{"n":19,"t":"(Musa), her ikisinin de düşmanı olan (adam)ı yakalamak isteyince, (adam) ona şöyle demişti: “Ey Musa! Dün bir canı öldürdüğün gibi, şimdi de beni mi öldürmek istiyorsun? Sen yeryüzünde sadece zorbalık istiyorsun; ıslah edicilerden olmak istemiyorsun.”"},{"n":20,"t":"Şehrin ileri gelenlerinden bir adam koşarak gelmiş ve “Ey Musa! Şüphesiz ki yöneticiler (toplantı hâlinde) seni öldürmek için hakkında karar veriyorlar. Hemen (buradan) çık! Şüphesiz ki ben senin için samimi davrananlardanım!” demişti."},{"n":21,"t":"(Musa) korku içinde, (etrafı) gözetleyerek şehirden çıkmış (ve) “Rabbim! Beni zalimler topluluğundan koru!” diye dua etmişti."},{"n":22,"t":"(Musa) Medyen’e doğru yöneldiğinde “Umarım ki Rabbim beni doğru yola ulaştırır.” demişti."},{"n":23,"t":"Medyen suyuna varınca, orada (hayvanlarını) sulayan bir grup insanla karşılaşmıştı. Onların gerisinde de (hayvanlarını) engelleyen (geri tutan) iki hanım (kız) görmüştü. Onlara “Derdiniz nedir (neden sulamıyorsunuz)?” diye sorunca, şöyle demişlerdi: “Çobanlar sulayıp çekilene kadar biz sulamayız; babamız da büyük, yaşlıdır (mecburen biz suluyoruz).”"},{"n":24,"t":"Bunun üzerine (Musa) hemen onların yerine (davarlarını) sulamıştı. Daha sonra bir gölgeye çekilmiş ve “Rabbim! Doğrusu bana vereceğin her lütfa öyle muhtacım ki!” demişti."},{"n":25,"t":"Bu esnada, iki kızdan biri edeple yürüyerek o (Musa)’nın yanına gelmiş (ve) “Babam, bizim için (hayvanları) sulamanın karşılığını ödemek için seni çağırıyor!” demişti. (Musa, kızın babası Şuayb’a) gelip olayları (kendi başından geçenleri) anlatınca, (Şuayb) “Korkma, o zalim toplumdan artık kurtuldun!” demişti."},{"n":26,"t":"(Şuayb’ın iki kızından) biri “Ey babacığım! Onu ücretli (çalışan olarak) tut! Şüphesiz ki ücretle tuttuklarının en hayırlısı, işte bu güçlü ve güvenilir olan (kişidir)” demişti."},{"n":27,"t":"(Şuayb, Musa’ya) şöyle demişti: “Bana sekiz yıl çalışmana karşılık şu iki kızımdan birini sana nikâhlamak istiyorum. Süreyi on yıla tamamlarsan o sana kalmış bir şeydir; seni sıkıntıya düşürmek istemem. İnşallah beni dürüst olanlardan bulacaksın.”"},{"n":28,"t":"(Musa da) şöyle demişti: “Bu, benimle senin aranda (bir antlaşma)dır. İki süreden hangisini doldurursam bana düşmanlık (haksızlık) yapılmayacak (değil mi)? Allah söylediklerimize vekildir (şahittir).”"},{"n":29,"t":"Musa, o süreyi doldurup ailesiyle yola çıkınca, Tûr (Sînâ Dağı) tarafından bir ateş görmüştü. Ailesine “(Siz burada) bekleyin! Bir ateş gördüm. Umarım ki ondan size bir haber veya ısınmanız için ateşten bir kor getiririm.” demişti."},{"n":30,"t":"Oraya varınca, o bereketli yerde, sağ taraftaki vadinin kıyısından, (yanan) ağaç yönünden kendisine şöyle seslenilmişti: “Ey Musa! Âlemlerin Rabbi olan Allah benim ben!"},{"n":31,"t":"Asanı (yere) bırak!” (Musa) onu yılan gibi depreşir görünce, arkasına bakmadan geri dönmüştü (ve ona şöyle seslenilmişti:) “Ey Musa! Geri dön, korkma! Artık sen güvende olanlardansın!"},{"n":32,"t":"Elini koynuna sok ki kusursuz bembeyaz çıksın. Korkudan dolayı (açılan) kollarını da kendine çek! İşte bu iki (olay) Firavun ve yöneticilerine karşı Rabbin tarafından (sana verilen) iki kesin delildir. Şüphesiz ki onlar yoldan çıkan bir toplum olmuşlardır.”"},{"n":33,"t":"(Musa) “Rabbim! Ben (yanlışlıkla) onlardan birini öldürmüştüm, (bu yüzden) beni öldürmelerinden korkuyorum!”"},{"n":34,"t":"Kardeşim Harun’un dili benimkinden daha düzgündür. Onu da beni doğrulayan bir yardımcı olarak benimle birlikte gönder! Beni yalanlamalarından korkuyorum.” demişti."},{"n":35,"t":"(Allah) şöyle demişti: “Seni kardeşinle destekleyeceğiz ve size öyle bir güç vereceğiz ki delillerimiz sayesinde onlar size ulaşamayacaklar. Siz ikiniz ve size uyanlar üstün geleceksiniz.”"},{"n":36,"t":"(Musa), onlara apaçık delillerimizi getirdiğinde “Bu, sadece uydurulmuş bir büyüdür; önceki atalarımızdan böyle bir şey de duymadık!” demişlerdi."},{"n":37,"t":"Musa ise şöyle demişti: “Rabbim, kendi katından kimin hidayet getirdiğini ve yurdun (bu dünyanın) sonunun kimin olacağını çok iyi bilendir.” Şüphesiz ki zalimler kurtulamazlar."},{"n":38,"t":"Firavun: “Ey yöneticiler! Sizin için benden başka ilah tanımıyorum. Ey Haman! Benim için çamur üzerine bir ateş yak (tuğla imal et); bana bir kule yap ki Musa’nın ilahına ulaşayım; onu(n Musa’nın) yalan söyleyenlerden (olduğunu) sanıyorum.” demişti."},{"n":39,"t":"O (Firavun) ve askerleri, yeryüzünde haksız olarak kibirlenmiş ve bize döndürülmeyeceklerine inanmışlardı."},{"n":40,"t":"Biz de onu ve askerlerini yakalayıp denizde boğmuştuk. Bak zalimlerin sonu nasıl oldu!"},{"n":41,"t":"(Böylece) onları, (insanları) ateşe çağıran öncüler kılmıştık. Kıyamet günü de kendilerine yardım edilmeyecektir."},{"n":42,"t":"Bu dünyada arkalarına lanet takmıştık (lanetle anılmalarını sağlamıştık). Kıyamet gününde de kötülenmişler arasında olacaklardır."},{"n":43,"t":"Yemin olsun ki biz ilk nesilleri helak ettikten sonra (gerçeği) hatırlasınlar diye insanlar için öngörüler (içeren), (ayrıca) bir rehber ve rahmet olarak o Kitabı Musa’ya vermiştik."},{"n":44,"t":"Musa’ya emrimizi verdiğimiz sırada sen, batı tarafında bulunmuyordun ve (o olayı) görenlerden de değildin."},{"n":45,"t":"(Oysa) biz nice nesiller var etmiştik de onların üzerinden uzun zaman geçmişti. Sen ayetlerimizi kendilerine tilavet etmek (okuyup aktarmak) üzere Medyen halkı arasında oturmuş da değildin. Ancak bütün elçileri gönderen bizdik."},{"n":46,"t":"Musa’ya seslendiğimiz zaman da sen Tûr’un (Sînâ Dağı’nın) yanında değildin. Düşünüp (gerçeği) hatırlarlar diye senden önce kendilerine uyarıcı gelmemiş bir kavmi uyarman için Rabbinden bir rahmet olarak (bunları sana bildirdik)."},{"n":47,"t":"Kendi ellerinin yapıp ettikleri nedeniyle başlarına bir musibet geldiğinde “Rabbimiz! Bize bir elçi gönderseydin de ayetlerine uyup müminlerden olsaydık!” diyecek olmasalardı (seni göndermezdik)."},{"n":48,"t":"Kendilerine tarafımızdan hakikat gelince “Musa’ya verilen (mucizeler) gibi ona da verilmeli değil miydi?” demişlerdi. Daha önce Musa’ya verileni de inkâr etmemişler miydi? “Birbirine arka çıkan iki büyü(cü)” demişlerdi. (Sözlerine devamla) “Doğrusu biz hepsini inkar edenleriz.” demişlerdi."},{"n":49,"t":"De ki: “Doğruysanız Allah katından bu ikisinden (Musa’ya ve bana indirilenden) daha doğru bir kitap getirin, ben de ona uyayım!”"},{"n":50,"t":"Sana cevap veremezlerse bil ki onlar arzularına uymaktadır. Allah tarafından bir yol gösterici olmaksızın kendi arzusuna uyandan daha sapkın kim olabilir ki! Şüphesiz ki Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":51,"t":"Yemin olsun ki (gerçeği) hatırlasınlar diye o sözü (Kur’an’ı) onlara ulaştırmıştık."},{"n":52,"t":"Ondan (Kur’an’dan) önce kendilerine kitap verdiklerimiz, ona (Kur’an’a) inanırlar."},{"n":53,"t":"Kendilerine (Kur’an) tilavet edildiği (okunup aktarıldığı) zaman “Ona iman ettik. Şüphesiz ki o, Rabbimizden gelen gerçektir. Esasen biz daha önce de müslümanlardık.” derler."},{"n":54,"t":"İşte bunlara (inanan kitap ehline), sabretmeleri nedeniyle ödülleri iki kez verilecektir. Bunlar kötülüğü iyilikle savar ve kendilerine verdiğimiz rızıktan da infak ederler."},{"n":55,"t":"Onlar, boş söz duydukları zaman ondan yüz çevirip “Bizim işlerimiz bize, sizin işleriniz size. Size selam olsun! Biz, cahillere itibar etmeyiz!” der (geçer)ler."},{"n":56,"t":"Sen sevdiğini doğru yola ulaştıramazsın ancak Allah dileyeni (layık gördüğünü) doğru yola ulaştırır. O, doğru yola ulaştırılmış olanları iyi bilendir."},{"n":57,"t":"(İnkârcılar) “Biz seninle birlikte o doğru yola uyarsak, yerimizden (yurdumuzdan) atılırız!” demişlerdi. Onları, kendi katımızdan bir rızık olarak her şeyin ürünlerinin toplanıp getirildiği güvenli, dokunulmaz bir yere (Mekke’ye) yerleştiren de biz değil miydik! Fakat onların çoğu (bu gerçeği) bilmezler."},{"n":58,"t":"Biz refahından şımarmış nice şehri helak etmişizdir. İşte kendilerinden sonra içinde az oturulabilen evleri! Onlara biz mirasçı olmuşuzdur."},{"n":59,"t":"Rabbin, kendilerine ayetlerimizi tilavet eden (okuyup aktaran) bir elçiyi şehirlerin merkezine gönderinceye kadar o şehirleri helak ediciler değildik. (Zaten) biz halkı zalim olan şehirlerden başkasını da helak ediciler değildik."},{"n":60,"t":"Size verilen şeyler, dünya hayatının geçimlikleri ve süsüdür. Allah katında olanlar ise hayırlı ve kalıcı olandır. Akıl etmiyor musunuz?"},{"n":61,"t":"Güzel bir vaatte bulunduğumuz, kendisi de o (vaate) kavuşan kimse, (sadece) dünya hayatının geçimlikleriyle yaşattığımız, sonra da kıyamet gününde (azap için) hazır kılınanlardan olan kimse gibi midir?"},{"n":62,"t":"O gün (Allah) onlara seslenerek “Benim ortaklarım olduklarını iddia ettikleriniz hani nerede!” diyecektir."},{"n":63,"t":"(O gün) hüküm aleyhlerine gerçekleşmiş olanlar şöyle diyeceklerdir: “Rabbimiz! Şunlar, azdırdığımız kişilerdir. Biz nasıl azmışsak onları da öyle azdırdık. (Kendilerinden) uzak olduğumuzu sana (arz ederiz). Zaten onlar, bize de tapmıyorlardı.”"},{"n":64,"t":"(İnkârcılara) “Ortaklarınızı çağırın!” denecektir. Onlar da çağıracaklar fakat kendilerine cevap veremeyecekler ve (karşılarında) azabı göreceklerdir. Keşke (dünyadayken) doğru yola girselerdi!"},{"n":65,"t":"O gün (Allah) onlara seslenerek “Elçilere ne cevap verdiniz?” diyecektir."},{"n":66,"t":"O gün o (inkârcı)lara bütün haberler (bahaneler) kapanacak, birbirlerine (hiçbir şey) soramayacaklardır."},{"n":67,"t":"(Fakat) tevbe eden, iman edip iyi iş(ler) yapanlara gelince, bunlar da kurtulanlardan olacaktır."},{"n":68,"t":"Rabbin, (peygamber olarak) dilediğini yaratır ve seçer. Onların (bu konuda) seçim hakkı yoktur. Allah onların (inkârcıların) ortak koştuklarından yüce ve uzaktır."},{"n":69,"t":"Rabbin, onların kalplerinin gizlediğini de açığa vurduklarını da bilir."},{"n":70,"t":"İşte O, Allah’tır. Kendisinden başka ilah yoktur. Önünde de (dünyada da) sonunda da (ahirette de) hamd (övgü) yalnızca O’na aittir. Hüküm, yalnızca O’na aittir ve yalnızca O’na döndürüleceksiniz."},{"n":71,"t":"De ki: “Bir düşünsenize, Allah geceyi kıyamet gününe kadar üzerinize aralıksız devam ettirse, Allah’tan başka size herhangi bir ışık getirebilecek ilah kimmiş! (Hâlâ gerçeği) duymuyor musunuz?”"},{"n":72,"t":"De ki: “Bir düşünsenize, Allah gündüzü kıyamet gününe kadar üzerinize aralıksız devam ettirse, Allah’tan başka dinleneceğiniz herhangi bir geceyi size getirecek ilah kimmiş! (Hâlâ gerçeği) görmüyor musunuz?”"},{"n":73,"t":"(Birinde) dinlenesiniz, (diğerinde de) O’nun cömertliğinden (rızkınızı) arayasınız ve şükredesiniz diye (Allah) rahmetinin gereği sizin için geceyi ve gündüzü yaratmıştır."},{"n":74,"t":"O gün (Allah) onlara seslenerek “Benim ortaklarım olduklarını iddia ettikleriniz hani nerede?” diyecektir."},{"n":75,"t":"(O gün) her ümmetten bir şahit çıkarmış olacağız ve (inkârcılara) “Kesin delilinizi getirin!” diyeceğiz. (İşte o zaman) bilecekler ki gerçek, Allah’a aittir ve uydurmakta oldukları şeyler de kendilerinden kaybolmuşlardır."},{"n":76,"t":"Şüphesiz ki Karun, Musa’nın kavmindendi ve onlara azgınlık ediyordu. Biz ona, anahtarlarını (taşımak) güçlü bir topluluğa bile zor gelecek hazineler vermiştik. Hani kavmi ona (Karun’a) şöyle demişti: “Şımarma! Şüphesiz ki Allah şımarıkları sevmez."},{"n":77,"t":"Allah’ın sana verdiği şeyler sayesinde ahiret yurdunu iste; dünyadan payını unutma! Allah sana iyilik yaptığı gibi, sen de (insanlara) iyilik yap ve yeryüzünde bozgunculuğu arzulama! Şüphesiz ki Allah bozguncuları sevmez.”"},{"n":78,"t":"(Karun ise) “O (servet), bana ancak kendimdeki bilgi sayesinde verildi!” demişti. Bilmiyor muydu ki Allah kendinden önceki nesillerden, ondan daha güçlü ve (maddi) birikimi çok daha fazla olan kişileri elbette helak etmişti. Suçlulardan günahları(nın ne olduğu) sorulmaz."},{"n":79,"t":"(Karun), süslü bir şekilde kavminin karşısına çıkmıştı. Dünya hayatını arzulayanlar, “Ah, keşke Karun’a verilenin benzeri bize de verilseydi! Şüphesiz ki o, çok büyük bir payın (servetin) sahibidir!” demişlerdi."},{"n":80,"t":"Kendilerine ilim verilmiş olanlar ise şöyle demişlerdi: “Yazıklar olsun size! İman edip iyi iş(ler) yapan için Allah’ın (vereceği) ödül hayırlı olandır. Ona da ancak sabredenler kavuşturulabilir.”"},{"n":81,"t":"Sonunda biz onu da evini de yerin dibine geçirmiştik. Allah’a karşı kendisine yardım edecek grubu (kimsesi) de yoktu; kendini kurtarabileceklerden de değildi."},{"n":82,"t":"Daha dün onun (Karun’un) yerinde olmayı isteyenler şöyle diyorlardı: “Vay! Demek ki Allah rızkı kullarından dilediğine (layık olana) açarak (bol) da veriyor, kısarak (dar) da. Allah bize lütufta bulunmuş olmasaydı, bizi de (yerin dibine) geçirirdi. Vay! Demek ki kâfirler kurtulamazmış!”"},{"n":83,"t":"O ahiret yurduna gelince, biz onu yeryüzünde kibirlenmek ve bozgunculuk (yapmak) istemeyenler için hazırlıyoruz. (Mutlu) son, muttakîler (duyarlı olanlar) içindir."},{"n":84,"t":"Kim bir iyilikle gelirse ona ondan daha iyisi vardır. Kim de bir kötülükle gelirse, kötülükleri işleyenlere yaptıklarından başka karşılık verilmeyecektir."},{"n":85,"t":"Kur’an’ı sana farz kılan (Allah) elbette seni dönülecek yere (Mekke’ye) döndürecektir. De ki: “Rabbim, kimin hidayetle geldiğini, kimin de apaçık bir şaşkınlık içinde olduğunu çok iyi bilendir.”"},{"n":86,"t":"Bu Kitabın sana vahyolunacağını ummuyordun. (Bu) ancak Rabbinden sana bir rahmet olarak (verilmiş)tir. Kâfirlere sakın arka çıkma!"},{"n":87,"t":"Sana indirildikten sonra, artık onlar seni Allah’ın ayetlerinden sakın ha alıkoymasınlar! Rabbine davet et ve asla müşriklerden olma!"},{"n":88,"t":"Allah ile birlikte başka bir ilaha yalvarma! (Çünkü) O’ndan başka ilah yoktur. O’nun yüzü (zatı) hariç, (geri kalan) her şey yok olacaktır. Hüküm, yalnızca O’na aittir ve yalnızca O’na döndürüleceksiniz."}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":2,"t":"İnsanlar, imtihan edilmeden sadece “İman ettik!” demeleriyle bırakılacaklarını mı sandılar!"},{"n":3,"t":"Yemin olsun ki biz onlardan öncekileri de imtihan etmiştik. Elbette Allah doğruları bil(dir)ip (ortaya çıkaracak)tır; yalancıları da mutlaka bil(dir)ip (ortaya çıkaracaktır)."},{"n":4,"t":"Yoksa kötülükleri yapanlar, bizi geçebileceklerini (bizden kaçabileceklerini) mi sandılar? Ne kadar kötü hüküm veriyorlar!"},{"n":5,"t":"Kim Allah’a kavuşmayı umuyorsa, bilsin ki Allah’ın (belirlediği) zaman elbette gelecektir. O duyandır, bilendir."},{"n":6,"t":"Cihad eden (fedakârlık yapan) ancak kendisi için cihad etmiş (fedakârlık yapmış) olur. Şüphesiz ki Allah âlemlerden zengindir."},{"n":7,"t":"İman edip iyi işler yapanların kötülüklerini elbette örtecek ve onlara, yaptıklarının en güzeli ile karşılık vereceğiz."},{"n":8,"t":"Biz insana ana babasına güzel davranmasını emrettik. Onlar seni, hakkında bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa, onlara itaat etme! Dönüşünüz sadece banadır. Elbette yapmış olduklarınızı size bildireceğim."},{"n":9,"t":"İman edip iyi işler yapanları elbette iyilere katacağız."},{"n":10,"t":"İnsanlardan kimi vardır ki “Allah’a inandık.” der; Allah uğrunda eziyete uğratıldığı zaman, insanlar(ın) eziyeti(ni) Allah’ın azabı gibi görür. Rabbinden bir yardım gelecek olsa, mutlaka “Doğrusu biz de sizinleydik!” derler. Allah insanların göğüslerinde (kalplerinde) olanları iyi bilen değil midir!"},{"n":11,"t":"Allah iman edenleri elbette bil(dir)ip (ortaya çıkaracaktır); iki yüzlüleri de elbette bil(dir)ip (ortaya çıkaracaktır)."},{"n":12,"t":"Kâfir olanlar iman edenlere “Bizim yolumuza uyun, sizin günahlarınızı da biz yüklenelim!” derler. (Oysa) günahlarından hiçbir şeyi asla yüklenici değillerdir. Şüphesiz ki onlar yalancıdır."},{"n":13,"t":"Elbette kendi yüklerini (günahlarını, ayrıca) kendi yükleriyle (günahlarıyla) birlikte (sebep oldukları diğer) yükleri (günahları) da taşıyacaklardır; uydurdukları şeylerden kıyamet günü mutlaka sorguya çekileceklerdir."},{"n":14,"t":"Yemin olsun ki biz Nuh’u kendi halkına göndermiştik; bin seneden elli yıl eksik bir süre onların arasında kalmıştı. Onlar haksızlık ederken (sonunda) tufan kendilerini yakalamıştı."},{"n":15,"t":"Biz onu ve gemideki halkı kurtarmış ve onu âlemlere ibret yapmıştık."},{"n":16,"t":"İbrahim’i de (elçi olarak göndermiştik). Kavmine şöyle demişti: “Allah’a kulluk edin! O’na karşı takvâlı (duyarlı) olun! Bilirseniz bu, sizin için hayırlı olandır."},{"n":17,"t":"Siz Allah’ın peşi sıra birtakım putlara tapıyor, asılsız sözler uyduruyorsunuz. Şüphesiz ki Allah’ın peşi sıra taptıklarınız, size rızık veremezler. Rızkı Allah katında arayın! O’na kulluk edin ve O’na şükredin! Yalnızca O’na döndürüleceksiniz.”"},{"n":18,"t":"(Size tebliğ edileni) yalanlarsanız, elbette sizden önceki milletler de (gerçekleri) yalanlamıştı. Elçi'ye düşen (görev) yalnızca apaçık tebliğdir."},{"n":19,"t":"Allah’ın yaratmaya nasıl başladığını, sonra da bunu (nasıl) tekrarladığını hiç düşünmezler mi? Şüphesiz ki bu, Allah’a kolaydır."},{"n":20,"t":"De ki: “Yeryüzünde dolaşın ve (Allah) yaratmaya nasıl başlamış bir bakın!” Allah bundan sonra son yaratılışı (ahiret hayatını) da gerçekleştirecektir. Şüphesiz ki Allah her şeye gücü yetendir."},{"n":21,"t":"O, dileyene (layık gördüğüne) azap eder; dileyene (layık gördüğüne) ise merhamet eder. Yalnızca O’na döndürüleceksiniz."},{"n":22,"t":"Yerde ve gökte (O’nu) asla aciz bırakamazsınız. Sizin için Allah’a rağmen dost da yardımcı da yoktur."},{"n":23,"t":"Allah’ın ayetlerini ve O’na kavuşmayı inkâr edenler –işte onlar– benim merhametimden ümitlerini kesmişlerdir ve onlar için elem verici bir azap vardır."},{"n":24,"t":"(İbrahim’in) kavminin cevabı ise “Onu öldürün veya yakın!” demelerinden başka bir şey olmamıştı. (Ama) Allah onu ateşten kurtarmıştı. Şüphesiz ki bunda iman eden bir toplum için dersler vardır."},{"n":25,"t":"(İbrahim) şöyle demişti: “Siz sadece aranızdaki dünya hayatına özel bir sevgi uğruna Allah’ın peşi sıra birtakım putlar edindiniz. Sonra kıyamet günü birbirinizi tanımazlıktan gelecek ve bir kısmınız bir kısmına lanet edecektir. Barınağınız ateştir; sizin için asla yardımcılar da yoktur!”"},{"n":26,"t":"Lut (da) ona iman etmişti ve (İbrahim) “Doğrusu ben Rabbime (emrettiği yere) hicret ediyorum. Şüphesiz ki yalnızca O güçlüdür, doğru hüküm verendir.” demişti."},{"n":27,"t":"Biz ona (İbrahim’e), İshak ve (İshak’ın oğlu) Yakup’u lütfetmiş, peygamberliği ve Kitabı onun soyundan gelenlere vermiştik. Ona (böylece) dünyada ödülünü vermiştik. Şüphesiz ki o, ahirette de iyilerden (olacak)tır."},{"n":28,"t":"Lut’u da (elçi olarak göndermiştik). Kavmine şöyle demişti: “Şüphesiz ki siz, sizden önce âlemlerden (insanlardan) kimsenin yapmadığı bir çirkinliği yapıyorsunuz."},{"n":29,"t":"Siz erkeklere yaklaşacak, yol kesecek ve toplantılarınızda o çirkinliği mi yapacaksınız!” Kavminin cevabı ise “Doğru söyleyenlerdensen bize Allah’ın azabını getir!” demelerinden başka bir şey olmamıştı."},{"n":30,"t":"(Lut:) “Rabbim! Şu bozguncu topluma karşı bana yardım et!” demişti."},{"n":31,"t":"Elçilerimiz (melekler) İbrahim’e (çocuk) müjdesi getirdiklerinde şöyle demişlerdi: “Biz bu şehir halkını helak edeceğiz. Şüphesiz ki oranın halkı zalim kişilerdir.”"},{"n":32,"t":"(İbrahim) şöyle demişti: “Ama orada Lut var!” (Melekler ise): “Biz orada kimin bulunduğunu çok iyi bilenleriz. Onu ve ailesini elbette kurtaracağız. Sadece hanımı hariç; o, (azapta) kalacaklar arasındadır.” demişlerdi."},{"n":33,"t":"Elçilerimiz Lut’a gelince, (Lut) onların yüzünden üzülmüş ve onlardan dolayı içi daralmıştı. Ona “Korkma, tasalanma! Şüphesiz ki biz seni de aileni de kurtaracağız. Yalnız, (azapta) kalacaklar arasında bulunan hanımın hariç!” demişlerdi."},{"n":34,"t":"Şüphesiz ki biz yoldan çıkmalarına karşılık bu şehir halkının üzerine, gökten bir azap indireceğiz."},{"n":35,"t":"Yemin olsun ki biz aklını kullanacak bir toplum için oradan apaçık bir delil bırakmışızdır."},{"n":36,"t":"Medyen’e de kardeşleri Şuayb’ı (elçi göndermiştik). Şöyle demişti: “Ey kavmim, Allah’a kulluk edin! Ahiret gününe ümit bağlayın ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın!”"},{"n":37,"t":"(Kavmi) onu yalanlamıştı. Kendilerini (korkunç) bir sarsıntı yakalamıştı ve yurtlarında diz üstü çökmüşlerdi."},{"n":38,"t":"Âd ve Semûd’u da (helak etmiştik). Sizin için, (onların durumu) oturdukları yerler(in kalıntıların)dan anlaşılmaktadır. Şeytan, yaptıkları işleri kendilerine süslü göstermiş ve onları doğru yoldan alıkoymuştur. (Oysa) bakıp görebilecek durumdaydılar."},{"n":39,"t":"Karun’u, Firavun’u ve Haman’ı da (helak etmiştik). Yemin olsun ki Musa onlara apaçık deliller getirmişti de onlar yeryüzünde kibirlenmişlerdi. (Azabımızı) geçebilecek değillerdi."},{"n":40,"t":"Nitekim onlardan her birini günahı sebebiyle cezalandırmıştık. Kiminin üzerine taş göndermiştik. Kimini korkunç bir ses yakalamıştı. Kimini yerin dibine geçirmiştik. Kimini de suda boğmuştuk. Allah onlara haksızlık edecek değildi fakat onlar kendi kendilerine haksızlık etmekteydiler."},{"n":41,"t":"Allah’ın peşi sıra dostlar edinenlerin örneği, yuva edinen örümceğin örneği gibidir. Şüphesiz ki yuvaların en dayanıksız olanı elbette örümcek yuvasıdır. Keşke bilselerdi!"},{"n":42,"t":"Allah onların kendisinin peşi sıra yalvardıkları şeyleri bilmektedir. O güçlüdür, doğru hüküm verendir."},{"n":43,"t":"İşte biz şu örnekleri insanlar için veriyoruz; onları (gerçeği) bilenlerden başkası akıl etmez."},{"n":44,"t":"Allah gökleri ve yeri bir amaç ile yaratmıştır. Şüphesiz ki bunda iman edenler için bir delil vardır."},{"n":45,"t":"Sana vahyedilen Kitabı tilavet et (okuyup aktar) ve namazı kıl! Şüphesiz ki namaz, çirkinlikten ve kötülükten alıkoyar. Allah’ı anmak elbette (ibadetlerin) en büyüğüdür. Allah yaptıklarınızı bilir."},{"n":46,"t":"İçlerinden haksızlık edenler hariç, kitap ehliyle ancak en güzel şekilde mücadele edin ve deyin ki: “Bize indirilene de size indirilene de iman ettik. Bizim ilahımız da sizin ilahınız da tektir ve biz O’na teslim olmuşuzdur.”"},{"n":47,"t":"İşte böylece sana Kitabı (Kur’an’ı) indirdik. Kendilerine kitap verdiklerimiz ona iman ediyorlar. Şunlardan (Araplardan) da ona iman edenler vardır. Ayetlerimizi kâfirlerden başkası inkâr etmez."},{"n":48,"t":"Sen bundan önce ne (kutsal) bir kitap okur ne de onu sağ elinle yazardın. Öyle olsaydı (gerçeği) iptal edenler elbette kuşku duyarlardı."},{"n":49,"t":"Hayır! O (Kur’an), kendilerine ilim verilenlerin göğüslerinde (kalplerinde) apaçık ayetlerdir. Ayetlerimizi zalimlerden başkası inkâr etmez."},{"n":50,"t":"(O zalimler:) “Ona Rabbinden (başka) ayetler (mucizeler) indirilmeli değil miydi?” demişlerdi. De ki: “Ayetler (mucizeler) ancak Allah katında(n)dır. Ben ise sadece apaçık bir uyarıcıyım.”"},{"n":51,"t":"Kendilerine tilavet edilmekte (okunup aktarılmakta) olan Kitabı (Kur’an’ı) sana indirmemiz onlara yetmedi mi? Elbette iman eden bir toplum için onda rahmet ve (gerçeğin) hatırla(t)ması vardır."},{"n":52,"t":"De ki: “Benimle sizin aranızda şahit olarak Allah yeter. Göklerde ve yerde ne varsa (hepsini) bilir.” Batıla inanıp Allah’ı inkâr edenler (var ya), işte onlar kaybedenlerin ta kendileridir."},{"n":53,"t":"Senden, azabı acele (getirmeni) istiyorlar. Önceden belirlenmiş bir vade olmasaydı, azap onlara elbette gelip çatmıştı. Onlar farkında değilken, (o azap) ansızın kendilerine gelecektir."},{"n":54,"t":"(Evet) senden azabı acele (getirmeni) istiyorlar. Şüphesiz ki cehennem kâfirleri çepeçevre kuşatıcıdır."},{"n":55,"t":"O gün azap, onları hem üstlerinden hem de ayaklarının altından kaplayacak ve (Allah onlara) “Yaptıklarınızın (cezasını) tadın!” diyecektir."},{"n":56,"t":"Ey iman eden kullarım! Şüphesiz ki benim arzım (yerim) geniştir. Yalnızca bana kulluk edin!"},{"n":57,"t":"Her nefis (can), ölümü tadıcıdır. Sonunda sadece bize döndürüleceksiniz."},{"n":58,"t":"İman edip iyi işler yapanları -evet onları- içlerinde ebedî kalmak üzere altlarından ırmaklar akan cennet köşklerine elbette yerleştireceğiz. (Böyle iyi) işler yapanların ödülü ne güzeldir!"},{"n":59,"t":"(Ödülü hak edenler) sadece Rablerine güvenerek sabredenlerdir."},{"n":60,"t":"Nice canlı var ki rızkını (yanında) taşımıyor. Onlara da size de rızık veren Allah’tır. O duyandır, bilendir."},{"n":61,"t":"Onlara “Gökleri ve yeri yaratan, güneşi ve ayı emri altında tutan kimdir?” diye sorsan, elbette “Allah.” derler. (Allah’a kulluktan) nasıl da döndürülüyorlar!"},{"n":62,"t":"Allah kullarından rızkı dilediğine açarak (bol) da verir, ona kısarak (dar) da verir. Şüphesiz ki Allah her şeyi bilendir."},{"n":63,"t":"Onlara “Gökten su indirip onunla ölümünün ardından yeri canlandıran kimdir?” diye sorsan, mutlaka “Allah” derler. De ki: “Hamd (övgü) Allah içindir; esasında onların çoğu akıl etmezler.”"},{"n":64,"t":"Bu dünya hayatı, oyun ve eğlenceden başka bir şey değildir. Şüphesiz ki ahiret yurdu(na gelince), işte asıl hayat odur. Keşke bilmiş olsalardı!"},{"n":65,"t":"65-66 Gemiye bindikleri zaman, dini yalnız O’na özgü kılarak Allah’a yalvarırlar. Fakat onları karaya kurtarınca (çıkarınca), bir de bakarsın ki kendilerine verdiklerimize karşılık nankörlük etmeleri için (Allah’a) ortak koşmaktadırlar. (Bir süre daha) yararlansınlar (bakalım)! İleride (gerçeği) bilecekler!"},{"n":66,"t":"65-66 Gemiye bindikleri zaman, dini yalnız O’na özgü kılarak Allah’a yalvarırlar. Fakat onları karaya kurtarınca (çıkarınca), bir de bakarsın ki kendilerine verdiklerimize karşılık nankörlük etmeleri için (Allah’a) ortak koşmaktadırlar. (Bir süre daha) yararlansınlar (bakalım)! İleride (gerçeği) bilecekler!"},{"n":67,"t":"Çevrelerinde insanlar kapılıp götürülürken, (Mekke’yi) güven içinde saygın bir yer yaptığımızı görmediler mi? Onlar Allah’ın nimet(ler)ine nankörlük edip batıla mı inanıyorlar!"},{"n":68,"t":"Allah’a yalan uyduran veya kendisine gelmişken gerçeği yalanlayandan daha zalim kim olabilir ki! Cehennemde kâfirlere yer mi yok!"},{"n":69,"t":"Bizim uğrumuzda cihad edenleri (fedakârlık yapanları) elbette kendi yollarımıza ulaştıracağız. Şüphesiz ki Allah güzel davrananlarla beraberdir."}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":"2-5","t":"Rumlar (Arapların bulunduğu bölgeye) en yakın yerde yenildi. (Oysa) onlar bu yenilgilerinden sonra birkaç sene içinde galip geleceklerdir. Önce de sonra da emir (yetki) yalnızca Allah’a aittir. O gün, müminler de Allah’ın yardımıyla sevineceklerdir. (Allah) dilediğine (layık olana) yardım eder. O güçlüdür, çok merhametlidir."},{"n":6,"t":"(Bu), Allah’ın vaadi olarak (gerçekleşecektir). Allah sözünden caymaz fakat insanların çoğu bilmezler."},{"n":7,"t":"Onlar dünya hayatının görünen yüzünü bilirler. Onlar ahiretten tamamen habersiz(miş gibi davranır)lar."},{"n":8,"t":"Allah’ın, gökleri, yeri ve ikisi arasında bulunanları ancak ve ancak bir amaç ile ve belirli bir süre için yarattığını kendi kendilerine hiç mi düşünmediler! Şüphesiz ki insanların çoğu, Rableriyle karşılaşmayı inkâr etmektedir."},{"n":9,"t":"Öncekilerin sonunun nasıl olduğunu görmek için yeryüzünde hiç mi dolaşmadılar? Onlar kendilerinden daha güçlüydüler; yeri kazıp altüst etmiş, onu (toprağı) bunların imar ettiklerinden daha çok imar etmişlerdi. Elçileri de onlara apaçık deliller getirmişti. Allah onlara haksızlık edecek değildi fakat onlar kendi kendilerine haksızlık etmekteydiler."},{"n":10,"t":"Sonunda Allah’ın ayetlerini yalanlayarak ve onlarla alay ederek kötülük yapanların sonları çok kötü oldu."},{"n":11,"t":"Allah yaratmaya başlar; sonra da onu (yaratmayı) iade eder (tekrarlar). Sonunda yalnızca O’na döndürüleceksiniz."},{"n":12,"t":"O (Son) Saat’in yaşanacağı gün, suçlular ümitsizlik içinde olacaklardır."},{"n":13,"t":"(Allah’a koştukları) ortaklarından kendilerine hiçbir şefaatçi çıkmayacaktır. Zaten onlar ortaklarını da inkâr edeceklerdir."},{"n":14,"t":"O (Son) Saat’in gerçekleşeceği gün, işte o gün (müminlerle inkârcılar) birbirlerinden ayrılacaklardır."},{"n":15,"t":"İman edip iyi işler yapanlara gelince, onlar cennette (nimetlerle) neşelendirileceklerdir."},{"n":16,"t":"Kâfir olanlar (yani) ayetlerimizi ve ahiret buluşmasını yalanlamış olanlar ise işte onlar azapta hazır bulundurulacaklardır."},{"n":17,"t":"Akşama ulaştığınızda ve sabaha kavuştuğunuzda Allah’ı tesbih (edin, namaz kılın)!"},{"n":18,"t":"Göklerde ve yerde hamd (övgü) yalnızca O’nadır. (Ayrıca) günün sonunda (yatsı vaktinde) ve öğleye ulaştığınızda da (Allah’ı tesbih edin, namaz kılın)!"},{"n":19,"t":"Ölüden diriyi çıkarıyor; diriden de ölüyü çıkarıyor; yeri ölümünün ardından canlandırıyor. İşte siz de (mezarlarınızdan) böyle çıkarılacaksınız."},{"n":20,"t":"Sizi topraktan yaratması, O’nun delillerindendir. Sonra siz yayılan insanlar oldunuz."},{"n":21,"t":"Kendileriyle kaynaşmanız için size kendi (cinsi)nizden eşler yaratması, aranızda sevgi ve merhamet var etmesi O’nun delillerindendir. Şüphesiz ki bunda düşünen bir toplum için dersler vardır."},{"n":22,"t":"Gökleri ve yeri yaratması, dillerinizin ve renklerinizin farklı olması O’nun delillerindendir. Şüphesiz ki bunda (gerçeği) bilenler için dersler vardır."},{"n":23,"t":"Gece olsun gündüz olsun, uyumanız ve (Allah’ın) lütfundan (payınızı) aramanız da O’nun delillerindendir. Şüphesiz ki bunda (gerçeği) dinleyen bir toplum için dersler vardır."},{"n":24,"t":"Size korku ve ümit olarak şimşeği göstermesi, gökten su indirip ölümünün ardından yeri (toprağı) onunla diriltmesi de O’nun delillerindendir. Şüphesiz ki bunda akıl eden bir toplum için dersler vardır."},{"n":25,"t":"Göğün ve yerin O’nun emri ile durması da O’nun delillerindendir. Sonra sizi yerden (dirilmeniz için) bir kez çağırdı mı bir de bakarsınız ki hemen (mezarlarınızdan) çıkıyorsunuz."},{"n":26,"t":"Göklerde ve yerde kim varsa hepsi yalnızca O’na (Allah’a) aittir. Hepsi yalnızca O’na boyun eğenlerdir."},{"n":27,"t":"Yaratmaya başlayan O’dur; sonra onu yeniden yaratır ki bu O’nun için çok kolaydır. Göklerde ve yerde en yüce sıfat yalnızca O’na aittir. O güçlüdür, doğru hüküm verendir."},{"n":28,"t":"(Allah) size kendinizden şöyle bir örnek vermektedir: Sahibi olduğunuz köleler içinde, size verdiğimiz rızıklarda –birbirinizden çekindiğiniz gibi kendilerinden çekineceğiniz için sizinle eşit (haklara sahip)– ortaklarınız var mı? Akıl eden bir toplum için ayetleri işte böyle açıklıyoruz."},{"n":29,"t":"Aslında haksızlık edenler, bilgisizce heveslerine uydular. Allah’ın saptırdığını (sapkınlığını onayladığını) kim doğru yola ulaştırabilir ki! Onların hiçbir yardımcısı da yoktur."},{"n":30,"t":"Sen hanîf (Allah’ı birleyen) olarak yüzünü dine yani Allah’ın insanları üzerinde yarattığı fıtrata çevir! Allah’ın yaratmasında değişme yoktur. İşte doğru din budur fakat insanların çoğu (bu gerçeği) bilmezler."},{"n":31,"t":"Hepiniz O’na yönelenenler olarak (fıtratınıza dönün)! O’na karşı takvâlı (duyarlı) olun, namazı kılın; müşriklerden olmayın!"},{"n":32,"t":"Dinlerini parça parça edip gruplara ayrılanlardan (olmayın! Bunlardan) her grup, kendi yanında bulunanla sevinmektedir."},{"n":33,"t":"33-34 İnsanların başına bir sıkıntı gelince Rablerine yönelerek O’na yalvarırlar. Sonra (Allah) katından onlara bir rahmet (bolluk) tattırınca bakarsınız ki kendilerine verdiklerimize karşılık nankörlük etmeleri için onlardan bir grup, Rablerine yine ortak koşuyorlar. Bir süre (daha) yararlanın! İleride bileceksiniz!"},{"n":34,"t":"33-34 İnsanların başına bir sıkıntı gelince Rablerine yönelerek O’na yalvarırlar. Sonra (Allah) katından onlara bir rahmet (bolluk) tattırınca bakarsınız ki kendilerine verdiklerimize karşılık nankörlük etmeleri için onlardan bir grup, Rablerine yine ortak koşuyorlar. Bir süre (daha) yararlanın! İleride bileceksiniz!"},{"n":35,"t":"Yoksa onlara kesin bir delil indirdik de o delil müşrik olmalarını mı söylüyor!"},{"n":36,"t":"İnsanlara bir rahmet (bolluk) tattırdığımızda ona sevinirler. Yaptıkları nedeniyle başlarına bir kötülük gelse bir de bakarsın ki ümitsizliğe düşerler."},{"n":37,"t":"Görmediler mi ki Allah, rızkı dilediğine (layık olana) açarak (bol) da verebilir, kısarak (dar) da. Şüphesiz ki bunda inanan bir toplum için dersler vardır."},{"n":38,"t":"Sen yakınlara, yoksula ve yolda kalmışa hakkını ver! Allah’ın rızasını isteyenler için bu, hayırlı olandır. İşte onlar kurtulanların ta kendileridir."},{"n":39,"t":"İnsanların mallarında artış olsun diye verdiğiniz herhangi bir faiz, Allah katında artmaz. Allah’ın rızasını isteyerek verdiğiniz zekâta gelince, işte zekât veren o kişiler -evet onlar- (sevaplarını) katlayanlardır."},{"n":40,"t":"Allah, sizi yaratandır; sonra sizi rızıklandırandır; sonra sizi öldürecek, sonra da sizi (tekrar) diriltecek olandır. (Allah’a koştuğunuz) ortaklarınız içinde bunlardan herhangi bir şeyi yapabilecek var mı? O, onların ortak koştuklarından yüce ve uzaktır."},{"n":41,"t":"İnsanların elleriyle kazandıkları (yaptıkları) yüzünden karada ve denizde bozulma meydana geldi. Böylece (yanlış yoldan) dönsünler diye (Allah onların) yaptıklarının bir kısmını onlara tattırır."},{"n":42,"t":"De ki: “Yeryüzünde dolaşın da daha öncekilerin sonları nasıl oldu, bakın!” Onların çoğu müşrikti."},{"n":43,"t":"Allah katından, dönüşü olmayan bir gün (kıyamet günü) gelmeden önce yüzünü o doğru dine çevir! O gün, (insanlar) bölük bölük ayrılacaklardır."},{"n":44,"t":"Kim inkâr ederse inkârı kendi aleyhine olur. İyi işler yapanlara gelince, onlar da kendileri için (cennetteki yerlerini) hazırlıyor olurlar."},{"n":45,"t":"(Allah) iman edip iyi işler yapanlara kendi lütfundan karşılık verecektir. Şüphesiz ki O, kâfirleri sevmez."},{"n":46,"t":"Size rahmetinden tattırsın, gemiler O’nun emriyle yüzsün, lütfundan (payınızı) arayasınız ve şükredesiniz diye müjdeciler olarak rüzgârları göndermesi de O’nun delillerindendir."},{"n":47,"t":"Yemin olsun ki biz senden önce onların toplumlarına elçiler göndermiştik de onlara apaçık belgeler (deliller) getirmişlerdi. (İnkar edip) günaha dalanlardan intikam almıştık. Müminlere yardım etmek de üzerimize haktır (borçtur)."},{"n":48,"t":"Allah rüzgârları gönderendir. Bu (rüzgâr)lar bulutu kaldırır. (Allah) onu gökte dilediği gibi yayar ve parçalara ayırır. (Bulutların) arasından yağmurun çıktığını görürsün. (Allah) kullarından dilediğine onu (yağmuru) isabet ettirince onlar hemen sevinirler."},{"n":49,"t":"Oysa onlar daha önce yani üzerlerine (yağmur) indirilmesinden önce iyice ümitlerini kesmişlerdi."},{"n":50,"t":"Allah’ın rahmetinin sonuçlarına bir bak: Toprağı ölümünün ardından nasıl diriltiyor! Şüphesiz ki O, ölüleri de mutlaka dirilticidir. O, her şeye gücü yetendir."},{"n":51,"t":"Şüphesiz ki bir rüzgâr göndersek de onu (ekinleri) sararmış görseler, ardından elbette nankörlüğe başlarlar."},{"n":52,"t":"Şüphesiz ki sen ölülere duyuramaz; sağırlara da arkalarını dönüp giderlerken çağrıyı duyuramazsın."},{"n":53,"t":"Sen körleri şaşkınlıklarından (çevirip) doğru yola iletemezsin. Ayetlerimize inanıp teslim olanlardan başkasına duyuramazsın."},{"n":54,"t":"Sizi güçsüz yaratan, sonra güçsüzlüğün ardından kuvvet veren ve sonra kuvvetin ardından güçsüzlük ve yaşlılık veren Allah’tır. O dilediğini yaratır. O bilendir, gücü yetendir."},{"n":55,"t":"O (Son) Saat gerçekleştiği gün, suçlular (dünyada) ancak kısa bir süre kaldıklarına dair yemin edecekler. İşte onlar (dünyada da gerçeklerden) böyle döndürülüyorlardı."},{"n":56,"t":"Kendilerine ilim ve iman verilenler (inkârcılara) şöyle diyeceklerdir: “Şüphesiz ki siz Allah’ın yazısında (hükmedildiği gibi) diriltilme gününe kadar kaldınız. İşte bugün, diriltilme günüdür fakat siz onu bilmiyordunuz (reddediyordunuz).”"},{"n":57,"t":"O gün, haksızlık edenlerin mazeretleri yarar sağlamayacak; onlardan (Allah’ı) memnun etmeye çalışmaları da istenmeyecektir."},{"n":58,"t":"Yemin olsun ki biz bu Kur’an’da insanlara her türlü örneği verdik. Onlara bir ayet (mucize) getirsen, kâfir olanlar elbette şöyle diyeceklerdir: “Siz ancak ve ancak (gerçekleri) iptal edenlersiniz.”"},{"n":59,"t":"İşte (gerçeği) bilme(k isteme)yenlerin kalplerini Allah böyle mühürler."},{"n":60,"t":"Sabret! Şüphesiz ki Allah’ın vaadi gerçektir. (Buna) kesin bir şekilde inanmayanlar sakın seni gevşekliğe sevk etmesin!"}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":2,"t":"İşte şu(nlar), doğru hükümler içeren Kitabın ayetleridir."},{"n":3,"t":"(O kitap) güzel davrananlar için bir rehber ve rahmettir."},{"n":4,"t":"Onlar namazı kılar, zekâtı verir ve ahirete de kesin bir şekilde inanırlar."},{"n":5,"t":"İşte onlar Rableri tarafından doğru yol üzerindedir ve onlar kurtulanların ta kendileridir."},{"n":6,"t":"İnsanlardan öylesi var ki bilgisizce Allah yolundan saptırmak ve sonra da o (yol)la alay etmek için boş söz satın alır. İşte onlara küçük düşürücü bir azap vardır."},{"n":7,"t":"Ona ayetlerimiz tilavet edildiği (okunup aktarıldığı) zaman, sanki bunları duymamış, sanki kulaklarında (s) ağırlık varmış gibi kibirlenerek yüz çevirir. Onu, elem verici bir azapla müjdele!"},{"n":8,"t":"Şüphesiz ki iman edip iyi işler yapanlar için nimetleri bol cennetler vardır."},{"n":9,"t":"Allah’ın vaadi olarak orada ebedî kalacaklardır. O güçlüdür, doğru hüküm verendir."},{"n":10,"t":"O, gökleri görebileceğiniz direkler olmadan yaratmıştır. Sizi sarsmasıyla ilgili yer içinde ağır baskılar yerleştirmiştir. Orada (yerde) her çeşit canlıyı yaymıştır. Biz gökten su indirip, orada (yerde) her değerli çiftten yetiştirmekteyiz."},{"n":11,"t":"İşte bu(nlar) Allah’ın yarattıklarıdır. O’ndan başkasının ne yarattığını bana gösterin! Hayır! Zalimler apaçık bir sapkınlık içindedir."},{"n":12,"t":"Yemin olsun ki biz Lokman’a “Allah’a şükret!” diyerek hikmet (doğru hüküm verme yeteneği) vermiştik. Şükreden ancak kendisi için şükretmiş olur. Nankörlük eden de (bilsin ki) şüphesiz ki Allah (gerçek) zengindir, övgüye layıktır."},{"n":13,"t":"Hani Lokman, oğluna öğüt vererek “Ey yavrucuğum! Allah’a ortak koşma! Şüphesiz ki şirk büyük bir zulümdür.” demişti."},{"n":14,"t":"Biz insana, ana babasını (onlara güzel davranmasını) emretmişizdir. (Çünkü) annesi onu sıkıntı üstüne sıkıntı ile taşımıştır. Sütten ayrılması (kesilmesi) de iki yıl içinde olur. (İşte bunun için) “Bana (ve) ana babana şükret!” diye (emretmiştik). Dönüş, yalnızca banadır."},{"n":15,"t":"Onlar seni, hakkında bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa onlara itaat etme! Onlarla dünyada iyi geçin! Bana yönelenlerin yoluna uy! Sonunda dönüşünüz sadece banadır. (O zaman) size (dünyada) yapmış olduklarınızı bildireceğim."},{"n":16,"t":"(Lokman şöyle demişti:) “Ey yavrucuğum! Yaptığın (iyi veya kötü her) iş, bir hardal tanesi ağırlığında bile olsa ve bu bir kayanın içinde veya göklerde veya yerin derinliklerinde bulunsa yine de Allah onu (karşına) getirir. Şüphesiz ki Allah (detaylarıyla) bilendir, haberdardır."},{"n":17,"t":"Ey yavrucuğum! Namazı kıl; iyiliği emredip (öğütleyip) kötülükten engelle (sakındır); başına gelenlere de sabret! Şüphesiz ki bu, azmetmeye değer işlerdendir."},{"n":18,"t":"İnsanlara yanağını bükme (kibirli olma) ve yeryüzünde kibirlenerek yürüme! Şüphesiz ki Allah kendini beğenip övünenleri sevmez."},{"n":19,"t":"Yürüyüşünde orta hâlli ol, sesini de alçalt! Şüphesiz ki seslerin en çirkini eşeklerin sesidir.”"},{"n":20,"t":"Allah’ın, göklerde ve yerdeki (imkânları) sizin emrinize verdiğini, nimetlerini açık ve gizli olarak size bolca yaydığını görmediniz mi? (Buna rağmen) insanların bir kısmı –bilgisi, rehberi ve aydınlatıcı bir kitabı olmaksızın– Allah hakkında tartışmaktadır."},{"n":21,"t":"Onlara (müşriklere) “Allah’ın indirdiğine uyun!” dendiği zaman, onlar “Hayır! Biz atalarımızı üzerinde bulduğumuz (yol)a uyarız.” dediler. Şeytan, onları alevli ateşin azabına çağırıyor idiyse (de mi)!"},{"n":22,"t":"Kim iyilik yaparak yüzünü Allah’a teslim ederse elbette en sağlam kulba yapışmıştır. Bütün işlerin sonu yalnızca Allah’a varır."},{"n":23,"t":"İnkâr edenin inkârı seni üzmesin! Onların dönüşü ancak bizedir. Elbette yaptıklarını kendilerine bildireceğiz. Şüphesiz ki Allah göğüslerin (kalplerin) özünü bilendir."},{"n":24,"t":"Onları biraz yararlandırır, sonra da kendilerini ağır bir azaba sürükleriz."},{"n":25,"t":"Onlara “Gökleri ve yeri kim yarattı?” diye sorsan, elbette “Allah” derler. De ki: “Hamd (övgü) Allah içindir; esasında onların çoğu (ne dediklerini) bilmezler.”"},{"n":26,"t":"Göklerde ve yerde ne varsa hepsi yalnızca Allah’a aittir. Şüphesiz ki gerçek zengin, övülmeye layık olan yalnızca Allah’tır."},{"n":27,"t":"Yeryüzündeki ağaçlar kalem, deniz de arkasından yedi deniz daha katılarak (mürekkep) olsa yine de Allah’ın sözleri (yazmakla) tükenmez. Şüphesiz ki Allah güçlüdür, doğru hüküm verendir."},{"n":28,"t":"Sizin yaratılmanız ve diriltilmeniz ancak tek bir kişinin yaratılması ve diriltilmesi gibidir. Şüphesiz ki Allah duyandır, görendir."},{"n":29,"t":"Bilmez misin ki Allah geceyi gündüzün içine koyuyor, gündüzü de gecenin içine koyuyor. Güneşi ve ayı emri altına almıştır. Her biri belirlenmiş bir süreye kadar akıp gider. Şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":30,"t":"Çünkü Allah gerçeğin ta kendisidir; O’nun peşi sıra yalvardıkları ise şüphesiz ki batıldır. Şüphesiz ki Allah -evet yalnız O- yücedir, büyüktür."},{"n":31,"t":"Size varlığının delillerini göstermesi için, Allah’ın nimetiyle geminin denizde yüzdüğünü görmüyor musun? Şüphesiz ki bunda çok sabreden, çok şükreden herkes için dersler vardır."},{"n":32,"t":"Dalgalar, onları gölgeler gibi kuşattığı zaman, dini yalnız O’na özgü kılarak Allah’a yalvarırlar. (Allah) onları karaya kurtarınca (çıkarınca), içlerinden bir kısmı orta (dengeli yolda) olur. Bizim ayetlerimizi nankör gaddarlardan başkası inkâr etmez."},{"n":33,"t":"Ey insanlar! Rabbinize karşı takvâlı (duyarlı) olun! Hiçbir babanın evladı, hiçbir evladın da babası adına hiçbir şey gideremeyeceği günden çekinin! Şüphesiz ki Allah’ın vaadi gerçektir. Dünya hayatı sakın sizi aldatmasın ve o çok aldatıcı (şeytan sakın) sizi Allah ile aldatmasın!"},{"n":34,"t":"Şüphesiz ki o (Son) Saat’in bilgisi yalnızca Allah’ın katındadır. Yağmuru O yağdırır. Rahimlerde olanı O bilir. Kimse yarın ne kazanacağını bilemez. Kimse nerede öleceğini de bilemez. Şüphesiz ki Allah bilendir, haberdardır."}],[{"n":1,"t":"Elif. Lâm. Mîm."},{"n":2,"t":"Kendisinde hiçbir şüphe bulunmayan bu Kitabın indirilişi âlemlerin Rabbindendir."},{"n":3,"t":"Yoksa “Onu (Muhammed) uydurdu” mu diyorlar? Aksine doğru yolu bulsunlar diye o, senden önce kendilerine uyarıcı gelmemiş bir kavmi uyarman için Rabbinden gönderilen gerçektir."},{"n":4,"t":"Gökleri, yeri ve ikisinin arasındakileri altı günde (dönemde) yaratan, sonra arşa istiva eden Allah’tır. Sizin için O’ndan başka hiçbir dost ve şefaatçi yoktur. (Hâlâ gerçeği) hatırlamıyor musunuz?"},{"n":5,"t":"(Allah) gökten yere (kadar her) işi düzenleyip yönetir. Sonra (bütün bu işler) sizin saymakta olduğunuz türden bin sene tutan bir günde O’na yükselir."},{"n":6,"t":"İşte, görünmeyeni de görüneni de bilen, güçlü, çok merhametli olan O’dur."},{"n":7,"t":"O ki yarattığı her şeyi güzel yapmış ve insanı yaratmaya çamurdan başlamıştır."},{"n":8,"t":"Sonra onun neslini dayanıksız bir suyun özünden yaratmıştır."},{"n":9,"t":"Sonra onu şekillendirmiş, ona rûhundan üflemiştir. Sizin için işitme (duyusu), gözler ve kalpler yaratmıştır. Ne kadar da azınız şükrediyor!"},{"n":10,"t":"(İnkârcılar) “Toprağın içinde kaybolduğumuz zaman biz mi yeni bir yaratılışta olacakmışız?” derler. Doğrusu onlar Rablerine kavuşmayı inkâr edenlerdir."},{"n":11,"t":"De ki: “Size vekil kılınan (görevlendirilen) ölüm meleği sizi vefat ettirecek, sonra Rabbinize döndürüleceksiniz.”"},{"n":12,"t":"O suçluların Rableri huzurunda başlarını öne eğecekleri ve “Rabbimiz! Gördük, duyduk; bizi (dünyaya) geri gönder de iyi işler yapalım; artık kesin olarak inananlarız!” diyecekleri zamanı bir görsen!"},{"n":13,"t":"Biz dileseydik elbette herkese hidayetini verirdik. Fakat “Cehennemi hem cinlerden hem insanlardan bir kısmıyla dolduracağım!” diye benden kesin söz çıkmıştır."},{"n":14,"t":"(O gün onlara şöyle diyeceğiz:) “Bugüne kavuşmayı unutmanızın karşılığını tadın! Doğrusu biz de sizi unuttuk; yaptıklarınız nedeniyle ebedî azabı tadın!”"},{"n":15,"t":"Bizim ayetlerimize inananlara onlarla (ayetlerimizle gerçekler) hatırlatıldığı zaman, kibirlenmeden secde eder ve Rablerini hamd (övgü) ile tesbih ederler (yüceltirler)."},{"n":16,"t":"Rablerine korkuyla ve ümitle yalvararak vücutları yataklar(ın)dan uzak kalır; kendilerine verdiğimiz rızıktan (Allah yolunda) infak ederler (verirler)."},{"n":17,"t":"Yaptıklarına karşılık olarak, onlar için ne göz aydınlıklarının gizlendiğini kimse bilemez."},{"n":18,"t":"Mümin olan kişi, yoldan çıkan kişi gibi midir? (Elbette) bir olamazlar."},{"n":19,"t":"İman edip iyi işler yapanlara gelince, yaptıklarının karşılığında bir ikram olarak onlar için barınılacak cennetler vardır."},{"n":20,"t":"Yoldan çıkanlara gelince, onların barınağı ise ateştir. Oradan her çıkmak istediklerinde geri döndürülmüş (olacak)lar ve kendilerine, “Yalanlamış olduğunuz cehennem azabını tadın!” denecektir."},{"n":21,"t":"(Gerçeğe) dönsünler diye en büyük azaptan önce onlara mutlaka en yakın azaptan tattıracağız."},{"n":22,"t":"Kendisine Rabbinin ayetleri hatırlatıldıktan sonra onlardan yüz çevirenden daha zalim kim olabilir ki! Şüphesiz ki biz suçlulardan intikam alıcılarız."},{"n":23,"t":"Yemin olsun ki biz Musa’ya da Kitabı vermiştik. Sen (de) ona kavuşacağından şüphe etme! Onu İsrailoğullarına bir rehber kılmıştık."},{"n":24,"t":"Sabrettikleri ve ayetlerimize kesin bir şekilde inandıkları zaman onların içinden, emrimizle doğru yola ulaştıran önderler çıkarmıştık."},{"n":25,"t":"Şüphesiz ki Rabbin anlaşmazlığa düştükleri şeyler hakkında kıyamet günü aralarında hükmedecektir."},{"n":26,"t":"Yurtlarında dolaştıkları kendilerinden önceki nice nesli helak etmiş olmamız onlara (sonrakilere) yol göstermedi mi? Bunlarda elbette dersler vardır. (Gerçeği) dinlemezler mi?"},{"n":27,"t":"Kupkuru yerlere suyu ulaştırdığımızı, onunla hayvanlarının ve kendilerinin yemekte oldukları ekini çıkarmakta olduğumuzu da mı düşünmediler? (Gerçeği) görmezler mi?"},{"n":28,"t":"“Doğruysanız bu fetih (hüküm) günü ne zamanmış!” derler."},{"n":29,"t":"De ki: “Fetih (hüküm) gününde kâfir olanlara (o günkü) imanları yarar sağlamayacak ve kendilerine bakılmayacak da!”"},{"n":30,"t":"Onlardan yüz çevir ve bekle! Şüphesiz ki onlar da bekleyenlerdir."}],[{"n":1,"t":"Ey Peygamber! Allah’a karşı takvâlı (duyarlı) ol; kâfirlere ve münafıklara itaat etme! Şüphesiz ki Allah bilendir, doğru hüküm verendir."},{"n":2,"t":"Rabbinden sana vahyedilene uy! Şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":3,"t":"Allah’a güven! Vekil (güven kaynağı) olarak Allah yeter."},{"n":4,"t":"Allah hiçbir erkeğin (insanın) göğsünde iki kalp yaratmamıştır. Zıhar yaptığınız eşlerinizi anneleriniz kılmamış ve evlatlıklarınızı da öz çocuklarınız yapmamıştır. Bunlar sizin ağızlarınızdaki (boş) sözlerden ibarettir. Allah ise gerçeği söyler ve (doğru) yola O ulaştırır."},{"n":5,"t":"Onları (evlatlıklarınızı, kendi) babaları(nın adıyla) çağırın! Allah katında en doğrusu budur. Babalarını bilmiyorsanız, (bu takdirde) onlar, din kardeşleriniz ve dostlarınızdır. Yanlışlıkla yaptıklarınızda size vebal yoktur fakat kalplerinizin kastettiği(nde vebal vardır). Allah çok bağışlayandır, çok merhametlidir."},{"n":6,"t":"Peygamber, müminlere kendi canlarından daha yakındır; eşleri de onların (ümmetin) anneleridir. Allah’ın kitabına göre yakınlık sahibi olanlar, (vârislik bakımından) birbirlerine (diğer) müminler ve muhacirlerden daha uygundurlar. Ancak, dostlarınıza uygun bir (vasiyet) yapmanız hariçtir. Bu (uygulamamız), Kitapta yazılı bir (hükmümüz)dür."},{"n":7,"t":"Hani biz, peygamberlerden söz almıştık; senden de, Nuh’tan, İbrahim’den, Musa’dan ve Meryem oğlu İsa’dan da. Onlardan sağlam bir söz almıştık."},{"n":8,"t":"(Allah bu sözü), doğru kişilerin doğruluklarını sorgulasın diye (almıştı). Kâfirler için de elem verici bir azap hazırlamıştır."},{"n":9,"t":"Ey iman edenler! Allah’ın size olan (şu) nimetini hatırlayın: Hani size ordular gelmişti de biz onlara (düşmanlarınıza) karşı bir rüzgâr ve sizin görmediğiniz ordular göndermiştik. Allah yaptıklarınızı görendir."},{"n":10,"t":"Onlar hem yukarınızdan hem aşağı tarafınızdan üzerinize geldikleri zaman, gözler kaydığı (yıldığı), yürekler boğazlara geldiği ve siz Allah hakkında türlü türlü şeyler düşündüğünüz zaman,"},{"n":11,"t":"İşte orada müminler imtihan edilmiş ve şiddetli bir sarsıntıya uğratılmışlardı."},{"n":12,"t":"Hani münafıklar ile kalplerinde hastalık bulunanlar “(Meğer) Allah ve Elçisi bize aldatmadan başka bir vaatte bulunmamışlar!” diyorlardı."},{"n":13,"t":"Onlardan bir grup da şöyle demişti: “Ey Yesribliler (Medineliler)! Sizin için durmanın sırası değil, dönün!” İçlerinden bir grup ise evleri savunmasız olmadığı halde “Şüphesiz ki evlerimiz savunmasızdır!” diyerek Peygamber’den izin istiyordu; (savaştan) kaçmaktan başka bir şey istemiyorlardı."},{"n":14,"t":"(Medine’nin) her yanından (kendi) üzerlerine saldırılsaydı da kendilerinden fitne (savaş) istenseydi, şüphesiz ki hemen bunu yaparlar; onunla ilgili gecikmezlerdi."},{"n":15,"t":"Yemin olsun ki daha önce onlar, arkalarını dönmeyeceklerine (kaçmayacaklarına) dair Allah’a söz vermişlerdi. Allah’a verilen söz sorumluluk gerektirmektedir."},{"n":16,"t":"(İzin isteyenlere) de ki: “Ölümden veya savaştan kaçıyorsanız, kaçmanın size asla yararı olamaz!” (Kaçsanız) bile zaten az yaşatılacaksınız."},{"n":17,"t":"De ki: “Allah size herhangi bir kötülük dilerse, sizi O’na karşı kim koruyabilir veya size herhangi bir merhamet dilerse (size kim zarar verebilir ki)!” Onlar kendileri için Allah’a rağmen hiçbir dost da yardımcı da bulamayacaklardır."},{"n":18,"t":"Allah içinizden (savaştan) alıkoyanları ve yandaşlarına “Bize gelip (katılın)!” diyenleri elbette bilmektedir. Zaten bunlar savaşa çok az gelir."},{"n":19,"t":"(Gelseler de) size karşı cimri olarak (gelirler). Korku geldiğinde, üzer(ler)ine ölüm baygınlığı çökmüş gibi gözleri dönerek sana bakmakta olduklarını görürsün. Korku gidince, iyiliği kıskanarak sizi sivri dilleriyle incitirler. Onlar iman etmiş değillerdir; (bu yüzden) Allah onların yaptıklarını boşa çıkarmıştır. Bu, Allah’a çok kolaydır."},{"n":20,"t":"(Münafıklar, düşman) birliklerinin gitmediğini sanıyorlardı. O birlikler (tekrar) gelse, sizin haberlerinizi (uzaktan) soracak şekilde göçebe Arapların arasında çölde olmak isterler. Zaten içinizde bulunsalardı bile pek savaşacak değillerdi."},{"n":21,"t":"Şüphesiz ki Allah’ın Elçisinde sizin için, (yani) Allah’a ve ahiret gününe (kavuşmayı) umanlar ve Allah’ı çok hatırlayanlar için güzel bir örnek vardır."},{"n":22,"t":"Müminler ise (düşman) birliklerini gördüklerinde “İşte bu, Allah ve Elçisinin bize vadettiğidir! Allah ve Elçisi doğru söylemiştir.” demişlerdi. Bu (orduların gelişi), onların ancak imanlarını ve Allah’a bağlılıklarını artırmıştı."},{"n":23,"t":"Müminlerden, Allah’a verdikleri sözde duran nice adamlar (yiğitler) vardır. Onlardan kimi, adağını (Allah’a sözünü) yerine getirmiş; kimi de (yerine getirmeyi) beklemektedir. Onlar (sözlerini) asla değiştirmemişlerdir."},{"n":24,"t":"Sonunda Allah doğru olanlara, doğruluklarına karşılık (ödül) verecektir; münafıklara dilerse azap edecek veya (tevbe ederlerse bu) tevbelerini kabul edecektir. Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":25,"t":"Allah o kâfirleri hiçbir menfaate ulaşamadan öfkeleri ile geri çevirmişti. Savaş (konusun)da Allah(ın yardımı), müminlere yeter. Allah kuvvetlidir, güçlüdür."},{"n":26,"t":"Allah kitap ehlinden (olup) onlara (müşrik ordularına) yardım edenleri kalelerinden indirmiş ve kalplerine korku düşürmüştü. (Siz direnenlerin) bir kısmını öldürüyor, bir kısmını da esir alıyordunuz."},{"n":27,"t":"(Allah) onların yer(ler)ine, yurtlarına, mallarına ve ayak basmadığınız topraklar(ın)a sizi mirasçı yaptı. Allah her şeye gücü yetendir."},{"n":28,"t":"Ey Peygamber! Eşlerine de ki: “Dünya hayatını ve süsünü (refahını) istiyorsanız, gelin sizi yararlandırayım (mehrinizi vereyim) ve sizi güzellikle bırakayım (boşanalım).”"},{"n":29,"t":"Allah’ı, Elçisini ve ahiret yurdunu istiyorsanız, (bilin ki) şüphesiz ki Allah içinizden güzel davrananlar için büyük bir ödül hazırlamıştır."},{"n":30,"t":"Ey Peygamber’in kadınları (hanımları)! Sizden kim açık bir çirkinlik yaparsa, ona iki kat azap uygulanır. Bu, Allah’a çok kolaydır."},{"n":31,"t":"Sizden kim Allah’a ve Elçisine gönülden itaat eder ve iyi bir iş yaparsa ona da ödülünü iki kat veririz. Ona (cennette) bol rızık hazırlamış (olacağız)."},{"n":32,"t":"Ey Peygamber’in kadınları (hanımları)! Siz, kadınlardan herhangi biri gibi değilsiniz. (Allah’a karşı) takvâlı (duyarlı)ysanız, (yabancı erkeklere karşı) çekici bir üslup ile konuşmayın; sonra kalbinde hastalık bulunan kimse ümide kapılır. Uygun söz söyleyin!"},{"n":33,"t":"Evlerinizde oturun; eski Cahiliye (âdetinde olduğu) gibi açılıp saçılmayın! Namazı kılın, zekâtı verin; Allah’a ve Elçisine gönülden itaat edin! Ey (Peygamber’in) evinin halkı! Allah sizden, günahı gidermek ve sizi tertemiz yapmak istiyor."},{"n":34,"t":"Evlerinizde tilavet edilmekte (okunup aktarılmakta) olan Allah’ın ayetlerini ve hikmeti (doğru hükümleri) hatırlayın! Şüphesiz ki Allah en ince işleri görüp bilendir, haberdardır."},{"n":35,"t":"Müslüman erkekler ve müslüman kadınlar, mümin erkekler ve mümin kadınlar, (Allah’a) itaatkâr erkekler ve (Allah’a) itaatkâr kadınlar, doğru olan erkekler ve doğru olan kadınlar, sabreden erkekler ve sabreden kadınlar, (Allah’a saygı gösteren) mütevazı erkekler ve (Allah’a saygı gösteren) mütevazı kadınlar, sadaka veren erkekler ve sadaka veren kadınlar, oruç tutan erkekler ve oruç tutan kadınlar, namuslarını koruyan erkekler ve (namuslarını) koruyan kadınlar, Allah’ı çok hatırlayan erkekler ve (Allah’ı çok) hatırlayan kadınlar var ya, işte Allah bunlar için bir bağışlanma ve büyük bir ödül hazırlamış (olacak)tır."},{"n":36,"t":"Allah ve Elçisi bir işe hükmettiği zaman, mümin erkek ve kadına işleri konusunda tercih hakkı yoktur. Kim Allah’a ve Elçisine isyan ederse elbette apaçık bir sapkınlığa düşmüş olur."},{"n":37,"t":"Hani Allah’ın nimet verdiği, senin de nimet verdiğine (Zeyd’e) “Eşini yanında (nikâhında) tut; Allah’a karşı takvâlı ol!” diyordun. Allah’ın açığa vuracağı şeyi insanlardan korkarak içinde gizliyordun. Oysa kendisinden korkmana layık olan Allah’tır. Zeyd, ondan (eşi Zeynep’ten) ilişiğini tamamen kesince, biz seni onunla (Zeynep’le) eşleştirdik (nikâhladık) ki evlatlıklar eşlerinden tamamen ayrıldıklarında müminlere (ayrılan o kadınlarla evlenmek isterlerse) herhangi bir zorluk olmasın! Allah’ın emri yerine getirilmiştir."},{"n":38,"t":"Allah’ın, kendisine farz kıldığı (bu) şeyde Peygamber’e herhangi bir vebal yoktur. Daha önce geçenler arasında da Allah’ın kanunu (buydu). Allah’ın emri belirlenmiş bir ölçüdür."},{"n":39,"t":"O (peygamberler ki) Allah’ın mesajlarını tebliğ eder; Allah’a saygı duyarlar. Allah’tan başka kimseden korkmazlar. Hesap görücü olarak Allah (herkese) yeter."},{"n":40,"t":"Muhammed, sizin (yetişkin) erkeklerinizden hiçbirinin babası değildir. Fakat o, Allah’ın elçisi ve peygamberlerin sonuncusudur. Allah her şeyi bilendir."},{"n":41,"t":"Ey iman edenler! Allah’ı çok hatırlayın!"},{"n":42,"t":"O’nu sabah akşam tesbih edin (yüceltin)!"},{"n":43,"t":"O ve melekleri sizi karanlıklardan aydınlığa çıkarmak için size salât ediyor (destek veriyor). (Allah) müminlere karşı çok merhametli olandır."},{"n":44,"t":"Kendisine kavuşacakları gün, (Allah’ın) onlara (müminlere) esenliği ‘selam’dır. (Allah) onlara çok değerli bir ödül hazırlamış (olacak)tır."},{"n":45,"t":"45-46 Ey Peygamber! Şüphesiz ki biz seni şahit, müjdeleyici, uyarıcı, O’nun izniyle Allah’a davet eden ve münîr (ışık saçan) bir kandil olarak gönderdik."},{"n":46,"t":"45-46 Ey Peygamber! Şüphesiz ki biz seni şahit, müjdeleyici, uyarıcı, O’nun izniyle Allah’a davet eden ve münîr (ışık saçan) bir kandil olarak gönderdik."},{"n":47,"t":"Allah’tan (gelecek) büyük bir lütfa ereceklerini müminlere müjdele!"},{"n":48,"t":"Kâfirlere ve münafıklara itaat etme! Onların eziyetlerine aldırma! Allah’a güven! Vekil olarak Allah yeter."},{"n":49,"t":"Ey iman edenler! Mümin kadınları nikâhlayıp da onlara (cinsel olarak) dokunmadan onları boşarsanız, onların aleyhine sizin lehinize sayacağınız hiçbir (bekleme) süresi yoktur. Onlara, geçimlik (mehrin yarısını) verin ve onları güzel bir şekilde bırakın (boşanın)."},{"n":50,"t":"Ey Peygamber! Mehirlerini verdiğin eşlerini, Allah’ın sana ganimet olarak verdiklerinden elinin altında bulunanları, amcanın, halanın, dayının ve teyzenin seninle birlikte hicret eden kızlarını sana helal kıldık. (Bir de) kendisini (mehirsiz bir şekilde) Peygamber’e hibe eden, Peygamber’in de nikâhlamak istediği mümin bir hanımı diğer müminlere değil, sadece sana özel olmak üzere (helal kıldık). Elbette biz sana bir zorluk olmasın diye eşleri ve ellerinin altında bulunanlar hakkında müminlere neyi farz kıldığımızı biliriz. Allah çok bağışlayandır, çok merhametlidir."},{"n":51,"t":"Onlardan dilediğini geriye bırakır, dilediğini de yanına alırsın. (Bir süre) ayrı kaldığın (hanımlar)ından (yolculuğa çıkarken gelmelerini) istemende sana herhangi bir vebal yoktur. Böyle (yapman), onların mutlu olmalarına, üzülmemelerine ve hepsinin senin verdiklerine razı olmalarına daha uygundur. Allah kalplerinizde olanı bilmektedir. Allah bilendir, hoşgörülüdür."},{"n":52,"t":"Bundan sonra artık başka kadınlarla evlenmen de sağ elinin sahip oldukları (mevcut eşlerin) hariç, güzellikleri senin hoşuna gitse bile bunları başka eşlerle değiştirmen de sana helal değildir. Allah her şeyi gözetleyicidir."},{"n":53,"t":"Ey iman edenler! Siz (yemeğin hazırlanma) zamanını gözetmeksizin -bir yemek için size izin verilmesi hariç- Peygamber’in evlerine girmeyin; sadece davet edildiğiniz zaman girin! Yemeği yediğinizde başka bir konuya girmeyerek hemen dağılın! (Çünkü) şüphesiz ki bu durum Peygamber’i üzmekte fakat o (size bunu söylemeye) utanmaktadır. (Ancak) Allah gerçeği söylemekten çekinmez. Onlardan (Peygamber’in hanımlarından) herhangi bir şey istediğiniz zaman perde arkasından isteyin! Bu (durum) hem sizin kalpleriniz hem de onların kalpleri için daha temiz bir davranıştır. Allah’ın Elçisini üzmeniz ve kendisinden sonra onun eşlerini nikâhlamanız sizin için asla söz konusu olamaz. Şüphesiz ki bu durum, Allah katında büyük (bir günah)tır."},{"n":54,"t":"Bir şeyi açığa vursanız da gizleseniz de şüphesiz ki Allah her şeyi bilendir."},{"n":55,"t":"Onlara (Peygamber’in hanımlarına) babaları, oğulları, kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, (tanıdık) kadınları ve sağ ellerinin sahip olduklarından dolayı herhangi bir vebal yoktur. Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah her şeye şahittir."},{"n":56,"t":"Allah ve melekleri, Peygamber’e salât ediyorlar (destek veriyorlar). Ey iman edenler! Siz de ona salât edin (destek verin) ve tam teslimiyet gösterin!"},{"n":57,"t":"Allah’ı ve Elçisini incitenlere Allah dünyada da ahirette de lanet etmiş ve onlar için küçük düşürücü bir azap hazırlamış (olacak)tır."},{"n":58,"t":"Mümin erkeklere ve mümin kadınlara, yapmadıkları bir şeyden dolayı eziyet edenler, elbette bir iftira ve apaçık bir günah yüklenmişlerdir."},{"n":59,"t":"Ey Peygamber! Eşlerine, kızlarına ve müminlerin kadınlarına (dışarı çıktıklarında) dış örtülerini üzerlerine salmalarını söyle! Bu, onların tanınması ve incitilmemesi için en uygunudur. Allah çok bağışlayandır, çok merhametlidir."},{"n":60,"t":"60-61 Şüphesiz ki münafıklar, kalplerinde hastalık bulunanlar ve şehirde çirkin haber yayanlar vazgeçmezlerse, seni onların üzerine salarız; sonra lanetlenmiş olarak, orada senin yanında ancak az bir zaman kalabilirler. Nerede ele geçirilirlerse yakalanır ve (şiddetli bir) ölümle öldürülürler."},{"n":61,"t":"60-61 Şüphesiz ki münafıklar, kalplerinde hastalık bulunanlar ve şehirde çirkin haber yayanlar vazgeçmezlerse, seni onların üzerine salarız; sonra lanetlenmiş olarak, orada senin yanında ancak az bir zaman kalabilirler. Nerede ele geçirilirlerse yakalanır ve (şiddetli bir) ölümle öldürülürler."},{"n":62,"t":"Daha önce geçenler arasında da Allah’ın kanunu (buydu). Allah’ın kanununda asla bir değişiklik bulamazsın."},{"n":63,"t":"İnsanlar sana o (Son) Saat’ten soruyorlar. De ki: “Onun bilgisi yalnızca Allah katındadır.” Belki de o (Son) Saat çok yakın olacak. Onu sana bildirecek olan ne olabilir ki!"},{"n":64,"t":"Şüphesiz ki Allah kâfirlere lanet etmiş ve onlar için çılgın bir ateş hazırlamış (olacak)tır."},{"n":65,"t":"(Onlar) orada ebedî kalacaklar, (kendilerini azaptan koruyacak) herhangi bir dost da yardımcı da bulamayacaklardır."},{"n":66,"t":"Yüzleri ateşte evrilip çevrildiği gün “Ah (eyvah), yazık bize! Keşke Allah’a itaat etseydik, Elçi'ye de itaat etseydik!” diyecekler."},{"n":67,"t":"(İnkârcılar) “Rabbimiz! Biz, liderlerimize ve büyüklerimize itaat ettik (ama) onlar bizi yoldan saptırdılar."},{"n":68,"t":"Rabbimiz! Onlara iki kat azap ver ve onlara büyük (bir şekilde) lanet et!” demiş (olacaklar)dır."},{"n":69,"t":"Ey iman edenler! Siz de Musa’ya eziyet edenler gibi olmayın! (Sonunda) Allah onu, dedikleri şeyden temize çıkarmıştı. O, Allah katında itibarlıydı."},{"n":70,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun ve doğru söz söyleyin!"},{"n":71,"t":"(Böyle davranırsanız) Allah sizin için işlerinizi düzeltir ve sizin için günahlarınızı bağışlar. Kim Allah’a ve Elçisine gönülden itaat ederse elbette büyük bir kurtuluşa ulaşmış olur."},{"n":72,"t":"Biz emaneti (sorumluluğu) göklere, yere ve dağlara sunmuştuk da onlar bunu yüklenmekten çekinmişler, (sorumluluğundan) korkmuşlardı. Onu insan yüklenmişti. Şüphesiz ki o (insan), çok zalimdir, çok cahildir."},{"n":73,"t":"Allah münafık erkeklere ve münafık kadınlara, müşrik erkeklere ve müşrik kadınlara azap edecek; iman eden erkeklerin ve iman eden kadınların da tevbesini kabul edecektir. Allah çok bağışlayandır, çok merhametlidir."}],[{"n":1,"t":"Hamd (övgü), göklerde ve yerde bulunanlar kendisine ait olan Allah içindir. Ahirette de hamd (övgü) yalnızca O’na aittir. O, doğru hüküm verendir, haberdardır."},{"n":2,"t":"Yerin içine gireni ve ondan çıkanı, gökten ineni ve oraya yükseleni bilir. O, çok merhametlidir; çok bağışlayandır."},{"n":3,"t":"Kâfir olanlar, “O (Son) Saat bize gelmeyecektir!” demişlerdi. De ki: “Hayır! Gaybı (bilinemeyeni) bilen Rabbime yemin olsun ki o (Son Saat) mutlaka size gelecektir.” Göklerde ve yerde zerre miktarı bir şey bile O’ndan uzak (ve gizli) kalmaz. Bundan daha küçük ve daha büyük (hiçbir şey) yoktur ki apaçık bir kitapta (ilahi kanunda) bulunmasın."},{"n":4,"t":"(Allah) iman edip iyi işler yapanlara karşılık vermek için (bunu yapacaktır). Onlar için bağışlanma ve değerli bir rızık vardır."},{"n":5,"t":"Ayetlerimizi aciz bırakmak için karşılıklı olarak uğraşanlar için de en kötüsünden elem verici azap vardır."},{"n":6,"t":"Kendilerine bilgi verilenler, Rabbinden sana indirilenin (Kur’an’ın) gerçek olduğunu ve onun güçlü, övgüye layık olan (Allah’ın) yoluna ulaştırdığını görürler (bilirler)."},{"n":7,"t":"Kâfir olanlar (kendi aralarında) şöyle demişlerdi: “Çürüyüp paramparça olduğunuz zaman yeni bir yaratılışta olacağınızı bildiren adamı size gösterelim mi?"},{"n":8,"t":"Acaba o, Allah’a yalan mı uydurmuştur? Yoksa onda cinlenmişlik mi var?” Hayır! Ahirete inanmayanlar (orada) azapta (olacaklar)dır ve derin bir sapkınlık içindedir."},{"n":9,"t":"Onlar gökten ve yerden, önlerinde ve arkalarında (olup bitenlere) hiç bakmıyorlar mı? Dilesek onları yere batırır veya üzerlerine gökten parçalar düşürürüz. Şüphesiz ki bunda (Rabbine) yönelen her kul için bir ders vardır."},{"n":10,"t":"Yemin olsun ki Davud’a tarafımızdan bir ikramda bulunmuştuk (ve) “Ey dağlar! (Beni tesbih ederek) onunla (Davud’la) birlikte yankıyla ses verin!” (demiştik); kuşlara da (aynısını söylemiştik). Ona (onun için) demiri yumuşatmıştık."},{"n":11,"t":"“Geniş zırhlar yap; dokumasında ölçülü davran!” diye (vahyetmiştik). (Siz de) iyi işler yapın! Şüphesiz ki ben yaptıklarınızı görenim."},{"n":12,"t":"Sabah (gidişi) bir ay(lık mesafe), (akşam) dönüşü bir ay(lık mesafe) olan rüzgârı da Süleyman’a (onun hizmetine) vermiştik ve onun için erimiş bakırı, kaynağından sel gibi akıtmıştık. Rabbinin izniyle cinlerden bir kısmı onun (gözünün) önünde çalışırdı. Onlardan kim emrimizden sapsa ona alevli azabı tattırırdık."},{"n":13,"t":"Onlar (cinler) Süleyman için mabedlerden, heykellerden, havuzlar gibi (geniş) leğenlerden, sabit (ağır) kazanlardan ne dilerse yaparlardı. Ey Davud ailesi! Şükür için çalışın! Kullarımdan şükreden(ler) ne kadar da azdır!"},{"n":14,"t":"(Süleyman’ın) ölümüne hükmettiğimiz zaman, onun öldüğünü ancak bastonunu kemiren bir ağaç kurdu göstermişti. (Süleyman) yıkılınca, ortaya çıktı ki cinler gaybı (bilinemeyeni) bilselerdi, o küçük düşürücü azap içinde kalmazlardı."},{"n":15,"t":"Şüphesiz ki sağdan ve soldan iki bahçeye sahip olan sebe’ kavmi için oturdukları yerde bir ders vardır. (Onlara:) “Rabbinizin rızkından yiyin ve O’na şükredin!” (demiştik). İşte güzel bir şehir ve çok bağışlayan bir Rab!"},{"n":16,"t":"(Ancak) onlar yüz çevirmişlerdi. Bu yüzden üzerlerine Arim Seli’ni göndermiştik. Onların iki bahçesini, acı meyveli, ılgınlı ve içinde biraz da sedir ağacı bulunan iki (harap) bahçeye çevirmiştik."},{"n":17,"t":"Nankörlük ettikleri için onları böyle cezalandırmıştık. Nankör olandan başkasını cezalandırır mıyız hiç!"},{"n":18,"t":"Onlar(ın yurdu) ile kendilerini bereketlendirdiğimiz şehirler arasında, kolayca görünen şehirler var etmiş ve bunlar arasında (kolayca) yürümelerini (seyahat etmelerini) mümkün kılmıştık. (Onlara) “Oralarda geceleri ve gündüzleri güven içinde yürüyün (seyahat edin!” demiştik)."},{"n":19,"t":"(Bunun üzerine) “Rabbimiz! Seferlerimizin (yolculuk yaptığımız şehirlerin) arasını uzaklaştır!” demişler ve kendilerine yazık etmişlerdi. (Biz de) onları sözlere (ibretlik anılara) çevirmiş ve onları tamamen parçalamıştık. Şüphesiz ki bunda çok sabreden, çok şükreden herkes için dersler vardır."},{"n":20,"t":"Yemin olsun ki İblis, onlar hakkındaki tahminini doğrulamıştı. İnanan az bir grubun dışında hepsi ona uymuşlardı."},{"n":21,"t":"(Oysa) onun (İblis’in), onlar üzerinde hiçbir etkisi yoktu. Ancak ahirete inananı, şüphe içinde kalandan bil(dir)ip (ortaya çıkaralım) diye (ona bu fırsatı vermiştik). Rabbin her şeyi koruyandır."},{"n":22,"t":"(Müşriklere) de ki: “Allah’ın peşi sıra (ilah) sandıklarınıza yalvarın! Onlar göklerde ve yerde zerre ağırlığınca (hiçbir şeye) sahip değillerdir. Onların bu ikisinde (göklerde ve yerde) hiçbir ortaklığı yoktur; O’nun (Allah’ın) onlardan herhangi bir destekçisi de yoktur.”"},{"n":23,"t":"O’nun (Allah’ın) huzurunda, izin verdiği kimseden başkasına şefaat yarar sağlamaz. Sonunda onların (iyilerin) yüreklerinden korku giderilince (melekler) “Rabbiniz ne buyurdu?” diye soracaklardır. Onlar (cennetlikler) de “Gerçeği!” diyeceklerdir. O yücedir, büyüktür."},{"n":24,"t":"De ki: “Size göklerden ve yerden kim rızık veriyor?” De ki: “Allah! Biz veya siz (ikimizden biri) doğru yol üzerindedir veya apaçık bir sapkınlık içindedir.”"},{"n":25,"t":"De ki: “Bizim işlediğimiz suçtan size sorulmayacak; biz de sizin işlediğiniz (suç)tan sorulmayacağız.”"},{"n":26,"t":"De ki: “Rabbimiz hepimizi bir araya toplayacak, sonra aramızda hak ile (adaletle) hükmedecektir. O, (hükmü) apaçık (adil) verendir, bilendir.”"},{"n":27,"t":"De ki: “O’na (Allah’a) kattığınız ortaklarınızı bana gösterin!” Hayır, aksine! Güçlü, doğru hüküm veren yalnızca Allah’tır."},{"n":28,"t":"Biz seni bütün insanlara ancak müjdeleyici ve uyarıcı olarak gönderdik fakat insanların çoğu bilmezler."},{"n":29,"t":"“Doğruysanız o vaat (Son Saat) ne zamanmış!” derler."},{"n":30,"t":"De ki: “Size öyle bir gün vadedilmiştir ki ondan ne bir saat (bir an) geri kalabilir, ne de ileri geçebilirsiniz.”"},{"n":31,"t":"Kâfir olanlar şöyle demişlerdi: “Biz hiçbir zaman bu Kur’an’a ve bundan önce gelen (kitaplara) inanmayacağız.” Sen o zalimleri, Rablerinin huzurunda tutuklanmış, birbirlerine söz atarlarken bir görsen! Zayıf bırakılanlar kibirlenenlere “Siz olmasaydınız elbette biz inananlar olurduk!” diyeceklerdir."},{"n":32,"t":"Kibirlenenler zayıf bırakılanlara (kıyamet gününde) “Size hidayet geldikten sonra sizi ondan biz mi çevirdik? Aksine siz suç işliyordunuz!” diyeceklerdir."},{"n":33,"t":"Zayıf bırakılanlar kibirlenenlere “Hayır! (İşiniz gücünüz) gece gündüz tuzak kurmaktı. Çünkü siz daima Allah’ı inkâr etmemizi, O’na ortaklar koşmamızı bize emrederdiniz!” diyeceklerdir. Azabı gördüklerinde pişmanlık(larını içinde) gizlemiş olacaklardır. Biz de o kâfir olanların boyunlarına demir halkalar takacağız. Onlar yaptıklarından başka (bir şeyle) mi cezalandırılacaklar ki!"},{"n":34,"t":"Biz ne zaman bir şehre bir uyarıcı gönderdiysek oranın şımarıkları mutlaka “Biz size gönderilmiş olan her şeyi inkâr edicileriz!” demişlerdi."},{"n":35,"t":"(Onlar) “Biz mal ve evlat bakımından daha çoğuz; biz asla azaba uğratılacak da değiliz” demişti."},{"n":36,"t":"De ki: “Rabbim rızkı dilediğine (layık olana) açarak (bol) da verir, kısarak (dar) da verir fakat insanların çoğu bilmezler.”"},{"n":37,"t":"Sizi huzurumuza yaklaştıracak olan, mallarınız da değildir; çocuklarınız da değildir. Ancak iman edip iyi iş(ler) yapanlar hariç! Onlara, (dünyada) yaptıklarının kat kat fazlası karşılık (ödül) vardır. Onlar (cennet) odalarında güven içinde (olacaklar)dır."},{"n":38,"t":"Ayetlerimizi aciz bırakmak için karşılıklı olarak uğraşanlara gelince, onlar da azapta hazır kılınacaklardır."},{"n":39,"t":"De ki: “Rabbim rızkı kullarından dilediğine (layık olana) açarak (bol) da verir, ona kısarak (dar) da verir. Siz iyiliğe ne infak ederseniz (verirseniz), O yerine (yenisini) hemen verir. O rızık verenlerin en hayırlısıdır.”"},{"n":40,"t":"O gün (Allah) onların hepsini toplayacak; sonra meleklere “Size tapanlar bunlar mıydı?” diye (sora)caktır."},{"n":41,"t":"(Melekler de) “Sen yücesin; bizim dostumuz onlar değil, sensin. Aslında onlar cinlere tapıyorlardı. Çoğu onlara inanmıştı.” diyeceklerdir."},{"n":42,"t":"Bugün birbirinize yarar da zarar da vermeye gücünüz yetmez. Haksızlık edenlere “(Dünyada) yalanlamış olduğunuz ateş azabını tadın!” diyeceğiz."},{"n":43,"t":"Onlara apaçık ayetlerimiz tilavet edildiği (okunup aktarıldığı) zaman şöyle demişlerdi: “Bu, sizi babalarınızın taptığı (ilahlardan) çevirmek isteyen bir adamdan başkası değildir. Bu (Kur’an) da uydurulmuş bir yalandan başka bir şey değildir!” demişlerdi. Gerçek kendilerine geldiğinde onu inkâr edenler “Bu (Kur’an) apaçık bir büyüden başka bir şey değildir!” demişlerdi."},{"n":44,"t":"Biz onlara okuyacakları kitaplar vermemiştik. Senden önce onlara herhangi bir uyarıcı da göndermemiştik."},{"n":45,"t":"Onlardan öncekiler de (peygamberlerini) yalanlamışlardı. Bunlar, öncekilere verdiklerimizin (gücün) onda birine bile ulaşamamışlardı. (Önceki toplumlar da) elçilerimi yalanlamışlardı. Cezalandırmam (bak) nasıl olmuştu!"},{"n":46,"t":"(Onlara) de ki: “Size tek bir öğüt vereceğim: (İster) ikişer ikişer (toplu halde, isterse) yalnız başınızayken Allah’ın huzurunda (olduğunuzun bilincinde) olun!” Sonra (şunu) düşünün: Arkadaşınızda (Muhammed’de) hiçbir cinlenmişlik yoktur! O ancak şiddetli bir azabın öncesinde sizin için bir uyarıcıdır."},{"n":47,"t":"De ki: “Ben sizden herhangi bir ücret istemişsem o sizin olsun. Ücretim yalnızca Allah’a aittir. O her şeye şahittir.”"},{"n":48,"t":"De ki: “Şüphesiz ki Rabbim gerçeği ortaya koyar. (O), gaybları (bilinemeyenleri) çok iyi bilendir.”"},{"n":49,"t":"De ki: “Gerçek geldi; batıl ne bir şeyi ortaya çıkarabilir ne de geri getirebilir.”"},{"n":50,"t":"De ki: “(Gerçeklerden) saparsam, sadece kendi aleyhime sapmış olurum. Doğru yolu bulursam bu da Rabbimin bana vahyettiği (Kur’an) sayesindedir. Şüphesiz ki O duyandır, yakındır.”"},{"n":51,"t":"Telaşa düştükleri zaman (onları) bir görsen! Artık kurtuluş yoktur; yakın bir yerden yakalanmışlardır."},{"n":52,"t":"“Ona inandık!” demişlerdir. Ama uzak bir yerden (imana) ulaşmak onlar için nasıl mümkün olur ki!"},{"n":53,"t":"Daha önce (dünyada) onu (gerçeği) inkâr etmişlerdi. Uzak bir yerden gayb (bilinemeyen) hakkında atıp tutuyorlardı."},{"n":54,"t":"Bundan önce benzerlerine yapıldığı gibi, kendileriyle arzu ettikleri şey arasına perde çekilmiş (olacak)tır. Şüphesiz ki onlar kuşkulandıran bir şüphe içindeydiler."}],[{"n":1,"t":"Hamd (övgü), gökleri ve yeri yoktan yaratan, melekleri ikişer, üçer, dörder kanatlı elçiler yapan, yaratmada dilediğini(n sayısını) artıran Allah’adır. Şüphesiz ki Allah her şeye gücü yetendir."},{"n":2,"t":"Allah insanlara herhangi bir merhamet açarsa onu tutabilecek kimse yoktur. O’nun tuttuğunu da kendisinden sonra gönderebilecek kimse yoktur. O güçlüdür, doğru hüküm verendir."},{"n":3,"t":"Ey insanlar! Allah’ın size olan nimet(ler)ini hatırlayın! Allah’tan başka size gökten ve yerden rızık verecek herhangi bir yaratıcı mı varmış! O’ndan başka ilah yoktur. Nasıl oluyor da (gerçeklerden) döndürülüyorsunuz!"},{"n":4,"t":"Seni yalanlarlarsa (üzülme); elbette senden önceki elçiler de yalanlanmıştı. Bütün işler yalnızca Allah’a döndürülecektir."},{"n":5,"t":"Ey insanlar! Şüphesiz ki Allah’ın vaadi gerçektir. Dünya hayatı sakın sizi aldatmasın ve o çok aldatıcı (şeytan) sakın sizi Allah ile aldatmasın!"},{"n":6,"t":"Şüphesiz ki şeytan sizin için düşmandır; siz de onu düşman edinin! Zira o, kendi tarafında olanları alevli ateş halkı olmaları için davet eder."},{"n":7,"t":"Kâfir olanlar için şiddetli bir azap vardır; iman edip iyi işler yapanlara gelince, onlar için de bağışlanma ve büyük bir ödül vardır."},{"n":8,"t":"İşinin kötülüğü kendisine süslü gösterilip onu güzel gören kişi (diğerleri gibi olur mu)! Şüphesiz ki Allah dileyeni (layık gördüğünü) saptırır (sapkınlığını onaylar), dileyeni (layık gördüğünü) de doğru yola ulaştırır. Onlar için üzülerek kendini perişan etme! Şüphesiz ki Allah onların yaptıklarını bilendir."},{"n":9,"t":"Rüzgârları gönderip de bulutu kaldıran (harekete geçiren) Allah’tır. İşte biz o (bulutu) ölü bir şehre göndeririz de ölümünden sonra onunla toprağa hayat veririz. Diriltilme de böyle olacaktır."},{"n":10,"t":"Kim itibar istiyorsa (bilsin ki) itibar, tamamen yalnızca Allah’a aittir. Yalnızca iyi işin yükselttiği güzel sözler Allah’a yükselir. Kötülüklerin tuzağını kuranlara şiddetli bir azap vardır. Onların tuzağı ise yok olup gider."},{"n":11,"t":"Allah sizi (önce) topraktan, sonra da nutfeden (zigottan) yarattı; daha sonra sizi eşler (çiftler) hâline getirdi. Hiçbir dişi, O’nun bilgisi olmadan gebe kalamaz ve doğuramaz. (Bir canlıya) ömür verilmesi de ömründen kısılıp azaltılması da mutlaka bir kitaptadır (sistemi vardır). Şüphesiz ki bu, Allah’a çok kolaydır."},{"n":12,"t":"İki deniz birbirine eşit değildir. Biri tatlıdır, susuzluğu keser, içmesi kolaydır; diğeri ise tuzludur, acıdır. (Buna rağmen) hepsinden de taze et (balık) yiyorsunuz ve giyeceğiniz süs (eşyası) çıkartıyorsunuz. (Allah’ın) nimetlerinden arayıp da şükretmeniz için gemilerin denizi yarıp gittiğini görürsün."},{"n":13,"t":"(Allah) geceyi gündüzün içine koyuyor, gündüzü de gecenin içine koyuyor. Güneşi ve ayı emri altına almıştır. (Bunların) her biri belirlenmiş bir süreye kadar akıp gitmektedir. İşte otorite sadece kendisine ait olan Rabbiniz Allah’tır. O’nun peşi sıra yalvardıklarınız ise bir çekirdek zarına bile sahip değillerdir."},{"n":14,"t":"Onlara (putlara) yalvarsanız (bile) çağrınızı duyamazlar. Sizi duysalardı da isteklerinize cevap veremezlerdi. Kıyamet günü (onları) ortak koştuğunuzu da inkâr edeceklerdir. Haberdar olan (Allah) gibi (gerçeği kimse) sana bildiremez."},{"n":15,"t":"Ey insanlar! Siz Allah’a muhtaçsınız. Gerçek zengin ve övülmeye layık olan Allah’tır."},{"n":16,"t":"Dilerse sizi giderir ve (yerinize) yepyeni bir halk getirir."},{"n":17,"t":"Bu, asla Allah’a zor değildir."},{"n":18,"t":"Hiçbir (günah) yüklüsü, başkasının (günah) yükünü yüklenemez. (Günah) yükü ağır olan kişi, yükünü taşımaya -yakını bile olsa- (başkasını) yardıma çağırsa, yükünden hiçbir zerresi taşınamaz. Sen sadece yalnızken Rablerine saygı duyanları ve namazı kılanları uyarabilirsin. Arınmaya çalışan kişi, sadece kendisi için arınmış olur. Dönüş yalnızca Allah’adır."},{"n":19,"t":"19-22 Kör ile gören, karanlıklar ile aydınlık, (serinletici) gölge ile (kavurucu) sıcak ve diriler ile ölüler bir olamaz. Şüphesiz ki Allah dileyene (layık gördüğüne) duyurur. Sen (aklı) mezarlarda olanlara (gerçeği) duyuramazsın."},{"n":20,"t":"19-22 Kör ile gören, karanlıklar ile aydınlık, (serinletici) gölge ile (kavurucu) sıcak ve diriler ile ölüler bir olamaz. Şüphesiz ki Allah dileyene (layık gördüğüne) duyurur. Sen (aklı) mezarlarda olanlara (gerçeği) duyuramazsın."},{"n":21,"t":"19-22 Kör ile gören, karanlıklar ile aydınlık, (serinletici) gölge ile (kavurucu) sıcak ve diriler ile ölüler bir olamaz. Şüphesiz ki Allah dileyene (layık gördüğüne) duyurur. Sen (aklı) mezarlarda olanlara (gerçeği) duyuramazsın."},{"n":22,"t":"19-22 Kör ile gören, karanlıklar ile aydınlık, (serinletici) gölge ile (kavurucu) sıcak ve diriler ile ölüler bir olamaz. Şüphesiz ki Allah dileyene (layık gördüğüne) duyurur. Sen (aklı) mezarlarda olanlara (gerçeği) duyuramazsın."},{"n":23,"t":"Sen sadece bir uyarıcısın."},{"n":24,"t":"Biz seni bir amaç için müjdeleyici ve uyarıcı olarak gönderdik. (Nitekim) her ümmet için de elbette bir uyarıcı gelmiştir."},{"n":25,"t":"Seni yalanlarlarsa (üzülme), elbette onlardan öncekiler de kendilerine apaçık deliller, sahifeler ve aydınlatıcı kitabı getiren elçileri yalanlamışlardı."},{"n":26,"t":"Sonra ben de o kâfir olanları yakalamıştım. Cezalandırmam (bak) nasıl olmuştu!"},{"n":27,"t":"Şüphesiz ki Allah’ın, gökten su indirmekte olduğunu görmüyor musun? O (su) sayesinde çeşitli renklerde meyveler (yiyecekler) çıkarmaktayız. Dağlardan da renkleri farklı, beyaz, kırmızı ve simsiyah yollar (yarattık)."},{"n":28,"t":"İnsanlardan, adım atan canlılardan ve dört bacaklı hayvanlardan da renkleri farklı olanlar var. Kulları içinden sadece (gerçeği) bilenler Allah’a saygı duyarlar. Şüphesiz ki Allah güçlüdür, çok bağışlayandır."},{"n":29,"t":"29-30 Allah’ın kitabını tilavet edenler (okuyup aktaranlar), namazı kılanlar ve rızık olarak verdiğimiz şeylerden gizli ve açık infak edenler (verenler), (Allah) ödüllerini tam olarak versin ve lütfundan (nimetlerini) artırsın diye asla yok olmayacak bir kazanç umarlar. Şüphesiz ki O çok bağışlayandır, şükre çok karşılık verendir."},{"n":30,"t":"29-30 Allah’ın kitabını tilavet edenler (okuyup aktaranlar), namazı kılanlar ve rızık olarak verdiğimiz şeylerden gizli ve açık infak edenler (verenler), (Allah) ödüllerini tam olarak versin ve lütfundan (nimetlerini) artırsın diye asla yok olmayacak bir kazanç umarlar. Şüphesiz ki O çok bağışlayandır, şükre çok karşılık verendir."},{"n":31,"t":"Sana vahyettiğimiz kitap, kendinden önceki (kitapların aslı)nı doğrulayan gerçektir. Şüphesiz ki Allah kullarından haberdardır, görendir."},{"n":32,"t":"Sonra Kitabı kullarımızdan seçtiklerimize miras kıldık. Kimi kendisine haksızlık eder; kimi ortadadır; kimi de Allah’ın izniyle hayırlarda öndedir. Asıl büyük lütuf işte budur."},{"n":33,"t":"(Büyük lütuf) orada altın bilezikler ve incilerle bezenip (süslenip) ipekten elbiseleri olacak şekilde girecekleri durmaya değer cennetlerdir."},{"n":34,"t":"34-35 (Cennette şöyle) diyeceklerdir: “Hamd (övgü), bizden kaygıyı gideren Allah’adır! İçinde bize hiçbir yorgunluk ve bıkkınlık ulaşmayacak olan, cömertliğinin sonucu olarak bizi ebedî kalınacak cennet yurduna yerleştiren Rabbimiz şüphesiz ki çok bağışlayandır, şükre çok karşılık verendir.”"},{"n":35,"t":"34-35 (Cennette şöyle) diyeceklerdir: “Hamd (övgü), bizden kaygıyı gideren Allah’adır! İçinde bize hiçbir yorgunluk ve bıkkınlık ulaşmayacak olan, cömertliğinin sonucu olarak bizi ebedî kalınacak cennet yurduna yerleştiren Rabbimiz şüphesiz ki çok bağışlayandır, şükre çok karşılık verendir.”"},{"n":36,"t":"Kâfir olanlara da cehennem ateşi vardır. (Orada ölmeleri) hükmü verilmez ki ölsünler; azaplarından da hafifletilme olmayacaktır. Her kâfire işte böyle karşılık vereceğiz."},{"n":37,"t":"Oradakiler şöyle feryat edecekler: “Rabbimiz! Bizi (buradan) çıkar da (dünyada) yaptıklarımızın dışında iyi iş(ler) yapalım.” (Onlara şöyle denecektir:) “Size uyarıcı da geldiği hâlde (gerçeği) hatırlayabilecek kimsenin bunu başarabileceği kadar bir ömür vermedik mi? Şimdi tadın (azabı)!” Zalimlerin hiçbir yardımcısı yoktur."},{"n":38,"t":"Şüphesiz ki Allah göklerin ve yerin gaybını (bilinemeyenlerini) bilendir. O, göğüslerin (kalplerin) içinde olanı da bilendir."},{"n":39,"t":"O (Allah) sizi yeryüzünde halifeler (sorumlular olarak) görevlendirmiştir. Kim kâfir olursa küfrü kendi aleyhinedir. kâfirlerin küfrü Rableri katında öfkeden başka bir şey artırmaz. Kâfirlerin küfrü kayıptan başka bir şey(lerini) artırmaz."},{"n":40,"t":"De ki: “Allah’ın peşi sıra yalvardığınız ortaklarınızı bir düşünsenize! Yerden neyi yaratmışlar bana gösterin veya göklerle ilgili (onların yaratılışında) onların ortaklığı mı varmış! Yoksa biz onlara (farklı) bir kitap vermişiz de o kitaptan bir delile mi dayanıyorlarmış!” Aksine o zalimler birbirlerine aldanmadan başka bir şey vadetmiyorlar."},{"n":41,"t":"Şüphesiz ki göklerin ve yerin yok olmasını engelleyen Allah’tır. Yok olurlarsa, O’ndan sonra (Allah’tan başka) kimse onları (sistemlerinde) tutamaz. Şüphesiz ki O hoşgörülüdür, çok bağışlayandır."},{"n":42,"t":"42-43 Kendilerine bir uyarıcı gelmesi hâlinde, herhangi bir topluluktan daha doğru yolda olacaklarına dair bütün güçleriyle Allah’a yemin etmişlerdi. Fakat onlara uyarıcı gelince bu, onların sadece gerçek(ler)den uzaklaşmalarını yani yeryüzünde kibirlenmelerini ve kötülük tuzağını (kurmalarını) artırdı. Oysa kötü tuzak, sadece sahibinin başına geçer. Onlar öncekilere (uygulanan) kanunundan başka ne bekliyorlar ki! Allah’ın kanununda asla bir değişiklik bulamazsın! Allah’ın kanununda asla bir sapma bulamazsın."},{"n":43,"t":"42-43 Kendilerine bir uyarıcı gelmesi hâlinde, herhangi bir topluluktan daha doğru yolda olacaklarına dair bütün güçleriyle Allah’a yemin etmişlerdi. Fakat onlara uyarıcı gelince bu, onların sadece gerçek(ler)den uzaklaşmalarını yani yeryüzünde kibirlenmelerini ve kötülük tuzağını (kurmalarını) artırdı. Oysa kötü tuzak, sadece sahibinin başına geçer. Onlar öncekilere (uygulanan) kanunundan başka ne bekliyorlar ki! Allah’ın kanununda asla bir değişiklik bulamazsın! Allah’ın kanununda asla bir sapma bulamazsın."},{"n":44,"t":"Kendilerinden çok daha güçlü olan öncekilerin sonunun nasıl olduğunu görmek için yeryüzünde hiç mi dolaşmadılar? Göklerde de yerde de Allah’ı aciz bırakacak hiçbir şey yoktur. Şüphesiz ki O bilendir, gücü yetendir."},{"n":45,"t":"Allah insanları yaptıkları yüzünden (hemen) hesaba çekseydi, onun sırtında (yeryüzünde) hiçbir canlı bırakmazdı. Ancak onları belirlenmiş bir süreye erteliyor. Süreleri gelince şüphesiz ki Allah kullarını görendir."}],[{"n":1,"t":"Yâ. Sîn."},{"n":2,"t":"Doğru hükümler içeren Kur’an’a yemin olsun ki"},{"n":"3-4","t":"Şüphesiz sen (hepsi) doğru yol üzerinde olan elçilerdensin."},{"n":"5-6","t":"(Kur’an), ataları uyarılmış, (ancak gerçeklerden) habersizmiş gibi davranan bir toplumu uyarman için çok güçlü, çok merhametli (Allah) tarafından indirilmiştir."},{"n":7,"t":"Şüphesiz ki onların çoğuna (gafletlerine karşılık) azap vaadi gerçekleşmiştir. (Onlar) iman etmezler."},{"n":8,"t":"Şüphesiz ki biz onların boyunlarına, çenelerine kadar dayanacak halkalar geçirdik; başları yukarı kalkıktır."},{"n":9,"t":"Önlerinden ve arkalarından bir set çektik ve onları çepeçevre kuşattık; gerçeği görmezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da onlar için birdir, inanmazlar."},{"n":11,"t":"Sen ancak zikre (Kur’an’a) uyan ve gaybda bulunan Rahmân’a saygı duyanı uyarabilirsin. İşte böylesini bir bağışlama ve değerli bir ödülle müjdele!"},{"n":12,"t":"Şüphesiz ki ölüleri ancak biz dirilteceğiz. İnsanların yaptıklarını ve (geriye bıraktıkları) eserlerini yazıyoruz. Biz her şeyi apaçık bir imam’da (amel defterinde) saymışızdır."},{"n":13,"t":"Onlara (müşriklere) şu şehir halkını örnek ver: Hani onlara elçiler gelmişti."},{"n":14,"t":"Hani kendilerine iki elçi gönderdiğimizde onları yalanlamışlardı. (İki elçiyi) üçüncü ile desteklemiştik ve “Biz (Allah tarafından) size gönderilmiş elçileriz.” demişlerdi."},{"n":15,"t":"(Şehir halkı elçilere) “Siz de ancak bizim gibi insansınız. Rahmân (size) herhangi bir şey indirmemiştir; siz sadece yalan söylüyorsunuz!” demişti."},{"n":16,"t":"(Elçiler) “Rabbimiz biliyor ki doğrusu biz size gönderilmiş elçileriz."},{"n":17,"t":"Apaçık tebliğden başka üzerimize düşen (bir şey) yoktur.” demişlerdi."},{"n":18,"t":"(Şehir halkı) “Sizin yüzünüzden uğursuzluğa uğradık. (Tebliğden) vazgeçmezseniz, şüphesiz ki sizi kovacağız; elbette bizden size elem verici bir azap dokunacak!” demişti."},{"n":19,"t":"(Elçiler şöyle demişlerdi): “Uğursuzluğunuz sizden kaynaklanıyor. (Gerçekler size) hatırlatıldığı için mi (uğursuzluğa uğradınız)? Aslında siz aşırıya kaçan bir topluluksunuz.”"},{"n":20,"t":"(Bu esnada) şehrin ileri gelenlerinden bir adam koşarak gelmiş ve şunları söylemişti: “Ey kavmim! Bu elçilere uyun!"},{"n":21,"t":"Sizden hiçbir ücret istemeyen, kendileri de doğru yol üzerinde olan (bu elçilere) uyun!"},{"n":22,"t":"Ben ne diye beni yoktan yaratana ibadet etmeyecekmişim ki! (Oysa) hepiniz yalnızca O’na döndürüleceksiniz."},{"n":23,"t":"O’nun peşi sıra ilahlar edinir miyim hiç! Rahmân bana bir zarar vermek isterse, onların (ilahların) şefaati bana hiçbir yarar sağlayamaz ve beni kurtaramaz."},{"n":24,"t":"(Başka ilahlar edinirsem) işte o zaman apaçık bir sapkınlıkta olurum."},{"n":25,"t":"Şüphesiz ki ben Rabbinize güvendim; siz de beni dinleyin (ve O’na güvenin)!”"},{"n":26,"t":"26-27 Ona “Cennete gir!” denince, o da “Ah! Keşke kavmim, Rabbimin beni bağışladığını ve beni ikram edilenlerden kıldığını bilseydi!” demişti."},{"n":27,"t":"26-27 Ona “Cennete gir!” denince, o da “Ah! Keşke kavmim, Rabbimin beni bağışladığını ve beni ikram edilenlerden kıldığını bilseydi!” demişti."},{"n":28,"t":"O (adam)ın ardından, şehir halkını (helak etmek için) üzerlerine gökten herhangi bir ordu indirmedik; (daha önce) de indiriciler değildik."},{"n":29,"t":"(Bekledikleri), korkunç bir sesten ibarettir; bir de bakarsın ki yere serilirler."},{"n":30,"t":"Ah, kendilerine gelen her elçi ile mutlaka alay etmiş olan kullara yazıklar olsun!"},{"n":31,"t":"Onlar (müşrikler), kendilerinden önce nice toplumları helak ettiğimizi, onların (eskilerin), diğerlerine (yaşayanlara) tekrar dönmediklerini hiç mi düşünmediler!"},{"n":32,"t":"Elbette onların hepsi, tamamı (huzurumuzda) hazır kılınmışlardır."},{"n":33,"t":"Ölü toprak onlar için bir delildir. Onu canlandırdık ve ondan ürünler çıkarttık; o (ürünler)den yiyorlar."},{"n":34,"t":"34-35 Yeryüzünde hurma bahçeleri ve üzüm bağları yarattık; ürünlerinden ve kendi elleriyle yaptıklarından yesinler diye oralarda birçok (su) kaynağı fışkırttık. (Hâlâ) şükretmeyecekler mi?"},{"n":35,"t":"34-35 Yeryüzünde hurma bahçeleri ve üzüm bağları yarattık; ürünlerinden ve kendi elleriyle yaptıklarından yesinler diye oralarda birçok (su) kaynağı fışkırttık. (Hâlâ) şükretmeyecekler mi?"},{"n":36,"t":"Yerin yetiştirmekte olduklarından, (insanların) kendilerinden ve bilemeyecekleri şeylerden bütün çiftleri yaratan (Allah) yücedir!"},{"n":37,"t":"Gece de onlar için bir delildir. Ondan (geceden) gündüzü sıyırıp çekeriz; bir de bakarsın ki insanlar karanlıkta kalırlar."},{"n":38,"t":"Güneş, kendisi için belirlenmiş yerde akar. İşte bu, güçlü, bilen (Allah)’ın ölçüsüdür."},{"n":39,"t":"Aya da eski bir hurma dalı gibi oluncaya kadar birtakım evreler belirledik."},{"n":40,"t":"Güneş aya yetişmez; gece de gündüzü geçemez. Hepsi, bir(er) yörüngede yüzerler."},{"n":41,"t":"Nesillerini dolu bir gemide taşımamız da onlar için bir delildir."},{"n":42,"t":"Kendileri için bunun gibi binecekleri başka şeyler de yarattık."},{"n":43,"t":"43-44 Katımızdan bir merhamet ve onları belirli bir süreye kadar yaşatma kararı hariç, dilersek onları (suda) boğabiliriz. Artık yardım da isteyemezler; boğulmaktan da kurtarılamazlar."},{"n":44,"t":"43-44 Katımızdan bir merhamet ve onları belirli bir süreye kadar yaşatma kararı hariç, dilersek onları (suda) boğabiliriz. Artık yardım da isteyemezler; boğulmaktan da kurtarılamazlar."},{"n":45,"t":"Onlara “Önünüzdekinden ve arkanızdakinden korunun ki merhamete uğratılasınız” dendiğinde"},{"n":46,"t":"Ve kendilerine Rablerinin ayetlerinden bir ayet geldiğinde, mutlaka ondan yüz çevirmişlerdi."},{"n":47,"t":"Onlara “Allah’ın size rızık olarak verdiklerinden infak edin (verin)” dendiğinde, kâfir olanlar iman edenlere “Allah’ın, dilemesi hâlinde doyuracağı kişileri biz mi doyuracakmışız! Siz sadece apaçık bir sapkınlık içindesiniz!” demişlerdi."},{"n":48,"t":"“Doğruysanız o vaat (Son Saat) ne zamanmış!” derler."},{"n":49,"t":"Birbirleriyle çekişip dururken kendilerini ansızın yakalayacak korkunç bir sesten başka bir şey beklemiyorlar."},{"n":50,"t":"O durumda ne bir tavsiyede bulunabilir; ne de ailelerine dönebilirler."},{"n":51,"t":"Sûr’a üflendiğinde, bir de bakarsın ki (hemen) mezarlar(ın)dan (kalkarak) Rablerine koşacaklar."},{"n":52,"t":"(Müşrikler) “Ah, eyvah! Bizi kabrimizden kim kaldırıp (uyandırdı)? Bu, Rahmân’ın vadettiği (gün)dür; (demek ki) elçiler gerçeği söylemiş!” diyecekler."},{"n":53,"t":"(Bekledikleri), müthiş bir sesten ibarettir. Bir de bakarsın ki hepsi (huzurumuzda) hazır kılınmışlardır."},{"n":54,"t":"(Artık) bugün, kimse haksızlığa uğratılmayacak ve size de yaptıklarınızdan başka karşılık verilmeyecektir."},{"n":55,"t":"Bugün cennet halkı meşguliyetler içinde eğlenirler."},{"n":56,"t":"Onlar ve eşleri, tahtların üzerinde gölgelerde (olacaklar)dır."},{"n":57,"t":"Onlar için orada, her çeşit meyve ve her istedikleri vardır."},{"n":58,"t":"(Bir de) çok merhametli Rab’den ‘selam’ sözü (vardır)."},{"n":59,"t":"(Suçlulara şöyle denecektir): “Ey suçlular, bugün (kenara) çekilip ayrılın!"},{"n":60,"t":"Ey âdemoğulları! Size ‘Şeytana tapmayın; şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":61,"t":"Bana kulluk edin; doğru yol budur’ demedim mi?"},{"n":62,"t":"Şeytan sizden pek çok nesli saptırdı; akıl etmediniz mi?"},{"n":63,"t":"63-64 İşte, nankörlüğünüzün karşılığı olarak size vadedilen cehennem, bugün oraya girin!”"},{"n":64,"t":"63-64 İşte, nankörlüğünüzün karşılığı olarak size vadedilen cehennem, bugün oraya girin!”"},{"n":65,"t":"Bugün onların ağızlarını mühürleyeceğiz; kazandıkları (yaptıkları) hakkında bize elleri konuşacak ve ayakları da şahitlik edecektir."},{"n":66,"t":"Dileseydik gözlerini silip (kör eder)dik de yolu bulmaya koşuşurlardı; (bu durumda) nasıl görebilirler ki!"},{"n":67,"t":"Dileseydik oldukları yerde şekillerini değiştirirdik de ileri gitmeye güç yetiremezlerdi ve geri de dönemezler(di)!"},{"n":68,"t":"Uzun ömür verdiğimizi yaratılışta tersine çeviririz. Akıl etmiyorlar mı?"},{"n":"69-70","t":"Biz ona (Peygamber’e) şiir öğretmedik. Zaten ona gerekmez de. O(nun söyledikleri), sağ olanları uyarsın ve kâfirlere de (azap) sözü gerçekleşsin diye sadece (gerçeğin) hatırla(t)ması ve apaçık bir Kur’an’dır."},{"n":71,"t":"Ellerimizin (kudretimizin) yaptığı işlerden olarak kendileri için hayvanları yaratmamızı ve onlara sahip olmalarını düşünmediler mi!"},{"n":72,"t":"Onları kendilerinin hizmetine sunduk; bir kısmından binekleri vardır; bir kısmından ise yiyorlar."},{"n":73,"t":"Onlarda insanlar için yararlar ve içecekler de vardır. (Hâlâ) şükretmiyorlar mı?"},{"n":74,"t":"Kendilerine yardım edileceğini umarak Allah’ın peşi sıra ilahlar edindiler."},{"n":75,"t":"(Oysa) onlar kendilerine yardım edemezler; onlar diğerlerinin (birbirlerinin) hazırlanmış askerleridir."},{"n":76,"t":"Sözleri seni üzmesin! Gizlediklerini de açıkladıklarını da biliyoruz."},{"n":77,"t":"O (inkârcı) insan, kendisini nutfeden (zigottan) yarattığımızı görmedi mi? Bir de bakarsın ki o apaçık bir tartışmacı olmuş."},{"n":78,"t":"Kendi yaratılışını unutarak bize örnek vermeye kalkışmış ve “Çürümüş kemikleri kim diriltebilirmiş ki!” demişti."},{"n":79,"t":"De ki: “Onları ilk kez yoktan var eden diriltecektir. O, her türlü yaratmayı çok iyi bilendir.”"},{"n":80,"t":"Yeşil ağaçtan sizin için ateş yaratan da O’dur. İşte o (ağaç)tan tutuşturuyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan (Allah) insanların benzerlerini yaratmaya gücü yeten değil midir? Elbette! O, her türlü yaratabilendir, bilendir."},{"n":82,"t":"Bir şey(in olmasını) istediği zaman O’nun durumu o şeye sadece “Ol!” demektir; o da hemen olmaya başlar."},{"n":83,"t":"Her şeyin egemenliği yalnızca kendi elinde olan (Allah) yücedir! Hepiniz, yalnızca O’na döndürüleceksiniz."}],[{"n":1,"t":"Yemin olsun: Sıra sıra dizilenlere,"},{"n":2,"t":"Engel olanlara,"},{"n":3,"t":"Zikr (Kur’an) okuyanlara ki"},{"n":4,"t":"Şüphesiz ilahınız tektir."},{"n":5,"t":"Hem göklerin, yerin ve ikisi arasındakilerin Rabbi hem de doğuların Rabbidir."},{"n":6,"t":"Şüphesiz ki biz yakın göğü gezegenlerden oluşan süsle süsledik."},{"n":7,"t":"(Onu) isyankâr her şeytandan koruduk."},{"n":8,"t":"8-9 Onlar yüce topluluğa kulak veremezler. Kovularak her taraftan atılırlar. Onlar için ebedî bir azap vardır."},{"n":9,"t":"8-9 Onlar yüce topluluğa kulak veremezler. Kovularak her taraftan atılırlar. Onlar için ebedî bir azap vardır."},{"n":10,"t":"Ancak (meleklerin konuşmalarından) bir söz çalmaya kalkışan olursa, onu hemen delip geçen parlak bir ışık takip eder."},{"n":11,"t":"(Şimdi) sor onlara! Onları yaratmak mı daha zor, yoksa bizim yarattığımız (diğer) bilinçli (varlıkları yaratmak) mı? Şüphesiz ki biz kendilerini yapışkan bir çamurdan yarattık."},{"n":12,"t":"Elbette sen şaşırıyorsun. (Oysa) onlar alay ediyorlar."},{"n":13,"t":"Kendilerine (gerçekler) hatırlatıldığı zaman (gerçeği) hatırlamazlar."},{"n":14,"t":"Bir ayet gördüklerinde alay ederler."},{"n":15,"t":"Şöyle derler: “Bu, apaçık bir büyüden başka bir şey değildir."},{"n":16,"t":"Biz ölüp de toprak ve kemik hâline gelmişken mi biz mi diriltileceğiz?"},{"n":17,"t":"Önceki atalarımız da mı?”"},{"n":18,"t":"De ki: “Evet hem de hor ve değersiz olarak (diriltileceksiniz).”"},{"n":19,"t":"O (diriltme) korkunç bir sesten ibaret olacak; bir de bakarsın ki onlar etrafa bakacaklar."},{"n":20,"t":"(Kâfirler:) “Ah, eyvah bize! Bu hesap günüymüş!” demiş (olacak)lardır."},{"n":21,"t":"İşte bu, yalanlamış olduğunuz ayrılma günüdür."},{"n":22,"t":"22-23 (Allah meleklere şöyle diyecek:) “Zalimleri, eşlerini (onlar gibi olanları) ve Allah’ın peşi sıra tapmış olduklarını toplayın! Onları cehennemin yoluna iletin!"},{"n":23,"t":"22-23 (Allah meleklere şöyle diyecek:) “Zalimleri, eşlerini (onlar gibi olanları) ve Allah’ın peşi sıra tapmış olduklarını toplayın! Onları cehennemin yoluna iletin!"},{"n":24,"t":"Onları tutuklayın; şüphesiz ki onlar sorguya çekilecekler!”"},{"n":25,"t":"Size ne oldu ki birbirinize yardım etmiyorsunuz?"},{"n":26,"t":"Hayır! Onlar o gün boyun eğmiş olacaklardır."},{"n":27,"t":"Onların bir kısmı bir kısmına dönüp (hesap) soracaklar."},{"n":28,"t":"(Uyanlar, uyduklarına) “Şüphesiz ki siz bize (hep) sağdan gelirdiniz!” diyeceklerdir."},{"n":29,"t":"(Uyulanlar ise) şöyle diyecekler: “Aksine siz inananlar değildiniz."},{"n":30,"t":"Bizim sizi zorlayacak hiçbir gücümüz yoktu. Aslında siz azgın bir toplumdunuz!"},{"n":31,"t":"Rabbimizin (azap) sözü bizim aleyhimize gerçekleşti. Biz (azabı) mutlaka tadacağız."},{"n":32,"t":"Biz sizi saptırdık. Çünkü kendimiz de sapmıştık.”"},{"n":33,"t":"Şüphesiz ki o gün onlar azapta ortaktırlar."},{"n":34,"t":"İşte biz, suçlulara böyle yapacağız."},{"n":35,"t":"Şüphesiz ki onlara “Allah’tan başka ilah yoktur.” dendiği zaman kibir gösterirlerdi."},{"n":36,"t":"“Cinlenmiş bir şair için mi ilahlarımızı terk edeceğiz!” derlerdi."},{"n":37,"t":"Aksine o (elçi), gerçeği getirmiş ve (önceki) elçileri de doğrulamıştı."},{"n":38,"t":"Şüphesiz ki siz elem verici azabı tadacaksınız."},{"n":39,"t":"Size yaptıklarınızdan başka karşılık verilmeyecektir."},{"n":40,"t":"Allah’ın samimi kulları hariç."},{"n":41,"t":"Onlar için bilinen bir rızık vardır."},{"n":42,"t":"42-44 Nimet cennetlerinde tahtlar üzerinde karşılıklı (otururlarken onlara) meyveler ikram edilmiş olacaktır."},{"n":43,"t":"42-44 Nimet cennetlerinde tahtlar üzerinde karşılıklı (otururlarken onlara) meyveler ikram edilmiş olacaktır."},{"n":44,"t":"42-44 Nimet cennetlerinde tahtlar üzerinde karşılıklı (otururlarken onlara) meyveler ikram edilmiş olacaktır."},{"n":45,"t":"45-46 Onlara (içleri) pınardan (doldurulmuş) berrak, içenlere lezzet veren kadehler dolaştırılacaktır."},{"n":46,"t":"45-46 Onlara (içleri) pınardan (doldurulmuş) berrak, içenlere lezzet veren kadehler dolaştırılacaktır."},{"n":47,"t":"Onlarda (içtiklerinde) sersemletme (baş ağrısı) yoktur; ondan dolayı sarhoş da edilmezler."},{"n":48,"t":"Yanlarında bakışlarını yalnız onlara özel kılmış (güzel) gözlü (eş)ler vardır."},{"n":49,"t":"Onlar saklı yumurta gibi bembeyazdır."},{"n":50,"t":"(Cennette) onların bir kısmı, diğerlerine yönelip birbirlerine sormaya başlayacaklar."},{"n":51,"t":"İçlerinden bir (mümin) şöyle diyecek: “Benim yakın (bir arkadaş)ım vardı."},{"n":52,"t":"Der(di) ki: ‘Sen de (diriltilmeye) inananlardan mısın?"},{"n":53,"t":"Biz ölüp de toprak ve kemik hâline gelmişken mi, biz mi (diriltilip) cezalandırılacağız”"},{"n":54,"t":"(Mümin kişi), “(O arkadaşımın durumunu) bilmek ister misiniz?” diyecektir."},{"n":55,"t":"(Ardından) bakıp arkadaşını cehennemin ortasında görecektir."},{"n":56,"t":"(Mümin olan, ateşteki arkadaşına) şöyle diyecektir: “Allah’a yemin olsun: Sen az daha beni de helak edecektin."},{"n":57,"t":"Rabbimin nimeti olmasaydı, şimdi ben de (cehenneme) getirilenlerden olacaktım."},{"n":58,"t":"58-59 Birinci ölümümüz hariç, bir daha ölmeyeceğiz, değil mi? Biz azaba da uğratılmayacağız.”"},{"n":59,"t":"58-59 Birinci ölümümüz hariç, bir daha ölmeyeceğiz, değil mi? Biz azaba da uğratılmayacağız.”"},{"n":60,"t":"Şüphesiz ki bu, büyük bir kurtuluştur."},{"n":61,"t":"Çalışanlar böylesi (bir kurtuluş) için çalışsınlar!"},{"n":62,"t":"Şimdi ziyafet olarak bu (nimetler) mi hayırlıdır, yoksa zakkum ağacı mı?"},{"n":63,"t":"Şüphesiz ki biz onu (zakkumu) zalimler için bir fitne (sıkıntı) kıldık."},{"n":64,"t":"Şüphesiz ki o, cehennemin dibinde bitip yetişen bir ağaçtır."},{"n":65,"t":"Tomurcukları sanki şeytanların başları gibidir."},{"n":66,"t":"(Cehennemdekiler) ondan yer ve karınlarını ondan doldururlar."},{"n":67,"t":"Sonra (zakkumun) üzerine onlar için kaynar sudan bir içecek vardır."},{"n":68,"t":"Sonra elbette onların dönüşü çılgın ateşe olacaktır."},{"n":69,"t":"Şüphesiz ki onlar, atalarını sapkınlıkta bulmuşlardı."},{"n":70,"t":"Kendileri de onların peşlerinden koşturuyorlar."},{"n":71,"t":"Yemin olsun ki kendilerinden önceki eski toplumların çoğu sapmıştı."},{"n":72,"t":"Yemin olsun ki biz onlara uyarıcılar göndermiştik."},{"n":73,"t":"73-74 Allah’ın samimi kulları hariç, uyarılanların (fakat inanmayanların) sonunun nasıl olduğuna bir bak!"},{"n":74,"t":"73-74 Allah’ın samimi kulları hariç, uyarılanların (fakat inanmayanların) sonunun nasıl olduğuna bir bak!"},{"n":75,"t":"Yemin olsun ki Nuh, bize yalvarıp yakarmıştı. Biz de duayı ne güzel kabul edeniz!"},{"n":76,"t":"Kendisini ve ailesini (destekçilerini) büyük felaketten kurtarmıştık."},{"n":77,"t":"Biz onun (Nuh’un) soyunu -işte onları- kalıcı kılmıştık."},{"n":78,"t":"Sonrakiler arasında ona (iyi bir ün) bırakmıştık."},{"n":79,"t":"Bütün âlemlerde Nuh’a selam olsun!"},{"n":80,"t":"Şüphesiz ki biz güzel davrananları işte böyle ödüllendiririz."},{"n":81,"t":"Şüphesiz ki o, mümin kullarımızdandı."},{"n":82,"t":"Sonra diğerlerini (suda) boğmuştuk."},{"n":83,"t":"Şüphesiz ki İbrahim de onun (Nuh’un) tarafındandı."},{"n":84,"t":"Hani o, Rabbine teslim olan (tertemiz) bir kalp ile gelmişti."},{"n":85,"t":"Hani babasına ve halkına şöyle demişti: “Siz neye kulluk ediyorsunuz?"},{"n":86,"t":"Allah’ın peşi sıra uydurma ilahlar(a) mı?"},{"n":87,"t":"Âlemlerin Rabbi hakkındaki görüşünüz nedir?”"},{"n":88,"t":"Sonra yıldızlara bakmıştı."},{"n":89,"t":"“Ben hâlsizim (hastayım)!” demişti."},{"n":90,"t":"Onlar (kavmi) de ona arkalarını dönüp (gitmiş)lerdi."},{"n":"91-92","t":"(İbrahim) yavaşça putlarının yanına varmış, (önlerine konmuş yemekleri görünce) “Yemiyor musunuz? Neden konuşmuyorsunuz?” demişti."},{"n":93,"t":"(Yanlarına giderek) sağ eliyle (güçlü bir şekilde) onlara vurmuştu (kırmıştı)."},{"n":94,"t":"(Putperestler) koşarak ona gelmişlerdi."},{"n":"95-96","t":"(İbrahim) “Yonttuğunuz şeylere mi ibadet ediyorsunuz! Sizi ve yapmakta olduklarınızı Allah yarattı” demişti."},{"n":97,"t":"(Putperestler ise) “Onun için bir bina yapın ve derhal onu ateşe atın!” demişlerdi."},{"n":98,"t":"Ona bir tuzak kurmayı istemişlerdi. Fakat biz onları alçaklardan kılmıştık."},{"n":"99-100","t":"(İbrahim) “Ben Rabbime gidiyorum. O, bana doğru yolu gösterecektir. Rabbim! Bana iyilerden (olacak bir çocuk) ver!” demişti."},{"n":101,"t":"Biz de onu çok hoşgörülü bir oğul ile müjdelemiştik."},{"n":102,"t":"(Oğlu) onunla birlikte yürüyecek çağa ulaşınca, (İbrahim) “Ey yavrucuğum! Rüyada seni kesmekte olduğumu görüyorum; bir düşün, ne dersin?” demişti. (O da) “Ey babacığım! Emrolunduğun şeyi yap! İnşallah beni sabredenlerden bulacaksın.” demişti."},{"n":103,"t":"Her ikisi de teslim olup, onu (oğlunu) alnı üzerine yatırınca,"},{"n":"104-105","t":"Biz ona “Ey İbrahim! Elbette rüyayı gerçekleştirdin. Şüphesiz ki biz, güzel davrananları böyle ödüllendiririz.” diye seslenmiştik."},{"n":106,"t":"Bu, apaçık bir imtihandı."},{"n":107,"t":"Biz (oğlunun yerine) ona büyük bir kurban fidye vermiştik."},{"n":108,"t":"Sonrakiler arasında ona (iyi bir ün) bırakmıştık."},{"n":109,"t":"İbrahim’e selam olsun!"},{"n":110,"t":"İşte (biz) güzel davrananları böyle ödüllendiririz."},{"n":111,"t":"Şüphesiz ki o, mümin kullarımızdandı."},{"n":112,"t":"İyilerden bir peygamber olarak ona İshak’ı müjdelemiştik."},{"n":113,"t":"Ona ve İshak’a bereketler vermiştik. Her ikisinin neslinden iyilik yapan da kendisine açıkça haksızlık eden de çıkacaktır."},{"n":114,"t":"Yemin olsun ki biz Musa’ya ve Harun’a nimetler vermiştik."},{"n":115,"t":"Onları ve toplumlarını o büyük sıkıntıdan kurtarmıştık."},{"n":116,"t":"Kendilerine yardım etmiştik ve galip gelenler işte onlar olmuştu."},{"n":117,"t":"İkisine de apaçık anlaşılan Kitabı vermiştik."},{"n":118,"t":"Her ikisini de doğru yola ulaştırmıştık."},{"n":119,"t":"Sonrakiler arasında o ikisine (iyi bir ün) bırakmıştık."},{"n":120,"t":"Musa ve Harun’a selam olsun!"},{"n":121,"t":"Şüphesiz ki biz güzel davrananları işte böyle ödüllendiririz."},{"n":122,"t":"Şüphesiz ki o ikisi de inanmış kullarımızdandı."},{"n":123,"t":"Şüphesiz ki İlyas da elçilerdendi."},{"n":124,"t":"Hani kavmine “(Allah’a karşı) takvâlı (duyarlı) olmuyor musunuz?"},{"n":"125-126","t":"Yaratanların en iyisini yani sizin de Rabbiniz, atalarınızın da Rabbi olan Allah’ı bırakıp da Ba‘l’e mi yalvarıyorsunuz?” demişti."},{"n":127,"t":"(Kavmi) onu (İlyas’ı) yalanlamıştı. Şüphesiz ki onlar (cehennemde) hazır kılınacaklardır."},{"n":128,"t":"Allah’ın samimi kulları hariç."},{"n":129,"t":"Sonrakiler arasında ona (iyi bir ün) bırakmıştık."},{"n":130,"t":"İlyas’a selam olsun!"},{"n":131,"t":"Şüphesiz ki biz güzel davrananları işte böyle ödüllendiririz."},{"n":132,"t":"Şüphesiz ki o, mümin kullarımızdandı."},{"n":133,"t":"Şüphesiz ki Lut da elçilerdendi."},{"n":"134-135","t":"Hani biz geride kalanlar arasındaki yaşlı (eşi) hariç, onu ve bütün ailesini kurtarmıştık."},{"n":136,"t":"Ardından diğerlerini helak etmiştik."},{"n":"137-138","t":"Siz sabah ve gece onlara (şehirlerine) uğruyorsunuz. Akıl etmiyor musunuz?"},{"n":139,"t":"Şüphesiz ki Yunus da elçilerdendi."},{"n":140,"t":"Hani o, dolu bir gemiye (binip) kaçmıştı."},{"n":141,"t":"(Gemide olanlarla) karşılıklı kura çekmişler ve (Yunus da) kaybedenlerden olmuştu."},{"n":142,"t":"Kendini kınayıp dururken onu bir balık yutmuştu."},{"n":"143-144","t":"(Allah’ı) tesbih edenlerden (yüceltenlerden) olmasaydı, (insanların) diriltilecekleri güne kadar elbette o (balığın) karnında kalırdı."},{"n":145,"t":"Hâlsiz (hasta) bir vaziyette onu kıyıya çıkarmıştık."},{"n":146,"t":"Üzerine (gölge etmesi için) geniş yapraklı bir bitki yetiştirmiştik."},{"n":147,"t":"Onu, yüz bin hatta daha çok kişiye (peygamber olarak) göndermiştik."},{"n":148,"t":"(Ona) inanmışlardı; biz de onları bir süreye kadar yaşatmıştık."},{"n":149,"t":"Onlara (müşriklere) sor: “Kızlar Rabbinin de erkekler onların mı?”"},{"n":150,"t":"Yoksa onlar şahitken (onlar görürken) melekleri kız olarak mı yaratmışız!"},{"n":"151-152","t":"Dikkat edin! Şüphesiz ki yalan uydurarak “Allah çocuk edindi!” diyorlar. Şüphesiz ki onlar yalancıdır."},{"n":153,"t":"(Allah) kızları oğullara tercih mi etmiş!"},{"n":154,"t":"Ne oluyor size? Nasıl (böyle) hükmediyorsunuz?"},{"n":155,"t":"(Gerçeği) hiç hatırlamıyor musunuz?"},{"n":156,"t":"Yoksa sizin apaçık bir deliliniz mi var?"},{"n":157,"t":"Doğruysanız kitabınızı getirin!"},{"n":158,"t":"O’nunla (Allah ile) cinler arasında da bir soy bağı uydurdular. Yemin olsun ki cinler de (Allah’ın huzurunda) hazır kılınacaklarını bilirler."},{"n":159,"t":"Allah onların (müşriklerin) yakıştırdıklarından yücedir."},{"n":160,"t":"Allah’ın samimi kulları hariç."},{"n":"161-163","t":"Siz ve taptığınız şeyler (hiçbiriniz), cehenneme girecek olan kimseden başkasını asla O’na karşı azdırıp saptıramazsınız."},{"n":164,"t":"(Melekler şöyle derler:) “Bizim her birimiz için bilinen bir makam vardır."},{"n":165,"t":"Şüphesiz ki biz (orada) sıra sıra dururuz."},{"n":166,"t":"Şüphesiz ki biz (Allah’ı) tesbih edenleriz (yüceltenleriz).”"},{"n":167,"t":"(Müşrikler) şöyle diyorlardı:"},{"n":"168-169","t":"“Öncekilere (verilenlerden) bizde de bir zikr (kitap) olsaydı mutlaka Allah’ın samimi kulları olurduk!”"},{"n":170,"t":"Hemen onu (Kur’an’ı) inkâr ettiler. İleride (gerçeği) bilecekler!"},{"n":171,"t":"Yemin olsun ki gönderilmiş elçi kullarımıza (şu) sözü verdik:"},{"n":172,"t":"Onlar, mutlaka zafere ulaşacaklardır."},{"n":173,"t":"Şüphesiz ki bizim ordumuz üstün gelecektir."},{"n":174,"t":"Belirli bir süreye kadar onlardan yüz çevir!"},{"n":175,"t":"Onları gör (gözetle); onlar da ileride görecekler."},{"n":176,"t":"Azabımızı acele mi istiyorlar?"},{"n":177,"t":"(Acele istedikleri azabımız) yurtlarına indiğinde, uyarılanların (fakat inanmayanların) sabahı ne kötü olur!"},{"n":178,"t":"Belirli bir süreye kadar onlardan yüz çevir!"},{"n":179,"t":"(Onları) gör (gözetle); onlar da ileride görecekler."},{"n":180,"t":"Rabbin, yani itibar sahibi Rabbin, onların yakıştırdıklarından uzaktır."},{"n":181,"t":"Gönderilen bütün elçilere selam olsun!"},{"n":182,"t":"Hamd (övgü), âlemlerin Rabbi (olan) Allah içindir."}],[{"n":1,"t":"Sâd. Zikr (itibar) sahibi Kur’an’a yemin olsun."},{"n":2,"t":"Aslında kâfir olanlar, (haksız) bir gurur ve ayrılık (düşmanlık) içindedir."},{"n":3,"t":"Onlardan önce nice nesilleri helak etmiştik de feryat etmişlerdi; (ancak) kurtulmaları mümkün değildi."},{"n":4,"t":"4-5 Onlar kendilerine içlerinden bir uyarıcının gelmesine şaşmış ve o kâfirler “Bu bir büyücüdür; çok yalancıdır! Bütün ilahları (yalanlayıp) tek ilah mı (var diyor)? Şüphesiz ki bu çok tuhaf bir şeydir!” demişlerdi."},{"n":5,"t":"4-5 Onlar kendilerine içlerinden bir uyarıcının gelmesine şaşmış ve o kâfirler “Bu bir büyücüdür; çok yalancıdır! Bütün ilahları (yalanlayıp) tek ilah mı (var diyor)? Şüphesiz ki bu çok tuhaf bir şeydir!” demişlerdi."},{"n":6,"t":"İçlerinden yöneticiler öne atılmış, (şöyle demişlerdi:) “(İnancınızda) yürüyün; ilahlarınıza bağlı kalın (onları savunun)! Şüphesiz ki bu, (sizden) istenen şeydir."},{"n":7,"t":"Son dinde bile böyle bir şey duymadık. Bu, uydurmadan başka bir şey değildir."},{"n":8,"t":"Zikr (Kur’an), aramızdan ona (Muhammed’e) mi indirildi?” Aslında (onlar) zikrimden (Kur’an’dan) şüphe içindedir. Aslında onlar azabımı henüz tatmadılar."},{"n":9,"t":"Yoksa güçlü, bolca veren Rabbinin merhamet hazineleri onların yanında mı?"},{"n":10,"t":"Yoksa göklerin, yerin ve ikisi arasında bulunanların otoritesi kendi ellerinde mi? (Öyleyse), sebepler içinde yükselsinler (bahanelere sarılsınlar)!"},{"n":11,"t":"(Onlar) orada (Mekke’de) çeşitli (zayıf) gruplardan oluşmuş, bozguna uğratılacak bir ordudur."},{"n":12,"t":"12-13 (Nitekim) kendilerinden önce Nuh kavmi, Âd (kavmi), kazıklar sahibi Firavun, Semûd, Lut kavmi ve Eyke halkı (gibi) bütün bu gruplar yalanlamışlardı."},{"n":13,"t":"12-13 (Nitekim) kendilerinden önce Nuh kavmi, Âd (kavmi), kazıklar sahibi Firavun, Semûd, Lut kavmi ve Eyke halkı (gibi) bütün bu gruplar yalanlamışlardı."},{"n":14,"t":"Hepsi elçileri elbette yalanlamışlardı ve (kendilerine) azabım gerçekleşmişti."},{"n":15,"t":"Bunlar da geri dönüşü olmayan bir (bela) sesinden başka bir şey beklemiyorlar."},{"n":16,"t":"(Müşrikler, alay ederek) “Rabbimiz! Bizim payımızı hesap gününden önce acele ver!” demişlerdi."},{"n":17,"t":"Onların söylediklerine karşı sabret; güçlü, (Allah’a) çok yönelen kulumuz Davud’u hatırla!"},{"n":18,"t":"Biz dağları (onun) hizmetine vermiştik. Akşam ve kuşluk vakti onunla birlikte tesbih ederler (yüceltirlerdi)."},{"n":19,"t":"Toplanıp gelen kuşları da (emrine vermiştik). Hepsi de O’na (Allah’a) çok yönelicilerdi."},{"n":20,"t":"Onun hükümdarlığını güçlendirmiş, ona hikmet (doğru hüküm verme yeteneği) ve güzel konuşabilme (özelliği) vermiştik."},{"n":21,"t":"Mabedin (duvarlarına) tırmanan davacıların haberi sana ulaştı (değil) mi?’"},{"n":22,"t":"Davud’un (yanına) girdiklerinde (Davud) onlardan korkmuştu. Onlar da “Korkma! Biz bir kısmı diğer kısmına haksızlık eden iki davacıyız; aramızda adaletle hükmet! Haksızlık etme; bize doğru yolu göster!” demişlerdi."},{"n":23,"t":"(Davalılardan biri): “Şüphesiz ki bu benim kardeşimdir; onun doksan dokuz koyunu, benim ise tek bir koyunum var. (Durum) böyleyken ‘Onun (bakımını) bana ver!’ dedi ve hitapta bana üstün geldi (beni ikna etti).”"},{"n":24,"t":"(Davud şöyle demişti): “Şüphesiz ki (kardeşin) senin koyununu kendi koyunlarına katmak istemekle sana haksızlık etmiştir. Doğrusu iman edip iyi işler yapanlar hariç –ki böyleleri azdır– ortakların çoğu birbirlerine haksızlık ederler.” Davud kendisini denediğimizi anlamış, Rabbinden bağışlanma dileyerek eğilip boyun eğmiş ve (Allah’a) yönelmişti."},{"n":25,"t":"Biz de bu işte onu bağışlamıştık. Şüphesiz ki yanımızda onun için (özel) bir yakınlık ve güzel bir varış yeri vardır."},{"n":26,"t":"Ey Davud! Biz seni yeryüzünde halife (sorumlu olarak) görevlendirdik. İnsanlar arasında adaletle hükmet! Arzu(n)a uyma; sonra (bu durum) seni Allah’ın yolundan saptırır. Doğrusu Allah’ın yolundan sapanlara, hesap gününü unutmalarına karşılık şiddetli bir azap vardır."},{"n":27,"t":"Göğü, yeri ve ikisi arasındakileri batıl olarak (boş yere) yaratmadık. Bu (iddia), kâfir olanların zannıdır. Ateşi hak eden o kâfir olanların vay hâllerine!"},{"n":28,"t":"Yoksa biz iman edip iyi işler yapanları, yeryüzünde bozgunculuk yapanlar gibi veya muttakîleri (duyarlı olanları) yoldan çıkanlar (ile bir) mi tutacağız!"},{"n":29,"t":"(Bu Kur’an), ayetlerini derinlemesine düşünsünler ve öz akıl sahipleri (gerçeği) hatırlasınlar diye sana indirdiğimiz bereket kaynağı bir kitaptır."},{"n":30,"t":"Davud’a Süleyman’ı vermiştik; o ne güzel bir kuldu; daima (Allah’a) yönelendi."},{"n":31,"t":"Hani akşama doğru kendisine safkan atlar sunulmuştu."},{"n":32,"t":"(Süleyman) “Şüphesiz ki ben Rabbimi hatırlatmaları nedeniyle iyi şeyleri sevmekten hoşlanırım.” demişti. Sonunda onlar (atlar) perdeleninceye (gözden kayboluncaya) kadar (bu durum sürmüştü)."},{"n":33,"t":"(Sonra) “Onları (atları) tekrar bana getirin!” demiş ve ayaklarını ve boyunlarını sıvazlamaya başlamıştı."},{"n":34,"t":"Yemin olsun ki Süleyman’ı imtihan etmiş; tahtına bir ceset bırakmıştık da bir süre sonra (bize) yönelmişti."},{"n":35,"t":"“Rabbim! Beni bağışla; bana, benden sonra kimsenin ulaşamayacağı bir hükümdarlık ver (lütfet)! Şüphesiz ki bolca veren sensin, sen!” demişti."},{"n":36,"t":"Bunun üzerine O’nun (Allah’ın) emriyle istediği yere yumuşakça akan rüzgârı hizmetine vermiştik."},{"n":37,"t":"(Ayrıca), şeytanları yani her tür (maharetli) bina ustalarını ve dalgıçları,"},{"n":38,"t":"Zincirlerle birbirlerine bağlanmış diğerlerini de (hizmetine sunmuştuk)."},{"n":39,"t":"Bütün bu (verdiklerimiz ona) lütfumuzdur. “İster (dilediğine) ver (serbest bırak); ister hesapsız bir şekilde (elinde) tut!” (demiştik)."},{"n":40,"t":"Şüphesiz ki yanımızda onun (Süleyman) için (özel) bir yakınlık ve güzel bir varış yeri vardır."},{"n":41,"t":"Kulumuz Eyüp’ü de hatırla! Hani Rabbine “Doğrusu şeytan bana bir yorgunluk ve eziyet verdi.” diye seslenmişti."},{"n":42,"t":"(Biz de ona) “Ayağını yere vur! İşte hem soğuk yıkanılacak hem de içilecek (soğuk) bir su!” (demiştik)."},{"n":43,"t":"Katımızdan bir merhamet ve öz akıl sahiplerine (gerçeği) hatırla(t)mak için ona hem ailesini hem de onlarla birlikte bir mislini bağışlamıştık."},{"n":44,"t":"(Eyüp’e) “Eline bir demet sap al da onunla vur (yola çık); doğrudan sapma.” (demiştik). Şüphesiz ki Eyüp’ü sabırlı (bir kul) bulmuştuk; o, hep (Allah’a) yönelen ne güzel bir kuldu."},{"n":45,"t":"Güçlü ve öngörü sahibi kullarımızı (yani) İbrahim’i, İshak’ı ve Yakup’u da hatırla!"},{"n":46,"t":"Şüphesiz ki onları ahiret yurdunu hatırlama duygusuyla arı duru bir özellikle saflaştırmıştık."},{"n":47,"t":"Şüphesiz ki onlar katımızda en hayırlı güzide seçkinlerdendirler."},{"n":48,"t":"İsmail’i, Elyesa’yı, Zülkifl’i de hatırla! Hepsi de en hayırlılardandır."},{"n":49,"t":"İşte (Kur’an) bir hatırla(t)madır. Şüphesiz ki muttakîlere (duyarlı olanlara) güzel bir varış yeri vardır."},{"n":50,"t":"50-51 İçlerinde yaslanabilecekleri, her çeşit meyve ve içeceği isteyebilecekleri, kapıları onlar için açılmış durulmaya değer bahçeler (vardır)."},{"n":51,"t":"50-51 İçlerinde yaslanabilecekleri, her çeşit meyve ve içeceği isteyebilecekleri, kapıları onlar için açılmış durulmaya değer bahçeler (vardır)."},{"n":52,"t":"Yanlarında yaşlarına uygun, bakışlarını kendilerine yönelten (eş)ler (bulunacaktır)."},{"n":53,"t":"Hesap günü için size vadedilen budur."},{"n":54,"t":"Şüphesiz ki bu(nlar), bitip tükenmek bilmeyen rızıklarımızdır."},{"n":55,"t":"55-56 (İyilerin durumu) böyleyken, azgınlara da içine girecekleri, çok feci bir yatak olan kötü bir varış yeri, yani cehennem hazırlanmıştır."},{"n":56,"t":"55-56 (İyilerin durumu) böyleyken, azgınlara da içine girecekleri, çok feci bir yatak olan kötü bir varış yeri, yani cehennem hazırlanmıştır."},{"n":57,"t":"57-58 İşte (ceza türleri); kaynar su, irin ve ona benzer daha nicelerinden oluşan (cehennemi) tatsınlar!"},{"n":58,"t":"57-58 İşte (ceza türleri); kaynar su, irin ve ona benzer daha nicelerinden oluşan (cehennemi) tatsınlar!"},{"n":59,"t":"(Melekler, inkârcıların liderlerine) “İşte bunlar, sizin peşinize takılan topluluktur; (bakın işte) rahat yüzü görmeyecekler; onlar mutlaka ateşe gireceklerdir!” (diyeceklerdir)."},{"n":60,"t":"(Saptırılanlar liderlerine) “Asıl siz rahat yüzü görmeyin! Onu (ateşi) bize siz sundunuz! Burası ne kötü bir yerdir!” diyeceklerdir."},{"n":61,"t":"(Saptırılanlar devamla), “Rabbimiz! Bunu önümüze (başımıza) kim getirdiyse onun ateşteki azabını kat kat artır!” diyeceklerdir."},{"n":62,"t":"(Saptıranlar ise) şöyle diyeceklerdir: “Kendilerini dünyadayken kötülerden saydığımız erkekleri (insanları) niçin görmüyoruz?"},{"n":63,"t":"Kendileriyle de alay ediyorduk değil mi? Yoksa gözler onlardan kaydı mı?”"},{"n":64,"t":"İşte cehennem halkının bu tür tartışması şüphesiz bir gerçektir."},{"n":65,"t":"65-66 De ki: “Ben sadece bir uyarıcıyım; tek, ezici güç sahibi, göklerin, yerin ve ikisi arasında bulunanların Rabbi, güçlü, çok bağışlayan Allah’tan başka ilah yoktur.”"},{"n":66,"t":"65-66 De ki: “Ben sadece bir uyarıcıyım; tek, ezici güç sahibi, göklerin, yerin ve ikisi arasında bulunanların Rabbi, güçlü, çok bağışlayan Allah’tan başka ilah yoktur.”"},{"n":67,"t":"67-68 De ki: “Kendisinden yüz çevirip durduğunuz bu (Kur’an), büyük bir haberdir."},{"n":68,"t":"67-68 De ki: “Kendisinden yüz çevirip durduğunuz bu (Kur’an), büyük bir haberdir."},{"n":69,"t":"Onlar konuşup tartışırken benim yüce toplulukta (olup bitenler) hakkında hiçbir bilgim yoktu."},{"n":70,"t":"Bana sadece ‘apaçık bir uyarıcı olduğum’ vahyediliyor.”"},{"n":71,"t":"Hani Rabbin meleklere şöyle demişti: “Ben çamurdan bir insan yaratacağım."},{"n":72,"t":"Ona düzgün şekil verip kendisine rûhumdan üflediğim zaman, onun için (bana) secde edin!”"},{"n":73,"t":"Bütün melekler hemen secde etmişlerdi."},{"n":74,"t":"İblis hariç. Kibirlenmiş ve kâfirlerden olmuştu."},{"n":75,"t":"(Allah) “Ey İblis! İki elimle (kudretimle) yarattığım varlık için (bana) secde etmekten seni engelleyen neydi! Kibirlendin öyle mi; yoksa (haksız yere) büyüklenenlerden mi oldun!” demişti."},{"n":76,"t":"(İblis de) “Ben ondan hayırlıyım (üstünüm). Beni ateşten yarattın; onu çamurdan yarattın.” demişti."},{"n":77,"t":"(Allah) şöyle demişti: “Çık oradan! Şüphesiz ki sen kovuldun."},{"n":78,"t":"Hesap gününe kadar lanetim senin üzerinedir!”"},{"n":79,"t":"(İblis) “Rabbim! İnsanların diriltilecekleri güne kadar bana zaman ver.” demişti."},{"n":80,"t":"80-81 (Allah) “Bilinen vaktin gününe kadar zaman verilenlerdensin.” demişti."},{"n":81,"t":"80-81 (Allah) “Bilinen vaktin gününe kadar zaman verilenlerdensin.” demişti."},{"n":82,"t":"82-83 (İblis) “kudretine yemin olsun ki içlerinden samimi kulların hariç hepsini azdıracağım!” demişti."},{"n":83,"t":"82-83 (İblis) “kudretine yemin olsun ki içlerinden samimi kulların hariç hepsini azdıracağım!” demişti."},{"n":84,"t":"(Allah) şöyle demişti: “İşte bu doğru (samimi kullarımı azdıramazsın). Ben şu gerçeği söylüyorum:"},{"n":85,"t":"Cehennemi seninle ve onlardan (insanlardan) sana uyanlarla dolduracağım.”"},{"n":86,"t":"De ki: “Buna karşılık sizden herhangi bir ücret istemiyorum. Ben asla zorluk çıkartanlardan da değilim.”"},{"n":87,"t":"O (Kur’an) ancak âlemler için bir hatırla(t)madır."},{"n":88,"t":"Haberini bir süre sonra öğreneceksiniz."}],[{"n":1,"t":"(Bu) Kitabın indirilişi, güçlü, doğru hüküm veren Allah’tandır."},{"n":2,"t":"Şüphesiz ki Kitabı sana bir amaç için biz indirdik. Sen de dini O’na özgü kılarak Allah’a kulluk et!"},{"n":3,"t":"Dikkat edin! Arı duru din yalnızca Allah’a aittir. O’nun peşi sıra dostlar edinenler “Onlara, bizi yalnızca Allah’a biraz daha yaklaştırsınlar diye kulluk ediyoruz!” (derler). Şüphesiz ki Allah ayrılığa düştükleri şeylerde aralarında hüküm verecektir. Şüphesiz ki Allah yalancı ve inkârcı kimseyi doğru yola ulaştırmaz."},{"n":4,"t":"Allah çocuk edinmek isteseydi, elbette yarattıklarından dilediğini seçerdi. O yücedir. O tek, ezici güç sahibi olan Allah’tır."},{"n":5,"t":"(Allah) gökleri ve yeri bir amaç ile yarattı. Geceyi gündüzün üzerine bürüyüp örtüyor; gündüzü de gecenin üzerine bürüyüp örtüyor. Güneşi ve ayı emri altına almıştır. (Bunların) her biri belirlenmiş bir süreye kadar akıp gitmektedir. Dikkat edin! O güçlüdür, çok bağışlayandır."},{"n":6,"t":"(Allah) sizi tek bir nefisten (candan/cevherden) yaratmıştır; sonra ondan (o candan/cevherden) eşini de var etmiştir. Sizin için hayvanlardan da sekiz çift indirmiştir (yaratmıştır). Sizi annelerinizin karınlarında üç katlı karanlık içinde aşamalardan geçirerek yaratıyor. İşte bu (yaratıcı), Rabbiniz Allah’tır. Otorite yalnızca O’na aittir. O’ndan başka ilah yoktur. Nasıl oluyor da (gerçeklerden) döndürülüyorsunuz!"},{"n":7,"t":"İnkâr ederseniz, şüphesiz ki Allah size muhtaç değildir. O, kullarının küfrüne razı olmaz. Şükrederseniz sizden bunu kabul eder. Hiçbir (günah) yüklüsü başkasının (günah) yükünü yüklenemez. Sonunda dönüşünüz sadece Rabbinizedir ve O, yaptığınız şeyleri size bildirecektir. Şüphesiz ki O göğüslerin (kalplerin) özünü bilendir."},{"n":8,"t":"İnsana bir sıkıntı gelince Rabbine yönelerek O’na yalvarır. Sonra (Allah) katından ona bir nimet verince, önceden yalvarmış olduğunu unutur. O’nun yolundan saptırmak için Allah’a ortaklar koşar. (İnkâr edene) de ki: “Küfrünle biraz (daha) yaşa! Şüphesiz ki sen ateş halkındansın!”"},{"n":9,"t":"Ahiretten çekinerek ve Rabbinin merhametini umarak geceleyin secde hâlinde ve kıyamda durarak ibadet eden kimse (inkârcı gibi) midir! De ki: “Bilenlerle bilmeyenler hiç bir olur mu!” (Bu gerçeği) sadece öz akıl sahipleri hatırlar."},{"n":10,"t":"De ki: “(Allah şöyle diyor:) Ey inanan kullarım! Rabbinize karşı takvâlı (duyarlı) olun! Bu dünyada güzel davrananlara güzel (karşılık) vardır. Allah’ın arzı (yeryüzü) geniştir. Ancak sabredenlere ödülleri hesapsız verilecektir.”"},{"n":11,"t":"De ki: “Bana, dini O’na özgü kılarak Allah’a kulluk etmem emrolundu."},{"n":12,"t":"Bana müslümanların ilki (öncüsü) olmam emrolundu.”"},{"n":13,"t":"De ki: “Rabbime isyan edersem elbette büyük günün azabından korkarım.”"},{"n":14,"t":"De ki: “Ben dinimi O’na özgü kılarak yalnızca Allah’a ibadet ederim.”"},{"n":15,"t":"Siz de O’nun peşi sıra dilediğinize tapın (bakalım)! De ki: “Şüphesiz ki kaybedenler, kıyamet günü kendilerine ve ailelerine (destekçilerine) yazık edenlerdir. Dikkat edin! Asıl apaçık kayıp işte budur."},{"n":16,"t":"Onların hem üstlerinden ateşten karanlıklar (tabakalar) hem de altlarından (ateş) karanlıkları (tabakaları) olacaktır. İşte Allah kullarını bununla korkutuyor. Ey kullarım! Yalnızca bana karşı takvâlı (duyarlı) olun!"},{"n":17,"t":"Tağut’a (azgınlık edene) kulluk etmekten kaçınıp, Allah’a yönelenlere müjde vardır. (Bu) kullarımı müjdele!"},{"n":18,"t":"Onlar (her) sözü dinler; en güzeline uyarlar. İşte onlar Allah’ın doğru yola ulaştırdığı kişilerdir. Öz akıl sahipleri de işte sadece onlardır."},{"n":19,"t":"Hakkında azap sözü gerçekleşmiş kimse (diğerleri gibi olur mu)! Ateşte olanı sen mi kurtaracaksın!"},{"n":20,"t":"Fakat Rablerine karşı takvâlı (duyarlı) olanlara, Allah’ın vaadi olarak üst üste yapılmış, altlarından ırmaklar akan köşkler vardır. Allah verdiği sözden dönmez."},{"n":21,"t":"Şüphesiz ki Allah’ın, gökten su indirmekte olduğunu görmüyor musun? (Allah) onu (suyu) yerdeki kaynaklara yerleştirir; sonra onunla türlü türlü renklerde ekin çıkarır. Sonra (o ekin) kurur da sararmış olduğunu görürsün. Sonra da onu (ekini) kuru bir kırıntı (çer çöp) yapar. Şüphesiz ki bunda, öz akıl sahipleri için (gerçeği) hatırla(t)ma vardır."},{"n":22,"t":"Allah’ın, göğsünü (kalbini) İslam’a açtığı, kendisi de Rabbinden bir nûr üzere olan kişi (kötü olanlarla bir) olur mu? Allah’ı anmada kalpleri katılaşmış olanlara yazıklar olsun! İşte onlar apaçık bir sapkınlık içindedir."},{"n":23,"t":"Allah sözün en güzelini, müteşâbih (benzeşen anlamlı) ve mesânî (hakikatleri tekrarlanan) bir kitap olarak indirdi. Bu (Kitab)ın etkisiyle Rablerine saygı duyanların tüyleri ürperir. Sonra hem derileri hem de kalpleri Allah’ın zikrine (Kur’an’a ısınıp) yumuşar. İşte bu (Kitap), Allah’ın, dileyeni (layık gördüğünü) kendisiyle doğru yola ulaştırdığı bir rehberdir. Allah kimi de saptırırsa (sapkınlığını onaylarsa) artık ona hiçbir yol gösteren olamaz."},{"n":24,"t":"Kıyamet gününde yüzünü azabın şiddetinden korumaya çalışan kimse, (güvendeki gibi) midir? Zalimlere “(Dünyadayken) kazandıklarınızı tadın!” denir."},{"n":25,"t":"Onlardan öncekiler de yalanlamışlardı ve bilemeyecekleri bir yerden onlara azap gelmişti."},{"n":26,"t":"Allah dünya hayatında onlara rezilliği tattırdı. Ahiret azabı ise elbette çok daha büyüktür. Keşke bilselerdi!"},{"n":27,"t":"Yemin olsun ki biz (gerçeği) hatırlasınlar diye bu Kur’an’da insanlara her türlü örneği verdik."},{"n":28,"t":"Takvâlı (duyarlı) olsunlar diye, pürüzsüz Arapça bir Kur’an olarak (indirdik)."},{"n":29,"t":"Allah çekişip duran birçok ortağın sahip olduğu bir adam ile yalnız bir kişiye bağlı olan bir adamı örnek olarak veriyor. Bu ikisi eşit midir? Hamd (övgü) Allah içindir. Fakat onların çoğu bilmezler."},{"n":30,"t":"Şüphesiz ki sen de öleceksin, onlar da ölecekler."},{"n":31,"t":"Sonra şüphesiz kıyamet günü Rabbinizin huzurunda davalaşacaksınız."},{"n":32,"t":"Allah’a yalan uyduran ve kendisine gelen gerçeği (Kur’an’ı) yalanlayandan daha zalim kim olabilir ki! kâfirler için cehennemde yer mi yok!"},{"n":33,"t":"Gerçeği getiren ve onu doğrulayan(lar) var ya, işte muttakîler (duyarlı olanlar) sadece bunlardır."},{"n":34,"t":"Onlar için Rableri katında diledikleri her şey vardır. (İşte) bu, güzel davrananların ödülüdür."},{"n":35,"t":"Böylece Allah onların (dünyada) yaptıkları en kötü şeyleri bile örtecek, ödüllerini yapmış olduklarının en güzeliyle verecektir."},{"n":36,"t":"Allah kuluna yetmez mi hiç! Seni O’ndan başkalarıyla korkutuyorlar. Allah kimi saptırırsa (sapkınlığını onaylarsa) artık ona hiçbir yol gösteren olamaz."},{"n":37,"t":"Allah kimi de doğru yola ulaştırırsa, artık onu da saptırabilecek kimse yoktur. Allah güçlü, intikam sahibi değil midir?"},{"n":38,"t":"Onlara “Gökleri ve yeri kim yarattı?” diye sorsan, mutlaka “Allah” derler. De ki: “(Şunu) düşünün: Allah bana bir zarar vermek isterse, onlar (putlar) O’nun verdiği zararı açıp (giderebilir) mi? Veya (Allah) bana bir merhamet dilerse onlar O’nun merhametini tutup (önleyebilirler) mi?” De ki: “Bana Allah yeter. Güvenenler de yalnızca O’na güvenirler!”"},{"n":39,"t":"39-40 De ki: “Ey kavmim! Bulunduğunuz yerde (elinizden geleni) yapın! Şüphesiz ki ben de (görevimi) yapacağım!” Kendisini rezil edecek azabın kime geleceğini ve kalıcı bir azabın kime konacağını ileride bileceksiniz."},{"n":40,"t":"39-40 De ki: “Ey kavmim! Bulunduğunuz yerde (elinizden geleni) yapın! Şüphesiz ki ben de (görevimi) yapacağım!” Kendisini rezil edecek azabın kime geleceğini ve kalıcı bir azabın kime konacağını ileride bileceksiniz."},{"n":41,"t":"Şüphesiz ki Kitabı sana, insanlarla ilgili bir amaç için biz indirdik. Artık kim doğru yolu seçerse, (bu) kendi (iyiliği) içindir. Kim de saparsa, sadece kendi aleyhine sapmış olur. Sen onlar üzerinde asla vekil değilsin."},{"n":42,"t":"Allah (nefislerin) ölüm zamanı gelince, ölmeyenin de uykusundayken nefisleri vefat ettirir. Ölümüne hükmettiğini (kişinin ruhunu katında) tutar; diğerini ise (ölüm zamanı gelmeyeni ise) belirlenmiş bir süreye kadar (kişiye) gönderir. Şüphesiz ki bunda düşünen bir toplum için dersler vardır."},{"n":43,"t":"Yoksa onlar Allah’ın peşi sıra (başkalarını) şefaatçiler mi edindiler! De ki: “Onlar hiçbir şeye güç yetiremezlerse ve akıl erdiremezlerse de mi?”"},{"n":44,"t":"De ki: “Şefaat tamamen ve yalnızca Allah’a aittir. Göklerin ve yerin otoritesi yalnızca O’na aittir. Sonra da yalnızca O’na döndürüleceksiniz.”"},{"n":45,"t":"Allah tek olarak anıldığı zaman, ahirete inanmayanların kalpleri daralır. O’nun peşi sıra başkaları anıldığı zaman hemen sevinirler."},{"n":46,"t":"De ki: “Ey gökleri ve yeri yoktan yaratan, görünmeyeni de görüneni de bilen Allah’ım! Kullarının arasında, ayrılığa düştükleri şeyin hükmünü ancak sen vereceksin.”"},{"n":47,"t":"Yeryüzünde ne varsa hepsi ve onunla birlikte bir benzeri daha o zalimlerin olsaydı, kıyamet gününde azabın kötülüğünden (kurtulmak için) elbette onu fidye verirlerdi (feda ederlerdi). (O gün) onlar için, Allah tarafından hiç hesaba katmadıkları şeyler ortaya çıkmış (olacak)tır."},{"n":48,"t":"Onların kazandıkları kötülükler (o gün) açığa çıkmış, alay ettikleri şey kendilerini kuşatmış (olacak)tır."},{"n":49,"t":"İnsana bir zarar dokunduğu zaman bize yalvarır. Sonra, kendisine tarafımızdan bir nimet verdiğimizde “Bu, bana ancak bilgi(m) sayesinde verilmiştir” der. Hayır! O bir imtihandır fakat çoğu bilmez."},{"n":50,"t":"Bunu onlardan öncekiler de elbette söylemişti ama kazandıkları şeyler onlara yarar sağlamamıştı."},{"n":51,"t":"Kazandıklarının kötü sonuçları onları yakalamıştı. Bunlardan da (müşriklerden de) haksızlık edenlerin işledikleri kötülükler başlarına gelecektir. (Allah’ı) asla aciz bırakamazlar."},{"n":52,"t":"Bilmediler mi ki Allah rızkı dilediğine (layık olana) açarak (bol) da verebilir; kısarak (dar) da. Şüphesiz ki bunda inanan bir toplum için dersler vardır."},{"n":53,"t":"De ki: “(Allah şöyle buyuruyor:) Ey kendi nefisleri aleyhine haddi aşan kullarım! Allah’ın merhametinden ümit kesmeyin! Şüphesiz ki Allah bütün günahları bağışlayabilir. Şüphesiz ki O çok bağışlayandır, çok merhametlidir."},{"n":54,"t":"Size azap gelip çatmadan önce Rabbinize dönün ve O’na teslim olun; sonra size yardım edilmez."},{"n":55,"t":"Siz farkında olmadan, ansızın başınıza azap gelmesinden önce Rabbinizden size indirilenin en güzeline (Kur’an’a) uyun!"},{"n":56,"t":"Herhangi bir kişinin ‘Allah’ın katında (O’nun buyruklarını) umursamamamdan dolayı ah, yazıklar olsun (bana)! Doğrusu ben alay edenlerdendim!’ demesi(nden önce Kur’an’a uyun)!"},{"n":57,"t":"Veya ‘Allah beni doğru yola ulaştırsaydı, elbette muttakîlerden (duyarlı olanlardan) olurdum!’ demesi(nden önce Kur’an’a uyun)!"},{"n":58,"t":"Veya azabı gördüğünde ‘Keşke benim için bir kez (dünyaya dönme) imkânı olsa da güzel davrananlardan olsam!’ demesi(nden önce Kur’an’a uyun)!”"},{"n":59,"t":"(Allah, bu isteği dile getirenlere şöyle diyecektir): “Hayır! Ayetlerim elbette sana gelmişti de sen onları yalanlamış, kibirlenmiş ve kâfirlerden olmuştun.”"},{"n":60,"t":"Allah hakkında yalan söyleyenlerin kıyamet gününde yüzlerinin kapkara olduğunu görürsün. Kibirlenenler için cehennemde yer mi yok!"},{"n":61,"t":"Allah takvâ (duyarlılık) sahiplerini başarıları sebebiyle kurtaracaktır. Onlara hiçbir kötülük dokunmaz. Onlar üzülmeyecek de."},{"n":62,"t":"Allah her şeyin yaratıcısıdır. O her şeye vekildir (güven kaynağıdır)."},{"n":63,"t":"Göklerin ve yerin anahtarları yalnızca O’na aittir. Allah’ın ayetlerini inkâr edenler var ya, işte onlar kaybedenlerin ta kendileridir."},{"n":64,"t":"De ki: “Ey cahiller! Bana Allah’tan başkasına kulluk etmemi mi emrediyorsunuz?”"},{"n":65,"t":"Yemin olsun ki sana da senden öncekilere de şöyle vahyolunmuştur: Şüphesiz ki (Allah’a) ortak koşarsan, işlerin elbette boşa gider ve elbette kaybedenlerden olursun!"},{"n":66,"t":"Hayır! Yalnızca Allah’a kulluk et ve şükredenlerden ol!"},{"n":67,"t":"(İnkârcılar) Allah’ı gerektiği gibi tanımadılar. Kıyamet günü bütün yer, O’nun yetkisindedir. Gökler de O’nun sağ eliyle (kudretiyle) dürülmüş (olacaktır). O, onların ortak koştuklarından yüce ve uzaktır."},{"n":68,"t":"Sûr’a üflenmiş (olacak) ve –Allah’ın diledikleri hariç– göklerde ve yerde bulunanlar bayılacaktır. Sonra ona bir daha üflenince, bir de bakarsın ki onlar ayağa kalkmış bakıyorlar!"},{"n":69,"t":"Yeryüzü, Rabbinin nuru ile aydınlanacaktır. Kitap (ortaya) konulacak, peygamberler ve şahitler getirilecek, aralarında adaletle hüküm verilecek, kendilerine haksızlık edilmeyecektir."},{"n":70,"t":"(Dünyada) ne yaptıysa herkese karşılığı tastamam verilecektir. O, onların yaptıklarını çok iyi bilendir."},{"n":71,"t":"Kâfir olanlar grup grup cehenneme sevk edilecektir. Sonunda oraya geldikleri zaman kapıları açılacak ve bekçileri onlara “Size, içinizden Rabbinizin ayetlerini tilavet eden (okuyup aktaran) ve bugününüzle karşılaşacağınızı uyaran elçiler gelmemiş miydi?” diyecektir. Onlar “Evet (gelmişti)!” diyecekler ancak azap sözü kâfirler üzerine hak olmuştur."},{"n":72,"t":"Onlara “İçinde ebedî kalıcılar olarak cehennemin kapılarından girin!” denecektir. Kibirlenenlerin yeri ne kötüdür!"},{"n":73,"t":"Rablerine karşı takvâlı (duyarlı) olanlar da grup grup cennete sevk edilecektir. Sonunda oraya geldikleri zaman kapıları zaten açılmış durumdadır ve bekçileri onlara “Selam size! Tertemiz geldiniz. Artık ebedî kalmak üzere girin oraya!” diyecektir."},{"n":74,"t":"Onlar da “Bize verdiği sözde duran ve bizi dilediğimiz yerinde yerleş(ip otura)cağımız bu cennet yurduna mirasçı kılan Allah’a hamdolsun! İyi işler yapanların ödülü ne güzelmiş!” diyecektir."},{"n":75,"t":"(O gün) meleklerin, Rablerine hamd (övgü) ile tesbih ederek (yücelterek) arşın etrafını çevrelemiş olduklarını görürsün. Aralarında adaletle hükmedilmiş ve “Hamd, âlemlerin Rabbi olan Allah içindir.” denecektir."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"(Bu) Kitabın indirilişi, güçlü, bilen Allah katındandır."},{"n":3,"t":"O, günahı bağışlayan, tevbeyi kabul eden, azabı şiddetli olandır, lütuf sahibidir. O’ndan başka ilah yoktur; dönüş de yalnızca O’nadır."},{"n":4,"t":"Kâfir olanlardan başkası, Allah’ın ayetleri hakkında tartışmaz. Onların diyar diyar dolaşması kesinlikle seni aldatmasın!"},{"n":5,"t":"Onlardan önce Nuh kavmi ve bunlardan sonraki gruplar da (peygamberlerini) yalanlamışlardı. Her ümmet, kendi elçisini yakalamaya azmetmişti. Batıl sayesinde gerçeği iptal etmek için mücadele etmişlerdi. (Bunun üzerine onları) kıskıvrak yakalamıştım. Azabım (bak) nasıl olmuştu!"},{"n":6,"t":"Onların ateş halkı olduklarına dair Rabbinin sözü kâfir olanlar üzerine gerçekleşmiştir."},{"n":7,"t":"Arşı taşıyan ve bir de onun çevresinde bulunanlar (melekler), Rablerini hamd (övgü) ile tesbih ederler (yüceltirler). O’na iman eder ve müminler için şöyle bağışlanma dilerler: “Rabbimiz! Senin merhamet ve ilmin her şeyi kapsamıştır. Tevbe eden ve senin yoluna gidenleri bağışla; onları cehennem azabından koru!"},{"n":8,"t":"Rabbimiz! Onları da atalarından, eşlerinden ve nesillerinden iyi olanları da kendilerine vadettiğin durmaya değer cennetlere koy! Şüphesiz ki güçlü, doğru hüküm veren yalnızca sensin!"},{"n":9,"t":"Onları her türlü kötülüklerden koru! O gün sen kimi kötülüklerden korursan elbette ona merhamet etmişsindir. Asıl büyük kurtuluş işte budur.”"},{"n":10,"t":"Kâfir olanlara (mahşerde) şöyle seslenilecektir: “Allah’ın gazabı, sizin kendinize olan öfkenizden elbette daha büyüktür. Zira imana davet ediliyorken inkâr ediyordunuz.”"},{"n":11,"t":"Onlar “Rabbimiz! Bizi iki kez öldürdün, iki kez dirilttin. Günahlarımızı itiraf ettik. Bir daha (bu ateşten) çıkış yolu var mıdır?” demiş (olacaklar)dır."},{"n":12,"t":"(Onlara şöyle denecektir:) “Tek Allah’a çağrıldığı(nız) zaman inkâr ederdiniz. O’na ortak koşulunca (buna) inanırdınız. Hüküm yüce (ve) büyük olan Allah’a aittir.”"},{"n":13,"t":"Size delillerini gösteren ve sizin için gökten rızık indiren O’dur. Allah’a yönelenden başkası (gerçeği) hatırlamaz."},{"n":14,"t":"Kâfirlerin hoşuna gitmese de dini O’na özgü kılarak Allah’a dua edin!"},{"n":15,"t":"(Allah) dereceleri yükseltendir; arşın sahibidir. Kavuşma günüyle ilgili uyarmak için emri gereği kullarından dilediğine rûhu (Kur’an’ı) indirir."},{"n":16,"t":"O gün onlar meydana çıkacaklar. Onların hiçbir şeyi Allah’a gizli kalmaz. (Onlara:) “Bugün otorite kimindir? Tek, ezici güç sahibi olan Allah’a aittir!” (denecektir)."},{"n":17,"t":"Bugün herkese kazandığının karşılığı verilecektir. Bugün haksızlık yoktur. Şüphesiz ki Allah hesabı hızlı olandır."},{"n":18,"t":"Yaklaşan gün hakkında onları uyar! Çünkü (o anda) dehşet içinde yutkunurken yürekleri ağızlarına gelecektir. Zalimlerin hiçbir dostu ve sözü dinlenir hiçbir şefaatçisi yoktur."},{"n":19,"t":"(Allah) gözlerin (bakışların) hainliğini ve kalplerin gizlediğini bilir."},{"n":20,"t":"Allah adaletle hükmedecektir. O’nun peşi sıra yalvardıkları ise asla hükmedemezler. Şüphesiz ki yalnızca Allah gerçek duyandır, görendir."},{"n":21,"t":"Öncekilerin sonunun nasıl olduğunu görmek için yeryüzünde hiç mi dolaşmadılar? Onlar kuvvet ve yeryüzündeki eserleri yönünden bunlardan daha da üstündüler. (Böyleyken) Allah onları günahları yüzünden yakalamıştı. Onları Allah’(ın gazabın)dan koruyan da olmamıştı."},{"n":22,"t":"Bunun sebebi, elçileri kendilerine apaçık deliller getirdikleri hâlde inkâr etmeleriydi. Allah da onları yakalamıştı. Şüphesiz ki O kuvvetlidir, azabı da şiddetlidir."},{"n":23,"t":"23-24 Yemin olsun ki Musa’yı da ayetlerimizle ve apaçık bir delille Firavun’a, Haman’a ve Karun’a göndermiştik de (onlar “Bu) bir büyücüdür; çok yalancıdır!” demişlerdi."},{"n":24,"t":"23-24 Yemin olsun ki Musa’yı da ayetlerimizle ve apaçık bir delille Firavun’a, Haman’a ve Karun’a göndermiştik de (onlar “Bu) bir büyücüdür; çok yalancıdır!” demişlerdi."},{"n":25,"t":"İşte o (Musa), tarafımızdan kendilerine gerçeği getirince “Onunla birlikte iman edenlerin oğullarını öldürün; kadınlarını ise sağ bırakın!” demişlerdi. (Ama) kâfirlerin tuzağı elbette boşa çıkar."},{"n":26,"t":"Firavun, “Bırakın beni, Musa’yı öldüreyim; (o da) Rabbine yalvarsın! Şüphesiz ki ben onun, dininizi değiştirmesinden veya yeryüzünde bozgunculuk çıkarmasından korkuyorum!” demişti."},{"n":27,"t":"Musa da “Ben hesap gününe inanmayan her kibirliden, benim de Rabbim, sizin de Rabbiniz olana (Allah’a) sığındım.” demişti."},{"n":28,"t":"Firavun ailesinden olup, imanını gizleyen bir mümin adam şöyle demişti: “Siz bir adamı ‘Rabbim Allah’tır!’ diyor diye öldürecek misiniz? (Oysa) o, size Rabbinizden apaçık deliller getirmiştir. O (Musa) yalancı ise yalanı kendi aleyhinedir. Doğru söylüyorsa sizi tehdit ettiği (azab)ın bir kısmı olsun gelip size isabet eder. Şüphesiz ki Allah haddi aşan, yalancı kimseyi doğru yola ulaştırmaz."},{"n":29,"t":"Ey kavmim! Bugün, yeryüzüne hâkim kişiler olarak hükümdarlık sizindir. (Fakat) Allah’ın azabı bize gelip çatarsa bize kim yardım edebilir ki!” Firavun ise “Ben size sadece kendi görüşümü söylüyorum ve yine size ancak doğru yolu gösteriyorum!” demişti."},{"n":30,"t":"İman eden kişi şöyle demişti: “Ey kavmim! Doğrusu ben üzerinize önceki toplulukların günü gibi (bir felaket gelmesinden) korkuyorum."},{"n":31,"t":"Nuh kavminin, Âd ile Semûd (kavimlerinin) ve onlardan sonra gelenlerin durumunun örneği gibi. Allah kullarına haksızlık dilemez."},{"n":32,"t":"Ey kavmim! Şüphesiz ki sizin için o bağrışıp çağrışma gününden korkuyorum."},{"n":33,"t":"O gün arkanıza dönüp kaç(maya çalış)acaksınız. Sizi Allah’tan (azabından) kurtaracak kimse yoktur. Allah kimi saptırırsa artık ona hiçbir yol gösteren olamaz.”"},{"n":34,"t":"Yemin olsun ki (Musa’dan) önce Yusuf da size apaçık deliller getirmişti; onun size getirdiği şeyler hakkında şüphe edip durmuştunuz. Sonunda o vefat edince “Allah ondan sonra asla elçi göndermez!” demiştiniz. İşte Allah aşırı giden (bütün) şüphecileri böyle sapkınlıkta bırakır."},{"n":35,"t":"Kendilerine gelmiş hiçbir delil olmadığı hâlde Allah’ın ayetleri hakkında mücadele edenler, gerek Allah katında, gerekse iman edenler katında büyük bir öfkeyle karşılanır. Allah her zorba kibirlinin kalbini işte böyle mühürler."},{"n":36,"t":"Firavun “Ey Haman, bana yüksek bir kule yap; belki sebeplere (yollara) ulaşırım."},{"n":37,"t":"Yani göklerin sebeplerine (yollarına ulaşırım). (Böylece belki) Musa’nın ilahına ulaşırım; şüphesiz ki ben onu (Musa’yı) yalancı sanıyorum!” demişti. Böylece Firavun’a, yaptığı kötü iş süslü gösterilmiş ve yoldan saptırılmıştı. (Zaten) Firavun’un tuzağı elbette yıkımdadır (kayıptadır)."},{"n":38,"t":"İman eden kişi şöyle demişti: “Ey kavmim! Siz bana uyun ki ben de size doğru yolu göstereyim."},{"n":39,"t":"Ey kavmim! Dünya hayatı, geçici (bir eğlence)den ibarettir. Ahiret(e gelince), işte kalınacak yurt orasıdır."},{"n":40,"t":"Kim herhangi bir kötülük işlerse, kendisine sadece o kadar karşılık verilecektir. Erkek veya kadın kim mümin olarak iyi iş yaparsa işte onlar cennete gireceklerdir; orada kendilerine hesapsız rızık verilecektir."},{"n":41,"t":"Ey kavmim! Siz beni ateşe çağırıyorken ben sizi kurtuluşa çağırıyorum."},{"n":42,"t":"Siz beni, Allah’ı inkâr etmeye ve hakkında hiçbir bilgim olmayan şeyleri O’na ortak koşmaya çağırıyorsunuz. Ben ise sizi, güçlü ve çok bağışlayan olan (Allah)’a davet ediyorum."},{"n":43,"t":"Gerçek şu ki sizin beni davet ettiğiniz şeyin, dünyada da ahirette de davete değer bir tarafı yoktur. Şüphesiz ki dönüşümüz Allah’adır; aşırı gidenler de elbette ateş halkının kendileridir."},{"n":44,"t":"Size söylediklerimi ileride hatırlayacaksınız. Ben işimi Allah’a havale ediyorum. Şüphesiz ki Allah kulları görendir.”"},{"n":45,"t":"Sonunda Allah kurdukları tuzakların kötülüklerinden onu korumuştu. Firavun’un ailesini (destekçilerini) ise kötü azap kuşatmıştı."},{"n":46,"t":"Sabah akşam ateşe sunulurlar. O (Son) Saat gerçekleştiğinde “Firavun’un ailesini (destekçilerini) azabın en şiddetlisine koyun!” (denecektir)."},{"n":47,"t":"(Kâfirler) ateşin içinde birbirleriyle çekişirlerken zayıf olanlar, (saptıran) kibirlilere “Şüphesiz ki biz size uymuştuk. Şimdi ateşin birazını bizden savabilir misiniz?” diyecekler."},{"n":48,"t":"Kibirliler ise “Doğrusu hepimiz bunun içindeyiz. Şüphesiz ki Allah kulları arasında hükmü vermiştir.” diyeceklerdir."},{"n":49,"t":"Ateşte bulunanlar, cehennem bekçilerine “Rabbinize dua edin de bizden bir gün bile olsa azabı hafifletsin!” diyeceklerdir."},{"n":50,"t":"(Cehennemin bekçileri) “Size elçileriniz apaçık deliller getirmediler mi?” diyecekler. Onlar da “Evet (getirdiler)!” cevabını verecekler. (Bekçiler ise) “(Öyleyse) kendiniz yalvarın! (Gerçi) kâfirlerin yalvarması sadece boşunadır.” diyeceklerdir."},{"n":51,"t":"Şüphesiz ki biz elçilerimize ve iman edenlere hem dünya hayatında hem de şahitlerin (şahitliğe) duracakları günde yardım edeceğiz."},{"n":52,"t":"O gün zalimlere, özür dilemeleri hiçbir yarar sağlamayacaktır. Lanet de onlar içindir; kötü yurt (cehennem) de onlar içindir!"},{"n":53,"t":"53-54 Yemin olsun ki biz Musa’ya hidayeti vermiş ve İsrailoğullarına da o Kitabı öz akıl sahipleri için bir rehber ve (gerçeği) hatırlatan bir (öğüt) olarak miras bırakmıştık."},{"n":54,"t":"53-54 Yemin olsun ki biz Musa’ya hidayeti vermiş ve İsrailoğullarına da o Kitabı öz akıl sahipleri için bir rehber ve (gerçeği) hatırlatan bir (öğüt) olarak miras bırakmıştık."},{"n":55,"t":"Sabret! Şüphesiz ki Allah’ın vaadi gerçektir. Günahının bağışlanmasını iste! Akşam sabah Rabbini hamd (övgü) ile tesbih et (yücelt)!"},{"n":56,"t":"Şüphesiz ki kendilerine gelmiş hiçbir delil olmadığı hâlde Allah’ın ayetleri hakkında mücadele edenler var ya, onların göğüslerinde (kalplerinde), asla ulaşamayacakları bir büyüklük hevesinden başka bir şey yoktur. Sen Allah’a sığın! Şüphesiz ki -O’dur O- duyan; gören."},{"n":57,"t":"Elbette göklerin ve yerin yaratılması, insanların (yeniden) yaratılmasından daha büyüktür. Fakat insanların çoğu bilmezler."},{"n":58,"t":"Körle gören, iman edip iyi işler yapanlarla kötülük yapan bir olmaz. Ne kadar da azınız (gerçeği) hatırlıyor!"},{"n":59,"t":"O (Son) Saat, mutlaka gelecektir; bunda hiçbir şüphe yoktur. Fakat insanların çoğu inanmazlar."},{"n":60,"t":"Rabbiniz şöyle demiştir: “Bana dua edin, cevap vereyim. Şüphesiz ki bana ibadeti bırakıp kibirlenenler, ileride aşağılanarak cehenneme gireceklerdir.”"},{"n":61,"t":"Allah, içinde dinlenesiniz diye sizin için geceyi yaratan, (çalışıp kazanmanız için de) gündüzü aydınlık kılandır. Şüphesiz ki Allah insanlara karşı lütufkârdır. Fakat insanların çoğu şükretmezler."},{"n":62,"t":"İşte bu, her şeyin yaratıcısı olan Rabbiniz Allah’tır. O’ndan başka ilah yoktur. Nasıl da (gerçeklerden) döndürülüyorsunuz!"},{"n":63,"t":"Allah’ın ayetlerini inkâr etmiş olanlar, işte (gerçeklerden) böyle döndürülüyorlardı."},{"n":64,"t":"Yeri sizin için yerleşim alanı, göğü de bir bina kılan, size şekil verip de şeklinizi güzel yapan ve sizi temiz (helal) besinlerle rızıklandıran Allah’tır. İşte Rabbiniz Allah budur. Âlemlerin Rabbi Allah ne yücedir!"},{"n":65,"t":"O, daima diridir, O’ndan başka ilah yoktur. Dini O’na özgü kılarak O’na dua edin! Hamd (övgü) âlemlerin Rabbi Allah içindir."},{"n":66,"t":"De ki: “Bana Rabbimden apaçık deliller geldiğinde (de) Allah’ın peşi sıra yalvardıklarınıza tapmam bana yasaklandı ve bana ‘Âlemlerin Rabbine teslim olmam’ emredildi.”"},{"n":67,"t":"Sizi (önce) topraktan, sonra nutfeden (zigottan), sonra ‘alakadan (embriyodan) yaratan, sonra sizi bebek olarak (ana rahminden) çıkaran, sonra sizi yetişkinlik çağınıza ulaşmanız, ardından da ihtiyarlamanız için (yaşatan) O’dur. İçinizden daha önce vefat ettirilenler de vardır ve belirli bir vakte ulaşmanız için (sizi yaşatan da O’dur). Umulur ki akıl edersiniz."},{"n":68,"t":"O diriltendir, öldürendir. Bir işe hükmettiği zaman ona sadece “Ol!” der, o da hemen olmaya başlar."},{"n":69,"t":"Allah’ın ayetleri hakkında tartışanları görmedin mi? Nasıl da (gerçeklerden) uzaklaştırılıyorlar!"},{"n":70,"t":"Onlar, Kitabı (Kur’an’ı) ve elçilerimize gönderdiklerimizi yalanlayanlardır. İleride (gerçeği) bilecekler!"},{"n":71,"t":"71-72 O zaman boyunlarında demir halkalar ve zincirler olduğu hâlde kaynar suya sürüklenecekler; sonra da ateşte yakılacaklardır."},{"n":72,"t":"71-72 O zaman boyunlarında demir halkalar ve zincirler olduğu hâlde kaynar suya sürüklenecekler; sonra da ateşte yakılacaklardır."},{"n":73,"t":"73-74 Sonra onlara “Allah’ın peşi sıra ortak koştuklarınız nerede?” denecektir. Onlar da “Bizden kayboldular; zaten biz önceleri hiçbir şeye yalvarmıyorduk!” diyecekler. İşte böylece Allah o kâfirleri saptırır (sapkınlıkta bırakır)."},{"n":74,"t":"73-74 Sonra onlara “Allah’ın peşi sıra ortak koştuklarınız nerede?” denecektir. Onlar da “Bizden kayboldular; zaten biz önceleri hiçbir şeye yalvarmıyorduk!” diyecekler. İşte böylece Allah o kâfirleri saptırır (sapkınlıkta bırakır)."},{"n":75,"t":"Bu, sizin yeryüzünde haksız olarak şımarmanız ve aşırı derecede sevinip kibirlenmenizden ötürüdür."},{"n":76,"t":"(Şöyle denecektir): “İçinde ebedî kalıcılar olarak cehennemin kapılarından girin!” Kibirlenenlerin yeri ne kötüdür!"},{"n":77,"t":"Sabret! Şüphesiz ki Allah’ın vaadi gerçektir. Onlara vadettiğimiz (azabın) bir kısmını sana gösteririz veya seni daha önce vefat ettiririz. Sadece bize döndürüleceklerdir."},{"n":78,"t":"Yemin olsun ki senden önce de elçiler göndermiştik. Onlardan kıssasını sana anlattıklarımız da var; kıssasını sana anlatmadıklarımız da var. Hiçbir elçi, Allah’ın izni olmaksızın herhangi bir ayeti (mucizeyi) getiremez. Allah’ın (azap) emri gelince de hüküm verilmiş (olur); batılı seçenler orada kaybetmiş (olacak)lardır."},{"n":79,"t":"Bir kısmına binesiniz, bir kısmının (etinden) yiyesiniz diye sizin için hayvanları yaratan Allah’tır."},{"n":80,"t":"Onlarda, sizin için daha nice yararlar vardır. Göğüslerinizdeki (kalplerinizdeki) arzuya onlar(ın) üzerinde ulaşırsınız. Onların ve gemilerin üzerinde taşınırsınız."},{"n":81,"t":"(Allah) size delillerini gösteriyor. Allah’ın ayetlerinden hangisini inkâr edebilirsiniz ki!"},{"n":82,"t":"Kendilerinden öncekilerin sonunun nasıl olduğunu görmek üzere yeryüzünde hiç mi dolaşmadılar? Öncekiler bunlardan daha çoktu, kuvvetçe ve yeryüzündeki eserleri bakımından da daha sağlamdılar. (Fakat) kazandıkları şeyler, onlara asla yarar sağlamamıştır."},{"n":83,"t":"Elçileri onlara apaçık bilgiler getirince, onlar kendilerinde bulunan (eksik) bilgiye güvenmişlerdi. (Buna karşılık) alay ettikleri şey kendilerini kuşatacaktır."},{"n":84,"t":"Ağır azabımızı gördükleri zaman “Tek olan Allah’a inandık ve O’na ortak koştuğumuz şeyleri inkâr ettik.” derler."},{"n":85,"t":"Allah’ın kulları hakkında süregelen kanunu olarak azabımızı gördükleri zaman (o anki) imanları, kendilerine yarar sağlamamıştır. kâfirler, orada kaybetmiş (olacak)lardır."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"(Bu kitabın) indirilişi Rahmân (ve) Rahîm (olan Allah) tarafındandır."},{"n":3,"t":"3-4 (Bu), ayetleri Arapça bir Kur’an olarak açıklanmış, bilen bir toplum için müjdeleyici ve uyarıcı olarak (indirilmiş) bir kitaptır. Fakat onların çoğu yüz çevirdi; artık dinlemezler."},{"n":4,"t":"3-4 (Bu), ayetleri Arapça bir Kur’an olarak açıklanmış, bilen bir toplum için müjdeleyici ve uyarıcı olarak (indirilmiş) bir kitaptır. Fakat onların çoğu yüz çevirdi; artık dinlemezler."},{"n":5,"t":"(İnkârcılar) şöyle demişlerdi: “Bizi çağırdığın şeye karşı kalplerimiz kapalıdır. Kulaklarımızda da bir (s) ağırlık vardır. Bizimle senin aranda bir perde bulunmaktadır. (Sen istediğini) yap; biz de yapanlarız!”"},{"n":6,"t":"De ki: “Ben yalnızca sizin gibi bir insanım. Bana ‘ilahınızın tek bir ilah olduğu’ vahyolunuyor. Artık O’na yönelin; O’ndan bağışlanma dileyin! Ortak koşanların vay hâline!”"},{"n":7,"t":"Onlar zekâtı vermezler; ahireti inkâr edenler de işte onlardır."},{"n":8,"t":"Şüphesiz ki iman edip iyi işler yapanlar için başa kakılmayan (kesintisiz) bir ödül vardır."},{"n":9,"t":"De ki: “Siz yeri iki günde (dönemde) yaratanı inkâr edip O’na ortaklar mı koşuyorsunuz! O, âlemlerin Rabbidir.”"},{"n":10,"t":"O, yere üzerinden ağır baskılar yerleştirmiştir. Orada bereketler yaratmış ve orada tam dört günde (dönemde) isteyenler için eşit gıdalar belirlemiştir."},{"n":11,"t":"Sonra duman hâlinde olan göğe yönelmişti. Ona (göğe) ve yere “İsteyerek veya istemeyerek gelin!” deyince onlar da “İsteyerek geldik!” cevabını vermişlerdi."},{"n":12,"t":"Böylece onları (gökleri) iki günde (dönemde) yedi gök olarak yaratmış ve her göğe görevini vahyetmişti (bildirmişti). Biz yakın göğü kandillerle ve koruma ile (koruyucu güçlerle) süslemiştik. İşte bu güçlü, bilen (Allah)’ın ölçüsüdür."},{"n":13,"t":"Yüz çevirirlerse de ki: “Sizi Âd ve Semûd’un (başına gelen) yıldırım gibi bir yıldırıma (afete) karşı uyarıyorum!”"},{"n":14,"t":"Hani elçiler onlara önlerinden ve arkalarından gelerek “Allah’tan başkasına kulluk etmeyin!” dedikleri zaman, (onlar) “Rabbimiz (peygamber göndermek) isteseydi elbette melekleri gönderirdi. Onun için biz sizinle gönderilen şeyleri inkâr ediyoruz!” demişlerdi."},{"n":15,"t":"Âd kavmine gelince, yeryüzünde haksız yere kibirlenmiş ve “Bizden daha kuvvetli kim var!” demişlerdi. Onlar, kendilerini yaratan Allah’ın, onlardan çok daha kuvvetli olduğunu görmediler mi? Onlar, ayetlerimizi inkâr ediyorlardı."},{"n":16,"t":"(Bu nedenle) biz de onlara dünya hayatında alçaklık azabını tattıralım diye o kara günlerde soğuk bir rüzgâr göndermiştik. Ahiret azabı elbette daha çok rezil edicidir. Onlara yardım da edilmez."},{"n":17,"t":"Semûd’a gelince, onlara doğru yolu göstermiştik ama onlar körlüğü doğru yola tercih etmişlerdi. Böylece yapmakta oldukları kötülükler yüzünden küçük düşürücü azabın yıldırımı onları yakalayıp çarpmıştı."},{"n":18,"t":"İman edip takvâlı (duyarlı) davranmış olanları ise kurtarmıştık."},{"n":19,"t":"O gün Allah’ın düşmanları, ateşe sürülmek üzere bir araya getirileceklerdir."},{"n":20,"t":"Sonunda oraya geldikleri zaman, işitme (duyu)ları, gözleri ve derileri işledikleri şeylerle ilgili olarak onların aleyhine şahitlik edecektir."},{"n":21,"t":"(Kişiler) derilerine “Niçin aleyhimize şahitlik ettiniz?” diyecek, onlar da “Her şeyi konuşturan Allah bizi de konuşturmuştur. İlk kez sizi de O yaratmıştır. Yalnızca O’na döndürüleceksiniz.” diyeceklerdir."},{"n":22,"t":"Siz işitme (duyu)nuzun, gözlerinizin ve derilerinizin aleyhinize şahitlik etmesinden sakınmıyordunuz. Ancak yaptıklarınızdan çoğunu Allah’ın bilmeyeceğini sanıyordunuz."},{"n":23,"t":"Rabbiniz hakkında beslediğiniz işte bu zan var ya, sizi o mahvetti ve kaybedenlerden oldunuz."},{"n":24,"t":"Dayanabilirlerse onların yeri ateştir. (Mahşerde Allah’ı) hoşnut etmek isterlerse istekleri asla kabul edilmeyecektir."},{"n":25,"t":"Biz onlara birtakım arkadaşlar sardırmıştık da onlar, önlerinde ve arkalarında ne varsa hepsini bunlara süslü göstermişlerdi. Kendilerinden önce geçen cinler ve insanlardan oluşan ümmetler hakkında (uygulanacak azap) sözü onlar için de gerçekleşmiştir. Şüphesiz ki onlar kaybedenlerdi."},{"n":26,"t":"Kâfir olanlar, “Bu Kur’an’ı dinlemeyin; (okunurken) onunla ilgili gürültü yapın! Umulur ki galip gelirsiniz!” demişlerdi."},{"n":27,"t":"Kâfir olanlara elbette şiddetli bir azabı tattırmaktayız ve elbette onları yaptıklarının en kötüsüyle cezalandıracağız."},{"n":28,"t":"İşte o Allah düşmanlarının cezası ateştir. Ayetlerimizi inkâr etmelerinin karşılığı olarak orada onlara ebedî kalacakları yurt (cehennem) vardır."},{"n":29,"t":"Kâfir olanlar şöyle diyeceklerdir: “Rabbimiz! Cinlerden ve insanlardan bizi saptıranları bize göster de aşağılanmışlardan olsunlar diye onları ayaklarımızın altına alalım!”"},{"n":30,"t":"Şüphesiz ki “Rabbimiz Allah’tır.” deyip sonra doğru yolda olanlara melekler “Korkmayın, üzülmeyin, size vadedilen cennetle sevinin!” (diyerek) inerler."},{"n":31,"t":"31-32 (Melekler şöyle derler): “Biz dünya hayatında da ahirette de sizin dostlarınızız. Orada, çok bağışlayan, çok merhametli olan (Allah)’tan bir ikram olarak sizin için canlarınızın çektiği her şey vardır ve istediğiniz her şey orada sizin için (hazırlanmış olacak)tır.”"},{"n":32,"t":"31-32 (Melekler şöyle derler): “Biz dünya hayatında da ahirette de sizin dostlarınızız. Orada, çok bağışlayan, çok merhametli olan (Allah)’tan bir ikram olarak sizin için canlarınızın çektiği her şey vardır ve istediğiniz her şey orada sizin için (hazırlanmış olacak)tır.”"},{"n":33,"t":"Allah’a davet eden, iyi iş(ler) yapan ve “Ben müslümanlardanım!” diyenden daha güzel sözlü kim olabilir ki!"},{"n":34,"t":"İyilikle kötülük bir olmaz. Sen (kötülüğü) en güzel şekilde sav! Bir de bakarsın ki seninle arasında düşmanlık bulunan kimse sanki sımsıcak bir dost olur."},{"n":35,"t":"Buna ancak sabredenler kavuşturulur; buna ancak (hayırdan) büyük payı olan kimse kavuşturulur."},{"n":36,"t":"Sana şeytandan bir kışkırtma gelirse hemen Allah’a sığın! Şüphesiz ki yalnızca O duyandır, bilendir."},{"n":37,"t":"Gece ve gündüz, güneş ve ay O’nun delillerindendir. Güneşe de aya da secde etmeyin! Yalnızca O’na (Allah’a) ibadet ediyorsanız, (bilin ki) onları da yaratan Allah’a secde edin!"},{"n":38,"t":"İnsanlar kibirlenirlenirse (bilsinler ki) Rabbinin yanında bulunan (melekler), hiç bıkmadan gece gündüz O’nu tesbih ederler (yüceltirler)."},{"n":39,"t":"Yeri boynu bükük (çorak) görmen de O’nun delillerindendir. Biz onun üzerine suyu indirdiğimiz zaman bir de bakarsın ki kıpırdayıp kabarır. Onu (toprağı) dirilten (Allah) elbette ölüleri de diriltendir. Şüphesiz ki O her şeye gücü yetendir."},{"n":40,"t":"Ayetlerimiz hakkında eğriliğe sapanlar bize gizli kalmazlar. Kıyamet günü ateşin içine atılacak olan mı hayırlıdır; yoksa (huzurumuza) güvenle gelecek olan mı? Dilediğinizi yapın! Şüphesiz ki O yaptıklarınızı görendir."},{"n":41,"t":"Şüphesiz ki kendilerine zikr (Kur’an) geldiğinde onu inkâr edenler (kayıptadır). Şüphesiz ki o yüce bir kitaptır."},{"n":42,"t":"Ona önünden de arkasından da batıl gelemez. O doğru hüküm veren, övgüye layık olan (Allah)’tan indirilmedir."},{"n":43,"t":"Sana söylenmekte olan, senden önceki elçilere söylenmiş olandan başka bir şey değildir. Şüphesiz ki senin Rabbin hem bağışlama sahibidir hem de elem verici bir azabın sahibidir."},{"n":44,"t":"Biz onu yabancı dilde bir Kur’an yapsaydık “Ayetleri açıklanmalı değil miydi? Arap’a yabancı dilden (kitap) olur mu?” derlerdi. De ki: “O, inananlar için doğru yolu gösteren bir rehber ve şifadır. İnanmayanlara gelince, onların kulaklarında bir (s) ağırlık vardır ve o (Kur’an) onlara kapalıdır. (Sanki) onlara uzak bir yerden sesleniliyor!”"},{"n":45,"t":"Yemin olsun ki biz Musa’ya da Kitabı vermiştik fakat onda anlaşmazlığa düşülmüştü. Rabbinden bir söz geçmemiş olsaydı elbette aralarında (hemen) hüküm verilirdi. Şüphesiz ki onlar (Mekkeliler) de ondan (Kur’an’dan) kuşkulandıran bir şüphe içindedir."},{"n":46,"t":"Kim iyi bir iş yaparsa (bu) kendi lehinedir. Kim de kötülük yaparsa kendi aleyhinedir. Rabbin kullara asla haksızlık edici değildir."},{"n":47,"t":"O (Son) Saat’in bilgisi, yalnızca O’na bırakılır (O’na aittir). O’nun bilgisi dışında hiçbir meyve kabuğunu yarıp çıkamaz; hiçbir dişi gebe kalamaz ve doğuramaz. (Allah) onlara (müşriklere) “Ortaklarım nerede!” diye seslendiği gün “(Buna dair) bizden hiçbir şahit olmadığını sana arz ederiz!” diyeceklerdir."},{"n":48,"t":"(Böylece dünyada) yalvarıp durdukları (şeyler) onlardan uzaklaşmış, kendileri için kaçacak hiçbir yer olmadığını da anlamış (olacak)lardır."},{"n":49,"t":"İnsan, hayır (mal) istemekten bıkmaz. Kendisine bir kötülük dokunursa hemen üzülüp ümitsizliğe düşer."},{"n":50,"t":"Şüphesiz ki kendisine dokunan bir zarardan sonra biz ona bir rahmet (bolluk) tattırırsak “Bu benim hakkımdır; o (Son) Saat’in gerçekleşeceğini de sanmıyorum; Rabbime döndürülmüş olursam bile şüphesiz ki O’nun katında benim için daha güzel (şeyler) vardır!” der. kâfir olanlara (dünyada) yaptıklarını elbette bildireceğiz; onlara ağır azaptan elbette tattıracağız."},{"n":51,"t":"Biz o (nankör) insana nimet verdiğimizde yüz çevirip yan çizer. Kendisine bir şer dokunduğu zaman da uzun yakarışta bulunur."},{"n":52,"t":"De ki: “Bir düşünsenize, o (Kur’an) Allah katından ise siz de onu inkâr etmişseniz, o zaman uzak bir ayrılıkta olandan daha sapkın kim olabilir ki!”"},{"n":53,"t":"Onlara ufuklardaki ve kendi nefislerindeki delillerimizi ileride göstereceğiz ki onun (Kur’an’ın) gerçekliği onlara apaçık olsun. Rabbinin her şeye şahit olması yetmez mi!"},{"n":54,"t":"Dikkat edin! Onlar, Rableriyle karşılaşma konusunda şüphe içindedir. Dikkat edin! Şüphesiz ki O her şeyi kuşatıcıdır."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"Ayn. Sîn. Kâf."},{"n":3,"t":"Güçlü, doğru hüküm veren Allah senden öncekilere (olduğu gibi) sana da işte böyle vahyetmektedir."},{"n":4,"t":"Göklerde ve yerde ne varsa hepsi yalnızca O’na aittir. O yücedir, büyüktür."},{"n":5,"t":"Neredeyse üstlerinden gökler çatlayacak! Melekler de Rablerini hamd (övgü) ile tesbih ediyor (yüceltiyorlar) ve yeryüzündekiler için bağışlanma diliyorlar. Dikkat edin! Yalnızca Allah çok bağışlayandır, çok merhametlidir."},{"n":6,"t":"O’nun peşi sıra dostlar edinenleri Allah daima gözetlemektedir. Sen onlar üzerinde asla vekil (güven kaynağı) değilsin."},{"n":7,"t":"Şehirlerin anasını (Mekkelileri) ve onun çevresindekileri uyarman ve asla şüphe olmayan toplanma günüyle (ilgili) onları uyarman için sana böyle Arapça bir Kur’an vahyettik. (İnsanların) bir bölümü cennette, bir bölümü de çılgın alevli cehennemde (olacak)tır."},{"n":8,"t":"Allah dileseydi onları tek bir ümmet yapardı. Fakat O, dileyeni (layık gördüğünü) rahmetine koyar. Zalimlerin ise hiçbir dostu ve yardımcısı yoktur."},{"n":9,"t":"Yoksa onlar, Allah’ın peşi sıra başka dostlar mı edindiler! (Oysa) Allah -işte O- gerçek dosttur. O ölüleri diriltecektir; O her şeye gücü yetendir."},{"n":10,"t":"Ayrılığa düştüğünüz herhangi bir şeydeki (konunun) hükmü Allah’a aittir. İşte, Rabbim Allah budur. Yalnızca O’na güvendim ve yalnızca O’na yönelirim."},{"n":11,"t":"O, gökleri ve yeri yoktan yaratandır. Size kendinizden eşler, hayvanlardan da (kendilerine) eşler yaratmıştır; bu (düzen)de sizi (çoğaltıp) yaymaktadır. Hiçbir şey, O’nun benzeri gibi bile olamaz. O duyandır, görendir."},{"n":12,"t":"Göklerin ve yerin anahtarları, yalnızca O’nun (katında)dır. (Allah) rızkı dilediğine açarak (bol) da verebilir, kısarak (dar) da. Şüphesiz ki O her şeyi bilendir."},{"n":13,"t":"“Dini ayakta tutun ve onda ayrılığa düşmeyin!” diye Nuh’a tavsiye ettiğini, sana vahyettiğimizi, İbrahim’e, Musa’ya ve İsa’ya tavsiye ettiğimizi (Allah) size de din kıldı. (Fakat) kendilerini çağırdığın bu (din) ortak koşanlara ağır geldi. Allah dilediğini (layık olanı) kendisine (peygamber olarak) seçer ve kendisine yöneleni de doğru yola ulaştırır."},{"n":14,"t":"Kendilerine bilgi geldikten sonra, sadece aralarındaki kıskançlık yüzünden ayrılığa düştüler. Belirli bir süreye kadar Rabbinden bir söz geçmemiş olsaydı, elbette aralarında hüküm verilirdi. Onlardan sonra kitaba vâris kılınanlar (Mekkeliler) de şüphesiz ki ondan (Kur’an’dan) kuşkulandıran bir şüphe içindedir."},{"n":15,"t":"İşte onun için sen davet et ve emrolunduğun gibi doğru ol! Onların heveslerine uyma! De ki: “Ben Allah’ın indirdiği (her) kitaba inandım ve aranızda adaleti gerçekleştirmekle emrolundum. Allah bizim de Rabbimizdir; sizin de Rabbinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz de sizedir. Sizinle bizim aramızda delil (getirmeye gerek) yok. Allah hepimizi bir araya toplayacaktır; dönüş de yalnızca O’nadır."},{"n":16,"t":"Çağrısına (duasına) cevap verildikten sonra, Allah hakkında tartışmaya girenlerin delilleri Rableri katında boştur. Onlara bir gazap vardır ve onlar için şiddetli bir (de) azap vardır."},{"n":17,"t":"Kitabı ve ölçüyü bir amaç ile indiren Allah’tır. Belki de o (Son) Saat çok yakındır. Onu sana bildirecek olan ne olabilir ki!"},{"n":18,"t":"Ona (Son Saat’e) inanmayanlar, onunla ilgili olarak acele ederler. İnananlar ise ondan korkar ve onun gerçek olduğunu bilirler. Dikkat edin! O (Son) Saat hakkında tartışanlar, uzak bir sapkınlık içindedir."},{"n":19,"t":"Allah kullarına cömerttir; dilediğini rızıklandırır. O kuvvetlidir, güçlüdür."},{"n":20,"t":"Kim ahiret kazancını istiyorsa, onun kazancını artırırız. Kim de dünya kazancını istiyorsa ona da ondan (bir şeyler) veririz. Fakat onun ahirette hiçbir payı yoktur."},{"n":21,"t":"Yoksa onların, Allah’ın izin vermediği şeyleri kendilerine dinî bir hüküm olarak belirleyen ortakları mı var! Ayırıcı söz olmasaydı elbette aralarında hüküm verilirdi. Şüphesiz ki zalimlere elem verici bir azap vardır."},{"n":22,"t":"Yaptıkları şeyler başlarına gelirken zalimlerin korkudan titrediklerini göreceksin. İman edip iyi işler yapanlar da cennetlerin bahçelerinde (olacaklar)dır. Rablerinin katında onlara diledikleri her şey vardır. Asıl büyük lütuf işte budur."},{"n":23,"t":"İşte Allah’ın, iman edip iyi işler yapan kullarına müjdelediği ödül budur. De ki: “Ben buna karşılık (Allah’a) yakın olmayı sevmenizden başka sizden herhangi bir ücret istemiyorum.” Kim güzel bir davranışta bulunursa onun (sevabını) güzelce artırırız. Şüphesiz ki Allah çok bağışlayandır, şükrün karşılığını çok verendir."},{"n":24,"t":"Yoksa onlar (senin için) “Allah’a yalan uydurdu” mu diyorlar? Allah dilerse senin de kalbini mühürler(di). Allah batılı yok eder; sözleriyle gerçeği ortaya koyar. Şüphesiz ki O göğüslerin (kalplerin) özünü bilendir."},{"n":25,"t":"O, kullarının tevbesini kabul eden, kötülükleri bağışlayan ve yaptıklarınızı bilendir."},{"n":26,"t":"(Allah) iman edip iyi işler yapanların çağrısına (duasına) cevap verir; lütfundan onların (ödülünü) artırır. Kâfirlere gelince, onlara da şiddetli bir azap vardır."},{"n":27,"t":"Allah kullarına rızkı bolca verseydi yeryüzünde azarlardı. Fakat O, (rızkı) dilediği ölçüde indirir. Şüphesiz ki O, kullarından haberdardır, görendir."},{"n":28,"t":"O, (insanlar) umutlarını kestikten sonra yağmuru indiren, rahmetini her tarafa yayandır. O dosttur, övülmeye layık olandır."},{"n":29,"t":"Gökleri, yeri ve bu ikisinde yaydığı canlıları yaratması da O’nun delillerindendir. O, dilediği zaman bunları bir araya toplamaya da gücü yetendir."},{"n":30,"t":"Başınıza gelen herhangi bir musibet, kendi ellerinizle kazandıklarınız (yaptıklarınız) yüzündendir. (Allah) çoğunu da affeder."},{"n":31,"t":"Yeryüzünde (O’nu) asla aciz bırakamazsınız. Sizin için Allah’a rağmen dost da yardımcı da yoktur."},{"n":32,"t":"Denizde dağlar gibi akıp giden (gemi)ler de O’nun (varlığının) delillerindendir."},{"n":33,"t":"(Allah) dilerse rüzgârı durdurur da (gemiler denizin) üzerinde (öylece) kalakalırlar. Şüphesiz ki bunda, çok sabreden, çok şükreden herkes için dersler vardır."},{"n":34,"t":"Veya (Allah) yaptıkları yüzünden onları helak eder; pek çoğunu da affeder."},{"n":35,"t":"Ayetlerimiz hakkında tartışanlar (var ya), onlar için kaçacak yer yoktur."},{"n":36,"t":"Size verilen şeyler, dünya hayatının geçimliğidir. Allah katında olanlar ise iman edip sadece Rablerine güvenenler için hayırlı ve kalıcı olandır."},{"n":37,"t":"Onlar büyük günahlardan ve çirkinliklerden kaçınır; kızdıkları zaman da bağışlarlar."},{"n":38,"t":"Onlar Rablerinin çağrısına cevap verir ve namazı kılarlar. Onların işleri, aralarında danışma iledir. Kendilerine verdiğimiz rızıktan da infak ederler (verirler)."},{"n":39,"t":"Bir haksızlığa uğradıkları zaman yardımlaşırlar."},{"n":40,"t":"Bir kötülüğün cezası, (en çok) ona denk bir kötülüktür. Kim bağışlar ve barışı sağlarsa, onun ödülü Allah’a aittir. Şüphesiz ki O, zalimleri sevmez."},{"n":41,"t":"Kim haksızlığa uğradıktan sonra hakkını alırsa, onlara herhangi bir yol (ceza) yoktur."},{"n":42,"t":"Ancak insanlara haksızlık edenlere ve yeryüzünde haksız yere taşkınlık edenlere yol (ceza) vardır. İşte onlar için elem verici bir azap vardır."},{"n":43,"t":"Kim sabreder ve bağışlarsa şüphesiz ki bu (davranışı) yapılmaya değer işlerdendir."},{"n":44,"t":"Allah kimi saptırırsa (sapkınlığını onaylarsa), bundan sonra artık onun hiçbir dostu yoktur. Azabı gördüklerinde zalimlerin “Dönecek bir yol var mı?” dediklerini görürsün."},{"n":45,"t":"Ateşe sunulurlarken onların, alçaklıktan (başlarını öne) eğerek göz ucuyla gizli gizli baktıklarını göreceksin. İnananlar da “Şüphesiz ki kaybedenler, kıyamet günü kendilerine ve ailelerine (destekçilerine) yazık edenlerdir.” diyeceklerdir. Dikkat edin! Zalimler, ebedî bir azap içindedir."},{"n":46,"t":"Onların, Allah’ın peşi sıra kendilerine yardım edecek hiçbir dostları yoktur. Allah kimi saptırırsa (sapkınlığını onaylarsa) artık onun için herhangi bir yol yoktur."},{"n":47,"t":"Allah’tan geri döndürülmesi imkânsız olan bir gün gelmeden önce Rabbiniz(in çağrısına) uyun! O gün, sizin için sığınak yoktur; hiçbir şeyi inkâr da edemezsiniz."},{"n":48,"t":"Yüz çevirirlerse, biz seni onların üzerine bekçi olarak göndermedik. Sana düşen (görev), sadece tebliğdir. Biz insana katımızdan bir rahmet (bolluk) tattırdığımız zaman ona sevinir. Elleriyle yaptıkları yüzünden başlarına bir kötülük gelirse, şüphesiz ki insan çok nankördür!"},{"n":49,"t":"Göklerin ve yerin otoritesi, yalnızca Allah’a aittir. Dilediğini yaratır; dilediğine kız çocukları verir; dilediğine de erkek çocukları verir."},{"n":50,"t":"Veya onları hem erkek hem de kız çocukları olmak üzere çift (ikiz) verir. Dilediğini de kısır yapar. Şüphesiz ki O bilendir, gücü yetendir."},{"n":51,"t":"Allah bir insana ancak vahiy yoluyla yani (manevi bir) perde arkasından konuşur yani bir elçi gönderip izniyle ona dilediğini vahyeder. Şüphesiz ki O çok yücedir, doğru hüküm verendir."},{"n":52,"t":"İşte böylece sana da emrimizden bir rûh (Kur’an’ı) vahyettik. Sen o Kitabı ve (esasları belirlenmiş) o imanı bilmezdin. Fakat biz onu kullarımızdan dilediğimizi (layık olanı) kendisiyle doğru yola ulaştırdığımız bir nûr (ışık) kıldık. Şüphesiz ki sen doğru yolu göstermektesin:"},{"n":53,"t":"Yani göklerdekiler ve yerdekiler kendisine ait olan Allah’ın yolunu. Dikkat edin! Bütün işler yalnızca Allah’a döner."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"Apaçık Kitaba yemin olsun ki"},{"n":3,"t":"Şüphesiz biz akıl edesiniz diye onu Arapça bir Kur’an kıldık."},{"n":4,"t":"O, katımızdaki Ana Kitap’tadır; yücedir, doğru hükümler içermektedir."},{"n":5,"t":"Siz haddi aşan kişiler oldunuz diye sizi zikr (Kur’an’la uyarmak)tan vaz mı geçelim?"},{"n":6,"t":"Daha önceki milletlere nice peygamberler göndermiştik."},{"n":7,"t":"Onlar kendilerine gelen her peygamberle mutlaka alay ederlerdi."},{"n":8,"t":"Biz bunlardan daha zorba olanları da helak etmiştik. (Nitekim) öncekilerin örneği geçmiştir."},{"n":9,"t":"Onlara “Gökleri ve yeri kim yarattı?” diye sorsan “Onları elbette güçlü olan, bilen (Allah) yarattı.” derler."},{"n":10,"t":"Yeri size beşik kılan ve doğru gidesiniz diye orada size yollar yaratandır."},{"n":11,"t":"Gökten bir ölçüyle su indiren de O’dur. Biz onunla ölü şehri (toprağı) canlandırırız. Siz de (mahşer için) işte böyle çıkarılacaksınız."},{"n":12,"t":"Bütün çiftleri yaratan, size bineceğiniz gemiler ve hayvanlar var eden de O’dur."},{"n":13,"t":"Böylece onların (hayvanların) sırtına binip (gemilerin) üzerlerine yerleşince, Rabbinizin nimetini anarak şöyle diyesiniz diye: “Bunu bizim hizmetimize veren (Allah) yücedir, (yoksa) biz bunları (hizmetimize) yanaştıramazdık."},{"n":14,"t":"Şüphesiz ki biz sadece Rabbimize döneceğiz.”"},{"n":15,"t":"Onlar (müşrikler), kullarından bir kısmını O’nun (Allah’ın) bir parçası saydılar. Şüphesiz ki (müşrik) insan, apaçık bir nankördür."},{"n":16,"t":"Yoksa (Allah) yarattıklarından kızları kendisine aldı da oğulları size mi seçti (ayırdı)!"},{"n":17,"t":"Onlardan biri, Rahmân’a yakıştırdığı (kız çocuğu)yla müjdelenince öfkelenerek yüzü simsiyah kesilirdi."},{"n":18,"t":"(Şöyle derdi): “Süs içinde yetiştirilip mücadelede açık olmayan (bir kız) mı (bana müjdeleniyor)?”"},{"n":19,"t":"Rahmân’ın kulları olan melekleri dişi saydılar. Onların (meleklerin) yaratılışına şahit mi olmuşlar! Şahitlik (iddia)ları yazılacak ve sorguya çekileceklerdir."},{"n":20,"t":"Dediler ki: “Rahmân dileseydi, biz onlara tapmazdık.” Onların bu konuda hiçbir bilgisi yoktur. Onlar yalandan başka bir şey söylemeyenlerdir."},{"n":21,"t":"Yoksa bundan önce onlara bir kitap verdik de ona mı tutunuyorlar!"},{"n":22,"t":"Hayır! “Şüphesiz ki babalarımızı (böyle) bir din üzerinde bulduk; biz de onların izleri üzere gidenleriz.” dediler."},{"n":23,"t":"Senden önce de hangi şehre uyarıcı göndermişsek oranın şımarıkları mutlaka “Şüphesiz ki babalarımızı (böyle) bir din üzerinde bulduk, biz de onların izlerine uyanlarız.” derlerdi"},{"n":24,"t":"(Elçi) “Ben size, babalarınızı üzerinde bulduğunuz (din)den daha doğrusunu getirmişsem (yine de bana uymaz mısınız?)” deyince, onlar “Doğrusu biz sizinle gönderileni inkâr ediyoruz!” demişlerdi."},{"n":25,"t":"Biz de onlardan intikam almıştık. Bak yalanlayanların sonu nasıl olmuştu!"},{"n":26,"t":"Hani İbrahim, babasına ve kavmine şöyle demişti: “Ben sizin taptıklarınızdan uzağım!"},{"n":27,"t":"Ancak beni yoktan yaratan (Allah) başkadır! Şüphesiz ki O, beni doğru yola ulaştıracaktır.”"},{"n":28,"t":"(Allah) bunu (İbrahim’in bu sözünü), ardından geleceklere devamlı kalacak bir söz olarak bıraktı ki (insanlar gerçeğe) dönsünler."},{"n":29,"t":"Doğrusu, bunları da atalarını da kendilerine gerçek ve onu apaçık (tebliğ eden) bir elçi gelinceye kadar barındırdım."},{"n":30,"t":"Kendilerine o gerçek (vahiy) gelince “Bu bir büyüdür; şüphesiz ki biz onu inkâr edenleriz!” dediler."},{"n":31,"t":"(Devamla:) “Bu Kur’an, iki şehirden bir(er) büyük adama indirilmeli değil miydi?” dediler."},{"n":32,"t":"Rabbinin rahmetini onlar mı paylaştırıyorlar! Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık. Birbirlerine iş gördürmeleri için kimini ötekine derecelerle üstün kıldık. Rabbinin rahmeti onların biriktirdikleri şeylerden hayırlıdır."},{"n":33,"t":"İnsanların küfürde birleşmiş tek bir ümmet olma (tehlikesi) bulunmasaydı, Rahmân’ı inkâr edenlerin evlerinin tavanlarını ve çıkacakları merdivenleri gümüşten yapardık."},{"n":34,"t":"Evlerinin kapılarını ve üzerine yaslanacakları koltukları da (gümüşten yapardık)."},{"n":35,"t":"(Onlara çeşitli) ziynetler (verirdik). Bütün bunlar, sadece dünya hayatının geçimliğidir. Ahiret ise Rabbinin katında muttakîlere (duyarlı olanlara) özeldir."},{"n":36,"t":"Kim Rahmân’ın zikrine (Kur’an’a) karşı kör davranırsa (ondan yüz çevirirse), yanından ayrılmayan bir şeytanı ona sardırırız."},{"n":37,"t":"Şüphesiz ki bu (şeyta)nlar, onları doğru yoldan alıkoyarlar da onlar kendilerinin doğru yolda olduklarını sanırlar."},{"n":38,"t":"(Arkadaşı), bize (huzurumuza) gelince (şeytana) “Ah, keşke benimle senin aranda iki doğular kadar uzaklık olsaydı; ne kötü arkadaşmışsın!” diyecektir."},{"n":39,"t":"Haksızlık ettiğiniz için (pişmanlığınız) bugün size hiçbir yarar sağlamayacaktır. Şüphesiz ki siz azapta ortaksınız."},{"n":40,"t":"Sağırlara sen mi duyuracaksın veya körleri ve apaçık sapkınlıkta olanları sen mi doğru yola ulaştıracaksın!"},{"n":41,"t":"Biz seni onlardan alıp götürsek de şüphesiz ki onlardan intikam alırız."},{"n":42,"t":"Veya onlara vadettiğimiz (azabı) sana gösteririz. Şüphesiz ki bizim onlara gücümüz yeter."},{"n":43,"t":"Sen, sana vahyedilene sımsıkı sarıl! Elbette sen doğru yoldasın."},{"n":44,"t":"Şüphesiz ki o (Kur’an), senin ve kavmin için (gerçeği) hatırlatan (öğüt)tür. İlerde ondan sorgulanacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz elçilerimize (ümmetlerine) sor! “Rahmân’ın peşi sıra tapılacak ilahlar (edinin.” diye) emretmiş miyiz!"},{"n":46,"t":"Yemin olsun ki biz Musa’yı delillerimizle Firavun’a ve yöneticilerine göndermiştik de (Musa) “Ben âlemlerin Rabbinin elçisiyim.” demişti."},{"n":47,"t":"Onlara delillerimizi getirince hemen onlara gülmüşlerdi."},{"n":48,"t":"Onlara gösterdiğimiz her bir delil, kardeşinden (diğerinden) daha büyüktü. (Gerçeğe) dönsünler diye onları azapla yakalamıştık."},{"n":49,"t":"(Musa’ya) şöyle demişlerdi: “Ey büyücü! Sana verdiği söze göre bizim için Rabbine dua et; çünkü biz artık doğru yola gireceğiz.”"},{"n":50,"t":"Onlardan azabı her kaldırdığımızda hemen sözlerinden dönmüşlerdi."},{"n":51,"t":"Firavun, kavmine seslenip şöyle demişti: “Ey kavmim! Mısır’ın hükümdarlığı ve altımdan akıp giden şu ırmaklar benim değil mi? (Hâlâ gerçeği) görmüyor musunuz?"},{"n":52,"t":"Yoksa ben kendisi zayıf ve neredeyse söz anlatamayacak durumda bulunan şu (adam)dan daha hayırlı değil miyim?"},{"n":53,"t":"Ona altından bilezikler verilmeli veya beraberinde melekler gelmeli değil miydi?”"},{"n":54,"t":"(Firavun) kavmini küçümsemiş, onlar da kendisine boyun eğmişti. Şüphesiz ki onlar, yoldan çıkmış bir toplumdu."},{"n":55,"t":"Böylece bizi öfkelendirdiklerinde onlardan intikam almış, hepsini (denizde) boğmuştuk."},{"n":56,"t":"Onları, sonradan gelenlerin geçmişi ve ibretlik örneği kılmıştık."},{"n":57,"t":"Meryem oğlu (İsa, Kur’an’da) bir örnek olarak anlatılınca, kavmin(den bazıları) hemen sevinç çığlıkları atmaya başlamışlardı."},{"n":58,"t":"(Müşrikler) “Bizim ilahlarımız mı hayırlı, yoksa o mu?” demişlerdi. Bunu sana ancak tartışmak için söylemişlerdi. Doğrusu onlar, kavgacı bir toplumdur."},{"n":59,"t":"O (İsa), kendisine nimet verdiğimiz ve İsrailoğullarına örnek (delil) kıldığımız bir kuldan başkası değildir."},{"n":60,"t":"Dileseydik içinizden, yeryüzünde yerinize geçecek melekler yaratırdık."},{"n":61,"t":"Şüphesiz ki o, (Son) Saat için bir bilgidir. Ondan şüphe etmeyin ve bana uyun! Bu doğru yoldur."},{"n":62,"t":"Sakın şeytan, sizi (doğru yoldan) engellemesin! Şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":63,"t":"İsa, apaçık delillerle geldiği zaman şöyle demişti: “Ben size elbette hikmet (doğru hükümler) getirdim ve ayrılığa düştüğünüz şeylerden bir kısmını size elbette açıklayacağım. Allah’a karşı takvâlı (duyarlı) olun ve bana itaat edin!"},{"n":64,"t":"Şüphesiz ki Allah -yalnızca O- benim de Rabbimdir; sizin de Rabbinizdir. O’na kulluk edin! Doğru yol budur.”"},{"n":65,"t":"(Çeşitli) gruplar (İsa hakkında) kendi aralarında ayrılığa düştüler. Elem verici günün azabı nedeniyle zalimlerin vay hâllerine!"},{"n":66,"t":"Onlar, farkında değillerken o (Son) Saat’in kendilerine ansızın gelmesinden başka bir şey mi bekliyorlar!"},{"n":67,"t":"O gün, muttakîler (duyarlı olanlar) dışında dostlar birbirlerine düşman kesilirler."},{"n":68,"t":"Ey kullarım! Bugün size korku yoktur; siz üzülmeyeceksiniz de!"},{"n":69,"t":"Onlar ayetlerimize inanan ve müslüman olan (kullar)dı."},{"n":70,"t":"(Cennetliklere şöyle seslenilecektir:) “Siz ve eşleriniz, ağırlanmış olarak cennete girin!”"},{"n":71,"t":"Onlara altın tepsiler ve kadehler dolaştırılacaktır. Orada, canlarının istediği, gözlerinin hoşlandığı her şey vardır. Siz orada ebedî kalacaksınız."},{"n":72,"t":"(Onlara) “İşte yaptıklarınıza karşılık size miras olarak verilen cennet budur."},{"n":73,"t":"Orada sizin için bol bol meyveler vardır, onlardan yersiniz.” (denecektir)."},{"n":74,"t":"Şüphesiz ki suçlular cehennem azabında ebedî kalıcıdır."},{"n":75,"t":"Azapları hafifletilmeyecektir. Onlar orada (kurtuluştan) ümit kesmişlerdir."},{"n":76,"t":"Biz onlara haksızlık etmedik fakat kendileri haksızlık edenlerdi."},{"n":77,"t":"(Cehennemdekiler:) “Ey (mahşer meleği) Mâlik! Rabbin bizim hakkımızda (ölüm) hükmünü versin!” diye seslenmiş, o (Mâlik) de “Şüphesiz ki siz böyle kalacaksınız!” demiş (olacak)tır."},{"n":78,"t":"Biz size elbette gerçeği getirmiştik fakat çoğunuz gerçek(ler)den hoşlanmıyorsunuz."},{"n":79,"t":"Yoksa (müşrikler) bir işe kesin karar mı verdiler! Doğrusu kararlı olan biziz!"},{"n":80,"t":"Yoksa onlar, sırlarını ve gizli konuşmalarını duymadığımızı mı sanıyorlar? Aksine yanlarındaki elçilerimiz (melekler) yazmaktadır."},{"n":81,"t":"De ki: “Rahmân’ın herhangi bir çocuğu olsa(ydı), elbette (ona) kulluk edenlerin ilki ben olur(d)um!”"},{"n":82,"t":"Göklerin ve yerin Rabbi, arşın da Rabbi olan (Allah) onların yakıştırdıklarından yücedir."},{"n":83,"t":"Sen (şimdilik) bırak da kendilerine vadedilen günlerine kavuşuncaya kadar (boş işlere) dalsınlar, oynasınlar."},{"n":84,"t":"Gökteki ilah da O’dur; yerdeki ilah da. O, doğru hüküm verendir, bilendir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasında bulunan her şeyin otoritesi sadece kendisine ait olan (Allah) ne yücedir! O (Son) Saat’in bilgisi, yalnızca O’nun katındadır. Hepiniz yalnızca O’na döndürüleceksiniz."},{"n":86,"t":"O’nun peşi sıra yalvardıkları varlıklar, şefaat (yetkisine) sahip olamazlar. Ancak bilerek gerçeğe şahitlik eden (melek)ler hariç!"},{"n":87,"t":"Onlara “kendilerini kimin yarattığını.” sorsan elbette “Allah.” derler. Nasıl da (gerçeklerden) döndürülüyorlar!"},{"n":88,"t":"(Peygamber’in:) “Ey Rabbim!” demesine yemin olsun ki şüphesiz ki bunlar iman etmeyen bir toplumdur."},{"n":89,"t":"(Şimdilik) onlardan yüz çevir ve (onlara) “Selam!” de! İleride (gerçeği) bilecekler!"}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"Apaçık Kitaba yemin olsun ki"},{"n":3,"t":"Biz onu (Kur’an’ı) bereketli bir gecede indir(meye başla)dık. Şüphesiz ki biz uyarıcıyız."},{"n":"4-6","t":"Katımızdan (verilen bir) emir olarak doğru hüküm içeren her iş onda (o gecede) ayrıntılı olarak ortaya konulur. Rabbinin merhameti gereği (peygamberler) gönderici olan da elbette biziz. Şüphesiz ki O -evet O- duyandır, bilendir."},{"n":7,"t":"Kesin inananlar olursanız, (bilin ki Allah) göklerin, yerin ve ikisi arasında bulunanların Rabbidir."},{"n":8,"t":"O’ndan başka ilah yoktur. Diriltir de öldürür de. (O) sizin de Rabbinizdir; önceki atalarınızın da Rabbidir."},{"n":9,"t":"Ne var ki onlar şüphe içinde eğlenip duruyorlar."},{"n":10,"t":"(Şimdi) sen göğün açık bir duman getireceği günü gözetle!"},{"n":11,"t":"(O duman) insanları kaplayacaktır. Bu, elem verici bir azaptır."},{"n":12,"t":"(İşte o zaman inkârcılar:) “Rabbimiz! Bizden azabı kaldır! Şüphesiz ki biz (artık) inanıyoruz.” (diyecekler)."},{"n":13,"t":"Bu hatırlamanın onlara ne yararı olabilir ki! Oysa kendilerine (gerçeği ulaştıran) apaçık bir elçi gelmişti."},{"n":14,"t":"Sonra ondan yüz çevirmiş ve “Bu, cinlenmiş, (başkaları tarafından) öğretilmiş biridir!” demişlerdi."},{"n":15,"t":"Azabı kısa bir süre kaldıracağız; (ama) siz (yine eski hâlinize) döneceksiniz."},{"n":16,"t":"(Fakat) biz büyük bir darbe vuracağımız gün şüphesiz ki intikam alıcıyız."},{"n":17,"t":"Yemin olsun ki kendilerinden önce Firavun’un kavmini de imtihan etmiştik. Onlara değerli bir elçi gelmişti."},{"n":18,"t":"(Musa şöyle demişti:) “Allah’ın kullarını bana verin! Şüphesiz ki ben size (gönderilen) güvenilir elçiyim."},{"n":19,"t":"Allah’a büyüklük taslamayın! Şüphesiz ki ben size apaçık bir delil getiriyorum."},{"n":20,"t":"Beni kovmanızdan benim de sizin de Rabbinize sığındım."},{"n":21,"t":"Bana inanmazsanız benden uzaklaşın!”"},{"n":22,"t":"(Musa:) “Bunlar suç işleyen bir toplumdur.” diye Rabbine dua etmişti."},{"n":23,"t":"(Allah şöyle buyurmuştu): “Kullarımı geceleyin yola çıkar! Şüphesiz ki takip edileceksiniz."},{"n":24,"t":"Denizi rahatça terk edip geç! Şüphesiz ki onlar boğulacak bir ordudur.”"},{"n":25,"t":"25-27 Onlar geride bahçeler, (su) kaynakları, ekinler, değerli bir makam ve içinde zevk sürdükleri nimetler bırakmışlardı."},{"n":26,"t":"25-27 Onlar geride bahçeler, (su) kaynakları, ekinler, değerli bir makam ve içinde zevk sürdükleri nimetler bırakmışlardı."},{"n":27,"t":"25-27 Onlar geride bahçeler, (su) kaynakları, ekinler, değerli bir makam ve içinde zevk sürdükleri nimetler bırakmışlardı."},{"n":28,"t":"İşte böylece onları (o nimetleri) başka bir topluma miras bırakmıştık."},{"n":29,"t":"Gök ve yer onların ardından ağlamamıştı; kendilerine zaman da tanınmamıştı."},{"n":30,"t":"30-31 Yemin olsun ki biz, İsrailoğullarını küçük düşürücü o azaptan yani Firavun’dan kurtarmıştık. Şüphesiz ki o, haddini aşanlardan bir zorbaydı."},{"n":31,"t":"30-31 Yemin olsun ki biz, İsrailoğullarını küçük düşürücü o azaptan yani Firavun’dan kurtarmıştık. Şüphesiz ki o, haddini aşanlardan bir zorbaydı."},{"n":32,"t":"Yemin olsun ki biz bir bilgiye göre onları (İsrailoğullarını) âlemlere (kendi zamanlarının inkârcılarına) seçkin kılmıştık."},{"n":33,"t":"Onlara, içinde apaçık bir imtihan bulunan deliller vermiştik."},{"n":34,"t":"Onlar (müşrikler) şöyle diyorlar:"},{"n":35,"t":"“İlk ölümümüzden başka bir şey yoktur. Biz asla diriltilecek de değiliz."},{"n":36,"t":"Doğruysanız atalarımızı getirin (de görelim)!”"},{"n":37,"t":"Bunlar mı daha hayırlı yoksa Tübba‘ kavmi ve onlardan öncekiler mi? Onları yok etmiştik; şüphesiz ki onlar suçluydular."},{"n":38,"t":"Biz gökleri, yeri ve bunlar arasındakileri oyuncular olarak yaratmadık."},{"n":39,"t":"Onları sadece gerçek bir amaçla yarattık. Fakat çoğu (bunu) bilmez."},{"n":40,"t":"Şüphesiz ki ayrılma (mahşer) günü, hepsinin bir arada buluşacağı (gündür)."},{"n":41,"t":"O gün, dostun dosta hiçbir yararı olmaz; kendilerine yardım da edilmez."},{"n":42,"t":"Ancak Allah’ın merhamet ettiği kişiler böyle değildir. Şüphesiz ki O güçlüdür, çok merhametlidir."},{"n":43,"t":"43-46 Şüphesiz ki zakkum ağacı, kaynar suyun kaynamasına benzer şekilde suçluların karınları(n)da erimiş maden gibi kaynayan yemeğidir."},{"n":44,"t":"43-46 Şüphesiz ki zakkum ağacı, kaynar suyun kaynamasına benzer şekilde suçluların karınları(n)da erimiş maden gibi kaynayan yemeğidir."},{"n":45,"t":"43-46 Şüphesiz ki zakkum ağacı, kaynar suyun kaynamasına benzer şekilde suçluların karınları(n)da erimiş maden gibi kaynayan yemeğidir."},{"n":46,"t":"43-46 Şüphesiz ki zakkum ağacı, kaynar suyun kaynamasına benzer şekilde suçluların karınları(n)da erimiş maden gibi kaynayan yemeğidir."},{"n":47,"t":"(Allah meleklere şöyle emredecek): “Tutun onu! Cehennemin ortasına sürükleyin!"},{"n":48,"t":"Sonra başının üzerine kaynar su azabından dökün!”"},{"n":49,"t":"(Cehennemlik kişiye:) “Tat bakalım! Sen -evet sen- (hani) güçlü(ydün); itibarlı(ydın)!"},{"n":50,"t":"İşte bu, şüphelenip durduğunuz şeydir.” (denecektir)."},{"n":51,"t":"51-52 Şüphesiz ki muttakîler (duyarlı olanlar) ise güvenilir bir makamda, bahçelerde ve (su) kaynaklarında (olacaklar)."},{"n":52,"t":"51-52 Şüphesiz ki muttakîler (duyarlı olanlar) ise güvenilir bir makamda, bahçelerde ve (su) kaynaklarında (olacaklar)."},{"n":53,"t":"Karşılıklı oturarak ince ipek ve parlak atlastan giyinecekler."},{"n":54,"t":"İşte böyle! Biz onları, (güzel) gözlü hurilerle (de) eşleştirmiş (olacağ)ız."},{"n":55,"t":"Orada, güven içinde (canlarının istediği) her meyveyi isteyeceklerdir."},{"n":56,"t":"56-57 İlk (tattıkları) ölüm dışında, orada artık ölüm tatmayacaklar. (Allah) onları, Rabbinden bir lütuf olarak cehennem azabından korumuş (olacak)tır. Asıl büyük kurtuluş işte budur."},{"n":57,"t":"56-57 İlk (tattıkları) ölüm dışında, orada artık ölüm tatmayacaklar. (Allah) onları, Rabbinden bir lütuf olarak cehennem azabından korumuş (olacak)tır. Asıl büyük kurtuluş işte budur."},{"n":58,"t":"Biz onu (Kur’an’ı gerçeği) hatırlasınlar diye senin diline kolaylaştırdık."},{"n":59,"t":"Sen (durumu bekleyip) gözetle; şüphesiz ki onlar da gözetlemektedir."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"(Bu) Kitabın indirilişi, güçlü, doğru hüküm veren Allah’tandır."},{"n":3,"t":"Şüphesiz ki göklerde ve yerde inananlar için dersler vardır."},{"n":4,"t":"Sizin yaratılışınızda ve (Allah’ın yeryüzünde) yaydığı canlılarda, kesin bir şekilde inanan bir toplum için dersler vardır."},{"n":5,"t":"Gecenin ve gündüzün değişmesinde, Allah’ın gökten indirmiş olduğu rızıkta (yağmurda) ve ölümünden sonra yeri onunla diriltmesinde, rüzgârları çevirmesinde (estirmesinde) akıl eden toplum için dersler vardır."},{"n":6,"t":"İşte şu(nlar), Allah’ın sana bir amaç ile tilavet etmekte (okuyup aktarmakta) olduğumuz ayetleridir. Allah’tan ve O’nun ayetlerinden sonra hangi söze inanacaklar ki!"},{"n":7,"t":"Yalancı (ve) günahkâr herkesin vay hâline!"},{"n":8,"t":"O, kendisine tilavet edilen (okunup aktarılan) Allah’ın ayetlerini duyar da sonra kibirlenerek sanki hiç onları duymamış gibi (küfründe) direnir. İşte onu elem verici bir azapla müjdele!"},{"n":9,"t":"Ayetlerimizden bir şey öğrendiği zaman onlarla alay eder. İşte onlara küçük düşürücü bir azap vardır."},{"n":10,"t":"Arkalarından da cehennem vardır. Kazandıkları şeyler de Allah’ın peşi sıra edindikleri dostlar da onlara hiçbir yarar sağlamaz. Onlar için büyük azap vardır."},{"n":11,"t":"İşte bu (Kur’an) bir rehberdir. Rablerinin ayetlerini inkâr edenlere gelince, onlara en kötüsünden elem verici bir azap vardır."},{"n":12,"t":"(O) Allah ki emri gereğince içinde gemilerin yüzmesi ve lütfedip verdiği rızkı aramanız için, (ayrıca) şükredesiniz diye denizi sizin hizmetinize vermiştir."},{"n":13,"t":"O, göklerde ve yerde ne varsa hepsini, kendi katından (bir lütuf olarak) size boyun eğdirmiştir. Şüphesiz ki bunda düşünen bir toplum için dersler vardır."},{"n":14,"t":"İman edenlere söyle: Allah’ın (ceza) günlerinin geleceğini ummayanları bağışlasınlar! Sonunda (Allah) her topluma kazandıklarının karşılığını verecektir."},{"n":15,"t":"Kim iyi bir iş yaparsa (bu) kendi lehinedir. Kim de kötülük yaparsa kendi aleyhinedir. Sonra sadece Rabbinize döndürüleceksiniz."},{"n":16,"t":"Yemin olsun ki biz, İsrailoğullarına Kitap, (doğru) hüküm (verme yeteneği) ve peygamberlik vermiştik. Onlara temiz şeylerden rızık vermiş ve onları âlemlere (inançsızlara) üstün kılmıştık."},{"n":17,"t":"İş(lerle) ilgili onlara apaçık deliller vermiştik. (Ancak) onlar, kendilerine ilim geldikten sonra, aralarındaki kıskançlık yüzünden ayrılığa düşmüşlerdi. Şüphesiz ki Rabbin, anlaşmazlığa düştüğü şeyler hakkında kıyamet günü aralarında hükmedecektir."},{"n":18,"t":"Sonra da seni iş (din) konusunda bir şeriat (kanun) sahibi kıldık. Sen ona uy; bilmeyenlerin isteklerine uyma!"},{"n":19,"t":"Şüphesiz ki onlar Allah’tan (gelecek olanda) senden hiçbir şey gideremezler. Şüphesiz ki zalimler birbirlerinin dostlarıdır; Allah da muttakîlerin (duyarlı olanların) dostudur."},{"n":20,"t":"Bu (Kur’an), bütün insanlar için öngörüler, (ayrıca) kesin bir şekilde inanan toplum için bir rehber ve rahmettir."},{"n":21,"t":"Yoksa kötülük işleyenler ölümlerinde ve hayatlarında kendilerini, iman edip iyi işler yapanlarla bir mi tutacağımızı sandılar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"Allah gökleri ve yeri bir amaç ile yaratmıştır. Böylece herkese kazandığının karşılığı verilecektir. Onlara haksızlık edilmeyecektir."},{"n":23,"t":"Arzusunu ilahı edineni ve Allah’ın (kendi katındaki) bir bilgiye göre saptırdığı, işitme (duyu)sunu ve kalbini mühürlediği ve gözünün üstüne de perde çektiği kişiyi gördün mü? Şimdi onu, Allah’a rağmen kim doğru yola ulaştırabilir ki! (Gerçeği) hatırlamayacak mısınız?"},{"n":24,"t":"(İnkârcılar) dediler ki: “Hayat, sadece şu dünya hayatımızdan ibarettir. (Kimimiz) ölürüz, (kimimiz) yaşarız. Bizi, sadece zaman yok eder.” Onların bu konuda hiçbir bilgisi yoktur. Onlar, sadece zanda bulunuyorlar."},{"n":25,"t":"Onlara ayetlerimiz açıkça tilavet edildiğinde (okunup aktarıldığında) “Doğruysanız atalarımızı getirin (de görelim)!” demelerinden başka delilleri yoktur."},{"n":26,"t":"De ki: “Allah sizi diriltecektir (yaşatacaktır), sonra sizi öldürecektir. Sonra sizi kendisinde şüphe olmayan kıyamet günü bir araya toplayacaktır.” Fakat insanların çoğu (bunu) bilmezler."},{"n":27,"t":"Göklerin ve yerin otoritesi yalnızca Allah’a aittir. O (Son) Saat’in gerçekleşeceği gün var ya, batıla sapanlar işte o gün kaybedeceklerdir."},{"n":28,"t":"O gün her ümmeti, diz çökmüş olarak görürsün. Her ümmet, kendi kitabına çağrılacaktır. (Onlara şöyle denecektir:) “Bugün size (dünyada) yaptıklarınızın karşılığı verilmektedir!"},{"n":29,"t":"Bu, size gerçeği söyleyen kitabımızdır.” Şüphesiz ki biz yaptıklarınızı kaydediyorduk."},{"n":30,"t":"İnanıp iyi işler yapanlara gelince, Rableri onları merhametine koyacaktır. Asıl apaçık kurtuluş işte budur."},{"n":31,"t":"Kâfir olanlara gelince, onlara “Ayetlerim size tilavet edilmemiş (okunup aktarılmamış) mıydı? Siz de kibirlenip suçlu bir toplum olmuştunuz (değil mi?)” denecektir."},{"n":32,"t":"(Onlara) “Allah’ın vaadi gerçektir; o (Son) Saat’te de hiçbir şüphe yoktur.” dendiği zaman, “O (Son) Saat’in ne olduğunu bilmiyoruz; (o konuda) sadece zanda bulunuyoruz; asla ikna edilmiş değiliz!” demiştiniz."},{"n":33,"t":"Onların yaptığı kötülükler (o gün) açığa çıkmış, alay etmiş oldukları şey kendilerini kuşatmış (olacak)tır."},{"n":34,"t":"(Onlara) şöyle denecektir: “Siz bugüne kavuşacağınızı unuttuğunuz gibi biz de bugün sizi unutuyoruz. Barınağınız ateştir; sizin için asla yardımcılar da yoktur!”"},{"n":35,"t":"Bunun sebebi şudur: “Siz Allah’ın ayetleriyle alay ettiniz; dünya hayatı sizi aldattı.” Bugün ondan (ateşten) çıkarılmayacaklardır ve onların (Allah’ı) hoşnut etmeleri de istenmeyecektir."},{"n":36,"t":"Hamd (övgü), yalnızca göklerin Rabbi, yerin Rabbi yani bütün âlemlerin Rabbi olan Allah’a aittir."},{"n":37,"t":"Göklerde ve yerde büyüklük yalnızca O’na aittir. O güçlüdür, doğru hüküm verendir."}],[{"n":1,"t":"Hâ. Mîm."},{"n":2,"t":"(Bu) Kitabın indirilişi, güçlü, doğru hüküm veren Allah’tandır."},{"n":3,"t":"Biz gökleri, yeri ve ikisi arasında bulunanları ancak ve ancak bir amaç ile ve belirli bir süre için yarattık. Kâfir olanlar, uyarıldıkları şeylerden yüz çevirmektedir."},{"n":4,"t":"De ki: “Allah’ın peşi sıra yalvardığınız şeyleri (ortaklarınızı) bir düşünsenize!” Yerden neyi yaratmışlar bana gösterin veya göklerle ilgili (onların yaratılışında) onların ortaklığı mı varmış! Doğruysanız bundan önce (size indirilmiş) bir kitap veya bir bilgi kalıntısı (varsa onu) bana getirin!"},{"n":5,"t":"Kıyamet gününe kadar kendisine cevap veremeyecek kişilere Allah’ın peşi sıra yalvarandan daha sapkın kim olabilir ki! (Oysa) onlar, bunların (müşriklerin) yalvarmalarından habersizdir."},{"n":6,"t":"İnsanlar (mahşerde) toplandıkları zaman, (tapanlar) onlara (taptıklarına) düşman kesilir ve kendilerine kulluk ettiklerini inkâr ederler."},{"n":7,"t":"Onlara ayetlerimiz apaçık tilavet edildiği (okunup aktarıldığı) zaman, kendilerine geldiğinde gerçeği inkâr edenler “Bu, apaçık bir büyüdür!” demişlerdi."},{"n":8,"t":"Yoksa “Onu (Muhammed) uydurdu” mu diyorlar! De ki: “Ben onu uydurursam, Allah tarafından bana gelecek şeyi (azabı) savmaya gücünüz yetmez. O, sizin (Kur’an) hakkında yaptığınız taşkınlıkları çok iyi bilendir. Benimle aranızda şahit olarak O (Allah) yeter. O çok bağışlayandır, çok merhametlidir.”"},{"n":9,"t":"De ki: “Ben elçilerden bir türedi (ilk defa gönderilen) değilim. Bana ve size ne yapılacağını da bilmiyorum. Ben, bana vahyolunandan başkasına uymam. Ben ancak apaçık bir uyarıcıyım.”"},{"n":10,"t":"De ki: “Hiç düşündünüz mü; ya bu (Kur’an) Allah katından ise ve siz de onu inkâr etmişseniz, İsrailoğullarından bir şahit de bunun benzerini görüp inandığı hâlde siz yine de kibirlenmişseniz (hâliniz nasıl olacak)?” Şüphesiz ki Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":11,"t":"Kâfir olanlar, iman edenler için şöyle demişlerdi: “Bu iş bir iyilik olsaydı, onlar bizi geçemezlerdi.” Onlar (kâfirler) bununla doğru yola ulaşmayı istemedikleri için “Bu, eski bir iftiradır!” diyeceklerdir."},{"n":12,"t":"Kendisinden (Kur’an’dan) önce, bir önder ve bir rahmet olarak Musa’nın Kitabı vardır. Bu (Kur’an) da haksızlık edenleri uyarmak ve güzel davrananlara müjde olmak üzere Arap diliyle indirilmiş, (önceki vahiyleri) doğrulayıcı bir kitaptır."},{"n":13,"t":"Şüphesiz ki “Rabbimiz Allah’tır.” deyip sonra doğru yolda olanlara korku yoktur ve onlar üzülmeyecek de."},{"n":14,"t":"Onlar cennet halkıdır. (Dünyada) yapmış olduklarına karşılık orada ebedî kalacaklardır."},{"n":15,"t":"Biz insana, ana babasına iyilik etmesini emrettik. Annesi onu zahmetle taşıdı ve zahmetle doğurdu. Taşınması ile sütten kesilmesi otuz aydır. Sonunda insan, yetişkinlik çağına ve kırk yaşına varınca der ki: “Rabbim! Bana ve ana babama verdiğin nimet(ler)e şükretmemde ve razı olacağın iyi iş(ler) yapmamda beni başarılı kıl! Benim için de soyumda iyiliği devam ettir! Ben sana döndüm. Elbette ki ben müslümanlardanım.”"},{"n":16,"t":"İşte, yaptıklarının en iyisini kabul edeceğimiz ve günahlarını bağışlayacağımız bu kişiler cennet halkı arasındadır. Bu, kendilerine verilen doğru bir söz olarak (böyledir)."},{"n":17,"t":"Ana babasına “Öf! Benden önce nice nesiller gelip geçmişken, bana (tekrar) diriltilmemi mi vadediyorsunuz?” diyen kişiye, onlar (ana babası) Allah’ın yardımına sığınarak “Yazıklar olsun sana! Allah’ın vaadinin gerçek olduğuna inan!” dediklerinde o, “Bu, öncekilerin masallarından başka bir şey değildir!” der."},{"n":18,"t":"İşte onlar, kendilerinden önce geçen cinler ve insanlardan oluşan ümmetler hakkında (uygulanacak azap) sözü kendileri için de gerçekleşmiş olanlardır. Şüphesiz ki onlar kaybedenlerdi."},{"n":19,"t":"Herkesin yaptıklarına göre dereceleri vardır. Sonunda (Allah) onlara yaptıklarının (karşılığını) verecektir; onlara haksızlık edilmeyecektir."},{"n":20,"t":"Kâfir olanlar ateşe sunulacakları gün (onlara şöyle denecektir): “Dünyadaki hayatınızda bütün güzel şeylerinizi harcadınız; onlardan yararlandınız. Bugün ise yeryüzünde haksız olarak kibirlenmeniz ve yoldan çıkmanızdan dolayı küçük düşürücü bir azapla cezalandırılacaksınız!”"},{"n":21,"t":"Âd (kavmin)in kardeşini (Hud’u) an! Zira o, kendinden önce ve sonra uyarıcıların geçtiği Ahkaf bölgesindeki kavmini “Allah’tan başkasına kulluk etmeyin! Şüphesiz ki üzerinize gelecek büyük bir günün azabından korkuyorum!” diye uyarmıştı."},{"n":22,"t":"(Kavmi) “Sen bizi ilahlarımızdan çevirmek için mi bize geldin? Doğru söyleyenlerdensen bize vadettiğini bize (başımıza) getir!” demişti."},{"n":23,"t":"(Hud ise) “O bilgi yalnızca Allah’ın katındadır. Ben size, bana gönderilen şeyi ulaştırıyorum. Fakat sizin cahil bir topluluk olduğunuzu görüyorum!” demişti."},{"n":24,"t":"Sonunda onu (kasırgayı), vadilerine doğru yayılan bir bulut şeklinde görünce (sevinçle) “Bu, bize yağmur yağdıracak yayılan bir buluttur!” demişlerdi. (Hud ise) “Hayır! O, sizin acele istediğiniz şeydir (azaptır). İçinde elem verici azap bulunan bir rüzgârdır!” (demişti)."},{"n":25,"t":"O (rüzgâr), Rabbinin emriyle her şeyi yıkar, mahveder. Nitekim (kasırga gelince) evlerinden başka bir şey görülemez olmuştu. İşte biz, suçlu toplumu böyle cezalandırırız."},{"n":26,"t":"Yemin olsun ki onlara, size vermediğimiz güç ve servet vermiştik. Kendilerine işitme (duyusu), gözler ve kalpler vermiştik. Fakat işitme (duyusu), gözleri ve kalpleri kendilerine hiçbir yarar sağlamamıştı. Çünkü Allah’ın ayetlerini (bilerek) inkâr ediyorlardı. Alay ettikleri şey, kendilerini kuşatmış (olacak)tır."},{"n":27,"t":"Yemin olsun ki biz çevrenizdeki şehirleri (halklarını) helak etmiştik. (Gerçeğe) dönerler diye ayetleri (onlara) tekrar tekrar açıklamıştık."},{"n":28,"t":"Kendilerine yakınlık sağlamak için Allah’ın peşi sıra ilah edindikleri şeyler, onlara yardım etselerdi ya! Hayır! (Tapındıkları şeyler) onlardan kaybolup (gitmiştir). İşte bu, onların yalanı ve uydurup durdukları şeydir."},{"n":29,"t":"Hani cinlerden bir grubu, Kur’an’ı dinlemeleri için sana yönlendirmiştik. (Kur’an’ı dinlemeye) hazır olduklarında (birbirlerine) “Susun!” demişler, (dinlemeleri) bitince uyarıcılar olarak toplumlarına dönmüşlerdi."},{"n":30,"t":"(O cinler) şöyle demişlerdi: “Ey kavmimiz! Şüphesiz ki biz Musa’dan sonra indirilen, kendinden öncekini(n aslını) doğrulayan, gerçeğe ve doğru yola ulaştıran bir kitap dinledik."},{"n":31,"t":"Ey kavmimiz! Allah’ın davetçisine (çağrısına) cevap verin ve O’na iman edin ki günahlarınızı bağışlasın ve sizi elem verici bir azaptan korusun."},{"n":32,"t":"(Ancak) kim Allah’ın davetçisine (çağrısına) cevap vermezse, bilsin ki kimse O’nu yeryüzünde elbette aciz bırakamaz ve böylesi kişilerin O’nun peşi sıra dostları da olamaz. İşte onlar apaçık bir sapkınlığın içindedir.”"},{"n":33,"t":"Gökleri ve yeri yaratan, bunları yaratmakla yorulmayan Allah’ın, ölüleri diriltmeye de gücünün yeteceğini hiç mi düşünmediler? Evet; şüphesiz ki O, her şeye gücü yetendir."},{"n":34,"t":"Ateşe sunulacakları gün, kâfir olanlara “Bu (diriltilme) gerçek değil miymiş!” (diyecek), onlar da “Rabbimize yemin olsun: Evet (gerçekmiş)!” diyeceklerdir. (Allah:) “İnkâr ettiğinizden dolayı azabı tadın!” diyecektir."},{"n":35,"t":"Elçilerden kararlılık sahibi olanların sabrettiği gibi sen de sabret! Onlar (inkârcılar) hakkında acele etme! Vadedildikleri azabı gördükleri gün sanki dünyada sadece gündüzün bir saati kadar kaldıklarını sanacaklar. (Bu), bir tebliğdir. Yoldan çıkmış topluluktan başkası helak edilir mi hiç!"}],[{"n":1,"t":"Kâfir olanların ve (insanları) Allah yolundan alıkoyanların işlerini (Allah) boşa çıkarmış (olacak)tır."},{"n":2,"t":"İman edip iyi işler yapanların ve Muhammed’e indirilenin Rableri tarafından gerçek olduğuna inananların günahlarını (Allah) örtmüş ve onların durumunu düzeltmiş (olacak)tır."},{"n":3,"t":"Bunun sebebi, inkâr edenlerin batıla uymaları, inananların da Rablerinden gelen gerçeğe uymuş olmalarıdır. İşte böylece Allah insanlara kendilerinden örnekler vermektedir."},{"n":4,"t":"(Savaşta) o inkâr edenlerle karşılaştığınız zaman boyunlarını vurun! Sonunda o (sağ kalan)ları etkisiz hale getirince bağ(ların)ı sıkıca bağlayın! Savaş sona erince de artık ya karşılıksız serbest bırakma veya fidye (uygulayın)! İşte böyle. Allah dileseydi onlardan intikam alırdı. Fakat (bu) sizi birbirinizle denemek içindir. Allah yolunda öldürülenlere gelince, (Allah) onların yaptıklarını asla boşa çıkarmayacaktır."},{"n":5,"t":"(Allah) onları (isteklerine) ulaştıracak ve durumlarını düzeltecektir."},{"n":6,"t":"Onları, kendilerine tanıttığı cennete yerleştirecektir."},{"n":7,"t":"Ey iman edenler! Siz Allah’a (dinine) yardım ederseniz (O da) size yardım eder; ayaklarınızı sağlamlaştırır."},{"n":8,"t":"İnkâr edenlere gelince, onların hakkı yıkımdır. (Allah) onların yaptıklarını boşa çıkarmıştır."},{"n":9,"t":"Bunun sebebi, Allah’ın indirdiğini beğenmemeleridir. (Allah da) onların işlerini boşa çıkarmıştır."},{"n":10,"t":"Kendilerinden öncekilerin sonunun nasıl olduğunu görmek üzere yeryüzünde hiç mi dolaşmadılar? Allah onları yerle bir etmiştir. Kâfirlere de onların benzerleri vardır."},{"n":11,"t":"Bu, Allah’ın inananların yardımcısı olmasından dolayıdır. Kâfirlere gelince, onların yardımcıları yoktur."},{"n":12,"t":"Şüphesiz ki Allah iman edip iyi işler yapanları, altlarından ırmaklar akan cennetlere koyacaktır. Kâfir olanlar ise (dünyadan) yararlanır, hayvanların yediği gibi yerler. Onların (mahşerdeki) yeri ateştir."},{"n":13,"t":"Senin şehrinden –ki (halkı) seni (oradan) çıkarmıştı– daha kuvvetli nice şehirleri yok etmiştik; onlara bir yardım eden de çıkmamıştı."},{"n":14,"t":"Rabbi tarafından apaçık bir delil üzere olan kişi, kötü işi kendisine güzel görünen ve heveslerine uyan kimse gibi olur mu hiç!"},{"n":15,"t":"Muttakîlere (duyarlı olanlara) vadedilen cennetin örneği şöyledir: Orada (zamanla) bozulmayan sudan ırmaklar, tadı değişmeyen sütten ırmaklar, içenlere lezzet veren içkiden ırmaklar ve süzme baldan ırmaklar vardır. Orada meyvelerin her çeşidi onlarındır. Rablerinden de bağışlanma vardır. Bu (durum), ateşte ebedî kalan ve bağırsaklarını parça parça edecek kaynar su içirilen kimsenin durumu gibi olur mu hiç!"},{"n":16,"t":"Onlardan seni dinleyenler de vardır. Fakat senin yanından çıkınca kendilerine bilgi verilmiş olanlara “Az önce ne demişti?” diye (alaycılıkla) sorarlar. İşte onlar, kalplerini Allah’ın mühürledidikleridir ve arzularına uyanlardır."},{"n":17,"t":"Doğru yolu bulanlara gelince, (Allah) onların hidayetlerini artırır ve onlara takvâlarını verir."},{"n":18,"t":"Onlar, o (Son) Saat’in ansızın kendilerine gelmesinden başka ne bekliyorlar ki! Elbette onun alâmetleri gelmiştir. Kendilerine gelip çatınca (gerçeği) hatırlamaları neye yarar!"},{"n":19,"t":"Bil ki Allah’tan başka ilah yoktur. Hem kendi hatanın hem de mümin erkeklerin ve mümin kadınların (hatalarının) bağışlanmasını dile! Allah dönüp dolaştığınız yeri de duracağınız yeri de bilir."},{"n":20,"t":"İman etmiş olanlar “Keşke savaş hakkında bir sure indirilmiş olsaydı!” derler. Ama hükmü apaçık bir sure indirilip de onda savaştan söz edilince, kalplerinde hastalık bulunanların ölüm baygınlığı geçiren kimsenin bakışı gibi sana baktıklarını görürsün. Onlara yakışan da budur!"},{"n":21,"t":"(Onların görevi) itaat ve güzel söz(dür). İş ciddiye bindiği zaman Allah’a sadakat gösterselerdi, elbette kendileri için hayırlı olurdu."},{"n":22,"t":"Geri dönerseniz, yeryüzünde bozgunculuk yapmaya ve akrabalık bağlarını kesmeye dönmüş olmaz mıydınız?"},{"n":23,"t":"İşte bunlar, Allah’ın kendilerini lanetlediği, sağırlaştırdığı ve gözlerini kör ettiği kişilerdir."},{"n":24,"t":"Onlar, Kur’an’ı inceden inceye düşünmüyorlar mı? Yoksa kalpler kilitli mi?"},{"n":25,"t":"Şüphesiz ki kendilerine doğru yol belli olduktan sonra arkalarına dönenleri şeytan sürüklemiş ve kendilerine ümit vermiştir."},{"n":26,"t":"Bunun sebebi, Allah’ın indirdiğinden hoşlanmayanlara “Bazı konularda size itaat edeceğiz!” demeleridir. Allah onların gizlediklerini biliyor."},{"n":27,"t":"Ya melekler onların yüzlerine ve sırtlarına vurarak canlarını alırken hâlleri nasıl olacak!"},{"n":28,"t":"Bunun sebebi, onların Allah’ı öfkelendiren şeylere uymaları ve O’nu memnun edecek şeylerden hoşlanmamalarıdır. Bu yüzden (Allah) onların işlerini boşa çıkarmıştır."},{"n":29,"t":"Kalplerinde hastalık bulunanlar, Allah’ın onların kinlerini ortaya çıkarmayacağını mı sandılar!"},{"n":30,"t":"Biz dileseydik onları sana gösterirdik, sen de onları yüzlerinden tanırdın; konuşma tarzlarından da tanıyorsun (tanıyor olurdun). Allah işlerinizi bilmektedir."},{"n":31,"t":"Sizi mutlaka imtihan edeceğiz; ta ki içinizden cihad edenlerle (fedakârlık yapanlarla) sabredenleri bil(dir)ip (ortaya çıkaralım) ve haberlerinizi(n doğruluğunu) deneyelim."},{"n":32,"t":"Şüphesiz ki inkar edip (insanları) Allah yolundan alıkoyan ve kendilerine doğru yol belli olduktan sonra Elçi'ye karşı gelenler, Allah’a asla hiçbir zarar veremeyeceklerdir. İleride onların yaptıklarını boşa çıkaracaktır."},{"n":33,"t":"Ey iman edenler! Allah’a itaat edin, Elçi'ye de itaat edin! İşlerinizi boşa çıkarmayın!"},{"n":34,"t":"Şüphesiz ki inkar edip (insanları) Allah yolundan alıkoyan ve sonra da kâfir olarak ölenleri Allah asla bağışlamayacaktır."},{"n":35,"t":"Savaşta üstün durumdayken gevşeyip barışa çağırmayın (barışa çağırmak zorunda kalmayın)! Allah sizinle beraberdir. O, yaptıklarınızı asla eksiltmeyecektir."},{"n":36,"t":"Dünya hayatı, sadece bir oyun ve eğlenceden ibarettir. İman eder ve takvâlı (duyarlı) davranırsanız (Allah) size ödüllerinizi verecek ve sizden mallarınızın (tamamını) istemeyecektir."},{"n":37,"t":"Onları sizden isteseydi ve (buna) sizi zorlasaydı, cimrilik ederdiniz ve (Allah) da sizin kinlerinizi ortaya çıkarmış olurdu."},{"n":38,"t":"İşte siz Allah yolunda infaka (vermeye) çağrılıyorsunuz. Sizden cimrilik eden(ler) var. Kim cimrilik ederse sadece kendisine cimrilik etmiş olur. Allah zengindir, siz (O’na) muhtaçsınız. (Allah’a itaatten) yüz çevirirseniz, yerinize sizden başka bir toplum getirir; artık onlar sizin gibi olmazlar."}],[{"n":1,"t":"Şüphesiz ki biz sana (Hudeybiye’de) apaçık bir zafer verdik."},{"n":2,"t":"Böylece Allah senin geçmiş ve gelecek günahını bağışlayacak, sana olan nimetini tamamlayacak ve seni doğru yola ulaştıracaktır."},{"n":3,"t":"Sana güçlü bir şekilde yardım edecektir."},{"n":4,"t":"İmanlarını imanla artırsınlar diye müminlerin kalplerine güven indiren O’dur. Göklerin ve yerin orduları yalnızca Allah’a aittir. Allah bilendir, doğru hüküm verendir."},{"n":5,"t":"(Allah) mümin erkeklerle mümin kadınları, içlerinde ebedî kalacakları, altlarından ırmaklar akan cennetlere yerleştirecek ve onların günahlarını örtecektir. İşte bu, Allah katında büyük bir kurtuluştur."},{"n":6,"t":"Allah hakkında kötü zanda bulunan münafık erkeklere ve münafık kadınlara, müşrik erkeklere ve müşrik kadınlara da azap edecektir. (Müslümanlar için bekledikleri) kötülük çemberi, onların (inkârcıların ve münafıkların) başlarına gelsin! Allah onlara gazap etmiş, kendilerini lanetlemiş ve cehennemi kendilerine hazırlamış (olacak)tır; ne kötü varış yeridir (orası)!"},{"n":7,"t":"Göklerin ve yerin orduları yalnızca Allah’a aittir. Allah güçlüdür, doğru hüküm verendir."},{"n":8,"t":"8-9 Allah’a ve Elçisine iman edesiniz, O’na (Allah’a) saygı gösteresiniz, O’nu yüceltesiniz ve sabah akşam O’nu tesbih edesiniz (yüceltesiniz) diye şüphesiz ki biz seni bir şahit, bir müjdeleyici ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"8-9 Allah’a ve Elçisine iman edesiniz, O’na (Allah’a) saygı gösteresiniz, O’nu yüceltesiniz ve sabah akşam O’nu tesbih edesiniz (yüceltesiniz) diye şüphesiz ki biz seni bir şahit, bir müjdeleyici ve bir uyarıcı olarak gönderdik."},{"n":10,"t":"Şüphesiz ki sana biat edenler, elbette Allah’a biat etmektedir. Allah’ın eli, onların ellerinin üzerindedir. Kim (sözünden) dönerse ancak kendi aleyhine dönmüş olur. Kim de Allah’a olan sözüne vefa gösterirse, (Allah) ona ileride büyük bir ödül verecektir."},{"n":11,"t":"Göçebelerden geride kalmış olanlar sana şöyle diyecekler: “Mallarımız ve ailelerimiz bizi meşgul etti. Bizim için bağışlanma dile!” Onlar, kalplerinde olmayanı dilleriyle söylerler. De ki: “(Allah) size bir zarar (vermeyi) dilerse veya bir yarar elde etmenizi isterse sizin için Allah’a karşı kimin bir şeye gücü yetebilir ki!” Gerçek şu ki Allah yaptıklarınızdan haberdardır."},{"n":12,"t":"Aslında siz Elçinin ve müminlerin ailelerine asla dönemeyeceğini sanmıştınız. Bu, sizin kalplerinize güzel görünmüştü; kötü zanda bulunmuş ve helaki (cezalandırılmayı) hak etmiş bir topluluk olmuştunuz."},{"n":13,"t":"Kim Allah’a ve Elçisine iman etmezse (bilsin ki) biz, kâfirler için çılgın bir ateş hazırlamış (olacağ)ız."},{"n":14,"t":"Göklerin ve yerin otoritesi yalnızca Allah’a aittir. (Allah) dileyeni (layık gördüğünü) bağışlar, dileyene (layık gördüğüne) de azap eder. Allah çok bağışlayandır, çok merhametlidir."},{"n":15,"t":"Ganimetleri almak için gittiğinizde (Hudeybiye’den) geride kalanlar, Allah’ın sözünü değiştirmek isteyerek “Bırakın, biz de sizi takip edelim!” diyeceklerdir. De ki: “Siz asla bizi takip etmeyeceksiniz! Allah işte sizin için daha önce böyle buyurmuştur.” Onlar size “Hayır, bizi kıskanıyorsunuz!” diyeceklerdir. Aksine onlar az anlayanlardır."},{"n":16,"t":"Göçebelerden (Hudeybiye’den) geride kalmış olanlara de ki: “Siz ileride çok güçlü bir kavme karşı (savaşmaya) çağrılacaksınız. Onlarla ya savaşacaksınız ya da teslim olacaklar. İtaat ederseniz, Allah size güzel bir ödül verecektir. Önceden döndüğünüz gibi yine dönecek olursanız size elem verici bir şekilde azap eder."},{"n":17,"t":"Görme engelliye zorluk yoktur; topala zorluk yoktur; hastaya da zorluk yoktur. Kim Allah’a ve Elçisine gönülden itaat ederse (Allah) onu, altlarından ırmaklar akan cennetlere yerleştirir. Kim de yüz çevirirse ona elem verici bir şekilde azap eder."},{"n":18,"t":"O ağacın altında sana biat ederlerken, Allah o müminlerden şüphesiz ki razı olmuştur. Kalplerinde olanı bilmiş, onlara güven duygusu indirmiş ve onları yakın bir zaferle ödüllendirmiş (olacak)tır."},{"n":19,"t":"Elde edecekleri pek çok ganimetlerle de (onları ödüllendirecektir). Allah güçlüdür, doğru hüküm verendir."},{"n":20,"t":"Allah size, elde ede(bil)eceğiniz birçok ganimet vadetmiştir. (Şimdilik) bunları hemen vermiş ve insanların ellerini sizden çekmiştir ki bu (imkânlar), müminlere bir delil olsun ve sizi doğru yola ulaştırsın."},{"n":21,"t":"Allah’ın elbette kuşattığı, henüz elde edemediğiniz başka (imkânlar) da (vadetmiştir). Allah her şeye gücü yetendir."},{"n":22,"t":"Kâfir olanlar sizinle savaşsalardı, elbette arkalarına dönüp (kaçar)lardı. Sonra hiçbir dost ve hiçbir yardımcı da bulamazlardı."},{"n":23,"t":"Allah’ın, daha önce geçen (süregelen) kanunu (budur). Allah’ın kanununda asla bir değişiklik bulamazsın."},{"n":24,"t":"Sizi onlara üstün (galip) kıldıktan sonra, Mekke vadisinde onların ellerini sizden, sizin ellerinizi de onlardan çeken O’dur. Allah yaptıklarınızı görendir."},{"n":25,"t":"Onlar, kâfir olan ve sizin Mescid-i Haram’ı ziyaretinizi ve bekletilen kurbanların yerlerine ulaşmasını engelleyenlerdir. (Mekke’de) kendilerini henüz tanımadığınız mümin erkeklerle mümin kadınları bilmeyerek ezmeniz sebebiyle üzüntüye kapılma ihtimaliniz olmasaydı (Allah savaşı önlemezdi). Allah dilediğini (layık olanı) rahmetine koymak için böyle yapmıştır. Birbirinden ayrılmış olsalardı, elbette onlardan kâfir olanlara elem verici bir şekilde azap ederdik."},{"n":26,"t":"O zaman inkâr edenler, kalplerine katılığı (tutuculuğu), cahiliye katılığını (tutuculuğunu) yerleştirmişlerdi. Allah da Elçisine ve müminlere güven duygusu indirmiş, onların takvâ (duyarlılık) sözünü tutmalarını sağlamıştı. (Zaten) onlar, buna en layık ve en ehil kişilerdi. Allah her şeyi bilendir."},{"n":27,"t":"Şüphesiz ki Allah, Elçisinin rüyasını bir amaç uğruna doğru çıkarmıştır. İnşallah şüphesiz ki siz güven içinde (kiminiz) başlarınızı tıraş etmiş, (kiminiz saçlarını) kısaltmış olarak, korkmadan Mescid-i Haram’a gireceksiniz. Allah sizin bilmediğinizi bilir. İşte bunun dışında size yakın bir zafer vermiş (olacak)tır."},{"n":28,"t":"(Dinini) bütün din(ler)e üstün kılmak için Elçisini bir rehber ve gerçek din ile gönderen O’dur. Şahit olarak Allah yeter."},{"n":29,"t":"Muhammed, Allah’ın Elçisidir. Beraberinde bulunanlar da kâfirlere karşı şiddetli, kendi aralarında merhametlidir. Allah’tan lütuf ve rıza isteyerek onları rükû halinde, secde halinde görürsün. Onların nişanları, yüzlerindeki secde izidir. Bu, onların Tevrat’taki örneğidir. İncil’deki örneği ise şöyledir: (Onlar) filizini yarıp çıkarmış, onu güçlendirerek kalınlaşmış, gövdesi üzerine dikilmiş bir ekin gibidir. (Bu), çiftçilerin hoşuna gider. (Allah) böylece onlar (güçlenen müminler) sebebiyle kâfirleri öfkelendirir. Allah onlardan iman edip iyi işler yapanlara bağışlanma ve büyük ödül vadetmiştir."}],[{"n":1,"t":"Ey iman edenler! Allah’ın ve Elçisinin önüne geçmeyin! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah duyandır, bilendir."},{"n":2,"t":"Ey iman edenler! Seslerinizi Peygamber’in sesinin üzerine yükseltmeyin! Birbirinize yüksek sesle konuştuğunuz gibi, ona yüksek sesle konuşmayın; (yoksa) farkına varmadan işleriniz boşa gider."},{"n":3,"t":"Şüphesiz ki Allah’ın Elçisinin yanında seslerini kısanlar, kalplerini Allah’ın takvâ (duyarlılık) ile imtihan ettiği (arındırdığı) kişilerdir. Onlar için bağışlanma ve büyük bir ödül vardır."},{"n":4,"t":"Sana odaların arkasından (bağırarak) seslenenlerin çoğu akıl etmezler."},{"n":5,"t":"Onlar sen (yanlarına) çıkıncaya kadar sabretselerdi, elbette kendileri için daha hayırlı olurdu. Allah çok bağışlayandır, çok merhametlidir."},{"n":6,"t":"Ey iman edenler! Yoldan çıkmış biri size bir haber getirirse (onun doğruluğunu) araştırın! (Yoksa) bilmeden bir topluluğa kötülük edersiniz de sonra yaptığınıza pişman olursunuz."},{"n":7,"t":"Bilin ki içinizde Allah’ın Elçisi vardır. O, birçok işte size uysaydı sıkıntıya düşerdiniz. Fakat Allah size imanı sevdirmiş ve onu kalplerinize süslemiş; inkârı, yoldan çıkmayı ve isyanı da size çirkin göstermiştir. Asıl doğru yoldakiler işte bunlardır."},{"n":8,"t":"(Bu), Allah’tan bir lütuf ve nimet olarak (böyledir). Allah bilendir, doğru hüküm verendir."},{"n":9,"t":"Müminlerden iki grup birbirleriyle şavaşırlarsa aralarını düzeltin! Biri ötekine saldırırsa, Allah’ın buyruğuna dönünceye kadar saldıran tarafla savaşın! (Savaştan vazgeçip) dönerse artık aralarını adaletle düzeltin ve adil davranın! Şüphesiz ki Allah adil davrananları sever."},{"n":10,"t":"Müminler sadece kardeştirler. Kardeşlerinizin arasını düzeltin ve Allah’a karşı takvâlı (duyarlı) olun ki size merhamet edilsin."},{"n":11,"t":"Ey iman edenler! Bir topluluk diğer bir toplulukla alay etmesin! Belki onlar (alay edilenler), kendilerinden (alay edenlerden) daha hayırlıdır. Kadınlar da kadınlarla alay etmesin! Belki onlar (alay edilenler), kendilerinden (alay edenlerden) daha hayırlıdır. Kendi kendinizi ayıplamayın; birbirinizi kötü lakaplarla çağırmayın! İmandan sonra yoldan çıkmak (anlamındaki kelime) ne kötü bir isimdir! Kim tevbe etmezse işte onlar, zalimlerin ta kendileridir."},{"n":12,"t":"Ey iman edenler! Zandan çok kaçının! Şüphesiz ki zannın bir kısmı günahtır. Biriniz diğerini arkasından çekiştirmesin! Biriniz, ölmüş kardeşinin etini yemekten hoşlanır mı? Bundan tiksindiniz (değil mi?). Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah tevbeyi çok kabul edendir, çok merhametlidir."},{"n":13,"t":"Ey insanlar! Şüphesiz ki biz sizi bir erkekle bir dişi (hücre türün)den yarattık. Birbirinizle tanışmanız için sizi toplumlara ve kabilelere ayırdık. Şüphesiz ki Allah katında en değerli olanınız, en çok takvâlı (duyarlı) olanınızdır. Şüphesiz ki Allah bilendir, haberdardır."},{"n":14,"t":"Göçebe Araplar “İman ettik!” dediler. De ki: “Siz (henüz) iman etmediniz ama ‘Teslim olduk!’ deyin! (Çünkü) iman henüz kalplerinize yerleşmedi. Allah’a ve Elçisine itaat ederseniz (Allah) işlerinizden hiçbir şeyi eksiltmez.” Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":15,"t":"Gerçek müminler ancak Allah’a ve Elçisine iman eden, sonrasında şüphe duymayan, Allah yolunda mallarıyla ve canlarıyla cihad edenlerdir (fedakârlık yapanlardır). İşte (inancında) doğru olanlar sadece bunlardır."},{"n":16,"t":"De ki: “Allah göklerde ve yerde olanları bilmekteyken siz dininizi Allah’a mı öğretiyorsunuz!” Allah her şeyi bilendir."},{"n":17,"t":"Onlar, müslüman olmalarını senin başına kakıyorlar. De ki: “Müslümanlığınızı benim başıma kakmayın! Doğruysanız bilin ki size imanı gösterdiği için aslında Allah size iyilikte bulunmaktadır.”"},{"n":18,"t":"Şüphesiz ki Allah göklerin ve yerin gaybını (bilinemeyenini) bilir. Allah yaptıklarınızı görendir."}],[{"n":1,"t":"Kâf. Yüce Kur’an’a yemin olsun."},{"n":2,"t":"Doğrusu kendilerine içlerinden bir uyarıcının gelmesine şaştılar ve kâfirler “Bu, şaşılacak bir şeydir!"},{"n":3,"t":"Biz öldüğümüz ve toprak olduğumuz zaman (diriltilecek) mi(yiz)? Bu, (akla) uzak bir dönüştür!” dediler."},{"n":4,"t":"Biz toprağın onlardan neleri eksiltmekte olduğunu elbette bilmekteyiz. Katımızda (o bilgileri) koruyan bir kitap vardır."},{"n":5,"t":"Aksine onlar, kendilerine geldiğinde gerçeği yalanladılar. (Şimdi) onlar derin bir perişanlık içindedir."},{"n":6,"t":"Üstlerindeki göğe bakmadılar mı hiç; onu nasıl bina etmiş ve süslemişiz! Onda hiçbir eksik yoktur."},{"n":7,"t":"Yeri de genişlettik ve içine ağırlıklar yerleştirdik. Orada her tür güzel çiftten (bitkiler) yetiştirdik."},{"n":8,"t":"(Bütün bunlar, Allah’a) yönelen her kulun öngörülü olması ve (gerçeği) hatırlaması içindir."},{"n":9,"t":"Gökten bereketli bir su indirdik de onunla, bahçeler ve biçilecek taneler yetiştirdik."},{"n":10,"t":"10-11 Kullara rızık olması için tomurcukları üst üste uzun hurma ağaçları (yetiştirdik). Onunla (suyla) ölü bir şehri (toprağı) canlandırdık. İşte (mahşerdeki) çıkış da böyledir."},{"n":11,"t":"10-11 Kullara rızık olması için tomurcukları üst üste uzun hurma ağaçları (yetiştirdik). Onunla (suyla) ölü bir şehri (toprağı) canlandırdık. İşte (mahşerdeki) çıkış da böyledir."},{"n":12,"t":"12-14 Onlardan önce Nuh kavmi, Ress halkı, Semûd ve Âd (kavmi), Firavun, Lut’un kardeşleri, Eyke halkı ve Tübba‘ kavmi de yalanlamıştı. Hepsi elçileri yalanlamıştı. Böylece (azap) tehdidim gerçekleşmişti."},{"n":13,"t":"12-14 Onlardan önce Nuh kavmi, Ress halkı, Semûd ve Âd (kavmi), Firavun, Lut’un kardeşleri, Eyke halkı ve Tübba‘ kavmi de yalanlamıştı. Hepsi elçileri yalanlamıştı. Böylece (azap) tehdidim gerçekleşmişti."},{"n":14,"t":"12-14 Onlardan önce Nuh kavmi, Ress halkı, Semûd ve Âd (kavmi), Firavun, Lut’un kardeşleri, Eyke halkı ve Tübba‘ kavmi de yalanlamıştı. Hepsi elçileri yalanlamıştı. Böylece (azap) tehdidim gerçekleşmişti."},{"n":15,"t":"İlk yaratmada acizlik mi göstermişiz! Aksine onlar yeni bir yaratma hakkında şüphe içindedir."},{"n":16,"t":"Yemin olsun ki insanı biz yarattık. Nefsinin ona neler fısıldadığını bilmekteyiz. Biz ona şah damarından daha yakınız."},{"n":17,"t":"Hani sağdan ve soldan iki (melek), kaydedici olarak (insanı) gözetleyicidir."},{"n":18,"t":"Kişinin her bir sözünün (davranışının) yanında hazır bir gözetleyici, bir kaydedici mutlaka vardır."},{"n":19,"t":"Ölüm sarhoşluğu gerçeği getirir; (insana) “İşte bu, senin kaçtığın şeydir!” (denir)."},{"n":20,"t":"Sûr’a üflenecektir. İşte bu, vadedilen gündür."},{"n":21,"t":"Herkes, yanında bir sevk edici (melek), bir de şahitle birlikte gelecektir."},{"n":22,"t":"(Sorgulanan kişiye) “Şüphesiz ki sen bundan gafletteydin; (kıyamet günü) biz senin gaflet perdeni kaldırdık. Bugün artık gözün keskindir!” (denecektir)."},{"n":23,"t":"Yakınındaki (sevk edici melek) “İşte yanımdaki hazır!” diyecektir."},{"n":24,"t":"24-26 (Görevlilerine şöyle denecektir:) “Siz ikiniz! Çok inatçı ısrarcı her kâfiri, iyiliğe bütün gücüyle engel olanı, Allah ile birlikte başka ilah edinen şüpheci saldırganı cehenneme atın; onu şiddetli azaba atın!”"},{"n":25,"t":"24-26 (Görevlilerine şöyle denecektir:) “Siz ikiniz! Çok inatçı ısrarcı her kâfiri, iyiliğe bütün gücüyle engel olanı, Allah ile birlikte başka ilah edinen şüpheci saldırganı cehenneme atın; onu şiddetli azaba atın!”"},{"n":26,"t":"24-26 (Görevlilerine şöyle denecektir:) “Siz ikiniz! Çok inatçı ısrarcı her kâfiri, iyiliğe bütün gücüyle engel olanı, Allah ile birlikte başka ilah edinen şüpheci saldırganı cehenneme atın; onu şiddetli azaba atın!”"},{"n":27,"t":"Yakınındaki (şeytan): “Rabbimiz! Onu ben azdırmadım. Fakat kendisi derin bir sapkınlık içindeydi.” diyecektir."},{"n":28,"t":"(Allah) şöyle diyecektir: “Huzurumda çekişmeyin! (Ben size) uyarı göndermiştim!"},{"n":29,"t":"Benim huzurumda söz değiştirilmez; ben kullar(ım)a asla haksızlık edici değilim.”"},{"n":30,"t":"O gün cehenneme “Doldun mu?” diyeceğiz. O da “Daha var mı?” diyecektir."},{"n":31,"t":"(Kendilerinden) uzakta olmayacak şekilde cennet de muttakîlere (duyarlı olanlara) yaklaştırılacaktır."},{"n":32,"t":"İşte bu (cennet) sizin için, yani daima (Allah’a) yönelen (ve emirlerini) koruyup (gözeten) herkes içindir."},{"n":33,"t":"(Bunlar) yalnızken Rahmân’a saygı gösteren ve (O’na) yönelmiş bir kalp getirenlerdir."},{"n":34,"t":"Oraya esenlikle girin! İşte bu, ebedî (hayat) günüdür."},{"n":35,"t":"Orada kendileri için diledikleri her şey vardır. Katımızda fazlası da vardır."},{"n":36,"t":"Biz onlardan önce kendilerinden çok daha güçlü olan ve (ölümden kurtulmak için) “Sığınılacak bir yer var mı?” diye diyar diyar dolaşan nice nesilleri yok etmişizdir."},{"n":37,"t":"Şüphesiz ki bunda (akıl eden) bir kalbi olan, yani görerek ona kulak verenler için gerçeği hatırlatan (dersler) vardır."},{"n":38,"t":"Yemin olsun ki biz gökleri, yeri ve ikisi arasında bulunanları altı günde (dönemde) yarattık. Bize hiçbir yorgunluk da ulaşmadı."},{"n":39,"t":"39-40 Onların dediklerine sabret! Güneşin doğuşundan önce de batışından önce de gecenin bir bölümünde ve secdelerin ardından da Rabbini hamd (övgü) ile tesbih et (yücelt)!"},{"n":40,"t":"39-40 Onların dediklerine sabret! Güneşin doğuşundan önce de batışından önce de gecenin bir bölümünde ve secdelerin ardından da Rabbini hamd (övgü) ile tesbih et (yücelt)!"},{"n":41,"t":"(Diriltilme için) seslenenin yakın bir yerden sesleneceği güne kulak ver(in)!"},{"n":42,"t":"O gün, (insanlar) o korkunç sesi gerçekten duyacaklardır. Bu, (mezarlardan) çıkış günüdür."},{"n":43,"t":"Şüphesiz ki dirilten de öldüren de biziz. Dönüş sadece bize olacaktır."},{"n":44,"t":"O gün yer, onlar nedeniyle (insanların diriltilmesi için) çabucak yarılacaktır. Bu, bizim için kolay bir toplamadır."},{"n":45,"t":"Onların söylediklerini çok iyi bileniz. Sen onların üzerinde asla zorba değilsin. Tehdidimden korkanlara (gerçeği) Kur’an’la hatırlat!"}],[{"n":1,"t":"Yemin olsun: Esip savuranlara,"},{"n":2,"t":"Ağırlık taşıyanlara,"},{"n":3,"t":"Kolayca süzülenlere,"},{"n":4,"t":"İşi ayıranlara ki"},{"n":5,"t":"Size vadedilenler elbette doğrudur."},{"n":6,"t":"Hesap da mutlaka gerçekleşecektir."},{"n":7,"t":"Yörüngeleri bulunan göğe yemin olsun ki"},{"n":8,"t":"Şüphesiz siz çelişkili söz(ler) içindesiniz."},{"n":9,"t":"Ondan (Kur’an’dan) savrulan kişi (kendi aleyhine) savrulmuş olur."},{"n":10,"t":"Kahrolsun o koyu yalancılar!"},{"n":11,"t":"Onlar, koyu bir şaşkınlıkta ne yaptığını bilmeyenlerdir."},{"n":12,"t":"Hesap gününün ne zaman olduğunu soruyorlar."},{"n":13,"t":"O gün onlar, ateş üzerinde imtihan edileceklerdir."},{"n":14,"t":"(Onlara) “İmtihanınızı(n sonucunu) tadın! Acele gelmesini istediğiniz şey işte budur!” (denecektir)."},{"n":15,"t":"15-16 Şüphesiz ki muttakîler (duyarlı olanlar), Rablerinin kendilerine verdiği (nimetleri) alarak cennetlerde ve (su) kaynaklarında (olacaklar)dır. Şüphesiz ki onlar, bundan önce (dünyada) güzel davrananlardı."},{"n":16,"t":"15-16 Şüphesiz ki muttakîler (duyarlı olanlar), Rablerinin kendilerine verdiği (nimetleri) alarak cennetlerde ve (su) kaynaklarında (olacaklar)dır. Şüphesiz ki onlar, bundan önce (dünyada) güzel davrananlardı."},{"n":17,"t":"Geceleri az uyurlardı."},{"n":18,"t":"Seher vakitlerinde de bağışlanma dilerler(di)."},{"n":19,"t":"Mallarında açıktan isteyen ve açıktan isteyemeyen kişiler için hak vardır."},{"n":20,"t":"20-21 Kesin olarak inananlar için yerde de deliller vardır, kendinizde de. Görmüyor musunuz?"},{"n":21,"t":"20-21 Kesin olarak inananlar için yerde de deliller vardır, kendinizde de. Görmüyor musunuz?"},{"n":22,"t":"Gökte de rızkınız ve size vadedilenler vardır."},{"n":23,"t":"Göğün ve yerin Rabbine yemin olsun: Bu (vadedilen gün) konuşmanız gibi gerçektir."},{"n":24,"t":"İbrahim’in ağırlanan misafirlerinin (meleklerin) haberi sana geldi, (değil) mi?"},{"n":25,"t":"Hani onlar (İbrahim’in) yanına girmiş ve “Selam!” demişlerdi. (İbrahim de) “Selam!” demiş, “(Bunlar) yabancı bir topluluk!” (diye içinden geçirmişti)."},{"n":26,"t":"26-27 Hemen ailesinin yanına giderek besili bir dana (eti) getirmiş, onu onlara yaklaştırıp “Yemez misiniz?” demişti."},{"n":27,"t":"26-27 Hemen ailesinin yanına giderek besili bir dana (eti) getirmiş, onu onlara yaklaştırıp “Yemez misiniz?” demişti."},{"n":28,"t":"(Yemediklerini görünce) onlardan korkmaya başlamıştı. (Melekler) “Korkma!” demiş ve ona bilen bir erkek çocuğu müjdelemişlerdi."},{"n":29,"t":"Hanımı, çığlık atarak (meleklere) yönelmiş ve (elini) yüzüne vurarak “Ben kısır bir kocakarıyım!” demişti."},{"n":30,"t":"Onlar (melekler ise:) “Öyle, (ama) bunu Rabbin söylemiştir. Şüphesiz ki yalnızca O, doğru hüküm verendir, bilendir.” demişlerdi."},{"n":31,"t":"(İbrahim:) “Ey elçiler (melekler)! (Başka) ne işiniz var?” diye sormuştu."},{"n":32,"t":"32-34 Onlar “Şüphesiz ki biz suçlu bir topluma, üzerlerine çamurdan taş yağdırmak için gönderildik. (Bu taşlar), aşırı gidenler için Rabbinin katında işaretlenmiş(tir)!” demişlerdi."},{"n":33,"t":"32-34 Onlar “Şüphesiz ki biz suçlu bir topluma, üzerlerine çamurdan taş yağdırmak için gönderildik. (Bu taşlar), aşırı gidenler için Rabbinin katında işaretlenmiş(tir)!” demişlerdi."},{"n":34,"t":"32-34 Onlar “Şüphesiz ki biz suçlu bir topluma, üzerlerine çamurdan taş yağdırmak için gönderildik. (Bu taşlar), aşırı gidenler için Rabbinin katında işaretlenmiş(tir)!” demişlerdi."},{"n":35,"t":"(Biz) orada bulunan müminleri çıkarmıştık."},{"n":36,"t":"Zaten orada müslümanlardan (olan) bir ev (halkın)dan başka (kurtarılacak) kimse bulmamıştık."},{"n":37,"t":"Elem verici azaptan korkanlar için orada bir delil bırakmıştık."},{"n":38,"t":"Musa’da da (dersler vardır). Onu apaçık bir delil ile Firavun’a göndermiştik."},{"n":39,"t":"(Firavun), ordusuyla birlikte yüz çevirmiş, “O bir büyücüdür veya bir cinlenmiştir!” demişti."},{"n":40,"t":"Onu da ordularını da yakalayıp denizde boğmuştuk; bu sırada kendini kınayıp duruyordu."},{"n":41,"t":"Âd (kavmin)de de (dersler vardır). Hani onlara kasıp kavuran rüzgârı göndermiştik."},{"n":42,"t":"(O kasırga) geçtiği yerde hiçbir şey bırakmamış, her şeyi kül edip savurmuştu."},{"n":43,"t":"Semûd (kavmin)de de (dersler vardır). Hani onlara “Bir süreye kadar yararlanın (yaşayın)!” denmişti."},{"n":44,"t":"Rablerinin emrine karşı gelmişlerdi. Bu yüzden, bakarlarken onları yıldırım çarpmıştı."},{"n":45,"t":"Ayağa kalkacak güçleri kalmamış, yardım edenleri de olmamıştı."},{"n":46,"t":"Daha önce de Nuh kavmini (helak etmiştik). Şüphesiz ki onlar, yoldan çıkmış bir toplumdular."},{"n":47,"t":"Göğü güçlü bir şekilde biz bina ettik (yükselttik) ve biz (onu) elbette genişleticiyiz."},{"n":48,"t":"Yeri de biz döşedik. (Bak) ne güzel döşeyiciyiz!"},{"n":49,"t":"Her şeyden iki çift yarattık ki (gerçeği) hatırlayasınız."},{"n":50,"t":"Allah’a koşun! Şüphesiz ki ben size O’ndan (gelmiş) apaçık bir uyarıcıyım."},{"n":51,"t":"Allah ile birlikte başka bir ilah edinmeyin! Şüphesiz ki ben size O’ndan (gelmiş) apaçık bir uyarıcıyım."},{"n":52,"t":"Böylece onlardan öncekilere herhangi bir elçi geldiğinde elbette “O bir büyücüdür veya cinlenmiştir!” demişlerdi."},{"n":53,"t":"Bunu birbirlerine vasiyet mi ettiler! Doğrusu onlar, azgın bir topluluktur."},{"n":54,"t":"Onlardan yüz çevir! Sen asla kınanacak değilsin."},{"n":55,"t":"Sen (gerçeği) hatırlat! Şüphesiz ki hatırlatmak müminlere yarar sağlar."},{"n":56,"t":"Ben cinleri ve insanları, sadece bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben onlardan hiçbir rızık istemiyorum; beni doyurmalarını da istemiyorum."},{"n":58,"t":"Şüphesiz ki yalnızca Allah gerçek rızık verendir, kuvvet sahibidir, güçlüdür."},{"n":59,"t":"Şüphesiz ki arkadaşlarının payı gibi haksızlık edenlerin de (azaptan) payı vardır. (Azabı) benden acele istemesinler!"},{"n":60,"t":"Kendilerine vadedilen günlerinden dolayı kâfir olanların vay hâllerine!"}],[{"n":1,"t":"Yemin olsun: Tûr’a,"},{"n":2,"t":"2-3 Yayılmış ince deriye satır satır yazılmış Kitaba,"},{"n":3,"t":"2-3 Yayılmış ince deriye satır satır yazılmış Kitaba,"},{"n":4,"t":"Ziyaret edilen Ev’e (Kâbe’ye),"},{"n":5,"t":"Yükseltilmiş tavana (göğe),"},{"n":6,"t":"Kaynatılmış denize ki"},{"n":7,"t":"Rabbinin azabı mutlaka gerçekleşecektir."},{"n":8,"t":"Ona engel olacak hiçbir şey yoktur."},{"n":9,"t":"O gün, gök şiddetli bir şekilde sallanıp çalkalanacaktır."},{"n":10,"t":"Dağlar da yürüdükçe yürüyecektir."},{"n":11,"t":"Yalanlayanların o gün vay hâllerine!"},{"n":12,"t":"Onlar daldıkları batıl içinde oyalanıp duranlardır."},{"n":13,"t":"O gün cehennem ateşine itilip atılacaklar."},{"n":14,"t":"(Onlara şöyle denecektir:) “İşte yalanlayıp durduğunuz ateş budur!”"},{"n":15,"t":"Bu bir büyü müymüş! Yoksa görmüyor musunuz?"},{"n":16,"t":"Girin oraya (ateşe)!’ Sabretseniz de sabretmeseniz de sizin için birdir. Size, sadece yaptıklarınızın karşılığı verilmektedir."},{"n":17,"t":"17-18 Şüphesiz ki muttakîler (duyarlı olanlar) Rablerinin kendilerine verdikleriyle sefa sürerek cennetlerde ve nimet içinde olacaklardır. Rableri onları cehennem azabından korumuş olacaktır."},{"n":18,"t":"17-18 Şüphesiz ki muttakîler (duyarlı olanlar) Rablerinin kendilerine verdikleriyle sefa sürerek cennetlerde ve nimet içinde olacaklardır. Rableri onları cehennem azabından korumuş olacaktır."},{"n":19,"t":"19-20 (Onlara) “Yaptıklarınıza karşılık sıra sıra dizilmiş koltuklara yaslanarak afiyetle yiyip için!” (denecektir). Onları, güzel gözlü hurilerle eşleştirmiş (olacağ)ız."},{"n":20,"t":"19-20 (Onlara) “Yaptıklarınıza karşılık sıra sıra dizilmiş koltuklara yaslanarak afiyetle yiyip için!” (denecektir). Onları, güzel gözlü hurilerle eşleştirmiş (olacağ)ız."},{"n":21,"t":"İman edenlere ve onlara imanla uyan nesiller(in)e gelince; biz onları (cennette) nesilleriyle buluşturacağız. Onların yapıp ettiklerinden hiçbir şey eksiltmeyeceğiz. Her kişi kazandığına karşılık rehindir."},{"n":22,"t":"Onlara canlarının istediği türden meyve ve etten bolca vermiş olacağız."},{"n":23,"t":"Boş söze de günaha girmeye de (neden) olmayan kadeh(lerden almak için) orada karşılıklı olarak çekişecekler."},{"n":24,"t":"Saklı inci gibi kendilerine ait gençler (servis için) etraflarında dolaşacaklar."},{"n":25,"t":"Onların bir kısmı bir kısmına dönüp soracaklar."},{"n":26,"t":"Demiş (olacak)lar ki: “Daha önce biz, ailemiz içinde (azaptan) korkardık."},{"n":27,"t":"Allah bize lütfetti de bizi kavurucu azaptan korudu."},{"n":28,"t":"Şüphesiz ki biz bundan önce (dünyada) O’na yalvarıyorduk. Şüphesiz ki yalnızca O çok iyilik edendir; çok merhametlidir.”"},{"n":29,"t":"Sen (gerçeği) hatırlat! Rabbinin lütfuyla sen kâhin de değilsin; cinlenmiş de değilsin."},{"n":30,"t":"Yoksa onlar “(O) bir şairdir; zamanın (getireceği) felaketlere uğramasını bekliyoruz!” mu diyorlar!"},{"n":31,"t":"De ki: “Bekleyin! Şüphesiz ki ben de sizinle birlikte bekleyenlerdenim.”"},{"n":32,"t":"Onlara akılları mı bunu emrediyor; yoksa onlar azgın bir topluluk mudur?"},{"n":33,"t":"Veya “Onu kendisi uydurdu!” mu diyorlar? Hayır! Onlar iman etmezler."},{"n":34,"t":"Doğru (sözlü) iseler onun (Kur’an’ın) benzeri bir söz getirsinler."},{"n":35,"t":"Yoksa onlar, herhangi bir (yaratıcı) olmadan mı yaratıldılar? Yoksa kendileri mi yaratıcıdır?"},{"n":36,"t":"Yoksa gökleri ve yeri onlar mı yarattı? Hayır! Onlar kesin bir şekilde inanmazlar."},{"n":37,"t":"Yoksa Rabbinin hazineleri onların yanında mıdır? Yoksa her şeye hâkim olan kendileri midir?"},{"n":38,"t":"Yoksa onların, (Allah katındaki sırları) dinleyebildikleri merdivenleri mi var? (Öyleyse) dinleyiciler apaçık bir delil getirsinler!"},{"n":39,"t":"Yoksa kızlar O’nun (Allah’ın), oğullar sizin mi?"},{"n":40,"t":"Yoksa sen onlardan bir ücret istiyorsun da borç yüzünden ağır bir yük altında mı kalıyorlar?"},{"n":41,"t":"Yoksa gayb (bilinemeyen şeyler) yanlarında da (ondan) mı yazıyorlar?"},{"n":42,"t":"Veya bir tuzak mı (kurmak) istiyorlar? Asıl tuzağa düşecek kişiler kâfir olanlardır."},{"n":43,"t":"Veya onlar için Allah’tan başka ilah mı var! Allah onların ortak koştuklarından yücedir."},{"n":44,"t":"Gökten düşen bir kütle görseler “(Bunlar) üst üste yığılmış bulutlardır.” derler."},{"n":45,"t":"Artık bayıltılacakları günlerine kavuşuncaya kadar onları kendi hâllerine bırak!"},{"n":46,"t":"Tuzakları o gün kendilerine hiçbir yarar sağlamayacak ve kendilerine yardım da edilmeyecektir."},{"n":47,"t":"Haksızlık edenlere, elbette ondan başka da azap vardır. Fakat çoğu bilmezler."},{"n":48,"t":"Rabbinin hükmüne sabret! Çünkü sen gözlerimizin önündesin. Kalktığın zaman da Rabbini hamd (övgü) ile tesbih et (yücelt)!"},{"n":49,"t":"Gecenin bir kısmında ve yıldızların batışından sonra da O’nu tesbih et (yücelt)!"}],[{"n":1,"t":"(Parça parça) indiğinde necm’e (Kur’an’a) yemin olsun."},{"n":2,"t":"Arkadaşınız (Muhammed), sapmamış ve azgınlaşmamıştır."},{"n":3,"t":"Arzusundan konuşmuyor."},{"n":4,"t":"O (Kur’an) kendisine vahyedilmekte olan vahiyden başka bir şey değildir."},{"n":5,"t":"5-7 Çünkü o (Kur’an’ı) müthiş kuvvetleri olan, donanımlı (Cebrail) öğretmiştir. (Cebrail) en yüksek ufuktayken belirmişti."},{"n":6,"t":"5-7 Çünkü o (Kur’an’ı) müthiş kuvvetleri olan, donanımlı (Cebrail) öğretmiştir. (Cebrail) en yüksek ufuktayken belirmişti."},{"n":7,"t":"5-7 Çünkü o (Kur’an’ı) müthiş kuvvetleri olan, donanımlı (Cebrail) öğretmiştir. (Cebrail) en yüksek ufuktayken belirmişti."},{"n":8,"t":"Sonra yaklaşmış, (ona doğru) sarkmıştı."},{"n":9,"t":"İki yay arası kadar, hatta daha da yakın olmuştu."},{"n":10,"t":"(Böylece Cebrail, Allah’ın) kendisine vahyettiğini kuluna (Peygamber’e) vahyetmişti."},{"n":11,"t":"(Gözünün) gördüğünü kalbi yalanlamamıştı."},{"n":12,"t":"Gördüğü (melek) konusunda şimdi kendisi ile tartışıyor musunuz?"},{"n":13,"t":"13-15 Yemin olsun ki bir başka inişinde onu, cennetü’l-me’vâ (durmaya değer bahçe)nin yanındaki sidretü’l-müntehâ (uzaktaki sedir ağacı)’nın yanında bir kez daha görmüştü."},{"n":14,"t":"13-15 Yemin olsun ki bir başka inişinde onu, cennetü’l-me’vâ (durmaya değer bahçe)nin yanındaki sidretü’l-müntehâ (uzaktaki sedir ağacı)’nın yanında bir kez daha görmüştü."},{"n":15,"t":"13-15 Yemin olsun ki bir başka inişinde onu, cennetü’l-me’vâ (durmaya değer bahçe)nin yanındaki sidretü’l-müntehâ (uzaktaki sedir ağacı)’nın yanında bir kez daha görmüştü."},{"n":16,"t":"Hani o sidre’yi (sedir ağacını) neler kaplıyordu neler!"},{"n":17,"t":"(Peygamber’in) gözü ne (sağa sola) kaymış ne de sınırı aşmıştı."},{"n":18,"t":"Şüphesiz ki (orada) Rabbinin en büyük delillerinden (birini, Cebrail’i) görmüştü."},{"n":19,"t":"19-20 Lât’a, Uzzâ’ya ve diğer üçüncüsü olan Menât’a (neden taptığınızı) hiç düşündünüz mü?"},{"n":20,"t":"19-20 Lât’a, Uzzâ’ya ve diğer üçüncüsü olan Menât’a (neden taptığınızı) hiç düşündünüz mü?"},{"n":21,"t":"Erkek(ler) sizin de dişi(ler) mi O’nun?"},{"n":22,"t":"O zaman şu (yaptığınız) haksız bir paylaşımdır!"},{"n":23,"t":"Bu (putlar), haklarında Allah’ın hiçbir delil indirmediği, sizin ve atalarınızın taktığı isimlerden başka bir şey değildir. (Müşrikler) zanna ve nefislerinin arzuladığından başka hiçbir şeye uymuyorlar. Yemin olsun ki onlara Rablerinden bir rehber gelmiştir."},{"n":24,"t":"Yoksa insan, her arzu ettiğine sahip olduğunu (mu sanıyor)!"},{"n":25,"t":"Oysa ahiret de ilki (dünya) da yalnızca Allah’a aittir."},{"n":26,"t":"Göklerde nice melekler vardır ki onların şefaatleri hiçbir işe yaramaz. Ancak Allah’ın dilediği ve razı olduğuna izin vermesinden sonraki durum hariç."},{"n":27,"t":"Şüphesiz ki ahirete inanmayanlar, meleklere dişi isimleri takıyorlar."},{"n":28,"t":"Onların bu konuda hiçbir bilgisi yoktur. Zandan başka bir şeye uymuyorlar. Şüphesiz ki zan, gerçeklik bakımından hiçbir şey ifade etmez."},{"n":29,"t":"Zikrimizden (Kur’an’dan) yüz çeviren ve yakın (dünya) hayatından başka bir şey istemeyen kişilere aldırış etme!"},{"n":30,"t":"İşte onların bilgisi bundan ibarettir. Şüphesiz ki Rabbin -evet yalnızca O- kendi yolundan kimin saptığını çok iyi bilendir ve O kimin doğru yola ulaştığını da çok iyi bilendir."},{"n":31,"t":"Göklerde ve yerde bulunan her şey, yalnızca Allah’a aittir. En sonunda (Allah) kötülük edenleri yaptıklarıyla cezalandıracak ve güzel işler yapanları da daha güzeliyle ödüllendirecektir."},{"n":32,"t":"Ufak tefek kusurlar dışında, büyük günahlardan ve çirkinliklerden kaçınanlara gelince, Rabbinin bağışlaması çok geniştir. O, sizi topraktan yarattığı zaman ve siz annelerinizin karınlarında saklı (ceninler hâlinde) bulunduğunuz sırada (bile) sizi iyi bilendir. (Bu nedenle) kendinizi temize çıkarmayın! O, takvâlı (duyarlı) olanı iyi bilendir."},{"n":33,"t":"33-34 (Gerçeğe) sırt dönen, azıcık verip sonra vermemekte direneni bir düşün!"},{"n":34,"t":"33-34 (Gerçeğe) sırt dönen, azıcık verip sonra vermemekte direneni bir düşün!"},{"n":35,"t":"(Yoksa) gaybın (bilinemeyenin) bilgisi sadece kendi yanındadır da (bunu sadece) o mu görüyor!"},{"n":36,"t":"36-37 Yoksa Musa’nın ve çok vefalı İbrahim’in sahifelerinde bulunan(lar, ona) bildirilmedi mi?"},{"n":37,"t":"36-37 Yoksa Musa’nın ve çok vefalı İbrahim’in sahifelerinde bulunan(lar, ona) bildirilmedi mi?"},{"n":38,"t":"Hiçbir (günah) yüklüsü, başkasının (günah) yükünü yüklenemez."},{"n":39,"t":"İnsan için kendi yaptığından başka bir şey yoktur."},{"n":40,"t":"Yaptığı ileride (ahirette) görülecektir."},{"n":41,"t":"Sonra da ona karşılığı tastamam verilecektir."},{"n":42,"t":"Şüphesiz ki son (varış) sadece Rabbinedir."},{"n":43,"t":"Güldüren de yalnızca O’dur, ağlatan da."},{"n":44,"t":"Öldüren de yalnızca O’dur, dirilten de."},{"n":45,"t":"45-46 Şüphesiz ki erkek ve dişi iki eşi, atıldığı zaman nutfeden (spermden) yaratan O’dur."},{"n":46,"t":"45-46 Şüphesiz ki erkek ve dişi iki eşi, atıldığı zaman nutfeden (spermden) yaratan O’dur."},{"n":47,"t":"Şüphesiz ki diğer yaratılış (insanı diriltmek) de yalnızca O’na aittir."},{"n":48,"t":"Zengin eden de yalnızca O’dur; kısarak veren de."},{"n":49,"t":"Doğrusu Şi‘ra (yıldızı)nın Rabbi de yalnızca O’dur."},{"n":50,"t":"50-51 Şüphesiz ki önceki Âd kavmini ve Semûd’u O helak etmişti ve (onlardan) geriye hiçbir şey bırakmamıştı."},{"n":51,"t":"50-51 Şüphesiz ki önceki Âd kavmini ve Semûd’u O helak etmişti ve (onlardan) geriye hiçbir şey bırakmamıştı."},{"n":52,"t":"Daha önce Nuh kavmini de (O helak etmişti). Şüphesiz ki onlar haksızlık etmiş ve azgınlık yapmışlardı."},{"n":53,"t":"Alt üst olan şehirleri de O yok etmişti."},{"n":54,"t":"Böylece kuşatan şey (felaket) onları da kuşatmıştı."},{"n":55,"t":"Rabbinin hangi nimetleri hakkında şüphe duyabilirsin ki!"},{"n":56,"t":"İşte bu, önceki uyarılardan bir uyarıdır."},{"n":57,"t":"Yaklaşmakta olan (Son Saat) yaklaştı."},{"n":58,"t":"Onu (zamanını) Allah’tan başka kimse açığa çıkaramaz."},{"n":59,"t":"Şimdi siz bu sözü mü tuhaf buluyorsunuz!"},{"n":60,"t":"Gülüyorsunuz; ağlamıyorsunuz."},{"n":61,"t":"Siz oyalanıyorsunuz!"},{"n":62,"t":"Allah için secde edin ve (O’na) kulluk edin!"}],[{"n":1,"t":"O (Son) Saat yaklaşmıştır ve (o zaman geldiğinde) ay yarılmış (olacak)tır."},{"n":2,"t":"Bir ayet (mucize) görseler bile hemen yüz çevirir ve “Bu da sıradan bir büyüdür!” derler."},{"n":3,"t":"Kendi arzularına uyarak (gerçeği) yalanladılar. (Oysa) her iş amacına ulaşacaktır."},{"n":4,"t":"4-5 Yemin olsun ki onlara tastamam doğru hükümler içeren, (kendilerini) kötülükten engelleyecek haberler gelmiştir. (Yüz çevirene) uyarılar yarar sağlamaz."},{"n":5,"t":"4-5 Yemin olsun ki onlara tastamam doğru hükümler içeren, (kendilerini) kötülükten engelleyecek haberler gelmiştir. (Yüz çevirene) uyarılar yarar sağlamaz."},{"n":6,"t":"Sen de onlardan yüz çevir! Bir çağrıcının hoş görülmeyecek bir şeye çağıracağı gün,"},{"n":7,"t":"Etrafa yayılmış çekirgeler gibi bakışları perişan bir hâlde mezarlardan çıkacaklar."},{"n":8,"t":"Boyunlarını (o) çağrıcıya uzatan kâfirler, “Bu, ne zor bir günmüş!” diyecekler."},{"n":9,"t":"Onlardan önce Nuh’un halkı da (gerçeği) yalanlamış, kulumuzu yalanlayarak “(O) cinlenmiştir.” demişlerdi. (Tebliğden vazgeçirilmeye) zorlanmıştı."},{"n":10,"t":"(Nuh) Rabbine “Yenik düştüm, yardım et!” diyerek yalvarmıştı."},{"n":11,"t":"Biz de boşanan bir su ile göğün kapılarını açmıştık."},{"n":12,"t":"Yerden de (su) kaynakları fışkırtmıştık. Böylece (bu iki) su, belirlenmiş bir iş (tufan) için birleşmişti."},{"n":13,"t":"Onu (Nuh’u) levhalar ve çivilerle (çakılmış gemide) taşımıştık."},{"n":14,"t":"(O gemi) inkar edilmiş olana (Nuh’a) bir karşılık olarak gözlerimizin önünde akıp gidiyordu."},{"n":15,"t":"Yemin olsun ki onu (gemiyi) bir ibret olarak bırakmıştık; hani gerçeği hatırlayan var mı?"},{"n":16,"t":"Benim azabım ve benim uyarılarım (bak) nasıl olmuştu!"},{"n":17,"t":"Yemin olsun ki Kur’an’ı (gerçeği) hatırla(t)mak için kolaylaştırdık. Hatırlayan var mı?"},{"n":18,"t":"Âd (halkı) da (Hud’u) yalanlamıştı. Benim azabım ve benim uyarılarım (bak) nasıl olmuştu!"},{"n":19,"t":"19-20 Sürekliliği olan kara bir günde onların üzerine, insanları sökülmüş hurma kütükleri gibi yere seren bir kasırga göndermiştik."},{"n":20,"t":"19-20 Sürekliliği olan kara bir günde onların üzerine, insanları sökülmüş hurma kütükleri gibi yere seren bir kasırga göndermiştik."},{"n":21,"t":"Benim azabım ve benim uyarılarım (bak) nasıl olmuştu!"},{"n":22,"t":"Yemin olsun ki Kur’an’ı (gerçeği) hatırla(t)mak için kolaylaştırdık. Hatırlayan var mı?"},{"n":23,"t":"23-24 Semûd (kavmi) de uyarı(cı)ları yalanlamıştı ve “Aramızdan bir insana mı uyacağız? Bu durumda biz sapkınlık ve çılgınlık içinde oluruz!” demişlerdi."},{"n":24,"t":"23-24 Semûd (kavmi) de uyarı(cı)ları yalanlamıştı ve “Aramızdan bir insana mı uyacağız? Bu durumda biz sapkınlık ve çılgınlık içinde oluruz!” demişlerdi."},{"n":25,"t":"(Devamla:) “Vahiy, aramızdan ona mı verildi? Aslında o, şımarık yalancının biridir!” demişlerdi."},{"n":26,"t":"Yarın (yakında) onlar şımarık yalancının kim olduğunu göreceklerdir."},{"n":27,"t":"(Ey Salih)! Onları imtihan etmek için dişi devenin göndericileri biziz (onu biz belirledik). Sen onları sadece gözetle ve sabırlı olmaya devam et!"},{"n":28,"t":"Onlara, her biri kendi nöbetinde sudan yararlanacak şekilde suyun aralarında paylaşılarak kullanılacağını bildir!"},{"n":29,"t":"Onlar arkadaşlarını çağırmışlar, (içlerinden biri) hemen ileri atılmış ve deveyi vahşice katletmişti."},{"n":30,"t":"Benim azabım ve benim uyarılarım (bak) nasıl olmuştu!"},{"n":31,"t":"(Deveyi kesince) biz de üzerlerine korkunç bir ses göndermiştik. Anında ağıla konulan kuru ot gibi olmuşlardı."},{"n":32,"t":"Yemin olsun ki Kur’an’ı (gerçeği) hatırla(t)mak için kolaylaştırdık. Hatırlayan var mı?"},{"n":33,"t":"Lut’un halkı da uyarıları yalanlamıştı."},{"n":34,"t":"34-35 Lut’un ailesi (destekçileri) hariç, üzerlerine taş göndermiştik (yağdırmıştık). Onları (Lut’un destekçilerini) ise katımızdan bir nimet olarak seher vakti kurtarmıştık. Biz şükredenin karşılığını işte böyle veririz."},{"n":35,"t":"34-35 Lut’un ailesi (destekçileri) hariç, üzerlerine taş göndermiştik (yağdırmıştık). Onları (Lut’un destekçilerini) ise katımızdan bir nimet olarak seher vakti kurtarmıştık. Biz şükredenin karşılığını işte böyle veririz."},{"n":36,"t":"Yemin olsun ki yakalamamızla ilgili (Lut daha önceden) kendilerini uyarmıştı, (ama) onlar bu tehditleri kuşkuyla karşılamışlardı."},{"n":37,"t":"Yemin olsun ki onlar (Lut’un) misafirlerinden (ahlaksızca) yararlanmak bile istemişlerdi de gözlerini kör etmiştik. (Kendilerine) “Benim azabımı ve benim uyarılarım(a itibar etmemenizin sonucunu) tadın!” (demiştik)."},{"n":38,"t":"Bir sabah erkenden onları kararlı bir azap yakalamıştı."},{"n":39,"t":"(Kendilerine) “Azabımı ve uyarılarım(a itibar etmemenizin sonucunu) tadın!” (demiştik)."},{"n":40,"t":"Yemin olsun ki Kur’an’ı (gerçeği) hatırla(t)mak için kolaylaştırdık. Hatırlayan var mı?"},{"n":41,"t":"Şüphesiz ki Firavun’un ailesine (destekçilerine) de uyarı(cı)lar gelmişti."},{"n":42,"t":"(Fakat) onlar da bütün ayetlerimizi yalanlamışlardı. (Bunun üzerine) biz de onları, güç ve kudretimize uygun bir şekilde yakalamıştık."},{"n":43,"t":"Sizin kâfirleriniz onlardan daha mı iyidir? Yoksa sizin için kitaplarda (azaptan) uzak olma (bilgisi) mi var!"},{"n":44,"t":"Yoksa “Biz güçlü bir topluluğuz!” mu diyorlar?"},{"n":45,"t":"O topluluk, ileride bozguna uğratılacak ve arkalarını dönüp kaçacaklardır."},{"n":46,"t":"Aslında o (Son) Saat, onların buluşma zamanıdır ve o (Son) Saat daha dehşetlidir; daha acıdır."},{"n":47,"t":"Şüphesiz ki suçlular sapkınlık ve çılgınlık içindedir."},{"n":48,"t":"O gün ateşe yüzüstü sürüklenip (kendilerine) “Sekar (cehennemin)in dokunuşunu tadın!” (denecektir)."},{"n":49,"t":"Şüphesiz ki biz her şeyi bir ölçüyle yarattık."},{"n":50,"t":"Bizim (Son Saat) emrimiz, sadece göz açıp kapamak gibi tektir (bir anda olur)."},{"n":51,"t":"Yemin olsun ki sizin gibi grupları helak etmiştik. Hatırlayan var mı?"},{"n":52,"t":"Yaptıkları her şey kitaplarda (amel defterlerinde) mevcuttur."},{"n":53,"t":"Küçük büyük her şey satır satır yazılmıştır."},{"n":"54-55","t":"Muttakîler (duyarlı olanlar) ise güçlü hükümdarın (Allah’ın) huzurunda ‘doğruluk makamındaki’ bahçelerde ve ırmak(ların kenarların)da olacaklardır."}],[{"n":1,"t":"Rahmân."},{"n":2,"t":"Kur’an’ı (O) öğretti."},{"n":3,"t":"İnsanı (O) yarattı."},{"n":4,"t":"Açıklamayı (insana O) öğretti."},{"n":5,"t":"Güneş ve ay bir hesaba göre (hareket etmekte)dir."},{"n":6,"t":"Bitkiler ve ağaçlar da secde etmektedir."},{"n":7,"t":"7-8 (Allah) göğü yükseltmiş ve dengeyi bozmayasınız diye (oraya) bir denge koymuştur."},{"n":8,"t":"7-8 (Allah) göğü yükseltmiş ve dengeyi bozmayasınız diye (oraya) bir denge koymuştur."},{"n":9,"t":"Ölçüyü adaletle yerine getirin ve eksik tartmayın!"},{"n":10,"t":"(Allah) yeri canlılar için yaratmıştır."},{"n":11,"t":"11-12 Orada meyveler, salkımlı hurma ağaçları, yapraklı taneler ve güzel kokulu bitkiler vardır."},{"n":12,"t":"11-12 Orada meyveler, salkımlı hurma ağaçları, yapraklı taneler ve güzel kokulu bitkiler vardır."},{"n":13,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":14,"t":"(Allah) insanı, pişmiş çamur gibi ses çıkaran bir balçıktan yarattı."},{"n":15,"t":"Cinleri de ateşten bir karışımdan yarattı."},{"n":16,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":17,"t":"(Allah) iki doğunun da Rabbidir, iki batının da Rabbidir."},{"n":18,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":19,"t":"(Allah) iki denizi salmıştır; birbirlerine kavuşurlar."},{"n":20,"t":"Aralarında bir engel vardır; birbirine karışmazlar."},{"n":21,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":22,"t":"İkisinden de inci ve mercan çıkar."},{"n":23,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":24,"t":"Denizde (akıp giden), dağlar gibi büyük gemiler de yalnızca O’na aittir."},{"n":25,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":26,"t":"Oradaki (dünyadaki) herkes fanidir."},{"n":27,"t":"Rabbinin yücelik ve cömertlik sahibi (olan) yüzü (zatı) sonsuz olacaktır."},{"n":28,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":29,"t":"Göklerde ve yerdeki herkes O’ndan ister. O, her gün (her an) bir iştedir."},{"n":30,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":31,"t":"Ey iki ağırlık sahipleri (cinler ve insanlar)! İleride size yöneleceğiz."},{"n":32,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":33,"t":"Ey cin ve insan topluluğu! Göklerin ve yerin sınırlarından geçip gitmeye gücünüz yetiyorsa geçip gidin! (Allah’ın ikram edeceği) büyük bir güç olmadan geçip gidemezsiniz."},{"n":34,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":35,"t":"Üzerinize ateşten bir alev ve bir duman gönderilir ve (hiçbir yerden) yardım da alamazsınız."},{"n":36,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":37,"t":"Gök yarılıp da yağ gibi kırmızı gül (rengini) aldığı zaman (haliniz nasıl olacak)!"},{"n":38,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":39,"t":"İşte o gün kişinin günahından, (başka) hiçbir insan ve cin sorumlu tutulmayacaktır."},{"n":40,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":41,"t":"Suçlular yüzlerinden tanınacaktır; perçemlerinden ve ayaklarından alınacak (yakalanacak)lardır."},{"n":42,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":43,"t":"İşte bu, suçluların yalanladığı cehennemdir."},{"n":44,"t":"Onlar onunla (cehennemle) kaynar su arasında gidip geleceklerdir."},{"n":45,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":46,"t":"Rabbinin makamın(da yargılanmak)tan korkanlara iki cennet vardır."},{"n":47,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":48,"t":"(İki cennet de) rengârenktir."},{"n":49,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":50,"t":"İkisinde de akıp giden iki kaynak vardır."},{"n":51,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":52,"t":"İkisinde de her türlü meyveden çiftler vardır."},{"n":53,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":54,"t":"(Cennetlikler) içleri ipek kumaştan oluşan döşeklere yaslanmış olacaklardır. İki cennetin meyveleri (cennetliklere) yakındır."},{"n":55,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":56,"t":"Oralarda (cennetlerde) bakışlarını (yalnızca eşlerine) kısanlar (çevirenler) var ki onlardan (cennetliklerden) önce kendilerine hiçbir insan ve cin dokunmamıştır."},{"n":57,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":58,"t":"Onlar (cennetteki eşleri) yakut ve mercan gibidir."},{"n":59,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":60,"t":"İyiliğin karşılığı iyilikten başka nedir ki!"},{"n":61,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":62,"t":"Bu ikisinden başka iki cennet daha vardır."},{"n":63,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":64,"t":"(Bu cennetler) koyu yeşildir."},{"n":65,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":66,"t":"İkisinde de fışkırmakta olan iki kaynak vardır."},{"n":67,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":68,"t":"İkisinde de her türlü meyve, hurma ve nar vardır."},{"n":69,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":70,"t":"Oralarda (cennetlerde) güzel hayırlılar (eşler) vardır."},{"n":71,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":72,"t":"Otağlar (çadırlar) içinde (cennetliklere) özel huriler (vardır)."},{"n":73,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":74,"t":"Onlardan (cennetliklerden) önce kendilerine hiçbir insan ve cin dokunmamıştır."},{"n":75,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":76,"t":"(Orada) yeşil çimenlere ve çok güzel yaygılara (halılara) yaslanmış bir hâlde (olacaklar)dır."},{"n":77,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz ki!"},{"n":78,"t":"Yücelik ve cömertlik sahibi Rabbinin adı yüceler yücesidir."}],[{"n":1,"t":"O olay (Son Saat) gerçekleştiği zaman,"},{"n":2,"t":"Meydana gelişini yalanlayan kimse olmayacaktır."},{"n":3,"t":"(O, bazılarını) alçaltıcı, (bazılarını) yükselticidir."},{"n":"4-7","t":"Yer şiddetle sarsıldığı, dağlar tamamen parçalanıp toz duman hâline geldiği, (mahşerde) siz üç eş (grup) olacağınız zaman,"},{"n":8,"t":"Sağın halkı, ne mutlu insanlardır o sağın halkı!"},{"n":9,"t":"Solun halkı, ne mutsuz insanlardır o solun halkı!"},{"n":10,"t":"(Ahirette) önde olanlar, (dünyada fedakârlıkta da) önde olanlardır."},{"n":11,"t":"11-12 Bu kişiler, nimet cennetlerinde (Allah’a) yakınlaştırılanlardır."},{"n":12,"t":"11-12 Bu kişiler, nimet cennetlerinde (Allah’a) yakınlaştırılanlardır."},{"n":13,"t":"Çoğu önceki (ümmet)lerdendir."},{"n":14,"t":"Birazı da sonraki (ümmet)lerdendir."},{"n":"15-16","t":"Karşılıklı olarak yaslanacakları mücevherlerle işlenmiş tahtlar üzerinde (ağırlanacaklar)dır."},{"n":"17-18","t":"Çevrelerinde, kaynağından çıkan (suyla dolu) testiler, ibrikler ve kadehler bulunan uzun ömürlü gençler dolaşır."},{"n":19,"t":"O (içtiklerinden) dolayı başları ağrıtılmaz; sarhoş da olmazlar."},{"n":20,"t":"Tercih ettikleri meyve(ler),"},{"n":21,"t":"Canlarının çektiği kuş et(ler)i,"},{"n":"22-24","t":"Saklı inciler gibi güzel gözlü huriler yaptıklarının bir karşılığı olarak kendilerine (verilecektir)."},{"n":"25-26","t":"O (cennet)lerde “Selam, selam”dan başka bir söz de günaha sokan bir (laf) da duymazlar."},{"n":27,"t":"Sağın halkı, ne mutlu insanlardır o sağın halkı!"},{"n":28,"t":"(İşte onlar) düzgün (dalbastı) kiraz ağacında,"},{"n":29,"t":"Meyveleri kat kat muz ağaçları(n)da,"},{"n":30,"t":"Uzamış gölge(lik)te,"},{"n":31,"t":"Çağlayarak akan sularda,"},{"n":"32-33","t":"Kesilmeyen (tükenmeyen) ve engellenemeyen sayısız meyve(lik)lerde (ağırlanacaklardır)."},{"n":"34-37","t":"(Uyumlu), yepyeni olarak şekillendirdiğimiz ve tamamen yeni bir yaratılışla oluşturduğumuz kabartılmış döşeklerde (onlara ödüller verilecektir)."},{"n":"38-40","t":"(Bütün bunlar) bir bölümü önceki (ümmet)lerden, bir bölümü de sonrakilerden oluşan sağın halkı içindir."},{"n":41,"t":"Solun halkı, ne mutsuz insanlardır o solun halkı!"},{"n":"42-44","t":"(Onlar) içlerine işleyen bir ateş ve kaynar su ile serinliği de rahatlatması da olmayan zifiri bir karanlığın içinde olacaklardır."},{"n":45,"t":"Şüphesiz ki onlar bundan önce (dünyada) şımartılmışlardı."},{"n":46,"t":"Büyük günahı (şirki) işlemekte ısrar ediyorlar."},{"n":"47-48","t":"Şöyle diyorlardı: “Hem biz hem de önceki atalarımız, ölüp toprak ve kemik hâline geldikten sonra (yeniden) diriltilecekmişiz, öyle mi?”"},{"n":49,"t":"De ki: “Hem öncekiler (atalarınız) hem de sonrakiler,"},{"n":50,"t":"Bilinen bir günün belirlenen vaktinde mutlaka toplanacaksınız.”"},{"n":51,"t":"Sonra siz ey yalancı sapkınlar!"},{"n":"52-53","t":"Elbette zakkum ağacından yiyenler ve karınlar(ını) ondan dolduranlar (olacaksınız)."},{"n":"54-55","t":"Üzerine (bir) de susamış develer(in su içişi) gibi insanın içine işleyen kaynar sudan içeceksiniz."},{"n":56,"t":"Hesap gününde onların ağırlanması(!) böyle (olacak)tır!"},{"n":57,"t":"Sizi biz yaratmıştık. (Gerçekleri) onaylamanız gerekmez miydi?"},{"n":58,"t":"Atmakta olduğunuz meniyi (spermi) hiç düşündünüz mü?"},{"n":59,"t":"Onu siz mi yaratıyorsunuz; yoksa yaratanlar biz miyiz?"},{"n":"60-61","t":"Aranızda ölümü belirleyen biziz. Sizi, benzerlerinizle değiştirmemiz ve yine sizi bilemeyeceğiniz şekilde (ahirette) yeniden yaratmamızda kimse bizim önümüze geçemez."},{"n":62,"t":"Üstelik ilk yaratılışı biliyorsunuz. (Buna rağmen gerçeği) hatırlamanız gerekmez mi?"},{"n":63,"t":"Ektiğinizi (tohumu) düşündünüz mü hiç?"},{"n":64,"t":"Onu siz mi yetiştiriyorsunuz; yoksa yetiştiren biz miyiz?"},{"n":"65-67","t":"Dileseydik onu kuru bir çöp yapardık da “Şüphesiz ki borçlandık (zarardayız); dahası biz (üründen) mahrum bırakıldık!” diyerek şaşar kalırdınız."},{"n":68,"t":"İçmekte olduğunuz suyu düşündünüz mü hiç?"},{"n":69,"t":"Onu bulutlardan siz mi indirdiniz; yoksa indirenler biz miyiz?"},{"n":70,"t":"Dileseydik onu da tuzlu yapardık. Şükretmeniz gerekmez mi?"},{"n":71,"t":"Tutuşturmakta olduğunuz ateşi hiç düşündünüz mü?"},{"n":72,"t":"Onun ağacını siz mi yetiştirdiniz; yoksa oluşturanlar biz miyiz?"},{"n":73,"t":"İşte, biz onu (ağacı, gerçeğin) hatırlatması ve ihtiyacı olanlar için geçimlik yaptık."},{"n":74,"t":"Yüce Rabbinin adını tesbih et (yücelt)!"},{"n":75,"t":"Hayır! Nücûm’un yerlerine yemin ederim."},{"n":76,"t":"Bilirseniz şüphesiz ki bu büyük bir yemindir."},{"n":77,"t":"Şüphesiz ki bu değerli bir Kur’an’dır."},{"n":78,"t":"Saklı bir kitaptadır."},{"n":79,"t":"Ona arındırılmış (melek)lerin dışında kimse dokunamaz."},{"n":80,"t":"Alemlerin Rabbinden indir(il)medir."},{"n":81,"t":"Siz bu sözü küçümsüyor musunuz?"},{"n":82,"t":"Rızkınızı yalanlamaya dönüştürüyorsunuz?"},{"n":83,"t":"Peki (ya can) boğaza dayandığı zaman (haliniz nasıl olacak)!"},{"n":84,"t":"O zaman siz (ölmekte olan kişiye) bakar durursunuz."},{"n":85,"t":"Biz ona sizden daha yakınız fakat siz göremezsiniz."},{"n":"86-87","t":"Mademki hesaba çekilmeyeceksiniz, doğruysanız (ölmekte olanı geri) döndürsenize!"},{"n":"88-89","t":"(Ölen kişi Allah’a) yakınlaştırılanlardan ise ona rahatlık, güzel rızık ve nimet cenneti vardır."},{"n":"90-91","t":"Sağın halkından ise (kendisine) “Sana (senin gibi olan) sağın halkından selam olsun!” (denecektir)."},{"n":"92-94","t":"Sapkınlık yapan, yalanlayanlardan ise ona da kaynar sudan bir ziyafet(!) ve cehenneme yaslanma vardır."},{"n":95,"t":"İşte bu, gerçeğin ta kendisidir."},{"n":96,"t":"Yüce Rabbinin adını tesbih et (yücelt)!"}],[{"n":1,"t":"Göklerde ve yerde bulunan her şey Allah’ı tesbih etmektedir (yüceltmektedir). O güçlüdür, doğru hüküm verendir."},{"n":2,"t":"Göklerin ve yerin otoritesi yalnızca O’na aittir. Diriltir, öldürür. O her şeye gücü yetendir."},{"n":3,"t":"O ilktir, sondur; apaçıktır, içkindir. O her şeyi bilendir."},{"n":4,"t":"O, gökleri ve yeri altı günde (dönemde) yaratandır; sonra da arşa istiva edendir. Yerin içine gireni ve ondan çıkanı, gökten ineni ve oraya yükseleni bilir. Nerede olursanız olun, O sizinle beraberdir. Allah yaptıklarınızı görendir."},{"n":5,"t":"Göklerin ve yerin otoritesi yalnızca O’na aittir. Bütün işler yalnızca Allah’a döndürülecektir."},{"n":6,"t":"Geceyi gündüzün içine koyuyor, gündüzü de gecenin içine koyuyor. O göğüslerin (kalplerin) özünü bilendir."},{"n":7,"t":"Allah’a ve Elçisine inanıp güvenin! Sizi, kendisinde yetkili kıldığı şeylerden (mallardan) infak edin (verin)! Sizden güvenenler ve infak edenler (verenler) için büyük ödül vardır."},{"n":8,"t":"Elçi sizi Rabbinize inanıp güvenmeye çağırdığı hâlde niçin Allah’a inanıp güvenmiyorsunuz? İnanıyorsanız o, sizden kesin bir söz de almıştı."},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna (Elçiye) apaçık ayetler indiren O’dur. Şüphesiz ki Allah size çok şefkatlidir, çok merhametlidir."},{"n":10,"t":"Size ne oluyor da Allah yolunda infak etmiyorsunuz (vermiyorsunuz)? (Oysa) göklerin ve yerin mirası, yalnızca Allah’a aittir. İçinizden zaferden önce infak eden (veren) ve savaşan(lar, diğerleriyle) eşit değildir. Onların derecesi, sonradan infak edenlerden (verenlerden) ve savaşanlardan daha üstündür. Allah hepsine en güzel olanı (cenneti) vadetmiştir. Allah yapmakta olduklarınızdan haberdardır."},{"n":11,"t":"Kim Allah’a güzel bir borç verirse (Allah) da karşılığını ona kat kat verir; onun için değerli bir ödül de vardır."},{"n":12,"t":"Mümin erkeklerle mümin kadınları, (kendilerini aydınlatan) nûrlarının (ışıklarının) önlerinde ve sağlarında koşarken gördüğün günde, (onlara) “Bugün müjdeniz, içlerinde ebedî kalıcılar olarak (kalacağınız), altlarından ırmaklar akan cennetlerdir.” (denecektir). Asıl büyük kurtuluş işte budur!"},{"n":13,"t":"Münafık erkeklerle münafık kadınların müminlere “Bizi bekleyin, nûrunuzdan (ışığınızdan) bir parça nûr (ışık) alalım.” diyeceği günde (kendilerine) “Arkanıza dönün de (orada) bir nûr (ışık) arayın!” denecektir. Onların arasına içinde merhamet, dışında azap bulunan kapılı bir sur çekilmiş (olacak)tır."},{"n":14,"t":"(Münafıklar) onlara (müminlere) “Biz sizinle birlikte değil miydik?” diye sesleneceklerdir. (Müminler de) şöyle diyeceklerdir: “Evet ancak siz kendinizi fitneye soktunuz, beklediniz, şüpheye düştünüz ve Allah’ın emri (ölüm) gelip çatıncaya kadar kuruntular sizi aldattı; o çok aldatan (şeytan) sizi Allah ile aldattı.”"},{"n":15,"t":"Bugün artık sizden (münafıklardan) da kâfir olanlardan da fidye kabul edilmez. Barınağınız ateştir. Size layık olan odur. Ne kötü varış yeridir (orası)!"},{"n":16,"t":"İman edenlerin kalplerinin Allah’ı anmaya ve (O’nun katından) inen gerçeğe (Kur’an’a) boyun eğme zamanı gelmedi mi? Onlar (müminler), daha önce kendilerine kitap verilenler gibi olmasınlar! Zira üzerinden uzun zaman geçmişti de kalpleri katılaşmıştı. İçlerinden çoğu da yoldan çıkmıştı."},{"n":17,"t":"Bilin ki ölümünden sonra yeri canlandıran şüphesiz ki Allah’tır. Akıl edesiniz diye ayetleri size elbette açıkladık."},{"n":18,"t":"(Gerçeği) doğrulayan erkeklere ve kadınlara, Allah’a güzel bir borç vermiş (olanlara) (verdiklerinin karşılığı) kat kat ödenecektir; onlara değerli ödül de vardır."},{"n":19,"t":"Allah’a ve elçilerine iman edenler -evet sadece onlar- (gerçeği) çok doğrulayanlardır ve Rableri katında şahit olanlardır. (Mahşerde) onlar için ödülleri ve nûrları (ışıkları) vardır. İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar da cehennem halkıdır."},{"n":20,"t":"Bilin ki dünya hayatı, sadece bir oyun, bir eğlence, bir süs, aranızda bir övünme, mal ve çocuk sahibi olma (yarışın)dan ibarettir. (Bu hayat), tıpkı bir yağmur gibidir; (yetiştirdiği) ürünleri çiftçilerin hoşuna gider. Sonra (o ekinler) kurur; sen onun sararmış olduğunu görürsün; sonra da (o ekinler) kuru bir kırıntı (çer çöp) olur. Ahirette (inkârcılar için) şiddetli bir azap vardır. (Müminler için ise) Allah’ın bağışlaması ve rızası vardır. Dünya hayatı, aldatıcı bir geçimlikten başka bir şey değildir."},{"n":21,"t":"Rabbinizden bir bağışlanmaya ve Allah’a ve elçilerine inananlar için hazırlanacak, genişliği gökle yerin genişliği gibi olan cennete koşun! İşte bu, Allah’ın dilediğine (layık olana) verdiği lütfudur. Allah büyük lütuf sahibidir."},{"n":22,"t":"Yerde ve bizzat insanların kendilerinde meydana gelen herhangi bir musibet yoktur ki biz onu yaratmadan önce bir kitapta (kanunda kayıtlı) olmasın! Şüphesiz ki bu, Allah’a çok kolaydır."},{"n":23,"t":"Elinizden çıkana üzülmeyesiniz ve (Allah’ın) size verdiği nimetlerle şımarmayasınız diye (Allah bu kanunu belirlemiştir). Allah kendini beğenmiş övünüp duranları sevmez."},{"n":24,"t":"Onlar, cimrilik edip insanlara da cimriliği emredenlerdir. Kim yüz çevirirse şüphesiz ki yalnızca Allah zengindir, hamde (övgüye) layık olandır."},{"n":25,"t":"Şüphesiz ki biz, elçilerimizi apaçık delillerle gönderdik ve insanların adaleti yerine getirmeleri için beraberlerinde Kitabı ve ölçüyü indirdik. Biz demiri de indirdik (kullanımını öğrettik) ki onda, büyük bir güç ve insanlar için yararlar vardır. Bu, Allah’(ın dinin)e ve elçilerine yalnızken yardım edenleri bil(dir)mesi (ortaya çıkarması) içindir. Şüphesiz ki Allah kuvvetlidir, güçlüdür."},{"n":26,"t":"Yemin olsun ki biz Nuh’u ve İbrahim’i (peygamber olarak) göndermiştik; onların soyuna da (bazı kişilere) peygamberlik ve Kitap vermiştik. Onlardan (insanlardan) kimi doğru yoldadır. İçlerinden çoğu da yoldan çıkmıştı."},{"n":27,"t":"Sonra bunların izinden art arda elçilerimizi göndermiştik. Meryem oğlu İsa’yı da arkalarından göndermiş, ona İncil’i vermiştik. Ona uyanların kalplerine şefkat ve merhamet yerleştirmiştik. Uydurdukları ruhbanlığa gelince, onu onlara biz yazmamıştık. Fakat kendileri, Allah rızasını kazanmak için yapmış, (ancak) buna da gerektiği gibi uymamışlardı. Biz de onlardan iman edenlere ödüllerini vermiştik. İçlerinden çoğu yoldan çıkmıştı."},{"n":28,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun ve Elçisine inanıp güvenin ki O (Allah da), size rahmetinden iki kat versin; size sayesinde yürüyeceğiniz bir nûr (ışık) versin ve sizi bağışlasın! Allah çok bağışlayandır, çok merhametlidir."},{"n":29,"t":"Kitap ehli, Allah’ın lütfundan hiçbir şey elde edemeyeceklerini, lütfun tamamen Allah’ın elinde olduğunu, onu dilediğine (layık olana) vereceğini bilmezlik etmesinler. Allah büyük lütuf sahibidir."}],[{"n":1,"t":"Eşi hakkında seninle tartışan ve Allah’a şikâyette bulunan (kadın)ın sözünü Allah elbette duymuştur. Allah sizin konuşmanızı duymaktadır. Şüphesiz ki Allah duyandır, görendir."},{"n":2,"t":"İçinizden eşlerine zıhar yapanların kadınları, onların anneleri değildir. Onların anneleri ancak kendilerini doğuran (kadın)lardır. Şüphesiz ki onlar çirkin bir söz ve yalan söylüyorlar. Şüphesiz ki Allah çok affedicidir, çok bağışlayandır."},{"n":3,"t":"Kadınlara zıhar yapıp sonra söylediklerinden dönenlerin, eşleriyle (cinsel olarak) birleşmeden önce bir köleyi özgürlüğe kavuşturmaları (gerekir). Size öğütlenen budur. Allah yaptıklarınızdan haberdardır."},{"n":4,"t":"(Buna imkân) bulamayan(lar), (eşleriyle cinsel olarak) birleşmeden önce art arda iki ay oruç (tutar). (Buna da) gücü yetmeyen, altmış yoksulu doyurmak (zorundadır). Bu (kolaylaştırma), Allah’a ve Elçisine inanmanız nedeniyledir. İşte şu(nlar), Allah’ın (koyduğu) sınırlarıdır. Kâfirler için elem verici bir azap vardır."},{"n":5,"t":"Allah’a ve Elçisine karşı gelenler, kendilerinden öncekilerin tepelendiği gibi tepelenmiş (olacaklar)dır. (Oysa hepsine) apaçık ayetler indirmişizdir. Kâfirler için küçük düşürücü bir azap vardır."},{"n":6,"t":"O gün, Allah onların hepsini diriltecek ve (dünyada) yaptıklarını kendilerine bildirecektir. Allah onların unuttuğu şey(ler)i bir bir sayıp dökmüş (olacak)tır. Allah her şeye şahittir."},{"n":7,"t":"Göklerde ve yerde olanları Allah’ın bildiğini görmüyor musun? Üç kişinin gizli konuştuğu (yerde) dördüncüsü mutlaka O’dur. Beş kişinin gizli konuştuğu (yerde) altıncısı mutlaka O’dur. Bunlardan daha az veya daha çok olsunlar, nerede olurlarsa olsunlar mutlaka O onlarla beraberdir. Sonra kıyamet günü (dünyada) yaptıklarını onlara bildirecektir. Şüphesiz ki Allah her şeyi bilendir."},{"n":8,"t":"Gizli konuşmaktan engellendikten sonra yine o yasaklananı yapmaya kalkışarak günah, düşmanlık ve Elçi'ye isyan konusunda gizlice konuşanları görmedin mi? Onlar sana geldikleri zaman, seni Allah’ın selamlamadığı şekilde selamlıyorlar. Kendi içlerinden de “Bu söylediklerimiz yüzünden Allah’ın bize azap etmesi gerekmez miydi?” diyorlar. Onlara cehennem yeter. Oraya gireceklerdir. Ne kötü varış yeridir (orası)!"},{"n":9,"t":"Ey iman edenler! Aranızda özel konuşacağınız zaman günah, düşmanlık ve Elçi'ye isyan konusunda gizlice konuşmalar yapmayın! İyilik ve takvâyı (duyarlılığı) konuşun! Yalnızca kendi huzuruna toplanacağınız Allah’a karşı takvâlı (duyarlı) olun!"},{"n":10,"t":"Gizli konuşmalar sadece şeytandandır. Bu, iman edenleri üzmek içindir. Allah’ın izni olmadıkça (şeytan onlara) hiçbir zarar veremez. Müminler yalnızca Allah’a güvensinler!"},{"n":11,"t":"Ey iman edenler! Size “Meclislerde yer açın!” denince yer açın ki Allah da size genişlik versin. Size “Kalkın!” denince kalkın ki Allah da içinizden inananları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah yaptıklarınızdan haberdardır."},{"n":12,"t":"Ey iman edenler! Elçi ile özel bir şey konuşacağınız zaman bu özel konuşmanızdan önce bir sadaka verin! Bu, sizin için daha hayırlı ve daha temizdir. (Sadaka verecek imkân) bulamazsanız, şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":13,"t":"(Elçi ile) gizli (özel) görüşmenizden önce sadakalar vermekten çekindiniz mi? Bunu yapamadığınıza ve Allah da sizi affettiğine göre namazı kılın, zekâtı verin; Allah’a ve Elçisine itaat edin! Allah yaptıklarınızdan haberdardır."},{"n":14,"t":"Allah’ın kendilerine gazap ettiği bir topluluğu dost edinenleri görmedin mi? Onlar (münafıklar) ne sizdendir ne de onlardan. Bilerek yalan yere yemin ediyorlar."},{"n":15,"t":"Allah onlara şiddetli bir azap hazırlamış (olacak)tır. Şüphesiz ki onların yaptıkları çok kötüdür!"},{"n":16,"t":"Yeminlerini kalkan (bahane) edinip Allah yolundan saptılar. Onlara küçük düşürücü bir azap vardır."},{"n":17,"t":"Onların malları da çocukları da Allah(’ın azabına karşı) kendilerine hiçbir şeyde asla yarar sağlamayacaktır. İşte onlar ateş halkıdır; onlar orada ebedî kalacaklardır."},{"n":18,"t":"O gün Allah onların hepsini yeniden diriltecektir. Onlar (dünyada) size yemin ettikleri gibi (mahşerde de) O’na (Allah’a yalan yere) yemin edeceklerdir. Kendilerinin bir şey üzerinde olduklarını sanırlar. Dikkat edin! Şüphesiz ki onlar yalancıların ta kendileridir."},{"n":19,"t":"Şeytan onları etkisi altına aldı ve kendilerine Allah’ı anmayı unutturdu. İşte onlar şeytanın tarafındadır. Dikkat edin! Şeytanın tarafı(nda olanlar) kaybedenlerin ta kendileridir."},{"n":20,"t":"Şüphesiz ki Allah’a ve Elçisine karşı gelenler, işte onlar en alçakların arasındadır."},{"n":21,"t":"Allah “Ben -elbette ben- ve elçilerim şüphesiz ki galip geleceğiz.” diye yazmıştır. Şüphesiz ki Allah kuvvetlidir, güçlüdür."},{"n":22,"t":"Allah’a ve ahiret gününe inanan bir toplumun, Allah’a ve Elçisine karşı gelenlerle –babaları veya çocukları veya kardeşleri veya akrabaları da olsa– dostluk ettiğini göremezsin. İşte (Allah) onların kalbine iman yazmış ve katından bir rûh (Kur’an) ile onları desteklemiştir. (Allah) onları içlerinde ebedî kalacakları, altlarından ırmaklar akan cennetlere koyacaktır. Allah kendilerinden razı, onlar da O’ndan memnun olmuşlardır. İşte onlar Allah’ın tarafındadır. Dikkat edin! Allah’ın tarafı(nda olanlar) kurtulanların ta kendileridir."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa Allah’ı tesbih eder (yüceltir). O güçlüdür, doğru hüküm verendir."},{"n":2,"t":"Kitap ehlinden kâfir olanları, ilk sürgünde yurtlarından çıkartan O’dur. Siz onların (yurtlarından) çıkacaklarını sanmamıştınız. Onlar da kalelerinin kendilerini Allah’tan koruyacağını sanmışlardı. (Ancak) Allah onlara beklemedikleri yerden (azabıyla) geldi ve yüreklerine korku düşürdü. (Onlar) evlerini (yurtlarını) hem kendi elleriyle hem de müminlerin elleriyle tahrip ediyorlar(dı). Ey öngörü sahipleri! İbret alın!"},{"n":3,"t":"Allah onlara (yaptıklarına karşılık ceza olarak) sürgünü yazmamış olsaydı, elbette onları dünyada (başka bir şekilde) cezalandıracaktı. Ahirette de onlar için ateş azabı vardır."},{"n":4,"t":"Bu (uygulama), onların Allah’a ve Elçisine karşı gelmelerinden ötürüdür. Kim Allah’a karşı gelirse, şüphesiz ki Allah azabı şiddetli olandır."},{"n":5,"t":"Hurma ağaçlarından herhangi birini kesmeniz veya kökleri üzerinde ayakta bırakmanız hep Allah’ın izniyledir. Sonunda (Allah) yoldan çıkanları rezil eder."},{"n":6,"t":"Allah’ın, onlardan (mallardan sorumluluğunu Elçisine) verdiği şeyler için siz at ve deve koşturmamıştınız. Fakat Allah elçilerini dilediği kişilere üstün kılar. Allah her şeye gücü yetendir."},{"n":7,"t":"Allah’ın (fethedilen) şehirler(in) halkından (sorumluluğunu) Elçisine verdiği şeyler, içinizden sadece zenginler arasında (dolaşan) bir devlet olmasın diye Allah, Elçi, yakınlık sahibi (olanlar), yetimler, yoksullar ve yolcu(lar) içindir. Elçi size ne verdiyse onu alın; size neyi yasakladıysa ondan da kaçının! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah azabı şiddetli olandır."},{"n":8,"t":"(Bu ganimet malları), yurtlarından ve mallarından uzaklaştırılmış olan, Allah’tan bir lütuf ve rıza dileyen, Allah’(ın dinin)e ve Elçisine yardım eden muhacir fakirlerindir. İşte doğru olanlar sadece bunlardır."},{"n":9,"t":"Daha önceden (Medine’yi) yurt edinmiş ve kalplerine imanı yerleştirmiş olanlar (ensar), kendilerine hicret edenleri (muhacirleri) severler. Onlara verilenlerden dolayı göğüslerinde (kalplerinde) herhangi bir ihtiyaç hissetmezler. Kendileri ihtiyaç içinde bulunsalar bile onları kendilerine tercih ederler. Kim nefsinin cimriliğinden korunursa, işte onlar kurtulanların ta kendileridir."},{"n":10,"t":"Bunların arkasından gelenler şöyle dua ederler: “Rabbimiz! Bizi ve imanda bizi geçmiş (bizden önce iman etmiş) kardeşlerimizi bağışla! İman edenlere kalplerimizde hiçbir kin bırakma! Rabbimiz! Şüphesiz ki sen çok şefkatlisin; çok merhametlisin!"},{"n":11,"t":"Münafıkların, kitap ehlinden kâfir olan kardeşlerine “Siz (yurdunuzdan) çıkartılırsanız, mutlaka biz de sizinle birlikte çıkarız; sizin aleyhinizde kimseye asla uymayız. Sizinle savaşılırsa mutlaka size yardım ederiz.” dediklerini görmedin mi?’ Allah onların yalancı olduklarına şahitlik eder."},{"n":12,"t":"Şüphesiz ki onlar (yurtlarından) çıkarılsalar, onlarla birlikte (evlerinden bile) çıkmazlar. Savaşa tutuşmuş olsalar, onlara yardım etmezler. Yardım etseler bile arkalarını dönüp kaçarlar; sonra kendilerine de yardım edilmez."},{"n":13,"t":"Onların göğüslerinde (içlerinde) size karşı duydukları korku, Allah’a olan korkularından daha şiddetlidir. Bunun sebebi, onların (gerçeği) anlamayan bir topluluk oluşudur."},{"n":14,"t":"Onlar, korunaklı şehirlerde veya duvarlar (siperler) arkasında bulunmadan sizinle toplu hâlde savaşamazlar. Kendi aralarındaki savaşları ise şiddetlidir. Sen onları derli toplu sanırsın, (oysa) kalpleri darmadağındır. Bunun sebebi, onların akıl etmeyen bir topluluk oluşlarıdır."},{"n":15,"t":"(Onların durumu), kendilerinden az önce geçmiş ve yaptıklarının cezasını tatmış olanların örneği gibidir. Onlara elem verici bir azap vardır."},{"n":16,"t":"(Münafıkların durumu) tıpkı şeytan(ın durumu) gibidir. Hani şeytan, insana “İnkâr et!” der. (İnsan) inkâr edince de “Şüphesiz ki ben senden uzağım; şüphesiz ki ben âlemlerin Rabbi olan Allah’tan korkarım!” der."},{"n":17,"t":"(Sonunda) içinde ebedî kalacakları ateş ikisinin de sonu olacaktır. İşte bu, zalimlerin cezasıdır."},{"n":18,"t":"Ey iman edenler! Allah’a karşı takvâlı (duyarlı) olun ve herkes yarın için ne hazırladığına baksın! Allah’a karşı takvâlı (duyarlı) olun! Şüphesiz ki Allah yaptıklarınızdan haberdardır."},{"n":19,"t":"Allah’ı unutan ve (bu yüzden Allah’ın da) onlara kendilerini unutturduğu kişiler gibi olmayın! Onlar yoldan çıkanların ta kendileridir."},{"n":20,"t":"Ateş halkı ile cennet halkı bir olmaz. Cennet halkı elbette kurtulanlardır."},{"n":21,"t":"Bu Kur’an’ı bir dağa indirseydik, şüphesiz ki onu Allah’a saygı(sı)ndan dolayı boyun eğmiş bir şekilde, paramparça olmuş görürdün. İşte biz düşünsünler diye şu örnekleri insanlar için veriyoruz."},{"n":22,"t":"O, kendisinden başka ilah olmayan Allah’tır. Görünmeyeni de görüneni de bilendir. O Rahmân’dır, Rahîm’dir."},{"n":23,"t":"O, kendisinden başka ilah olmayan Allah’tır. Hükümdardır, kutsallığın kaynağıdır, esenlik kaynağıdır, güven verendir, gözetip koruyandır, güçlüdür, istediğini yaptırabilendir, büyüklüğünü gösterendir. Allah onların ortak koştuklarından yücedir."},{"n":24,"t":"O, yaratan, yoktan var eden, şekil veren, en güzel isimler sadece kendisine ait olan Allah’tır. Göklerde ve yerde olanlar O’nu tesbih eder (yüceltir). O, güçlüdür, doğru hüküm verendir."}],[{"n":1,"t":"Ey iman edenler! Onlar size gelen gerçeği inkâr etmişlerken, Rabbiniz Allah’a imanınızdan dolayı Elçiyi de sizi de yurdunuzdan çıkarıyorken, benim de düşmanım, sizin de düşmanınız olanlara (o kafirlere) içten sevgi besleyerek onları (sakın) dost edinmeyin! Benim yolumda cihad etmek (fedakârlık yapmak) ve rızamı kazanmak için (yurdunuzdan) çıktığınız hâlde, (hâlâ) onlara içten sevgi (mi) gizliyorsunuz (besliyorsunuz)! Ben sizin gizlediğinizi de açığa vurduğunuzu da çok iyi bilenim. Sizden kim bunu yaparsa (onları dost edinirse), elbette doğru yoldan sapmış olur."},{"n":2,"t":"Onlar sizi ele geçirirlerse, size düşman kesilir, ellerini ve dillerini size kötülük için uzatır, inkâr etmenizi isterler."},{"n":3,"t":"Kıyamet günü, yakınlarınız ve çocuklarınız size asla yarar sağlayamazlar. (Çünkü Allah) aranızı ayıracaktır. Allah yapmakta olduğunuz her şeyi görendir."},{"n":4,"t":"İbrahim’de ve onunla birlikte olanlarda sizin için elbette güzel bir örnek vardır. Onlar toplumlarına demişlerdi ki: “Biz sizden ve Allah’ın peşi sıra taptıklarınızdan uzağız. Sizi tanımıyoruz. Siz tek bir Allah’a inanıncaya kadar, sizinle bizim aramızda sürekli bir düşmanlık ve öfke belirmiştir.” İbrahim’in, babasına “Şüphesiz ki senin için bağışlanma dileyeceğim. (Fakat) senin için Allah’tan (gelecek) herhangi bir şeyi (önlemeye) gücüm yetmez.” sözü hariç. (O müminler şöyle dua etmişlerdi:) “Rabbimiz! Yalnızca sana güvendik, yalnızca sana yöneldik. Dönüş de yalnızca sanadır."},{"n":5,"t":"Rabbimiz! Bizi, kâfir olanlar için fitne kılma! Rabbimiz! Bizi bağışla! Şüphesiz ki güçlü, doğru hüküm veren yalnızca sensin!”"},{"n":6,"t":"Şüphesiz ki onlarda sizin için, (yani) Allah’a ve ahiret gününe (kavuşmayı) umanlar) için güzel bir örnek vardır. Kim yüz çevirirse şüphesiz ki yalnızca Allah zengindir, hamde (övgüye) layık olandır."},{"n":7,"t":"Allah sizinle düşman olduklarınız arasında bir dostluk meydana getirebilir. Allah her şeye gücü yetendir. Allah çok bağışlayandır, çok merhametlidir."},{"n":8,"t":"Allah sizinle din uğrunda savaşmayan ve sizi yurtlarınızdan çıkarmayanlara iyilik yapmanızı ve onlara adil davranmanızı yasaklamaz. Şüphesiz ki Allah adil davrananları sever."},{"n":9,"t":"Allah sizinle din uğrunda savaşanları, sizi yurtlarınızdan çıkaranları ve çıkarılmanız için onlara (düşmanlara) yardım edenleri dost edinmenizi yasaklar. Kim onları dost edinirse işte onlar zalimlerin ta kendileridir."},{"n":10,"t":"Ey iman edenler! Mümin kadınlar hicret ederek size geldiği zaman, onları imtihan edin (sorgulayın)! (Elbette) Allah onların imanlarını çok iyi bilendir. Siz de onların inanmış kadınlar olduklarını öğrenirseniz, onları kâfirlere geri göndermeyin! (Çünkü) bunlar onlara helal değildir; onlar da bunlara helal olmazlar. Onların (kocalarının) verdiklerini (mehirleri kocalarına geri) verin! mehirlerini kendilerine verdiğiniz zaman onlarla evlenmenizde size herhangi bir vebal yoktur. Kâfir kadınları nikâhınızda tutmayın! Verdiklerinizi (mehirlerinizi) isteyin; onlar da verdiklerini (mehirlerini) istesinler! İşte Allah’ın hükmü budur. O aranızda (böyle) hükmetmektedir. Allah bilendir, doğru hüküm verendir."},{"n":11,"t":"Eşlerinizin kâfirlere (kaçması sebebiyle) herhangi bir kaybınız olursa, siz de sonuca ulaşır (galip gelir)seniz, eşleri gitmiş olanlara harcadıkları kadarını (ganimetten) verin! İnandığınız Allah’a karşı takvâlı (duyarlı) olun!"},{"n":12,"t":"Ey Peygamber! İnanmış kadınlar, Allah’a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleri ve ayakları arasında bir iftira uydurup getirmemek, iyi işlerde sana karşı gelmemek konusunda sana biat etmek üzere geldikleri zaman biatlarını kabul et! Onlar için Allah’tan bağışlanma dile! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."},{"n":13,"t":"Ey iman edenler! Kendilerine Allah’ın gazap ettiği (hiçbir) topluluğu dost edinmeyin! Onlar, kâfirlerin mezarlar halkından (ölülerden) ümit kestikleri gibi elbette ahiretten ümit kesmişlerdir."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa Allah’ı tesbih eder (yüceltir). O güçlüdür, doğru hüküm verendir."},{"n":2,"t":"Ey iman edenler! Yapmayacağınız şeyleri niçin söylüyorsunuz?"},{"n":3,"t":"Yapmayacağınız şeyleri söylemeniz, Allah katında büyük bir öfkeyle karşılanır."},{"n":4,"t":"Şüphesiz ki Allah kendi yolunda kenetlenmiş bir bina gibi sıra halinde savaşanları sever."},{"n":5,"t":"Hani Musa, kavmine “Ey kavmim! Benim, Allah’ın size (gönderdiği) elçisi olduğumu bildiğiniz hâlde niçin bana eziyet ediyorsunuz?” demişti. Onlar (gerçeklerden sapıp) kayınca, Allah da kalplerini kaydırmıştı. Allah yoldan çıkanlar topluluğunu doğru yola ulaştırmaz."},{"n":6,"t":"Hani Meryem oğlu İsa “Ey İsrailoğulları! Şüphesiz ki ben size önümdeki Tevrat’ı(n aslını) doğrulayıcı, adı Ahmet olup benden sonra gelecek elçiyi de müjdeleyici olarak Allah’ın (gönderdiği) elçiyim.” demişti. Ne zaman ki o, kendilerine apaçık deliller getirince “Bu(nlar) apaçık bir büyüdür!” demişlerdi."},{"n":7,"t":"İslam’a çağrıldığı hâlde Allah’a iftira edenden daha zalim kim olabilir ki! Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":8,"t":"Onlar Allah’ın nurunu (ışığını/Kur’an’ı) ağızlarıyla söndürmek istiyorlar. kâfirler istemeseler de Allah nurunu (Kur’an’ı) tamamlayıcıdır."},{"n":9,"t":"Müşrikler istemese de (dinini) bütün din(ler)e üstün kılmak için Elçisini bir rehber ve gerçek din ile gönderen O’dur."},{"n":10,"t":"Ey iman edenler! Sizi elem verici bir azaptan kurtaracak ticaret (yolunu) size göstereyim mi?"},{"n":11,"t":"Allah’a ve Elçisine inanıp güvenirsiniz; mallarınız ve canlarınızla Allah yolunda cihad edersiniz (fedakârlık yaparsınız). Bilirseniz bu, sizin için hayırlı olandır."},{"n":12,"t":"O, günahlarınızı bağışlar; sizi altlarından ırmaklar akan cennetlere, durmaya değer cennetlerdeki güzel meskenlere yerleştirir. İşte bu, büyük kurtuluştur."},{"n":13,"t":"Seveceğiniz başka (bir ticaret) daha var: Allah’tan yardım ve yakın bir zafer. Müminleri (bunlarla) müjdele!"},{"n":14,"t":"Ey iman edenler! Allah’ın (yolunun) yardımcıları olun! Nitekim Meryem oğlu İsa, Havarilere “Allah’a doğru (giden yolda) kim bana yardımcı olacak?” demişti. Havariler de “Biz Allah’ın (yolunun) yardımcılarıyız!” demişlerdi. İsrailoğulları’ndan bir grup inanmış, bir grup ise inkâr etmişti. Sonunda biz, inananları düşmanlarına karşı desteklemiştik. Böylece galip gelmişlerdi."}],[{"n":1,"t":"Göklerde ve yerde ne varsa hepsi, (gerçek) hükümdar, kutsallığın kaynağı, güçlü, doğru hüküm veren Allah’ı tesbih eder (yüceltir)."},{"n":2,"t":"O, ümmilere (Mekkelilere) kendilerine (Allah’ın) ayetlerini tilavet etmekte (okuyup aktarmakta), onları (kötülüklerden) arındırmakta ve onlara Kitap ve hikmeti (doğru hükümleri) öğretmekte olan bir Elçi göndermiştir. Daha önce onlar apaçık bir sapkınlık içindeydi."},{"n":3,"t":"Henüz kendilerine katılmamış bulunan diğerlerine de (sonraki nesillere de bu elçiyi göndermiştir). O güçlüdür, doğru hüküm verendir."},{"n":4,"t":"İşte bu, Allah’ın dilediğine (layık olana) verdiği lütfudur. Allah büyük lütuf sahibidir."},{"n":5,"t":"Kendilerine Tevrat’ı taşıma sorumluluğu verilip de onu taşımayanların örneği, kitaplar taşıyan eşeğin örneği gibidir. Allah’ın ayetlerini yalanlamış olan toplumun örneği ne kötüdür! Allah zalimler topluluğunu doğru yola ulaştırmaz."},{"n":6,"t":"De ki: “Ey yahudi olanlar! (Diğer) insanlar değil de yalnızca kendinizin Allah’ın dostları olduğunuzu sanıyorsanız (ve bu konuda) doğruysanız ölümü isteyin (bakalım)!”"},{"n":7,"t":"Onlar, kendi elleriyle önceden yaptıkları işler (günahları) sebebiyle ölümü istemezler. Allah zalimleri iyi bilendir."},{"n":8,"t":"De ki: “Sizin kendisinden kaçtığınız ölüm şüphesiz ki sizi yakalayacaktır. Sonra da görünmeyeni de görüneni de bilen (Allah)’a döndürüleceksiniz ve yaptıklarınızı size bildirecektir.”"},{"n":9,"t":"Ey iman edenler! Cuma günü salât (namaz) için çağrıldığı(nız) zaman, hemen Allah’ı anmaya koşun ve alışverişi bırakın! Bilirseniz bu sizin için hayırlı olandır."},{"n":10,"t":"Salât (namaz) bitirilince yeryüzüne dağılın ve Allah’ın lütfundan isteyin! Allah’ı çok hatırlayın! Umulur ki kurtulursunuz."},{"n":11,"t":"Onlar, bir ticaret ve eğlence gördükleri zaman hemen dağılıp ona gider ve seni ayakta (yalnız) bırakırlar. De ki: “Allah’ın katındaki (kazanç), eğlenceden de ticaretten de hayırlıdır. Allah rızık verenlerin en hayırlısıdır.”"}],[{"n":1,"t":"Münafıklar sana geldiklerinde “Şahitlik ederiz ki şüphesiz sen Allah’ın Elçisisin!” derler. Allah senin elbette kendi elçisi olduğunu bilmektedir. Allah münafıkların yalancı olduklarına elbette şahittir."},{"n":2,"t":"Yeminlerini kalkan (bahane) edinip Allah yolundan saptılar. Şüphesiz ki onların yaptıkları çok kötüdür!"},{"n":3,"t":"Bunun sebebi, onların önce iman et(tiğini söyley)ip sonra inkâr etmeleridir. (Bu yüzden) kalpleri mühürlenmiştir. Artık (gerçeği) anlayamazlar."},{"n":4,"t":"Onları (münafıkları) gördüğün zaman görünüşleri hoşuna gider; konuşurlarsa sözlerini dinlersin. Onlar, sanki giydirilmiş kütükler gibidir. Her gürültüyü kendi aleyhlerine sanırlar. Onlar düşmandır. Onlardan sakın! Allah onları kahretsin! Nasıl da (gerçeklerden) döndürülüyorlar!"},{"n":5,"t":"Onlara “Gelin, Allah’ın Elçisi sizin için bağışlanma dilesin.” dendiği zaman başlarını çevirirler ve sen onların kibirlenerek uzaklaştıklarını görürsün."},{"n":6,"t":"Onlara (onlar için) bağışlanma dilesen de dilemesen de birdir. Allah onları elbette bağışlamayacaktır. Şüphesiz ki Allah yoldan çıkanlar topluluğunu doğru yola ulaştırmaz."},{"n":7,"t":"Onlar “Allah’ın Elçisi’nin yanında bulunanlara infak etmeyin (vermeyin) ki dağılıp gitsinler!” diyenlerdir. Oysa göklerin ve yerin hazineleri yalnızca Allah’a aittir. Fakat münafıklar bunu anlamazlar."},{"n":8,"t":"Onlar “Şüphesiz ki Medine’ye dönersek, üstün olan (taraf), zayıf olanı mutlaka oradan çıkaracaktır!” diyorlardı. (Oysa) itibar yalnızca Allah’a, Elçisine ve müminlere aittir fakat münafıklar (bunu) bilmezler."},{"n":9,"t":"Ey iman edenler! Mallarınız ve çocuklarınız, sizi Allah’ı hatırlamaktan alıkoymasın! Kim bunu yaparsa işte onlar kaybedenlerin ta kendileridir."},{"n":10,"t":"“Rabbim! Beni yakın bir süreye kadar geciktirsen de sadaka verip iyilerden olsam!” diyecek şekilde herhangi birinize ölüm gelmesinden önce size verdiğimiz rızıktan dağıtın!"},{"n":11,"t":"Allah süresi geldiğinde kimseyi (ölümünü) asla ertelemez. Allah yaptıklarınızdan haberdardır."}],[{"n":1,"t":"Göklerde ve yerde ne varsa hepsi Allah’ı tesbih eder (yüceltir). Otorite yalnızca O’na aittir; hamd (övgü) de yalnızca O’nadır. O her şeye gücü yetendir."},{"n":2,"t":"Sizi yaratan O’dur. Kiminiz kâfir, kiminiz mümindir. Allah yaptıklarınızı görendir."},{"n":3,"t":"(Allah) gökleri ve yeri bir amaç ile yaratmıştır. Sizi şekillendirdi ve şekillerinizi de güzel yaptı. Dönüş de yalnızca O’nadır."},{"n":4,"t":"Göklerde ve yerde olanları bilir; gizlediğinizi de açıkladığınızı da bilir. Allah göğüslerin (kalplerin) özünü bilendir."},{"n":5,"t":"Daha önce kâfir olanların haberi size ulaşmamış mıydı! İşte onlar, yaptıklarının cezasını (dünyada) tatmışlardı. Onlar için (mahşerde de) elem verici bir azap vardır."},{"n":6,"t":"(O azabın sebebi) onlara elçilerin apaçık deliller getirmeleri fakat onların “Bir insan mı bizi doğru yola ulaştıracakmış?” demeleriydi. İnkâr etmiş ve yüz çevirmişlerdi. Allah da zengin (ihtiyaçsız) olduğunu göstermişti. Allah zengindir, hamde (övgüye) layık olandır."},{"n":7,"t":"Kâfir olanlar, elbette diriltilmeyeceklerini sanmışlardı. De ki: “Hayır! Rabbime yemin olsun: Şüphesiz ki diriltileceksiniz; sonra (da) yaptıklarınız size mutlaka bildirilecektir. Bu, Allah’a kolaydır.”"},{"n":8,"t":"O yüzden Allah’a, Elçisine ve indirdiğimiz o nûra (Kur’an’a) inanıp güvenin! Allah yapmakta olduklarınızdan haberdardır."},{"n":9,"t":"Toplanma gününde sizi toplayacağı gün, işte o teğâbun (karşılıklı aldanma) günüdür. Kim Allah’a inanır ve iyi iş(ler) yaparsa, (Allah) onun kötülüklerini örtecektir; onu içinde ebedî kalacakları, altlarından ırmaklar akan cennetlere yerleştirecektir. İşte büyük kurtuluş budur."},{"n":10,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, işte onlar ateş halkıdır. Orada ebedî kalacaklardır. Ne kötü varış yeridir (orası)!"},{"n":11,"t":"Allah’ın izni olmaksızın hiçbir musibet isabet etmez. Kim Allah’a inanırsa (Allah) onun kalbini doğru yola ulaştırır. Allah her şeyi bilendir."},{"n":12,"t":"Allah’a itaat edin; Elçi'ye de itaat edin! Yüz çevirirseniz (bilin ki) Elçimize düşen görev, sadece apaçık tebliğdir."},{"n":13,"t":"Allah kendisinden başka ilah olmayandır. Müminler yalnızca Allah’a güvensinler!"},{"n":14,"t":"Ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olanlar da vardır. Onlardan sakının! Affeder, hoşgörür ve (suçlarını) bağışlarsanız, (bilin ki) Allah da çok bağışlayandır, çok merhametlidir."},{"n":15,"t":"Mallarınız ve çocuklarınız sadece bir imtihandır. Büyük ödül ise yalnızca Allah’ın katındadır."},{"n":16,"t":"Gücünüz yettiğince Allah’a karşı takvâlı (duyarlı) olun! Dinleyin, itaat edin, kendi iyiliğiniz için infak edin (verin)! Kim nefsinin cimriliğinden korunursa, işte onlar kurtulanların ta kendileridir."},{"n":17,"t":"Allah’a güzel bir borç verirseniz, (Allah) onu sizin için kat kat artırır ve sizi bağışlar. Allah şükre çok karşılık verendir, hoşgörülüdür."},{"n":18,"t":"Görünmeyeni de görüneni de bilendir; güçlüdür, doğru hüküm verendir."}],[{"n":1,"t":"Ey Peygamber! Kadınları boşayacağınız zaman onları (bekleme) sürelerini gözeterek boşayın ve o süreyi sayın! Rabbiniz Allah’a karşı takvâlı (duyarlı) olun! Apaçık bir çirkinlik (fuhuş) yapmaları durumu hariç, onları (bulundukları) evlerinden çıkarmayın, kendileri de çıkmasınlar! Şu (hüküm)ler, Allah’ın (koyduğu) sınırlarıdır. Kim Allah’ın sınırlarını aşarsa işte onlar, elbette kendine haksızlık etmiş olur. Bilemezsin, belki de Allah bundan sonra bir durum ortaya çıkarır."},{"n":2,"t":"(Bekleme) sürelerini doldurduklarında onları ya uygun bir şekilde (nikâhınızda) tutun veya onlardan uygun bir şekilde ayrılın! İçinizden adil iki kişiyi de şahit tutun! Şahitliği Allah için yapın! İşte bu, Allah’a ve ahiret gününe inananlara verilen öğüttür. Kim Allah’a karşı takvâlı (duyarlı) olursa (Allah) ona çıkış yolu yaratır."},{"n":3,"t":"Onu hesap edemeyeceği bir yerden rızıklandırır. Kim Allah’a güvenirse O, ona yeter. Şüphesiz ki Allah emrini yerine getirendir. Elbette Allah her şey için bir ölçü koymuştur."},{"n":4,"t":"Kadınlarınızdan âdet halinden ümit kesenlerin (durumundan) şüphe ederseniz, onların bekleme süresi üç aydır. (Bir sebeple) âdet göremeyenler (için de durum böyledir). Hamile olanların (bekleme) süresi ise yüklerini bırakmaları (doğuma kadar)dır. Kim Allah’a karşı takvâlı (duyarlı) olursa, (Allah) ona işinde kolaylık verir."},{"n":5,"t":"İşte bu(nlar), Allah’ın size indirdiği emirleridir. Kim Allah’a karşı takvâlı olursa, (Allah) onun kötülüklerini örter ve onun ödülünü artırır."},{"n":6,"t":"Gücünüz ölçüsünde oturduğunuz yerin (evinizin) bir bölümünde onları (da) oturtun! Onları (gitmeleri için) sıkıştırıp kendilerine zarar vermeyin! (Boşandığınız kadınlar) hamile iseler, doğum yapıncaya kadar nafakalarını verin! Sizin için (çocuğunuzu) emzirirlerse onlara ücretlerini verin; aranızda uygun bir şekilde istişare edin! (Emzirtme konusunda) zorluk çekerseniz, onu başka bir (kadın) emzirecektir."},{"n":7,"t":"İmkânı geniş olan, imkânına göre nafaka versin; rızkı daraltılmış olan da Allah’ın kendisine verdiğinden nafaka ödesin! Allah kimseyi ona verdiği (imkân)dan başkasıyla sorumlu tutmaz. Allah her zorluktan sonra kolaylık yaratacaktır."},{"n":8,"t":"Rabbinin ve O’nun elçilerinin emrinden uzaklaşıp azmış nice şehirler (halklar) vardı ki biz onları (mahşerde) şiddetli bir hesaba çekeceğiz ve onlara görülmemiş şekilde azap edeceğiz."},{"n":9,"t":"Böylece onlar da işlerinin cezasını tatmış (olacak)lardır; işlerinin sonu da tam bir kayıptır."},{"n":10,"t":"Allah onlara şiddetli bir azap hazırlamış (olacak)tır. Ey iman etmiş öz akıl sahipleri! Allah’a karşı takvâlı (duyarlı) olun! Allah size elbette bir hatırlatıcı (elçi) indirmiştir:"},{"n":11,"t":"İman edip iyi işler yapanları, karanlıklardan aydınlığa çıkarmak için size Allah’ın apaçık ayetlerini tilavet eden (okuyup aktaran) bir elçi (göndermiştir). Kim Allah’a inanır ve iyi iş(ler) yaparsa (Allah da) onu, içinde ebedî kalacakları, altlarından ırmaklar akan cennetlere yerleştirecektir. Elbette Allah o kimse için bir rızık lütfetmiş (olacak)tır."},{"n":12,"t":"Allah yedi kat göğü ve yerden de bir o kadarını yaratandır. Allah’ın her şeye gücünün yettiğini ve her şeyi ilmiyle elbette kuşattığını bilin diye emir bunlar (göklerle yer) arasında inmektedir."}],[{"n":1,"t":"Ey Peygamber! Allah’ın sana helal kıldığı şeyi eşlerini memnun etmek uğruna niçin kendine haram kılıyorsun? Allah çok bağışlayandır, çok merhametlidir."},{"n":2,"t":"Allah (gerektiğinde) yeminlerinizi bozmanızı elbette size farz kılmıştır. Sizin yardımcınız Allah’tır. O bilendir, doğru hüküm verendir."},{"n":3,"t":"Hani Peygamber, eşlerinden birine gizlice bir söz söylemişti. (Fakat eşi) o sözü (başkasına) bildirip Allah da bunu (Peygamber’e) açıklayınca, o da (konunun) bir kısmını (eşine) bildirmiş, bir kısmından da vazgeçmişti. (Peygamber) bunu ona (eşine) bildirince, (eşi) “Bunu sana kim bildirdi?” diye sormuş, o da “Bilen, haberdar olan (Allah) bana bildirdi.” demişti."},{"n":4,"t":"İkiniz de Allah’a tevbe ederseniz, (doğrusu budur. Çünkü) elbette kalpleriniz kaymıştı. Ona (Peygamber’e) karşı birbirinize arka çıkarsanız, onun dostu Allah, Cebrail ve müminlerin iyi(ler)idir. Bunların ardından melekler de (ona) destekçidir."},{"n":5,"t":"O sizi boşarsa, Rabbi ona, sizden daha hayırlı, (Allah’a) teslim olan, iman edip güvenen, (Allah’a) boyun eğen, (Allah’a) yönelen, ibadet eden, seyahat eden, dul veya bakire eşler verebilir."},{"n":6,"t":"Ey iman edenler! Kendinizi ve ailenizi, yakıtı insanlar ve taş olan ateşten koruyun! Üzerinde son derece güçlü, Allah’ın kendilerine emrine isyan etmeyen ve emredildikleri şeyi yapan melekler vardır."},{"n":7,"t":"(Onlara:) “Ey kâfir olanlar! Bugün özür dilemeyin! Size yaptıklarınızın karşılığı verilecektir!” (denir)."},{"n":8,"t":"Ey iman edenler! Samimi bir tevbe ile Allah’a yönelin! Umulur ki Rabbiniz sizden kötülüklerinizi örter. Peygamber’i ve onunla birlikte iman edenleri rezil etmeyeceği günde Allah sizi, altlarından ırmaklar akan cennetlere yerleştirir. Onların ışığı önlerinden ve sağlarından koşar (ve) “Rabbimiz! Işığımızı bizim için tamamla; bizi bağışla! Şüphesiz ki sen her şeye gücü yetensin.” derler."},{"n":9,"t":"Ey Peygamber! O kâfirlerle ve o münafıklarla cihad et; onlara karşı sert davran! Onların barınağı cehennemdir. Ne kötü varış yeridir (orası)!"},{"n":10,"t":"Allah kâfir olanlara, Nuh’un hanımı ile Lut’un hanımını örnek vermektedir. (Bu iki kadın), kullarımızdan iki iyi kulun (nikâhları) altındalardı ve onlara ihanet etmişlerdi. (Nuh ve Lut) Allah’tan gelen hiçbir şeyi onlardan savamamıştı. (Onlara) “Ateşe girenlerle birlikte siz de girin!” denmiş (olacak)tır."},{"n":11,"t":"Allah inananlara ise Firavun’un hanımını (Asiye’yi) örnek vermektedir. (O) “Rabbim! Bana katında, cennette bir ev nasip et! Beni Firavun’dan ve onun iş(ler)inden koru! Beni zalimler topluluğundan kurtar!” demişti."},{"n":12,"t":"Namusunu korumuş İmran’ın kızı Meryem’i de (örnek vermektedir). Biz ona rûhumuzdan üflemiştik ve Rabbinin sözlerini (emirlerini) ve kitaplarını onaylamıştı (benimsemişti). O, boyun eğenlerdendi."}],[{"n":1,"t":"Otoritenin tek sahibi olan (Allah) yüceler yücesidir; O her şeye gücü yetendir."},{"n":2,"t":"Hanginizin daha güzel davranacağınızı denemesi için ölümü ve hayatı yaratan O’dur. O güçlüdür, çok bağışlayandır."},{"n":3,"t":"Yedi kat göğü tabaka tabaka (birbiriyle uyumlu) yaratan da O’dur. Rahmân’ın yaratmasında hiçbir uyumsuzluk göremezsin. Gözü(nü) çevir (de bir bak), herhangi bir kusur görebilecek misin!"},{"n":4,"t":"Sonra tekrar tekrar gözü(nü) çevir (de bak; sonunda) göz(lerin) bitkin bir şekilde yorgun olarak sana geri dönecektir."},{"n":5,"t":"Yemin olsun ki biz yakın göğü kandillerle süsledik ve onları şeytanlar için kovucular yaptık. Onlar için kavurucu azabı hazırladık."},{"n":6,"t":"Rablerine karşı kâfir olanlar için cehennem azabı vardır. Ne kötü varış yeridir (orası)!"},{"n":7,"t":"Onlar oraya atıldıklarında, kaynarken (cehennemin) korkunç sesini duyacaklardır."},{"n":8,"t":"Neredeyse öfkeden çatlayacak! Oraya (cehenneme) her bir grup atıldığında, (cehennemin) bekçileri onlara “Size bir uyarıcı gelmemiş miydi?” diye soracaklar."},{"n":9,"t":"Onlar (cehennemdekiler) şöyle diyecekler: “Evet, elbette bize bir uyarıcı gelmişti fakat biz onu yalanlamış ve “Allah hiçbir şey indirmemiştir; siz sadece büyük bir sapkınlık içindesiniz!” demiştik."},{"n":10,"t":"“(Elçileri) dinleseydik yani aklımızı kullansaydık şu alevli ateş halkı arasında olmazdık!” (diyecekler)."},{"n":11,"t":"Günahlarını itiraf etmiş (olacaklar). O alevli ateş halkı (merhametten) uzak olsun!"},{"n":12,"t":"Şüphesiz ki gaybdaki Rablerine saygı duyanlara gelince, onlar için hem bağışlanma hem de büyük bir ödül vardır."},{"n":13,"t":"Sözünüzü ister gizleyin, ister açığa vurun! Şüphesiz ki O, göğüslerin (kalplerin) özünü bilendir."},{"n":14,"t":"Yaratan bilmez mi hiç! O derin bilgi sahibidir, haberdardır."},{"n":15,"t":"O, yeri sizin için boyun eğdirmiştir. Her tarafını dolaşıp O’nun (Allah’ın verdiği) rızkından yiyin! Dönüş, yalnızca O’nadır."},{"n":16,"t":"Gökte (de) olanın sizi yere batırmasından güvende misiniz? O zaman (yer) hemen sarsılmaya başlar."},{"n":17,"t":"Yoksa gökte (de) olan zatın üzerinize taş yağdırmasından güvende misiniz? Uyarımın nasıl olduğunu ileride anlayacaksınız."},{"n":18,"t":"Yemin olsun ki onlardan öncekiler de yalanlamışlardı. Benim cezalandırmam (bak) nasıl olmuştu!"},{"n":19,"t":"Üzerlerinde kanat çırparak uçan kuşları düşünmediler mi? Onları Rahmân’dan başkası (havada) tutamaz. Şüphesiz ki O her şeyi görendir."},{"n":20,"t":"Yoksa Rahmân’a karşı size yardım edebilecek askerleriniz mi var! kâfirler ancak (derin) bir yanılgı içindedir."},{"n":21,"t":"Yoksa (Allah size verdiği) rızkını tutarsa (keserse), size rızık verecek biri mi varmış! Hayır! Onlar, azgınlık ve nefrette inatla direnmektedir."},{"n":22,"t":"Yüzüstü sürünen mi daha doğru gidebilir yoksa doğru yolda düzgün bir şekilde yürüyen mi?"},{"n":23,"t":"De ki: “Sizi yaratan, sizin için işitme (duyusu), gözler ve kalpler var eden O’dur.” Ne kadar da azınız şükrediyor!"},{"n":24,"t":"De ki: “Sizi yeryüzünde çoğaltıp yayan O’dur; (mahşerde) yalnızca O’nun huzurunda toplanacaksınız.”"},{"n":25,"t":"(İnkârcılar) “Doğruysanız bu vaat (Son Saat) ne zamanmış!” derler."},{"n":26,"t":"De ki: “O bilgi yalnızca Allah katındadır. Ben sadece apaçık bir uyarıcıyım.”"},{"n":27,"t":"Onu yakın(ların)da gördüklerinde, kâfir olanların yüzleri asılmış olacaktır ve kendilerine “İşte aceleyle istediğiniz (gün) budur!” denecektir."},{"n":28,"t":"De ki: “Hiç düşündünüz mü? Allah beni ve beraberimdekileri öldürse veya bize merhamet etse, kâfirleri elem verici azaptan kim kurtarabilir!”"},{"n":29,"t":"De ki: “O, Rahmân’dır. O’na inandık ve yalnızca O’na güvendik. Kimin apaçık bir şaşkınlık içinde olduğunu ileride bileceksiniz.”"},{"n":30,"t":"De ki: “Hiç düşündünüz mü? Suyunuz çekilse kim size bir su kaynağı getirebilir ki!"}],[{"n":1,"t":"Nûn. Kaleme ve satır satır yazdıklarına yemin olsun."},{"n":2,"t":"Rabbinin nimeti sayesinde sen asla cinlenmiş değilsin."},{"n":3,"t":"Şüphesiz ki senin için başa kakılmayan (kesintisiz) bir ödül vardır."},{"n":4,"t":"Sen elbette yüce bir ahlak üzeresin."},{"n":5,"t":"5-6 Hanginizin fitneye düştüğünü ileride sen de göreceksin, onlar da görecekler."},{"n":6,"t":"5-6 Hanginizin fitneye düştüğünü ileride sen de göreceksin, onlar da görecekler."},{"n":7,"t":"Şüphesiz ki Rabbin -evet yalnızca O- kendi yolundan kimin saptığını iyi bilendir ve O kimlerin doğru yola ulaştırıldığını iyi bilendir."},{"n":8,"t":"(Gerçeği) yalanlayanlara itaat etme!"},{"n":9,"t":"Onlar senin (kendilerine) yumuşak davranmanı isterler ki kendileri de (sana) yumuşak davransınlar."},{"n":"10-13","t":"Sürekli (yalan yere) yemin edip duranlara, aşağılıklara, (herkesi) kötüleyenlere, söz götürüp getirenlere, iyiliğe engel olanlara, saldırganlara, günaha gömülenlere, kaba olanlara, ardından da kötülükle damgalı olanlara itaat etme!"},{"n":14,"t":"Malı ve çocukları var diye (şımardığından),"},{"n":15,"t":"Ona ayetlerimiz tilavet edildiği (okunup aktarıldığı) zaman “Öncekilerin masalları!” der."},{"n":16,"t":"(Buna karşılık), ileride onun burnunu sürteceğiz."},{"n":"17-18","t":"Şüphesiz ki biz, bahçe sahiplerini denediğimiz gibi onları da denemiştik. Hani o (bahçe sahipleri) bahçeyi kesin olarak sabah hasat edeceklerine yemin etmişlerdi; istisna etmemişler(di)."},{"n":19,"t":"Onlar uykudayken, Rabbinden (gelen) kuşatıcı bir afet orayı sarmıştı."},{"n":20,"t":"(Bahçe) hasat edilmiş gibi (bomboş) olmuştu."},{"n":21,"t":"Sabah olurken birbirlerine şöyle seslenmişlerdi:"},{"n":22,"t":"“Hasat etmek istiyorsanız, erkenden arazinize (bahçenize) gidin!”"},{"n":"23-24","t":"(Bahçe sahipleri “Keşke) bugün yanınıza sokulmak üzere bahçeye hiçbir yoksul girmese!” (dileğiyle) fısıldaşarak yürüyorlardı."},{"n":25,"t":"Her şeye güçleri yetermiş (gibi) çok erken davranıp (bahçeye gelmişlerdi)."},{"n":26,"t":"Fakat bahçeyi gördüklerinde “Biz (herhâlde) yolumuzu şaşırdık!” demişlerdi."},{"n":27,"t":"“(Hayır)! Aksine biz mahrum bırakıldık!” (diye sızlanmışlardı)."},{"n":28,"t":"İçlerinden en makul olanı “Ben sizi ‘Tesbih etsenize!’ diye uyarmamış mıydım?” demişti."},{"n":29,"t":"(Onlar) “Rabbimiz yücedir! Doğrusu biz (kendimize) yazık etmişiz!” demişlerdi."},{"n":30,"t":"Birbirlerini kınamaya başlamışlardı."},{"n":31,"t":"(Şunu) demişlerdi: “Eyvah, yazıklar olsun bize! Biz azgın kişilermişiz."},{"n":32,"t":"Belki Rabbimiz bize (yok olan bahçemizin) yerine daha iyisini verir. Şüphesiz ki biz (artık) sadece Rabbimize yönelenleriz.”"},{"n":33,"t":"İşte (dünya) azabı böyledir. Ahiret azabı ise elbette daha büyüktür. Keşke bilselerdi!"},{"n":34,"t":"Şüphesiz ki muttakîler (duyarlı olanlar) için Rableri katında nimetleri bol cennetler vardır."},{"n":35,"t":"(Allah’a) teslimiyet gösterenleri suçlularla bir mi tutacağız!"},{"n":36,"t":"Ne oluyor size? Nasıl (böyle) hükmediyorsunuz?"},{"n":"37-38","t":"Yoksa içinde beğendiğiniz her şeyin bulunduğu bir kitabınız var da onda(n) mı okuyorsunuz!"},{"n":39,"t":"Yoksa vereceğiniz her hükmün lehinize olacağına dair kıyamet gününe kadar geçerli aleyhimizde yeminler mi var (biz size böyle sözler mi verdik)!"},{"n":40,"t":"Buna (bu iddiaya) hangilerinin kefil olabileceğini kendilerine sor!"},{"n":41,"t":"Yoksa (kendilerini destekleyen) ortaklar(ı) mı var! Sözlerinde doğru iseler, ortaklarını getirsinler!"},{"n":42,"t":"O gün, bacaktan açılacak (işler zorlaşacak) ve secdeye davet edileceklerdir fakat (buna) güç yetiremeyeceklerdir."},{"n":43,"t":"Kendilerini aşağılanma kaplamış olarak gözleri (sıkıntıdan) yıkılmış bir hâlde (olacaktır). (Oysa) onlar, sağlamken secde etmeye davet edilmişlerdi."},{"n":44,"t":"Bu sözü (Kur’an’ı) yalanlayanı bana bırak! Biz onları bilemedikleri bir şekilde yavaş yavaş helake sürükleyeceğiz."},{"n":45,"t":"Onlara zaman tanıyorum. Şüphesiz ki benim tuzağım (ince planım) çok sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da borç yüzünden ağır bir yük altında mı kalıyorlar?"},{"n":47,"t":"Yoksa gayb (bilinemeyen şeyler) yanlarında da (ondan) mı yazıyorlar?"},{"n":48,"t":"Sen Rabbinin hükmüne sabret! Balık sahibi (Yunus) gibi olma! Hani o, üzüntülü bir hâlde (Rabbine) seslenmişti."},{"n":49,"t":"Rabbinden ona bir nimet yetişmemiş olsaydı mutlaka kınanmış (bir hâlde) ıssız bir sahile atılacaktı."},{"n":50,"t":"Rabbi onu (peygamber olarak) seçmişti ve kendisini iyilerden kılmıştı."},{"n":51,"t":"Kâfir olanlar zikr’i (Kur’an’ı) duydukları zaman neredeyse seni gözleriyle devirecekler(di). “Şüphesiz ki o cinlenmiştir!” diyorlar."},{"n":52,"t":"Halbuki o (Kur’an), ancak âlemler için (gerçeği) hatırla(t)madır."}],[{"n":1,"t":"Gerçekleşecek olan!"},{"n":2,"t":"Nedir o gerçekleşecek olan!"},{"n":3,"t":"O gerçekleşecek olanı sana bildiren ne olabilir ki!"},{"n":4,"t":"Semûd ve Âd (kavimleri) de o çarpan felaketi yalanlamıştı."},{"n":5,"t":"Semûd (kavmi) var ya onlar azgınlığın(ın) karşılığında helak edilmişti."},{"n":6,"t":"Âd (kavmi) ise uğultulu, kasıp kavuran bir fırtına ile helak edilmişti."},{"n":7,"t":"(Allah) art arda yedi gece sekiz gün(düz) o (kasırgayı) onların üzerine salmıştı. (Orada olsaydın) o halkı, içi boş hurma kütükleri gibi yere serilmiş hâlde görürdün."},{"n":8,"t":"Onlardan geriye kalan (bir kişi) görebiliyor musun!"},{"n":9,"t":"Firavun, ondan öncekiler ve altı üstüne getirilen şehirler(in halkları) hep o hatayı (şirki) işlemişlerdi."},{"n":10,"t":"Rablerinin (her bir) elçisine isyan etmişlerdi; O da onları şiddetli bir şekilde yakalamıştı."},{"n":11,"t":"Şüphesiz ki su azgınlaştığı zaman sizi gemide biz taşımıştık."},{"n":12,"t":"(Gerçeği) hatırlatma (vesilesi) yapalım ve kavrayan kulak(ların sahipleri) onu iyice kavrasın diye onları size (anlattık)."},{"n":"13-15","t":"Sûr’a tek bir kez üflendiği, yer ve dağlar taşınarak birbirine tek çarpışla çarpıştırıldığı zaman, işte o gün o olay gerçekleşmiş (olacak)tır."},{"n":16,"t":"Gök yarılmış (olacak) ve o gün direncini kaybedecektir."},{"n":17,"t":"Melek(ler) onun (göğün) etrafında olacaktır. O gün, Rabbinin arşını onların da üzerlerinde sekiz (melek) taşıyacaktır."},{"n":18,"t":"O gün, (Allah’a) sunulacaksınız; size ait hiçbir sır gizli kalmayacaktır."},{"n":19,"t":"Kitabı kendisine sağından verilen kişiye gelince, o şöyle diyecektir: “Alın, işte kitabımı (amel defterimi) okuyun!"},{"n":20,"t":"Doğrusu ben hesabımla karşılaşacağıma inanmıştım.”"},{"n":"21-23","t":"Artık o (kişi), meyveleri sarkmış hâlde olan yüksek bir cennette memnun olacağı bir hayat içinde olacaktır."},{"n":24,"t":"(Cennetliklere şöyle seslenilecektir:) “Geçmiş günlerde işlediklerinize karşılık afiyetle yiyin, için!”"},{"n":25,"t":"Kitabı kendisine solundan verilene gelince, o kişi şöyle diyecektir: “Ah, keşke, bana kitabım (amel defterim) verilmeseydi!"},{"n":26,"t":"Hesabımın ne olduğunu da bilmeseydim!"},{"n":27,"t":"Ah, keşke, onunla (ölümümle) her iş bitseydi!"},{"n":28,"t":"Malım bana yarar sağlamadı."},{"n":29,"t":"Saltanatım da benden yok olup gitti.”"},{"n":30,"t":"(Allah, meleklerine şöyle diyecektir): “Onu yakalayın ve bağlayın!"},{"n":31,"t":"Sonra onu alevli ateşe yaslayın!"},{"n":32,"t":"Sonra (onu) yetmiş arşın uzunluğunda bir zincirle oraya sokun!”"},{"n":33,"t":"Şüphesiz ki o, yüce olan Allah’a iman etmiyordu."},{"n":34,"t":"Yoksulu doyurmaya da teşvik etmiyordu."},{"n":35,"t":"Bugün burada onun sıcak bir dostu yoktur."},{"n":"36-37","t":"(Sürekli) hata yapanlardan başkasının yemeyeceği irinden başka hiçbir yiyecek de yoktur."},{"n":"38-39","t":"Hayır! Görebildiklerinize ve göremediklerinize yemin ederim ki"},{"n":40,"t":"Şüphesiz ki o (Kur’an), değerli bir elçinin (Cebrail’in ulaştırdığı) sözüdür."},{"n":41,"t":"O, asla bir şairin sözü değildir. Ne kadar da azınız iman ediyor!"},{"n":42,"t":"O, asla bir kâhinin sözü de değildir. Ne kadar da azınız (gerçeği) hatırlıyor!"},{"n":43,"t":"Âlemlerin Rabbinden indir(il)medir."},{"n":44,"t":"(O elçi) bize (atfen) bazı sözler uydurmuş olsaydı,"},{"n":45,"t":"Bu nedenle elbette (onu önce) güçlü bir şekilde yakalardık."},{"n":46,"t":"Sonra da bu nedenle can damarını keserdik."},{"n":47,"t":"Hiçbiriniz buna engel de olamazdınız."},{"n":48,"t":"Şüphesiz ki o (Kur’an), muttakîler (duyarlı olanlar) için bir hatırlatmadır."},{"n":49,"t":"Şüphesiz ki içinizde (onu) yalanlayanların olduğunu bilmekteyiz."},{"n":50,"t":"Şüphesiz ki o (Kur’an), kâfirler için bir pişmanlık (sebebi)dir."},{"n":51,"t":"Şüphesiz ki o (Kur’an), gerçeğin ta kendisidir."},{"n":52,"t":"Yüce Rabbinin adını tesbih et (yücelt)!"}],[{"n":1,"t":"Soran biri gerçekleşecek azabı sordu."},{"n":2,"t":"Kâfirler için, o azabı savacak (kimse) yoktur."},{"n":3,"t":"O (azap), yüksek makamların sahibi Allah’tandır."},{"n":4,"t":"Melekler ve ruh(lar), miktarı elli bin sene olan bir günde O’na yükselir."},{"n":5,"t":"Sen güzelce sabret!"},{"n":6,"t":"Doğrusu onlar, o (hesabı) uzak (ihtimal) görüyorlar."},{"n":7,"t":"Biz ise onu yakın görmekteyiz."},{"n":8,"t":"O gün gök, erimiş maden gibi olur."},{"n":9,"t":"Dağlar, (yayılmış) yün gibi bir hâl alır."},{"n":10,"t":"Hiçbir dost da dostu(nu) soramaz."},{"n":"11-14","t":"Birbirlerine gösterileceklerdir. O suçlu kişi, o günün azabından (kurtulmak için) oğlunu (çocuğunu), hanımını (eşini), kardeşini, kendisini koruyup barındıran yakınlarını ve yeryüzünde kim varsa hepsini kendisini (azaptan) kurtarması için fidye vermek isteyecektir."},{"n":"15-16","t":"Hayır! Şüphesiz ki o (cehennem), derileri kavurup soyan alevli bir ateştir."},{"n":"17-18","t":"Arkasını dönüp yüz çevireni ve (mal) toplayıp yığan kimseyi (kendine) çağıracaktır."},{"n":19,"t":"Şüphesiz ki insan çok hırslı yaratılmıştır."},{"n":20,"t":"Başına bir kötülük geldiğinde çok sızlanır."},{"n":21,"t":"Bir hayra (zenginliğe) ulaşınca da çok cimri kesilir."},{"n":22,"t":"Ancak salât (ibadet) edenler hariç!"},{"n":23,"t":"Onlar salâtlarında (ibadetlerinde) devamlı olanlardır."},{"n":"24-25","t":"Onlar mallarında açıktan isteyen ve açıktan isteyemeyen(ler) için bilinen bir hak bulunanlardır."},{"n":26,"t":"Onlar hesap gününe inananlardır."},{"n":27,"t":"Onlar Rablerinin azabından korkanlardır."},{"n":28,"t":"Şüphesiz ki Rablerinin azabı(na karşı) güvende olunamaz."},{"n":29,"t":"Onlar namuslarını koruyanlardır."},{"n":30,"t":"Ancak eşleri yani (evlilik yoluyla) meşru olarak sahip oldukları kişiler hariç. Şüphesiz ki onlar, (eşleriyle ilişkilerinde) kınanmazlar."},{"n":31,"t":"Bundan öteye (geçmek) isteyenler ise haddini aşanların ta kendileridir."},{"n":32,"t":"Onlar emanetlerine ve sözlerine uyanlardır."},{"n":33,"t":"Onlar şahitliklerini yerine getirenlerdir."},{"n":34,"t":"Onlar bütün ibadetlerini koruyanlardır."},{"n":35,"t":"İşte onlar cennetlerde ağırlanacaklardır."},{"n":"36-37","t":"Kâfir olanlara ne oluyor ki sağdan ve soldan bölük bölük sana doğru boyunlarını uzatıyorlar!"},{"n":38,"t":"Onlardan her bir kişi nimet cennetine konulacağını mı umuyor!"},{"n":39,"t":"Hayır! Şüphesiz ki biz onları bildikleri şeyden yarattık."},{"n":"40-41","t":"Hayır! Doğuların ve batıların Rabbine yemin ederim ki onların yerine daha iyilerini getirmeye bizim gücümüz yeter ve biz asla geçilebilenler değiliz."},{"n":42,"t":"Sen onları (şimdilik) bırak da kendilerine vadedilen günlerine kavuşuncaya kadar (boş işlere) dalsınlar, oynasınlar!"},{"n":"43-44","t":"O gün onlar sanki dikili bir şeye koşuyorlar gibi kendilerini aşağılanma kaplamış olarak gözleri (perişanlıktan) yıkılmış bir hâlde mezarlarından hızla çıkacaklar. İşte bu kendilerine vadedilmiş gündür!"}],[{"n":1,"t":"Kendilerine elem verici bir azap gelmeden önce kavmini uyar(sın) diye Nuh’u kendi kavmine göndermiştik."},{"n":2,"t":"Şöyle demişti: “Ey kavmim! Ben sizin için apaçık bir uyarıcıyım."},{"n":3,"t":"Allah’a kulluk edin; O’na karşı takvâlı (duyarlı) olun ve bana itaat edin."},{"n":4,"t":"(Böylece Allah) da günahlarınızı bağışlasın ve sizi, belirli bir süreye kadar ertelesin (yaşatsın)!” Allah’ın (belirlediği) süresi gelince (o artık) ertelenmez. Keşke bilseydiniz!"},{"n":5,"t":"(Nuh) demişti ki: “Rabbim! Doğrusu ben kavmimi gece gündüz (imana) davet ettim"},{"n":6,"t":"Benim davetim ancak kaçmalarını artırdı."},{"n":7,"t":"Sen onları bağışlayasın diye onları ne zaman davet ettiysem, parmaklarını kulaklarına tıkadılar; elbiselerine büründüler, direndiler ve kibirlendikçe kibirlendiler."},{"n":8,"t":"Sonra, ben kendilerini açıktan davet ettim."},{"n":9,"t":"Ardından, onlara hem (açıktan) ilan ettim hem de gizli gizli söyledim."},{"n":10,"t":"(Onlara) dedim ki: ‘Rabbinizden bağışlanma dileyin; şüphesiz ki O çok bağışlayandır."},{"n":11,"t":"(Af dileyin ki) üzerinize göğü (yağmuru) bol bol göndersin!"},{"n":12,"t":"Mallarınızı ve çocuklarınızı çoğaltsın; size bahçeler versin; sizin için ırmaklar yapsın (akıtsın)!"},{"n":13,"t":"Size ne oluyor ki Allah’a büyüklüğü yakıştıramıyorsunuz?"},{"n":14,"t":"Sizi aşama aşama elbette O yaratmıştır."},{"n":15,"t":"Görmediniz mi Allah yedi göğü tabaka tabaka (birbiriyle uyumlu) nasıl yaratmıştır!"},{"n":16,"t":"Onların içinde ayı bir nûr kılmış, güneşi de bir kandil yapmıştır."},{"n":17,"t":"Allah sizi de bitki gibi yerden yetiştirmiştir."},{"n":18,"t":"Sonra sizi yine oraya döndürecek ve sizi yeniden (oradan) çıkartacaktır."},{"n":19,"t":"19-20 Ondan geniş yollar edinesiniz diye Allah yeri sizin için yaymıştır.”"},{"n":20,"t":"19-20 Ondan geniş yollar edinesiniz diye Allah yeri sizin için yaymıştır.”"},{"n":21,"t":"(Söylediklerini dinlememeleri üzerine) Nuh şöyle demişti: “Rabbim! Doğrusu onlar bana karşı geldiler; malı ve çocuğu kendi kaybını artırmaktan başka bir işe yaramayan kimseye uydular."},{"n":22,"t":"Çok büyük tuzaklar da kurdular.”"},{"n":23,"t":"Şöyle demişlerdi: “Sakın ilahlarınızı bırakmayın; Vedd’i, Suvâ‘ı, Yeğûs’u, Ye‘ûk’u ve Nesr’i terk etmeyin!”"},{"n":24,"t":"(Böylece) onlar elbette çoklarını saptırdılar. (Bunun üzerine Nuh: “Rabbim)! Sen de bu zalimlerin ancak şaşkınlıklarını artır!” (demişti)."},{"n":25,"t":"Onlar, günahları yüzünden suda boğuldular ve ateşe sokuldular ve (o zaman) Allah’ın peşi sıra hiçbir yardımcı da bulamadılar (bulamayacaklar)."},{"n":26,"t":"Nuh demişti ki: “Rabbim! O kâfirlerden kimseyi yeryüzünde bırakma!"},{"n":27,"t":"Şüphesiz ki sen onları bırakırsan kullarını saptırır; sadece ahlaksız, nankör (işler) doğururlar (yaparlar)."},{"n":28,"t":"Rabbim! Beni, ana babamı, iman etmiş olarak evime girenleri, iman eden erkekleri ve iman eden kadınları bağışla! Zalimlerin de ancak helakini artır!”"}],[{"n":"1-2","t":"De ki: “Cinlerden bir grubun (beni) dinlediği ve şöyle söyledikleri bana vahyolunmuştur: ‘Şüphesiz ki doğruya götüren harikulade bir Kur’an dinledik ve ona inandık; artık Rabbimize hiçbir şeyi ortak koşmayacağız."},{"n":3,"t":"Eşi de çocuğu da olmayan Rabbimizin şanı çok yücedir."},{"n":4,"t":"İçimizden bir beyinsiz, Allah hakkında asılsız, saçma sözler söylerdi."},{"n":5,"t":"Biz hiçbir insan ve cinin Allah hakkında yalan söylemeyeceğini sanmıştık."},{"n":6,"t":"İnsanlardan bazı erkekler, bazı erkek cinlere sığınıyordu da (bu durum onların) sadece azgınlığını artırıyordu."},{"n":7,"t":"Onlar da sizin sandığınız gibi, Allah’ın kimseyi (elçi) olarak göndermeyeceğini sanmışlardı."},{"n":8,"t":"Biz göğü de yokladık fakat onu güçlü koruyucularla, ışık hüzmeleriyle doldurulmuş bulduk."},{"n":9,"t":"(Oysa) biz (haber) dinlemek için göğün (çeşitli) yerlerinde oturuyorduk fakat şimdi kim (haber) dinlemek isterse, kendisini takip eden bir alev hüzmesi bulu(yo)r."},{"n":10,"t":"(Artık) yeryüzündekilere kötülük mü edildiğini, yoksa Rablerinin onlara bir hayır mı dilediğini bilemiyoruz."},{"n":11,"t":"İçimizden iyiler de başkaları (kötüler) de var. Hepimiz türlü türlü yollar tutmuştuk."},{"n":12,"t":"Allah’ı yeryüzünde asla aciz bırakamayacağımızı ve başka yere kaçmakla da (kurtulamayacağımızı) iyice anladık."},{"n":13,"t":"Şüphesiz ki artık biz o rehberi (Kur’an’ı) duyunca ona iman ettik. Rabbine güvenen kişi, kendisine herhangi bir zarar verilmesinden de haksızlığa uğratılmaktan da korkmaz."},{"n":14,"t":"İçimizden (Allah’a) teslim olanlar da yoldan sapanlar da var. (Allah’a) teslim olanlar, doğru yolu arayıp (bulmuş olan)lardır."},{"n":15,"t":"Yoldan sapanlar ise cehennem için yakıt olmuş (olacaklardır).”"},{"n":"16-17","t":"Doğru yolda olsalardı, kendilerini nimetler içerisinde imtihan edelim diye onlara bol su verirdik. Zaten kim Rabbinin zikrinden (Kur’an’dan) yüz çevirirse, Allah onu şiddeti artan bir azaba sürükler."},{"n":18,"t":"Şüphesiz ki mescitler Allah’a aittir. Allah ile birlikte kimseye yalvarmayın!"},{"n":19,"t":"Allah’ın kulu, O’na davet için kalktığında (yoldan sapanlar) neredeyse onun üzerine çullanırlardı."},{"n":20,"t":"De ki: “Ben sadece Rabbime dua ederim (O’na çağırırım) ve O’na kimseyi ortak koşmam.”"},{"n":21,"t":"De ki: “Ben size zarar verme ve doğru yola getirme gücüne de sahip değilim.”"},{"n":22,"t":"De ki: “Allah’tan (gelecek bir azaba karşı) beni asla kimse koruyamaz. O’ndan başka bir sığınak da asla bulamam."},{"n":23,"t":"(Benim görevim), Allah’tan gelen ve O’nun mesajlarından oluşan (emirleri) sadece tebliğdir. Allah’a ve Elçisine isyan eden kişi için içinde ebedî kalacakları cehennem ateşi vardır."},{"n":24,"t":"Sonunda, kendilerine vadedilen şeyi gördükleri zaman, kimin yardımcısının daha zayıf ve sayısının daha az olduğunu ileride bileceklerdir."},{"n":25,"t":"De ki: “Size vadedilen (gün) yakın mıdır, yoksa Rabbim onun için uzun bir süre mi koyar, onu ben bilemem.”"},{"n":26,"t":"Gaybı (bilinemeyeni) bilen (Allah) gaybını (bilinemeyeni) kimseye açmaz."},{"n":"27-28","t":"Ancak dilediği elçi(ler) bunun dışındadır. Rablerinin mesajlarını onların (meleklerin) tebliğ ettiğini bilsin diye, o (elçinin) önünden ve arkasından gözetleyici(ler) gönderir. (Allah) onların beraberinde bulunanı kuşatmış ve her şeyi bir bir sayıp kaydetmiştir."}],[{"n":1,"t":"Ey (peygamberlik görevine) bürünen!"},{"n":2,"t":"Birazı (bazı saatleri) hariç, gece kalk!"},{"n":3,"t":"(Gecenin) yarısında, ondan biraz eksilt(erek daha erken kalk)."},{"n":4,"t":"Ona ilave ederek (gece yarısından sonra kalk) ve Kur’an’ı ağır ağır oku!"},{"n":5,"t":"Şüphesiz ki biz sana (sorumluluğu) ağır bir söz bırakacağız (vahyedeceğiz)."},{"n":6,"t":"Şüphesiz ki gecenin inşası daha kalıcıdır; sözü de daha etkilidir."},{"n":7,"t":"Şüphesiz ki gündüz senin için uzun (süreli) meşguliyet(ler) vardır."},{"n":8,"t":"Rabbinin adını an! Bütün varlığınla O’na yönel!"},{"n":9,"t":"(Allah) doğunun da batının da Rabbidir. Kendisinden başka ilah yoktur. (Sadece) O’nu vekil (güven kaynağı) edin!"},{"n":10,"t":"O (müşriklerin) söylediklerine karşı sabırlı ol ve onlardan güzellikle uzaklaş!"},{"n":11,"t":"Nimet sahibi (olan) o yalanlayıcıları bana bırak; onlara biraz zaman tanı!"},{"n":"12-13","t":"Şüphesiz ki bizim katımızda, (onlar için hazırlanmış) prangalar, yakıcı ateş, boğazdan geçmeyen yiyecek ve elem verici azap vardır."},{"n":14,"t":"O gün (Son Saat’te) yer ve dağlar sars(ıl)acak; dağlar erimiş kum yığınına dönecektir."},{"n":15,"t":"Şüphesiz ki Firavun’a elçi gönderdiğimiz gibi size de hakkınızda şahitlik edecek bir elçi gönderdik."},{"n":16,"t":"Firavun, o Elçi'ye isyan etmişti. Biz de onu kahredici bir şekilde kıskıvrak yakalamıştık."},{"n":17,"t":"Çocuğu yaşlıya çevirecek o güne karşı kâfir olursanız, (azaptan) nasıl korunabilirsiniz ki!"},{"n":18,"t":"Gök, o (gün) nedeniyle yarılacaktır. (Allah’ın) vaadi gerçekleşmiş olacaktır."},{"n":19,"t":"Şüphesiz ki bu (Kur’an), (gerçeği) hatırla(t)madır. Dileyen, Rabbine (giden) bir yol tutar."},{"n":20,"t":"Şüphesiz ki Rabbin, senin ve beraberinde bulunan bir grubun gecenin üçte ikisinden daha az bir kısmında, yarısında ve üçte birinde kalkmakta olduğunu biliyor. Allah gecenin ve gündüzün ölçüsünü belirler. O, sizin bunu (tamamen) sayamayacağınızı bilmiş ve (bunun için) tevbenizi kabul etmiştir. Kolay olan zamanda Kur’an’dan okuyun! İçinizde hastalar olacağını, (içinizden) bir kısmının Allah’ın lütfundan (rızık) aramak üzere yeryüzünde sefere çıkacağını, diğer bir kısmının da Allah yolunda savaşacağını (Allah) bilmektedir. Kolay olan zamanda ondan (Kur’an’dan) okuyun! Namazı kılın, zekâtı verin ve Allah’a güzel bir borç verin! Kendiniz için (önceden) ne tür bir iyilik sunarsanız, Allah katında onu hem daha hayırlı hem de ödül bakımından daha büyük olarak bulacaksınız. Allah’tan bağışlanma dileyin! Şüphesiz ki Allah çok bağışlayandır, çok merhametlidir."}],[{"n":1,"t":"Ey (peygamberlik görevine) bürünen!"},{"n":2,"t":"Kalk ve uyar!"},{"n":3,"t":"Sadece Rabbini yücelt!"},{"n":4,"t":"Elbiseni (kalbini) temiz tut!"},{"n":5,"t":"Pislikten uzak dur!"},{"n":6,"t":"(Yaptığını) çok görerek başa kakma!"},{"n":7,"t":"Sadece Rabbin için sabret!"},{"n":"8-9","t":"Sûr’a üflendiği zaman, işte o gün, çok zor bir gün (olacak)tır."},{"n":10,"t":"Kâfirler için kolay değildir."},{"n":11,"t":"Tek başıma yarattığımla beni baş başa bırak!"},{"n":12,"t":"Ona çok mal verdim."},{"n":13,"t":"Göz önünde olan çocuklar (verdim)."},{"n":14,"t":"Her şeyi önüne serdim."},{"n":15,"t":"(Ama) ardından o (kişi, ona verdiğim nimetlerimi) daha da artırmamı ister."},{"n":16,"t":"Hayır! Şüphesiz ki o, ayetlerimize karşı inatçıydı."},{"n":17,"t":"Onu ileride sarp bir yokuşa sardıracağım!"},{"n":18,"t":"Şüphesiz ki o, düşündü ve ölçüp biçti."},{"n":19,"t":"Kahrolası, nasıl da ölçüp biçti!"},{"n":20,"t":"Sonra, kahrolası (yine) nasıl da ölçüp biçti!"},{"n":21,"t":"Sonra baktı."},{"n":22,"t":"Sonra surat(ını) astı, kaş(larını) çattı."},{"n":23,"t":"Sonra arkasını döndü, kibirlendi."},{"n":24,"t":"“Bu (Kur’an), geçmişten nakledilen bir büyüden başka bir şey değildir.” dedi."},{"n":25,"t":"“Bu, insan sözünden başka bir şey değildir!” (dedi)."},{"n":26,"t":"Onu Sekar’a atacağım."},{"n":27,"t":"Sekar’ın ne olduğunu sana bildiren ne olabilir ki!"},{"n":28,"t":"Ne (yakmadık yer) bırakır, ne de terk eder."},{"n":29,"t":"İnsanın (derisini) kavurur."},{"n":30,"t":"Üzerinde on dokuz vardır."},{"n":31,"t":"Biz ateşin sahiplerini (muhafızlarını) ancak melekler yapmışızdır. Onların sayısını kâfir olanlar için sadece bir imtihan yaptık ki kendilerine kitap verilenler ikna olsunlar; iman edenlerin imanı artsın; hem kendilerine kitap verilenler hem de müminler şüpheye düşmesinler; kalplerinde hastalık bulunanlar ve kâfirler de “Allah bu örnekle ne kastetmiştir ki?” desinler. İşte böylece Allah dileyeni (layık gördüğünü) saptırır (sapkınlığını onaylar), dileyeni (layık gördüğünü) doğru yola ulaştırır. Rabbinin ordularını O’ndan başka kimse bilemez. Bunlar, insanlık için sadece (gerçeğin) hatırlat(ıl)masıdır."},{"n":32,"t":"Hayır! Yemin olsun: Aya,"},{"n":33,"t":"Dönüp gitmekte olan geceye,"},{"n":34,"t":"Ağarmakta olan sabaha ki"},{"n":35,"t":"O (cehennem), büyük (ceza)ların birisidir."},{"n":"36-37","t":"İnsanlık için yani sizden ileri gitmek veya geri(de) kalmak isteyenler için uyarıcıdır."},{"n":38,"t":"Her nefis kazandıklarına karşılık rehindir."},{"n":39,"t":"Sağın halkı hariç."},{"n":"40-42","t":"Cennetlerdeyken “Sizi ateşe sürükleyen nedir?” diye suçluların durumundan soracaklar."},{"n":43,"t":"(Onlar da) şöyle diyecekler: “Biz salât (ibadet) edenlerden değildik."},{"n":44,"t":"Yoksulu doyurmazdık."},{"n":45,"t":"Boş şeylere dalanlarla birlikte biz de boş şeylere dalardık."},{"n":46,"t":"Hesap gününü yalanlardık."},{"n":47,"t":"Sonunda kesin bir gerçek (olan ölüm) bize gelip çattı.”"},{"n":48,"t":"(Bekledikleri) şefaatçilerin şefaati onlara yarar sağlamaz."},{"n":"49-51","t":"Onlara ne oluyor da aslandan kaçan ürkmüş yaban eşekleri gibi bu hatırlatmadan (Kur’an’dan) yüz çeviriyorlar?"},{"n":52,"t":"Aslında onların her biri, kendisine (önünde) açılmış sahifeler (vahiy) verilmesini istiyor."},{"n":53,"t":"Hayır! Aslında onlar ahiretten korkmuyorlar."},{"n":54,"t":"Hayır! Şüphesiz ki bu (Kur’an), bir hatırlatmadır."},{"n":55,"t":"Dileyen onu(nla gerçeği) hatırlar."},{"n":56,"t":"(Bunu yapanlar), Allah’ın istediğinden başkasını hatırlamamış olurlar. Takvâya (duyarlı olmaya) layık olan da bağışlayan da O’dur."}],[{"n":1,"t":"Hayır! Kıyamet gününe yemin ederim."},{"n":2,"t":"Hayır! Kendini kınayan nefse (insana) da yemin ederim."},{"n":3,"t":"İnsan kemiklerini asla bir araya toplayamayacağımızı mı sanıyor!"},{"n":4,"t":"Evet! Biz onun parmak uçlarını bile düzenlemeye gücü yetenleriz."},{"n":"5-6","t":"Aslında (inkârcı) insan, “Kıyamet günü de ne zamanmış!” diye sorarak, önündekini (ahireti) yalanlamak ister."},{"n":"7-10","t":"İşte göz(ler kamaşıp) şimşek çaktığı, ay karardığı, güneş ve ay bir araya getirildiği zaman, işte o gün (inkârcı) insan “(Acaba) nereye kaçmalı(yım)?” diyecektir."},{"n":11,"t":"Hayır! Sığınacak (bir) yer yoktur!"},{"n":12,"t":"O gün varılacak yer sadece Rabbinin huzurudur."},{"n":13,"t":"O gün, (dünyada yapıp) öne sürdüğü ve (yapmayıp) geride bıraktığı ne varsa insana bildirilecektir."},{"n":"14-15","t":"(Birtakım) mazeretler ileri sürmeye kalkışacak olsaydı bile artık insan kendi kendinin şahididir."},{"n":16,"t":"(Ey suçlu kişi)! Artık onu (hakkındaki hükmü) çabucak almak için dilini kımıldatma!"},{"n":17,"t":"Şüphesiz ki onun toplanması ve okunması sadece bize aittir."},{"n":18,"t":"Biz onu okuduğumuz zaman okunuşunu takip et!"},{"n":19,"t":"Sonra onu açıklamak da sadece bize aittir."},{"n":20,"t":"Hayır! Doğrusu siz çabucak geçeni (dünyayı) seviyorsunuz."},{"n":21,"t":"Ahireti bırakıyorsunuz."},{"n":"22-23","t":"O gün bazı yüzler, Rablerini(n kararını) beklerken ışıl ışıl olacaktır."},{"n":"24-25","t":"O gün bazı asık yüzler de vardır ki bel kemiklerini kıran bir felakete uğratılacağını anlayacaktır."},{"n":"26-30","t":"Doğrusu (can), köprücük kemiğine dayanıp “Tedavi edebilecek kimdir?” dendiğinde, bunun gerçek bir ayrılık olduğunu anlayıp bacak(lar) birbirine dolaştığında, işte o gün varılacak yer sadece Rabbinin huzuru olacaktır."},{"n":31,"t":"(İnkârcı kişi, gerçeği) onaylamamış, (Allah’ın dinine) destek olmamıştı."},{"n":32,"t":"Aksine yalanlamış ve yüz çevirmişti."},{"n":33,"t":"Sonra da kibirlenerek kendi ailesine gitmişti."},{"n":34,"t":"Yazıklar olsun sana, yazıklar olsun!"},{"n":35,"t":"Sonra (tekrar) yazıklar olsun sana, yazıklar olsun!"},{"n":36,"t":"İnsan, kendisinin başıboş bırakılacağını mı sanıyor!"},{"n":37,"t":"(İnsan) akıtılan meninin (spermin) bir kısmından (oluşan) bir nutfe (zigot) değil miydi!"},{"n":38,"t":"Sonra bu (zigot) ‘alakaya (embriyoya) dönüşmüş, (Allah) onu (insan biçiminde) yaratıp şekillendirmiştir."},{"n":39,"t":"(Allah) o (meni)den de iki eşi, yani erkek ve dişiyi var etmiştir."},{"n":40,"t":"(O’nun), ölüleri diriltmeye hiç gücü yetmez mi!"}],[{"n":1,"t":"Henüz anılan bir şey değilken, şüphesiz ki insanın üzerinden çok uzun bir süre geçti!"},{"n":2,"t":"Gerçek şu ki biz insanı katışık (döllenmiş) bir nutfeden (zigottan) yarattık. Onu imtihan edeceğiz; (bu yüzden) onu duyar ve görür kıldık."},{"n":3,"t":"Şüphesiz ki biz insana yol gösterdik. Ya şükredici (olur) ya da nankör."},{"n":4,"t":"Şüphesiz ki biz, kâfirler için (ahirette) zincirler, halkalar ve alevli bir ateş hazırlamış (olacağız)."},{"n":5,"t":"Şüphesiz ki iyiler ise (cennette) kâfûr katılmış bir kadehten içeceklerdir."},{"n":6,"t":"(Kâfûr), Allah’ın iyi kullarının içecekleri ve akıttıkça akıtacakları bir kaynaktır."},{"n":7,"t":"(Allah’ın iyi kulları), verdikleri sözü yerine getirir ve kötülüğü her yere yayılmış olan bir günden korkarlar."},{"n":8,"t":"Onlar, kendileri muhtaç olmalarına rağmen yoksulu, yetimi ve esiri yedirir (doyurur)lar."},{"n":"9-10","t":"(Şöyle derler:) “Biz sizi yalnızca Allah rızası için doyuruyoruz; sizden herhangi bir karşılık da teşekkür de istemiyoruz. (Çünkü) biz, zor ve belalı bir günde Rabbimizden (O’nun azabından) korkuyoruz.”"},{"n":11,"t":"Allah onları o günün şiddetinden korumuş (olacak)tır; (yüzlerine) parlaklık, (kalplerine de) sevinç verecektir."},{"n":12,"t":"Sabretmelerine karşılık onlara cennet ve özgürlük lütfedecektir."},{"n":13,"t":"Orada koltuklara kurulmuş olacaklar; yakıcı sıcak da dondurucu soğuk da görmeyeceklerdir."},{"n":14,"t":"(Cennet ağaçlarının) gölgeleri onların (cennetliklerin) üzerlerine sarkacak, meyveleri (kolayca toplanması için) eğdirilecektir."},{"n":15,"t":"Çevrelerinde gümüş kaplar ve billur kupalar dolaştırılacaktır."},{"n":16,"t":"Miktarını kendilerinin belirleyeceği o billur kupalar da gümüştendir."},{"n":"17-18","t":"Onlara orada, adına Selsebil denen kaynaktan, (içindeki) karışımı Zencebil olan bir kadehten içirilecektir."},{"n":19,"t":"O (cennetliklerin) etrafında, yaşlanmayan gençler dolaşır. Onları gördüğünde kendilerini saçılıp dağılmış inciler sanırsın."},{"n":20,"t":"(Cennette) her nereye bakarsan, (pek çok) nimet ve büyük bir otorite görürsün."},{"n":21,"t":"Üzerlerinde ince ipekten yeşil elbiseler ve kalın ipek kumaşlar olacaktır; gümüş bilezikler takacaklardır. Rableri onlara tertemiz bir içecek ikram edecektir."},{"n":22,"t":"(Onlara şöyle denecektir:) “Şüphesiz ki bu(nlar), sizin için ödüldür. Çalışma(ları)nız karşılığını bulmuştur.”"},{"n":23,"t":"Kur’an’ı sana peyder pey indiren elbette biziz, biz."},{"n":24,"t":"Rabbinin hükmü için sabret! Onlardan hiçbir günahkâra veya hiçbir nanköre itaat etme!"},{"n":25,"t":"Sabah akşam Rabbinin ismini an!"},{"n":26,"t":"Gecenin bir kısmında O’na secde et; gecenin uzun bir bölümünde de O’nu tesbih et (yücelt)!"},{"n":27,"t":"Şüphesiz ki bu (insa)nlar, çabucak geçen (dünyay)ı seviyorlar da ağır günü (ahireti) arkalarına atıyorlar."},{"n":28,"t":"Onları biz yarattık ve yaratılışlarını sapasağlam yaptık. Dilediğimiz (zaman) onları benzerleriyle değiştiririz."},{"n":29,"t":"Şüphesiz ki bu (gerçeği) hatırla(t)madır. Dileyen, Rabbine (giden) bir yol tutar."},{"n":30,"t":"(Böyle yaparsanız) Allah’ın dilediğinden başkasını dilememiş olursunuz. Şüphesiz ki Allah bilendir, doğru hüküm verendir."},{"n":31,"t":"(Allah) dileyeni (layık gördüğünü) merhametine koyar. Zalimler için de elem verici bir azap hazırlamış (olacak)tır."}],[{"n":1,"t":"Yemin olsun: Birbiri ardınca gönderilenlere,"},{"n":2,"t":"Esip savuranlara,"},{"n":3,"t":"Yaydıkça yayanlara,"},{"n":4,"t":"Ayırdıkça ayıranlara,"},{"n":"5-6","t":"Özür (imkânı vermek) veya uyarı(da bulunmak) için öğüt bırakanlara (ulaştıranlara) ki"},{"n":7,"t":"Size vadedilen (gün) elbette gerçekleşecektir."},{"n":8,"t":"Yıldızlar silindiği (söndürüldüğü)nde,"},{"n":9,"t":"Gök yarıldığında,"},{"n":10,"t":"Dağlar ufalanıp savrulduğunda,"},{"n":11,"t":"Elçilere (şahitlik için) vakit verildiğinde (Son Saat gerçekleşmiş olacaktır)."},{"n":12,"t":"(Bu durum), hangi güne ertelenmiştir?"},{"n":13,"t":"Ayrılma gününe."},{"n":14,"t":"O ayrılma gününün ne olduğunu sana bildiren ne olabilir ki!"},{"n":15,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":16,"t":"Biz (bunlar gibi inkârcı olan) öncekileri de helak etmedik mi?"},{"n":17,"t":"Sonra gelenleri de onların peşine takacağız."},{"n":18,"t":"İşte biz, suçlulara böyle yaparız!"},{"n":19,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":20,"t":"Sizi dayanıksız bir sudan yaratmadık mı?"},{"n":"21-22","t":"Sonra onu belirli bir süreye kadar sağlam bir yere yerleştirmiştik."},{"n":23,"t":"(İşte bunları) bir ölçüyle yaptık. Ne güzel ölçü koyanlarız biz!"},{"n":24,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":"25-26","t":"Biz yeryüzünü diriler ve ölüler için toplanma yeri yapmadık mı?"},{"n":27,"t":"Oraya sabit ağırlıklar koyduk ve size tatlı sular içirdik."},{"n":28,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":29,"t":"(İnkârcılara şöyle denecektir): “Yalanlamış olduğunuz şeye doğru yürüyün!"},{"n":"30-31","t":"Üç katlı, gölge etmeyen ve ateşten korumayan bir karanlığa doğru yürüyün!”"},{"n":32,"t":"Şüphesiz ki o (cehennem), kütükler (gibi büyük) kıvılcımlar saçar."},{"n":33,"t":"O (kıvılcımlar) sanki sarı (kızgın) halatlar gibidir."},{"n":34,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":35,"t":"Bu (mahşer, kâfirlerin) konuşamayacağı gündür."},{"n":36,"t":"Özür dilemeleri için kendilerine izin verilmeyecektir."},{"n":37,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":"38-39","t":"(İnkârcılara şöyle denecektir:) “Bu, ayrılık günüdür. Sizi de öncekileri de bir araya toplayacağız. (Azaptan kurtulmak için) bir hileniz varsa hemen bana tuzak kurun!"},{"n":40,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":"41-42","t":"Şüphesiz ki muttakîler (duyarlı olanlar), gölgelerde, (su) kaynaklarında ve canlarının çektiği her tür meyve(lik)lerde olacaklardır."},{"n":43,"t":"(Onlara) “Yaptıklarınıza karşılık afiyetle yiyip için” (denecektir)."},{"n":44,"t":"Şüphesiz ki biz güzel davrananları işte böyle ödüllendiririz."},{"n":45,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":46,"t":"(Suçlulara şöyle denecektir:) “Yiyin, (dünyadan) biraz daha yararlanın! (Bilin ki) siz suçlusunuz.”"},{"n":47,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":48,"t":"Onlara “(Allah’a) boyun eğin!” dendiğinde boyun eğmezler."},{"n":49,"t":"(O günü) yalanlayanların, o gün vay hâline!"},{"n":50,"t":"Bundan (Kur’an’dan) sonra artık hangi söze inanacaklar ki!"}],[{"n":1,"t":"Birbirlerine neyi soruyorlar?"},{"n":"2-3","t":"Anlaşmazlığa düştükleri o büyük haberi."},{"n":4,"t":"Hayır! İleride (gerçeği) bilecekler!"},{"n":5,"t":"Sonra, şüphesiz ki ileride (gerçeği) bilecekler!"},{"n":"6-7","t":"Biz yeri bir beşik, dağları da birer kazık yapmadık mı?"},{"n":8,"t":"Sizi eşler (çiftler) hâlinde yarattık."},{"n":9,"t":"Uykunuzu bir dinlenme (aracı) kıldık."},{"n":"10-11","t":"Geceyi bir örtü, gündüzü de çalışıp kazanma zamanı yaptık."},{"n":12,"t":"Üstünüzde sağlam yedi (kat göğü) bina ettik."},{"n":13,"t":"(Orada) aydınlatan bir kandil (güneş) yarattık."},{"n":"14-16","t":"Tohumlar, bitkiler (ve ağaçları) sarmaş dolaş olmuş bahçeler yetiştirmeniz için sıkışan bulutlardan şarıl şarıl akan sular indirdik."},{"n":17,"t":"Şüphesiz ki ayrılma günü belirlenmiş bir vakittir."},{"n":18,"t":"Sûr’a üflenileceği gün, bölük bölük (Allah’ın huzuruna) geleceksiniz."},{"n":19,"t":"(O gün) gök açılacak ve kapı kapı olacaktır."},{"n":20,"t":"Dağlar da yürütülmüş, serap hâline getirilmiş (olacak)tır."},{"n":"21-22","t":"Şüphesiz ki cehennem, azgınların durağı olarak (cehennemlikleri) gözetlemektedir."},{"n":23,"t":"(Azgınlar) orada çağlar boyu kalacaklardır."},{"n":"24-26","t":"(Dünyadaki inkârlarına) uygun bir karşılık olarak kaynar su ve irinden başka orada hiçbir serinlik veya (susuzluk gideren) hiçbir içecek tadamayacaklardır."},{"n":27,"t":"Şüphesiz ki onlar hesabı ummazlardı."},{"n":28,"t":"Ayetlerimizi de yalanladıkça yalanlamışlardı."},{"n":29,"t":"Biz ise her şeyi bir kitapta sayıp kaydetmişizdir."},{"n":30,"t":"Tadın (azabı)! Bundan sonra yalnızca azabınızı artıracağız."},{"n":31,"t":"Şüphesiz ki muttakîler (duyarlı olanlar) için ödül(ler) vardır:"},{"n":32,"t":"Bahçeler ve üzüm bağları,"},{"n":33,"t":"Uyumlu (olgunlaşmış üzüm) taneleri,"},{"n":34,"t":"Dolu kadeh(ler)."},{"n":35,"t":"Onlar orada boş bir söz de yalan da duymayacaklar."},{"n":"36-37","t":"Bunlar senin Rabbinden, yani göklerin, yerin ve ikisi arasında bulunanların Rahmân olan Rabbinden hesapsız bir bağış ve ödül olarak (verilecektir). O’nun huzurunda konuşmaya güç yetiremezler."},{"n":38,"t":"Ruh(lar)ın ve meleklerin sıra sıra duracakları o gün, Rahmân’ın izin verdiklerinden başkası konuşamayacaktır; (konuşan da) doğruyu söyleyecektir."},{"n":39,"t":"İşte o gün gerçektir. Dileyen, Rabbine bir dönüş (yolu) tutar."},{"n":40,"t":"Şüphesiz ki biz sizi yakın bir azap ile uyardık. O gün kişi önceden yaptıklarına bakacak ve kâfir (olanlar) “Ah, keşke toprak olsaydım!” diyecektir."}],[{"n":1,"t":"Yemin olsun: Söküp çıkaranlara,"},{"n":2,"t":"Kolayca çekenlere,"},{"n":3,"t":"Yüzdükçe yüzenlere,"},{"n":4,"t":"Yarışıp geçenlere,"},{"n":5,"t":"İşleri düzenleyenlere ki"},{"n":6,"t":"O gün o sarsıcı (deprem) sarsacak."},{"n":7,"t":"(Ardından onu) artçısı takip edecek."},{"n":8,"t":"Kalpler (korkudan) titreyecek."},{"n":9,"t":"Gözleri (korkudan) aşağı kayacak."},{"n":"10-11","t":"“Çürümüş kemik olduktan sonra, çukurda (mezarda) daha önceki hâlimize mi döndürüleceğiz” derler."},{"n":12,"t":"“O zaman, o zararlı bir dönüş olur!” derler."},{"n":13,"t":"(Oysa) bu dönüş, tek bir ses(e bakar)."},{"n":14,"t":"Bir de bakarsın ki onlar, mahşerdedir."},{"n":15,"t":"Musa’nın haberi sana geldi, (değil) mi?"},{"n":16,"t":"Hani Rabbi kutsal Tuvâ Vadisi’nde ona şöyle seslenmişti:"},{"n":17,"t":"“Firavun’a git! O iyice azdı.”"},{"n":18,"t":"“(Ona) de ki: “Arınmak ister misin?"},{"n":19,"t":"(İstiyorsan) seni Rabbine yönlendireyim. (Böylece O’na) saygı duyarsın.”"},{"n":20,"t":"Sonunda ona en büyük ayeti (mucizeyi) göstermişti."},{"n":21,"t":"(Ancak Firavun, gerçeği) yalanlamış ve isyan etmişti."},{"n":22,"t":"Sonra hızlıca arkasını dönüp gitmişti."},{"n":"23-24","t":"(Yandaşlarını) toplamış, onlara seslenmiş ve demişti ki: “Ben sizin yüce rabbinizim.”"},{"n":25,"t":"(Bunun üzerine) Allah onu ahiret ve dünya azabıyla yakalamıştı."},{"n":26,"t":"Şüphesiz ki bu (kıssa)da saygı duyacak olanlar için bir ibret vardır."},{"n":27,"t":"Sizin yaratılışınız mı daha güçlüdür, yoksa (Allah’ın) oluşturduğu gök mü?"},{"n":28,"t":"(Göğün) cisimlerini yükseltmiş ve onları düzene kavuşturmuştur."},{"n":29,"t":"Gecesini karanlık yapmış, (gündüz) ışığını çıkarıp var etmiştir."},{"n":30,"t":"Daha sonra da yeri yaymıştır."},{"n":31,"t":"Ondan (yerden) suyunu ve bitki örtüsünü de O çıkarmıştır."},{"n":32,"t":"Dağları (yere) O çakmıştır."},{"n":33,"t":"Sizin ve hayvanlarınızın yararlanması için (böyle yapmıştır)."},{"n":"34-35","t":"O büyük olay gerçekleştiğinde, işte o gün insan (dünyada) neler yaptığını hatırlayacaktır."},{"n":36,"t":"Gör(mesi gerek)enler için cehennem ortaya çıkartılacaktır."},{"n":"37-39","t":"Kim azgınlık yapmış ve dünya hayatını tercih etmişse cehennem (onların) barınağıdır."},{"n":"40-41","t":"Rabbinin makamından korkan ve kendisini arzulara (uymaktan) alıkoyanlara gelince, şüphesiz ki böylelerinin barınağı da cennettir."},{"n":42,"t":"Sana o (Son) Saat’in demir atma zamanından soruyorlar."},{"n":43,"t":"Sen onu nerden hatırlayabilirsin ki!"},{"n":44,"t":"Sonu(nun bilgisi) yalnızca Rabbine aittir."},{"n":45,"t":"Sen sadece ondan (Son Saat’ten) saygı ile korkanları uyarıcısın."},{"n":46,"t":"Onu (mahşeri) gördükleri gün, (dünyada sanki) bir yatsı vakti veya (gündüzün) kuşluğu kadar kalmış gibi olacaklar."}],[{"n":"1-2","t":"Görme engelli biri ona geldi diye yüzünü ekşitti ve arkasını döndü."},{"n":"3-4","t":"O (azgın Mekkeli)nin arınacağını veya (gerçeği) hatırlayıp bunun ona yarar sağlayacağını sana bildirecek olan ne olabilir ki!"},{"n":"5-6","t":"Kendini zengin (ihtiyaçsız) gören bu kişiye gelince, sen ona yöneliyorsun."},{"n":7,"t":"Oysa onun temizlenip arınmamasından sen sorumlu değilsin."},{"n":"8-10","t":"Fakat (Allah’a) saygı ile koşarak sana gelenle ilgilenmiyorsun."},{"n":11,"t":"Hayır! Şüphesiz ki bunlar, (gerçeğin) hatırlatılmasıdır."},{"n":12,"t":"Dileyen onu (Kur’an’ı) hatırlar."},{"n":"13-16","t":"(Kur’an) kıymetli ve güvenilir elçilerin ellerinde, yüceltilmiş, arındırılmış, kutsal, değerli sahifelerdedir."},{"n":17,"t":"Kahrolası o insan ne kadar da nankördür!"},{"n":18,"t":"(Allah) onu hangi şeyden yarattı (bir düşünse ya)?"},{"n":19,"t":"Bir nutfeden (zigottan) yaratıp ona şekil verir."},{"n":20,"t":"Sonra ona yolu kolaylaştırır."},{"n":21,"t":"Daha sonra onu öldürüp kabre koydurur."},{"n":22,"t":"En sonunda dilediği zaman onu yeniden diriltir."},{"n":23,"t":"Gerçek şu ki (insan, Allah’ın) ona emrettiğini yerine getirmedi."},{"n":24,"t":"Bu insan, yiyeceğine bir baksın!"},{"n":25,"t":"Suyu bolca indirdik."},{"n":26,"t":"Toprağı yardıkça yardık."},{"n":27,"t":"Orada (toprakta) taneler yetiştirdik."},{"n":28,"t":"Üzüm ve sebze,"},{"n":29,"t":"Zeytin ve hurma,"},{"n":30,"t":"Gür (ağaçlı) bahçe,"},{"n":31,"t":"Meyve ve çayır,"},{"n":32,"t":"Sizin ve hayvanlarınızın yararlanması için (böyle yaptık)."},{"n":33,"t":"Kulakları sağır eden o ses geldiği zaman,"},{"n":"34-36","t":"O gün kişi kardeşinden, annesinden, babasından, hanımından (eşinden) ve çocuğundan kaçar."},{"n":37,"t":"(Çünkü) o gün, her kişinin kendisine yetecek bir işi olacaktır."},{"n":38,"t":"O gün bazı yüzler aydınlıktır."},{"n":39,"t":"(Onlar) güler, müjdeyle sevinir."},{"n":40,"t":"O gün bazı yüzlerde de toz (hüzün) vardır."},{"n":41,"t":"(Onları âdeta) karanlık kaplamıştır."},{"n":42,"t":"İşte onlar -evet onlar- kâfirlerdir, (doğru yoldan) sapanlardır."}],[{"n":1,"t":"Güneş dürüldüğünde,"},{"n":2,"t":"Yıldızlar (sönüp) döküldüğünde,"},{"n":3,"t":"Dağlar yürütüldüğünde,"},{"n":4,"t":"On aylık (değerli) gebe develer bırakıldığında,"},{"n":5,"t":"Yabani hayvanlar bir araya toplandığında,"},{"n":6,"t":"Denizler kaynatıldığında (Son Saat gerçekleşmiş olacaktır)."},{"n":7,"t":"Ruhlar (bedenlerle) eşleştirildiğinde,"},{"n":"8-9","t":"Diri diri gömülen kız çocuğuna hangi günah(ı) yüzünden öldürüldüğü sorulduğunda,"},{"n":10,"t":"(Amel) defterler(i) açıldığında,"},{"n":11,"t":"Gök sıyrıldığında,"},{"n":12,"t":"Cehennem alevlendirildiğinde,"},{"n":13,"t":"Cennet yaklaştırıldığında"},{"n":14,"t":"Her can (ahiret için dünyada) neler hazırladığını bilmiş (olacak)tır."},{"n":15,"t":"Hayır! Yemin ederim: Kaybolan (yıldız)lara,"},{"n":16,"t":"(Yörüngelerinde) akıp gizlenen (gezegen)lere,"},{"n":17,"t":"Kararmaya başlayan geceye,"},{"n":18,"t":"Nefes almaya (aydınlanmaya) başlayan sabaha ki"},{"n":19,"t":"Şüphesiz o (Kur’an), değerli bir elçinin (Cebrail’in ulaştırdığı) sözüdür."},{"n":20,"t":"(O elçi), arşın sahibi (olan Allah) katında çok itibarlıdır."},{"n":21,"t":"Orada (kendisine) itaat edilen, güvenilendir."},{"n":22,"t":"Arkadaşınız asla cinlenmiş değildir."},{"n":23,"t":"Yemin olsun ki onu (Cebrail’i) apaçık ufukta görmüştü."},{"n":24,"t":"O, gayb (bilinemeyenler) hakkında cimri değildir."},{"n":25,"t":"O (Kur’an), asla kovulmuş şeytanın sözü değildir."},{"n":26,"t":"Gidişiniz nereye!"},{"n":"27-28","t":"O (Kur’an) âlemler için, yani içinizden doğru yolda gitmek isteyenler için ancak bir hatırla(t)madır."},{"n":29,"t":"(Böylece), âlemlerin Rabbi olan Allah’ın dilediğinden başkasını dilememiş olursunuz."}],[{"n":1,"t":"Gök yarıldığında,"},{"n":2,"t":"Gezegenler serpiştirildiğinde,"},{"n":3,"t":"Denizler fışkırtıl(ıp kabar)tıldığında,"},{"n":4,"t":"Mezarlar(ın içindekiler dışarı) çıkartıldığında,"},{"n":5,"t":"Her can (dünyada yapıp) öne sürdüklerini ve (yapmayıp) geride bıraktıklarını bilmiş (olacak)tır."},{"n":6,"t":"Ey insan! Cömert Rabbine karşı seni aldatan nedir?"},{"n":7,"t":"O ki seni yarattı, şekillendirdi, dengeli kıldı."},{"n":8,"t":"Dilediği şekilde seni oluşturdu."},{"n":9,"t":"Hayır! Doğrusu siz dini (hesap gününü) yalanlıyorsunuz."},{"n":"10-12","t":"Üzerinizde, yapmakta olduklarınızı bilen, değerli yazıcılardan oluşan kaydediciler (melekler) vardır."},{"n":13,"t":"Şüphesiz ki iyiler, elbette nimet içinde (olacak)tır."},{"n":14,"t":"Şüphesiz ki (yoldan) sapanlar ise cehennemde (olacak)tır."},{"n":15,"t":"Hesap gününde oraya gireceklerdir."},{"n":16,"t":"Oradan asla kurtulamayacaklardır."},{"n":17,"t":"Hesap gününün ne olduğunu sana bildiren ne olabilir ki!"},{"n":18,"t":"Evet! O Hesap gününün ne olduğunu sana bildiren ne olabilir ki!"},{"n":19,"t":"O gün, kimse kimse için herhangi bir şeye (yetkiye) sahip olamaz. O gün, yetki yalnızca Allah’a aittir."}],[{"n":1,"t":"Eksik ölçenlere (yolsuzluk yapanlara) yazıklar olsun!"},{"n":2,"t":"Onlar insanlardan (bir şey alırken) ölçtüklerinde (baskı yaparak) tam ölçerler."},{"n":3,"t":"Onlara (insanlara vermek için) ölçtüklerinde veya tarttıklarında ise eksiltirler."},{"n":"4-6","t":"Büyük bir günde yani insanların, âlemlerin Rabbinin huzurunda duracakları günde diriltileceklerini hiç düşünmezler mi?"},{"n":7,"t":"Hayır! Şüphesiz ki (yoldan) sapanların yazısı (kaydı) Siccîn’dedir."},{"n":8,"t":"Siccîn’in ne olduğunu sana bildiren ne olabilir ki!"},{"n":9,"t":"Numaralandırılmış (açıkça yazılı) bir kitaptır."},{"n":"10-11","t":"Hesap gününü yalanlayan yalancıların o gün vay hâline!"},{"n":12,"t":"Onu günahkâr azgınlardan başkası yalanlamaz."},{"n":13,"t":"Ona ayetlerimiz tilavet edildiği (okunup aktarıldığı) zaman “Öncekilerin masalları!” der."},{"n":14,"t":"Hayır, aksine! Kazandıkları (kötülükler nedeniyle) kalplerinin üzerinde pas tutmuştur."},{"n":15,"t":"Hayır! Şüphesiz ki onlar o gün Rablerinden perdelenmiş (mahrum) olacaklardır."},{"n":16,"t":"Sonra, şüphesiz ki onlar cehenneme girecekler."},{"n":17,"t":"Sonra (kendilerine) “Yalanlamış olduğunuz (cehennem) işte budur.” denecektir."},{"n":18,"t":"Doğrusu, şüphesiz ki iyilerin kaydı ise ‘Illiyyûn’dadır."},{"n":19,"t":"‘Illiyyûn’un ne olduğunu sana bildiren ne olabilir ki!"},{"n":20,"t":"Numaralandırılmış (açıkça yazılı) bir kitaptır."},{"n":21,"t":"Onu (kitabı, Allah’a) yaklaştırılmış olanlar (sevinçle) görür."},{"n":22,"t":"Şüphesiz ki iyiler, elbette nimet içindedir."},{"n":23,"t":"Koltuklar üzerinde (etrafa) bakarlar."},{"n":24,"t":"Nimetin parıltısını yüzlerinde sezersin (görürsün)."},{"n":25,"t":"Kendilerine (ağzı) mühürlü, katıksız (sarhoş etmeyen) bir (içki)den içirilir."},{"n":26,"t":"(İçiminin) sonu misk olacaktır (güzel kokacaktır). Yarışanlar işte bunun için yarışsınlar!"},{"n":27,"t":"Onun (içeceğin) karışımı Tesnîm’dendir."},{"n":28,"t":"(Tesnîm, Allah’a) yaklaştırılmış olanların içeceği bir kaynaktır."},{"n":29,"t":"Şüphesiz ki suçlular (dünyada) iman edenlere gülerlerdi."},{"n":30,"t":"Onlara uğradıklarında birbirlerine kaş göz işareti yaparlardı."},{"n":31,"t":"Ailelerine döndüklerinde keyiflenerek dönerlerdi."},{"n":32,"t":"Onları (müminleri) gördüklerinde ise “Şüphesiz ki bunlar sapkınlardır!” derlerdi."},{"n":33,"t":"(Oysa) onların (müminlerin) üzerine koruyucular (muhafız) olarak gönderilmemişlerdi."},{"n":"34-35","t":"İman edenler de bugün, koltuklar üzerinde (onlara) bakarak kâfirlere gülerler."},{"n":36,"t":"Kâfirler yaptıklarının cezasını buldular mı!"}],[{"n":1,"t":"Gök yarıldığında,"},{"n":2,"t":"Rabbin(in emrin)e kulak verip (hüküm) gerçekleştirildiği(nde),"},{"n":3,"t":"Yer genişletilerek yayıldığında,"},{"n":4,"t":"İçindekileri dışarı atıp boşaldığı(nda),"},{"n":5,"t":"Rabbin(in emrin)e kulak verip (hüküm) gerçekleştirildiği(nde mahşerde toplanacaksınız)."},{"n":6,"t":"Ey insan! Şüphesiz ki Rabbine (giden yolda) çaba üstüne çaba gösteriyorsun ve (sonunda) O’na varacaksın."},{"n":7,"t":"Kimin kitabı (amel defteri), sağından verilirse,"},{"n":8,"t":"Kolay bir hesapla hesaba çekilecek,"},{"n":9,"t":"Sevinçli (bir şekilde) ailesine dönecektir."},{"n":10,"t":"Kimin de kitabı (amel defteri) sırtının arkasından verilirse,"},{"n":11,"t":"Hemen yok olmayı dileyecek,"},{"n":12,"t":"Alevli ateşe girecektir."},{"n":13,"t":"Şüphesiz ki o, (dünyadayken) ailesinin (arkadaşlarının) içinde çok mutluydu."},{"n":14,"t":"Şüphesiz ki o, (Rabbine) dönmeyeceğini sanıyordu."},{"n":15,"t":"Hayır! Şüphesiz ki Rabbi onu görendir."},{"n":16,"t":"Hayır! Yemin ederim: Akşamın alaca karanlığına,"},{"n":17,"t":"Geceye ve topladığı (örttüğü) şeylere,"},{"n":18,"t":"Dolunay halindeki aya ki"},{"n":19,"t":"Siz elbette bir hâlden (başka) bir hâle geçeceksiniz."},{"n":20,"t":"Onlara ne oluyor da inanmıyorlar!"},{"n":21,"t":"Kendilerine Kur’an okunduğu zaman secde de etmiyorlar!"},{"n":22,"t":"Aksine o kâfir olanlar yalanlıyorlar."},{"n":23,"t":"Allah onların gizlediği şeyleri çok iyi bilendir."},{"n":24,"t":"Onlara elem verici bir azabı müjdele!"},{"n":25,"t":"İman edip iyi işler yapanlar başkadır; onlar için başa kakılmayan (kesintisiz) bir ödül vardır."}],[{"n":1,"t":"Yemin olsun: Burçları olan göğe,"},{"n":2,"t":"Vadedilen o güne,"},{"n":3,"t":"Şahit(ler)e ve şahitlik edilen(ler)e."},{"n":4,"t":"4-5 Tutuşturulmuş yakıt(la) dolu o ateş(li) çukur(un) halkı kahrolsun!"},{"n":5,"t":"4-5 Tutuşturulmuş yakıt(la) dolu o ateş(li) çukur(un) halkı kahrolsun!"},{"n":6,"t":"6-7 Hani onlar o (ateşli çukur)un başında oturmuş, müminlere yaptıkları (işkenceyi) seyrediyorlardı."},{"n":7,"t":"6-7 Hani onlar o (ateşli çukur)un başında oturmuş, müminlere yaptıkları (işkenceyi) seyrediyorlardı."},{"n":8,"t":"Onlardan (müminlerden) yalnızca güçlü ve övgüye layık olan Allah’a iman etmeleri nedeniyle intikam alıyorlardı."},{"n":9,"t":"O ki göklerin ve yerin otoritesi kendisine aittir. Allah her şeye şahittir."},{"n":10,"t":"Şüphesiz ki inanmış erkeklerle inanmış kadınlara işkence edip sonra tevbe etmeyenlere cehennem azabı vardır ve onlar için yakıcı azap vardır."},{"n":11,"t":"Şüphesiz ki iman edip iyi işler yapanlar için ise altlarından ırmaklar akan cennetler vardır. İşte büyük kurtuluş budur."},{"n":12,"t":"Şüphesiz ki Rabbinin yakalaması çok şiddetlidir."},{"n":13,"t":"Şüphesiz ki O, başlatan ve tekrarlayandır."},{"n":14,"t":"O çok bağışlayandır, çok sevendir."},{"n":15,"t":"Arşın sahibidir; yücedir."},{"n":16,"t":"İstediği şeyi daima yapandır."},{"n":17,"t":"17-18 Firavun ve Semûd ordularının haberi sana geldi, (değil) mi?"},{"n":18,"t":"17-18 Firavun ve Semûd ordularının haberi sana geldi, (değil) mi?"},{"n":19,"t":"Doğrusu, kâfir olanlar bir yalanlama içindedir."},{"n":20,"t":"(Fakat) Allah onları arkalarından kuşatandır."},{"n":21,"t":"Doğrusu o yüce bir Kur’an’dır."},{"n":22,"t":"Levh-i Mahfûz’dadır (Korunmuş bir levhadadır)."}],[{"n":1,"t":"Göğe ve Târık’a yemin olsun!"},{"n":2,"t":"Târık’ın ne olduğunu sana bildiren ne olabilir ki!"},{"n":3,"t":"(O, karanlığı) delen yıldızdır."},{"n":4,"t":"Üzerinde bir gözetleyici (melek) olmayan hiçbir can yoktur."},{"n":5,"t":"İnsan, neyden yaratıldığına bir baksın!"},{"n":6,"t":"6-7 Omurga ile kaburga kemikleri arasından çıkan (akan) bir sudan (sıvıdan) yaratıldı."},{"n":7,"t":"6-7 Omurga ile kaburga kemikleri arasından çıkan (akan) bir sudan (sıvıdan) yaratıldı."},{"n":8,"t":"Şüphesiz ki O (Allah) onu geri döndürmeye (tekrar yaratmaya) gücü yetendir."},{"n":9,"t":"9-10 Sırların ortaya döküleceği o gün, onun (insanın) hiçbir gücü ve yardımcısı yoktur."},{"n":10,"t":"9-10 Sırların ortaya döküleceği o gün, onun (insanın) hiçbir gücü ve yardımcısı yoktur."},{"n":11,"t":"Yemin olsun: Dönüş sahibi olan göğe,"},{"n":12,"t":"Yarılan yere ki"},{"n":13,"t":"Şüphesiz ki o (Kur’an, doğru ile yanlışı) ayırt eden bir sözdür."},{"n":14,"t":"O asla bir şaka değildir."},{"n":15,"t":"Şüphesiz ki onlar bir tuzak kuruyor."},{"n":16,"t":"Ben de bir tuzak kuruyorum."},{"n":17,"t":"Kâfirlere mühlet ver, onlara biraz zaman tanı."}],[{"n":1,"t":"Yüce Rabbinin adını tesbih et (yücelt)!"},{"n":2,"t":"(O), yaratan ve düzene koyandır."},{"n":3,"t":"Ölçü koyandır ve yol gösterendir."},{"n":4,"t":"(Topraktan) otlağı çıkarandır."},{"n":5,"t":"Sonra da onu kapkara kuru ota çevirendir."},{"n":6,"t":"6-7 Sana (Kur’an’ı) okutacağız ve sen -Allah’ın dilemesi hariç- (onu) unutmayacaksın. Şüphesiz ki O, açığı da gizli olanı da bilir."},{"n":7,"t":"6-7 Sana (Kur’an’ı) okutacağız ve sen -Allah’ın dilemesi hariç- (onu) unutmayacaksın. Şüphesiz ki O, açığı da gizli olanı da bilir."},{"n":8,"t":"Kolay olanı sana (daha da) kolaylaştıracağız."},{"n":9,"t":"Hatırlamak yarar sağlayacağı için (gerçeği) hatırlat!"},{"n":10,"t":"(Allah’a) saygılı olan kişi (gerçeği) hatırlayacaktır."},{"n":11,"t":"En azgın (kâfir) ise ondan kaçınacaktır."},{"n":12,"t":"O en büyük ateşe girecek olandır."},{"n":13,"t":"Sonra, orada (tam) ölmeyecek ve (tam) yaşamayacak."},{"n":14,"t":"Arınan kişi elbette kurtulmuştur."},{"n":15,"t":"Rabbinin adını anıp salât edenler de (O’nun dinine destek olanlar da)."},{"n":16,"t":"Fakat siz dünya hayatını tercih ediyorsunuz."},{"n":17,"t":"(Oysa) ahiret daha iyi ve daha kalıcıdır."},{"n":18,"t":"Şüphesiz ki bu (anlatılanlar), önceki sahifelerde de (vahiylerde de) vardı:"},{"n":19,"t":"İbrahim’in ve Musa’nın sahifelerinde."}],[{"n":1,"t":"(Her şeyi) kaplayacak olanın haberi sana geldi, (değil) mi?"},{"n":2,"t":"O gün bazı yüzler düşüktür."},{"n":3,"t":"(Onlar) çalışandır, yorulandır."},{"n":4,"t":"Kızgın ateşe girecektir."},{"n":5,"t":"Kaynar bir (su) kaynağından (kendilerine) içirilecektir."},{"n":6,"t":"Onlar için kuru dikenden başka yiyecek yoktur."},{"n":7,"t":"Hem beslemez hem de açlığı gidermez."},{"n":8,"t":"O gün bazı yüzler de nimet içindedir (mutludur)."},{"n":9,"t":"Çalışmalarından memnundur."},{"n":10,"t":"Yüksek bir cennettedir."},{"n":11,"t":"Orada boş söz duymaz."},{"n":12,"t":"Orada akan (su) kaynağı var."},{"n":13,"t":"Orada yükseltilmiş tahtlar var."},{"n":14,"t":"Konulmuş kadehler,"},{"n":15,"t":"Dizilmiş yastıklar,"},{"n":16,"t":"Serilmiş halılar (var)."},{"n":17,"t":"Bakmazlar mı o deveye, nasıl yaratılmış!"},{"n":18,"t":"Göğe, nasıl yükseltilmiş!"},{"n":19,"t":"Dağlara, nasıl dikilmiş!"},{"n":20,"t":"Yere, nasıl yayılmış!"},{"n":21,"t":"Hatırlat! Sen sadece hatırlatıcısın."},{"n":22,"t":"Onların üzerinde bir zorba değilsin."},{"n":23,"t":"Ancak, kim yüz çevirir ve inkâr ederse,"},{"n":24,"t":"Allah ona en büyük azapla azap eder."},{"n":25,"t":"Şüphesiz ki onların dönüşü sadece bizedir."},{"n":26,"t":"Sonra onların hesabı da şüphesiz ki sadece bize aittir."}],[{"n":1,"t":"Yemin olsun: Tan vaktine,"},{"n":2,"t":"On geceye,"},{"n":3,"t":"‘Çift’e ve ‘tek’e,"},{"n":4,"t":"Geçmekte olan geceye ki"},{"n":5,"t":"Akıl sahibi için bun(lar)da bir yemin var değil mi?"},{"n":6,"t":"Rabbin (şunlara) ne yaptı görmedin mi: Âd (kavmine),"},{"n":7,"t":"7-8 (Yüksek) sütunları olan İrem (şehrine) -ki şehirler içinde onun benzeri yaratılmamıştı."},{"n":8,"t":"7-8 (Yüksek) sütunları olan İrem (şehrine) -ki şehirler içinde onun benzeri yaratılmamıştı."},{"n":9,"t":"Vadideki kayaları oyan Semûd (kavmine),"},{"n":10,"t":"Kazıklar sahibi Firavun’a."},{"n":11,"t":"Onlar şehirlerde azgınlık etmişlerdi."},{"n":12,"t":"Orada bozgunculuğu çoğaltmışlardı."},{"n":13,"t":"Bu yüzden Rabbin onların üzerine azap kırbacını yağdırmıştı."},{"n":14,"t":"Şüphesiz ki Rabbin, (sürekli) gözetlemektedir."},{"n":15,"t":"İnsana gelince, Rabbi kendisini imtihan edip ona ikramda bulunduğunda ve bol nimet verdiğinde “Rabbim bana ikram etti.” der."},{"n":16,"t":"(Fakat) ne zaman onu imtihan edip rızkını daralttığında ise “Rabbim beni küçük düşürdü (önemsemedi)” der."},{"n":17,"t":"Hayır! Doğrusu, siz yetime ikram etmiyorsunuz."},{"n":18,"t":"Yoksulu yedirmeye de birbirinizi teşvik etmiyorsunuz."},{"n":19,"t":"Mirası hırslı bir yiyişle (helal-haram demeden) yiyorsunuz."},{"n":20,"t":"Malı çok (aşırı) bir sevgiyle seviyorsunuz."},{"n":21,"t":"21-22 Hayır! Yer şiddetli bir sarsıntıyla sarsıldığı, melekler sıra sıra (dururken) Rabbin(in emri) geldiği zaman (haliniz nasıl olacak?)"},{"n":22,"t":"21-22 Hayır! Yer şiddetli bir sarsıntıyla sarsıldığı, melekler sıra sıra (dururken) Rabbin(in emri) geldiği zaman (haliniz nasıl olacak?)"},{"n":23,"t":"O gün, cehennem getirilecek ve insan (yaptıklarını) hatırlayacaktır. Ama (artık) bu hatırlamanın kendisine ne (yarar)ı olabilir ki!"},{"n":24,"t":"(O insan:) “Ah, keşke, bu hayatım için (dünyadayken iyi) bir şeyler gönderseydim!” diyecektir."},{"n":25,"t":"O gün, O’nun (Allah’ın) edeceği azap (gibi) kimse azap edemez."},{"n":26,"t":"O’nun (vuracağı) bağ (gibi) kimse bağ vuramaz."},{"n":27,"t":"Ey huzura kavuşan nefis (insan)!"},{"n":28,"t":"Sen (Allah’tan) memnun, (Allah da) senden razı olarak Rabbine dön!"},{"n":29,"t":"(İyi) kullarım(ın) arasına katıl"},{"n":30,"t":"Cennetime gir!"}],[{"n":1,"t":"Hayır bu şehre (Mekke’ye) yemin ederim."},{"n":2,"t":"Ki sen bu şehirde oturmaktasın."},{"n":3,"t":"Babaya ve çocuğa (da yemin ederim)."},{"n":4,"t":"Şüphesiz ki biz insanı zorluklar konusunda (dayanıklı) yarattık."},{"n":5,"t":"(O insan) kimsenin kendisine güç yetiremeyeceğini mi sanıyor?"},{"n":6,"t":"(Övünerek) “Pek çok mal harcadım.” diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor!"},{"n":8,"t":"8-9 Biz ona iki göz, bir dil ve iki dudak vermedik mi?"},{"n":9,"t":"8-9 Biz ona iki göz, bir dil ve iki dudak vermedik mi?"},{"n":10,"t":"Ona iki yolu da gösterdik."},{"n":11,"t":"(Fakat) o, sarp yokuşu (aşmayı) göze almadı."},{"n":12,"t":"O ‘sarp yokuş’un ne olduğunu sana bildiren ne olabilir ki!"},{"n":13,"t":"(Sarp yokuş); köleyi özgürlüğüne kavuşturmaktur."},{"n":14,"t":"14-16 Veya açlık gün(ün)de yakın(ı) olan bir yetimi veya (karnı) toprağa yapışmış (hiçbir şeyi olmayan) yoksulu doyurmaktır."},{"n":15,"t":"14-16 Veya açlık gün(ün)de yakın(ı) olan bir yetimi veya (karnı) toprağa yapışmış (hiçbir şeyi olmayan) yoksulu doyurmaktır."},{"n":16,"t":"14-16 Veya açlık gün(ün)de yakın(ı) olan bir yetimi veya (karnı) toprağa yapışmış (hiçbir şeyi olmayan) yoksulu doyurmaktır."},{"n":17,"t":"Sonra da iman edenlerden, birbirlerine sabrı tavsiye edenlerden ve merhameti tavsiye edenlerden olmaktır."},{"n":18,"t":"İşte onlar sağın halkıdır."},{"n":19,"t":"Ayetlerimizi inkâr edenler ise işte onlar solun halkıdır."},{"n":20,"t":"Onlar(ın cezası, kapıları) üzerlerine kilitlenmiş ateştir."}],[{"n":1,"t":"Yemin olsun: Güneşe ve onun aydınlığına,"},{"n":2,"t":"Onu izlediğinde aya,"},{"n":3,"t":"Onu açığa çıkarttığında gündüze,"},{"n":4,"t":"Onu kapladığında geceye,"},{"n":5,"t":"Göğe ve onu bina edene,"},{"n":6,"t":"Yere ve onu yayana,"},{"n":7,"t":"Nefse (insana) ve onu biçimlendirene,"},{"n":8,"t":"Sonra da ona (nefse), kötülük ve takvâ (duyarlılık) kabiliyetini verene ki"},{"n":9,"t":"Onu (nefsini) arındıran kişi elbette kurtulmuştur."},{"n":10,"t":"Onu (kötülüğe) gömen kişi ise kaybetmiştir."},{"n":11,"t":"Semûd (kavmi) azgınlığı yüzünden (gerçeği) yalanlamıştı."},{"n":12,"t":"Onların en azgını (deveyi kesmek için) ileri atılmıştı."},{"n":13,"t":"Allah’ın elçisi (Salih) onlara “Allah’ın devesine ve onun su hakkına (dokunmayın)” demişti."},{"n":14,"t":"(Fakat) onlar onu (elçiyi) yalanlamış ve o (deve)yi de kesmişlerdi. (Bunun üzerine), Rableri günahlarını başlarına geçirmiş ve orayı yerle bir etmişti."},{"n":15,"t":"(Bu toplum) kendi sonundan da korkmuyordu."}],[{"n":1,"t":"Yemin olsun: (Karanlığı)yla kapladığında geceye,"},{"n":2,"t":"Ortaya çıktığında gündüze,"},{"n":3,"t":"Erkeği ve dişiyi yaratana ki"},{"n":4,"t":"İşleriniz çeşit çeşittir."},{"n":5,"t":"Kim (malını) verirse, takvâlı (duyarlı) davranırsa,"},{"n":6,"t":"En güzeli (Kur’an’ı) doğrularsa,"},{"n":7,"t":"Kolay olanı (cennete gitmeyi) ona kolaylaştıracağız."},{"n":8,"t":"Kim de cimrilik ederse, (kendini) zengin (yeterli) görürse,"},{"n":9,"t":"En güzeli (Kur’an’ı) yalanlarsa,"},{"n":10,"t":"Ona da zor olanı (cehenneme gitmeyi) kolaylaştıracağız."},{"n":11,"t":"Düştüğü zaman da malı kendisine yarar sağlamayacaktır."},{"n":12,"t":"Şüphesiz ki doğru yola ulaştırmak yalnızca bize aittir."},{"n":13,"t":"Şüphesiz ki ilk de son da (dünya da ahiret de) bizimdir."},{"n":14,"t":"Ben sizi alevli bir ateşe karşı uyardım."},{"n":15,"t":"Ona en azgın olandan başkası girmeyecektir."},{"n":16,"t":"O ki yalanladı ve sırtını döndü."},{"n":17,"t":"En muttakî (duyarlı) olan ondan uzak tutulacaktır."},{"n":18,"t":"O ki (malını) vererek arınır."},{"n":19,"t":"19-20 Yüce Rabbinin rızasını kazanmaktan başka, kimseden beklediği bir karşılık da yoktur."},{"n":20,"t":"19-20 Yüce Rabbinin rızasını kazanmaktan başka, kimseden beklediği bir karşılık da yoktur."},{"n":21,"t":"Kendisi de ileride memnun olacaktır."}],[{"n":1,"t":"Yemin olsun: Kuşluk vaktine,"},{"n":2,"t":"(Karanlığı) çöken geceye ki"},{"n":3,"t":"Rabbin, seni terk etmedi ve (sana) darılmadı."},{"n":4,"t":"Şüphesiz ki (peygamberliğinin) son (dönemi) ilk (dönem)inden daha iyi olacaktır."},{"n":5,"t":"Rabbin, yakında sana (nimetler) verecek ve sen memnun olacaksın."},{"n":6,"t":"Yetimken seni bulup barındırmadı mı?"},{"n":7,"t":"Şaşkınken seni bulup doğru yola ulaştırmıştı."},{"n":8,"t":"Yalnızken seni bulup zengin etmişti."},{"n":9,"t":"Yetimi sakın ezme!"},{"n":10,"t":"Sorup (yardım) isteyeni sakın azarlama!"},{"n":11,"t":"Sadece Rabbinin nimetini anlat!"}],[{"n":1,"t":"Senin için göğsünü ferahlatmadık mı?"},{"n":2,"t":"2-3 Belini büken yükünü senden atmıştık."},{"n":3,"t":"2-3 Belini büken yükünü senden atmıştık."},{"n":4,"t":"Senin için şanını da yüceltmiştik."},{"n":5,"t":"Şüphesiz ki her zorlukla birlikte bir kolaylık vardır."},{"n":6,"t":"(Evet), şüphesiz ki her zorlukla birlikte bir kolaylık vardır."},{"n":7,"t":"(Bir işi bitirip) boş kalınca hemen (başka bir işe) kalk."},{"n":8,"t":"Yalnızca Rabbine yönel!"}],[{"n":1,"t":"Yemin olsun: Tîn’e, Zeytûn’a,"},{"n":2,"t":"Sînâ Dağı’na,"},{"n":3,"t":"Bu güvenli şehre (Mekke’ye) ki"},{"n":4,"t":"Şüphesiz biz insanı en güzel biçimde yarattık."},{"n":5,"t":"Sonra onu aşağıların aşağısına çevirdik."},{"n":6,"t":"İman edip iyi işler yapanlar hariç. Onlar için başa kakılmayan (kesintisiz) bir ödül vardır."},{"n":7,"t":"Artık sana dini (hesap gününü) yalanlatan nedir?"},{"n":8,"t":"Allah hüküm verenlerin en üstünü değil midir!"}],[{"n":1,"t":"Yaratan Rabbinin adı ile oku!"},{"n":2,"t":"O, insanı ‘alaktan (embriyodan) yarattı."},{"n":3,"t":"Oku! Rabbin en cömert olandır!"},{"n":4,"t":"Kalemle (yazmayı) öğreten O’dur."},{"n":5,"t":"İnsana bilmediğini (O) öğretti."},{"n":6,"t":"6-7 Hayır! Şüphesiz ki insan, kendini zengin (ihtiyaçsız) gördüğü için azar."},{"n":7,"t":"6-7 Hayır! Şüphesiz ki insan, kendini zengin (ihtiyaçsız) gördüğü için azar."},{"n":8,"t":"Şüphesiz ki dönüş, yalnızca Rabbinedir."},{"n":9,"t":"9-10 Salât (ibadet) ederken bir kulu engelleyeni gördün mü!"},{"n":10,"t":"9-10 Salât (ibadet) ederken bir kulu engelleyeni gördün mü!"},{"n":11,"t":"11-12 Gördün mü? (Bir düşün:) Ya o (kul) doğru yol üzerindeyse veya takvâyı (duyarlılığı) emrediyorsa?"},{"n":12,"t":"11-12 Gördün mü? (Bir düşün:) Ya o (kul) doğru yol üzerindeyse veya takvâyı (duyarlılığı) emrediyorsa?"},{"n":13,"t":"Gördün mü? (Bir düşün:) Ya o, (gerçeği) yalanlıyor ve (ondan) yüz çeviriyorsa?"},{"n":14,"t":"Şüphesiz ki Allah’ın gördüğünü (bu adam) bilmez mi!"},{"n":15,"t":"Hayır! Bundan vazgeçmezse (onu) perçeminden yakalayacağız!"},{"n":16,"t":"O yalancı, günahkâr perçem(in)den!"},{"n":17,"t":"(O), meclisini (destekçilerini) çağırsın!"},{"n":18,"t":"İleride biz de zebanileri çağıracağız!"},{"n":19,"t":"Hayır! Ona itaat etme! (Rabbine) secde et ve (O’na) yaklaş!"}],[{"n":1,"t":"Şüphesiz ki biz onu (Kur’an’ı) Kadir gecesinde indir(meye başla)dık."},{"n":2,"t":"Kadir gecesinin ne olduğunu sana bildiren ne olabilir ki!"},{"n":3,"t":"Kadir gecesi bin aydan daha hayırlıdır."},{"n":4,"t":"Melekler, beraberlerinde rûh (Kur’an) ile, Rablerinin izniyle her iş için inerler."},{"n":5,"t":"(O), tan yeri ağarıncaya kadar esenlik (gecesi)dir."}],[{"n":1,"t":"Beyyine (apaçık bir elçi) kendilerine gelinceye kadar kitap ehlinden ve müşriklerden bazı nankörler (küfürden) ayrılacak değillerdi."},{"n":2,"t":"(O), Allah tarafından gönderilen ve tertemiz sahifeleri tilavet eden (okuyup aktaran) bir elçidir."},{"n":3,"t":"O (sahifeler)de doğru hükümler vardır."},{"n":4,"t":"Kendilerine kitap verilenler ancak o beyyine (apaçık bir elçi) kendilerine geldikten sonra ayrılığa düşmüşlerdi."},{"n":5,"t":"(Oysa) dini yalnız O’na özgü kılarak, hanîfler (Allah’ı birleyenler) olarak Allah’a kulluk etmeleri, namaz kılmaları ve zekât vermeleri kendilerine özellikle emredilmişti. İşte sağlam din budur."},{"n":6,"t":"Şüphesiz ki kitap ehlinden ve müşriklerden bazı nankörler, içinde ebedî kalacakları cehennem ateşinde (olacaklar)dır. İşte onlar yaratılmışların en kötüleridir."},{"n":7,"t":"Şüphesiz ki iman edip iyi işler yapanlara gelince; işte onlar ise yaratılmışların en iyileridir."},{"n":8,"t":"Rableri katındaki karşılıkları (ödülleri), altlarından ırmaklar akan, içinde ebedî kalacakları durmaya değer cennetlerdir. Allah kendilerinden razı, onlar da O’ndan memnun olmuşlardır. Bu (müjdeler), Rabbine saygı duyan(lar) içindir."}],[{"n":1,"t":"Yer, şiddetli sarsıntısıyla sarsıldığında,"},{"n":2,"t":"Yer, ağırlıklarını çıkarttığı(nda),"},{"n":3,"t":"İnsan “Buna (yere) ne oluyor?” dediği(nde),"},{"n":4,"t":"İşte o gün (yer), haberlerini söyler."},{"n":5,"t":"Çünkü Rabbin ona vahyetmiş (bildirmiş olacak)tır."},{"n":6,"t":"O gün, (yaptığı) işleri kendilerine gösterilsin diye insanlar grup grup çıkarlar."},{"n":7,"t":"Kim zerre kadar iyilik yaparsa onu görür."},{"n":8,"t":"Kim de zerre kadar kötülük yaparsa onu görür."}],[{"n":1,"t":"Yemin olsun: Soluk soluğa koşan düşmanlara"},{"n":2,"t":"Kıvılcım (öfke) saçanlara,"},{"n":3,"t":"Sabah vakti baskın yapanlara."},{"n":4,"t":"Bu sebeple, onlar tozu dumana katmışlardı"},{"n":5,"t":"Topluluğun ortasına dalmışlardı."},{"n":6,"t":"Şüphesiz ki böylesi insan, Rabbine karşı çok nankördür."},{"n":7,"t":"Şüphesiz ki buna kendisi de şahittir."},{"n":8,"t":"Şüphesiz ki onun mal sevgisi çok şiddetlidir."},{"n":9,"t":"Bilmez mi ki mezarlarda olanlar dışarı atıldığında,"},{"n":10,"t":"Göğüslerde (kalplerde) olanlar (gizlenenler) ortaya döküldüğünde,"},{"n":11,"t":"Şüphesiz ki Rableri o gün onlardan haberdardır."}],[{"n":1,"t":"Büyük çarpma!"},{"n":2,"t":"Nedir o büyük çarpma!"},{"n":3,"t":"O büyük çarpmanın ne olduğunu sana bildiren ne olabilir ki!"},{"n":4,"t":"O gün insanlar (dört bir yana) yayılmış pervaneler gibi olurlar."},{"n":5,"t":"Dağlar da atılmış yün gibi olur."},{"n":6,"t":"Terazi (de sevap) ları ağır gelen kişi,"},{"n":7,"t":"Memnun olacağı bir hayat içinde (olacak)tır."},{"n":8,"t":"8-9 Terazi (de sevap) ları hafif olana gelince, işte onun anası (yeri) Hâviye’dir."},{"n":9,"t":"8-9 Terazi (de sevap) ları hafif olana gelince, işte onun anası (yeri) Hâviye’dir."},{"n":10,"t":"Onun ne olduğunu sana bildiren ne olabilir ki!"},{"n":11,"t":"(O), kızgın bir ateş(tir)!"}],[{"n":1,"t":"Çoğaltma yarışı sizi oyaladı!"},{"n":2,"t":"Sonunda mezarlıkları (bile) ziyaret ettiniz."},{"n":3,"t":"Hayır! İleride bileceksiniz!"},{"n":4,"t":"Sonra, ileride elbette bileceksiniz!"},{"n":5,"t":"5-6 Hayır! Şüphesiz ki kesin bir bilgiyle bilseydiniz, ateşi (önceden) elbette görürdünüz."},{"n":6,"t":"5-6 Hayır! Şüphesiz ki kesin bir bilgiyle bilseydiniz, ateşi (önceden) elbette görürdünüz."},{"n":7,"t":"Sonra onu (ahirette) bizzat göreceksiniz."},{"n":8,"t":"Sonra o gün, (dünyada size verilen) nimetlerden elbette sorulacaksınız."}],[{"n":1,"t":"Asra yemin olsun ki"},{"n":2,"t":"Şüphesiz insan zarardadır."},{"n":3,"t":"İman edip iyi işler yapanlar, birbirlerine doğruyu tavsiye edenler ve birbirlerine sabrı tavsiye edenler hariç."}],[{"n":1,"t":"(Arkadan) çekiştiren (ve) kusur arayan herkese yazıklar olsun!"},{"n":2,"t":"O ki mal biriktirir ve onu sayar durur."},{"n":3,"t":"Şüphesiz ki o, malının kendisini ebedî kılacağını sanır."},{"n":4,"t":"Hayır! Şüphesiz ki o, Hutame’ye atılacaktır."},{"n":5,"t":"Hutame’nin ne olduğunu sana bildiren ne olabilir ki!"},{"n":6,"t":"(O), Allah’ın tutuşturulmuş ateşidir."},{"n":7,"t":"O (ateş) ki kalplerin üzerinde yükselir."},{"n":"8-9","t":"Şüphesiz ki o (ateş), uzatılmış sütunlarda onların üzerine kapatılıp kilitlenmiş (olacak)tır."}],[{"n":1,"t":"Rabbinin fil sahiplerine ne yaptığını görmedin mi?"},{"n":2,"t":"Onların tuzaklarını boşa çıkarmadı mı?"},{"n":3,"t":"Üzerlerine sürü sürü kuşlar göndermişti."},{"n":4,"t":"Onlara çamurdan sertleşmiş taşlar atıyorlar(dı)."},{"n":5,"t":"Böylece, onları yenilmiş ekin (tarlası) gibi yapmıştı."}],[{"n":1,"t":"Kureyş’in güvenliğini (sağladığı) için,"},{"n":2,"t":"Onların kış ve yaz yolculuklarının güvenliğini (sağladığı) için,"},{"n":3,"t":"Bu Ev’in (Kâbe’nin) Rabbine kulluk etsinler."},{"n":4,"t":"O ki onları açlıktan (kurtarıp) doyurdu ve korkudan güvene kavuşturdu."}],[{"n":1,"t":"Dini (hesap gününü) yalanlayanı gördün mü?"},{"n":2,"t":"İşte o, yetimi itip kakandır."},{"n":3,"t":"Yoksulu doyurmaya teşvik etmez."},{"n":4,"t":"Yazıklar olsun o salât (ibadet) edenlere."},{"n":5,"t":"Ki onlar (yaptıklarını sandığı) salâtlarından (ibadetlerinden) habersizdir."},{"n":6,"t":"Onlar gösteriş yaparlar."},{"n":7,"t":"(En ufak) yardıma (bile) engel olurlar."}],[{"n":1,"t":"Şüphesiz ki sana Kevser’i (bol nimet) verdik."},{"n":2,"t":"Rabbin için salât (ibadet) et ve kurban kes!"},{"n":3,"t":"Şüphesiz ki asıl (hayırdan yana) soyu kesik olan, sana kin duyandır."}],[{"n":1,"t":"De ki: “Ey kâfirler!"},{"n":2,"t":"Ben sizin tapmakta olduklarınıza tapmıyorum."},{"n":3,"t":"Siz de benim tapmakta olduğuma tapmıyorsunuz."},{"n":4,"t":"(Zaten) ben sizin tapmış olduklarınıza tapmıyordum."},{"n":5,"t":"Siz de benim taptığıma tapmıyordunuz."},{"n":6,"t":"Sizin dininiz size, benim dinim banadır!"}],[{"n":1,"t":"Allah’ın yardımı ve zafer geldiğinde,"},{"n":2,"t":"İnsanların Allah’ın dinine akın akın girdiğini gördüğünde,"},{"n":3,"t":"Rabbini hamd (övgü) ile tesbih et (yücelt) ve O’ndan bağışlanma dile. Şüphesiz ki O, tevbeleri çok kabul edendir."}],[{"n":1,"t":"Ebu Leheb’in iki eli (malı ve kazancı) kurusun (kahrolsun), kendisi de!"},{"n":2,"t":"Malı da kazancı da ona yarar sağlamadı."},{"n":"3-5","t":"O ve odun taşıyıcı(sı olarak) hanımı boynunda hurma lifinden bükülmüş bir iple alevli bir ateşe girecektir."}],[{"n":1,"t":"De ki: “O, Allah’tır; tektir."},{"n":2,"t":"Allah muhtaç değildir."},{"n":3,"t":"Doğurtmamıştır (kimsenin babası değildir) ve doğurulmamıştır (kimsenin çocuğu da değildir)."},{"n":4,"t":"O’nun dengi de yoktur.”"}],[{"n":1,"t":"De ki: “(Şunların şerrinden) ağaran sabahın Rabbine sığınırım:"},{"n":2,"t":"Yarattığı şeylerin şerrinden,"},{"n":3,"t":"Çöktüğü zaman karanlığın şerrinden,"},{"n":4,"t":"Düğümlere üfleyenlerin şerrinden,"},{"n":5,"t":"Kıskançlık duyduğunda kıskancın şerrinden.”"}],[{"n":1,"t":"De ki: “İnsanların Rabbine sığınırım."},{"n":2,"t":"İnsanların hükümdarına,"},{"n":3,"t":"İnsanların ilahına."},{"n":"4-6","t":"İnsanların göğüslerine (kalplerine) vesveseler fısıldayan, cinlerden ve insanlardan (olan o) sinsi vesvesecinin şerrinden (Allah’a sığınırım).”"}]];
